window.EXAMS=[{"key": "xc101", "label": "101學測", "year": 101, "kind": "學測", "total": 23, "count": 10}, {"key": "zk101", "label": "101指考", "year": 101, "kind": "指考", "total": 26, "count": 13}, {"key": "xc102", "label": "102學測", "year": 102, "kind": "學測", "total": 23, "count": 10}, {"key": "zk102", "label": "102指考", "year": 102, "kind": "指考", "total": 26, "count": 14}, {"key": "xc103", "label": "103學測", "year": 103, "kind": "學測", "total": 23, "count": 12}, {"key": "zk103", "label": "103指考", "year": 103, "kind": "指考", "total": 26, "count": 13}, {"key": "xc104", "label": "104學測", "year": 104, "kind": "學測", "total": 23, "count": 12}, {"key": "zk104", "label": "104指考", "year": 104, "kind": "指考", "total": 26, "count": 12}, {"key": "xc105", "label": "105學測", "year": 105, "kind": "學測", "total": 23, "count": 11}, {"key": "zk105", "label": "105指考", "year": 105, "kind": "指考", "total": 26, "count": 14}, {"key": "xc106", "label": "106學測", "year": 106, "kind": "學測", "total": 23, "count": 10}, {"key": "zk106", "label": "106指考", "year": 106, "kind": "指考", "total": 26, "count": 14}, {"key": "xc107", "label": "107學測", "year": 107, "kind": "學測", "total": 42, "count": 14}, {"key": "zk107", "label": "107指考", "year": 107, "kind": "指考", "total": 42, "count": 16}, {"key": "xc108", "label": "108學測", "year": 108, "kind": "學測", "total": 42, "count": 14}, {"key": "zk108", "label": "108指考", "year": 108, "kind": "指考", "total": 42, "count": 17}, {"key": "xc109", "label": "109學測", "year": 109, "kind": "學測", "total": 42, "count": 19}, {"key": "zk109", "label": "109指考", "year": 109, "kind": "指考", "total": 42, "count": 17}, {"key": "xc110", "label": "110學測", "year": 110, "kind": "學測", "total": 42, "count": 18}, {"key": "zk110", "label": "110指考", "year": 110, "kind": "指考", "total": 42, "count": 17}, {"key": "xc111", "label": "111學測", "year": 111, "kind": "學測", "total": 37, "count": 13}, {"key": "xc112", "label": "112學測", "year": 112, "kind": "學測", "total": 37, "count": 13}, {"key": "xc113", "label": "113學測", "year": 113, "kind": "學測", "total": 36, "count": 11}, {"key": "xc114", "label": "114學測", "year": 114, "kind": "學測", "total": 36, "count": 10}, {"key": "xc115", "label": "115學測", "year": 115, "kind": "學測", "total": 36, "count": 13}];
window.ITEMS=[{"id": "xc101-8", "exam": "xc101", "nums": [8], "form": "單題", "img": "img/xc101-8.png", "source": "朱熹〈大學章句序〉", "author": "朱熹", "genre": "說理議論", "types": ["文意推論", "虛詞句式"], "passage": "《大學》之書，古之大學所以教人之法也。蓋自天降生民，則既莫不與之以仁義禮智之性矣，然其氣質之稟或不能齊，是以不能皆有以知其性之所有而全之也。一有聰明睿智能盡其性者出於其間，則天必命之以為億兆之君師，使之治而教之，以復其性。", "translation": "《大學》這本書，是古代太學用來教導人的方法。自從上天生下百姓，就沒有不賦予他們仁義禮智的本性的；但每個人天生的氣質不一定相同，所以不能人人都知道自己本性中擁有什麼並且保全它。一旦有聰明睿智、能充分發揮本性的人出現在百姓之中，上天就一定命令他做萬民的君主和老師，讓他治理並教化百姓，使大家恢復本性。", "keywords": [{"w": "蓋", "m": "句首發語詞，帶出說明"}, {"w": "稟", "m": "天生所承受的（氣質）"}, {"w": "齊", "m": "一致、相同"}, {"w": "億兆", "m": "指萬民、百姓"}, {"w": "復", "m": "恢復"}], "questions": [{"n": 8, "qtype": "單選", "stem": "下列是一段古文，請依文意選出排列順序最恰當的選項：《大學》之書，古之大學所以教人之法也。蓋自天降生民，甲、然其氣質之稟或不能齊　乙、則天必命之以為億兆之君師　丙、則既莫不與之以仁義禮智之性矣　丁、一有聰明睿智能盡其性者出於其間　戊、是以不能皆有以知其性之所有而全之也　使之治而教之，以復其性。（朱熹〈大學章句序〉）", "options": {"A": "甲戊丙乙丁", "B": "乙丁丙甲戊", "C": "丙甲戊丁乙", "D": "丁乙甲戊丙"}, "answer": "C", "explain": "先抓邏輯：天生百姓→都給了善性→但氣質不同→所以不能都保全本性→於是有聖人出現→天命他當君師→教化百姓恢復本性。「蓋自天降生民，則既……」用「則既」接最順，所以第一句是丙（給了仁義禮智之性）。接著用「然」轉折，是甲（氣質不能齊）；「是以」表結果，是戊（不能都保全本性）。再來「一有……出於其間」（丁）與「則天必命之……」（乙）是「一……則……」的條件句，丁在前乙在後；乙的「之」指聰明睿智者，正好接到末句「使之治而教之」。順序丙甲戊丁乙，選(C)。(A)(B)(D)開頭不是丙，都接不上「蓋自天降生民」。", "skill": "排序題先找連接詞配對（則既…然…是以；一有…則…），再用代詞「之」確認前後指涉。"}], "difficulty": "中", "label": "101學測", "year": 101, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc101-9", "exam": "xc101", "nums": [9], "form": "單題", "img": "img/xc101-9.png", "source": "秦觀〈望海潮〉、李璟〈攤破浣溪沙〉、溫庭筠〈菩薩蠻〉、黃庭堅〈鷓鴣天〉", "author": "秦觀、李璟、溫庭筠、黃庭堅", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文意推論"], "passage": "甲、梅英疏淡，冰澌溶洩，東風暗換年華\n乙、菡萏香銷翠葉殘，西風愁起綠波間。還與容光共憔悴，不堪看\n丙、玉樓明月長相憶，柳絲裊娜春無力。門外草萋萋，送君聞馬嘶\n丁、黃菊枝頭生曉寒，人生莫放酒杯乾。風前橫笛斜吹雨，醉裡簪花倒著冠", "translation": "甲：梅花稀疏淡去，冰塊融化流動，東風悄悄換了一年的光景（初春）。乙：荷花香氣消散、翠綠荷葉殘敗，西風在綠波間掀起愁緒；人也和荷花一樣憔悴，不忍再看（初秋）。丙：在玉樓明月下長長思念，柳絲柔弱搖曳，春意慵懶；門外春草茂盛，送你離開時聽見馬兒嘶鳴（春天）。丁：黃菊枝頭透出清晨的寒意，人生別讓酒杯空了；在風中橫吹笛子，斜雨飄飛，醉中插花、倒戴帽子（深秋）。", "keywords": [{"w": "冰澌", "m": "流動的冰塊"}, {"w": "菡萏", "m": "荷花"}, {"w": "裊娜", "m": "柔美搖曳的樣子"}, {"w": "萋萋", "m": "草茂盛的樣子"}], "questions": [{"n": 9, "qtype": "單選", "stem": "下列文句所描寫的景色，依一年時序的先後，排列正確的選項是：甲、梅英疏淡，冰澌溶洩，東風暗換年華　乙、菡萏香銷翠葉殘，西風愁起綠波間。還與容光共憔悴，不堪看　丙、玉樓明月長相憶，柳絲裊娜春無力。門外草萋萋，送君聞馬嘶　丁、黃菊枝頭生曉寒，人生莫放酒杯乾。風前橫笛斜吹雨，醉裡簪花倒著冠", "options": {"A": "甲乙丙丁", "B": "甲丙乙丁", "C": "丙甲乙丁", "D": "丙丁乙甲"}, "answer": "B", "explain": "抓每句的季節線索：甲「梅英疏淡、冰澌溶洩、東風」＝冬去春來的早春；丙「柳絲裊娜春無力、草萋萋」＝春意正濃；乙「菡萏香銷翠葉殘、西風」＝荷花凋謝，入秋；丁「黃菊、曉寒」＝深秋。所以是甲丙乙丁，選(B)。(A)把秋天的乙放在春天的丙前面；(C)(D)把丙放在早春的甲之前，也錯。", "skill": "判斷季節就圈物候詞：梅、冰融、東風＝早春；柳、春草＝春；荷殘、西風＝初秋；菊、寒＝深秋。"}], "difficulty": "易", "label": "101學測", "year": 101, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc101-10", "exam": "xc101", "nums": [10], "form": "單題", "img": "img/xc101-10.png", "source": "金庸《射鵰英雄傳》（選項引范仲淹〈岳陽樓記〉、《詩經》、崔國輔〈小長干曲〉等）", "author": "金庸", "genre": "古典詩詞曲", "types": ["文意推論", "典故出處", "比較閱讀"], "passage": "甲、心曠神怡，寵辱偕忘\n乙、先天下之憂而憂，後天下之樂而樂\n丙、悠悠我心，豈無他人？唯君之故，沉吟至今\n丁、日暮長江裏，相邀歸渡頭。落花如有意，來去逐船流", "translation": "甲：心胸開闊、精神愉快，榮耀和屈辱都忘了。乙：在天下人憂慮之前先憂慮，在天下人快樂之後才快樂。丙：我心中長久思念，難道沒有別人嗎？只因為你的緣故，我低吟思念到現在。丁：黃昏的長江上，相約一同回到渡口；落花好像有情意，隨著船來來去去。", "keywords": [{"w": "寵辱偕忘", "m": "榮寵與屈辱一併忘卻"}, {"w": "沉吟", "m": "低聲吟詠、深深思念"}, {"w": "逐", "m": "追隨"}], "questions": [{"n": 10, "qtype": "單選", "stem": "閱讀以下金庸《射鵰英雄傳》文字，根據文意、情境，依序選出最適合填入____的選項：黃蓉道：「做這篇文章的范文正公，當年威震西夏，文才武略，可說得上並世無雙。」郭靖央她將范仲淹的事跡說了一些，聽她說到他幼年家貧、父親早死、母親改嫁種種苦況，富貴後儉樸異常，處處為百姓著想，不禁油然起敬，在飯碗中滿滿斟了一碗酒，仰脖子一飲而盡，說道：「____，大英雄大豪傑固當如此胸懷！」（第26回）／黃蓉道：「當面撒謊！你有這許多女人陪你，還寂寞甚麼？」歐陽克張開摺扇，搧了兩搧，雙眼凝視著她，微笑吟道：「____。」黃蓉向他做個鬼臉，笑道：「我不用你討好，更加不用你思念。」（第12回）　甲、心曠神怡，寵辱偕忘　乙、先天下之憂而憂，後天下之樂而樂　丙、悠悠我心，豈無他人？唯君之故，沉吟至今　丁、日暮長江裏，相邀歸渡頭。落花如有意，來去逐船流", "options": {"A": "甲丙", "B": "甲丁", "C": "乙丙", "D": "乙丁"}, "answer": "C", "explain": "第一空：郭靖聽到范仲淹「處處為百姓著想」而起敬，說「大英雄大豪傑固當如此胸懷」，要填表現憂國愛民胸懷的句子，就是〈岳陽樓記〉的乙「先天下之憂而憂」。甲「心曠神怡，寵辱偕忘」雖也出自〈岳陽樓記〉，但寫的是登樓個人的快樂，談不上英雄胸懷。第二空：黃蓉後面說「更加不用你思念」，可見歐陽克吟的是表達思念對方的句子，丙「唯君之故，沉吟至今」（只因為你，我思念到現在）正合；丁只寫落花隨船的江上景致，雖有情意暗示，卻沒有「思念」。答案乙丙，選(C)。", "skill": "填空題要找空格前後的呼應語：前有「為百姓著想」、後有「如此胸懷」，後文有「不用你思念」，照線索對號入座。"}], "difficulty": "易", "label": "101學測", "year": 101, "kind": "學測", "textcat": "部定古文", "textcat2": "文學文本", "linked_core": "岳陽樓記"}, {"id": "xc101-11", "exam": "xc101", "nums": [11], "form": "單題", "img": "img/xc101-11.png", "source": "蘇軾〈書戴嵩畫牛〉", "author": "蘇軾", "genre": "筆記小品", "types": ["主旨寓意", "比較閱讀"], "passage": "蜀中有杜處士，好書畫，所寶以百數。有戴嵩〈牛〉一軸，尤所愛，錦囊玉軸，常以自隨。一日曝書畫，有一牧童見之，拊掌大笑，曰：「此畫鬬牛也。牛鬬，力在角，尾搐入兩股間。今乃掉尾而鬬，謬矣。」處士笑而然之。古語有云：「耕當問奴，織當問婢。」不可改也。", "translation": "四川有位姓杜的隱士，喜歡書畫，珍藏的作品有上百件。其中有一幅戴嵩畫的〈牛〉，他特別喜愛，用錦緞做袋子、玉做卷軸，常常隨身帶著。有一天他曬書畫，一個牧童看見了，拍手大笑說：「這畫的是鬥牛啊。牛在相鬥時，力氣用在角上，尾巴緊夾在兩條後腿中間。現在畫上的牛卻搖著尾巴鬥，錯了。」杜處士笑著認為他說得對。古話說：「耕田的事該問農奴，織布的事該問婢女。」這道理是不能改變的。", "keywords": [{"w": "處士", "m": "有才德而不做官的隱士"}, {"w": "拊掌", "m": "拍手"}, {"w": "搐", "m": "收縮、夾緊"}, {"w": "掉尾", "m": "搖尾巴"}, {"w": "然之", "m": "認為他說得對"}], "questions": [{"n": 11, "qtype": "單選", "stem": "蜀中有杜處士，好書畫，所寶以百數。有戴嵩〈牛〉一軸，尤所愛，錦囊玉軸，常以自隨。一日曝書畫，有一牧童見之，拊掌大笑，曰：「此畫鬬牛也。牛鬬，力在角，尾搐入兩股間。今乃掉尾而鬬，謬矣。」處士笑而然之。古語有云：「耕當問奴，織當問婢。」不可改也。（蘇軾〈書戴嵩畫牛〉）下列文句與上文主旨最不相關的選項是：", "options": {"A": "聞道有先後，術業有專攻", "B": "學無常師，有一業勝己者，便從學焉", "C": "使言之而是，雖在褐夫芻蕘，猶不可棄也", "D": "三人行，必有我師焉。擇其善者而從之，其不善者而改之"}, "answer": "D", "explain": "本文重點有兩層：一是「耕當問奴，織當問婢」，各行各業有專門的人最懂（實際經驗勝過名家）；二是牧童身分低微，說得對，處士也笑而接受。(A)「術業有專攻」正是專業分工，相關。(B)只要在某一方面比自己強，就向他學習，相關。(C)話若說得對，即使出自粗布衣的平民、割草砍柴的人也不可拋棄，對應牧童，相關。(D)強調從身邊的人身上學好的、看到不好的就反省改正，重點在品德上的自我修正，和「專業問專家」的主旨距離最遠，所以選(D)。", "skill": "「最不相關」題先把原文主旨濃縮成一兩個關鍵詞（專業、不以身分取人），再逐項比對，找重心偏掉的那一個。"}], "difficulty": "中", "label": "101學測", "year": 101, "kind": "學測", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "赤壁賦"}, {"id": "xc101-14", "exam": "xc101", "nums": [14, 15], "form": "題組", "img": "img/xc101-14.png", "source": "方孝孺〈越車〉", "author": "方孝孺", "genre": "寓言故事", "types": ["字詞解釋", "文意推論", "主旨寓意"], "passage": "越無車，有遊者得車於晉、楚之郊，輻朽而輪敗，輗折而轅毀，無所可用。然以其鄉之未嘗有也，舟載以歸，而誇諸人。觀者聞其誇而信之，以為車固若是，效而為之者相屬。他日，晉、楚之人見而笑其拙，越人以為紿己，不顧。及寇兵侵其境，越率敝車禦之。車壞，大敗，終不知其車也。", "translation": "越國沒有車子。有個在外遊歷的越國人在晉國、楚國的郊外得到一輛車，車輻腐朽、車輪破損，車轅前的關鍵零件斷了，車轅也毀了，根本不能用。但因為他的家鄉從來沒有過車，他就用船載回去，向眾人誇耀。看的人聽了他的誇耀就相信了，以為車本來就是這個樣子，仿造的人一個接一個。後來，晉、楚的人看見了，笑他們造得拙劣，越國人卻以為人家在騙自己，不理會。等到敵兵入侵國境，越國率領這些破車去抵禦。車子壞了，越國大敗，到最後還是不知道真正的車是什麼樣子。", "keywords": [{"w": "輻", "m": "連接車輪中心與輪框的直條"}, {"w": "輗", "m": "車轅前端與橫木相接的關鍵零件"}, {"w": "轅", "m": "車前駕牲口的長木"}, {"w": "固", "m": "本來"}, {"w": "相屬", "m": "接連不斷"}, {"w": "紿", "m": "欺騙"}, {"w": "顧", "m": "理會、在意"}], "questions": [{"n": 14, "qtype": "單選", "stem": "依據上文，下列各句「之」字指「越國遊者所說的話」的選項是：", "options": {"A": "然以其鄉「之」未嘗有也", "B": "觀者聞其誇而信「之」", "C": "效而為「之」者相屬", "D": "越率敝車禦「之」"}, "answer": "B", "explain": "(B)觀者聽了他的誇耀就相信「它」，「之」就是遊者誇口說的話，正確。(A)「其鄉之未嘗有」的「之」放在主語「其鄉」和謂語「未嘗有」之間，沒有實際意思，不是代詞。(C)「效而為之」是仿效著造「它」，指車子。(D)「禦之」是抵擋「他們」，指入侵的寇兵。", "skill": "判斷代詞「之」：把它換成具體名詞讀讀看，讀得通的才是答案；夾在主語謂語中間的「之」通常不翻。"}, {"n": 15, "qtype": "單選", "stem": "依據上文，敘述正確的選項是：", "options": {"A": "越人以為晉、楚之人所言不實，故對其譏笑不予理睬", "B": "越國遊者改造的晉、楚戰車不夠精良，因此被敵寇打敗", "C": "越人故意用殘破的戰車與寇兵作戰，使其輕敵，終獲勝利", "D": "越國遊者將晉、楚大軍的戰車毀壞，成功地阻止晉、楚入侵"}, "answer": "A", "explain": "(A)原文「越人以為紿己，不顧」：越人認為晉楚的人在騙自己，所以不理會，正確。(B)遊者並沒有「改造」車，他是撿了一輛破車回來，越人照著破車仿造；敗仗是因為車本來就是壞的。(C)越人不是「故意」用破車，而是根本不知道車該長什麼樣，而且結果是「大敗」，不是勝利。(D)文中沒有遊者毀壞晉楚戰車、阻止入侵的情節，入侵的是「寇兵」。", "skill": "敘述題逐項找原文對應句，特別留意「故意」「改造」「勝利」這類原文沒有的添加詞。"}], "difficulty": "易", "label": "101學測", "year": 101, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc101-20", "exam": "xc101", "nums": [20], "form": "單題", "img": "img/xc101-20.png", "source": "諸葛亮〈出師表〉、王維〈輞川閒居贈裴秀才迪〉、歸有光〈項脊軒志〉、《論語》、李白〈春夜宴從弟桃花園序〉、《戰國策‧馮諼客孟嘗君》、顧炎武〈廉恥〉、方苞〈左忠毅公軼事〉、韓愈〈師說〉等", "author": "多位作者", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)後值傾覆，受任於敗軍之際／復值接輿醉，狂歌五柳前\n(B)軒凡四遭火，得不焚，殆有神護者／學而不思則罔，思而不學則殆\n(C)況陽春召我以煙景，大塊假我以文章／願假東壁輝，餘光照貧女\n(D)梁使三反，孟嘗君固辭不往也／彼眾昏之日，固未嘗無獨醒之人也\n(E)庸奴！此何地也？而汝來前／吾師道也，夫庸知其年之先後生於吾乎", "translation": "", "keywords": [{"w": "值", "m": "遇到"}, {"w": "殆", "m": "大概；危險、疑惑不安"}, {"w": "假", "m": "借、給予"}, {"w": "固", "m": "堅決；本來"}, {"w": "庸", "m": "平庸；豈、哪裡"}], "questions": [{"n": 20, "qtype": "多選", "stem": "下列各組文句，「」內字義相同的選項是：", "options": {"A": "後「值」傾覆，受任於敗軍之際／復「值」接輿醉，狂歌五柳前", "B": "軒凡四遭火，得不焚，「殆」有神護者／學而不思則罔，思而不學則「殆」", "C": "況陽春召我以煙景，大塊「假」我以文章／願「假」東壁輝，餘光照貧女", "D": "梁使三反，孟嘗君「固」辭不往也／彼眾昏之日，「固」未嘗無獨醒之人也", "E": "「庸」奴！此何地也？而汝來前／吾師道也，夫「庸」知其年之先後生於吾乎"}, "answer": "AC", "explain": "(A)正確。兩個「值」都是「遇到」：後來遇到兵敗傾覆；又遇到像接輿那樣醉酒的狂人。(B)錯誤。前者「殆」是「大概」（大概有神明保護）；後者是「危險、疑惑而無所得」。(C)正確。兩個「假」都是「借、給予」：大自然借給我美麗的文采景致；希望借一點東邊牆壁的燈光。(D)錯誤。前者「固」是「堅決」（堅決推辭）；後者是「本來」（本來就不是沒有清醒的人）。(E)錯誤。前者「庸」是「平庸、無能」（庸奴＝沒用的奴才，罵人語）；後者是反問的「豈、哪裡」（哪裡需要知道他比我早生或晚生）。", "skill": "字義比較題，把兩個意思各自代回原句翻一遍，翻得通且意思一樣才選；「庸」「殆」「固」都是一字多義的常考字。"}], "difficulty": "中", "label": "101學測", "year": 101, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "馮諼客孟嘗君、出師表、師說、項脊軒志、廉恥、左忠毅公軼事"}, {"id": "xc101-21", "exam": "xc101", "nums": [21], "form": "單題", "img": "img/xc101-21.png", "source": "李白〈菩薩蠻〉、馬致遠〈天淨沙‧秋思〉、歐陽脩〈踏莎行〉、古詩十九首〈青青河畔草〉等", "author": "多位作者", "genre": "古典詩詞曲", "types": ["寫作手法", "詩詞賞析"], "passage": "(A)平林漠漠煙如織，寒山一帶傷心碧。暝色入高樓，有人樓上愁\n(B)枯藤老樹昏鴉，小橋流水人家，古道西風瘦馬，夕陽西下，斷腸人在天涯\n(C)寸寸柔腸，盈盈粉淚，樓高莫近危闌倚。平蕪盡處是春山，行人更在春山外\n(D)畫閣魂銷，高樓目斷，斜陽只送平波遠。無窮無盡是離愁，天涯地角尋思遍\n(E)青青河畔草，鬱鬱園中柳。盈盈樓上女，皎皎當窗牖，娥娥紅粉妝，纖纖出素手", "translation": "", "keywords": [{"w": "漠漠", "m": "迷濛、廣布的樣子"}, {"w": "暝色", "m": "暮色"}, {"w": "平蕪", "m": "平坦的草地"}, {"w": "窗牖", "m": "窗戶"}], "questions": [{"n": 21, "qtype": "多選", "stem": "文學作品中，常採用「由大而小」及「由遠而近」的手法，逐漸聚焦到所要描寫的重點對象。下列同時使用此兩種手法的選項是：", "options": {"A": "平林漠漠煙如織，寒山一帶傷心碧。暝色入高樓，有人樓上愁", "B": "枯藤老樹昏鴉，小橋流水人家，古道西風瘦馬，夕陽西下，斷腸人在天涯", "C": "寸寸柔腸，盈盈粉淚，樓高莫近危闌倚。平蕪盡處是春山，行人更在春山外", "D": "畫閣魂銷，高樓目斷，斜陽只送平波遠。無窮無盡是離愁，天涯地角尋思遍", "E": "青青河畔草，鬱鬱園中柳。盈盈樓上女，皎皎當窗牖，娥娥紅粉妝，纖纖出素手"}, "answer": "AE", "explain": "(A)正確。從遠處一大片樹林、寒山，到暮色進入高樓，再到樓上發愁的人，鏡頭由遠到近、由大到小，最後聚焦在「人」。(B)錯誤。前三句是一組組並列的景物，並沒有一路往近處、小處推進，最後「斷腸人在天涯」反而把人推到遙遠的天涯。(C)錯誤。先寫近處的人（柔腸、粉淚、倚欄），再望向平蕪、春山、春山外的行人，是由近而遠。(D)錯誤。從畫閣高樓向遠處斜陽平波望去，再寫離愁遍及天涯地角，也是由近向遠擴散。(E)正確。從河畔草、園中柳，到樓上女子、窗前，再到她的妝容、纖細的手，由遠而近、由大而小，最後聚焦在「素手」。", "skill": "把每句的描寫對象依序列出來，看鏡頭是「拉近、縮小」還是「推遠、放大」，兩個條件都要符合。"}], "difficulty": "中", "label": "101學測", "year": 101, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc101-22", "exam": "xc101", "nums": [22], "form": "單題", "img": "img/xc101-22.png", "source": "杜甫〈月夜憶舍弟〉、李白〈太原早秋〉、皇甫冉〈春思〉、張若虛〈春江花月夜〉、沈佺期〈獨不見〉", "author": "多位作者", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "(A)戍鼓斷人行，邊秋一雁聲。露從今夜白，月是故鄉明\n(B)霜威出塞早，雲色渡河秋。夢繞邊城月，心飛故國樓\n(C)鶯啼燕語報新年，馬邑龍堆路幾千。家住秦城鄰漢苑，心隨明月到胡天\n(D)可憐樓上月徘徊，應照離人妝鏡臺。玉戶簾中捲不去，搗衣砧上拂還來\n(E)白狼河北音書斷，丹鳳城南秋夜長。誰為含愁獨不見，更教明月照流黃", "translation": "", "keywords": [{"w": "戍鼓", "m": "邊防駐軍的更鼓"}, {"w": "馬邑龍堆", "m": "泛指北方邊塞"}, {"w": "妝鏡臺", "m": "女子梳妝的鏡臺"}, {"w": "搗衣砧", "m": "捶洗衣物用的石板，常與思婦連用"}, {"w": "流黃", "m": "黃紫色的絹，此指帷帳"}], "questions": [{"n": 22, "qtype": "多選", "stem": "古典詩中的「月亮」在不同情境之下，有不同的意涵。下列詩句藉「月」來抒發「思婦懷人」之情的選項是：", "options": {"A": "戍鼓斷人行，邊秋一雁聲。露從今夜白，月是故鄉明", "B": "霜威出塞早，雲色渡河秋。夢繞邊城月，心飛故國樓", "C": "鶯啼燕語報新年，馬邑龍堆路幾千。家住秦城鄰漢苑，心隨明月到胡天", "D": "可憐樓上月徘徊，應照離人妝鏡臺。玉戶簾中捲不去，搗衣砧上拂還來", "E": "白狼河北音書斷，丹鳳城南秋夜長。誰為含愁獨不見，更教明月照流黃"}, "answer": "CDE", "explain": "關鍵是說話的人是不是「在家思念遠方丈夫的女子」。(A)杜甫在戰亂邊地，覺得故鄉的月最明，是遊子思鄉、懷念兄弟，不是思婦。(B)人在邊城，心卻飛回故國的樓，是出外者的思鄉。(C)「家住秦城」的女子，心隨明月飛到丈夫戍守的胡地，是思婦懷念征人，正確。(D)月光照在「離人妝鏡臺」、照在「搗衣砧」上，捲不走、拂不去，寫閨中女子的相思，正確。(E)丈夫在白狼河北斷了音信，女子在長安城南秋夜難眠，明月照著帷帳更添愁，正確。", "skill": "先判斷「誰在思念」：出現妝鏡、搗衣、閨中、家住某地而心向邊塞，多半是思婦；人在邊塞望故鄉，多半是遊子。"}], "difficulty": "中", "label": "101學測", "year": 101, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc101-23", "exam": "xc101", "nums": [23], "form": "單題", "img": "img/xc101-23.png", "source": "蘇轍〈東軒記〉", "author": "蘇轍", "genre": "說理議論", "types": ["文意推論", "人物情感"], "passage": "余昔少年讀書，竊嘗怪顏子以簞食瓢飲，居於陋巷，人不堪其憂，顏子不改其樂。私以為雖不欲仕，然抱關擊柝尚可自養，而不害於學，何至困辱貧窶自苦如此？及來筠州，勤勞鹽米之間，無一日之休，雖欲棄塵垢，解羈縶，自放於道德之場，而事每劫而留之。然後知顏子之所以甘心貧賤，不肯求斗升之祿以自給者，良以其害於學故也。", "translation": "我從前年少讀書時，私下曾經對顏回感到奇怪：他吃一竹籃飯、喝一瓢水，住在簡陋的巷子裡，別人受不了那種憂苦，顏回卻不改他的快樂。我私自認為，就算不想做官，當個守城門、打更的小吏也能養活自己，而且不妨礙求學，何必讓自己窮困受辱到這種地步？等到來了筠州，整天忙著管鹽米的事務，沒有一天休息，雖然想拋開塵俗、解除束縛，讓自己在道德的境界裡自在悠遊，但事務總是把我拉住、留住。這才明白顏回之所以甘心過貧賤的日子，不肯謀求一點微薄的俸祿來養活自己，實在是因為那會妨害求學啊。", "keywords": [{"w": "竊", "m": "私下（謙詞）"}, {"w": "怪", "m": "感到奇怪"}, {"w": "抱關擊柝", "m": "守城門、打更，指低微的小官職"}, {"w": "貧窶", "m": "貧窮"}, {"w": "羈縶", "m": "束縛"}, {"w": "劫", "m": "強迫、脅迫"}, {"w": "良", "m": "確實、實在"}], "questions": [{"n": 23, "qtype": "多選", "stem": "閱讀下文，選出敘述正確的選項：", "options": {"A": "作者來到筠州之後，生活和顏回一樣貧窮艱困", "B": "俗世塵垢使作者深受羈絆，因而渴望擺脫俗務干擾", "C": "作者年少時認為：從事抱關擊柝的工作並不妨礙學習", "D": "由於親身經驗，作者終於明瞭顏回之所以不仕，是想全心致力為學", "E": "作者從小對顏回「簞食瓢飲，居於陋巷」而「不改其樂」的生活，就頗為欣賞"}, "answer": "BCD", "explain": "全文是「年少時不懂顏回→到筠州忙於公務→終於懂了」。(A)錯誤。作者在筠州的困擾是「勤勞鹽米之間，無一日之休」，是忙，不是窮；他有官職俸祿，並不像顏回一樣貧困。(B)正確。「雖欲棄塵垢，解羈縶……而事每劫而留之」，他想擺脫俗務卻被纏住。(C)正確。「私以為……抱關擊柝尚可自養，而不害於學」。(D)正確。「然後知顏子之所以甘心貧賤，不肯求斗升之祿……良以其害於學故也」，是親身經歷後才明白。(E)錯誤。「竊嘗怪」是曾經感到奇怪、不理解，不是欣賞。", "skill": "注意文章的「前後轉變」結構（昔…及…然後知…），作者早年與後來的想法不同，選項常故意把兩者混在一起。"}], "difficulty": "中", "label": "101學測", "year": 101, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc101-ns2", "exam": "xc101", "nums": ["二"], "form": "單題", "img": "img/xc101-ns2.png", "source": "陶淵明〈桃花源記〉", "author": "陶淵明", "genre": "寓言故事", "types": ["文意推論", "寫作手法", "主旨寓意"], "passage": "晉太元中，武陵人，捕魚為業。緣溪行，忘路之遠近。忽逢桃花林，夾岸數百步，中無雜樹，芳草鮮美，落英繽紛。漁人甚異之。復前行，欲窮其林。林盡水源，便得一山，山有小口，彷彿若有光。便捨船，從口入。初極狹，才通人。復行數十步，豁然開朗。土地平曠，屋舍儼然，有良田、美池、桑竹之屬，阡陌交通，雞犬相聞。其中往來種作，男女衣著，悉如外人；黃髮垂髫，並怡然自樂。", "translation": "東晉太元年間，有個武陵人以捕魚為生。他沿著溪流划船，忘了走了多遠。忽然遇到一片桃花林，夾著溪岸綿延幾百步，中間沒有別的樹，芳草鮮嫩美麗，落花紛紛飄落。漁人覺得非常奇怪，又往前划，想走到林子的盡頭。桃林在溪水源頭結束，接著看到一座山，山上有個小洞口，隱隱約約好像有光。他就下船，從洞口進去。起初洞很窄，只能容一個人通過；又走了幾十步，突然變得開闊明亮。只見土地平坦寬廣，房屋整整齊齊，有肥沃的田地、美麗的池塘，還有桑樹竹子之類；田間小路縱橫相通，雞鳴狗叫的聲音彼此都聽得到。人們在其中來來往往耕種勞作，男男女女的穿著，都像桃花源外的人；老人和小孩都安適快樂。", "keywords": [{"w": "緣", "m": "沿著"}, {"w": "落英", "m": "落花"}, {"w": "異", "m": "感到奇怪"}, {"w": "窮", "m": "走到盡頭"}, {"w": "儼然", "m": "整齊的樣子"}, {"w": "阡陌", "m": "田間小路"}, {"w": "交通", "m": "交錯相通"}, {"w": "黃髮垂髫", "m": "老人與小孩"}], "questions": [{"n": "二", "qtype": "非選", "stem": "文章分析（占18分）：閱讀框內文章之後，請分析：（一）「漁人甚異之」的「異」和漁人發現桃花源有何關聯？（二）陶潛從哪些方面來描寫桃花源？（三）從中可看出陶潛嚮往什麼樣的理想世界？答案必須標明（一）（二）（三），分列書寫。（一）（二）（三）合計文長約250—300字（約11—14行）。", "options": {}, "answer": "", "ref_answer": "（一）「異」是漁人對眼前桃花林美景（中無雜樹、芳草鮮美、落英繽紛）感到驚奇，這份好奇心促使他「復前行，欲窮其林」，才一路找到山口、進入桃花源。（二）透過漁人的眼睛描寫兩方面：自然環境——土地平曠，有良田、美池、桑竹之屬；人們的生活情狀——屋舍儼然，阡陌交通，雞犬相聞，往來種作，男女衣著悉如外人，黃髮垂髫並怡然自樂。（三）陶潛嚮往的是人人自食其力、衣食無缺，社會安定、和樂恬靜、與世無爭的世界，近於老子「安其居、樂其業」的小國寡民。", "ref_official": true, "explain": "第（一）題很多人只翻譯桃花林有多美，卻忘了說「異」怎麼推動情節：因為覺得奇怪→想走到盡頭→才發現山口與桃花源，要把這條因果鏈寫出來。第（二）題問「從哪些方面」，要先分類（自然環境／人們生活）再舉原文，而不是逐句翻譯。第（三）題由前面的描寫歸納：有田有池有桑竹＝豐足；阡陌交通、雞犬相聞＝安定和諧；黃髮垂髫怡然自樂＝人人安樂。", "skill": "非選分析題先把問題拆成「關鍵字→因果」「分類→舉證」「歸納→結論」三種動作，各題對應一種，分項作答。"}], "difficulty": "易", "label": "101學測", "year": 101, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "桃花源記"}, {"id": "zk101-4", "exam": "zk101", "nums": [4], "form": "單題", "img": "img/zk101-4.png", "source": "《荀子‧解蔽》", "author": "荀子", "genre": "說理議論", "types": ["文意推論", "寫作手法"], "passage": "危微之幾，惟明君子而後能知之。故人心譬如槃水，正錯而勿動，則湛濁在下，而清明在上，則足以見鬚眉而察理矣。微風過之，湛濁動乎下，清明亂於上，則不可以得大形之正也。", "translation": "危險與精微的細小徵兆，只有明智的君子才能察覺。所以人心就像一盤水，把它放正、擱著不去動它，混濁的渣滓就沉在下面，清澈的水在上面，這時就能照見鬍鬚眉毛、看清紋理。但只要有一陣微風吹過，渣滓在下面翻動，上面的清水也被攪亂，就連物體大致的形狀都照不正了。", "keywords": [{"w": "槃", "m": "同「盤」，盤子"}, {"w": "錯", "m": "同「措」，放置"}, {"w": "湛濁", "m": "沉澱的渣滓"}, {"w": "理", "m": "細微的紋理"}, {"w": "大形", "m": "大致的形體"}], "questions": [{"n": 4, "qtype": "單選", "stem": "下列文句，依文意選出排列順序最適當的選項：「危微之幾，惟明君子而後能知之。故人心譬如槃水，甲、微風過之　乙、正錯而勿動　丙、則足以見鬚眉而察理矣　丁、湛濁動乎下，清明亂於上　戊、則湛濁在下，而清明在上　則不可以得大形之正也。」", "options": {"A": "甲丁乙戊丙", "B": "甲戊丙乙丁", "C": "乙戊甲丁丙", "D": "乙戊丙甲丁"}, "answer": "D", "explain": "這段話是「正面情況→反面情況」的對比。先說水放正不動（乙），渣滓沉下、清水在上（戊），所以能照見鬚眉（丙）；再說一有微風吹過（甲），渣滓翻動、清水被攪亂（丁），最後接題目給的結尾「則不可以得大形之正也」。所以是乙戊丙甲丁。(A)(B)以「微風過之」開頭，接不上「人心譬如槃水」，也無法和結尾的「不可以得大形之正」搭配。(C)把「甲丁」放中間、「丙」放最後，會變成「微風吹過、清明亂了，就能看清鬚眉」，再接「不可以得大形之正」，前後矛盾。", "skill": "排序題先找成對的正反句：「足以見…」和「不可以得…」一正一反，各自前面要接相應的條件，結構就出來了。"}], "difficulty": "易", "label": "101指考", "year": 101, "kind": "指考", "textcat": "延伸", "textcat2": "學術文本", "linked_core": "勸學"}, {"id": "zk101-5", "exam": "zk101", "nums": [5], "form": "單題", "img": "img/zk101-5.png", "source": "楹聯（出處待查）", "author": "", "genre": "其他", "types": ["字詞解釋", "文化常識"], "passage": "讀書取正，讀易取變，讀騷取幽，讀莊取達，讀漢文取堅，最有味卷中歲月；與菊同野，與梅同疏，與蓮同潔，與蘭同芳，與海棠同韻，定自稱花裏神仙。", "translation": "讀《尚書》學它的端正，讀《易經》學它的變化，讀〈離騷〉學它的幽深，讀《莊子》學它的曠達，讀漢代文章學它的堅實，最有滋味的是在書卷中度過的歲月；和菊花一樣淡泊野逸，和梅花一樣清疏，和蓮花一樣高潔，和蘭花一樣芬芳，和海棠一樣有韻致，一定能自稱是花中的神仙。", "keywords": [{"w": "達", "m": "曠達、通達"}, {"w": "疏", "m": "稀疏清朗"}, {"w": "潔", "m": "高潔"}], "questions": [{"n": 5, "qtype": "單選", "stem": "閱讀下列楹聯，依序選出最適合填入□內的選項：讀書取正，讀易取變，讀騷取幽，讀莊取□，讀漢文取堅，最有味□□歲月；與菊同野，與梅同□，與蓮同□，與蘭同芳，與海棠同韻，定自稱花裏神仙。", "options": {"A": "達／卷中／疏／潔", "B": "道／卷中／疏／逸", "C": "達／篇外／寒／潔", "D": "道／篇外／寒／逸"}, "answer": "A", "explain": "上聯講讀各種書得到的收穫：《莊子》最大的特色是曠達逍遙，所以填「達」；「道」是名詞，和「正、變、幽、堅」這些形容特質的字不搭。讀書的歲月當然在「卷中」，不是「篇外」。下聯講花的品格：梅花枝幹稀疏、清瘦，常說「疏影橫斜」，填「疏」；蓮花「出淤泥而不染」，填「潔」。「寒」雖然也能形容梅，但要和蓮搭配「潔」才合，選項只有(A)全對。", "skill": "對聯填空先看同一串排比字的詞性要一致，再用你熟悉的經典印象（莊子—曠達、梅—疏影、蓮—高潔）去對。"}], "difficulty": "中", "label": "101指考", "year": 101, "kind": "指考", "textcat": "生活情境文本", "textcat2": "", "linked_core": ""}, {"id": "zk101-7", "exam": "zk101", "nums": [7], "form": "單題", "img": "img/zk101-7.png", "source": "〈桃花源記〉〈始得西山宴遊記〉〈岳陽樓記〉〈醉翁亭記〉", "author": "陶淵明、柳宗元、范仲淹、歐陽脩", "genre": "其他", "types": ["文化常識", "寫作手法"], "passage": "", "translation": "", "keywords": [], "questions": [{"n": 7, "qtype": "單選", "stem": "下列有關「記」的敘述，正確的選項是：", "options": {"A": "陶淵明〈桃花源記〉採倒敘手法，從漁人的角度追憶自我無意中發現美好世界的過程", "B": "柳宗元〈始得西山宴遊記〉以「始得」二字凸顯主旨，首段開門見山，細數宴遊見聞", "C": "范仲淹〈岳陽樓記〉旨在刻畫滕子京浮沉宦海、修葺岳陽樓之原委始末，雖名為樓記，實為史傳", "D": "歐陽脩〈醉翁亭記〉首段採用「由景而人」的手法，勾連山、水、亭、人物，終而拈出「樂」字"}, "answer": "D", "explain": "(D)正確：〈醉翁亭記〉首段從「環滁皆山也」寫到琅琊山、釀泉、醉翁亭，再帶出造亭的僧智僊和命名的太守，最後點出「山水之樂，得之心而寓之酒也」，正是由景而人、拈出「樂」字。(A)錯：〈桃花源記〉是用第三人稱順著時間寫「晉太元中，武陵人捕魚為業」，不是漁人自己倒敘追憶。(B)錯：首段寫的是作者被貶後「恆惴慄」、到處遊山卻「未始知西山之怪特」，是先蓄勢，不是開門見山細數宴遊見聞。(C)錯：〈岳陽樓記〉借題發揮，重點在「先天下之憂而憂，後天下之樂而樂」的胸懷，不是替滕子京寫傳。", "skill": "國學常識題要回想課文第一段實際寫了什麼，用課文原句去驗證敘述，不要被專有名詞嚇到。"}], "difficulty": "中", "label": "101指考", "year": 101, "kind": "指考", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "桃花源記、始得西山宴遊記、岳陽樓記、醉翁亭記"}, {"id": "zk101-9", "exam": "zk101", "nums": [9], "form": "單題", "img": "img/zk101-9.png", "source": "《論語》、〈漁父〉、〈出師表〉、〈蘭亭集序〉", "author": "", "genre": "經典語錄", "types": ["句意理解", "文意推論"], "passage": "子謂顏淵曰：「用之則行，舍之則藏，唯我與爾有是夫！」", "translation": "孔子對顏淵說：「有人任用我們，就出來推行理想；不被任用，就把才能收藏起來安居。只有我和你能做到這樣吧！」", "keywords": [{"w": "用之則行，舍之則藏", "m": "被任用就出仕行道，不被任用就退隱"}, {"w": "卷而懷之", "m": "把才能收起來藏在懷中，指隱退"}, {"w": "布衣", "m": "平民"}, {"w": "聞達", "m": "顯達、有名聲"}], "questions": [{"n": 9, "qtype": "單選", "stem": "《論語》：「子謂顏淵曰：『用之則行，舍之則藏，唯我與爾有是夫！』」反映古代士大夫對於「出仕」或「退隱」的態度，下列文意和這種態度最不相關的選項是：", "options": {"A": "邦有道，則仕；邦無道，則可卷而懷之", "B": "滄浪之水清兮，可以濯吾纓；滄浪之水濁兮，可以濯吾足", "C": "臣本布衣，躬耕於南陽，苟全性命於亂世，不求聞達於諸侯", "D": "夫人之相與，俯仰一世，或取諸懷抱，晤言一室之內；或因寄所託，放浪形骸之外"}, "answer": "D", "explain": "題目在問「出來做官或退隱」的態度。(D)出自王羲之〈蘭亭集序〉，說人與人相處一生，有人喜歡在室內和朋友談心，有人寄情外物、放浪不拘，講的是個性與生活方式的不同，和出仕、退隱無關，所以是答案。(A)《論語》：國家政治清明就出來做官，政治黑暗就收起才能隱退，正是出處之道。(B)〈漁父〉中的滄浪歌：水清洗帽帶（世道清明就出仕），水濁洗腳（世道混濁就避世），也是隨時勢進退。(C)〈出師表〉：諸葛亮說自己本是平民，在亂世只求保全性命，不求在諸侯間出名，是退隱的態度。", "skill": "先把題幹的關鍵概念換成白話（出仕／退隱），再看每個選項是不是在談「做不做官」，談別的就是答案。"}], "difficulty": "易", "label": "101指考", "year": 101, "kind": "指考", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "漁父、出師表、蘭亭集序"}, {"id": "zk101-10", "exam": "zk101", "nums": [10], "form": "單題", "img": "img/zk101-10.png", "source": "《讀畫錄》（臺靜農〈看了董陽孜書法後的感想〉引）", "author": "周亮工（《讀畫錄》）；臺靜農", "genre": "筆記小品", "types": ["文意推論", "主旨寓意"], "passage": "（陳老蓮）搨杭州府學龍眠七十二賢石刻，閉門摹十日，盡得之，出示人曰：「何若？」曰：「似矣！」則喜。又摹十日，出示人曰：「何若？」曰：「勿似也！」則更喜。蓋數摹而變其法，易圓以方，易整以散，勿得辨也。", "translation": "陳老蓮拓下杭州府學裡李龍眠畫的七十二賢石刻，關起門來臨摹了十天，完全學到了，拿給人看，問：「怎麼樣？」人家說：「很像了！」他就很高興。又臨摹十天，拿給人看，問：「怎麼樣？」人家說：「不像了！」他更加高興。原來他多次臨摹後改變了畫法，把圓轉改成方折，把整齊改成疏散，人家已經分辨不出原本的樣子了。", "keywords": [{"w": "搨", "m": "同「拓」，拓印"}, {"w": "摹", "m": "臨摹"}, {"w": "何若", "m": "怎麼樣"}, {"w": "易圓以方", "m": "把圓的筆法改成方的"}], "questions": [{"n": 10, "qtype": "單選", "stem": "閱讀下文，選出最符合文意的選項：", "options": {"A": "陳老蓮臨摹李龍眠筆法，愈近似則愈感覺喜悅", "B": "學習書畫應經由「似」，再進一步追求「勿似」", "C": "陳老蓮的學習歷程可以用「邯鄲學步」來形容", "D": "《讀畫錄》藉「易圓以方」說明李龍眠的畫風"}, "answer": "B", "explain": "文章重點是：學書畫要先從臨摹入手（求「似」），但不能只會拷貝，還要變出自己的風格（求「勿似」），所以(B)正確。(A)錯：「似矣」只是「喜」，「勿似」才「更喜」，越不像反而越高興。(C)錯：邯鄲學步是學別人沒學成、連自己原本的也忘了；陳老蓮是先學會再創新，正好相反。(D)錯：「易圓以方」是陳老蓮改變了李龍眠的畫法，說的是陳老蓮的變化，不是李龍眠的畫風。", "skill": "文白對讀題，白話評論那段通常就是主旨；用它回頭確認文言故事的重點。"}], "difficulty": "易", "label": "101指考", "year": 101, "kind": "指考", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "zk101-11", "exam": "zk101", "nums": [11], "form": "單題", "img": "img/zk101-11.png", "source": "宋濂〈猿說〉", "author": "宋濂", "genre": "寓言故事", "types": ["文意推論", "主旨寓意"], "passage": "武平產猿，猿毛若金絲，閃閃可觀；猿子尤奇，性可馴，然不離母。母黠，不可致。獵人以毒傅矢，伺母間射之。母度不能生，灑乳於林飲子；灑已，氣絕。獵人取母皮向子鞭之，子即悲鳴而下，斂手就制，每夕必寢皮乃安。甚者，輒抱皮跳擲而斃。嗟夫！猿且知有母，不愛其死，況人也耶！", "translation": "武平出產猿猴，猿毛像金絲，閃閃發亮很好看；小猿尤其奇特，性情可以馴服，但總不離開母猿。母猿很狡猾，抓不到。獵人在箭上塗毒，趁母猿不注意時射牠。母猿估計自己活不了，把乳汁灑在林間讓小猿喝；灑完就斷氣了。獵人拿母猿的皮對著小猿鞭打，小猿就悲哀地叫著下樹，收起手來任人捕捉，每晚一定要睡在母皮上才安心。更甚的，抱著母皮跳躍翻滾而死。唉！猿猴尚且知道有母親，不吝惜自己的生命，何況是人呢！", "keywords": [{"w": "黠", "m": "狡猾、機靈"}, {"w": "致", "m": "捕得"}, {"w": "傅", "m": "同「敷」，塗抹"}, {"w": "伺母間", "m": "趁母猿不備"}, {"w": "度", "m": "估計"}, {"w": "斂手就制", "m": "收手就擒"}, {"w": "不愛其死", "m": "不吝惜自己的性命"}], "questions": [{"n": 11, "qtype": "單選", "stem": "閱讀下文，選出敘述正確的選項：", "options": {"A": "本文藉猿來諷勸世人當愛其子", "B": "小猿機靈活潑，母猿很難制伏", "C": "小猿生性戀母，獵人加以利用而得逞", "D": "獵人趁母猿的疏忽，用毒箭偷襲小猿"}, "answer": "C", "explain": "小猿「不離母」，母猿死後，獵人拿母皮鞭打，小猿就悲鳴下樹、乖乖就擒，可見獵人正是利用小猿戀母的天性得手，(C)正確。(A)錯：結尾「猿且知有母…況人也耶」是勸人要孝順母親，不是愛子女。(B)錯：「黠，不可致」說的是母猿難抓，小猿反而「性可馴」。(D)錯：毒箭射的是母猿（伺母間射之），不是小猿。", "skill": "寓言題最後的「嗟夫」感嘆句就是主旨；細節題則要把每個動作對準「誰做的、對誰做」。"}], "difficulty": "易", "label": "101指考", "year": 101, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk101-12", "exam": "zk101", "nums": [12], "form": "單題", "img": "img/zk101-12.png", "source": "甲：范仲淹〈蘇幕遮〉；乙：晏幾道〈思遠人〉", "author": "范仲淹、晏幾道", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感", "寫作手法"], "passage": "甲、碧雲天，黃葉地，秋色連波，波上寒煙翠。山映斜陽天接水，芳草無情，更在斜陽外。黯鄉魂，追旅思，夜夜除非，好夢留人睡。明月樓高休獨倚，酒入愁腸，化作相思淚。\n乙、紅葉黃花秋意晚，千里念行客。看飛雲過盡，歸鴻無信，何處寄書得？淚彈不盡臨窗滴，就硯旋研墨。漸寫到別來，此情深處，紅箋為無色。", "translation": "甲：藍天白雲，滿地黃葉，秋色連著水波，波上籠著帶綠意的寒煙。山映著夕陽，天連著江水，無情的芳草一直延伸到斜陽之外。思鄉讓人黯然，羈旅的愁思緊緊糾纏，每夜除非做個好夢才睡得著。明月照高樓，別再獨自倚欄了，酒喝進愁腸，都化成相思的眼淚。\n乙：紅葉黃花，秋意已深，思念著千里外的遠行人。看著飛雲飄盡，北歸的雁也沒帶來音信，要把信寄到哪裡呢？眼淚彈不完，滴在窗前，就著硯台用淚水磨墨。慢慢寫到分別以來的心事，寫到情深處，淚水把紅色信箋都洗得褪了色。", "keywords": [{"w": "黯鄉魂", "m": "因思鄉而黯然傷神"}, {"w": "旅思", "m": "羈旅在外的愁思"}, {"w": "歸鴻", "m": "歸雁，古人以雁傳書"}, {"w": "紅箋", "m": "紅色信紙"}], "questions": [{"n": 12, "qtype": "單選", "stem": "閱讀下列兩首宋詞，選出敘述正確的選項：", "options": {"A": "均以避世離俗作為主題", "B": "均表現濃厚的離愁別緒", "C": "均採用先情後景的寫作手法", "D": "均描寫臨別時刻的場景與心情"}, "answer": "B", "explain": "甲詞寫遊子思鄉（黯鄉魂、相思淚），乙詞寫思念遠行的人（千里念行客、淚彈不盡），兩首都是分離後的思念愁苦，(B)正確。(A)錯：兩首都在寫思念，沒有逃離世俗的意思。(C)錯：兩首都是先寫秋景（碧雲天黃葉地／紅葉黃花），再寫情，是「先景後情」。(D)錯：寫的是分別「以後」的思念（乙詞還說「寫到別來」），不是臨別當下。", "skill": "比較詩詞先各用一句話說出「誰在想誰、什麼時候」，再看寫法是景在前還是情在前。"}], "difficulty": "易", "label": "101指考", "year": 101, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk101-13", "exam": "zk101", "nums": [13], "form": "單題", "img": "img/zk101-13.png", "source": "張養浩〈沽美酒帶太平令〉", "author": "張養浩", "genre": "古典詩詞曲", "types": ["典故出處", "詩詞賞析", "主旨寓意"], "passage": "在官時只說閑，得閑也又思官。直到教人做樣看。從前的試觀，那一個不遇災難？楚大夫行吟澤畔，伍將軍血污衣冠，烏江岸消磨了好漢，咸陽市乾休了丞相。這幾個百般，要安、不安，怎如俺五柳莊逍遙散誕！", "translation": "當官時總說想清閒，真的清閒了又想當官。直到落得讓人當作反面教材來看。試看從前那些人，哪一個沒遭遇災難？楚國大夫屈原在江邊邊走邊吟詩，伍子胥將軍鮮血染紅了衣冠，烏江岸邊斷送了英雄項羽，咸陽街市白白丟了丞相李斯的性命。這幾個人千方百計想求平安卻得不到，哪比得上我在五柳莊這樣逍遙自在！", "keywords": [{"w": "做樣看", "m": "當作榜樣（教訓）來看"}, {"w": "楚大夫", "m": "屈原"}, {"w": "伍將軍", "m": "伍子胥"}, {"w": "乾休", "m": "白白斷送"}, {"w": "五柳莊", "m": "借陶淵明（五柳先生）的隱居處"}, {"w": "散誕", "m": "自在不受拘束"}], "questions": [{"n": 13, "qtype": "單選", "stem": "閱讀下列散曲，選出敘述不正確的選項：", "options": {"A": "「伍將軍血污衣冠」指有功於吳國卻被賜劍自裁的伍子胥", "B": "「咸陽市乾休了丞相」指受趙高誣陷而被斬於咸陽的李斯", "C": "「在官時只說閑，得閑也又思官」寫出無官一身輕的閒適", "D": "「怎如俺五柳莊逍遙散誕」反映作者嚮往陶潛的隱居生活"}, "answer": "C", "explain": "(C)不正確：這兩句是在諷刺人心矛盾——做官時嫌忙想退休，退休了又想做官，寫的是貪戀官位、患得患失，不是閒適。(A)正確：伍子胥幫吳國打敗楚國，後來被吳王夫差賜劍自殺。(B)正確：李斯被趙高誣陷謀反，在咸陽被腰斬。(D)正確：「五柳」借指陶淵明，作者最後說哪比得上隱居的逍遙自在。", "skill": "散曲常用歷史人物當例子，先認出典故的人，再抓最後一句的「怎如俺…」看作者真正的立場。"}], "difficulty": "易", "label": "101指考", "year": 101, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk101-16", "exam": "zk101", "nums": [16, 17], "form": "題組", "img": "img/zk101-16.png", "source": "韓愈〈藍田縣丞廳壁記〉", "author": "韓愈", "genre": "其他", "types": ["句意理解", "文意推論", "寫作手法"], "passage": "丞之職，所以貳令，於一邑無所不當問。其下主簿、尉，主簿、尉乃有分職。丞位高而偪，例以嫌不可否事。文書行，吏抱成案詣丞，卷其前，鉗以左手，右手摘紙尾，雁鶩行以進，平立，睨丞曰：「當署。」丞涉筆占位，署惟謹，目吏問可不可。吏曰：「得」，則退；不敢略省，漫不知何事。官雖尊，力勢反出主簿、尉下。諺數慢，必曰丞，至以相訾謷。丞之設，豈端使然哉！\n博陵崔斯立，種學績文，以蓄其有，泓涵演迤，日大以肆。貞元初，挾其能，戰藝於京師，再進再屈千人。元和初，以前大理評事言得失黜官，再轉而為丞茲邑。始至，喟曰：「官無卑，顧材不足塞職。」既噤不得施用，又喟曰：「丞哉！丞哉！余不負丞而丞負余！」則盡枿去牙角，一躡故跡，破崖岸而為之。\n丞廳故有記，壞漏污不可讀；斯立易桷與瓦，墁治壁，悉書前任人名氏。庭有老槐四行，南牆鉅竹千梃，儼立若相持；水㶁㶁循除鳴，斯立痛掃溉，對樹二松，日哦其間。有問者，輒對曰：「余方有公事，子姑去。」\n考功郎中知制誥韓愈記。", "translation": "縣丞這個職位，是用來輔佐縣令的，全縣的事沒有不該過問的。它下面有主簿、縣尉，主簿和縣尉才各有專門職掌。縣丞地位高而逼近縣令，照例為了避嫌，對公事不表示可否。公文要發出時，小吏抱著擬好的案卷到縣丞那裡，把前面的內容捲起來，用左手夾住，右手捏著紙尾，像雁鴨一樣大搖大擺地走進來，直挺挺站著，斜眼看著縣丞說：「該簽名了。」縣丞拿筆蘸墨找好位置，小心謹慎地簽名，然後看著小吏問行不行。小吏說：「可以。」就退下；縣丞不敢稍微看一下內容，完全不知道是什麼事。官位雖然尊貴，權力反而在主簿、縣尉之下。民間諺語數落閒散無用的官，一定說縣丞，甚至用它來互相譏罵。設置縣丞的本意，難道真是要這樣嗎！\n博陵人崔斯立，努力治學、精於寫作，累積自己的學問，學識深廣，一天比一天更宏大恣肆。貞元初年，憑著才能到京城參加考試，兩次應考都勝過上千人。元和初年，因為以前當大理評事時議論朝政得失被貶官，兩次轉任後來當這個縣的縣丞。剛到任時，他嘆說：「官職沒有卑微的，只怕才能不足以勝任。」後來被迫閉口、才能無法施展，又嘆道：「縣丞啊！縣丞啊！我沒有辜負縣丞這個職位，是縣丞這個職位辜負了我！」於是完全收起稜角，一切照著舊例行事，放下自己的高傲去做這個官。\n縣丞廳原本有一篇壁記，已經毀損漏水、髒得看不清；斯立換了椽子和瓦片，粉刷整修牆壁，把歷任縣丞的姓名都寫上。庭院裡有四行老槐樹，南牆邊有上千竿大竹子，莊嚴挺立像在相互對峙；水嘩嘩地沿著臺階流淌鳴響，斯立把庭院徹底打掃灌溉，對面種了兩棵松樹，每天在那裡吟詠。有人來問事，他就回答說：「我正在辦公事，你暫且走吧。」\n考功郎中、知制誥韓愈記。", "keywords": [{"w": "貳令", "m": "做縣令的副手"}, {"w": "偪", "m": "侵迫，逼近"}, {"w": "不可否事", "m": "對公事不表示可否"}, {"w": "雁鶩行", "m": "像雁鴨走路，形容大搖大擺"}, {"w": "睨", "m": "斜眼看"}, {"w": "訾謷", "m": "詆毀"}, {"w": "種學績文", "m": "像種田織布般勤於治學寫作"}, {"w": "枿", "m": "絕，去除"}, {"w": "破崖岸", "m": "放下高傲的姿態"}, {"w": "㶁㶁", "m": "水聲"}], "questions": [{"n": 16, "qtype": "單選", "stem": "依據上文，下列文句敘述正確的選項是：", "options": {"A": "「不可否事」是表達事無不可為的積極態度", "B": "「雁鶩行以進，平立」是描寫小吏對縣丞的恭敬", "C": "「種學績文」是以耕田織布比喻崔斯立的勤學善寫", "D": "「水㶁㶁循除鳴，斯立痛掃溉」是藉水聲反映出崔斯立內心的喜悅與痛快"}, "answer": "C", "explain": "(C)正確：「種」是耕種、「績」是紡織，把治學寫文章比喻成農夫種田、婦女織布那樣辛勤累積。(A)錯：「不可否事」是縣丞為了避嫌，對公事不表示可不可以，是不敢管事的消極狀態。(B)錯：小吏像雁鴨一樣大搖大擺走進來、直直站著還斜眼看縣丞，是傲慢無禮，不是恭敬。(D)錯：這句寫崔斯立在無事可做的情況下整理庭院、與松竹為伴，是借景表現他的無奈與自我排遣，不是喜悅痛快。", "skill": "判斷描寫是褒是貶，要連著前後動作一起看：「雁鶩行、平立、睨」連在一起，態度就很清楚。"}, {"n": 17, "qtype": "單選", "stem": "下列文句，前後最不能互相呼應的選項是：", "options": {"A": "至以相訾謷／既噤不得施用", "B": "其下主簿、尉／力勢反出主簿、尉下", "C": "丞之職，所以貳令／丞之設，豈端使然哉", "D": "於一邑無所不當問／不敢略省，漫不知何事"}, "answer": "A", "explain": "(A)前句說社會上用「縣丞」來互相譏罵，後句說崔斯立被迫閉口、才能無法施展，兩句講的是不同的事，沒有呼應關係，所以是答案。(B)制度上主簿、縣尉在縣丞「之下」，實際權勢卻反而「在他們之下」，前後對照呼應。(C)前句說設縣丞是要輔佐縣令，後句反問設縣丞的本意難道是這樣嗎，首尾呼應。(D)按職責縣丞應該什麼都管，實際卻連公文都不敢看一眼，前後形成強烈對比。", "skill": "「呼應」題要找同一個話題的「理想 vs. 現實」或「前提 vs. 結論」，話題不同的那組就是不呼應。"}], "difficulty": "難", "label": "101指考", "year": 101, "kind": "指考", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "師說"}, {"id": "zk101-19", "exam": "zk101", "nums": [19], "form": "單題", "img": "img/zk101-19.png", "source": "多篇古文（〈過秦論〉〈醉翁亭記〉〈曹劌論戰〉〈出師表〉〈鴻門宴〉等）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "", "translation": "", "keywords": [{"w": "區區", "m": "小"}, {"w": "再", "m": "第二次、兩次"}, {"w": "斟酌", "m": "考慮衡量／倒酒"}, {"w": "倍", "m": "通「背」，背叛／加倍"}], "questions": [{"n": 19, "qtype": "多選", "stem": "下列各組文句，「」內字詞意義相同的選項是：", "options": {"A": "以「區區」之宋，猶有不欺人之臣／然秦以「區區」之地，致萬乘之權", "B": "傴僂「提攜」往來不絕者，滁人遊也／長者與之「提攜」，則兩手奉長者之手", "C": "一鼓作氣，「再」而衰，三而竭／季文子三思而後行。子聞之，曰：「再」，斯可矣", "D": "至於「斟酌」損益，進盡忠言，則攸之、禕、允之任也／過門更相呼，有酒「斟酌」之", "E": "日夜望將軍至，豈敢反乎？願伯具言臣之不敢「倍」德也／故事半古之人，功必「倍」之"}, "answer": "AC", "explain": "(A)相同：兩個「區區」都是「小小的」。宋國很小卻有守信的臣子；秦國原本地方很小卻取得天子的權勢（〈過秦論〉）。(B)不同：〈醉翁亭記〉「傴僂提攜」，傴僂指駝背老人、提攜指被大人牽著走的小孩；〈禮記〉的「提攜」是長輩牽著小孩的手這個動作。(C)相同：都是「第二次」。第二次擊鼓士氣就衰退（〈曹劌論戰〉）；孔子說想兩次就可以了（《論語》）。(D)不同：〈出師表〉的「斟酌」是考慮、衡量；陶淵明〈移居〉的「斟酌」是倒酒對飲。(E)不同：〈鴻門宴〉的「倍」通「背」，背叛；《孟子》的「倍」是加倍。", "skill": "字義比較題把兩個詞各自放回句子，用白話替換讀讀看，順不順一試就知道。"}], "difficulty": "中", "label": "101指考", "year": 101, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "鴻門宴、出師表、醉翁亭記"}, {"id": "zk101-20", "exam": "zk101", "nums": [20], "form": "單題", "img": "img/zk101-20.png", "source": "多篇古文（〈鴻門宴〉〈燭之武退秦師〉〈左忠毅公軼事〉〈虯髯客傳〉〈庖丁解牛〉〈蘭亭集序〉等）", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "", "translation": "", "keywords": [{"w": "軍", "m": "駐紮（名詞作動詞）"}, {"w": "親", "m": "親自（副詞）"}, {"w": "目", "m": "注視、看（動詞）／眼睛（名詞）"}, {"w": "觴", "m": "飲酒（動詞）／酒杯（名詞）"}], "questions": [{"n": 20, "qtype": "多選", "stem": "下列各組文句，「」內文字詞性相同的選項是：", "options": {"A": "父義，母慈，「兄」友，弟恭／君為我呼入，吾得「兄」事之", "B": "沛公「軍」霸上，未得與項羽相見／晉「軍」函陵，秦軍氾南", "C": "謂獄中語，乃「親」得之於史公云／每得降卒，必「親」引問委曲", "D": "一妓有殊色，執紅拂，立於前，獨「目」靖／臣以神遇而不以「目」視", "E": "一「觴」一詠，亦足以暢敘幽情／引「觴」滿酌，頹然就醉，不知日之入"}, "answer": "BC", "explain": "(B)相同：兩個「軍」後面都接地點，意思是「駐紮」，都是動詞。(C)相同：兩個「親」都是「親自」，修飾後面的動詞，是副詞。(A)不同：「兄友」的兄是名詞（哥哥），當主語；「兄事之」是「像對待兄長一樣侍奉他」，名詞當副詞用。(D)不同：〈虯髯客傳〉「獨目靖」是「只注視李靖」，動詞；〈庖丁解牛〉「以目視」是用眼睛看，名詞。(E)不同：「一觴一詠」是喝一杯酒、吟一首詩，觴當動詞；「引觴」是拿起酒杯，觴是名詞。", "skill": "判斷詞性先看它在句中的位置：後面接地點或受詞多半是動詞，放在動詞前面修飾多半是副詞。"}], "difficulty": "中", "label": "101指考", "year": 101, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "燭之武退秦師、鴻門宴、蘭亭集序、虬髯客傳、左忠毅公軼事"}, {"id": "zk101-21", "exam": "zk101", "nums": [21], "form": "單題", "img": "img/zk101-21.png", "source": "多首古典詩（孟浩然〈宿建德江〉、謝朓〈晚登三山還望京邑〉、王勃〈滕王閣詩〉、白居易〈琵琶行〉等）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "", "translation": "", "keywords": [{"w": "物是人非", "m": "景物依舊，人事已改變"}, {"w": "物換星移", "m": "景物變換、星辰移位，指時光流轉"}], "questions": [{"n": 21, "qtype": "多選", "stem": "下列詩句中，藉由江水表達「物是人非」之慨嘆的選項是：", "options": {"A": "移舟泊煙渚，日暮客愁新。野曠天低樹，江清月近人", "B": "餘霞散成綺，澄江靜如練。喧鳥覆春洲，雜英滿芳甸", "C": "閒雲潭影日悠悠，物換星移幾度秋。閣中帝子今何在，檻外長江空自流", "D": "曲終收撥當心畫，四絃一聲如裂帛。東船西舫悄無言，唯見江心秋月白", "E": "青春衣繡共稱宜，白首垂絲恨不遺。江上幾回今夜月，鏡中無復少年時"}, "answer": "CE", "explain": "「物是人非」要有兩個要素：景物還在、人事已變。(C)正確：當年建閣的滕王已不在，欄杆外的長江卻依舊白白地流，正是江水不變、人事全非。(E)正確：江上的月亮年年照樣升起，鏡中的自己卻再也不是少年，用江月不變對比人已老去。(A)錯：寫旅途日暮的孤寂客愁，江清月近只是景，沒有今昔對比。(B)錯：純寫江邊晚霞、春洲的美景。(D)錯：寫琵琶曲結束後全場無聲、只見江心秋月，是烘托音樂的感染力。", "skill": "看到「物是人非」就找「不變的景 vs. 已變的人」這組對比，兩樣都要有。"}], "difficulty": "易", "label": "101指考", "year": 101, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk101-n1", "exam": "zk101", "nums": ["一"], "form": "單題", "img": "img/zk101-n1.png", "source": "《左傳‧燭之武退秦師》；王更生《文心雕龍讀本》", "author": "左丘明（相傳）", "genre": "史傳人物", "types": ["文意推論", "比較閱讀", "寫作手法"], "passage": "（燭之武）見秦伯曰：「秦、晉圍鄭，鄭既知亡矣。若亡鄭而有益於君，敢以煩執事。越國以鄙遠，君知其難也。焉用亡鄭以陪鄰？鄰之厚，君之薄也。若舍鄭以為東道主，行李之往來，共其乏困，君亦無所害。且君嘗為晉君賜矣，許君焦、瑕，朝濟而夕設版焉，君之所知也。夫晉何厭之有？既東封鄭，又欲肆其西封。若不闕秦，將焉取之？闕秦以利晉，唯君圖之。」", "translation": "燭之武見到秦伯說：「秦、晉兩國包圍鄭國，鄭國已經知道要亡國了。如果滅了鄭國對您有好處，那就勞煩您的部下動手吧。可是越過晉國，把遠方的鄭國當作秦國的邊境，您知道這是很難的。何必滅掉鄭國去增加鄰國（晉）的土地呢？鄰國的力量增強，就等於您的力量削弱了。如果放過鄭國，讓它當東方道路上的主人，秦國使者來來往往，鄭國可以供應他們缺少的東西，對您也沒有什麼害處。況且您曾經給晉君恩惠，他答應把焦、瑕兩地給您，結果早上渡河回國，晚上就築起城牆防備您，這是您知道的。晉國哪有滿足的時候？它向東把鄭國當作邊界之後，又想向西擴張。如果不削減秦國的土地，要從哪裡取得呢？削弱秦國來讓晉國得利，希望您好好考慮。」", "keywords": [{"w": "執事", "m": "辦事的人，對對方的敬稱"}, {"w": "鄙遠", "m": "把遠方土地當作邊邑"}, {"w": "陪", "m": "增加"}, {"w": "東道主", "m": "東方道路上的主人"}, {"w": "行李", "m": "使者"}, {"w": "共", "m": "通「供」，供給"}, {"w": "設版", "m": "築牆防守"}, {"w": "厭", "m": "通「饜」，滿足"}, {"w": "封", "m": "疆界，此作動詞「以…為疆界」"}, {"w": "闕", "m": "通「缺」，使減損"}], "questions": [{"n": "一", "qtype": "非選", "stem": "文章解讀（占18分）：閱讀框內甲、乙兩段文章之後，請解釋：燭之武為了達到「言資悅懌」的遊說目的，如何掌握「時利」、「義貞」這兩個重要原則？並分（一）「時利」、（二）「義貞」，依序回答。（一）、（二）合計文長約200—250字（約9—11行）。", "options": {}, "answer": "", "ref_answer": "（一）時利：從秦、晉、鄭三國的形勢分析利害。1.就地理位置而言，鄭亡對晉有利、對秦有害——「越國以鄙遠，君知其難也。焉用亡鄭以陪鄰？鄰之厚，君之薄也」。2.捨棄攻鄭，對秦不僅無害反而有利——「若舍鄭以為東道主，行李之往來，共其乏困，君亦無所害」。（二）義貞：指出晉國曾經背信，又有擴張野心，將來必定危害秦國——「且君嘗為晉君賜矣，許君焦、瑕，朝濟而夕設版焉」「夫晉何厭之有？既東封鄭，又欲肆其西封。若不闕秦，將焉取之？」以正大的道理說明不能再信任晉國。", "ref_official": true, "explain": "先用甲文把兩個詞翻成白話：「時利」是順著當下局勢講利害，「義貞」是用正大的道理說服人。再回到乙文分段對號：前半段講地理位置（秦遠鄭近晉）和放過鄭國的好處，這是「時利」；後半段翻晉國的舊帳（答應給地卻築城防秦）和預言晉國貪得無厭，這是用信義與道理讓秦伯心服，屬於「義貞」。作答時每一點都引一句原文，再用自己的話說明它為什麼有說服力。", "skill": "文章解讀題先把題目給的關鍵詞定義清楚，再到原文逐句「對號入座」，一個論點配一句引文。"}], "difficulty": "中", "label": "101指考", "year": 101, "kind": "指考", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "燭之武退秦師"}, {"id": "xc102-4", "exam": "xc102", "nums": [4], "form": "單題", "img": "img/xc102-4.png", "source": "《左傳‧燭之武退秦師》、《論語》、《孟子》", "author": "多位作者", "genre": "經典語錄", "types": ["虛詞句式"], "passage": "(A)夫晉，何厭之有\n(B)父母唯其疾之憂\n(C)其一人專心致志，惟弈秋之為聽\n(D)用之則行，舍之則藏，唯我與爾有是夫", "translation": "(A)晉國哪有滿足的時候？(B)父母只擔憂子女的疾病。(C)其中一人專心一意，只聽弈秋的教導。(D)被任用就出來行道，不被任用就隱藏起來，只有我和你能做到這樣吧！", "keywords": [{"w": "厭", "m": "通「饜」，滿足"}, {"w": "之", "m": "賓語前置的標誌，不譯"}, {"w": "舍", "m": "捨棄、不用"}, {"w": "爾", "m": "你"}], "questions": [{"n": 4, "qtype": "單選", "stem": "古漢語中，往往為強調賓語（受詞），而將賓語提到動詞前面。下列不屬於這種語法結構的選項是：", "options": {"A": "夫晉，何厭之有", "B": "父母唯其疾之憂", "C": "其一人專心致志，惟弈秋之為聽", "D": "用之則行，舍之則藏，唯我與爾有是夫"}, "answer": "D", "explain": "把句子還原成「動詞＋賓語」的正常語序就知道。(A)「何厭之有」＝「有何厭」，賓語「何厭」提到動詞「有」前，用「之」標記。(B)「唯其疾之憂」＝「唯憂其疾」，賓語「其疾」提前。(C)「惟弈秋之為聽」＝「惟聽弈秋」，賓語「弈秋」提前，用「之為」標記。(D)「唯我與爾有是夫」中，「我與爾」是主語，「有」是動詞，「是」是賓語，語序正常，沒有賓語前置，所以選(D)。", "skill": "看到「唯／惟＋名詞＋之＋動詞」或「何＋名詞＋之有」，就是賓語前置的固定句型；把名詞搬回動詞後面讀讀看。"}], "difficulty": "中", "label": "102學測", "year": 102, "kind": "學測", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "燭之武退秦師"}, {"id": "xc102-5", "exam": "xc102", "nums": [5], "form": "單題", "img": "img/xc102-5.png", "source": "蕭繹《金樓子‧立言篇》", "author": "蕭繹", "genre": "說理議論", "types": ["文意推論", "寫作手法"], "passage": "〈擣衣〉清而徹，有悲人者。此是秋士悲於心，擣衣感於外，內外相感，愁情結悲，然後哀怨生焉。苟無感，何嗟何怨也！", "translation": "〈擣衣〉這首詩清澈透徹，讓人讀了悲傷。這是因為秋天的士人心中本來就悲傷，又被外面擣衣的聲音觸動，內心與外物互相感應，愁緒凝結成悲傷，然後哀怨就產生了。如果沒有感觸，又哪來的嘆息和哀怨呢！", "keywords": [{"w": "擣衣", "m": "把衣物放在石砧上捶打清洗，古詩中常引起思念"}, {"w": "徹", "m": "透徹"}, {"w": "苟", "m": "如果"}], "questions": [{"n": 5, "qtype": "單選", "stem": "下列是一段評論〈擣衣〉詩的文字，依文意選出排列順序最恰當的選項：〈擣衣〉清而徹，有悲人者。此是　甲、內外相感，愁情結悲　乙、秋士悲於心　丙、然後哀怨生焉　丁、擣衣感於外　苟無感，何嗟何怨也！（蕭繹《金樓子．立言篇》）", "options": {"A": "乙丙丁甲", "B": "乙丁甲丙", "C": "丁甲乙丙", "D": "丁丙乙甲"}, "answer": "B", "explain": "乙「悲於心」和丁「感於外」是一組對句，一內一外，必須連在一起；接著甲「內外相感」正好總結前面的「心」（內）與「外」；最後丙「然後哀怨生焉」是結果，也接到末句「苟無感，何嗟何怨也」（反面說明）。順序乙丁甲丙，選(B)。(A)把結果丙放在前面；(C)(D)甲或丙出現在乙之前，「內外相感」就沒有前文可以總結。", "skill": "排序先找「對句」綁在一起，再找總結語（內外相感）放在對句之後，「然後」類的結果句放最後。"}], "difficulty": "易", "label": "102學測", "year": 102, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc102-6", "exam": "xc102", "nums": [6], "form": "單題", "img": "img/xc102-6.png", "source": "張之洞撰蘇軾故居對聯", "author": "張之洞", "genre": "其他", "types": ["文化常識", "典故出處"], "passage": "五年間謫宦棲遲，較量惠州麥飯、儋耳蠻花，哪得此清幽山水；\n三蘇中天才獨絕，若論東坡八詩、赤壁兩賦，還是公遊戲文章。", "translation": "上聯：蘇軾在這裡貶官居住了五年，拿他後來在惠州吃麥飯、在儋耳看蠻地野花的日子來比，哪裡有這裡這樣清幽的山水？下聯：三蘇之中他的天才最為突出，若說到〈東坡八首〉、前後〈赤壁賦〉這些名作，也不過是他隨手寫來的遊戲文章罷了。", "keywords": [{"w": "謫宦", "m": "被貶官"}, {"w": "棲遲", "m": "居住、停留"}, {"w": "儋耳", "m": "今海南島儋州，蘇軾晚年貶所"}, {"w": "三蘇", "m": "蘇洵、蘇軾、蘇轍父子"}], "questions": [{"n": 6, "qtype": "單選", "stem": "右圖是張之洞所撰的蘇軾故居對聯，上下聯各缺兩句，請依文意與對聯組成原則，選出甲、乙、丙、丁依序最適合填入的選項：甲、較量惠州麥飯、儋耳蠻花　乙、若論東坡八詩、赤壁兩賦　丙、還是公遊戲文章　丁、哪得此清幽山水（上聯：五年間謫宦栖遲，①，②；下聯：三蘇中天才獨絕，③，④）", "options": {"A": "①甲②丁③乙④丙", "B": "①乙②丁③甲④丙", "C": "①甲②丙③乙④丁", "D": "①乙②丙③甲④丁"}, "answer": "A", "explain": "先分內容：上聯開頭「五年間謫宦棲遲」講貶官生活和居住地，所以接比較各貶所的甲「惠州麥飯、儋耳蠻花」，再接丁「哪得此清幽山水」（稱讚此地）。下聯開頭「三蘇中天才獨絕」講才華，所以接作品的乙「東坡八詩、赤壁兩賦」，再接丙「還是公遊戲文章」。再檢查對仗：甲「惠州麥飯、儋耳蠻花」對乙「東坡八詩、赤壁兩賦」，都是「地名＋物」並列；丁「哪得此清幽山水」對丙「還是公遊戲文章」。另外上聯末字要仄聲（水），下聯末字要平聲（章），也符合。答案(A)。", "skill": "對聯填空：先依上下聯開頭的主題分組，再看字數與詞性對仗，最後用「上聯仄收、下聯平收」驗證。"}], "difficulty": "中", "label": "102學測", "year": 102, "kind": "學測", "textcat": "生活情境文本", "textcat2": "延伸", "linked_core": "赤壁賦"}, {"id": "xc102-11", "exam": "xc102", "nums": [11], "form": "單題", "img": "img/xc102-11.png", "source": "羅大經《鶴林玉露》", "author": "羅大經", "genre": "筆記小品", "types": ["主旨寓意"], "passage": "昔有僕嫌其妻之陋者。主翁聞之，召僕至，以銀杯、瓦椀各一，酌酒飲之。問曰：「酒佳乎？」對曰：「佳。」「銀杯者佳乎？瓦椀者佳乎？」對曰：「皆佳。」主翁曰：「杯有精粗，酒無分別。汝既知此，則無嫌於汝妻之陋矣。」僕悟，遂安其室。", "translation": "從前有個僕人嫌棄妻子長得醜。主人聽說了，把僕人叫來，用一個銀杯、一個瓦碗各倒了酒給他喝。問他：「酒好嗎？」僕人回答：「好。」「銀杯裡的好，還是瓦碗裡的好？」回答：「都好。」主人說：「杯子有精緻粗糙之分，酒卻沒有差別。你既然懂得這個道理，就不該嫌棄你妻子醜了。」僕人醒悟，於是安心和妻子過日子。", "keywords": [{"w": "陋", "m": "容貌醜"}, {"w": "酌", "m": "倒酒"}, {"w": "椀", "m": "通「碗」"}, {"w": "安其室", "m": "安於家庭生活"}], "questions": [{"n": 11, "qtype": "單選", "stem": "閱讀下文，選出最接近本文主旨的選項：", "options": {"A": "承恩不在貌", "B": "命無莫強求", "C": "曾經滄海難為水", "D": "糟糠之妻不下堂"}, "answer": "A", "explain": "主人用比喻說理：杯子（外貌）有精粗，酒（內在）卻一樣好，所以不該因外貌嫌棄妻子。重點是「價值不在外貌」，(A)「承恩不在貌」（得到恩寵不在於容貌）最接近。(B)講命運不可強求，與本文無關。(C)比喻見過最好的，其他的都看不上眼，方向相反。(D)指不可拋棄共患難的妻子，重點在「不忘舊情、富貴不棄」，本文沒有僕人富貴或患難的情節，重點在外貌與內在。", "skill": "寓言說理題，先把比喻對應出來（杯＝外貌、酒＝內在），再找講同一組關係的選項。"}], "difficulty": "易", "label": "102學測", "year": 102, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc102-14", "exam": "xc102", "nums": [14, 15], "form": "題組", "img": "img/xc102-14.png", "source": "俞樾《春在堂隨筆》", "author": "俞樾", "genre": "筆記小品", "types": ["虛詞句式", "句意理解", "文意推論"], "passage": "余居西湖寓樓，樓多鼠，每夕跳踉几案，若行康莊，燭有餘燼，無不見跋。始甚惡之，繼而念鼠亦飢耳，至於余衣服書籍一無所損，又何惡焉。適有饋餅餌者，夜則置一枚於案頭以飼之，鼠得餅，不復嚼蠟矣。一夕，余自食餅，覺不佳，復吐出之，遂並以飼鼠。次日視之，餅盡，而余所吐棄者故在。乃笑曰：「鼠子亦狷介乃爾。」是夕，置二餅以謝之。次日，止食其一。余嘆曰：「不惟狷介，乃亦有禮。」", "translation": "我住在西湖邊的寓所樓上，樓裡老鼠很多，每晚在桌上跳來跳去，好像走在大馬路上一樣；蠟燭有剩下的殘段，沒有不被啃掉的。起初我很討厭牠們，後來想到老鼠也只是餓罷了，至於我的衣服書籍一點都沒有損壞，又何必討厭呢？剛好有人送我餅，晚上我就放一塊在桌上餵牠們，老鼠得到餅，就不再啃蠟燭了。有一晚，我自己吃餅，覺得不好吃，吐了出來，就一起拿去餵老鼠。第二天去看，餅吃光了，我吐掉的那塊卻還在。我就笑說：「小老鼠也這樣有骨氣啊。」這天晚上，我放了兩塊餅答謝牠。隔天，牠只吃了其中一塊。我感嘆說：「不只有骨氣，而且還懂禮節。」", "keywords": [{"w": "跳踉", "m": "跳躍"}, {"w": "康莊", "m": "四通八達的大路"}, {"w": "跋", "m": "蠟燭燃燒後的殘餘部分"}, {"w": "饋", "m": "贈送"}, {"w": "故在", "m": "仍然在"}, {"w": "狷介", "m": "潔身自好、有所不為"}, {"w": "乃爾", "m": "如此、這樣"}], "questions": [{"n": 14, "qtype": "單選", "stem": "依據文意，依序選出□□內最適合填入的選項：（始甚惡之，□□念鼠亦飢耳……余嘆曰：「□□狷介，乃亦有禮。」）", "options": {"A": "已而／不亦", "B": "俄而／不失", "C": "從而／不無", "D": "繼而／不惟"}, "answer": "D", "explain": "第一空：前面說「始甚惡之」（起初很討厭），後面是想法改變，要填表示時間先後的「繼而」（接著、後來）；「已而」也有不久之意，但「俄而」是很短的片刻，「從而」表示因此、進而，都不如「繼而」與「始」相對。第二空：「□□狷介，乃亦有禮」，後半「乃亦」（而且還）提示前半是「不只……」，要填「不惟」（不僅），形成「不惟……乃亦……」的遞進句。「不亦」是反問語氣（不也……嗎），「不失」是仍算得上，「不無」是並非沒有，都接不上「乃亦」。答案(D)。", "skill": "填虛詞先看搭配：「始……繼而……」表時間先後；「不惟……乃亦／而且……」表遞進。"}, {"n": 15, "qtype": "單選", "stem": "依據文意，選出敘述錯誤的選項：", "options": {"A": "「跳踉几案，若行康莊」，意謂：老鼠橫行無忌，毫不畏懼人", "B": "「燭有餘燼，無不見跋」，意謂：老鼠飢不擇食，連蠟燭都吃", "C": "「余所吐棄者故在」，意謂：老鼠取捨不苟，有所為有所不為", "D": "「置二餅以謝之」，意謂：老鼠無損衣物，故得到主人的酬謝"}, "answer": "D", "explain": "(A)正確，在桌上跳來跳去像走大路，表示毫不怕人。(B)正確，蠟燭殘段都被啃掉，後文「不復嚼蠟」也可印證老鼠餓到連蠟燭都吃。(C)正確，吐過的餅不吃，作者笑牠「狷介」，就是有所不為。(D)錯誤。作者放兩塊餅「謝之」，是緊接在發現老鼠不吃他吐掉的餅、稱讚牠「狷介」之後，酬謝的是牠的骨氣；「無損衣物」是作者早先決定不討厭老鼠的理由，不是這次答謝的原因。", "skill": "判斷「因果」要看事件緊接的上下文：謝禮出現在哪個情節之後，就是在謝那件事。"}], "difficulty": "中", "label": "102學測", "year": 102, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc102-18", "exam": "xc102", "nums": [18], "form": "單題", "img": "img/xc102-18.png", "source": "《論語》、諸葛亮〈出師表〉、張岱〈西湖七月半〉、吳敬梓〈范進中舉〉等", "author": "多位作者", "genre": "其他", "types": ["文化常識"], "passage": "(C)先帝創業未半，而中道崩殂。\n(D)杭人遊湖，巳出酉歸。\n(E)范進進學回家，母親、妻子俱各歡喜。", "translation": "", "keywords": [{"w": "崩", "m": "帝王去世"}, {"w": "巳時", "m": "上午九點到十一點"}, {"w": "酉時", "m": "下午五點到七點"}, {"w": "進學", "m": "童試及格，成為秀才"}], "questions": [{"n": 18, "qtype": "多選", "stem": "下列有關古代文化知識的敘述，正確的選項是：", "options": {"A": "孔門四科為德行、言語、政事、文學", "B": "古人以二十歲為成年，一般貴族男女，於該年行冠禮", "C": "諸葛亮〈出師表〉：「先帝創業未半，而中道崩殂。」「崩」，在古代為帝王過世的用語", "D": "張岱〈西湖七月半〉：「杭人遊湖，巳出酉歸。」「巳出酉歸」，是指：天未亮即出門，傍晚才回家", "E": "吳敬梓〈范進中舉〉：「范進進學回家，母親、妻子俱各歡喜。」「進學」，是指：范進經「童試」及格，考取秀才"}, "answer": "ACE", "explain": "(A)正確，《論語‧先進》列出孔門四科：德行、言語、政事、文學。(B)錯誤，男子二十歲行「冠禮」，女子是十五歲行「笄禮」，不是男女同在二十歲行冠禮。(C)正確，古代天子死稱「崩」，諸侯稱「薨」，大夫稱「卒」。(D)錯誤，巳時是上午九到十一點，酉時是下午五到七點，「巳出酉歸」是上午出門、傍晚回家，不是天沒亮就出門。(E)正確，「進學」指通過童試、成為秀才，可以進入府州縣學讀書。", "skill": "十二時辰從「子時＝23–1點」開始每兩小時一格往後推（丑1–3、寅3–5、卯5–7、辰7–9、巳9–11……酉17–19）。"}], "difficulty": "中", "label": "102學測", "year": 102, "kind": "學測", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "出師表"}, {"id": "xc102-21", "exam": "xc102", "nums": [21], "form": "單題", "img": "img/xc102-21.png", "source": "蘇洵〈六國論〉、方孝孺〈指喻〉、柳宗元〈始得西山宴遊記〉、《戰國策‧馮諼客孟嘗君》、方苞〈左忠毅公軼事〉、《論語》、岳飛〈良馬對〉、司馬光〈訓儉示康〉等", "author": "多位作者", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)至丹以荊卿為計，始速禍焉／況乎視之以至疎之勢，重之以疲敝之餘，吏之戕摩剝削以速其疾者亦甚矣\n(B)尺寸千里，攢蹙累積，莫得遯隱；縈青繚白，外與天際，四望如一／海外獨身遊，風雲際會秋。我傳靈德去，仗劍鬼神愁\n(C)臣竊矯君命，以責賜諸民，因燒其券，民稱萬歲，乃臣所以為君市義也／公辨其聲，而目不可開，乃奮臂以指撥眥，目光如炬\n(D)比及三年，可使有勇，且知方也／介而馳，初不甚疾，比行百里，始奮迅，自午至酉，猶可二百里，褫鞍甲而不息不汗，若無事然\n(E)有顏回者好學，不遷怒，不貳過。不幸短命死矣，今也則亡／家人習奢已久，不能頓儉，必致失所。豈若吾居位、去位、身存、身亡，常如一日乎", "translation": "", "keywords": [{"w": "速", "m": "招致；加速"}, {"w": "際", "m": "交會、相接"}, {"w": "乃", "m": "是；於是"}, {"w": "比", "m": "等到"}, {"w": "亡", "m": "通「無」；死亡"}], "questions": [{"n": 21, "qtype": "多選", "stem": "下列各組「」內的文字，前後意義相同的選項是：", "options": {"A": "至丹以荊卿為計，始「速」禍焉／況乎視之以至疎之勢，重之以疲敝之餘，吏之戕摩剝削以「速」其疾者亦甚矣", "B": "尺寸千里，攢蹙累積，莫得遯隱；縈青繚白，外與天「際」，四望如一／海外獨身遊，風雲「際」會秋。我傳靈德去，仗劍鬼神愁", "C": "臣竊矯君命，以責賜諸民，因燒其券，民稱萬歲，「乃」臣所以為君市義也／公辨其聲，而目不可開，「乃」奮臂以指撥眥，目光如炬", "D": "「比」及三年，可使有勇，且知方也／介而馳，初不甚疾，「比」行百里，始奮迅，自午至酉，猶可二百里，褫鞍甲而不息不汗，若無事然", "E": "有顏回者好學，不遷怒，不貳過。不幸短命死矣，今也則「亡」／家人習奢已久，不能頓儉，必致失所。豈若吾居位、去位、身存、身「亡」，常如一日乎"}, "answer": "BD", "explain": "(A)錯誤。前者「速禍」是「招致」災禍；後者「速其疾」是「加速」百姓的痛苦。(B)正確。兩個「際」都是交會、相接：遠處與天相接；風雲交會。(C)錯誤。前者「乃」是「是、就是」（這就是我為您買義的方法）；後者是「於是、就」（於是奮力舉起手臂）。(D)正確。兩個「比」都是「等到」：等到三年；等到跑了百里。(E)錯誤。前者「亡」通「無」（現在就沒有這樣的人了）；後者是「死亡」，與「身存」相對。", "skill": "字義比較時，前後句各換一個白話詞代進去；「亡」看到「今也則亡」要想到通「無」。"}], "difficulty": "中", "label": "102學測", "year": 102, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "馮諼客孟嘗君、始得西山宴遊記、左忠毅公軼事"}, {"id": "xc102-22", "exam": "xc102", "nums": [22], "form": "單題", "img": "img/xc102-22.png", "source": "《論語》、顧炎武〈與人書〉、《孟子‧滕文公下》等", "author": "多位作者", "genre": "經典語錄", "types": ["句意理解"], "passage": "(A)居處恭，執事敬，與人忠：雖之夷狄，不可棄也\n(B)善人同處，則日聞嘉訓；惡人從游，則日生邪情\n(C)獨學無友，則孤陋而難成；久處一方，則習染而不自覺\n(D)一齊人傅之，眾楚人咻之，雖日撻而求其齊也，不可得矣\n(E)子欲居九夷。或曰：「陋，如之何？」子曰：「君子居之，何陋之有！」", "translation": "(A)平時恭敬莊重，做事認真，待人忠誠，即使到了夷狄之地，也不可放棄。(B)和好人相處，每天都能聽到好的教誨；和壞人交往，每天都會產生邪念。(C)一個人學習而沒有朋友切磋，就會見識淺陋難以成就；長久待在一個地方，就會被習氣沾染而不自覺。(D)一個齊國人教他，一群楚國人在旁邊吵鬧干擾，即使每天鞭打他要他學會齊語，也做不到。(E)孔子想去九夷居住。有人說：「那裡簡陋，怎麼辦？」孔子說：「君子住在那裡，有什麼簡陋的呢！」", "keywords": [{"w": "之", "m": "到、往"}, {"w": "傅", "m": "教導"}, {"w": "咻", "m": "喧擾"}, {"w": "撻", "m": "鞭打"}, {"w": "習染", "m": "受習氣影響"}], "questions": [{"n": 22, "qtype": "多選", "stem": "下列引文，陳述外在環境對人產生影響的選項是：", "options": {"A": "居處恭，執事敬，與人忠：雖之夷狄，不可棄也", "B": "善人同處，則日聞嘉訓；惡人從游，則日生邪情", "C": "獨學無友，則孤陋而難成；久處一方，則習染而不自覺", "D": "一齊人傅之，眾楚人咻之，雖日撻而求其齊也，不可得矣", "E": "子欲居九夷。或曰：「陋，如之何？」子曰：「君子居之，何陋之有！」"}, "answer": "BCD", "explain": "判斷方向：是「環境影響人」，還是「人不受環境影響／人影響環境」。(A)強調不管到哪裡都要堅守恭、敬、忠，是個人修養不因環境改變，方向相反。(B)和善人或惡人相處，會讓人日聞嘉訓或日生邪情，是環境影響人。(C)沒有朋友、久居一地，都會讓人孤陋、受習染，是環境影響人。(D)楚人環繞喧擾，讓人學不會齊語，是環境影響人。(E)君子住在九夷，就能改變當地的簡陋，是人影響環境，方向相反。", "skill": "這類題先畫出箭頭：環境→人，還是人→環境，箭頭方向不同就排除。"}], "difficulty": "易", "label": "102學測", "year": 102, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc102-23", "exam": "xc102", "nums": [23], "form": "單題", "img": "img/xc102-23.png", "source": "屠本畯《艾子外語‧蛇虎告語》", "author": "屠本畯", "genre": "寓言故事", "types": ["主旨寓意", "文意推論"], "passage": "東蒙山中人喧傳虎來。艾子采茗，從壁上觀。聞蛇告虎曰：「君出而人民辟易，禽獸奔駭，勢烜赫哉！余出而免人踐踏，已為厚幸。欲憑藉寵靈，光輝山岳，何道而可？」虎曰：「憑余軀以行，可耳。」蛇於是憑虎行。未數里，蛇性不馴。虎被緊纏，負隅聳躍，蛇分二段。蛇怒曰：「憑得片時，害卻一生，冤哉！」虎曰：「不如是，幾被纏殺！」艾子曰：「倚勢作威，榮施一時，終獲後災，戒之！」", "translation": "東蒙山裡的人紛紛傳說老虎來了。艾子正在採茶，就在山壁上觀看。只聽見蛇對老虎說：「您一出來，人們嚇得退避，禽獸驚慌奔逃，聲勢多麼顯赫！我出來能不被人踩到，就已經很幸運了。我想藉您的威風，在山林中風光一下，有什麼辦法嗎？」老虎說：「攀附在我身上走，就可以了。」蛇於是攀著老虎走。走不到幾里，蛇的本性難改，緊緊纏住老虎。老虎被纏得受不了，背靠山角奮力跳躍，蛇被甩成兩截。蛇生氣地說：「才風光一下子，卻害了我一輩子，冤枉啊！」老虎說：「不這樣做，我差點被你纏死！」艾子說：「依仗權勢作威作福，風光只是一時，最後一定招來災禍，要引以為戒啊！」", "keywords": [{"w": "辟易", "m": "驚退躲避"}, {"w": "烜赫", "m": "聲勢盛大"}, {"w": "寵靈", "m": "恩寵、威勢"}, {"w": "負隅", "m": "背靠山的彎曲處"}, {"w": "幾", "m": "差一點"}], "questions": [{"n": 23, "qtype": "多選", "stem": "閱讀下文，選出符合文意的選項：", "options": {"A": "艾子世居東蒙山，平日以觀蛇虎相鬥為樂", "B": "憑虎而行的蛇，本性難移，因而對虎不利", "C": "虎置蛇於死地，是因虎性陰狠，事先布局", "D": "本文可用「為虎作倀」形容蛇與虎的關係", "E": "本文旨在告誡世人：藉勢逞威，禍害必至"}, "answer": "BE", "explain": "(A)錯誤，艾子只是「采茗」時碰巧聽到虎來而觀看，沒有說他世居此山，也沒有以觀鬥為樂。(B)正確，「蛇性不馴，虎被緊纏」，蛇改不了纏繞的本性，對虎造成危害。(C)錯誤，虎是被纏得快死才「負隅聳躍」，是自保，並非陰狠預謀，「不如是，幾被纏殺」可證。(D)錯誤，「為虎作倀」是幫壞人做壞事；本文的蛇是想借虎的威勢抬高自己，比較像「狐假虎威」。(E)正確，艾子說「倚勢作威，榮施一時，終獲後災」。", "skill": "寓言題最後的評論句（艾子曰）通常就是主旨，先讀它再回頭判斷情節選項。"}], "difficulty": "易", "label": "102學測", "year": 102, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc102-ns2", "exam": "xc102", "nums": ["二"], "form": "單題", "img": "img/xc102-ns2.png", "source": "蘇轍〈上樞密韓太尉書〉", "author": "蘇轍", "genre": "書信序跋", "types": ["文意推論", "主旨寓意", "寫作手法"], "passage": "材料（甲）：轍生好為文，思之至深，以為文者氣之所形。然文不可以學而能，氣可以養而致。孟子曰：「我善養吾浩然之氣。」今觀其文章，寬厚宏博，充乎天地之間，稱其氣之小大。太史公行天下，周覽四海名山大川，與燕、趙間豪俊交游，故其文疏蕩，頗有奇氣。此二子者，豈嘗執筆學為如此之文哉？其氣充乎其中而溢乎其貌，動乎其言而見乎其文，而不自知也。\n材料（乙）：且夫人之學也，不志其大，雖多而何為？轍之來也，於山見終南、嵩、華之高，於水見黃河之大且深，於人見歐陽公，而猶以為未見太尉也。故願得觀賢人之光耀，聞一言以自壯，然後可以盡天下之大觀而無憾者矣。\n轍年少，未能通習吏事。嚮之來，非有取於斗升之祿，偶然得之，非其所樂。然幸得賜歸待選，使得優游數年之間，將歸益治其文，且學為政。太尉苟以為可教而辱教之，又幸矣。", "translation": "（甲）我天生喜歡寫文章，對此思考得很深，認為文章是「氣」的外在表現。但文章不是靠模仿學得會的，「氣」卻可以經由修養而得到。孟子說：「我善於培養我的浩然之氣。」現在看他的文章，寬厚宏大，充滿天地之間，和他的氣一樣大。司馬遷走遍天下，遍覽四海的名山大川，和燕趙一帶的豪傑交遊，所以他的文章奔放灑脫，很有奇偉之氣。這兩位，哪裡曾經拿起筆刻意學寫這樣的文章呢？是他們的氣充滿內心而流露在外貌上，表現在言語中、顯現在文章裡，自己都沒察覺。（乙）而且人求學，如果不立志於遠大，學得再多又有什麼用？我這次來京城，山看到了終南、嵩山、華山的高峻，水看到了黃河的廣大深遠，人見到了歐陽脩，卻仍覺得還沒見到太尉您。所以希望能看到賢人的風采，聽到您一句話來壯大自己，這樣才算看盡天下的壯觀而沒有遺憾了。我年紀輕，還不熟悉做官的事務。先前來京城，不是為了微薄的俸祿，偶然得到官職，也不是我所喜歡的。幸好得以回鄉等候選派，讓我能從容地過幾年，我將回去更加用功寫文章，並且學習處理政事。太尉如果認為我可以教導，願意屈尊指教，那就更是我的幸運了。", "keywords": [{"w": "氣之所形", "m": "氣的表現"}, {"w": "稱", "m": "相稱、相當"}, {"w": "疏蕩", "m": "奔放灑脫"}, {"w": "豪俊", "m": "才智出眾的人"}, {"w": "自壯", "m": "壯大自己的志氣"}, {"w": "斗升之祿", "m": "微薄的俸祿"}, {"w": "辱", "m": "謙詞，承蒙屈尊"}], "questions": [{"n": "二", "qtype": "非選", "stem": "文章分析（占18分）：閱讀框線內蘇轍〈上樞密韓太尉書〉幾段文字後，回答問題：（一）綜合材料（甲）與材料（乙），說明蘇轍提及的「養氣方法」有哪些？（二）就材料（乙）蘇轍的自述，說明材料（甲）與〈上樞密韓太尉書〉的寫作目的有何關聯？答案必須標明（一）（二）分列書寫。（一）（二）合計文長限200-250字（約9行-12行）。", "options": {}, "answer": "", "ref_answer": "（一）養氣方法有三：1.效法孟子「善養吾浩然之氣」，修養內在心性德行；2.像司馬遷一樣遊歷名山大川（蘇轍自己也看過終南、嵩、華與黃河），開拓外在見聞；3.結交豪俊賢人（司馬遷交游燕趙豪俊、蘇轍已見歐陽公），砥礪志氣、壯大學養。（二）材料（甲）先提出「文者氣之所形」「氣可以養而致」，並舉孟子、司馬遷說明養氣之道；材料（乙）接著說自己山水已見、歐陽公已見，「而猶以為未見太尉」，所以「願得觀賢人之光耀，聞一言以自壯」。可見蘇轍先談養氣，是為了帶出求見韓琦的理由：見賢人正是養氣的最後一步，藉此請求韓琦接見指教，並學習吏事。", "ref_official": true, "explain": "第（一）題要「綜合」甲乙兩段，最容易漏掉的是孟子那一項（內在修養），不能只寫遊山水、交朋友。第（二）題問寫作目的，關鍵在看出這是一封「求見信」：前面大談養氣不是空談文學理論，而是鋪陳——既然養氣要見山川、見賢人，我山川見了、歐陽公也見了，只差太尉您。把「甲的理論→乙的請求」這條線寫清楚就抓到重點。注意韓太尉是韓琦，不要寫成韓愈。", "skill": "讀書信類文章，先問「寫信的人想向收信人要什麼」，再看前面的長篇議論如何為這個請求鋪路。"}], "difficulty": "中", "label": "102學測", "year": 102, "kind": "學測", "textcat": "學術文本", "textcat2": "生活情境文本", "linked_core": ""}, {"id": "zk102-4", "exam": "zk102", "nums": [4], "form": "單題", "img": "img/zk102-4.png", "source": "李頎〈送魏萬之京〉、白居易〈錢塘湖春行〉、杜甫〈詠懷古跡〉等唐詩", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "", "translation": "", "keywords": [{"w": "砧聲", "m": "搗衣的聲音，秋天備寒衣的象徵"}, {"w": "翠華", "m": "用翠羽裝飾的旗子，代指皇帝的儀仗"}, {"w": "章臺", "m": "漢代長安街名，代指繁華之地或歌妓所在"}], "questions": [{"n": 4, "qtype": "單選", "stem": "「關城樹色催寒近」、「亂花漸欲迷人眼」、「滄海客歸珠迸淚」、「翠華想像空山裡」分別為四首詩中對仗句的上句，選出其下句依序對應正確的選項：", "options": {"A": "玉殿虛無野寺中╱章臺人去骨遺香╱御苑砧聲向晚多╱淺草纔能沒馬蹄", "B": "章臺人去骨遺香╱玉殿虛無野寺中╱淺草纔能沒馬蹄╱御苑砧聲向晚多", "C": "淺草纔能沒馬蹄╱御苑砧聲向晚多╱玉殿虛無野寺中╱章臺人去骨遺香", "D": "御苑砧聲向晚多╱淺草纔能沒馬蹄╱章臺人去骨遺香╱玉殿虛無野寺中"}, "answer": "D", "explain": "對仗句要「詞性相對、意思相關」。①「關城樹色催寒近」寫秋天寒意逼近，對「御苑砧聲向晚多」：關城對御苑，樹色對砧聲，都是秋景。②「亂花漸欲迷人眼」是白居易寫春天西湖，對「淺草纔能沒馬蹄」：亂花對淺草，迷人眼對沒馬蹄。③「滄海客歸珠迸淚」對「章臺人去骨遺香」：滄海對章臺（地點），客歸對人去，珠迸淚對骨遺香。④「翠華想像空山裡」是杜甫想像劉備當年的儀仗，對「玉殿虛無野寺中」：翠華對玉殿，空山裡對野寺中，都寫帝王遺跡的荒涼。所以依序是(D)。", "skill": "配對仗句先抓最後三個字的結構（例如「空山裡／野寺中」都是方位詞結尾），再看名詞類別是否同類。"}], "difficulty": "中", "label": "102指考", "year": 102, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk102-5", "exam": "zk102", "nums": [5], "form": "單題", "img": "img/zk102-5.png", "source": "〈燭之武退秦師〉〈岳陽樓記〉〈蘭亭集序〉〈勞山道士〉", "author": "", "genre": "其他", "types": ["字詞解釋", "文化常識"], "passage": "", "translation": "", "keywords": [{"w": "夫人", "m": "那個人"}, {"w": "騷人", "m": "原指屈原〈離騷〉一類詩人，後泛指失意文人"}, {"w": "時人", "m": "當時的人"}], "questions": [{"n": 5, "qtype": "單選", "stem": "古文中的詞語解釋，有的可以從上下文意直接判斷，有的可從文化傳統中尋思其長期累積的意義。下列屬於後者的選項是：", "options": {"A": "將〈燭之武退秦師〉：「子犯請擊之，公曰：不可。微夫人之力不及此」的「夫人」解釋為「秦伯」", "B": "將范仲淹〈岳陽樓記〉：「遷客騷人，多會於此，覽物之情，得無異乎」的「騷人」解釋為「失意文人」", "C": "將王羲之〈蘭亭集序〉：「故列敘時人，錄其所述，雖世殊事異，所以興懷，其致一也」的「時人」解釋為「參加蘭亭修禊的人」", "D": "將蒲松齡〈勞山道士〉：「乃以箸擲月中。見一美人，自光中出，初不盈尺，至地，遂與人等。纖腰秀項，翩翩作霓裳舞」的「美人」解釋為「嫦娥」"}, "answer": "B", "explain": "(B)「騷人」來自屈原〈離騷〉：屈原忠而被貶、滿懷憂愁，後世就用「騷人」指懷才不遇、心中有愁的文人，這是文化傳統長期累積出來的意思，光看〈岳陽樓記〉這一句是看不出來的。(A)看上下文就知道：晉文公不打秦國，是因為當年靠秦伯的力量才能回國即位，「夫人」指秦伯。(C)看上下文：王羲之把參加蘭亭聚會的人和他們的詩一一記錄下來，「時人」就是當時參加的人。(D)看上下文：從月亮中走出來、跳霓裳舞的美女，自然就是月中的嫦娥。", "skill": "判斷一個詞是靠上下文還是靠典故，就問自己：只讀這一段，能不能推出這個解釋？推不出來的就是靠文化傳統。"}], "difficulty": "中", "label": "102指考", "year": 102, "kind": "指考", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "燭之武退秦師、蘭亭集序、岳陽樓記、勞山道士"}, {"id": "zk102-6", "exam": "zk102", "nums": [6], "form": "單題", "img": "img/zk102-6.png", "source": "《論語》", "author": "孔子及其弟子", "genre": "經典語錄", "types": ["字詞解釋", "句意理解"], "passage": "君子學道則愛人，小人學道則易使也。", "translation": "在上位的人學了禮樂之道，就會愛護百姓；百姓學了禮樂之道，就容易聽從指揮。", "keywords": [{"w": "君子", "m": "在上位者，或有德者"}, {"w": "小人", "m": "百姓，或無德者"}, {"w": "喻", "m": "明白、了解"}, {"w": "周", "m": "團結眾人，以公義相合"}, {"w": "比", "m": "勾結、偏私"}, {"w": "泰", "m": "安詳舒泰"}], "questions": [{"n": 6, "qtype": "單選", "stem": "《論語》中「君子」與「小人」之對比，有時指上位者與下民，有時指有德者與無德者。下列與「君子學道則愛人，小人學道則易使也」中，「君子」、「小人」所指相同的選項是：", "options": {"A": "君子喻於義，小人喻於利", "B": "君子周而不比，小人比而不周", "C": "君子泰而不驕，小人驕而不泰", "D": "君子有勇而無義為亂，小人有勇而無義為盜"}, "answer": "D", "explain": "「君子學道則愛人，小人學道則易使」：學了道會「愛人」的是管理者，會「容易被使喚」的是百姓，所以這裡的君子＝上位者、小人＝百姓。(D)上位者有勇無義會「作亂」（犯上奪權），百姓有勇無義會「當強盜」，犯錯的方式不同，正是依身分地位區分，所以相同。(A)君子懂得道義、小人只懂利益；(B)君子團結而不結黨、小人結黨而不團結；(C)君子安舒而不驕傲、小人驕傲而不安舒——這三組都是用品德好壞來分，不是地位。", "skill": "看「君子／小人」指什麼，就看後面的行為：講「管人、被使喚、作亂」偏地位；講「義利、驕泰」偏品德。"}], "difficulty": "中", "label": "102指考", "year": 102, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk102-7", "exam": "zk102", "nums": [7], "form": "單題", "img": "img/zk102-7.png", "source": "〈出師表〉〈典論‧論文〉〈陋室銘〉〈漁父〉", "author": "", "genre": "其他", "types": ["文化常識", "典故出處"], "passage": "", "translation": "", "keywords": [], "questions": [{"n": 7, "qtype": "單選", "stem": "古人常有手書前人名句的習慣，下列不可能發生的選項是：", "options": {"A": "劉基手書「諮諏善道，察納雅言」", "B": "韓愈手書「蓋文章，經國之大業，不朽之盛事」", "C": "陶淵明手書「山不在高，有仙則名；水不在深，有龍則靈」", "D": "王安石手書「滄浪之水清兮，可以濯吾纓；滄浪之水濁兮，可以濯吾足」"}, "answer": "C", "explain": "關鍵是「寫字的人要比名句作者晚出生」。(C)「山不在高，有仙則名」出自唐代劉禹錫〈陋室銘〉，陶淵明是東晉人，比劉禹錫早四百多年，不可能抄寫，所以是答案。(A)「諮諏善道，察納雅言」出自三國諸葛亮〈出師表〉，劉基是明朝人，可以。(B)出自三國曹丕〈典論‧論文〉，韓愈是唐朝人，可以。(D)滄浪歌見於先秦〈漁父〉與《孟子》，王安石是宋朝人，可以。", "skill": "時代先後題：先替每個名句找作者，再把兩個人放上朝代時間線比一比。"}], "difficulty": "易", "label": "102指考", "year": 102, "kind": "指考", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "漁父、典論論文、出師表"}, {"id": "zk102-8", "exam": "zk102", "nums": [8], "form": "單題", "img": "img/zk102-8.png", "source": "屈原祠、武侯祠、孔廟楹聯及詠李白之現代詩", "author": "", "genre": "其他", "types": ["文化常識", "典故出處"], "passage": "甲、何處招魂，香草還生三戶地；當年呵壁，湘流應識九歌心\n乙、王業不偏安，兩表於今懸日月；臣言當盡瘁，六軍長此駐風雲\n丙、氣備四時，與天地日月鬼神合其德；教垂萬世，繼堯舜禹湯文武作之師", "translation": "甲：要到哪裡去招他的魂？香草仍生長在楚國的土地上；當年他對著牆壁發問（寫〈天問〉），湘江應當懂得他〈九歌〉中的心意。\n乙：漢室王業不能偏安一方，前後兩篇〈出師表〉至今像日月高懸；他說臣子應當鞠躬盡瘁，六軍的風雲氣勢長留於此。\n丙：他的氣度兼備四季，德行與天地日月鬼神相合；他的教化流傳萬世，繼承堯、舜、禹、湯、文王、武王，成為萬世的老師。", "keywords": [{"w": "招魂", "m": "〈招魂〉，楚辭篇名"}, {"w": "三戶", "m": "「楚雖三戶，亡秦必楚」，代指楚地"}, {"w": "呵壁", "m": "相傳屈原見廟壁圖畫而作〈天問〉"}, {"w": "兩表", "m": "諸葛亮前後〈出師表〉"}, {"w": "盡瘁", "m": "鞠躬盡瘁"}], "questions": [{"n": 8, "qtype": "單選", "stem": "下列文字所描繪的人物，其時代先後順序正確的選項是：甲、何處招魂，香草還生三戶地；當年呵壁，湘流應識九歌心　乙、王業不偏安，兩表於今懸日月；臣言當盡瘁，六軍長此駐風雲　丙、氣備四時，與天地日月鬼神合其德；教垂萬世，繼堯舜禹湯文武作之師　丁、你原本是一朵好看的青蓮，腳在泥中，頭頂藍天，無需潁川之水，一身紅塵已被酒精洗淨", "options": {"A": "甲丙乙丁", "B": "乙丁丙甲", "C": "丙甲乙丁", "D": "丁乙甲丙"}, "answer": "C", "explain": "先認人：甲有「招魂、香草、九歌、湘流」，是戰國楚國的屈原；乙有「兩表、盡瘁」，是三國蜀漢的諸葛亮；丙說「教垂萬世…作之師」，是春秋時的孔子（萬世師表）；丁有「青蓮、酒」，是號青蓮居士、愛喝酒的唐代李白。時代順序：孔子（春秋）→屈原（戰國）→諸葛亮（三國）→李白（唐），也就是丙甲乙丁，選(C)。", "skill": "人物聯先找「招牌關鍵詞」（作品名、別號、名言），認出人再排朝代。"}], "difficulty": "易", "label": "102指考", "year": 102, "kind": "指考", "textcat": "生活情境文本", "textcat2": "", "linked_core": ""}, {"id": "zk102-11", "exam": "zk102", "nums": [11], "form": "單題", "img": "img/zk102-11.png", "source": "《韓非子‧難二》", "author": "韓非", "genre": "經典語錄", "types": ["文意推論", "句意理解"], "passage": "齊桓公之時，晉客至，有司請禮，桓公曰「告仲父」者三。而優笑曰：「易哉為君！一曰『仲父』，二曰『仲父』。」桓公曰：「吾聞君人者勞於索人，佚於使人。吾得仲父已難矣，得仲父之後，何為不易乎哉？」", "translation": "齊桓公的時候，晉國的客人來訪，官員請示接待禮儀，桓公連說三次「去告訴仲父（管仲）」。宮中的倡優笑說：「當國君真容易啊！一說『仲父』，再說『仲父』。」桓公說：「我聽說當國君的人，辛苦在尋找人才，輕鬆在任用人才。我得到仲父已經很難了，得到仲父之後，為什麼不能輕鬆呢？」", "keywords": [{"w": "有司", "m": "主管官員"}, {"w": "優", "m": "倡優，宮中表演娛樂的藝人"}, {"w": "君人者", "m": "統治人民的人，國君"}, {"w": "索", "m": "尋求"}, {"w": "佚", "m": "同「逸」，安逸"}], "questions": [{"n": 11, "qtype": "單選", "stem": "閱讀下文，選出最適合填入＿＿中的選項：（桓公曰：「吾聞＿＿。吾得仲父已難矣，得仲父之後，何為不易乎哉？」）", "options": {"A": "我無為，而民自化", "B": "君人者勞於索人，佚於使人", "C": "為政以德，譬如北辰，居其所而眾星共之", "D": "君尊則令行，官修則有常事，法制明則民畏刑"}, "answer": "B", "explain": "空格後面說「得到仲父很難，得到之後當然輕鬆」，正好是「先難後易」兩段：找人才辛苦（勞於索人），用人才輕鬆（佚於使人），所以(B)最能銜接。(A)講國君無為、百姓自然受感化，沒有「找人很難」這一層。(C)講用德行治國、眾人自然歸向，和「找到管仲」無關。(D)講君權、官制、法令，跟用人的難易不對題。", "skill": "填空題一定要讀空格「後面」那句，它通常就是空格內容的白話解釋或例證。"}], "difficulty": "易", "label": "102指考", "year": 102, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk102-12", "exam": "zk102", "nums": [12], "form": "單題", "img": "img/zk102-12.png", "source": "《墨子‧非攻中》", "author": "墨子", "genre": "說理議論", "types": ["文意推論", "主旨寓意"], "passage": "飾攻戰者言曰：「南則荊、吳之王，北則齊、晉之君，始封於天下之時，其土城之方，未至有數百里也；人徒之眾，未至有數十萬人也。以攻戰之故，土地之博，至有數千里也；人徒之眾，至有數百萬人。故當攻戰而不可為也。」子墨子言曰：「雖四五國則得利焉，猶謂之非行道也。譬若醫之藥人之有病者然。今有醫於此，和合其祝藥之於天下之有病者而藥之，萬人食此，若醫四五人得利焉，猶謂之非行藥也。」", "translation": "替攻戰辯護的人說：「南方的楚、吳之王，北方的齊、晉之君，剛受封的時候，土地不到幾百里見方，人口不到幾十萬。因為打仗的緣故，土地擴大到幾千里，人口多到幾百萬。所以攻戰是不能不做的。」墨子說：「即使有四五個國家因此得到好處，仍然不能說這是可行的正道。就好比醫生給病人用藥。現在有個醫生，調配好他的藥給天下的病人吃，一萬個人吃了，只有四五個人治好，仍然不能說這是可以通行的好藥。」", "keywords": [{"w": "飾", "m": "粉飾，替…辯護"}, {"w": "方", "m": "見方，面積"}, {"w": "人徒", "m": "人口、民眾"}, {"w": "藥", "m": "名詞作動詞，給藥醫治"}, {"w": "行藥", "m": "可以通行使用的藥"}], "questions": [{"n": 12, "qtype": "單選", "stem": "閱讀下文，根據墨子的看法，飾攻戰者所犯錯誤最可能是：", "options": {"A": "以偏概全", "B": "損人利己", "C": "貪得無厭", "D": "顧此失彼"}, "answer": "A", "explain": "辯護者只舉楚、吳、齊、晉這四五個打仗成功的國家，就斷定「攻戰應該做」；墨子用醫生比喻反駁：一萬人吃藥只有四五人有效，不能說是好藥。意思是成功的只是極少數，不能代表全部，所以錯誤是「以偏概全」(A)。(B)損人利己、(C)貪得無厭是在批評攻戰的道德問題，但墨子這段反駁的焦點是「舉例太少、推論不當」。(D)顧此失彼是只顧一邊、忽略另一邊，和「拿少數代表多數」不同。", "skill": "比喻論證題，把比喻的數字或結構對回原論點：「萬人中四五人」＝「天下眾國中四五國」，錯在哪就很清楚。"}], "difficulty": "易", "label": "102指考", "year": 102, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk102-13", "exam": "zk102", "nums": [13, 14], "form": "題組", "img": "img/zk102-13.png", "source": "孔尚任《桃花扇‧餘韻‧哀江南》", "author": "孔尚任", "genre": "古典詩詞曲", "types": ["主旨寓意", "句意理解", "人物情感"], "passage": "俺曾見金陵玉殿鶯啼曉，秦淮水榭花開早，誰知道容易冰消！眼看他起朱樓，眼看他宴賓客，眼看他樓塌了！這青苔碧瓦堆，俺曾睡風流覺，將五十年興亡看飽。那烏衣巷不姓王，莫愁湖鬼夜哭，鳳凰臺棲梟鳥。殘山夢最真，舊境丟難掉，不信這輿圖換稿！謅一套〈哀江南〉，放悲聲唱到老。", "translation": "我曾見過南京宮殿裡清晨黃鶯啼叫，秦淮河邊的水榭花開得早，誰知道這一切這麼容易就像冰一樣消融！眼看著他蓋起紅樓，眼看著他大宴賓客，眼看著他樓塌了！這長滿青苔的碎瓦堆，我曾在這裡過著風流快活的日子，五十年來的興亡盛衰都看盡了。那烏衣巷已不再屬於王家，莫愁湖邊鬼魂夜裡哭泣，鳳凰臺上棲息著惡鳥。殘破的山河在夢裡最真切，舊日的情景丟也丟不掉，不敢相信這國家的版圖已經改換！隨口編一套〈哀江南〉，放聲悲歌唱到老。", "keywords": [{"w": "冰消", "m": "像冰一樣消融，比喻迅速消失"}, {"w": "烏衣巷不姓王", "m": "東晉王、謝大族住在烏衣巷，此指豪門不再"}, {"w": "梟鳥", "m": "惡鳥，象徵不祥或小人當道"}, {"w": "輿圖換稿", "m": "地圖改畫，指改朝換代"}, {"w": "謅", "m": "隨口編造"}], "questions": [{"n": 13, "qtype": "單選", "stem": "關於上文的主旨，敘述正確的選項是：", "options": {"A": "天下興亡，匹夫有責，誓圖光復山河", "B": "天道循環，無往不復，不必悲傷痛哭", "C": "作舊地之遊，悔風流之事，興奮勵之志", "D": "話興衰之感，抒亡國之痛，訴故國之思"}, "answer": "D", "explain": "曲中從「眼看他起朱樓…樓塌了」寫盛衰無常，「不信這輿圖換稿」寫明朝滅亡的沉痛，「舊境丟難掉」「放悲聲唱到老」寫對故國的思念，正是(D)。(A)全曲只有哀嘆，沒有發誓要光復的行動。(B)結尾是「放悲聲唱到老」，明明悲痛得很，不是看開。(C)「俺曾睡風流覺」是回憶過去，不是懊悔，也沒有振作奮發的意思。", "skill": "主旨題看最後一兩句的情緒：「放悲聲唱到老」是悲，凡是說「不必悲傷」「奮發」的都可以先刪。"}, {"n": 14, "qtype": "單選", "stem": "關於上文的文句，詮釋正確的選項是：", "options": {"A": "俺曾睡風流覺：我曾在此快活的玩樂，喻自在如昔，足堪安慰", "B": "鳳凰臺棲梟鳥：惡鳥棲息於鳳凰臺上，喻哲人已遠，觸景傷懷", "C": "殘山夢最真：雖然只有殘山剩水，風景卻如夢如幻，真是美麗", "D": "不信這輿圖換稿：難以相信這故國河山，竟輕易落入他人之手"}, "answer": "D", "explain": "(D)正確：「輿圖」是地圖，「換稿」是改畫，地圖換了就是國家易主，「不信」寫出難以接受。(A)錯：「曾」睡風流覺是過去的快樂，如今只剩青苔碎瓦，是今昔對比的感傷，不是「自在如昔」。(B)錯：鳳凰是祥鳥、梟是惡鳥，鳳凰臺住了梟鳥，是比喻世道衰敗、景物荒涼，不是懷念哲人。(C)錯：「殘山」是殘破的江山，「夢最真」是說只有夢裡的舊時江山最真切，充滿亡國的痛，不是讚美風景。", "skill": "曲文裡的「曾」「舊」都暗示今昔對比，詮釋時要想到「現在已經沒有了」。"}], "difficulty": "中", "label": "102指考", "year": 102, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk102-15", "exam": "zk102", "nums": [15, 16], "form": "題組", "img": "img/zk102-15.png", "source": "辛文房《唐才子傳》", "author": "辛文房", "genre": "說理議論", "types": ["字詞解釋", "文意推論", "文化常識"], "passage": "能言者未必能行，能行者未必能言。觀李、杜二公，崎嶇板蕩之際，語語王霸，褒貶得失。忠孝之心，驚動千古。騷雅之妙，雙振當時。兼眾善於無今，集大成於往作。歷世之下，想見風塵。惜乎長轡未騁，奇才並屈，竹帛少色，徒列空言，嗚呼哀哉！昔謂杜之典重，李之飄逸，神聖之際，二公造焉。觀於海者難為水，遊李、杜之門者難為詩。斯言信哉。", "translation": "會說的人不一定能做，能做的人不一定會說。看李白、杜甫兩人，在動盪亂世之中，句句談論王道霸業，評論政治得失。他們忠君孝親的心，震動千古；詩歌的精妙，兩人同時在當代大放光彩。他們兼有前所未有的各種優點，集前人作品之大成。後世的人讀他們的詩，彷彿還能看見他們奔走風塵的樣子。可惜他們沒有機會施展抱負，奇才都受到委屈，史冊上缺少他們的功業，只留下空洞的言論，真令人哀嘆！從前人說杜甫的詩典雅莊重，李白的詩飄逸灑脫，達到神妙聖境，兩人都到達了。看過大海的人，很難再被別的水吸引；在李杜門下學過的人，很難再寫別的詩。這話真是可信啊。", "keywords": [{"w": "板蕩", "m": "《詩經》篇名，代指政局動亂"}, {"w": "王霸", "m": "王道與霸道，指治國之道"}, {"w": "騷雅", "m": "〈離騷〉與〈大雅〉〈小雅〉，代指詩歌"}, {"w": "長轡未騁", "m": "長長的韁繩沒能放開奔馳，比喻抱負未能施展"}, {"w": "竹帛", "m": "史冊"}, {"w": "造", "m": "到達"}], "questions": [{"n": 15, "qtype": "單選", "stem": "文中「昔謂杜之□□，李之□□」，依次填入的字詞，最恰當的選項是：", "options": {"A": "典重／飄逸", "B": "婉約／豪放", "C": "輕豔／奇詭", "D": "儒緩／清新"}, "answer": "A", "explain": "杜甫的詩沉鬱頓挫、用字嚴謹、內容厚重，稱「典重」；李白的詩想像奔放、灑脫不羈，稱「飄逸」，(A)正確。(B)「婉約／豪放」是宋詞兩大派別的說法，而且杜甫並不婉約。(C)「輕豔」不符合杜甫憂國憂民的風格，「奇詭」較像李賀。(D)「儒緩」不是杜詩的特色。", "skill": "作家風格題記住招牌標籤：杜甫沉鬱、典重；李白豪放、飄逸。"}, {"n": 16, "qtype": "單選", "stem": "下列關於文意的解釋，正確的選項是：", "options": {"A": "作者認為李、杜既是「能言」者，又擁有「能行」的機遇", "B": "「騷雅之妙」意指李、杜的作品，全屬〈離騷〉典雅風格", "C": "「竹帛少色」意指李、杜名垂青史，其他詩人則相形失色", "D": "「觀於海者難為水」意指李、杜詩作傑出，他人難以超越"}, "answer": "D", "explain": "(D)正確：看過大海的人很難再欣賞小水，比喻見過李杜的詩，別人的詩就很難入眼，代表李杜成就極高、難以超越。(A)錯：「長轡未騁，奇才並屈」說他們空有才能卻沒有施展的機會，只是「能言」，沒有「能行」的機遇。(B)錯：「騷雅」是用〈離騷〉和《詩經》的雅泛指詩歌，不是說作品全是〈離騷〉風格。(C)錯：「竹帛少色」是史冊上缺少他們政治功業的光彩，帶著惋惜，不是說別的詩人失色。", "skill": "看到「惜乎」「嗚呼哀哉」這類惋惜語，前後的詞多半是負面的（沒做成、沒機會），別讀成稱讚。"}], "difficulty": "中", "label": "102指考", "year": 102, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk102-17", "exam": "zk102", "nums": [17], "form": "單題", "img": "img/zk102-17.png", "source": "王鐸〈臨閣帖‧題末〉", "author": "王鐸", "genre": "書信序跋", "types": ["文意推論", "典故出處"], "passage": "書學以師古為第一義。近世書家以臆騁，動無法度，如射不掛鵠，琴不按譜，如是亦何難之有！變化從心，從心不踰，嗚呼！難之矣。近世詩與古文亦然，此可以驚河伯，不足以當海若也！崇禎十二年六月，嵩山樵者王鐸臨古，因題於末，以俟相知如何。", "translation": "學書法要把效法古人當作第一要務。近代的書法家任憑自己的想法揮灑，動不動就不守法度，就像射箭不掛靶子、彈琴不照琴譜，這樣有什麼困難的！變化隨心所欲，又能隨心所欲而不越出規矩，唉！這才難啊。近代的詩和古文也是這樣，這種作品只能讓河伯驚嘆，卻比不上海神。崇禎十二年六月，嵩山樵者王鐸臨摹古帖，順便題寫在後面，等待知音來評斷如何。", "keywords": [{"w": "師古", "m": "以古人為師"}, {"w": "以臆騁", "m": "任憑主觀想法馳騁"}, {"w": "鵠", "m": "箭靶的中心"}, {"w": "從心不踰", "m": "隨心所欲而不越出法度，化用《論語》「從心所欲，不踰矩」"}, {"w": "河伯／海若", "m": "黃河之神／北海之神，出自《莊子‧秋水》，比喻小與大"}], "questions": [{"n": 17, "qtype": "單選", "stem": "閱讀下文，選出不符合文意的選項：", "options": {"A": "作者認為近世書家不受法度限制，求新求變，精神值得肯定", "B": "作者臨古之後，認為書法與詩文創作，應以學習古人為優先", "C": "「可以驚河伯，不足以當海若」，是指雖有小成，但境界不高", "D": "作者認為書法創作任意變化，卻不失法度，此一境界很難達到"}, "answer": "A", "explain": "(A)不符合：作者把近世書家「動無法度」比作射箭不掛靶、彈琴不照譜，還說「這有什麼難的」，明顯是批評，不是肯定。(B)符合：開頭就說「書學以師古為第一義」，又說詩文也是這樣。(C)符合：《莊子‧秋水》中河伯自以為了不起，見到大海才知道自己渺小，借指近世作品只能唬唬見識淺的人，境界不高。(D)符合：「變化從心，從心不踰，嗚呼！難之矣」，隨心變化又不越規矩，是很難的境界。", "skill": "判斷作者態度，看他用的比喻是褒是貶：「射不掛鵠、琴不按譜」都是亂來，態度就是否定。"}], "difficulty": "易", "label": "102指考", "year": 102, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk102-19", "exam": "zk102", "nums": [19], "form": "單題", "img": "img/zk102-19.png", "source": "多篇古文（〈過秦論〉、《韓非子》、〈馮諼客孟嘗君〉、《老子》、〈諫逐客書〉等）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "", "translation": "", "keywords": [{"w": "弱", "m": "弱小"}, {"w": "姦", "m": "觸犯／奸邪"}, {"w": "食", "m": "給…吃"}, {"w": "為", "m": "是／做"}, {"w": "服", "m": "歸服／佩帶"}], "questions": [{"n": 19, "qtype": "多選", "stem": "下列各組文句「」內的字，前後意義相同的選項是：", "options": {"A": "「弱」國入朝／天下非小「弱」也", "B": "罰加乎「姦」令／「姦」臣猶有所譎其辭", "C": "「食」以草具／「食」之，比門下之魚客", "D": "天下皆知美之「為」美／生而不有，「為」而不恃", "E": "百姓樂用，諸侯親「服」／「服」太阿之劍，乘纖離之馬"}, "answer": "AC", "explain": "(A)相同：都是「弱小」。弱小的國家來朝見；天下並沒有變小變弱（都出自〈過秦論〉）。(C)相同：都讀ㄙˋ，「給…吃」。拿粗劣的食物給馮諼吃；給他吃（魚），比照門下吃魚的食客（〈馮諼客孟嘗君〉）。(B)不同：「罰加乎姦令」的姦是「觸犯」（處罰加在觸犯法令的人身上）；「姦臣」的姦是「奸邪」。(D)不同：「美之為美」的為是「是、作為」；「為而不恃」的為是「做事」（做了事也不仗恃）。(E)不同：「諸侯親服」的服是「歸服、順服」；「服太阿之劍」的服是「佩帶」（〈諫逐客書〉）。", "skill": "一字多義題把字換成候選白話詞（是／做、歸服／佩帶）帶回句子，兩邊都通的才是相同。"}], "difficulty": "中", "label": "102指考", "year": 102, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "諫逐客書、馮諼客孟嘗君"}, {"id": "zk102-21", "exam": "zk102", "nums": [21], "form": "單題", "img": "img/zk102-21.png", "source": "多篇古文（〈鴻門宴〉〈馮諼客孟嘗君〉〈師說〉〈訓儉示康〉〈廉恥〉）", "author": "", "genre": "其他", "types": ["虛詞句式", "句意理解"], "passage": "", "translation": "", "keywords": [{"w": "庸", "m": "豈、哪裡"}, {"w": "忍", "m": "忍心"}, {"w": "其", "m": "豈、難道（表反詰）"}], "questions": [{"n": 21, "qtype": "多選", "stem": "「反問」雖採問句形式，卻屬無疑而問、明知故問，意在強調預設的觀點。下列屬於反問句的選項是：", "options": {"A": "壯士，能復飲乎", "B": "誰習計會，能為文收責於薛者乎", "C": "吾師道也，夫庸知其年之先後生於吾乎", "D": "風俗頹敝如是，居位者雖不能禁，忍助之乎", "E": "況為大臣而無所不取，無所不為，則天下其有不亂，國家其有不亡者乎"}, "answer": "CDE", "explain": "(C)〈師說〉：我學的是道，哪裡需要知道他比我早生還晚生呢？答案是「不必知道」，反問。(D)〈訓儉示康〉：風氣敗壞成這樣，當官的就算不能禁止，難道忍心助長嗎？答案是「不該」，反問。(E)〈廉恥〉：大臣什麼都拿、什麼都做，天下哪有不亂、國家哪有不亡的？答案是「一定亂、一定亡」，反問。(A)〈鴻門宴〉項羽真的在問樊噲還能不能再喝，樊噲也回答了，是真正的詢問。(B)〈馮諼客孟嘗君〉孟嘗君真的在問誰懂會計、能去薛地收債，是詢問句。", "skill": "判斷反問：把問句改成肯定或否定的陳述句，意思不變而且語氣更強，就是反問；需要對方回答的才是真問。"}], "difficulty": "易", "label": "102指考", "year": 102, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "馮諼客孟嘗君、鴻門宴、師說、廉恥"}, {"id": "zk102-23", "exam": "zk102", "nums": [23], "form": "單題", "img": "img/zk102-23.png", "source": "蘇軾〈念奴嬌〉、辛棄疾〈青玉案〉〈賀新郎〉〈永遇樂〉、蘇軾〈洞仙歌〉", "author": "蘇軾、辛棄疾", "genre": "古典詩詞曲", "types": ["詩詞賞析", "典故出處", "人物情感"], "passage": "", "translation": "", "keywords": [{"w": "公瑾", "m": "周瑜"}, {"w": "將軍百戰身名裂", "m": "指李陵兵敗降匈奴、身敗名裂"}, {"w": "河梁", "m": "橋，借指送別（李陵送蘇武）"}, {"w": "易水", "m": "荊軻刺秦前在易水告別"}, {"w": "元嘉草草", "m": "南朝宋文帝元嘉年間草率北伐"}, {"w": "廉頗老矣，尚能飯否", "m": "作者借老將廉頗自比"}], "questions": [{"n": 23, "qtype": "多選", "stem": "下列詞作，藉歷史人物寄託作者情懷的選項是：", "options": {"A": "遙想公瑾當年，小喬初嫁了，雄姿英發。羽扇綸巾，談笑間，強虜灰飛煙滅", "B": "東風夜放花千樹。更吹落，星如雨。寶馬雕車香滿路。鳳簫聲動，玉壺光轉，一夜魚龍舞", "C": "試問夜如何？夜已三更，金波淡，玉繩低轉。但屈指西風幾時來，又不道，流年暗中偷換", "D": "將軍百戰身名裂。向河梁，回頭萬里，故人長絕。易水蕭蕭西風冷，滿座衣冠似雪。正壯士，悲歌未徹", "E": "元嘉草草，封狼居胥，贏得倉皇北顧。四十三年，望中猶記，烽火揚州路。可堪回首，佛狸祠下，一片神鴉社鼓。憑誰問，廉頗老矣，尚能飯否"}, "answer": "ADE", "explain": "(A)蘇軾〈念奴嬌‧赤壁懷古〉：寫周瑜年輕得志、談笑破敵，對照自己年老無成，寄託感慨。(D)辛棄疾〈賀新郎〉：用李陵別蘇武、荊軻易水訣別的故事，寄託與親人離別的悲壯之情。(E)辛棄疾〈永遇樂‧京口北固亭懷古〉：用宋文帝草率北伐失敗提醒當朝，又以廉頗自比，抒發老而不被重用的悲憤。(B)辛棄疾〈青玉案‧元夕〉這幾句寫元宵燈火、車馬、歌舞的熱鬧景象，沒有歷史人物。(C)蘇軾〈洞仙歌〉這幾句寫夏夜等待秋風、感嘆時光暗中流逝，選段中沒有出現歷史人物。", "skill": "先圈出選項裡的人名或典故（公瑾、將軍、易水、廉頗），沒有任何人物的直接刪除。"}], "difficulty": "中", "label": "102指考", "year": 102, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk102-24", "exam": "zk102", "nums": [24], "form": "單題", "img": "img/zk102-24.png", "source": "劉義慶《宣驗記‧鸚鵡滅火》", "author": "劉義慶", "genre": "寓言故事", "types": ["文意推論", "主旨寓意", "人物情感"], "passage": "有鸚鵡飛集他山，山中禽獸輒相愛重。鸚鵡自念：雖樂不可久也，便去。後數月，山中大火，鸚鵡遙見，便入水沾羽，飛而灑水。天神言：「汝雖有志意，何足云也？」對曰：「雖知不能救，然嘗僑居是山，禽獸行善，皆為兄弟，不忍見耳。」天神感應，即為滅火。", "translation": "有一隻鸚鵡飛到別的山上，山中的禽獸都很愛護敬重牠。鸚鵡心想：這裡雖然快樂，卻不能久留，就離開了。幾個月後，那座山發生大火，鸚鵡遠遠看見，就飛進水裡沾濕羽毛，飛到山上灑水。天神說：「你雖然有這份心意，但這點水哪值得一提呢？」鸚鵡回答：「我雖然知道救不了，但我曾經寄住在這座山，山中禽獸待我很好，都像兄弟一樣，我不忍心看著牠們受難啊。」天神受到感動，就替牠把火滅了。", "keywords": [{"w": "集", "m": "停棲"}, {"w": "愛重", "m": "愛護敬重"}, {"w": "何足云也", "m": "哪裡值得一提"}, {"w": "僑居", "m": "寄居"}, {"w": "行善", "m": "待人友善"}], "questions": [{"n": 24, "qtype": "多選", "stem": "閱讀下列小說，選出符合文意的選項：", "options": {"A": "「雖樂不可久也」意謂鸚鵡預知山中將有災禍", "B": "「入水沾羽，飛而灑水」歌詠鸚鵡的渴望自由", "C": "「汝雖有志意，何足云也」贊許鸚鵡的不屈不撓", "D": "「禽獸行善，皆為兄弟」呈現鸚鵡對山中禽獸的感恩", "E": "作者描述了「不忍」以及「知其不可而為之」的精神"}, "answer": "DE", "explain": "(D)符合：鸚鵡說山中禽獸待牠好、像兄弟一樣，所以不忍心，是感恩回報。(E)符合：「不忍見耳」是不忍之心；「雖知不能救」還去灑水，正是明知做不到仍然去做。(A)不符：「樂不可久」只是覺得寄人籬下不宜久留，文中沒有說牠預知火災。(B)不符：沾水灑水是為了救火，和自由無關。(C)不符：天神這句是說「你的心意雖好，但那點水哪有用」，是質疑，不是讚許。", "skill": "小說題把每個引句放回情節中的「說話者與目的」：天神說的話是質疑，鸚鵡的回答才是主旨。"}], "difficulty": "易", "label": "102指考", "year": 102, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc103-3", "exam": "xc103", "nums": [3], "form": "單題", "img": "img/xc103-3.png", "source": "古典詩四首（出處待查）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "(A)一夜清風動扇愁，背時容色入新秋。桃花眼裡汪汪淚，忍到更深枕上流\n(B)每坐臺前見玉容，今朝不與昨朝同。良人一夜出門宿，減卻桃花一半紅\n(C)淺色桃花亞短牆，不因風送也聞香。凝情盡日君知否，還似紅兒淡薄妝\n(D)暮春三月日重三，春水桃花滿禊潭。廣樂逶迤天上下，仙舟搖衍鏡中酣", "translation": "(A)一夜秋風吹動團扇，令人發愁，失寵的容顏進入新秋；桃花般的眼裡淚水汪汪，忍到深夜才在枕上流下。(B)每次坐在鏡臺前看自己的容貌，今天和昨天不一樣了；丈夫一夜在外過夜，臉上桃花般的紅潤就減了一半。(C)淺色的桃花低垂在矮牆邊，不用風吹也聞得到香；整天凝神含情，你知道嗎？就像紅兒淡淡的妝容。(D)暮春三月初三這天，春水和桃花布滿了修禊的水潭；盛大的音樂迴盪天地之間，仙舟在如鏡的水面搖盪，令人沉醉。", "keywords": [{"w": "背時", "m": "失時、失寵"}, {"w": "良人", "m": "丈夫"}, {"w": "亞", "m": "通「壓」，低垂"}, {"w": "日重三", "m": "三月三日，上巳節"}, {"w": "禊", "m": "古代在水邊洗濯以除災的祭祀"}], "questions": [{"n": 3, "qtype": "單選", "stem": "桃花因顏色鮮豔美麗，故詩人常藉以比喻美麗的女子。下列詩歌中的桃花，不具此喻意的選項是：", "options": {"A": "一夜清風動扇愁，背時容色入新秋。桃花眼裡汪汪淚，忍到更深枕上流", "B": "每坐臺前見玉容，今朝不與昨朝同。良人一夜出門宿，減卻桃花一半紅", "C": "淺色桃花亞短牆，不因風送也聞香。凝情盡日君知否，還似紅兒淡薄妝", "D": "暮春三月日重三，春水桃花滿禊潭。廣樂逶迤天上下，仙舟搖衍鏡中酣"}, "answer": "D", "explain": "看桃花跟「女子」有沒有連結。(A)「桃花眼」指女子美麗的眼睛，正在流淚，是比喻女子。(B)「減卻桃花一半紅」指女子臉上的紅潤（桃花般的容顏）因丈夫外宿而消減，是比喻女子。(C)淺色桃花「還似紅兒淡薄妝」，把桃花比作女子淡妝，是比喻女子。(D)寫三月三日上巳節，春水桃花滿布修禊的水潭，桃花只是節令景物，沒有比喻女子，所以選(D)。", "skill": "判斷意象有無比喻義：看詩中是否有「人」可對應（眼、容、妝、良人），只有景物沒有人物時，多半只是寫景。"}], "difficulty": "易", "label": "103學測", "year": 103, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc103-4", "exam": "xc103", "nums": [4], "form": "單題", "img": "img/xc103-4.png", "source": "余光中《青青邊愁》（選項引杜甫、古詩十九首、李白、《論語》）", "author": "余光中", "genre": "古典詩詞曲", "types": ["主旨寓意", "比較閱讀"], "passage": "(A)筆落驚風雨，詩成泣鬼神\n(B)不惜歌者苦，但傷知音稀\n(C)屈平詞賦懸日月，楚王臺榭空山丘\n(D)詩可以興，可以觀，可以群，可以怨", "translation": "(A)下筆時能驚動風雨，詩寫成了能讓鬼神哭泣。(B)不憐惜唱歌的人多辛苦，只傷心懂得歌聲的知音太少。(C)屈原的辭賦像日月一樣高懸不朽，楚王的樓臺宮殿卻早已成為空蕩的山丘。(D)讀詩可以激發情志，可以觀察社會風俗，可以和眾人交流相處，可以抒發怨情。", "keywords": [{"w": "屈平", "m": "屈原，名平"}, {"w": "臺榭", "m": "樓臺亭榭，代指權勢富貴"}, {"w": "興", "m": "引發聯想、感發情志"}], "questions": [{"n": 4, "qtype": "單選", "stem": "閱讀下文，選出最接近其意旨的選項：堅信一首詩的沉默比所有的擴音器加起來更清晰，比機槍的口才野砲的雄辯更持久。堅信文字的冰庫能冷藏最燙的激情最新鮮的想像。時間，你帶得走歌者帶不走歌。（余光中《青青邊愁》）", "options": {"A": "筆落驚風雨，詩成泣鬼神", "B": "不惜歌者苦，但傷知音稀", "C": "屈平詞賦懸日月，楚王臺榭空山丘", "D": "詩可以興，可以觀，可以群，可以怨"}, "answer": "C", "explain": "余光中的重點是：詩比喧囂的宣傳、武力（擴音器、機槍、野砲）更持久，詩人會死但作品永存（帶得走歌者帶不走歌）。(C)屈原的作品像日月長存，楚王的權勢宮殿卻化為山丘，正是「文學永恆、權勢短暫」，最接近。(A)講詩的感染力很強，沒有「比權力持久」的對比。(B)講知音難遇的寂寞。(D)講詩的功用，都不合。", "skill": "找意旨先抓原文的對比結構（詩 vs 擴音器、機槍；歌 vs 歌者），再找選項中有同樣對比的。"}], "difficulty": "易", "label": "103學測", "year": 103, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc103-6", "exam": "xc103", "nums": [6], "form": "單題", "img": "img/xc103-6.png", "source": "《河南程氏遺書》", "author": "程顥、程頤", "genre": "說理議論", "types": ["文意推論"], "passage": "四凶之才皆可用。堯之時，聖人在上，皆以其才任大位，而不敢露其不善之心。堯非不知其不善也，伏則聖人亦不得而誅之。及堯舉舜於匹夫之中而禪之位，則是四人者始懷憤怨不平之心而顯其惡，故舜得以因其跡而誅竄之也。", "translation": "四凶的才能都是可以用的。堯在位時，有聖人在上，四凶都憑才能擔任高位，而不敢顯露他們不善的心。堯並不是不知道他們不善，只是惡念潛藏著沒有表現出來，聖人也不能去懲罰他們。等到堯從平民中提拔舜並把帝位讓給他，這四個人才開始心懷憤恨不平而顯露惡行，所以舜才能根據他們的惡跡把他們誅殺或流放。", "keywords": [{"w": "四凶", "m": "相傳堯舜時代四個惡名昭彰的部族首領"}, {"w": "伏", "m": "隱藏"}, {"w": "禪", "m": "讓位"}, {"w": "因", "m": "依據"}, {"w": "竄", "m": "放逐"}], "questions": [{"n": 6, "qtype": "單選", "stem": "閱讀下文，選出敘述正確的選項：", "options": {"A": "堯知四凶不善，故意授以大位，使四凶彼此制衡", "B": "堯不因人有不善之心，即對其才幹能力全盤否定", "C": "舜得位後，四凶遭貶斥而懷恨，心性遂由善轉惡", "D": "舜認為心懷惡念者，縱無惡行表露，仍不可寬貸"}, "answer": "B", "explain": "(B)正確：堯知道四凶心不善，但因為他們「才皆可用」又沒有露出惡行，仍讓他們任大位，不因心不善就否定才能。(A)錯誤：堯用他們是因為有才，文中沒有「故意讓他們互相制衡」的說法。(C)錯誤：四凶的不善之心本來就有，只是先前不敢露；他們懷恨是因為舜從平民被拔擢而接位，並非先遭貶斥才由善轉惡。(D)錯誤：舜是「因其跡」（根據已顯露的惡行）才懲處，若沒有惡行，「伏則聖人亦不得而誅之」，正好相反。", "skill": "推論題要分清「心」與「跡」：文中強調只有顯露出來的惡行才能懲處，用這個標準檢查每個選項。"}], "difficulty": "中", "label": "103學測", "year": 103, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc103-7", "exam": "xc103", "nums": [7], "form": "單題", "img": "img/xc103-7.png", "source": "吟詠鄭成功對聯二副", "author": "", "genre": "其他", "types": ["文化常識", "典故出處"], "passage": "東海望臺澎，風景不殊，舉目有河山之異；南天留祠宇，雄圖雖渺，稱名則婦孺皆知。\n四鎮多貳心，兩島屯師，敢向東南爭半壁；諸王無寸土，一隅抗志，方知海外有孤忠。", "translation": "第一副：從東海遙望臺灣、澎湖，風景和從前沒有兩樣，抬眼卻有山河易主的感慨；南方留下了他的祠廟，宏大的志業雖已渺茫，提起他的名字連婦人小孩都知道。第二副：明末四鎮將領大多懷有二心，他卻在金門、廈門兩島屯兵，敢向東南爭奪半壁江山；明朝宗室諸王已失去寸土，他在一隅之地堅持抗清的志向，這才知道海外還有孤臣忠心。", "keywords": [{"w": "風景不殊", "m": "風景沒有不同，典出《世說新語》新亭對泣「風景不殊，正自有山河之異」"}, {"w": "祠宇", "m": "祠廟"}, {"w": "貳心", "m": "不忠、異心"}, {"w": "孤忠", "m": "孤臣的忠心"}], "questions": [{"n": 7, "qtype": "單選", "stem": "右圖是兩副吟詠鄭成功的對聯，請依文意與對聯組成原則，選出最適合的選項：甲、方知海外有孤忠　乙、稱名則婦孺皆知　丙、敢向東南爭半壁　丁、舉目有河山之異（對聯：東海望臺澎，風景不殊，①／南天留祠宇，雄圖雖渺，②／四鎮多貳心，兩島屯師，③／諸王無寸土，一隅抗志，④）", "options": {"A": "①丙②甲③丁④乙", "B": "①丙②乙③丁④甲", "C": "①丁②甲③丙④乙", "D": "①丁②乙③丙④甲"}, "answer": "D", "explain": "①「風景不殊」直接聯想到《世說新語》「風景不殊，正自有山河之異」，接丁「舉目有河山之異」。②「雄圖雖渺」（志業雖未成）用「雖」轉折，接乙「稱名則婦孺皆知」（名聲仍流傳）；丁對乙也工整（舉目／稱名，河山之異／婦孺皆知）。③「四鎮多貳心，兩島屯師」寫別人懷二心而鄭成功屯兵抗爭，接丙「敢向東南爭半壁」。④「諸王無寸土，一隅抗志」寫在孤島堅持，接甲「方知海外有孤忠」；丙、甲也成對（敢向／方知，東南／海外，爭半壁／有孤忠）。再看上聯末字仄（異、壁）、下聯末字平（知、忠），完全符合，選(D)。", "skill": "對聯題先找典故或關聯詞（風景不殊、雖），再檢查兩兩對仗與「上仄下平」。"}], "difficulty": "中", "label": "103學測", "year": 103, "kind": "學測", "textcat": "生活情境文本", "textcat2": "", "linked_core": ""}, {"id": "xc103-12", "exam": "xc103", "nums": [12, 13], "form": "題組", "img": "img/xc103-12.png", "source": "蒲松齡《聊齋誌異‧鴝鵒》", "author": "蒲松齡", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "王汾濱言：其鄉有養八哥者，教以語言，甚狎習，出遊必與之俱，相將數年矣。一日，將過絳州，去家尚遠，而資斧已罄。其人愁苦無策。鳥云：「何不售我？送我王邸，當得善價，不愁歸路無貲也。」其人云：「我安忍！」鳥言：「不妨。主人得價疾行，待我城西二十里大樹下。」其人從之。攜至城，相問答，觀者漸眾。有中貴見之，聞諸王。王召入，欲買之。其人曰：「小人相依為命，不願賣。」王問鳥：「汝願住否？」答言：「願住。」王喜。鳥又言：「給價十金，勿多予。」王益喜，立畀十金。其人故作懊恨狀而出。王與鳥語，應對便捷。呼肉啖之。食已，鳥曰：「臣要浴。」王命金盆貯水，開籠令浴。浴已，飛簷間，梳翎抖羽，尚與王喋喋不休。頃之，羽燥，翩躚而起。操晉聲曰：「臣去呀！」顧盼已失所在。王及內侍，仰面咨嗟，急覓其人，則已渺矣。後有往秦中者，見其人攜鳥在西安市上。", "translation": "王汾濱說：他的家鄉有個養八哥的人，教牠說話，人鳥非常親近，出遊一定帶著牠，相伴好幾年了。有一天，將要經過絳州，離家還很遠，盤纏卻已用光。這人愁苦得沒辦法。鳥說：「為什麼不賣了我？把我送到王府，一定能賣個好價錢，就不愁回家沒路費了。」那人說：「我怎麼忍心！」鳥說：「沒關係。主人拿到錢就快走，在城西二十里的大樹下等我。」那人照做。帶到城裡，人和鳥一問一答，圍觀的人越來越多。有個太監看到了，報告給王。王召他們進府，想買下鳥。那人說：「小人和牠相依為命，不願意賣。」王問鳥：「你願意留下嗎？」鳥回答：「願意留下。」王很高興。鳥又說：「給十兩銀子就好，不要多給。」王更高興了，立刻給了十兩。那人故意裝出懊惱悔恨的樣子離開。王和鳥說話，鳥應對敏捷。王叫人拿肉給牠吃。吃完，鳥說：「臣要洗澡。」王命人用金盆裝水，打開籠子讓牠洗。洗完，牠飛到屋簷間，梳理羽毛、抖動翅膀，還和王說個不停。過了一會兒，羽毛乾了，便輕快地飛起，用山西口音說：「臣走啦！」轉眼就不見了。王和侍從仰著臉嘆息，急忙去找那個人，早已不見蹤影。後來有人到陝西，看見那人帶著鳥在西安的市集上。", "keywords": [{"w": "狎習", "m": "親近熟悉"}, {"w": "資斧", "m": "旅費、盤纏"}, {"w": "罄", "m": "用盡"}, {"w": "貲", "m": "錢財"}, {"w": "中貴", "m": "宮中有權勢的宦官"}, {"w": "畀", "m": "交給"}, {"w": "翩躚", "m": "輕快飛舞的樣子"}], "questions": [{"n": 12, "qtype": "單選", "stem": "關於本篇故事內容，敘述正確的選項是：", "options": {"A": "八哥的主人因缺旅費，打算出售八哥", "B": "八哥擬另謀棲身之處，設局誆騙主人", "C": "八哥與主人合謀，利用賣身詐取錢財", "D": "八哥與主人得手後，在西安故技重施"}, "answer": "C", "explain": "(C)正確：八哥主動提議「何不售我」，並約好「待我城西二十里大樹下」，再趁洗澡飛走，是兩者合謀騙取王的錢。(A)錯誤：主人原本「愁苦無策」，聽到八哥提議還說「我安忍」，並沒有打算出售。(B)錯誤：八哥最後飛回主人身邊，沒有另謀棲身、也沒有騙主人。(D)錯誤：結尾只說有人看見他「攜鳥在西安市上」，沒有說他們再騙一次。", "skill": "選項中「打算」「故技重施」這類推測詞，要回原文確認有沒有直接證據。"}, {"n": 13, "qtype": "單選", "stem": "下列關於故事的解釋，錯誤的選項是：", "options": {"A": "主人將八哥「攜至城，相問答」，係為製造奇觀引人注意", "B": "八哥對王言「給價十金，勿多予」，有助於取得王的信任", "C": "主人「故作懊恨狀」，目的是為了讓八哥相信他萬分不捨", "D": "八哥「尚與王喋喋不休」，係為讓王疏於防備，以便逃走"}, "answer": "C", "explain": "(A)正確：在城裡和鳥一問一答，「觀者漸眾」，終於驚動王府，是故意製造話題。(B)正確：鳥替王著想要他少給錢，「王益喜」，讓王覺得牠真心想留下。(C)錯誤：主人和八哥本來就是同謀，不需要演給八哥看；「故作」懊恨是演給王看，讓王相信他真的捨不得賣，不起疑心。(D)正確：飛到屋簷後還和王說個不停，讓王以為牠不會走，等羽毛乾了再飛走。", "skill": "分析「故作」「假裝」的動作，要問：這場戲是演給誰看的？觀眾是誰，目的就跟誰有關。"}], "difficulty": "易", "label": "103學測", "year": 103, "kind": "學測", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "勞山道士"}, {"id": "xc103-14", "exam": "xc103", "nums": [14, 15], "form": "題組", "img": "img/xc103-14.png", "source": "《戰國策‧東周策》", "author": "", "genre": "史傳人物", "types": ["字詞解釋", "文意推論"], "passage": "昌他亡西周，之東周，盡輸西周之情於東周。東周大喜，西周大怒。馮且曰：「臣能殺之。」君予金三十斤。馮且使人操金與書，間遺昌他書曰：「告昌他，事可成，勉成之；不可成，亟亡來亡來。事久且泄，自令身死。」因使人告東周之候曰：「今夕有姦人當入者矣。」候得而獻東周，東周立殺昌他。", "translation": "昌他從西周逃出，到了東周，把西周的情報全部告訴東周。東周非常高興，西周非常憤怒。馮且說：「我能殺掉他。」西周國君給了他三十斤金。馮且派人帶著金子和信，暗中送信給昌他，信上說：「告訴昌他：事情能成功，就努力完成；不能成功，就趕快逃回來、逃回來。事情拖久了將會洩漏，那就是自己害死自己。」接著又派人告訴東周的探子說：「今晚有奸細要進來。」探子抓到送信的人，把信獻給東周國君，東周立刻殺了昌他。", "keywords": [{"w": "亡", "m": "逃亡"}, {"w": "之", "m": "往、到"}, {"w": "輸", "m": "送出、告知"}, {"w": "間", "m": "暗中"}, {"w": "遺", "m": "送給"}, {"w": "亟", "m": "趕快"}, {"w": "且", "m": "將要"}, {"w": "候", "m": "斥候、探子"}], "questions": [{"n": 14, "qtype": "單選", "stem": "下列各組「」內的文字，前後意義相同的選項是：", "options": {"A": "昌他亡西周，「之」東周／嚮「之」來，非有取於升斗之祿", "B": "馮且使人操金「與」書／噫！微斯人，吾誰「與」歸", "C": "事久「且」泄，自令身死／今疾「且」成，已非三月不能瘳", "D": "「因」使人告東周之候曰／「因」人之力而敝之，不仁"}, "answer": "C", "explain": "(A)前者「之」是動詞「往、到」；後者「嚮之來」的「之」放在時間詞後，是無義的助詞（先前來的時候）。(B)前者「與」是連詞「和」（金和信）；後者「吾誰與歸」是「我跟從誰呢」，「與」是跟從、親附。(C)正確，兩個「且」都是「將要」：事情拖久將要洩漏；病將要形成。(D)前者「因」是「於是、接著」；後者是「憑藉」（憑藉別人的力量卻又損害他）。", "skill": "「之」「與」「因」「且」都是高頻多義字，記住各自最常考的兩三個意思，代入句中驗證。"}, {"n": 15, "qtype": "單選", "stem": "依據文意，選出敘述正確的選項：", "options": {"A": "馮且收買昌他為西周間諜，遭東周查獲而遇害", "B": "馮且命昌他策反東周斥候，反令昌他被捕遇害", "C": "馮且誣陷昌他收賄通敵，昌他逃至東周而遭戮", "D": "馮且故布疑陣，使昌他被東周誤為間諜而遭戮"}, "answer": "D", "explain": "馮且的計謀是：寫一封假信，好像昌他其實是西周派去的臥底（「事可成，勉成之；不可成，亟亡來」），再故意通報東周探子攔截，讓東周誤以為昌他是間諜而殺了他。(D)正確。(A)昌他並沒有真的被收買，金和信都是做給東周看的道具。(B)沒有策反斥候的情節，告訴斥候是為了讓信被攔截。(C)昌他是先逃到東周，之後才被陷害；陷害的罪名是「西周間諜」，不是收賄通敵，而且順序也錯。", "skill": "讀計謀故事，先弄清「真相」與「假象」：誰知道真相、誰被騙，騙局要讓被騙的人相信什麼。"}], "difficulty": "中", "label": "103學測", "year": 103, "kind": "學測", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "馮諼客孟嘗君"}, {"id": "xc103-20", "exam": "xc103", "nums": [20], "form": "單題", "img": "img/xc103-20.png", "source": "甲：司馬光〈進資治通鑑表〉；乙：宋人書《戰國策》後之文（出處待查）", "author": "司馬光等", "genre": "書信序跋", "types": ["文化常識", "比較閱讀", "文意推論"], "passage": "甲：每患遷、固以來，文字繁多，自布衣之士，讀之不遍，況於人主，日有萬機，何暇周覽！臣常不自揆，欲刪削冗長，舉撮機要，專取關國家盛衰，繫生民休戚，善可為法，惡可為戒者，為編年一書，……上起戰國，下終五代，凡一千三百六十二年，修成二百九十四卷。\n乙：予在京師，因借館閣諸公家藏數本，參校之，蓋十正其六七，……其要皆主於利言之，合從連橫，變詐百出。然自春秋之後，以迄于秦，二百餘年興亡成敗之跡，粗見於是矣！雖非義理之所存，而辯麗橫肆，亦文辭之最，學者所不宜廢也。", "translation": "甲：我常擔憂從司馬遷、班固以來，史書文字太多，連一般讀書人都讀不完，何況君主每天要處理萬件政事，哪有空全部看完！我常不自量力，想刪去冗長的部分，摘取重點，專門選取關係國家興衰、牽涉百姓憂樂，好的可以效法、壞的可以作為警戒的史事，編成一部編年體的書……上起戰國，下到五代，共一千三百六十二年，修成二百九十四卷。乙：我在京城時，借來館閣與諸位先生家藏的幾個版本，互相校對，大概改正了十分之六七……書中重點都在講利益，合縱連橫，詭詐變化百出。但從春秋以後到秦朝，兩百多年興亡成敗的事跡，大致可以從這裡看到！雖然不是義理所在，但言辭雄辯華麗、奔放恣肆，也是文辭中最好的，求學的人不應廢棄。", "keywords": [{"w": "遷、固", "m": "司馬遷、班固"}, {"w": "不自揆", "m": "不自量力（謙詞）"}, {"w": "休戚", "m": "喜樂與憂慮"}, {"w": "參校", "m": "比對校正"}, {"w": "合從連橫", "m": "戰國時的合縱、連橫外交策略"}, {"w": "橫肆", "m": "奔放恣肆"}], "questions": [{"n": 20, "qtype": "多選", "stem": "關於下列甲、乙二人的陳述，敘述正確的選項是：", "options": {"A": "「甲」強調該書的政治功能；「乙」肯定該書的言辭效益", "B": "「甲」所修之書可能是《資治通鑑》；「乙」所校之書可能是《戰國策》", "C": "「甲」和「乙」的陳述，皆為呈給皇帝的上書，勸諫治國應以歷代興亡為鑑", "D": "《史記》、《漢書》是「甲」用以成書的主要材料，也是「乙」用以成書的主要憑藉", "E": "〈燭之武退秦師〉可在「甲」所修之書中檢得；〈馮諼客孟嘗君〉可在「乙」所校之書中讀到"}, "answer": "AB", "explain": "(A)正確：甲選取「關國家盛衰……善可為法，惡可為戒」的史事給君主看，重政治鑑戒；乙說「雖非義理之所存，而辯麗橫肆，亦文辭之最」，肯定文辭價值。(B)正確：甲是編年體、起戰國終五代、二百九十四卷，就是司馬光的《資治通鑑》；乙所校的書講「合從連橫，變詐百出」、記春秋後到秦的事，是《戰國策》。(C)錯誤：甲自稱「臣」，是給皇帝的表；乙用「予」，是校書後寫的文字，不是上書。(D)錯誤：乙是用館閣與私家藏本互相校對，不是以《史記》《漢書》為憑藉。(E)錯誤：〈燭之武退秦師〉是春秋時的事，出自《左傳》，而《資治通鑑》從戰國開始，查不到；〈馮諼客孟嘗君〉確實在《戰國策》中，但前半錯，整項錯。", "skill": "判斷書名先抓「體例＋起訖＋內容關鍵詞」（編年、起戰國終五代＝通鑑；合縱連橫＝戰國策），再用起訖年代檢驗選項。"}], "difficulty": "中", "label": "103學測", "year": 103, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc103-21", "exam": "xc103", "nums": [21], "form": "單題", "img": "img/xc103-21.png", "source": "《禮記‧檀弓》", "author": "", "genre": "經典語錄", "types": ["人物情感", "文意推論", "文化常識"], "passage": "曾子寢疾，病。樂正子春坐於床下，曾元、曾申坐於足，童子隅坐而執燭。童子曰：「華而睆，大夫之簀與？」子春曰：「止！」曾子聞之，瞿然曰：「呼！」曰：「華而睆，大夫之簀與？」曾子曰：「然。斯季孫之賜也，我未之能易也。元，起，易簀。」曾元曰：「夫子之病革矣！不可以變。幸而至於旦，請敬易之。」曾子曰：「爾之愛我也不如彼。君子之愛人也以德，細人之愛人也以姑息。吾何求哉？吾得正而斃焉，斯已矣。」舉扶而易之，反席未安而沒。", "translation": "曾子臥病在床，病得很重。學生樂正子春坐在床下，兒子曾元、曾申坐在床腳邊，一個童子坐在角落拿著蠟燭。童子說：「好華美光亮啊，這是大夫用的席子吧？」子春說：「別說了！」曾子聽到了，驚醒過來說：「啊！」童子又說：「好華美光亮啊，這是大夫用的席子吧？」曾子說：「是的。這是季孫送的，我還沒能換掉。元，起來，換席子。」曾元說：「您的病很危急了，不能移動。希望能撐到天亮，再恭敬地為您換。」曾子說：「你愛我還比不上那個童子。君子愛人是用德行成全他，小人愛人是用無原則的遷就。我還求什麼呢？我能合乎禮法地死去，就夠了。」大家扶起他換了席子，回到床上還沒躺穩就過世了。", "keywords": [{"w": "病", "m": "病重"}, {"w": "睆", "m": "明亮"}, {"w": "簀", "m": "竹席"}, {"w": "瞿然", "m": "驚醒的樣子"}, {"w": "革", "m": "通「亟」，危急"}, {"w": "姑息", "m": "無原則地遷就寬容"}, {"w": "沒", "m": "通「歿」，死"}], "questions": [{"n": 21, "qtype": "多選", "stem": "閱讀下文，選出敘述正確的選項：", "options": {"A": "樂正子春擔心曾子睡不著，故要童子勿執燭火", "B": "曾元希望曾子換席子，以不負季孫賜簀的美意", "C": "曾子責怪曾元不懂得變通，不如季孫善體人意", "D": "曾子認為不宜逾矩，故堅持要曾元為他換席子", "E": "曾子以為：因愛而姑息對方，反可能傷害對方"}, "answer": "DE", "explain": "背景：曾子不是大夫，睡大夫的席子不合禮，所以臨死堅持換掉。(A)錯誤：子春說「止」是要童子別再說（怕曾子聽到而堅持換席），不是叫他別拿蠟燭。(B)錯誤：曾元是「不可以變」，主張不要換。(C)錯誤：「爾之愛我也不如彼」的「彼」是指童子，童子點出不合禮的事，反而成全了曾子；曾子也不是怪曾元不懂變通，而是怪他用姑息的方式愛自己。(D)正確：「吾得正而斃焉，斯已矣」，堅持合禮。(E)正確：「君子之愛人也以德，細人之愛人也以姑息」，姑息會讓對方失禮，反而是害他。", "skill": "讀對話要先確定代詞指誰（彼＝童子），再理解每個人的立場（要換／不換），選項才不會被人名混淆。"}], "difficulty": "中", "label": "103學測", "year": 103, "kind": "學測", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "大同與小康"}, {"id": "xc103-22", "exam": "xc103", "nums": [22], "form": "單題", "img": "img/xc103-22.png", "source": "蘇軾〈赤壁賦〉、韓愈〈師說〉、曹丕〈典論論文〉、歐陽脩〈醉翁亭記〉等", "author": "多位作者", "genre": "其他", "types": ["寫作手法", "句意理解"], "passage": "(A)句讀之不知，惑之不解；或師焉，或不焉\n(B)西伯幽而演《易》，周旦顯而制《禮》；不以隱約而弗務，不以康樂而加思\n(C)禽鳥知山林之樂，而不知人之樂；人知從太守遊而樂，而不知太守之樂其樂", "translation": "(A)不懂句讀，有疑惑不能解決，前者去請教老師，後者卻不肯請教。(B)周文王被囚禁時推演《周易》，周公顯達時制定《周禮》；文王不因困頓而不努力，周公不因安樂而改變心志。(C)禽鳥知道山林的快樂，卻不知道人的快樂；人們知道跟隨太守遊玩的快樂，卻不知道太守是以他們的快樂為快樂。", "keywords": [{"w": "句讀", "m": "文句的停頓斷句"}, {"w": "西伯", "m": "周文王"}, {"w": "周旦", "m": "周公旦"}, {"w": "隱約", "m": "困頓、不得志"}, {"w": "加思", "m": "改變心志"}], "questions": [{"n": 22, "qtype": "多選", "stem": "蘇軾〈赤壁賦〉：「惟江上之清風，與山間之明月，耳得之而為聲，目遇之而成色」，此四句的文意可理解為：「江上之清風，耳得之而為聲；山間之明月，目遇之而成色」，但作者改變句子的銜接順序，故閱讀時，宜就文意調節對應關係。下列文句，與此表達方式相似的選項是：", "options": {"A": "句讀之不知，惑之不解；或師焉，或不焉", "B": "西伯幽而演《易》，周旦顯而制《禮》；不以隱約而弗務，不以康樂而加思", "C": "禽鳥知山林之樂，而不知人之樂；人知從太守遊而樂，而不知太守之樂其樂", "D": "牠們曾交錯湧疊，也曾高速接近船舷又敏捷地側翻；如在表演水中疊羅漢，如流星一樣劃一道弧線拋射離去", "E": "老和尚竟哽咽起來，掉了幾滴眼淚，他趕緊用袈裟的寬袖子，搵了一搵眼睛；秦義方也掏出手帕，狠狠擤了一下鼻子"}, "answer": "ABD", "explain": "這種寫法是先並列兩件事（甲、乙），再並列兩個說明（甲'、乙'），讀的時候要把甲配甲'、乙配乙'。(A)正確：「句讀之不知→或師焉；惑之不解→或不焉」（小的不懂去問老師，大的疑惑反而不問）。(B)正確：「西伯幽而演易→不以隱約而弗務；周旦顯而制禮→不以康樂而加思」。(C)錯誤：前後兩句各自完整，禽鳥一組、人一組，按順序直接讀，沒有拆開再對應。(D)正確：「交錯湧疊→如在表演水中疊羅漢；高速接近船舷又敏捷地側翻→如流星一樣劃一道弧線拋射離去」。(E)錯誤：老和尚一句、秦義方一句，各自完整敘述，不需要重新配對。", "skill": "看到「A、B；A'、B'」的四段結構，試著把第1、3段接起來、第2、4段接起來讀，讀得通就是這種寫法。"}], "difficulty": "中", "label": "103學測", "year": 103, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "典論論文、師說、醉翁亭記、赤壁賦"}, {"id": "xc103-23", "exam": "xc103", "nums": [23], "form": "單題", "img": "img/xc103-23.png", "source": "曹雪芹《紅樓夢》、吳敬梓《儒林外史》、羅貫中《三國演義》、杜光庭〈虬髯客傳〉、金庸《神鵰俠侶》", "author": "多位作者", "genre": "其他", "types": ["文意推論", "人物情感"], "passage": "(D)虬髯客想請道士觀察李世民是否具天子之相，以決定自己是否退出逐鹿之局，乃由劉文靜邀李世民前來看棋。弈棋中的道士見李世民神采驚人，慘然曰：「此局全輸矣！於此失卻局，奇哉！救無路矣！」", "translation": "(D)道士悽然說：「這盤棋全輸了！在這裡失掉了全局，真奇怪啊！沒有路可以挽救了！」表面說棋局，實指虬髯客爭天下的局勢已經輸了。", "keywords": [{"w": "逐鹿", "m": "爭奪天下"}, {"w": "慘然", "m": "悲傷的樣子"}, {"w": "影射", "m": "表面說甲，暗指乙"}], "questions": [{"n": 23, "qtype": "多選", "stem": "《後宮甄嬛傳》中，華妃陪皇后看戲時說：「到底是樊梨花有身家，出身西涼將門的嫡出女兒。若是換作庶出女兒，再沒有這移山倒海的本事，可真是死路一條了。」華妃表面上是評論戲中角色，實則藉以影射皇后是庶出女兒。下列文句畫底線處的文字，也在表面意義之外另有影射的選項是：", "options": {"A": "鳳姐拉過劉姥姥來，把一盤子花橫三豎四的插了一頭，賈母和眾人笑得不得了，劉姥姥笑道：「我雖老了，年輕時也風流，愛個花兒粉兒的，今兒索性做個老風流。」", "B": "范進想向丈人胡屠戶借鄉試的路費，被胡屠戶罵了一個狗血噴頭：「你問我借盤纏，我一天殺一個豬還賺不得錢把銀子，都把與你去丟在水裡，叫我一家老小嗑西北風？」", "C": "華歆勸曹丕殺曹植。曹丕召曹植入見，限七步吟詩一首，須以「兄弟」為題，但不許犯「兄弟」字樣，方可免死。曹植略不思索，即吟曰：「煮豆燃豆萁，豆在釜中泣。本是同根生，相煎何太急！」", "D": "虬髯客想請道士觀察李世民是否具天子之相，以決定自己是否退出逐鹿之局，乃由劉文靜邀李世民前來看棋。弈棋中的道士見李世民神采驚人，慘然曰：「此局全輸矣！於此失卻局，奇哉！救無路矣！」", "E": "歐陽鋒將柯鎮惡震下屋頂，郭靖、黃蓉分別以降龍十八掌、落英神劍掌對付歐陽鋒。一旁窺見的楊過，後來故意說給黃蓉聽：「一個大蟋蟀跟一隻老蟋蟀對打，老蟋蟀輸了，又來了兩隻小蟋蟀幫著，三隻打一個。大蟋蟀跳來跳去，這邊彈一腳，那邊咬一口，嘿嘿，那可厲害了……」"}, "answer": "CDE", "explain": "「影射」＝表面說一件事，其實暗指另一件事。(A)劉姥姥被插了滿頭花，自嘲「做個老風流」，是順著情境自我解嘲，說的就是自己，沒有暗指別的。(B)胡屠戶直接罵范進，字面就是本意，沒有影射。(C)表面寫煮豆燃萁，實指同為兄弟的曹丕逼迫曹植，是影射。(D)表面說棋局全輸，實指虬髯客爭天下的大局已輸給李世民，是影射。(E)表面說蟋蟀打架，實指歐陽鋒（大蟋蟀）打敗柯鎮惡（老蟋蟀），郭靖黃蓉（兩隻小蟋蟀）圍攻，是影射。", "skill": "判斷影射：把底線文字的表面對象（豆、棋、蟋蟀）換成故事裡的人或事，能一一對上就是影射。"}], "difficulty": "易", "label": "103學測", "year": 103, "kind": "學測", "textcat": "文學文本", "textcat2": "部定古文", "linked_core": "虬髯客傳"}, {"id": "xc103-ns1", "exam": "xc103", "nums": ["一"], "form": "單題", "img": "img/xc103-ns1.png", "source": "錢穆〈品與味〉", "author": "錢穆", "genre": "說理議論", "types": ["文意推論", "比較閱讀", "主旨寓意"], "passage": "近代之觀光遊覽必廣攬遊眾，乃可贏利。故凡屬勝境，惟求通俗化，遂使群客奔波盡興，實則人看人。儻兼以歌唱舞蹈，愈撩亂，則愈活躍，心神無片刻安頓處，斯為觀光之成功。凡屬觀光，乃求動，不求靜。乃求熱鬧，不求清淨。此乃近代人心一大趨向。中國風景皆求清賞，「鳥鳴山更幽」，始覺此山中之深趣。「山中方七日，世上已千年」。儻亦男女雜沓，喧嘩擁擠，轉眼即過，則七日亦在一瞬間。此始是近代觀光客遊覽客所要求，如此才感快意。古人詩「振衣千仞岡，濯足萬里流」，今人則必在萬目睽睽下振衣，一振衣而下座，掌聲雷動，乃始快意。千仞岡上，何人得見！海水浴場，亦必人群俱集，乃始成一場面。一人濯足，則何情味可言！故千仞之岡，則必組旅行隊。萬里之流，則必組游泳團。一人閒居，必感無聊。古以窈窕乃成淑女，今則儘時髦，儘摩登，投入人群中活躍，以供人玩賞為己樂，人品亦化成商品，良可嗟矣。", "translation": "近代的觀光旅遊一定要大量招攬遊客才能賺錢。所以凡是名勝，只求通俗化，讓遊客奔波玩個痛快，其實是人看人。如果再加上唱歌跳舞，越紛亂越熱鬧，心神沒有片刻安定，這才算觀光成功。觀光求動不求靜，求熱鬧不求清淨，這是近代人心的一大趨勢。中國的風景都講求清幽地欣賞，「鳥鳴山更幽」，才感受到山中的深刻趣味；「山中方七日，世上已千年」。如果也是男男女女雜亂擁擠喧嘩，轉眼就過，那七天也只是一瞬間。這才是近代觀光客要的，這樣才覺得痛快。古人詩說「在千仞高岡上抖落衣上灰塵，在萬里長流中洗腳」，今人卻一定要在眾目睽睽下抖衣，一抖完下臺，掌聲雷動，才感到痛快。千仞高岡上，誰看得見！海水浴場也一定要人群聚集，才成場面；一個人洗腳，有什麼情味可言！所以登高岡要組旅行隊，到大河要組游泳團，一個人閒居就覺得無聊。古代女子要嫻靜美好才是淑女，現在卻要時髦摩登，投入人群中活躍，以供人玩賞為樂，連人品也變成了商品，實在可嘆。", "keywords": [{"w": "儻", "m": "通「倘」，如果"}, {"w": "清賞", "m": "清靜地欣賞"}, {"w": "雜沓", "m": "眾多雜亂"}, {"w": "振衣", "m": "抖落衣上灰塵，比喻超脫塵俗"}, {"w": "濯足", "m": "洗腳"}, {"w": "窈窕", "m": "嫻靜美好"}, {"w": "良", "m": "實在"}], "questions": [{"n": "一", "qtype": "非選", "stem": "文章解讀（占9分：第（一）題6分，第（二）題3分）：閱讀框線內文章，回答：（一）古人的「清賞」和今人的「觀光」有何不同？（二）文中「人品亦化成商品」的意思為何？請將答案標明（一）（二）書寫，（一）（二）合計文長約100-150字（約5-7行）。", "options": {}, "answer": "", "ref_answer": "（一）古人的「清賞」求靜、求清淨，往往獨自或少數人置身山水，以安頓的心神體會景物的深趣（如「鳥鳴山更幽」「振衣千仞岡」），重在內心的涵養與自得；今人的「觀光」求動、求熱鬧，商業化、通俗化，成群結隊、喧嘩擁擠，在眾人注目與掌聲中才覺快意，實則人看人，心神無片刻安頓。（二）指今人的品格修養也受商業風氣影響：不再以嫻靜內斂為美，而是追求時髦、在人群中表現自己，以供人觀看玩賞為樂，把自身當成展示、交換的商品，失去了內在的品味與尊嚴。", "ref_official": false, "explain": "第（一）題用「對比表」整理最清楚：靜／動、清淨／熱鬧、獨處／群聚、內心自得／他人掌聲、深趣／盡興。原文每組都有例子（鳥鳴山更幽、振衣千仞岡 vs. 萬目睽睽、旅行隊），挑一兩個佐證即可，不要大段抄原文。第（二）題要解釋比喻：「商品」的特點是拿出來展示、給人看、供人消費，所以「人品化成商品」就是人以被別人觀看、玩賞為目的，品格修養也跟著外在化、庸俗化。", "skill": "文章解讀題先找作者設下的「對比組」，用自己的話整理成幾個對立概念，再各舉一例。"}], "difficulty": "中", "label": "103學測", "year": 103, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc103-ns2", "exam": "xc103", "nums": ["二"], "form": "單題", "img": "img/xc103-ns2.png", "source": "諸葛亮〈出師表〉", "author": "諸葛亮", "genre": "書信序跋", "types": ["寫作手法", "人物情感", "主旨寓意"], "passage": "臣本布衣，躬耕於南陽，苟全性命於亂世，不求聞達於諸侯。先帝不以臣卑鄙，猥自枉屈，三顧臣於草廬之中，諮臣以當世之事，由是感激，遂許先帝以驅馳。後值傾覆，受任於敗軍之際，奉命於危難之間，爾來二十有一年矣。先帝知臣謹慎，故臨崩寄臣以大事也。受命以來，夙夜憂勤，恐託付不效，以傷先帝之明，故五月渡瀘，深入不毛。今南方已定，兵甲已足，當獎率三軍，北定中原，庶竭駑鈍，攘除姦凶，興復漢室，還於舊都，此臣所以報先帝而忠陛下之職分也。", "translation": "我本來是個平民，在南陽親自耕田，只求在亂世中保全性命，不想在諸侯間求取名聲。先帝不嫌我身分低微、見識淺陋，屈尊降貴，三次到草廬拜訪我，向我請教天下大事，我因此感動奮發，答應為先帝奔走效力。後來遇到兵敗，我在軍隊潰敗時接受任命，在危難之際奉命出使，到現在已經二十一年了。先帝知道我做事謹慎，所以臨終時把國家大事託付給我。接受遺命以來，我日夜憂慮勤勉，怕託付的事沒有成效，損害先帝知人之明，所以五月渡過瀘水，深入荒涼的不毛之地。現在南方已經平定，兵器盔甲也充足，應當激勵率領三軍，北上平定中原，希望竭盡我平庸的才能，剷除奸邪凶惡的敵人，復興漢室，回到舊都，這是我報答先帝、忠於陛下的職責本分。", "keywords": [{"w": "布衣", "m": "平民"}, {"w": "卑鄙", "m": "身分低微、見識淺陋（古義）"}, {"w": "猥", "m": "降低身分，謙詞"}, {"w": "枉屈", "m": "屈尊"}, {"w": "驅馳", "m": "奔走效勞"}, {"w": "不毛", "m": "不長草木的荒地"}, {"w": "駑鈍", "m": "才能平庸（謙詞）"}], "questions": [{"n": "二", "qtype": "非選", "stem": "文章分析（占18分：第（一）題9分，第（二）題9分）：言語交際過程中，常見運用「謙遜原則」——儘量降低姿態，不彰顯自己，例如：「小弟不才，能力有限，請多包涵」。但基於某些目的，也可能刻意不採取這項原則。請就下引諸葛亮〈出師表〉的文字分析：（一）列出並簡要說明文中何處運用「謙遜原則」？何處刻意彰顯自己，不採取「謙遜原則」？（二）文中運用「謙遜原則」的同時，又刻意不採取「謙遜原則」，目的為何？請將答案標明（一）（二）書寫，（一）（二）合計文長約250-300字（約12-14行）。", "options": {}, "answer": "", "ref_answer": "（一）運用謙遜原則：「臣本布衣，躬耕於南陽」自言出身平凡；「苟全性命於亂世，不求聞達於諸侯」表示本無功名之心；「先帝不以臣卑鄙」自稱卑鄙；「庶竭駑鈍」自謙才能平庸。刻意彰顯自己：「受任於敗軍之際，奉命於危難之間，爾來二十有一年矣」強調在危難中挺身而出、效力多年；「先帝知臣謹慎，故臨崩寄臣以大事」強調受先帝託孤的信任；「夙夜憂勤……故五月渡瀘，深入不毛。今南方已定，兵甲已足」陳述平定南方的功績與準備。（二）謙遜之詞表明自己忠誠、無私心，出仕只為報答先帝知遇，避免功高震主、讓後主猜疑；彰顯之語則展示自己的資歷、能力與先帝的信任，證明北伐準備充分、有能力承擔，以取得後主的信任與支持，順利出師北伐，興復漢室。兩者並用，既表忠心又建立說服力。", "ref_official": false, "explain": "第（一）題「列出並簡要說明」，要直接引原文的關鍵句，再用一句話說它是在謙還是在顯。分辨方法：說自己出身低、能力差、沒有野心的是謙；講自己受重任、有功績、被先帝信任的是顯。第（二）題要想到寫作對象是後主劉禪、目的是請求出兵：只謙虛會讓人懷疑你能不能打仗，只誇功又怕被疑有野心，所以兩者並用——謙表忠心、顯建信心，最終都為了讓後主放心支持北伐。", "skill": "分析說話策略時，先確定「說給誰聽、要他做什麼」，再看每一句話對達成這個目的有什麼作用。"}], "difficulty": "中", "label": "103學測", "year": 103, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "出師表"}, {"id": "zk103-1", "exam": "zk103", "nums": [1], "form": "單題", "img": "img/zk103-1.png", "source": "曹丕〈燕歌行〉、諸葛亮〈出師表〉、《北史》等古文與現代用語對照", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "", "translation": "", "keywords": [{"w": "煢煢", "m": "孤單無依的樣子"}, {"w": "卑鄙", "m": "古：身分低微、見識淺陋；今：品格低劣"}, {"w": "風流", "m": "古：傑出人物的風采；今：放蕩多情"}, {"w": "感激", "m": "古：感動而奮發；今：感謝"}], "questions": [{"n": 1, "qtype": "單選", "stem": "同一詞語在古今不同的語境中，有時意義會改變。下列各組「」內的詞語，意義沒有改變的選項是：", "options": {"A": "君何淹留寄他方，賤妾「煢煢」守空房／他們母子二人，天天寡言少笑，相對「煢煢」", "B": "先帝不以臣「卑鄙」，猥自枉屈，三顧臣於草廬之中／這群小人的「卑鄙」行徑，令人不齒", "C": "古今「風流」，宋有子瞻，唐有太白，晉有東山，本無幾也／他只管「風流」快活，處處留情", "D": "（劉）松為人作碑銘，以示思道。思道讀之，多所不解，於是「感激」，閉戶讀書／慈善團體運送救援物資到災區，讓災民「感激」萬分"}, "answer": "A", "explain": "(A)沒有改變：曹丕〈燕歌行〉的「煢煢」是妻子獨守空房的孤單；現代句子母子相對煢煢，也是孤單寂寞。(B)改變了：〈出師表〉的「卑鄙」是諸葛亮謙稱自己身分低、見識淺；今天的「卑鄙」是人格低劣。(C)改變了：古句「古今風流」指蘇軾、李白、謝安（東山）這些傑出人物的風采；今句「風流快活」是指感情放蕩。(D)改變了：盧思道讀不懂劉松寫的碑文，「感激」是受到刺激而發憤，所以閉門讀書；今句是感謝。", "skill": "古今詞義題，先用現代意思讀古句，讀起來怪怪的（諸葛亮罵自己人格差？）就代表意思變了。"}], "difficulty": "中", "label": "103指考", "year": 103, "kind": "指考", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "出師表"}, {"id": "zk103-2", "exam": "zk103", "nums": [2], "form": "單題", "img": "img/zk103-2.png", "source": "《大學》、《老子》、《史記》等", "author": "", "genre": "經典語錄", "types": ["虛詞句式", "字詞解釋"], "passage": "", "translation": "", "keywords": [{"w": "病病", "m": "把缺點當作缺點來擔憂（前動詞、後名詞）"}, {"w": "將將", "m": "將領率領（前名詞、後動詞）"}, {"w": "明明德", "m": "彰明光明的德性（前動詞、後形容詞）"}], "questions": [{"n": 2, "qtype": "單選", "stem": "下列「」中的字詞，符合前者作動詞用、後者作名詞用的選項是：", "options": {"A": "民之所好好之，民之所「惡」「惡」之", "B": "聖人不病，以其「病」「病」，是以不病", "C": "（九江王）布稱疾不往，使「將」「將」數千人行", "D": "大學之道，在「明」「明」德，在親民，在止於至善"}, "answer": "B", "explain": "(B)《老子》：聖人沒有缺點，是因為他把缺點當作缺點來擔憂，所以沒有缺點。前面的「病」是「擔憂、以…為病」，動詞；後面的「病」是「缺點」，名詞，符合。(A)「民之所惡」是百姓所厭惡的，「惡之」是去厭惡它，兩個都是動詞（讀ㄨˋ）。(C)「使將將數千人」是派將領率領幾千人，前面是名詞（將領）、後面是動詞（率領），順序相反。(D)「明明德」是彰顯光明的德性，前面是動詞、後面是形容詞，不是名詞。", "skill": "疊字詞性題：前一字後面接著東西（受詞）多半是動詞，後一字前面有「其」或後面接名詞，就看它是被修飾還是在修飾。"}], "difficulty": "中", "label": "103指考", "year": 103, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk103-6", "exam": "zk103", "nums": [6], "form": "單題", "img": "img/zk103-6.png", "source": "李白〈春思〉等唐詩", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文化常識"], "passage": "甲、殘螢棲玉露，早雁拂金河\n乙、燕草如碧絲，秦桑低綠枝\n丙、木槿花開畏日長，時搖輕扇倚繩牀\n丁、四野便應枯草綠，九重先覺凍雲開", "translation": "甲：殘存的螢火蟲停在白露上，早來的大雁掠過銀河。\n乙：燕地的草才像碧綠的絲線，秦地的桑樹已經低垂著綠枝。\n丙：木槿花開，怕的是白天太長，不時搖著輕扇靠在繩床上。\n丁：四方田野應該就要讓枯草轉綠了，宮中已先感覺到凍雲散開。", "keywords": [{"w": "玉露", "m": "秋天的白露"}, {"w": "金河", "m": "秋天的銀河（五行中秋屬金）"}, {"w": "木槿", "m": "夏天開花的灌木"}, {"w": "凍雲", "m": "冬天寒冷凝結的雲"}, {"w": "九重", "m": "宮廷"}], "questions": [{"n": 6, "qtype": "單選", "stem": "下列詩句，依春夏秋冬四季順序排列，正確的選項是：", "options": {"A": "乙甲丙丁", "B": "乙丙甲丁", "C": "丁乙甲丙", "D": "丁丙甲乙"}, "answer": "B", "explain": "找每句的季節線索：乙「草如碧絲、桑低綠枝」，草木初綠，是春天（李白〈春思〉）。丙「木槿花開」「畏日長」「搖輕扇」，白天長又熱，是夏天。甲「殘螢」「玉露」「早雁」，螢火蟲快沒了、雁開始南飛，是秋天。丁「枯草」「凍雲開」，寒冬將盡、等待回春，是冬天。所以是乙丙甲丁，選(B)。", "skill": "季節題抓「物候」：動植物（螢、雁、木槿、桑）和天氣（露、凍雲、日長）比形容詞更可靠。"}], "difficulty": "易", "label": "103指考", "year": 103, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk103-11", "exam": "zk103", "nums": [11], "form": "單題", "img": "img/zk103-11.png", "source": "張秀亞〈琴韻心聲——我讀《琴心》〉；選項為古典詩句", "author": "張秀亞", "genre": "古典詩詞曲", "types": ["句意理解", "詩詞賞析"], "passage": "(A)此中有真意，欲辯已忘言\n(B)草木有本心，何求美人折\n(C)升降榮枯何足道，人間難覓是知音\n(D)此情可待成追憶，只是當時已惘然", "translation": "(A)這裡面有真正的意趣，想說明卻已忘了怎麼說。\n(B)草木有自己的本性，何必要美人來折取欣賞？\n(C)官位升降、人生盛衰哪值得一提，人世間最難找的是知音。\n(D)這份感情要等到日後回憶時才懂得珍惜，只是在當時就已經茫然若失。", "keywords": [{"w": "知音", "m": "了解自己的人（伯牙子期典故）"}, {"w": "本心", "m": "本性"}, {"w": "惘然", "m": "若有所失的樣子"}], "questions": [{"n": 11, "qtype": "單選", "stem": "閱讀下文，選出最符合文意的選項：在新寫實主義的噪音裡，我們聽到一個寂寞的歌人，倚著綠色的藤樹放歌。每一個節響，每一個音符，都會使我們想起閃爍而又熄滅了的夢之火焰，她歌唱，她嘆息，只是為了能在幽暗中回應的人。（張秀亞〈琴韻心聲——我讀《琴心》〉）", "options": {"A": "此中有真意，欲辯已忘言", "B": "草木有本心，何求美人折", "C": "升降榮枯何足道，人間難覓是知音", "D": "此情可待成追憶，只是當時已惘然"}, "answer": "C", "explain": "文章說寂寞的歌人在嘈雜中歌唱，「只是為了能在幽暗中回應的人」，也就是在等待懂她的人——知音，所以(C)最符合。(A)陶淵明〈飲酒〉，講體會到自然真意卻說不出來，重點是「難以言說」。(B)張九齡〈感遇〉，講自守本性、不求別人賞識，和「為了回應的人而唱」剛好相反。(D)李商隱〈錦瑟〉，講對往事的追憶與惘然，沒有「找知音」的意思。", "skill": "白話配古詩句，先把白話段落濃縮成一個關鍵詞（這題是「知音」），再找詩句裡同義的字眼。"}], "difficulty": "易", "label": "103指考", "year": 103, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk103-12", "exam": "zk103", "nums": [12], "form": "單題", "img": "img/zk103-12.png", "source": "林文月〈同在異鄉為異客〉、蔣勳〈我與書畫的緣分〉；選項為古典詩文", "author": "林文月、蔣勳", "genre": "經典語錄", "types": ["句意理解", "文意推論"], "passage": "(A)剪不斷、理還亂／知其不可而為之\n(B)心為形役，惆悵獨悲／申申如也，夭夭如也\n(C)縱浪大化、無復多慮／造次必於是，顛沛必於是\n(D)古今多少事，盡付笑談中／人不知而不慍，不亦君子乎", "translation": "(A)剪也剪不斷、理也理不清（離愁）／明知做不到還是去做。\n(B)讓心靈被形體役使，獨自惆悵悲傷／（孔子閒居時）神態舒展、和悅。\n(C)在大自然的變化中隨波放浪，不再多所憂慮／匆忙急迫時一定守著仁，顛沛流離時也一定守著仁。\n(D)古往今來多少事，都交給笑談罷了／別人不了解我也不生氣，不也是君子嗎？", "keywords": [{"w": "大化", "m": "大自然的變化"}, {"w": "造次", "m": "匆忙、倉促之間"}, {"w": "顛沛", "m": "困頓流離"}, {"w": "申申、夭夭", "m": "舒展和樂的樣子"}], "questions": [{"n": 12, "qtype": "單選", "stem": "下列兩段文字皆蘊含人生感懷，選出「＿＿」內依序最適合填入的語句：甲、姆媽也逝世十餘年，而今陽明山上墓木已拱！兄弟姊妹更是各自成家，四方星散，恐怕再也無法團聚一處吧？往日舊情，徒增欷歔，轉覺所謂「＿＿」行之之難。（林文月〈同在異鄉為異客〉）　乙、我開始在顏真卿的字中，看到戰亂中生命一絲不苟的端正，那種「＿＿」的歷史的莊嚴，其實遠不是「造型美術」四個字能夠解答，而更是一種生命的實踐罷。（蔣勳〈我與書畫的緣分〉）", "options": {"A": "剪不斷、理還亂／知其不可而為之", "B": "心為形役，惆悵獨悲／申申如也，夭夭如也", "C": "縱浪大化、無復多慮／造次必於是，顛沛必於是", "D": "古今多少事，盡付笑談中／人不知而不慍，不亦君子乎"}, "answer": "C", "explain": "甲：母親過世、手足星散，作者「徒增欷歔」，覺得某種道理「行之之難」——做起來很難的，應是「看開、不再多想」，所以填陶淵明的「縱浪大化、無復多慮」。「剪不斷理還亂」是描述愁緒本身，不是一種難以做到的修養。乙：顏真卿在「戰亂中」依然「一絲不苟的端正」，正是《論語》「造次必於是，顛沛必於是」——再倉促、再困頓都堅守原則。「知其不可而為之」強調明知不成仍去做，和「端正」的重點不同；「申申如也」是悠閒的樣子，不合戰亂；「人不知而不慍」講的是不求人知。所以選(C)。", "skill": "填空看關鍵字：「行之之難」要填一種「修養或道理」；「戰亂中…端正」要填「危難中不變」。用條件去刪選項。"}], "difficulty": "中", "label": "103指考", "year": 103, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk103-14", "exam": "zk103", "nums": [14], "form": "單題", "img": "img/zk103-14.png", "source": "陳善《捫蝨新話》", "author": "陳善", "genre": "筆記小品", "types": ["文意推論", "主旨寓意"], "passage": "楊大年、歐陽永叔，皆不喜杜詩。二公豈為不知文者，而好惡如此！晏元獻公嘗喜誦梅聖俞「寒魚猶著底，白鷺已飛前」之句，聖俞以為此非我之極致者，豈公偶自得意於其間乎？歐公亦云：「吾平生作文，唯尹師魯一見，展卷疾讀，五行俱下，便曉人深意處。」然則於餘人當有所不曉者多矣。所謂文章如精金美玉，市有定價，不可以口舌增損者，殆虛語耶？", "translation": "楊億、歐陽脩都不喜歡杜甫的詩。這兩位難道是不懂文章的人嗎？喜好厭惡卻是這樣！晏殊曾經喜歡朗誦梅堯臣「寒魚猶著底，白鷺已飛前」的句子，梅堯臣卻認為這不是自己最好的作品，難道是晏公剛好自己對這兩句特別有感覺嗎？歐陽脩也說：「我一生寫文章，只有尹洙一看，打開書卷快速閱讀，一眼看五行，就能明白我的深意。」這樣說來，其他人不懂他的地方應該很多了。所謂文章像純金美玉，市場上有固定價格，不能靠人的嘴巴增減價值，恐怕是空話吧？", "keywords": [{"w": "楊大年", "m": "楊億"}, {"w": "歐陽永叔", "m": "歐陽脩"}, {"w": "晏元獻公", "m": "晏殊"}, {"w": "梅聖俞", "m": "梅堯臣"}, {"w": "五行俱下", "m": "一眼看五行，形容讀得快"}, {"w": "殆", "m": "大概、恐怕"}], "questions": [{"n": 14, "qtype": "單選", "stem": "閱讀下文，選出最符合文意的選項：", "options": {"A": "文人往往各以所長，相輕所短", "B": "文章優劣各隨愛憎，難有定評", "C": "讀詩必須含英咀華，澄懷味象", "D": "鑑賞尤應振葉尋根，觀瀾索源"}, "answer": "B", "explain": "文中舉了三個例子：大文豪不喜歡杜詩、晏殊喜歡的句子梅堯臣自己不滿意、歐陽脩說只有尹洙看得懂他。結論是「文章像金玉有定價」這句話恐怕是空話——也就是文章好壞跟著讀者的喜好走，很難有一定的評價，(B)正確。(A)「文人相輕」是互相看不起，文中沒有人因為自己擅長什麼而輕視別人。(C)(D)是在講讀詩、鑑賞應有的方法，文章並沒有教人怎麼讀。", "skill": "舉例型短文，最後一句通常是結論；遇到「殆虛語耶」這種反問，要把它翻成肯定句來理解作者立場。"}], "difficulty": "易", "label": "103指考", "year": 103, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk103-15", "exam": "zk103", "nums": [15], "form": "單題", "img": "img/zk103-15.png", "source": "甲：羅隱〈鸚鵡〉；乙：歐陽脩〈畫眉鳥〉", "author": "羅隱、歐陽脩", "genre": "古典詩詞曲", "types": ["詩詞賞析", "主旨寓意", "比較閱讀"], "passage": "甲、莫恨雕籠翠羽殘，江南地暖隴西寒。勸君不用分明語，語得分明出轉難。\n乙、百囀千聲隨意移，山花紅紫樹高低。始知鎖向金籠聽，不及林間自在啼。", "translation": "甲：不要怨恨被關在雕花籠子裡、翠綠羽毛殘破，江南的氣候比你家鄉隴西溫暖多了。勸你說話不要說得太清楚，話說得越清楚，越難被放出籠子。\n乙：畫眉千百種鳴聲隨意變化，在高高低低開滿紅紫山花的樹間飛來飛去。這才知道把牠鎖在金籠裡聽牠唱，遠不如讓牠在林間自由自在地啼叫。", "keywords": [{"w": "雕籠", "m": "雕花的鳥籠"}, {"w": "隴西", "m": "隴山以西，唐人認為鸚鵡的產地"}, {"w": "分明語", "m": "話說得清清楚楚"}, {"w": "百囀", "m": "鳥鳴聲婉轉多變"}], "questions": [{"n": 15, "qtype": "單選", "stem": "對下引二詩的解說，正確的選項是：", "options": {"A": "二詩均因鳥的叫聲，而興感抒懷", "B": "二詩均對鳥難以放聲高鳴表示惋惜", "C": "甲詩中「君」指鸚鵡，也暗指逢迎諂媚者", "D": "乙詩以「樹」與「林」比喻無常的仕宦際遇"}, "answer": "A", "explain": "(A)正確：甲詩因鸚鵡會學人說話（牠的鳴聲）而有感，勸牠別說得太清楚；乙詩聽到畫眉「百囀千聲」，才體會籠中啼叫不如林間自在，兩首都是由鳥的聲音引發感觸。(B)錯：甲詩反而勸鸚鵡少說、說得含糊一點；乙詩惋惜的是失去自由，不是鳥不能高鳴。(C)錯：「君」確實指鸚鵡，但詩意是話說得太清楚、太有才能反而被困住，暗指直言或有才的人難以脫身，不是指逢迎諂媚的人。(D)錯：乙詩的「樹」「林」是畫眉自由生活的大自然，和「金籠」相對，象徵自由，不是比喻無常的官場。", "skill": "詠物詩先問：詩人在跟誰說話？這個物的什麼特點（這題是「聲音」）觸動了詩人？再想它和人的哪種處境相似。"}], "difficulty": "中", "label": "103指考", "year": 103, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk103-16", "exam": "zk103", "nums": [16, 17], "form": "題組", "img": "img/zk103-16.png", "source": "甲：李璟〈攤破浣溪沙〉；乙：晏殊〈浣溪沙〉", "author": "李璟、晏殊", "genre": "古典詩詞曲", "types": ["詩詞賞析", "句意理解", "比較閱讀"], "passage": "甲、菡萏香銷翠葉殘，西風愁起綠波間。還與韶光共憔悴，不堪看。細雨夢回鷄塞遠，小樓吹徹玉笙寒。簌簌淚珠多少恨，倚闌干。\n乙、一曲新詞酒一杯，去年天氣舊亭臺，夕陽西下幾時回。無可奈何花落去，似曾相識燕歸來，小園香徑獨徘徊。", "translation": "甲：荷花香氣消散、翠綠荷葉凋殘，秋風在綠波間吹起愁緒。荷花和美好的時光一同憔悴，令人不忍心看。細雨中從夢裡醒來，夢中的邊塞是那麼遙遠；小樓上把玉笙吹到最後一曲，笙已冰冷。撲簌簌的淚珠中含著多少怨恨，獨自倚著欄杆。\n乙：填一首新詞、喝一杯酒，天氣和去年一樣，亭臺也還是舊的，夕陽西下，什麼時候才會回來？花兒凋落讓人無可奈何，燕子歸來好像曾經認識。我在小園飄香的小路上獨自徘徊。", "keywords": [{"w": "菡萏", "m": "荷花"}, {"w": "韶光", "m": "美好的時光"}, {"w": "不堪看", "m": "不忍心看"}, {"w": "鷄塞", "m": "雞鹿塞，泛指邊塞"}, {"w": "吹徹", "m": "吹完最後一曲"}, {"w": "玉笙寒", "m": "笙管因夜寒而冰冷"}], "questions": [{"n": 16, "qtype": "單選", "stem": "下列「」內文句意涵的敘述，正確的選項是：", "options": {"A": "「西風愁起綠波間」意指秋天荷花凋殘，並寄寓愁緒", "B": "「不堪看」意謂不勝看，指眼前所見，令人目不暇給", "C": "「去年天氣舊亭臺」意謂受到去年天氣影響，亭臺老舊斑駁", "D": "「小園香徑獨徘徊」描寫歸燕在庭園小路上，孤獨穿梭往來"}, "answer": "A", "explain": "(A)正確：西風是秋風，吹在荷葉凋殘的綠波上，一個「愁」字把景物寫出情緒。(B)錯：「不堪看」是不忍心看，因為荷花和青春一起憔悴，而不是美景太多看不完。(C)錯：意思是天氣和去年一樣、亭臺也還是那座舊亭臺，景物依舊而人事已變，不是天氣讓亭臺變舊。(D)錯：獨自徘徊的是詞人自己，在小園中感嘆時光，不是燕子。", "skill": "詞句詮釋先找主語：中文詩詞常省略「我」，徘徊、倚闌干的多半是作者本人。"}, {"n": 17, "qtype": "單選", "stem": "下列關於主題、題材的分析，正確的選項是：", "options": {"A": "甲乙皆描寫迷離的夢中世界，以呈顯惆悵思緒", "B": "甲乙皆以悲秋為主題，表現出強烈的哀傷情感", "C": "甲藉荷花形味的消散，感歎眼前歡樂即將結束", "D": "乙藉花落燕歸的景象，表達對時光流逝的感思"}, "answer": "D", "explain": "(D)正確：乙詞花落了、燕子回來了，加上「夕陽西下幾時回」，都在感嘆時間一去不返。(A)錯：甲詞有「夢回」，但乙詞完全沒寫夢。(B)錯：甲詞寫秋天（西風、荷殘），乙詞寫的是暮春（花落、燕歸），而且晏殊的情感是淡淡的閒愁，不是強烈哀傷。(C)錯：甲詞荷花香消葉殘，是感嘆美好時光與人一同憔悴，並寄託對遠人的思念，並非「眼前正在歡樂、即將結束」。", "skill": "比較兩首詞，先替各自標出季節和核心意象，「皆」字的選項只要一首不符就錯。"}], "difficulty": "中", "label": "103指考", "year": 103, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk103-18", "exam": "zk103", "nums": [18], "form": "單題", "img": "img/zk103-18.png", "source": "多篇古文（〈岳陽樓記〉〈訓儉示康〉、《孟子》、〈勸學〉〈過秦論〉〈典論‧論文〉〈馮諼客孟嘗君〉〈左忠毅公軼事〉〈鴻門宴〉等）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "", "translation": "", "keywords": [{"w": "景", "m": "日光／大"}, {"w": "衣", "m": "衣服（名詞）／穿（動詞）"}, {"w": "數", "m": "方法、途徑／幾（數詞）"}, {"w": "賤", "m": "輕視"}, {"w": "畢", "m": "完畢"}], "questions": [{"n": 18, "qtype": "多選", "stem": "下列各組文句「」內的字，前後意義相同的選項是：", "options": {"A": "春和「景」明，波瀾不驚／我先王先民之「景」命，實式憑之", "B": "「衣」取蔽寒，食取充腹／七十者「衣」帛食肉，黎民不飢不寒", "C": "其「數」則始乎誦經，終乎讀禮／率罷散之卒，將「數」百之眾", "D": "常人貴遠「賤」近，向聲背實／左右以君「賤」之也，食以草具", "E": "公閱「畢」，即解貂覆生，為掩戶／若入前為壽，壽「畢」，請以劍舞"}, "answer": "DE", "explain": "(D)相同：都是「輕視」。一般人重視遠的、輕視近的（〈典論‧論文〉）；左右以為孟嘗君輕視馮諼（〈馮諼客孟嘗君〉）。(E)相同：都是「完畢」。左光斗讀完史可法的文章（〈左忠毅公軼事〉）；敬完酒之後（〈鴻門宴〉）。(A)不同：〈岳陽樓記〉「春和景明」的景是日光；「景命」的景是「大」。(B)不同：「衣取蔽寒」的衣是衣服，名詞；「七十者衣帛」是穿絲綢，動詞（《孟子》）。(C)不同：〈勸學〉「其數則始乎誦經」的數是學習的方法、途徑；〈過秦論〉「數百之眾」的數是幾，數詞。", "skill": "看到同一字一個在句首、一個後面接名詞（衣帛），先想詞性有沒有變，詞性變了意思通常也不同。"}], "difficulty": "中", "label": "103指考", "year": 103, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "勸學、馮諼客孟嘗君、鴻門宴、典論論文、岳陽樓記、左忠毅公軼事"}, {"id": "zk103-19", "exam": "zk103", "nums": [19], "form": "單題", "img": "img/zk103-19.png", "source": "《論語》、王維〈雜詩〉、〈馮諼客孟嘗君〉、《顏氏家訓》、〈燭之武退秦師〉", "author": "", "genre": "其他", "types": ["文化常識", "字詞解釋"], "passage": "", "translation": "", "keywords": [{"w": "君", "m": "對人的尊稱"}, {"w": "先生", "m": "對人的尊稱"}, {"w": "子", "m": "對男子的尊稱，您"}, {"w": "爾、汝曹", "m": "你、你們（一般稱呼，非敬詞）"}, {"w": "寡人", "m": "國君謙稱自己"}], "questions": [{"n": 19, "qtype": "多選", "stem": "古人稱自己常用謙詞，稱對方則常用敬詞。下列文句中使用敬詞的選項是：", "options": {"A": "爾愛其羊，我愛其禮", "B": "君自故鄉來，應知故鄉事", "C": "先生不羞，乃有意欲為收責於薛乎", "D": "若由此業，自致卿相，亦不願汝曹為之", "E": "吾不能早用子，今急而求子，是寡人之過也"}, "answer": "BCE", "explain": "(B)「君」是對人的尊稱，相當於「您」（王維〈雜詩〉）。(C)「先生」是孟嘗君對馮諼的尊稱。(E)「子」是鄭伯對燭之武的尊稱，同句的「寡人」是國君的謙稱。(A)「爾」是孔子對子貢說「你」，老師對學生的一般稱呼，不是敬詞。(D)「汝曹」是長輩對子孫說「你們」，也不是敬詞。", "skill": "敬詞常見：君、子、先生、足下、閣下；「爾、汝、若、而」都只是普通的「你」。"}], "difficulty": "易", "label": "103指考", "year": 103, "kind": "指考", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "燭之武退秦師、馮諼客孟嘗君"}, {"id": "zk103-20", "exam": "zk103", "nums": [20], "form": "單題", "img": "img/zk103-20.png", "source": "杜甫〈客至〉、《禮記‧禮運》、劉向奏疏（《漢書》）、《論語》、《荀子‧勸學》、〈岳陽樓記〉", "author": "", "genre": "其他", "types": ["虛詞句式", "句意理解"], "passage": "", "translation": "", "keywords": [{"w": "盤飧市遠無兼味", "m": "因為離市集遠，所以盤中菜餚沒有多樣（因果）"}, {"w": "質的", "m": "箭靶"}, {"w": "群枉", "m": "眾多邪曲的小人"}], "questions": [{"n": 20, "qtype": "多選", "stem": "杜甫〈客至〉：「盤飧市遠無兼味，樽酒家貧只舊醅。」前後二句都各自具有因果關係，下列文句也屬於這種句式的選項是：", "options": {"A": "謀閉而不興，盜竊亂賊而不作", "B": "讒邪進則眾賢退，群枉盛則正士消", "C": "君子易事而難說也，小人難事而易說也", "D": "質的張而弓矢至焉，林木茂而斧斤至焉", "E": "居廟堂之高則憂其民；處江湖之遠則憂其君"}, "answer": "BD", "explain": "杜詩是「因為市遠，所以無兼味；因為家貧，所以只有舊酒」，每句裡面自成因果。(B)正確：讒佞的人被進用，所以賢人退避；邪曲的人勢力大，所以正直之士消失，兩句各自是因果。(D)正確（《荀子‧勸學》）：箭靶張設好，所以弓箭射來；樹林茂盛，所以斧頭來砍，各自是因果。(A)錯（〈禮運‧大同〉）：陰謀被杜絕而不興起，盜賊作亂不發生，每句前後兩部分是同一件事的並列說明，不是前因後果。(C)錯（《論語》）：君子容易侍奉卻難以討好，前後是轉折對照，不是因果。(E)錯（〈岳陽樓記〉）：意思是無論在朝或在野都憂國憂民，強調的是「處在任何位置都憂」，屬於條件排比，並不是「居高位」造成「憂民」的因果。", "skill": "檢驗因果：在句中加上「因為…所以…」唸唸看，通順且合理才是因果；加不進去的是並列或轉折。"}], "difficulty": "難", "label": "103指考", "year": 103, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "大同與小康、勸學、岳陽樓記"}, {"id": "zk103-21", "exam": "zk103", "nums": [21], "form": "單題", "img": "img/zk103-21.png", "source": "《論語》、杜甫〈哀江頭〉、范仲淹〈岳陽樓記〉、鄭玄〈戒子益恩書〉、蘇軾〈念奴嬌〉", "author": "", "genre": "其他", "types": ["寫作手法"], "passage": "", "translation": "", "keywords": [{"w": "借代", "m": "用與事物密切相關的部分或特徵來代替該事物"}, {"w": "明眸皓齒", "m": "明亮的眼睛、潔白的牙齒，代楊貴妃"}, {"w": "錦鱗", "m": "彩色的鱗片，代魚"}, {"w": "黃巾", "m": "頭綁黃巾，代黃巾賊"}], "questions": [{"n": 21, "qtype": "多選", "stem": "寫作時提到某一事物，常運用與該事物密切相關的物件來代替，以求行文的生動變化。如蘇軾〈前赤壁賦〉：「方其破荊州，下江陵，順流而東也，舳艫千里，旌旗蔽空」，以船尾「舳」和船首「艫」代替「船」。下列詩文也運用此種表現方式的選項是：", "options": {"A": "歲寒，然後知松柏之後凋也", "B": "明眸皓齒今何在？血污遊魂歸不得", "C": "沙鷗翔集，錦鱗游泳；岸芷汀蘭，郁郁青青", "D": "黃巾為害，萍浮南北，復歸邦鄉。入此歲來，已七十矣", "E": "遙想公瑾當年，小喬初嫁了，雄姿英發，羽扇綸巾，談笑間，強虜灰飛煙滅"}, "answer": "BCD", "explain": "題目說的是「借代」。(B)杜甫〈哀江頭〉用「明眸皓齒」（美人的眼睛牙齒）代替楊貴妃。(C)〈岳陽樓記〉用「錦鱗」（魚身上的彩色鱗片）代替魚。(D)鄭玄〈戒子益恩書〉用「黃巾」（叛軍頭上綁的黃頭巾）代替黃巾賊。(A)錯：《論語》的松柏是用來象徵君子堅貞的品格，屬於象徵，不是用部分代替整體。(E)錯：「羽扇綸巾」是描寫周瑜手拿羽扇、頭戴青絲巾的瀟灑裝扮，周瑜（公瑾）本人已直接寫出，沒有拿裝扮去「代替」他。", "skill": "借代的檢驗法：把那個詞換回它代替的東西（錦鱗→魚），句子意思不變，才是借代；換了以後變怪的就不是。"}], "difficulty": "中", "label": "103指考", "year": 103, "kind": "指考", "textcat": "文學文本", "textcat2": "部定古文", "linked_core": "岳陽樓記、赤壁賦"}, {"id": "zk103-24", "exam": "zk103", "nums": [24], "form": "單題", "img": "img/zk103-24.png", "source": "章學誠《文史通義‧朱陸》", "author": "章學誠", "genre": "說理議論", "types": ["文意推論", "主旨寓意"], "passage": "朱、陸本不同，又況後學之嘵嘵乎？但門戶既分，則欲攻朱者，必竊陸、王之形似；欲攻陸、王，必竊朱子之形似。朱之形似必繁密，陸、王形似必空靈，一定之理也。而自來門戶之交攻，俱是專己守殘，束書不觀，而高談性天之流也。則自命陸、王以攻朱者，固偽陸、王；即自命朱氏以攻陸、王者，亦偽陸、王，不得號為偽朱也。同一門戶，而陸、王有偽，朱無偽者，空言易，而實學難也。", "translation": "朱熹和陸九淵的學說本來就不同，何況後來學者的爭吵不休呢？但是門派一旦分開，想攻擊朱學的人，一定會套用陸、王學說的外表；想攻擊陸、王的人，一定會套用朱學的外表。朱學的外表一定是繁瑣綿密，陸王學的外表一定是空靈玄妙，這是一定的道理。可是自古以來門派互相攻擊的，全是固執己見、守著殘缺知識、把書綁起來不讀，只會高談心性天理的人。所以自稱陸、王來攻擊朱學的，固然是假陸王；就連自稱朱學來攻擊陸、王的，其實也是假陸王，不能稱作假朱學。同一種門派之爭，陸王有假的、朱學卻沒有假的，是因為空談容易，而真正的實學很難啊。", "keywords": [{"w": "嘵嘵", "m": "爭辯不休的樣子"}, {"w": "形似", "m": "外表相似"}, {"w": "專己守殘", "m": "固執己見、抱守殘缺"}, {"w": "束書不觀", "m": "把書捆起來不讀"}, {"w": "性天", "m": "心性與天理"}], "questions": [{"n": 24, "qtype": "多選", "stem": "閱讀下文，依文意選出敘述正確的選項：", "options": {"A": "陸、王學與朱學比較，前者遠勝後者", "B": "陸、王學者輕率，常攻擊朱子學說為空言", "C": "朱學之學者求真，批評陸、王學說為繁密", "D": "以朱學自命而攻陸、王者，未必真知朱學", "E": "作者崇尚實學，鄙視束書不觀，而高談性天者"}, "answer": "DE", "explain": "(D)正確：作者說自稱朱學去攻擊陸王的，其實也只是「偽陸、王」——他們不讀書、只會空談，根本沒有朱學那種繁密的實學功夫，所以並不真懂朱學。(E)正確：作者批評門戶相攻的人都是「束書不觀，而高談性天」，結尾又說「空言易，而實學難」，可見他看重實學。(A)錯：作者沒有說陸王比朱學好，反而說朱學難以假冒，因為實學難。(B)錯：文中沒有說陸王學者攻擊朱子是空言；「空靈」是陸王學的外表特徵。(C)錯：「繁密」是朱學自己的外表特徵，不是朱學者拿來批評陸王的話。", "skill": "學術論辯文要先畫出「誰攻擊誰、各自的特徵」對照表，再看作者對兩邊的評價。"}], "difficulty": "難", "label": "103指考", "year": 103, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc104-6", "exam": "xc104", "nums": [6], "form": "單題", "img": "img/xc104-6.png", "source": "楊喚〈花與果實〉（選項為古典詩詞句）", "author": "楊喚", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感", "比較閱讀"], "passage": "(A)吾謀適不用，勿謂知音稀\n(B)歲月一何易，寒暑忽已革\n(C)花自飄零水自流，一種相思，兩處閒愁\n(D)不忍登高臨遠，望故鄉渺邈，歸思難收", "translation": "(A)我的謀略剛好沒被採用，不要說是知音太少。(B)歲月變換得多麼快啊，寒來暑往忽然又已更替。(C)花自顧自地飄落，水自顧自地流去；同一種相思，分在兩地各自愁悶。(D)不忍心登上高處遠望，看故鄉遙遠渺茫，思歸的心情難以收拾。", "keywords": [{"w": "適", "m": "恰好"}, {"w": "一何", "m": "多麼"}, {"w": "革", "m": "改變、更替"}, {"w": "渺邈", "m": "遙遠"}], "questions": [{"n": 6, "qtype": "單選", "stem": "依據詩意，作者感到被「嚙咬」、「絞傷」的原因，最可能是：花是無聲的音樂／果實是最動人的書籍／當它們在春天演奏，秋天出版／我的日子被時計的齒輪／給無情地嚙咬，絞傷／庭中便飛散著我的心的碎片／階下就響起我的一片嘆息（楊喚〈花與果實〉）", "options": {"A": "吾謀適不用，勿謂知音稀", "B": "歲月一何易，寒暑忽已革", "C": "花自飄零水自流，一種相思，兩處閒愁", "D": "不忍登高臨遠，望故鄉渺邈，歸思難收"}, "answer": "B", "explain": "詩中「時計的齒輪」是時鐘，日子被時鐘「無情地嚙咬、絞傷」，加上花在春天開、果在秋天結，表示一年轉眼就過，作者是在感嘆時光飛逝。(B)「歲月一何易，寒暑忽已革」正是嘆時間流轉迅速，最貼近。(A)是懷才不遇。(C)是兩地相思。(D)是思鄉懷歸，都和時間無關。", "skill": "現代詩的意象先「翻譯」成具體意思（時計齒輪＝時間），再到文言選項中找同一個主題。"}], "difficulty": "易", "label": "104學測", "year": 104, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc104-9", "exam": "xc104", "nums": [9], "form": "單題", "img": "img/xc104-9.png", "source": "賀詩二首（出處待查）", "author": "", "genre": "古典詩詞曲", "types": ["文化常識", "詩詞賞析"], "passage": "甲、三代冠裳應接武，百年琴瑟喜同幃。今朝福曜潘門燦，戲舞堂前著彩衣。\n乙、榮遷指日向南行，福曜遙臨萬里程。民已馨香生佛事，公應此地不忘情。", "translation": "甲：家中三代都有做官的人，子孫應當繼承先人的腳步；夫妻相伴百年，歡喜地同在一個帷帳下白頭偕老。今天福星照耀潘家，兒孫像老萊子一樣在堂前穿著彩衣歡舞，為長輩祝壽。乙：您不日就要升官往南方去了，福星遠遠照臨萬里旅程。百姓已經像供奉活佛一樣燒香感念您，您也應對這個地方念念不忘。", "keywords": [{"w": "冠裳", "m": "官帽與禮服，代指官宦"}, {"w": "接武", "m": "步履相接，比喻繼承前人"}, {"w": "百年琴瑟", "m": "夫妻相伴到老"}, {"w": "彩衣", "m": "老萊子年老仍穿彩衣娛親的典故，用於祝壽"}, {"w": "福曜", "m": "福星"}, {"w": "榮遷", "m": "升官調任"}], "questions": [{"n": 9, "qtype": "單選", "stem": "依甲、乙二詩的祝賀內容，分別選用相應的題辭，最恰當的選項是：甲、三代冠裳應接武，百年琴瑟喜同幃。今朝福曜潘門燦，戲舞堂前著彩衣。乙、榮遷指日向南行，福曜遙臨萬里程。民已馨香生佛事，公應此地不忘情。", "options": {"A": "天賜遐齡／大展鴻猷", "B": "天賜遐齡／里仁為美", "C": "昌大門楣／大展鴻猷", "D": "昌大門楣／里仁為美"}, "answer": "A", "explain": "甲詩的線索：「百年琴瑟」是夫妻相伴百年、白頭偕老；「戲舞堂前著彩衣」用老萊子七十歲還穿彩衣逗父母開心的典故，表示兒孫在堂前為長輩祝壽；「三代冠裳」也顯示家族綿延、人丁興旺。合起來是為年高的長輩（夫婦）祝壽，題辭用「天賜遐齡」（上天賜予長壽）。「昌大門楣」是賀生子或光耀門第，甲詩重點不在這裡。乙詩「榮遷指日向南行」是祝賀升官調任，題辭用「大展鴻猷」（大大施展宏大的謀略）；「里仁為美」用於賀遷居新屋，與升官不同。答案(A)。", "skill": "題辭題先圈出詩中的「事件詞」與典故（彩衣娛親＝壽、榮遷＝升官、琴瑟新婚／百年＝婚或偕老），再對應常用題辭；「百年琴瑟」要配合上下文判斷是新婚還是老夫妻。"}], "difficulty": "中", "label": "104學測", "year": 104, "kind": "學測", "textcat": "生活情境文本", "textcat2": "", "linked_core": ""}, {"id": "xc104-10", "exam": "xc104", "nums": [10], "form": "單題", "img": "img/xc104-10.png", "source": "《易經》、《詩經》、《孟子》、《論語》", "author": "多位作者", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "(A)戰戰兢兢，如臨深淵，如履薄冰\n(B)非其君不事，非其民不使。治則進，亂則退\n(C)原泉混混，不舍晝夜，盈科而後進，放乎四海\n(D)可與共學，未可與適道；可與適道，未可與立；可與立，未可與權", "translation": "(A)小心謹慎，就像站在深淵邊、走在薄冰上。(B)不是理想的君主不去事奉，不是理想的百姓不去使喚；天下太平就出來做官，天下大亂就退隱。(C)有源頭的泉水滾滾湧出，日夜不停，把坑洼填滿後再向前流，一直流到四海。(D)可以一起學習的人，未必能一起走向正道；能一起走向正道的，未必能一起堅守；能一起堅守的，未必能一起通權達變。", "keywords": [{"w": "原泉", "m": "有源頭的泉水"}, {"w": "混混", "m": "水流不斷的樣子"}, {"w": "舍", "m": "停止"}, {"w": "科", "m": "坑洼"}, {"w": "權", "m": "權衡變通"}], "questions": [{"n": 10, "qtype": "單選", "stem": "「天行健，君子以自強不息」，強調剛健進取的精神。下列文句，最符合此種精神的選項是：", "options": {"A": "戰戰兢兢，如臨深淵，如履薄冰", "B": "非其君不事，非其民不使。治則進，亂則退", "C": "原泉混混，不舍晝夜，盈科而後進，放乎四海", "D": "可與共學，未可與適道；可與適道，未可與立；可與立，未可與權"}, "answer": "C", "explain": "「自強不息」重點在持續不斷、努力向前。(C)泉水日夜不停地流，填滿坑洼再前進，終於流入四海，比喻有本源的人不斷努力、循序漸進，最符合。(A)強調謹慎小心，不是進取。(B)是伯夷「治則進，亂則退」的出處態度，講選擇而非不停進取。(D)講學習與修養的層次，一層比一層難，不是強調剛健不息。", "skill": "抓題幹關鍵詞（不息＝不停、健＝剛強），到選項裡找同義的字眼（不舍晝夜、進）。"}], "difficulty": "易", "label": "104學測", "year": 104, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc104-11", "exam": "xc104", "nums": [11], "form": "單題", "img": "img/xc104-11.png", "source": "《戰國策‧馮諼客孟嘗君》、諸葛亮〈出師表〉、《左傳‧燭之武退秦師》、魏徵〈諫太宗十思疏〉", "author": "多位作者", "genre": "史傳人物", "types": ["句意理解", "人物情感"], "passage": "(A)以責賜諸民，因燒其券\n(B)開張聖聽，以光先帝遺德\n(C)焉用亡鄭以陪鄰？鄰之厚，君之薄也\n(D)怨不在大，可畏惟人；載舟覆舟，所宜深慎；奔車朽索，其可忽乎", "translation": "(A)把債款賞賜給百姓，並燒掉債券。(B)廣開言路、聽取意見，來發揚先帝留下的美德。(C)何必滅掉鄭國來增強鄰國晉國呢？鄰國實力增強，就等於您的實力削弱了。(D)怨恨不在於大小，可怕的是民心；水能載舟也能覆舟，應該深深謹慎；用腐朽的繩索駕馭奔馳的車，怎麼可以疏忽呢？", "keywords": [{"w": "責", "m": "通「債」"}, {"w": "券", "m": "債券、借據"}, {"w": "陪", "m": "增益"}, {"w": "厚、薄", "m": "實力增強、削弱"}, {"w": "惟人", "m": "在於百姓"}], "questions": [{"n": 11, "qtype": "單選", "stem": "下列關於人物言語或行為的分析，錯誤的選項是︰", "options": {"A": "馮諼詐稱孟嘗君之命，「以責賜諸民，因燒其券」，反映出道義重於私利的政治觀點", "B": "諸葛亮建議後主要「開張聖聽，以光先帝遺德」，是希望後主能諮諏善道，察納雅言", "C": "燭之武勸秦伯「焉用亡鄭以陪鄰？鄰之厚，君之薄也」，提醒他不要用自己的薄情寡義來襯托鄰國國君的仁厚寬容", "D": "魏徵諫太宗「怨不在大，可畏惟人；載舟覆舟，所宜深慎；奔車朽索，其可忽乎」，強調民心向背對主政者的重要"}, "answer": "C", "explain": "(C)錯誤：燭之武說的「厚、薄」是指國家實力。秦晉相鄰，鄭國滅亡後土地歸晉，晉國變強（厚），相對秦國就變弱（薄），他是用利害關係說服秦伯，和國君的仁厚、薄情無關。(A)正確：馮諼燒債券為孟嘗君「市義」，收買民心，是重義輕利。(B)正確：「開張聖聽」就是廣開言路，與〈出師表〉後文「諮諏善道，察納雅言」一致。(D)正確：「可畏惟人」「載舟覆舟」都在說民心能決定政權存亡。", "skill": "「厚／薄」「大／小」這類形容詞在外交辭令中常指國力，先想清楚說話者的立場與利害，再判斷詞義。"}], "difficulty": "易", "label": "104學測", "year": 104, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "燭之武退秦師、馮諼客孟嘗君、出師表、諫太宗十思疏"}, {"id": "xc104-14", "exam": "xc104", "nums": [14, 15], "form": "題組", "img": "img/xc104-14.png", "source": "紀昀《閱微草堂筆記‧姑妄聽之》", "author": "紀昀", "genre": "筆記小品", "types": ["虛詞句式", "文意推論"], "passage": "人情狙詐，無過於京師。余嘗買羅小華墨十六鋌，漆匣黯敝，真舊物也。試之，乃摶泥而染以黑色，其上白霜，亦盦於濕地所生。又丁卯鄉試，在小寓買燭，爇之不燃，乃泥質而冪以羊脂。又燈下有唱賣爐鴨者，從兄萬周買之。乃盡食其肉，而完其全骨，內傅以泥，外糊以紙，染為炙煿之色，塗以油，惟兩掌頭頸為真。又奴子趙平以二千錢買得皮靴，甚自喜。一日驟雨，著以出，徒跣而歸，蓋靿則烏油高麗紙揉作皺紋，底則糊黏敗絮，緣之以布。", "translation": "人心狡詐，沒有比京城更厲害的。我曾經買過十六錠羅小華製的墨，漆盒又暗又舊，看起來真是古物。一試用，原來是把泥土捏成形再染成黑色，上面的白霜，也是放在潮濕地上悶出來的。又有一次丁卯年鄉試，在小旅舍買蠟燭，點了卻燒不起來，原來是泥做的，外面包一層羊油。又有在燈下叫賣烤鴨的，堂兄萬周買了一隻，原來（賣家）已經把鴨肉吃光，只保留完整的骨架，裡面塗上泥，外面糊上紙，染成烤過的顏色，再塗上油，只有兩隻腳掌和頭頸是真的。又有僕人趙平花二千錢買了一雙皮靴，非常得意。有一天下大雨，穿著出門，結果光著腳回來，原來靴筒是用黑油塗的高麗紙揉出皺紋做的，靴底是用破棉絮糊黏起來，再用布縫邊。", "keywords": [{"w": "狙詐", "m": "狡猾奸詐"}, {"w": "鋌", "m": "通「錠」，量詞"}, {"w": "黯敝", "m": "暗淡破舊"}, {"w": "摶", "m": "捏聚成團"}, {"w": "盦", "m": "覆蓋"}, {"w": "爇", "m": "燒"}, {"w": "冪", "m": "覆蓋"}, {"w": "徒跣", "m": "光著腳"}, {"w": "靿", "m": "靴筒"}], "questions": [{"n": 14, "qtype": "單選", "stem": "依據文意，選出依序最適合填入□內的選項：（余□買羅小華墨十六鋌……□兩掌頭頸為真……□靿則烏油高麗紙揉作皺紋）", "options": {"A": "初／果／蓋", "B": "初／惟／殆", "C": "嘗／果／殆", "D": "嘗／惟／蓋"}, "answer": "D", "explain": "第一空：「余□買羅小華墨」是回憶過去的一件事，填「嘗」（曾經）；「初」是起初，用於事情的開端，與後文「又……又……」列舉多件事不搭。第二空：烤鴨的肉被吃光、骨頭裹泥，「□兩掌頭頸為真」是說只有腳掌和頭頸是真的，填「惟」（只有）；「果」是果然，意思不通。第三空：趙平光腳回來，接著說明原因「原來靴筒是紙做的」，填「蓋」（原來是、因為）；「殆」是大概、恐怕，屬推測語氣，但後文是確定的事實。答案(D)。", "skill": "虛詞填空先判斷語氣：回憶往事用「嘗」，限定範圍用「惟」，說明原因用「蓋」，不確定的推測才用「殆」。"}, {"n": 15, "qtype": "單選", "stem": "下列與文中「黑心商品」相關的敘述，正確的選項是：", "options": {"A": "賣家藉舊盒及白霜將墨偽成古物", "B": "買主吃完鴨肉才發現鴨骨為泥製", "C": "商人先藉真品取信以利銷售贗品", "D": "購買者皆因一時貪圖廉價而受騙"}, "answer": "A", "explain": "(A)正確：「漆匣黯敝，真舊物也」「其上白霜，亦盦於濕地所生」，用破舊盒子和人工白霜讓墨看起來像古物。(B)錯誤：鴨肉早被賣家吃光（「乃盡食其肉」），買主根本沒肉可吃；而且骨頭是真的，是骨架裡外裹泥、糊紙。(C)錯誤：文中沒有先賣真品取得信任的情節。(D)錯誤：文中沒有提到價格便宜，趙平還花了二千錢；受騙是因為仿冒手法高明。", "skill": "注意「乃」字：「乃盡食其肉」的「乃」是「原來」，揭露真相，分清楚是誰吃了肉。"}], "difficulty": "中", "label": "104學測", "year": 104, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc104-17", "exam": "xc104", "nums": [17], "form": "單題", "img": "img/xc104-17.png", "source": "陶淵明〈桃花源記〉、顧炎武〈廉恥〉、歸有光〈項脊軒志〉、方苞〈左忠毅公軼事〉、蘇軾〈赤壁賦〉等（後句多出自古典白話小說）", "author": "多位作者", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)阡陌交通，雞犬相聞／賈赦交通外官，依勢凌弱\n(B)廉、恥，立人之大節／沈鍊每日間與地方人等，講論忠孝大節及古來忠臣義士的故事\n(C)室僅方丈，可容一人居／寺中若有此秘徑地道，敝寺方丈事先自會知照各派首領，怎能容這些邪魔外道從容脫身\n(D)汝復輕身而昧大義，天下事誰可支拄者／不要短見！此非娘子自肯失身，這是所遭不幸，娘子立志自明，今若輕身一死，有許多不便\n(E)縱一葦之所如，凌萬頃之茫然／看守兵役，見多九公不是本處打扮，有幾個飛忙去請通使，一面預備車馬，將多九公送至迎賓館。唐敖茫然不解，只好跟在後面", "translation": "", "keywords": [{"w": "交通", "m": "交錯相通；勾結往來"}, {"w": "大節", "m": "重大的節操"}, {"w": "方丈", "m": "一丈見方；寺院住持"}, {"w": "輕身", "m": "不愛惜生命"}, {"w": "茫然", "m": "廣闊無邊的樣子；不明白的樣子"}], "questions": [{"n": 17, "qtype": "多選", "stem": "下列各組「」內詞語，前後意義相同的選項是：", "options": {"A": "阡陌「交通」，雞犬相聞／賈赦「交通」外官，依勢凌弱", "B": "廉、恥，立人之「大節」／沈鍊每日間與地方人等，講論忠孝「大節」及古來忠臣義士的故事", "C": "室僅「方丈」，可容一人居／寺中若有此秘徑地道，敝寺「方丈」事先自會知照各派首領，怎能容這些邪魔外道從容脫身", "D": "汝復「輕身」而昧大義，天下事誰可支拄者／不要短見！此非娘子自肯失身，這是所遭不幸，娘子立志自明，今若「輕身」一死，有許多不便", "E": "縱一葦之所如，凌萬頃之「茫然」／看守兵役，見多九公不是本處打扮，有幾個飛忙去請通使，一面預備車馬，將多九公送至迎賓館。唐敖「茫然」不解，只好跟在後面"}, "answer": "BD", "explain": "(A)錯誤：前者〈桃花源記〉「交通」是道路交錯相通；後者是「勾結、往來」。(B)正確：兩者「大節」都是重大的節操、根本的品德。(C)錯誤：前者「方丈」是一丈見方，形容房間小；後者是寺院的住持。(D)正確：兩者「輕身」都是輕視生命、輕易犧牲：左光斗責備史可法不愛惜自己；勸娘子不要輕易尋死。(E)錯誤：前者〈赤壁賦〉「茫然」形容江面廣闊無邊；後者是不明白、摸不著頭緒。", "skill": "同形詞常有「古義／今義」或「字面／引申」兩種意思，把今天的用法和文中語境對比一下就能分辨。"}], "difficulty": "中", "label": "104學測", "year": 104, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "桃花源記、赤壁賦、項脊軒志、廉恥、左忠毅公軼事"}, {"id": "xc104-18", "exam": "xc104", "nums": [18], "form": "單題", "img": "img/xc104-18.png", "source": "范仲淹〈岳陽樓記〉、郁永河《裨海紀遊》、韓愈〈師說〉、蒲松齡《聊齋誌異‧勞山道士》、歐陽脩〈醉翁亭記〉", "author": "多位作者", "genre": "其他", "types": ["寫作手法", "句意理解"], "passage": "(A)予觀夫巴陵勝狀，在洞庭一湖。銜遠山，吞長江，浩浩湯湯，橫無際涯\n(B)復越峻坂五六，值大溪。溪廣四五丈，水潺潺巉石間，與石皆作藍靛色\n(C)聖人無常師。孔子師郯子、萇弘、師襄、老聃。郯子之徒，其賢不及孔子\n(D)一道士坐蒲團上，素髮垂領，而神觀爽邁。叩而與語，理甚玄妙。請師之\n(E)禽鳥知山林之樂，而不知人之樂；人知從太守遊而樂，而不知太守之樂其樂也", "translation": "(A)我看巴陵的美景，全在洞庭湖。它銜接遠山，吞納長江，水勢浩大，寬廣無邊。(B)又越過五六座陡坡，遇到一條大溪。溪寬四五丈，溪水在險峻的石頭間潺潺流著，水和石頭都是藍靛色。(C)聖人沒有固定的老師。孔子曾向郯子、萇弘、師襄、老聃學習，郯子這些人的賢能都比不上孔子。(D)一個道士坐在蒲團上，白髮垂到脖子，神采爽朗超邁。上前和他交談，道理非常玄妙，於是請求拜他為師。(E)禽鳥知道山林的快樂，卻不知道人的快樂；人們知道跟隨太守遊玩的快樂，卻不知道太守是以他們的快樂為快樂。", "keywords": [{"w": "勝狀", "m": "美好的景色"}, {"w": "湯湯", "m": "水勢浩大"}, {"w": "值", "m": "遇到"}, {"w": "巉", "m": "險峻"}, {"w": "常師", "m": "固定的老師"}, {"w": "神觀爽邁", "m": "神采爽朗超群"}], "questions": [{"n": 18, "qtype": "多選", "stem": "《論語》：「吾日三省吾身。為人謀而不忠乎？與朋友交而不信乎？傳不習乎？」句中畫底線處描述、解說「三省吾身」的內容。下列畫底線的文句，是對其前面的文句（未畫底線者）進行「描述、解說」的選項是：（底線：A「銜遠山，吞長江，浩浩湯湯，橫無際涯」；B「溪廣四五丈，水潺潺巉石間，與石皆作藍靛色」；C「孔子師郯子、萇弘、師襄、老聃。郯子之徒，其賢不及孔子」；D「叩而與語，理甚玄妙。請師之」；E「人知從太守遊而樂，而不知太守之樂其樂也」）", "options": {"A": "予觀夫巴陵勝狀，在洞庭一湖。銜遠山，吞長江，浩浩湯湯，橫無際涯", "B": "復越峻坂五六，值大溪。溪廣四五丈，水潺潺巉石間，與石皆作藍靛色", "C": "聖人無常師。孔子師郯子、萇弘、師襄、老聃。郯子之徒，其賢不及孔子", "D": "一道士坐蒲團上，素髮垂領，而神觀爽邁。叩而與語，理甚玄妙。請師之", "E": "禽鳥知山林之樂，而不知人之樂；人知從太守遊而樂，而不知太守之樂其樂也"}, "answer": "ABC", "explain": "判斷底線句是不是在「展開說明」前面那句。(A)正確：前面說巴陵美景在洞庭湖，底線具體描寫洞庭湖的氣勢。(B)正確：前面說遇到大溪，底線描寫大溪的寬度、水流、顏色。(C)正確：前面提出「聖人無常師」，底線舉孔子向多位老師學習為例來解說。(D)錯誤：前面寫道士的外貌，底線是接下來的動作（上前交談、拜師），是情節往前推進，不是描述前句。(E)錯誤：前後兩句是並列的對比（禽鳥／人），底線並沒有解說前句。", "skill": "檢查底線句：如果把它刪掉，前句的內容是否變得不具體？是的話就是「描述解說」；如果底線是新的動作或另一件事，就不是。"}], "difficulty": "中", "label": "104學測", "year": 104, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "師說、岳陽樓記、醉翁亭記、勞山道士、裨海紀遊"}, {"id": "xc104-19", "exam": "xc104", "nums": [19], "form": "單題", "img": "img/xc104-19.png", "source": "《孟子》、《大學》、《中庸》", "author": "多位作者", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "(A)君之視臣如土芥，則臣視君如寇讎\n(B)庖有肥肉，廄有肥馬；民有飢色，野有餓莩，此率獸而食人也\n(C)壞宮室以為汙池，民無所安息；棄田以為園囿，使民不得衣食\n(D)小人閒居為不善，無所不至，見君子而後厭然，揜其不善，而著其善\n(E)日省月試，既禀稱事，所以勸百工也；送往迎來，嘉善而矜不能，所以柔遠人也", "translation": "(A)君主把臣子看成泥土小草，臣子就把君主看成強盜仇人。(B)廚房裡有肥肉，馬廄裡有肥馬，百姓卻面有飢色，郊野有餓死的人，這是帶領野獸來吃人啊。(C)拆毀民房來做池塘，百姓沒有地方安居；廢棄農田來做園林，使百姓得不到衣食。(D)小人獨處時做壞事，什麼都做得出來，見到君子才遮遮掩掩，藏起壞處，顯示好處。(E)每天察看、每月考核，給的糧餉與工作相稱，這是用來勸勉各種工匠的；送往迎來，嘉獎有才能的人並同情能力不足的人，這是用來安撫遠方之人的。", "keywords": [{"w": "土芥", "m": "泥土與小草，比喻輕賤"}, {"w": "寇讎", "m": "強盜仇敵"}, {"w": "莩", "m": "通「殍」，餓死的人"}, {"w": "汙池", "m": "池塘"}, {"w": "園囿", "m": "養禽獸的園林"}, {"w": "厭然", "m": "掩藏的樣子"}, {"w": "既禀", "m": "供給的糧食"}], "questions": [{"n": 19, "qtype": "多選", "stem": "下列敘述，旨在說明因執政者施政未當，致使百姓陷入困境的選項是：", "options": {"A": "君之視臣如土芥，則臣視君如寇讎", "B": "庖有肥肉，廄有肥馬；民有飢色，野有餓莩，此率獸而食人也", "C": "壞宮室以為汙池，民無所安息；棄田以為園囿，使民不得衣食", "D": "小人閒居為不善，無所不至，見君子而後厭然，揜其不善，而著其善", "E": "日省月試，既禀稱事，所以勸百工也；送往迎來，嘉善而矜不能，所以柔遠人也"}, "answer": "BC", "explain": "要同時符合「執政者施政不當」＋「百姓受苦」。(A)講君臣之間的對待關係，對象是「臣」不是百姓。(B)正確：統治者的廚房馬廄豐足，百姓卻挨餓甚至餓死，是施政不當害民。(C)正確：拆民房、廢農田來蓋池塘園林，讓百姓無處住、沒衣食。(D)講小人的偽善，是個人修養，與施政無關。(E)講治國的好方法（勸百工、柔遠人），是正面施政。", "skill": "題幹有兩個條件時，逐項檢查「主語是誰」「受害的是誰」，缺一個就排除。"}], "difficulty": "易", "label": "104學測", "year": 104, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc104-20", "exam": "xc104", "nums": [20], "form": "單題", "img": "img/xc104-20.png", "source": "李白〈酬中都小吏攜斗酒雙魚於逆旅見贈〉、杜甫〈閿鄉姜七少府設鱠戲贈長歌〉", "author": "李白、杜甫", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法", "比較閱讀"], "passage": "甲、意氣相傾兩相顧，斗酒雙魚表情素。雙鰓呀呷鰭鬣張，蹳剌銀盤欲飛去。呼兒拂几霜刃揮，紅肌花落白雪霏。為君下箸一餐飽，醉著金鞍上馬歸。\n乙、姜侯設鱠當嚴冬，昨日今日皆天風。河凍未漁不易得，鑿冰恐侵河伯宮。饔人受魚鮫人手，洗魚磨刀魚眼紅。無聲細下飛碎雪，有骨已剁胔春蔥。", "translation": "甲：彼此意氣相投、互相眷顧，你帶著一斗酒和兩條魚來表達情意。魚的兩鰓一張一合，魚鰭張開，在銀盤上撥剌跳動像要飛走。叫孩子擦淨桌子，揮動雪亮的刀，紅色魚肉像花瓣落下，白色細片像雪花紛飛。為了你我吃得飽飽的，醉了就跨上金鞍騎馬回去。乙：姜少府在寒冬設生魚片宴，昨天今天都颳著大風。河水結冰還沒捕魚，魚很難得，鑿冰怕驚擾河伯的宮殿。廚師從漁夫手中接過魚，洗魚磨刀，魚眼還紅著（新鮮）。刀下無聲，細細切下像碎雪紛飛；有骨的部分已剁去，留下魚肉拌上春蔥。", "keywords": [{"w": "情素", "m": "真情"}, {"w": "呀呷", "m": "魚鰓開合的樣子"}, {"w": "蹳剌", "m": "魚跳動的聲音"}, {"w": "霜刃", "m": "雪亮的刀"}, {"w": "鱠", "m": "細切的生魚肉"}, {"w": "饔人", "m": "廚師"}, {"w": "胔春蔥", "m": "去骨留肉而雜以春蔥"}], "questions": [{"n": 20, "qtype": "多選", "stem": "閱讀下列二詩，選出寫作特色分析正確的選項：", "options": {"A": "二詩述及鮮魚料理過程，皆呈現刀工的俐落細膩", "B": "二詩皆運用視覺意象「雪」，凸顯魚肉的纖細瑩白", "C": "甲詩以「雙鰓呀呷鰭鬣張」、「蹳剌銀盤」等動態描寫，呈現活魚的生鮮", "D": "乙詩以「當嚴冬」、「河凍未漁不易得」等敘述，強調主人設餐宴的用心", "E": "二詩分以「欲飛去」與「有骨已剁」，形容飄然欲仙、蝕骨銷魂的美食享受"}, "answer": "ABCD", "explain": "(A)正確：甲「霜刃揮，紅肌花落白雪霏」、乙「磨刀……無聲細下飛碎雪」，都寫刀工快而細。(B)正確：甲「白雪霏」、乙「飛碎雪」，都用雪比喻切得細白的魚肉。(C)正確：鰓開合、鰭張開、在盤上跳動，寫魚非常鮮活。(D)正確：嚴冬河面結冰，魚很難得，主人還是設宴，可見用心。(E)錯誤：「欲飛去」寫活魚在盤中跳動像要飛走，「有骨已剁」是說去掉骨頭，都是寫料理實況，不是形容吃得飄飄欲仙、銷魂蝕骨。", "skill": "比較兩首詩時，先在兩首各自圈出同類描寫（刀、雪、魚的動態），再判斷選項的詮釋是否過度引申。"}], "difficulty": "中", "label": "104學測", "year": 104, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc104-21", "exam": "xc104", "nums": [21], "form": "單題", "img": "img/xc104-21.png", "source": "《莊子‧秋水》、劉向《說苑‧談叢》", "author": "莊子、劉向", "genre": "寓言故事", "types": ["比較閱讀", "主旨寓意", "寫作手法"], "passage": "甲、夫鵷鶵，發於南海而飛於北海，非梧桐不止，非練實不食，非醴泉不飲。於是鴟得腐鼠，鵷鶵過之，仰而視之曰：「嚇！」\n乙、梟逢鳩。鳩曰：「子將安之？」梟曰：「我將東徙。」鳩曰：「何故？」梟曰：「鄉人皆惡我鳴，以故東徙。」鳩曰：「子能更鳴可矣，不能更鳴，東徙猶惡子之聲。」", "translation": "甲：鵷鶵從南海出發飛往北海，不是梧桐樹不棲息，不是竹子的果實不吃，不是甘甜的泉水不喝。這時一隻貓頭鷹得到一隻腐爛的老鼠，鵷鶵從牠上空飛過，貓頭鷹抬頭看著牠，發出「嚇！」的聲音（怕牠搶）。乙：梟遇到斑鳩。斑鳩問：「你要去哪裡？」梟說：「我要往東搬家。」斑鳩問：「為什麼？」梟說：「鄉里的人都討厭我的叫聲，所以要往東搬。」斑鳩說：「你能改變叫聲就好了；不能改變叫聲，搬到東邊，那裡的人還是會討厭你的聲音。」", "keywords": [{"w": "鵷鶵", "m": "傳說中類似鳳凰的鳥"}, {"w": "練實", "m": "竹實"}, {"w": "醴泉", "m": "甘泉"}, {"w": "鴟", "m": "貓頭鷹一類的鳥"}, {"w": "嚇", "m": "怒斥、驅趕的聲音"}, {"w": "徙", "m": "遷移"}, {"w": "更", "m": "改變"}], "questions": [{"n": 21, "qtype": "多選", "stem": "閱讀下列二則寓言，選出敘述正確的選項：", "options": {"A": "甲用南海、北海、梧桐、練實、醴泉等意象來襯寫鵷鶵的襟懷和堅持", "B": "乙的梟將東徙，是因為曲高和寡，不被濁世所容，所以打算遠離塵網", "C": "甲以行為描述來呈現禽鳥的心理，乙則藉對話內容來表達禽鳥的想法", "D": "二寓言皆以禽鳥間的互動為故事主軸，寄寓作者對人世的觀察及諷諭", "E": "鴟和鳩皆目光短淺之徒，不能理解鵷鶵和梟，猶如燕雀難知鴻鵠之志"}, "answer": "ACD", "explain": "(A)正確：從南海飛到北海寫志向遠大，非梧桐不止、非練實不食、非醴泉不飲寫品格高潔堅持。(B)錯誤：梟搬家是因為「鄉人皆惡我鳴」，叫聲讓人討厭，自身有問題，不是曲高和寡。(C)正確：甲主要用鴟「仰而視之曰嚇」等行為表現牠怕腐鼠被搶的心理；乙全篇是梟與鳩的對話。(D)正確：甲是鵷鶵與鴟、乙是梟與鳩，都以禽鳥互動諷喻人：甲諷刺以小人之心度君子之腹，乙說明不改自身缺點、換環境也沒用。(E)錯誤：鴟確實目光短淺，但鳩是點出問題根源的明白人，見識反而比梟高明。", "skill": "比較兩則寓言，先各自用一句話寫出「誰對誰做了什麼、說明什麼道理」，再判斷選項是否把角色的好壞弄反。"}], "difficulty": "中", "label": "104學測", "year": 104, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc104-23", "exam": "xc104", "nums": [23], "form": "單題", "img": "img/xc104-23.png", "source": "李清照〈減字木蘭花〉、杜光庭〈虬髯客傳〉、流行歌詞、琦君〈髻〉、現代小說（出處待查）", "author": "多位作者", "genre": "其他", "types": ["人物情感", "比較閱讀"], "passage": "(A)賣花擔上，買得一枝春欲放。淚染輕勻，猶帶彤霞曉露痕。怕郎猜道，奴面不如花面好。雲鬢斜簪，徒要教郎比並看\n(B)張氏（紅拂）熟視其面，一手握髮，一手映身搖示（李）靖，令勿怒。急急梳頭畢，斂衽前問其姓。臥客答曰：「姓張。」對曰：「妾亦姓張，合是妹。」遽拜之", "translation": "(A)從賣花擔上買到一枝含苞待放的春花，花上像淚珠般沾著均勻的露水，還帶著朝霞和清晨露水的痕跡。怕情郎說我的臉不如花美，就把花斜插在髮髻上，偏要讓他比比看。(B)紅拂仔細看了那人的臉，一手握著頭髮，一手藏在身後向李靖搖手示意，叫他不要發怒。她趕快梳好頭，整理衣襟上前問那人姓什麼。躺著的客人回答：「姓張。」她說：「我也姓張，應該是妹妹。」立刻向他下拜。", "keywords": [{"w": "比並", "m": "相比"}, {"w": "映身", "m": "藏在身後"}, {"w": "斂衽", "m": "整理衣襟，表示恭敬"}, {"w": "遽", "m": "立刻"}], "questions": [{"n": 23, "qtype": "多選", "stem": "許多文學作品中的女性，常被塑造成順從男性意志、以男性為中心的形象。下列有關女性的描寫，顛覆這種形象的選項是：", "options": {"A": "賣花擔上，買得一枝春欲放。淚染輕勻，猶帶彤霞曉露痕。怕郎猜道，奴面不如花面好。雲鬢斜簪，徒要教郎比並看", "B": "張氏（紅拂）熟視其面，一手握髮，一手映身搖示（李）靖，令勿怒。急急梳頭畢，斂衽前問其姓。臥客答曰：「姓張。」對曰：「妾亦姓張，合是妹。」遽拜之", "C": "愛太傷／不愛最大／請人間蒸發／月光下／有的王子／原來是青蛙／愛錯又怎樣／難免會遇上／愛的黑魔法／我沒在怕／因為女生／越戰越堅強", "D": "姨娘梳各式各樣的頭，什麼鳳凰髻、羽扇髻、同心髻、燕尾髻，常常換樣子，襯托著姨娘細潔的肌膚，嬝嬝婷婷的水蛇腰兒，越發引得父親笑瞇了眼", "E": "秀潔沒有回答，金發伯也沒有繼續說下去，……她（秀潔）竟在一種自己無法控制的、莫名其妙的情緒下提高嗓門，朗聲答道：「你不要妄想！……就是你逼我唱，我死也不唱，看你這小小的開封府尹，又怎麼奈何得了本宮！」"}, "answer": "BCE", "explain": "判斷女性是「圍著男人轉」還是「自己做主」。(A)錯誤：女子簪花是怕「郎」覺得她不如花美，要讓郎比較，仍以男性眼光為中心。(B)正確：紅拂見虬髯客無禮，不但不慌，還主動示意李靖別發怒，並機智地認虬髯客為兄，化解危機，主導局面。(C)正確：歌詞說愛錯了也不怕，女生越戰越堅強，展現獨立自主。(D)錯誤：姨娘精心打扮是為了取悅父親（「引得父親笑瞇了眼」），以男性為中心。(E)正確：秀潔拒絕被逼唱戲，大聲反抗「我死也不唱」，展現自主意志。", "skill": "看女性行為的「目的」：為了取悅或迎合男性的，屬於傳統形象；主動判斷、做決定、反抗的，才是顛覆。"}], "difficulty": "易", "label": "104學測", "year": 104, "kind": "學測", "textcat": "文學文本", "textcat2": "部定古文", "linked_core": "虬髯客傳"}, {"id": "xc104-ns2", "exam": "xc104", "nums": ["二"], "form": "單題", "img": "img/xc104-ns2.png", "source": "曹丕〈典論論文〉、高行健〈文學的理由〉", "author": "曹丕、高行健", "genre": "說理議論", "types": ["比較閱讀", "主旨寓意", "文意推論"], "passage": "甲、蓋文章，經國之大業，不朽之盛事。年壽有時而盡，榮樂止乎其身，二者必至之常期，未若文章之無窮。是以古之作者，寄身於翰墨，見意於篇籍，不假良史之辭，不託飛馳之勢，而聲名自傳於後。", "translation": "文章是治理國家的偉大事業，是可以永垂不朽的盛事。人的壽命有結束的時候，榮華享樂也只限於自身，這兩者都有一定的期限，比不上文章能流傳無窮。所以古代的作者，把生命寄託在筆墨中，把思想表現在著作裡，不必依靠史官的記載，也不必憑藉權貴的勢力，名聲自然就流傳到後世。", "keywords": [{"w": "經國", "m": "治理國家"}, {"w": "常期", "m": "一定的期限"}, {"w": "翰墨", "m": "筆墨，指寫作"}, {"w": "見", "m": "通「現」，表現"}, {"w": "假", "m": "憑藉"}, {"w": "良史", "m": "優秀的史官"}, {"w": "飛馳之勢", "m": "顯貴者的權勢"}], "questions": [{"n": "二", "qtype": "非選", "stem": "文章分析（占18分）：閱讀框線內文章後，回答問題。答案請標明（一）、（二）書寫，（一）、（二）合計文長約250-300字（約12-14行）。（一）為何人可以透過書寫而不朽？請依據甲段文字，闡釋曹丕的看法。（二）就「書寫對寫作者個人的價值和意義」這個議題，你認為曹丕、高行健的觀點是否相同？請依據甲、乙二段文字，說明你的看法。（乙、回顧我的寫作經歷，可以說，文學就其根本乃是人對自身價值的確認，書寫其時便已得到肯定。文學首先誕生於作者自我滿足的需要，有無社會效應則是作品完成之後的事，再說，這效應如何也不取決於作者的意願。（高行健〈文學的理由〉））", "options": {}, "answer": "", "ref_answer": "（一）曹丕認為人的壽命與榮華享樂都有終結的期限，唯有文章能流傳無窮。作者把生命與思想寄託在作品中，作品本身就能流傳後世，不必倚靠史官記載或權貴提拔，名聲自然傳於後代，因此人可以藉由書寫超越肉身的有限而不朽。（二）兩人觀點不同。曹丕著眼於書寫的「身後價值」：文章是經國大業，寫作的意義在於使聲名傳世、達到不朽，價值來自後人的肯定與流傳。高行健則著眼於書寫的「當下價值」：文學是人對自身價值的確認，在書寫的當下就已完成肯定，源於作者自我滿足的需要；作品的社會效應是完成後的事，且不由作者決定。也可指出相同處：兩人都肯定書寫能確立個人價值、不必依附外在權勢；但曹丕重流傳後世，高行健重自我實現，取向仍有差異。", "ref_official": false, "explain": "第（一）題要抓曹丕的對比：年壽、榮樂「有時而盡」vs. 文章「無窮」；再抓「不假良史之辭，不託飛馳之勢」——不靠別人，作品自己就能傳名。第（二）題是比較題，「相同或不同」都可以，但要言之有據：最好用一組對照概念整理，例如「為後世留名 vs. 為自我確認」「價值在流傳 vs. 價值在書寫當下」「重社會影響 vs. 不在意社會效應」，各引原文一句佐證。", "skill": "比較兩人觀點時，先找出兩段文字回答的是同一個問題（書寫的價值在哪裡），再列出各自的答案與時間點（身後／當下），差異就清楚了。"}], "difficulty": "中", "label": "104學測", "year": 104, "kind": "學測", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "典論論文"}, {"id": "zk104-2", "exam": "zk104", "nums": [2], "form": "單題", "img": "img/zk104-2.png", "source": "顧炎武〈廉恥〉、方苞〈左忠毅公軼事〉、韓愈〈師說〉、《荀子‧勸學》、諸葛亮〈出師表〉", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "", "translation": "", "keywords": [{"w": "則（就）", "m": "表示結果、承接"}, {"w": "則（卻）", "m": "表示轉折"}, {"w": "則（是）", "m": "表示判斷"}, {"w": "則（原來）", "m": "表示發現"}], "questions": [{"n": 2, "qtype": "單選", "stem": "下列文句中的「則」字，與顧炎武〈廉恥〉：「不廉則無所不取」的「則」字，用法相同的選項是：", "options": {"A": "引入，微指左公處，則席地倚牆而坐", "B": "愛其子，擇師而教之，於其身也則恥師焉", "C": "君子博學而日參省乎己，則知明而行無過矣", "D": "至於斟酌損益，進盡忠言，則攸之、禕、允之任也"}, "answer": "C", "explain": "「不廉則無所不取」：不廉潔，「就」什麼都拿，則＝就，表示前面條件帶來的結果。(C)《荀子‧勸學》：君子廣泛學習又每天反省自己，「就」能智慧明達、行為沒有過失，同樣是「就」，正確。(A)〈左忠毅公軼事〉：史可法被帶進去，獄卒暗指左公所在，「原來」（只見）左公靠著牆坐在地上，表示發現。(B)〈師說〉：愛孩子就替他找老師，對自己「卻」以從師為恥，表示轉折。(D)〈出師表〉：至於衡量得失、進獻忠言，「是」郭攸之、費禕、董允的責任，表示判斷。", "skill": "虛詞題把「就／卻／是／原來」逐一代入，哪個最順就是它的用法，再找用法相同的。"}], "difficulty": "中", "label": "104指考", "year": 104, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "勸學、出師表、師說、廉恥、左忠毅公軼事"}, {"id": "zk104-5", "exam": "zk104", "nums": [5], "form": "單題", "img": "img/zk104-5.png", "source": "先秦諸子名實論", "author": "", "genre": "經典語錄", "types": ["文化常識"], "passage": "甲、得意忘言　乙、正名定分　丙、循名責實　丁、白馬非馬", "translation": "甲：領會了意思，就忘掉用來表達的語言。乙：端正名稱、確定名分。丙：依照職位名稱去要求實際的績效。丁：「白馬」不等於「馬」。", "keywords": [{"w": "得意忘言", "m": "《莊子‧外物》：言者所以在意，得意而忘言"}, {"w": "正名", "m": "孔子：名不正則言不順"}, {"w": "循名責實", "m": "韓非等法家的考核方法"}, {"w": "白馬非馬", "m": "名家公孫龍的論題"}], "questions": [{"n": 5, "qtype": "單選", "stem": "語言和它所指稱的內容，可視為名和實的關係。下列有關先秦諸子名實關係的論述，依儒家、道家、法家、名家的順序排列，正確的選項是：甲、得意忘言　乙、正名定分　丙、循名責實　丁、白馬非馬", "options": {"A": "乙甲丙丁", "B": "乙丁甲丙", "C": "丙甲乙丁", "D": "丙丁乙甲"}, "answer": "A", "explain": "儒家：孔子主張「必也正名乎」，名分端正、君君臣臣，所以是乙「正名定分」。道家：莊子說語言只是捕捉意思的工具，抓到意思就可以忘掉語言，是甲「得意忘言」。法家：韓非主張按官職的名稱去考核實際成效，是丙「循名責實」。名家：公孫龍提出「白馬非馬」，討論概念與名稱的關係，是丁。順序乙甲丙丁，選(A)。", "skill": "諸子題記住各家的「招牌口號」：儒正名、道忘言、法責實、名家玩概念（白馬非馬、堅白論）。"}], "difficulty": "中", "label": "104指考", "year": 104, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk104-6", "exam": "zk104", "nums": [6], "form": "單題", "img": "img/zk104-6.png", "source": "蕭麗紅《千江有水千江月》引《禮記‧昏義》", "author": "蕭麗紅", "genre": "經典語錄", "types": ["句意理解", "文意推論"], "passage": "敬慎重正而后親之", "translation": "（《禮記‧昏義》）以恭敬、謹慎、隆重、端正的態度完成婚禮，然後夫妻相親相愛。", "keywords": [{"w": "敬慎重正", "m": "恭敬、謹慎、隆重、端正"}, {"w": "親之", "m": "親近她、親愛她"}], "questions": [{"n": 6, "qtype": "單選", "stem": "閱讀下文，推斷「貞觀」覺得「好笑」的原因，最有可能的選項是：水銀燈下，貞觀望著他專注修傘的臉，忽想起幾日前，他寄給她的那本《長生殿》；書的後兩頁，有他所寫《禮記‧昏義》篇的幾個字——敬慎重正而后親之——好笑的是他還在旁邊加了註解：經過敬謹、隆重而又光明正大的婚禮之後，才去親愛她，是禮的真義。（蕭麗紅《千江有水千江月》）", "options": {"A": "「他」期待快點長大，好結婚生子", "B": "「他」重禮儀，希望婚禮場面盛大", "C": "「他」想含蓄表白，又怕對方不懂", "D": "「他」對古文一知半解，詮釋謬誤"}, "answer": "C", "explain": "「他」在送給貞觀的書上抄了講婚禮的古文，意思是想跟她談婚論嫁、表達心意，卻又擔心她看不懂，特地在旁邊加上白話註解——用古文表白已經很含蓄，卻又多此一舉地解釋，所以貞觀覺得好笑，(C)正確。(A)文中沒有「期待長大」的意思。(B)他抄這句是借古文示愛，重點不在婚禮要辦得盛大。(D)他的註解「經過敬謹、隆重而又光明正大的婚禮之後，才去親愛她」大致符合原意，不是解錯了。", "skill": "推斷人物心情，要問「他為什麼這樣做」：寄書＋抄婚禮古文＝表白；再加註解＝怕對方不懂。"}], "difficulty": "中", "label": "104指考", "year": 104, "kind": "指考", "textcat": "文學文本", "textcat2": "學術文本", "linked_core": ""}, {"id": "zk104-7", "exam": "zk104", "nums": [7], "form": "單題", "img": "img/zk104-7.png", "source": "現代詩句對照古典詠物詩（杜甫〈螢火〉等）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文意推論"], "passage": "(A)熠熠與娟娟，池塘竹樹邊。亂飛如拽火，成聚卻無煙\n(B)粉翅嫩如水，繞砌乍依風。日高山露解，飛入菊花中\n(C)露滌清音遠，風吹數葉齊。聲聲似相接，各在一枝棲\n(D)兩角徒自長，空飛不服箱。為牛竟何事，利吻穴枯桑", "translation": "(A)閃閃發亮又姿態美好，在池塘邊、竹林樹叢間。亂飛時像拖著一道火光，聚在一起卻沒有煙。\n(B)粉色的翅膀嫩得像水，繞著臺階隨風飄飛。太陽升高、山間露水消散，牠飛進菊花叢中。\n(C)露水洗過，清亮的叫聲傳得很遠，風吹得幾片葉子齊齊擺動。一聲聲彷彿互相應和，各自停在一根樹枝上。\n(D)兩隻角白白地長著，只會飛卻不能拉車。叫做「牛」到底做了什麼事？只會用尖利的嘴在枯桑樹上鑽洞。", "keywords": [{"w": "熠熠", "m": "光亮閃爍的樣子"}, {"w": "拽火", "m": "拖曳著火光"}, {"w": "服箱", "m": "駕車、拉車"}, {"w": "穴", "m": "鑽洞（名詞作動詞）"}], "questions": [{"n": 7, "qtype": "單選", "stem": "閱讀下列現代詩句，選出與詩中所詠對象相同的選項：用尾端，輕輕，就能頂住全世界的黑暗／死亡或遺忘。我便這樣不由自主地發光", "options": {"A": "熠熠與娟娟，池塘竹樹邊。亂飛如拽火，成聚卻無煙", "B": "粉翅嫩如水，繞砌乍依風。日高山露解，飛入菊花中", "C": "露滌清音遠，風吹數葉齊。聲聲似相接，各在一枝棲", "D": "兩角徒自長，空飛不服箱。為牛竟何事，利吻穴枯桑"}, "answer": "A", "explain": "現代詩「用尾端…頂住黑暗」「不由自主地發光」，是尾巴會發光的螢火蟲。(A)「熠熠」是閃閃發光、「亂飛如拽火，成聚卻無煙」像火卻沒有煙，正是螢火蟲，答案。(B)粉翅、飛入菊花，是蝴蝶。(C)清音遠、聲聲相接、棲在樹枝，是蟬。(D)兩角、叫做「牛」卻不能拉車、在桑樹上鑽洞，是天牛。", "skill": "詠物詩猜謎：把每首詩的「外形、動作、聲音」三條線索列出來，對照題目給的特徵。"}], "difficulty": "易", "label": "104指考", "year": 104, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk104-9", "exam": "zk104", "nums": [9], "form": "單題", "img": "img/zk104-9.png", "source": "諸葛亮語；《論語》、《孟子》", "author": "", "genre": "經典語錄", "types": ["句意理解", "文意推論"], "passage": "治世以大德，不以小惠。", "translation": "治理國家要靠大的德政，而不是靠給人小恩小惠。", "keywords": [{"w": "小惠", "m": "小恩小惠"}, {"w": "平其政", "m": "把政事治理好"}, {"w": "辟人", "m": "使行人迴避（開道）"}, {"w": "濟", "m": "幫助（過河）"}], "questions": [{"n": 9, "qtype": "單選", "stem": "關於執政者的施政原則，諸葛亮說：「治世以大德，不以小惠」。下列敘述，與此說法最接近的選項是：", "options": {"A": "邦有道，貧且賤焉，恥也；邦無道，富且貴焉，恥也", "B": "天下大悅而將歸己，視天下悅而歸己，猶草芥也，惟舜為然", "C": "菲飲食，而致孝乎鬼神；惡衣服，而致美乎黻冕；卑宮室，而盡力乎溝洫", "D": "君子平其政，行辟人可也。焉得人人而濟之？故為政者，每人而悅之，日亦不足矣"}, "answer": "D", "explain": "(D)出自《孟子》：子產用自己的車子幫人渡河，孟子批評這是小恩惠，說君子只要把政事治理好（例如造橋），出門時叫人迴避都可以，哪能一個一個去幫忙？想讓每個人都高興，時間根本不夠。重點正是「做大政，不施小惠」，最接近。(A)《論語》講個人在治世、亂世的出處與榮辱。(B)《孟子》講舜把天下歸附看得像草芥，重在孝親。(C)《論語》讚美禹自己生活儉樸，卻把心力用在祭祀、禮服和水利上，講的是執政者克己為民，不是大德與小惠的對比。", "skill": "找最接近的意思，先把題目濃縮成對比結構（大德 vs. 小惠），選項裡也要有同樣的對比。"}], "difficulty": "中", "label": "104指考", "year": 104, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk104-10", "exam": "zk104", "nums": [10], "form": "單題", "img": "img/zk104-10.png", "source": "《說苑‧奉使》", "author": "劉向", "genre": "史傳人物", "types": ["文意推論", "句意理解"], "passage": "楚莊王欲伐晉，使豚尹觀焉。反曰：「不可伐也。其憂在上，其樂在下；且賢臣在焉，曰沈駒。」明年，又使豚尹觀，反曰：「可矣。初之賢人死矣，諂諛多在君之廬者。其君好樂而無禮；其下危處以怨上。上下離心，與師伐之，其民必反。」莊王從之，果如其言矣。", "translation": "楚莊王想攻打晉國，派豚尹去觀察。豚尹回來說：「不能攻打。晉國的憂慮由國君承擔，快樂留給百姓；而且有賢臣在那裡，叫沈駒。」第二年，又派豚尹去觀察，他回來說：「可以了。原來那位賢人死了，國君身邊多是諂媚奉承的人。國君喜好享樂而不守禮；百姓生活危困而怨恨上位者。上下離心，出兵攻打，他們的人民一定會反叛。」莊王聽從了，結果果然像他說的那樣。", "keywords": [{"w": "觀", "m": "觀察、刺探"}, {"w": "反", "m": "同「返」，回來／後文「民必反」為反叛"}, {"w": "廬", "m": "居處，此指國君身邊"}, {"w": "危處", "m": "處境危困"}, {"w": "與師", "m": "興兵，出兵"}], "questions": [{"n": 10, "qtype": "單選", "stem": "閱讀下文，選出敘述正確的選項：", "options": {"A": "豚尹反對楚莊王攻打晉國，表現出他憂以天下、樂以天下的博愛襟懷", "B": "豚尹與沈駒分別為晉國與楚國賢臣，豚尹受到重用，沈駒則含冤而死", "C": "晉君由憂國轉而好樂，晉民由安樂轉而怨上，遂使晉國陷入崩解危機", "D": "晉國在沈駒死後，晉民因晉君不守禮法而造反，楚國遂趁機攻打晉國"}, "answer": "C", "explain": "第一年「其憂在上，其樂在下」：國君憂國、百姓安樂；第二年「其君好樂而無禮，其下危處以怨上」：國君貪樂、百姓怨恨，上下離心，正是(C)。(A)錯：豚尹第一次反對出兵是因為晉國上下團結、有賢臣，不是他自己的博愛胸懷；「憂在上、樂在下」說的是晉國的情況。(B)錯：豚尹是楚國人（楚王派去的），沈駒是晉國賢臣，文中也沒說沈駒含冤而死。(D)錯：順序顛倒——是楚國出兵攻打，晉民才「必反」（不替國君作戰），不是晉民先造反楚國再趁機。", "skill": "兩次觀察的故事，把「第一年」和「第二年」的情況並排比較，答案通常就在變化之處。"}], "difficulty": "易", "label": "104指考", "year": 104, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk104-11", "exam": "zk104", "nums": [11], "form": "單題", "img": "img/zk104-11.png", "source": "洪應明《菜根譚》", "author": "洪應明", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "害人之心不可有，防人之心不可無，此戒疏於慮也。寧受人之欺，毋逆人之詐，此警傷於察也。二語並存，精明而渾厚矣。", "translation": "不能有害人的心，但不能沒有防人的心，這是告誡人不要思慮不周。寧可被人欺騙，也不要事先猜疑別人會欺詐，這是警告人不要因為太過苛察而傷了厚道。兩句話同時做到，就能既精明又寬厚了。", "keywords": [{"w": "疏於慮", "m": "考慮不周到"}, {"w": "逆", "m": "預先揣測"}, {"w": "傷於察", "m": "因過度苛察而有所損傷"}, {"w": "渾厚", "m": "寬厚、淳樸"}], "questions": [{"n": 11, "qtype": "單選", "stem": "閱讀下文，選出最符合文意的選項：", "options": {"A": "寧可防察無疏，絕不受人欺詐", "B": "既要慎防危害，也要心胸寬大", "C": "對他人宜小心，對自己須誠實", "D": "千慮難免一疏，人心詐偽難防"}, "answer": "B", "explain": "前一句要人有防人之心（精明），後一句要人寧可受騙也別猜疑別人（渾厚），兩者並存就是「既要防備，又要寬厚」，(B)正確。(A)錯：「寧受人之欺」明明說寧可被騙，「絕不受人欺詐」正好相反。(C)錯：文中沒有談到對自己誠實。(D)錯：文章教人如何兼顧精明與厚道，不是感嘆人心難防。", "skill": "「二語並存」的文章，答案要同時包含兩句的精神，只講一邊的都不對。"}], "difficulty": "易", "label": "104指考", "year": 104, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk104-12", "exam": "zk104", "nums": [12, 13], "form": "題組", "img": "img/zk104-12.png", "source": "劉基《郁離子‧虎貙》", "author": "劉基", "genre": "寓言故事", "types": ["文意推論", "主旨寓意", "虛詞句式"], "passage": "若石隱於冥山之陰，有虎恆蹲以窺其藩。若石帥其人晝夜警，日出而殷鉦，日入而燎煇，宵則振鐸以望，植棘樹墉，坎山谷以守。卒歲，虎不能有獲。一日而虎死，若石大喜，自以為虎死無毒己者矣，於是弛其機，撤其備，垣壞而不修，藩決而不理。無何，有貙逐麋來，止其室之隈，聞其牛、羊、豕之聲而入食焉。若石不知其為貙也，叱之不走，投之以塊。貙人立而爪之，斃。君子謂：若石知一而不知二，宜其及也。", "translation": "若石隱居在冥山的北面，有一隻老虎常蹲在那裡窺伺他的籬笆。若石帶領家人日夜警戒，太陽出來就敲鉦，太陽下山就點火把，夜裡搖鈴守望，種荊棘、築土牆，在山谷挖坑來防守。過了一整年，老虎什麼都沒抓到。有一天老虎死了，若石非常高興，以為老虎死了就沒有東西能傷害自己了，於是放鬆機關、撤除防備，牆壞了不修，籬笆破了不管。沒多久，有一頭貙追著麋鹿來，停在他屋子的角落，聽到牛、羊、豬的叫聲就闖進去吃。若石不知道那是貙，大聲斥喝牠不走，就拿土塊丟牠。貙像人一樣站起來用爪子抓他，若石就死了。君子說：若石只知其一不知其二，遭到災禍是應該的。", "keywords": [{"w": "陰", "m": "山的北面"}, {"w": "藩", "m": "籬笆"}, {"w": "殷鉦", "m": "敲響鉦（銅製樂器）"}, {"w": "燎煇", "m": "點起火把"}, {"w": "坎", "m": "挖坑（名詞作動詞）"}, {"w": "毒", "m": "傷害"}, {"w": "弛其機", "m": "放鬆捕獸機關"}, {"w": "貙", "m": "一種似狸而大的猛獸"}, {"w": "隈", "m": "角落"}, {"w": "宜其及也", "m": "遭殃是應該的"}], "questions": [{"n": 12, "qtype": "單選", "stem": "根據上文，敘述正確的選項是：", "options": {"A": "若石雖然日夜警戒，但終究免不了被老虎咬死", "B": "兇猛的老虎蹲在籬笆牆邊窺視，是因為害怕貙", "C": "若石只知防備老虎，卻不知貙會危害身家性命", "D": "老虎被若石毒死，若石就鬆開弩機，撤除防備"}, "answer": "C", "explain": "若石嚴防老虎一整年，老虎一死就撤掉所有防備，結果被貙抓死；君子說他「知一而不知二」，就是只知道防虎、不知道還有別的危險，(C)正確。(A)錯：殺死若石的是貙，不是老虎。(B)錯：老虎窺視籬笆是想找機會吃東西，文中沒有說牠怕貙。(D)錯：「一日而虎死」只說老虎死了，沒說是若石毒死的；「無毒己者」的「毒」是傷害的意思。", "skill": "寓言題先抓結尾的評語（知一而不知二），再回頭核對每個細節是「誰做的」。"}, {"n": 13, "qtype": "單選", "stem": "「貙人立而爪之」的「人立」，由「名詞＋動詞」組成，名詞「人」用來描述「立」這個動作的特徵，意謂「像人一樣的站立」。下列文句「」內，屬於此種組成方式的選項是：", "options": {"A": "彊公室，杜私門，「蠶食」諸侯，使秦成帝業", "B": "老成凋謝，莫可諮詢；「巷議」街譚，事多不實", "C": "越明年，政通「人和」，百廢具興，乃重修岳陽樓", "D": "「歌吹」為風，粉汗為雨，羅紈之盛，多於堤畔之草"}, "answer": "A", "explain": "「人立」＝像人一樣站立，名詞說明動作的方式。(A)〈諫逐客書〉「蠶食諸侯」＝像蠶吃桑葉一樣，一點一點吞併諸侯，名詞「蠶」描述「食」的方式，相同。(B)「巷議」是在街巷中議論，名詞表示地點，不是「像巷一樣議論」。(C)〈岳陽樓記〉「人和」是人民和樂，人是主語、和是謂語，屬於主謂結構。(D)「歌吹」是唱歌和吹奏樂器，兩個動詞並列。", "skill": "判斷「名詞＋動詞」：在中間加「像…一樣」唸唸看（像蠶一樣吃），通的才是比喻動作方式。"}], "difficulty": "中", "label": "104指考", "year": 104, "kind": "指考", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "郁離子選"}, {"id": "zk104-19", "exam": "zk104", "nums": [19], "form": "單題", "img": "img/zk104-19.png", "source": "多篇古文（〈蘭亭集序〉〈原君〉〈項脊軒志〉〈虯髯客傳〉〈諫太宗十思疏〉〈漁父〉〈與陳伯之書〉等）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "", "translation": "", "keywords": [{"w": "盡", "m": "終盡、死亡／全部"}, {"w": "薄", "m": "迫近"}, {"w": "歸", "m": "女子出嫁／回去"}, {"w": "休", "m": "美善、美好"}, {"w": "寧", "m": "寧可／豈、難道"}], "questions": [{"n": 19, "qtype": "多選", "stem": "下列各組文句「」內的字，前後意義相同的選項是︰", "options": {"A": "況脩短隨化，終期於「盡」／以天下之害「盡」歸於人", "B": "其門人甚眾，「薄」暮畢集／炎日「薄」茅上，暑氣蒸鬱，覺悶甚", "C": "後五年，吾妻來「歸」／靖心知虬髯得事也，「歸」告張氏，具禮拜賀", "D": "將崇極天之峻，永保無疆之「休」／譬如人身血脈，節節相通，自無他病。數年以後，仍成樂土，豈不「休」哉", "E": "安能以身之察察，受物之汶汶者乎？「寧」赴湘流，葬於江魚之腹中／將軍獨靦顏借命，驅馳氈裘之長，「寧」不哀哉"}, "answer": "BD", "explain": "(B)相同：都是「迫近」。快到傍晚時門人都聚集了；烈日逼近茅草屋頂。(D)相同：都是「美善、美好」。〈諫太宗十思疏〉永保無窮的美善；幾年後成為樂土，難道不美好嗎？(A)不同：〈蘭亭集序〉「終期於盡」是生命終將結束；〈原君〉「盡歸於人」是全部。(C)不同：〈項脊軒志〉「吾妻來歸」是女子嫁過來；〈虯髯客傳〉「歸告張氏」是回去。(E)不同：〈漁父〉「寧赴湘流」是寧可；〈與陳伯之書〉「寧不哀哉」是難道、豈。", "skill": "「寧」後面接「不…哉」多半是反問的「豈」；後面接一個選擇行動，多半是「寧可」。"}], "difficulty": "中", "label": "104指考", "year": 104, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "漁父、與陳伯之書、蘭亭集序、虬髯客傳、諫太宗十思疏、項脊軒志、原君"}, {"id": "zk104-20", "exam": "zk104", "nums": [20], "form": "單題", "img": "img/zk104-20.png", "source": "〈鴻門宴〉、《論語》、《洛陽伽藍記》等", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "", "translation": "", "keywords": [{"w": "…者三", "m": "放在句末，可表示次數（做了三次），也可表示數量（有三個）"}], "questions": [{"n": 20, "qtype": "多選", "stem": "「平原君欲封魯仲連，魯仲連辭讓者三」，句末的「三」用來描述動作的頻率。下列文句中的「三」，屬於此種用法的選項是：", "options": {"A": "范增數目項王，舉所佩玉玦以示之者「三」", "B": "五帝五后，凡十主，未遷者六，未立者四，未諡者「三」", "C": "君子道者「三」，我無能焉：仁者不憂，知者不惑，勇者不懼", "D": "尋見莊帝從閶闔門入，登太極殿，唱萬歲者「三」，百官咸加朝服謁帝", "E": "每衞果毅都尉一人，被繡袍，各一人從；左右領軍衞有絳引幡，引前者三，掩後者「三」"}, "answer": "AD", "explain": "題目要找表示「做了幾次」的「三」。(A)〈鴻門宴〉范增舉起玉玦暗示項羽「三次」，是動作次數，正確。(D)喊萬歲喊了「三次」，也是動作次數，正確。(B)沒有追諡號的有「三位」君主，是數量。(C)《論語》君子之道有「三項」（仁、知、勇），是數量。(E)在前面引導的有三人、在後面護衛的有「三人」，是人數。", "skill": "在「三」後面補量詞試試：補「次」通順是頻率，補「個、位、人、項」通順是數量。"}], "difficulty": "易", "label": "104指考", "year": 104, "kind": "指考", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "鴻門宴、原君"}, {"id": "zk104-21", "exam": "zk104", "nums": [21], "form": "單題", "img": "img/zk104-21.png", "source": "南朝樂府民歌（〈子夜歌〉等）", "author": "", "genre": "古典詩詞曲", "types": ["寫作手法", "詩詞賞析"], "passage": "", "translation": "", "keywords": [{"w": "雙關", "m": "一個詞同時兼顧兩種意思，南朝民歌常用諧音雙關"}, {"w": "絲子／思子", "m": "蠶絲與思念你"}, {"w": "蓮子／憐子", "m": "蓮的果實與愛你"}, {"w": "梧子／吾子", "m": "梧桐子與我的你"}, {"w": "之子", "m": "這個人"}], "questions": [{"n": 21, "qtype": "多選", "stem": "「前絲斷纏綿，意欲結交情。春蠶易感化，絲子已復生」，其中「絲子」和「思子」為雙關語。下列詩句畫底線處（蓮子、之子、揚子、梧子、珠子），屬於相同表達手法的選項是：", "options": {"A": "朝登涼臺上，夕宿蘭池裡。乘月採芙蓉，夜夜得蓮子", "B": "雖無賓主意，頗得清淨理。興盡方下山，何必待之子", "C": "五月南風興，思君下巴陵。八月西風起，想君發揚子", "D": "憐歡好情懷，移居作鄉里。桐樹生門前，出入見梧子", "E": "今日還家去，念母勞家裡。卻與小姑別，淚落連珠子"}, "answer": "AD", "explain": "「絲子」字面是蠶絲，諧音「思子」（思念你），一個詞同時有兩層意思。(A)〈子夜四時歌〉「夜夜得蓮子」：字面是採芙蓉得到蓮子，諧音「憐子」（愛你），寫女子夜夜思戀情人，是雙關，正確。(D)「梧子」字面是梧桐的果實，諧音「吾子」（我的那個人），前面說「憐歡（愛著情郎）」「移居作鄉里」，出入都能見到心上人，是雙關，正確。(B)王維詩「何必待之子」的「之子」就是「這個人」，只有一種意思。(C)「想君發揚子」的「揚子」是地名揚子津，和上句「巴陵」相對，寫思念情人從揚子出發，沒有諧音的第二層意思。(E)〈孔雀東南飛〉「淚落連珠子」是眼淚像一串珠子落下，是比喻，不是雙關。", "skill": "雙關的檢驗法：把詞換成同音字，看能不能和前後的「情愛、思念」連起來，形成第二層意思。"}], "difficulty": "中", "label": "104指考", "year": 104, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk104-22", "exam": "zk104", "nums": [22], "form": "單題", "img": "img/zk104-22.png", "source": "甲：《漢書‧佞幸傳》；乙：龍榆生《中國韻文史》", "author": "班固；龍榆生", "genre": "史傳人物", "types": ["文化常識", "比較閱讀", "文意推論"], "passage": "甲、（李）延年善歌，為新變聲。是時上方興天地諸祠，欲造樂，令司馬相如等作詩頌，延年輒承意弦歌所造詩，為之新聲曲。\n乙、宋翔鳳云：「宋元之間，詞與曲一也；以文寫之則為詞，以聲度之則曲。」詞、曲皆有曲度，故謂之填詞，又稱倚聲，並先有聲而後有詞，非若古樂府之始或徒歌，終由知音者為之作曲，被諸管弦也。", "translation": "甲：李延年擅長唱歌，創作新的變調樂曲。當時漢武帝正大興天地各種祭祀，想製作樂章，命令司馬相如等人寫詩頌，李延年就順著皇帝的心意，把寫好的詩配上弦樂來唱，替它們譜成新的曲子。\n乙：宋翔鳳說：「在宋元之間，詞和曲是同一回事；用文字寫下來就叫詞，用音樂來衡量就叫曲。」詞和曲都有固定的曲調，所以叫做「填詞」，又叫「倚聲」，都是先有曲調、再有歌詞；不像古樂府，起初可能只是沒有伴奏的清唱，最後才由懂音樂的人替它譜曲，配上管弦樂器演奏。", "keywords": [{"w": "新變聲", "m": "新創的變調樂曲"}, {"w": "承意", "m": "順承皇帝的心意"}, {"w": "弦歌", "m": "配上弦樂歌唱"}, {"w": "倚聲", "m": "依照曲調填詞"}, {"w": "徒歌", "m": "沒有樂器伴奏的清唱"}, {"w": "被諸管弦", "m": "配上管弦樂器"}], "questions": [{"n": 22, "qtype": "多選", "stem": "閱讀下列兩則資料，選出敘述正確的選項：", "options": {"A": "「古樂府」即李延年「新聲曲」，乃「徒歌」之作", "B": "唐代白居易提倡的「新樂府」，體裁亦為「先有聲而後有詞」", "C": "詞在宋代的寫作方式，大致為「倚聲」，多按既有譜格填上新詞", "D": "李延年「弦歌所造詩」，即「知音者為之作曲，被諸管弦也」的表現", "E": "「宋元之間，詞與曲一也」意謂宋詞、元曲的押韻和協律方式完全相同"}, "answer": "CD", "explain": "(C)正確：乙文說詞叫「填詞、倚聲」，先有曲調再填歌詞，就是照著現成的曲譜填新詞。(D)正確：司馬相如等人先寫好詩，李延年再替詩譜曲、配上弦樂，正是「先有詞，再由懂音樂的人作曲、配樂」。(A)錯：「徒歌」是古樂府最初沒有伴奏的清唱；李延年的新聲曲是配了弦樂的，兩者不能畫上等號。(B)錯：白居易的新樂府是借樂府之名寫社會詩，多半不配樂，也不是先有曲調再填詞。(E)錯：「詞與曲一也」是說兩者都是依曲填寫的歌詞，性質相同，並沒有說押韻、協律方式完全一樣，「完全相同」說得太過。", "skill": "文學史資料題，把「先有詞還是先有曲」做成兩欄對照，選項逐一歸類就不會混。"}], "difficulty": "難", "label": "104指考", "year": 104, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc105-4", "exam": "xc105", "nums": [4], "form": "單題", "img": "img/xc105-4.png", "source": "韓愈〈師說〉、《儒林外史》、《三國演義》、袁宏道〈晚遊六橋待月記〉", "author": "韓愈等", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)小學而大遺，吾未見其明也（韓愈〈師說〉）\n(B)胡老爹，這個事須是這般，你沒奈何，權變一權變（《儒林外史》）\n(C)不費江東半分之力，已得十萬餘箭，明日即將來射曹軍（《三國演義》）\n(D)今歲春雪甚盛，梅花為寒所勒，與杏、桃相次開發，尤為奇觀（袁宏道〈晚遊六橋待月記〉）", "translation": "(A)小的方面（句讀）去學，大的方面（解惑）反而放棄，我看不出這有什麼聰明。(B)胡老爹，這件事只能這樣，你沒辦法，就變通一下吧。(C)不費江東一點力氣，已經得到十萬多支箭，明天就拿來射曹軍。(D)今年春雪很大，梅花被寒氣抑制，和杏花、桃花接連開放，特別壯觀。", "keywords": [{"w": "小學", "m": "學習小的部分（指句讀）"}, {"w": "權變", "m": "變通、隨機應變"}, {"w": "將來", "m": "拿來"}, {"w": "開發", "m": "開放、綻放"}], "questions": [{"n": 4, "qtype": "單選", "stem": "下列文句「」內的詞，其意義和現今慣用詞語相同的選項是：", "options": {"A": "「小學」而大遺，吾未見其明也", "B": "胡老爹，這個事須是這般，你沒奈何，「權變」一權變", "C": "不費江東半分之力，已得十萬餘箭，明日即「將來」射曹軍", "D": "今歲春雪甚盛，梅花為寒所勒，與杏、桃相次「開發」，尤為奇觀"}, "answer": "B", "explain": "答案(B)。「權變一權變」就是「變通一下」，和今天說的「權變」（隨機應變）意思一樣。(A)「小學」是「小的方面去學」，指學句讀，不是今天的「國民小學」；(C)「將來」是「拿來」，「將」是拿的意思，不是「未來」；(D)「開發」是花朵「開放」，不是今天開發土地、資源的意思。", "skill": "古今詞義題：把詞拆成單字逐字翻（將＝拿、來＝來），先用古義讀通，再和現代用法比較。"}], "difficulty": "中", "label": "105學測", "year": 105, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "師說、晚遊六橋待月記"}, {"id": "xc105-5", "exam": "xc105", "nums": [5], "form": "單題", "img": "img/xc105-5.png", "source": "〈勞山道士〉、〈出師表〉、〈醉翁亭記〉、〈工之僑獻琴〉、〈左忠毅公軼事〉、〈始得西山宴遊記〉、〈桃花源記〉等", "author": "多家", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)不堪其苦，陰有歸志／費禕、董允等，此皆良實，志慮忠純\n(B)其西南諸峰，林壑尤美／工之僑以歸，謀諸漆工，作斷紋焉\n(C)往來桐城，必躬造左公第／洋洋乎與造物者遊，而不知其所窮\n(D)見漁人，乃大驚，問所從來／余與從者後，五步之內，已各不相見", "translation": "(A)受不了那種苦，暗中有回家的念頭／費禕、董允這些人都善良誠實，心意思慮忠誠純正。(B)它西南方的各座山峰，樹林山谷特別美／工之僑帶琴回家，和漆匠商量，做出斷紋。(C)往來桐城時，一定親自到左公家拜訪／悠然自得地和創造萬物的大自然同遊，不知道盡頭在哪裡。(D)看見漁人，非常驚訝，問他從哪裡來／我和跟隨的人落在後面，五步之內已經彼此看不見。", "keywords": [{"w": "志", "m": "心意、念頭"}, {"w": "諸", "m": "眾、各；之於的合音"}, {"w": "造", "m": "到、拜訪；創造"}, {"w": "從", "m": "自、由；跟隨"}], "questions": [{"n": 5, "qtype": "單選", "stem": "下列各組「」內的字，前後意義相同的選項是：", "options": {"A": "不堪其苦，陰有歸「志」／費禕、董允等，此皆良實，「志」慮忠純", "B": "其西南「諸」峰，林壑尤美／工之僑以歸，謀「諸」漆工，作斷紋焉", "C": "往來桐城，必躬「造」左公第／洋洋乎與「造」物者遊，而不知其所窮", "D": "見漁人，乃大驚，問所「從」來／余與「從」者後，五步之內，已各不相見"}, "answer": "A", "explain": "答案(A)。兩個「志」都是「心意、念頭」：「歸志」是想回家的念頭，「志慮」是心意思慮。(B)前者「諸峰」是「眾、各」，後者「謀諸漆工」是「之於」的合音（和漆工商量這件事）。(C)前者「躬造」是「到、拜訪」，後者「造物者」是「創造」。(D)前者「所從來」的「從」是「自、由」，後者「從者」是「跟隨」。", "skill": "一字多義題：把字放回句子裡，用白話代進去讀讀看，讀得通才算對；看到「諸＋名詞（人、物）」在動詞後，先想「之於」。"}], "difficulty": "中", "label": "105學測", "year": 105, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "出師表、桃花源記、始得西山宴遊記、醉翁亭記、郁離子選、勞山道士、左忠毅公軼事"}, {"id": "xc105-6", "exam": "xc105", "nums": [6], "form": "單題", "img": "img/xc105-6.png", "source": "玉嬌龍語（電影《臥虎藏龍》）、胡適語；選項為古典詩詞", "author": "王之渙、蘇軾等", "genre": "古典詩詞曲", "types": ["詩詞賞析", "主旨寓意"], "passage": "(A)欲窮千里目，更上一層樓\n(B)功名屬少年，知心惟杜鵑\n(C)揀盡寒枝不肯棲，寂寞沙洲冷\n(D)堪尋敵手共論劍，高處不勝寒", "translation": "(A)想看盡千里遠的景色，就再登上一層樓。(B)功名屬於少年人，懂我心事的只有杜鵑鳥。(C)挑遍了寒冷的樹枝都不肯棲息，只能待在寂寞清冷的沙洲。(D)想找個敵手一起論劍都很難，站得太高，冷得受不了。", "keywords": [{"w": "堪", "m": "此處有「哪堪、難以」之意"}, {"w": "不勝寒", "m": "承受不了寒冷"}], "questions": [{"n": 6, "qtype": "單選", "stem": "下列文句，最接近玉嬌龍與胡適二人所述意旨的選項是：（題目引玉嬌龍、胡適兩段話，見截圖）", "options": {"A": "欲窮千里目，更上一層樓", "B": "功名屬少年，知心惟杜鵑", "C": "揀盡寒枝不肯棲，寂寞沙洲冷", "D": "堪尋敵手共論劍，高處不勝寒"}, "answer": "D", "explain": "答案(D)。玉嬌龍說她打敗師父後「不知道該往哪裡去，又能跟隨誰」，胡適說在沒有高手也沒有對手的社會裡，「勝敗必須一人承擔」——兩人都在講「站到最高處之後，沒有對手也沒有指引的孤獨」。(D)「堪尋敵手共論劍，高處不勝寒」正是找不到對手、高處孤寒。(A)講要更上層樓追求更高境界，是積極向上，不是孤獨；(B)講年少求功名、只有杜鵑知心，重點不在「無敵」；(C)蘇軾寫不肯隨便棲身的孤高寂寞，是不願同流合污，不是因為太強而沒有對手。", "skill": "先用一句話寫出題幹材料的共同點（這題是「無敵之後的孤獨」），再拿這句話逐一對照選項，找關鍵字最吻合的。"}], "difficulty": "易", "label": "105學測", "year": 105, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc105-13", "exam": "xc105", "nums": [13, 14], "form": "題組", "img": "img/xc105-13.png", "source": "侯白《啟顏錄》", "author": "侯白", "genre": "筆記小品", "types": ["文意推論", "寫作手法", "比較閱讀"], "passage": "山東人娶蒲州女，（蒲州女）多患癭，其妻母項癭甚大。成婚數月，婦家疑婿不慧。婦翁置酒，盛會親戚，欲以試之。問曰：「某郎在山東讀書，應識道理。鴻鶴能鳴，何意？」曰：「天使其然。」又曰：「松柏冬青，何意？」曰：「天使其然。」又曰：「道邊樹有骨⿰骨出，何意？」曰：「天使其然。」婦翁曰：「某郎全不識道理，何因浪住山東？」因以戲之，曰：「鴻鶴能鳴者，頸項長；松柏冬青者，心中強；道邊樹有骨⿰骨出者，車撥傷。豈是天使其然？」婿曰：「請以所聞見奉酬，不知許否？」曰：「可言之。」婿曰：「蝦蟆能鳴，豈是頸項長？竹亦冬青，豈是心中強？夫人項下癭如許大，豈是車撥傷？」婦翁羞愧，無以對之。", "translation": "有個山東人娶了蒲州女子，蒲州女子很多人脖子長瘤，他的岳母脖子上的瘤就很大。結婚幾個月後，女方家懷疑女婿不聰明。岳父擺酒，把親戚都請來，想考考他。問：「你在山東讀書，應該懂道理。鴻鶴能叫，是什麼緣故？」女婿說：「天生就是這樣。」又問：「松柏冬天還是綠的，是什麼緣故？」答：「天生就是這樣。」又問：「路邊的樹長了樹瘤，是什麼緣故？」答：「天生就是這樣。」岳父說：「你完全不懂道理，在山東白讀了！」就開玩笑說：「鴻鶴會叫，是因為脖子長；松柏冬天綠，是因為樹心堅強；路邊的樹有瘤，是被車子撞傷的。哪是天生的？」女婿說：「我也用我聽到看到的回敬您，可以嗎？」岳父說：「你說。」女婿說：「蝦蟆也會叫，難道是脖子長？竹子也冬天常綠，難道是心中堅強？岳母脖子下的瘤這麼大，難道是被車撞傷的？」岳父又羞又慚，答不出話來。", "keywords": [{"w": "癭", "m": "頸部的瘤"}, {"w": "不慧", "m": "不聰明"}, {"w": "浪", "m": "白白地、徒然"}, {"w": "奉酬", "m": "回敬、回應"}, {"w": "如許", "m": "如此、這麼"}], "questions": [{"n": 13, "qtype": "單選", "stem": "依據文意，選出敘述正確的選項：項癭：頸瘤。", "options": {"A": "岳父為了彰顯蒲州人的聰明博學，故刻意安排即興問答", "B": "對岳父的問題，女婿皆以「天使其然」回應，故被嘲笑", "C": "女婿四處漂泊，暫時寄居山東，故有「浪住山東」之說", "D": "女婿舉出蝦蟆、竹子及新婚妻子為證，反駁岳父的戲謔"}, "answer": "B", "explain": "答案(B)。岳父連問三題，女婿都回答「天使其然」，岳父才說他「全不識道理」來取笑他。(A)岳父設宴是因為「疑婿不慧，欲以試之」，想考女婿，不是要彰顯蒲州人聰明。(C)「浪住山東」的「浪」是「白白地」，意思是在山東白讀書了，不是四處漂泊。(D)女婿舉的是蝦蟆、竹子和「夫人（岳母）」的頸瘤，不是新婚妻子。", "skill": "遇到人物關係題，先把「誰對誰說話」標清楚；「夫人」在這裡指岳母，「浪」要用古義「徒然」去讀。"}, {"n": 14, "qtype": "單選", "stem": "女婿面對岳父的戲謔，以岳父的思維模式加以回應，因而改變形勢。下列人物應答時使用的語言技巧，與文中女婿相同的選項是：", "options": {"A": "（馮諼）辭曰：「責畢收，以何市而反？」孟嘗君曰：「視吾家所寡有者。」", "B": "諸葛令、王丞相共爭姓族先後，王曰：「何不言葛、王，而云王、葛？」令曰：「譬言驢、馬，不言馬、驢，驢寧勝馬邪？」", "C": "賈母問他：「可扭了腰了不曾？叫丫頭們搥一搥。」劉姥姥道：「那裡說的我這麼嬌嫩了？那一天不跌兩下子，都要搥起來，還了得呢！」", "D": "一個較有年紀的說：「該死的東西！到市上來，只這規紀亦就不懂？要做什麼生意？汝說幾斤幾兩，難道他的錢汝敢拿嗎？」「難道我們的東西，該白送給他的嗎？」參不平地回答"}, "answer": "B", "explain": "答案(B)。女婿的技巧是「借對方的邏輯反打對方」：岳父說會叫是因為脖子長，女婿就舉脖子短的蝦蟆也會叫，讓岳父自打嘴巴。(B)王導說「排名在前就比較厲害」（王、葛），諸葛恢就用同樣的邏輯回應：說「驢、馬」時驢在前，難道驢比馬強？一樣是順著對方的推論舉反例。(A)只是一般問答；(C)劉姥姥是自我解嘲、說自己身子粗壯；(D)參是不平地反問，但沒有借用對方的推論邏輯。", "skill": "比較「語言技巧」時，先把文中技巧濃縮成公式（這題是：對方說A因為B→我舉『沒有B也有A』的反例），再看選項是否套得上同一公式。"}], "difficulty": "中", "label": "105學測", "year": 105, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc105-15", "exam": "xc105", "nums": [15], "form": "單題", "img": "img/xc105-15.png", "source": "司馬遷《史記‧管晏列傳》", "author": "司馬遷", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "管仲曰：「吾始困時，嘗與鮑叔賈，分財利，多自與，鮑叔不以我為貪，知我貧也。吾嘗為鮑叔謀事，而更窮困，鮑叔不以我為愚，知時有利不利也。吾嘗三仕三見逐於君，鮑叔不以我為不肖，知我不遭時也。吾嘗三戰三走，鮑叔不以我為怯，知我有老母也。公子糾敗，召忽死之，吾幽囚受辱；鮑叔不以我為無恥，知我不羞小節，而恥功名不顯於天下也。生我者父母，知我者鮑子也！」", "translation": "管仲說：「我當初窮困時，曾和鮑叔一起做生意，分錢時自己多拿，鮑叔不認為我貪心，知道我窮。我曾替鮑叔謀劃事情，結果反而更窮困，鮑叔不認為我笨，知道時機有利有不利。我曾三次做官三次被國君趕走，鮑叔不認為我沒才能，知道我沒遇上好時機。我曾三次打仗三次逃跑，鮑叔不認為我膽小，知道我家有老母要奉養。公子糾失敗，召忽為他殉死，我卻被囚禁受辱，鮑叔不認為我不知羞恥，知道我不以小節為羞，而是以功名不能顯揚天下為恥。生我的是父母，了解我的是鮑叔啊！」", "keywords": [{"w": "賈", "m": "做生意"}, {"w": "不肖", "m": "沒有才能"}, {"w": "見逐", "m": "被驅逐"}, {"w": "走", "m": "逃跑"}, {"w": "小節", "m": "小的節操、細節"}], "questions": [{"n": 15, "qtype": "單選", "stem": "下列符合管仲對自己描述的選項是：", "options": {"A": "治國才能不如鮑叔牙", "B": "因鮑叔牙提拔而顯名", "C": "謀大事難免不拘小節", "D": "未因功名而不顧小節"}, "answer": "C", "explain": "答案(C)。管仲自己說「不羞小節，而恥功名不顯於天下」，意思是為了成就大功名，不拘泥小的節操，正是「謀大事難免不拘小節」。(A)文中沒有比較兩人的治國才能；(B)本段沒有提到鮑叔牙提拔他；(D)剛好說反了：管仲是為了功名而不顧小節，不是「未因功名而不顧小節」。", "skill": "找人物「自我評價」時，鎖定文中的總結句（這題是最後的「不羞小節，而恥功名不顯」），選項跟它方向相反的先刪。"}], "difficulty": "易", "label": "105學測", "year": 105, "kind": "學測", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "鴻門宴"}, {"id": "xc105-17", "exam": "xc105", "nums": [17], "form": "單題", "img": "img/xc105-17.png", "source": "魏徵〈諫太宗十思疏〉、李斯〈諫逐客書〉、顧炎武〈廉恥〉等", "author": "多家", "genre": "說理議論", "types": ["寫作手法", "句意理解"], "passage": "(A)居廟堂之高，則憂其民；處江湖之遠，則憂其君（范仲淹〈岳陽樓記〉）\n(B)物不產於秦，可寶者多；士不產於秦，而願忠者眾（李斯〈諫逐客書〉）\n(C)欲流之遠者，必浚其泉源；思國之安者，必積其德義（魏徵〈諫太宗十思疏〉）\n(D)貨惡其棄於地也，不必藏於己；力惡其不出於身也，不必為己（《禮記‧禮運》）\n(E)松柏後凋於歲寒，雞鳴不已於風雨；彼眾昏之日，固未嘗無獨醒之人也（顧炎武〈廉恥〉）", "translation": "(A)在朝廷做大官，就擔憂百姓；退居江湖，就擔憂國君。(B)不是秦國出產的東西，值得珍視的很多；不是秦國出身的人才，願意效忠的也很多。(C)想要水流得遠，一定要疏通源頭；想要國家安定，一定要累積德義。(D)厭惡財貨被丟棄在地上，但不一定要藏為己有；厭惡力氣不從自己身上使出來，但不一定是為了自己。(E)松柏在嚴寒中最後凋零，雞在風雨中仍不停啼叫；在眾人昏昧的時代，本來就不是沒有清醒的人。", "keywords": [{"w": "浚", "m": "疏通"}, {"w": "惡", "m": "厭惡（ㄨˋ）"}, {"w": "後凋", "m": "最後凋零"}], "questions": [{"n": 17, "qtype": "多選", "stem": "右圖是一則戒菸廣告，「持槍」的剪影用來類比「持菸」的手勢，意謂兩者同具危險性。下列文句「；」的前後，具有類似表意方式的選項是：", "options": {"A": "居廟堂之高，則憂其民；處江湖之遠，則憂其君", "B": "物不產於秦，可寶者多；士不產於秦，而願忠者眾", "C": "欲流之遠者，必浚其泉源；思國之安者，必積其德義", "D": "貨惡其棄於地也，不必藏於己；力惡其不出於身也，不必為己", "E": "松柏後凋於歲寒，雞鳴不已於風雨；彼眾昏之日，固未嘗無獨醒之人也"}, "answer": "BCE", "explain": "答案(B)(C)(E)。題目要找「用前句的事物類比後句的道理」。(A)前後是兩種處境並列，都在講憂國憂民，不是拿一件事比另一件事。(B)正確：用「物不產於秦卻很珍貴」類比「士不產於秦卻願效忠」。(C)正確：用「水要流遠須疏通源頭」類比「國要安定須積德義」。(D)前後是兩件並列的事（財貨、勞力），沒有類比關係。(E)正確：用松柏耐寒、雞鳴不止的自然現象，類比亂世中仍有清醒堅守的人。", "skill": "判斷類比：看前後兩句是不是「具體事物→抽象道理」，而且句型相似、可以畫等號；只是並列兩件同類事就不是類比。"}], "difficulty": "中", "label": "105學測", "year": 105, "kind": "學測", "textcat": "部定古文", "textcat2": "生活情境文本", "linked_core": "大同與小康、諫逐客書、諫太宗十思疏、岳陽樓記、廉恥"}, {"id": "xc105-18", "exam": "xc105", "nums": [18], "form": "單題", "img": "img/xc105-18.png", "source": "王維〈終南山〉、〈飲馬長城窟行〉、晏幾道〈蝶戀花〉、杜牧〈江南春〉、白居易〈長恨歌〉", "author": "多家", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "(A)白雲迴望合，青靄入看無（王維〈終南山〉）\n(B)青青河畔草，綿綿思遠道（〈飲馬長城窟行〉）\n(C)紅燭自憐無好計，夜寒空替人垂淚（晏幾道〈蝶戀花〉）\n(D)千里鶯啼綠映紅，水村山郭酒旗風（杜牧〈江南春〉）\n(E)行宮見月傷心色，夜雨聞鈴腸斷聲（白居易〈長恨歌〉）", "translation": "(A)回頭看，白雲合攏在一起；走進去看，青色霧氣又不見了。(B)河邊的草青青一片，綿延不斷，讓人思念遠方的人。(C)紅燭可憐自己沒有好辦法，只能在寒夜裡白白替人流淚。(D)千里江南處處鶯啼，綠葉映著紅花，水邊村莊、山城外，酒旗在風中飄。(E)在行宮看到月亮，月色都讓人傷心；夜雨中聽見鈴聲，聲聲讓人斷腸。", "keywords": [{"w": "青靄", "m": "青色的霧氣"}, {"w": "綿綿", "m": "連綿不斷"}, {"w": "郭", "m": "外城"}, {"w": "行宮", "m": "帝王出行時住的宮殿"}], "questions": [{"n": 18, "qtype": "多選", "stem": "文學作品常將個人的情感投射到外在景物，再透過對景物的狀寫，反映出人物的情思。例如〈聽海〉的歌詞：「聽海哭的聲音，嘆息著誰又被傷了心，卻還不清醒。……聽海哭的聲音，這片海未免也太多情，悲泣到天明。」表面上是海在悲泣，其實真正哭泣、嘆息的是聽海的人。下列文句，運用這種手法的選項是：", "options": {"A": "白雲迴望合，青靄入看無", "B": "青青河畔草，綿綿思遠道", "C": "紅燭自憐無好計，夜寒空替人垂淚", "D": "千里鶯啼綠映紅，水村山郭酒旗風", "E": "行宮見月傷心色，夜雨聞鈴腸斷聲"}, "answer": "CE", "explain": "答案(C)(E)。題目要找「把人的情感投射到景物上」（移情）。(C)蠟燭流蠟本來只是現象，作者說它「自憐」「替人垂淚」，其實是人在流淚——移情。(E)月色本身不會傷心、鈴聲本身不會斷腸，是唐玄宗思念楊貴妃的悲傷投射到月與鈴上——移情。(A)客觀描寫山中雲霧的變化；(B)由青草綿延聯想到思念，是起興，草本身沒有被賦予人的情感；(D)單純描寫江南春景。", "skill": "移情判斷：問自己「這個景物本身會有這種情緒嗎？」不會，卻被寫成有，就是人的情感投射。"}], "difficulty": "中", "label": "105學測", "year": 105, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc105-19", "exam": "xc105", "nums": [19], "form": "單題", "img": "img/xc105-19.png", "source": "《論語》、《孟子》", "author": "孔子、孟子", "genre": "經典語錄", "types": ["主旨寓意", "句意理解"], "passage": "(A)里仁為美。擇不處仁，焉得智（《論語‧里仁》）\n(B)舜何人也？予何人也？有為者亦若是（《孟子‧滕文公上》）\n(C)譬如為山，未成一簣，止，吾止也；譬如平地，雖覆一簣，進，吾往也（《論語‧子罕》）\n(D)輿薪之不見，為不用明焉；百姓之不見保，為不用恩焉。故王之不王，不為也，非不能也（《孟子‧梁惠王上》）\n(E)我未見好仁者、惡不仁者。……有能一日用其力於仁矣乎？我未見力不足者（《論語‧里仁》）", "translation": "(A)居住在有仁德風氣的地方才好。選擇住處不挑有仁德的地方，怎能算聰明？(B)舜是什麼人？我是什麼人？有作為的人也能像他一樣。(C)好比堆山，只差一筐土就完成，停下來，是我自己停的；好比填平地，雖然才倒下一筐土，繼續前進，是我自己要往前的。(D)看不見一車柴，是因為不肯用眼力；百姓得不到保護，是因為不肯施恩。所以大王不能稱王天下，是不肯做，不是做不到。(E)我沒見過真正愛好仁、厭惡不仁的人……有誰能哪一天把力氣用在仁上嗎？我沒見過力量不夠的。", "keywords": [{"w": "簣", "m": "盛土的竹筐"}, {"w": "輿薪", "m": "一車柴"}, {"w": "王之不王", "m": "大王不能稱王天下（後「王」讀ㄨㄤˋ）"}], "questions": [{"n": 19, "qtype": "多選", "stem": "儒家認為人擁有主體性和道德意志，故能志學進德、踐仁臻聖；此亦孔子「仁遠乎哉？我欲仁，斯仁至矣」之意。下列文句，表達上述意涵的選項是：", "options": {"A": "里仁為美。擇不處仁，焉得智", "B": "舜何人也？予何人也？有為者亦若是", "C": "譬如為山，未成一簣，止，吾止也；譬如平地，雖覆一簣，進，吾往也", "D": "輿薪之不見，為不用明焉；百姓之不見保，為不用恩焉。故王之不王，不為也，非不能也", "E": "我未見好仁者、惡不仁者。好仁者，無以尚之；惡不仁者，其為仁矣，不使不仁者加乎其身。有能一日用其力於仁矣乎？我未見力不足者"}, "answer": "BCDE", "explain": "答案(B)(C)(D)(E)。題目要的是「人有主體性，成德與否在自己決定」。(B)舜和我都是人，只要肯做就能和他一樣——自己決定。(C)停也是「吾止」，進也是「吾往」——成敗操之在我。(D)不是做不到而是不肯做——強調意志。(E)沒見過肯用力行仁卻力量不夠的人——行仁只看肯不肯。(A)講的是要選擇有仁德的環境居住，重點在外在環境，不是自己的道德意志。", "skill": "抓題幹關鍵詞（主體性＝靠自己），選項中出現「吾」「為不為」「有為者」這類強調自身意願的字眼，通常就是答案；強調環境、外力的則排除。"}], "difficulty": "中", "label": "105學測", "year": 105, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc105-21", "exam": "xc105", "nums": [21], "form": "單題", "img": "img/xc105-21.png", "source": "沈括《夢溪筆談》", "author": "沈括", "genre": "筆記小品", "types": ["比較閱讀", "文意推論"], "passage": "甲、藏書畫者，多取空名，偶傳為鍾、王、顧、陸之筆，見者爭售，此所謂「耳鑒」。又有觀畫而以手摸之，相傳以謂色不隱指者為佳畫，此又在耳鑒之下，謂之「揣骨聽聲」。\n乙、書畫之妙，當以神會，難可以形器求也。世之觀畫者，多能指摘其間形象、位置、彩色瑕疵而已，至於奧理冥造者，罕見其人。如彥遠《畫評》言：「王維畫物，多不問四時，如畫花，往往以桃、杏、芙蓉、蓮花同畫一景。」", "translation": "甲、收藏書畫的人，大多只看重名氣，偶然聽說是鍾繇、王羲之、顧愷之、陸探微的作品，看到的人就搶著買，這叫「用耳朵鑑定」。還有人看畫時用手去摸，相傳顏色摸起來不突起的就是好畫，這比「耳鑒」更差，叫做「摸骨聽聲（像算命一樣）」。\n乙、書畫的妙處，要用心神去領會，很難從外在形體去追求。一般看畫的人，大多只會挑剔畫中形象、位置、色彩的毛病罷了，至於能體會深奧道理、自然天成之境界的人，很少見。像張彥遠《畫評》說：「王維畫東西，常常不管四季，例如畫花，常把桃花、杏花、芙蓉、蓮花畫在同一個景裡。」", "keywords": [{"w": "空名", "m": "虛名"}, {"w": "售", "m": "買（此處指搶購）"}, {"w": "神會", "m": "用心神領會"}, {"w": "指摘", "m": "挑出毛病"}, {"w": "奧理冥造", "m": "深奧的道理、自然天成的意境"}], "questions": [{"n": 21, "qtype": "多選", "stem": "閱讀下列二文，選出符合作者觀點的選項：", "options": {"A": "耳鑒經由名家認可，是評斷書畫作品優劣的重要參考", "B": "耳鑒雖然是甄別畫作的好方法，但不如以手摸畫確實", "C": "世人品鑒書畫，往往重視創作者的名聲及其表現技巧", "D": "高妙的畫境可由創作者自由創造，不必符合真實情境", "E": "畫作好壞關鍵在於形象是否逼肖、空間布置是否妥適"}, "answer": "CD", "explain": "答案(C)(D)。(C)正確：甲文說大家「多取空名」——重名聲；乙文說世人「多能指摘其間形象、位置、彩色瑕疵」——重技巧表現。(D)正確：乙文舉王維把不同季節的花畫在同一景，作者認為這是「以神會」的高妙境界，不必合乎真實。(A)(B)錯：作者批評「耳鑒」只看名氣，手摸畫更「在耳鑒之下」，兩者都不是好方法。(E)錯：作者認為只看形象、位置是一般人的眼光，真正的關鍵是「神會」。", "skill": "比較閱讀先找作者的「褒」與「貶」：凡是作者用「此所謂」「而已」「在…之下」貶低的做法，選項若說它是好方法就錯。"}], "difficulty": "中", "label": "105學測", "year": 105, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc105-22", "exam": "xc105", "nums": [22], "form": "單題", "img": "img/xc105-22.png", "source": "連橫〈臺灣通史序〉、蘇軾〈赤壁賦〉、曹丕〈典論論文〉、韓愈〈師說〉、歸有光〈項脊軒志〉", "author": "多家", "genre": "其他", "types": ["典故出處", "文意推論"], "passage": "(A)是以郢書燕說，猶存其名；晉乘楚杌，語多可採\n(B)釃酒臨江，橫槊賦詩；固一世之雄也，而今安在哉\n(C)故西伯幽而演易，周旦顯而制禮，不以隱約而弗務，不以康樂而加思\n(D)聖人無常師。孔子師郯子、萇弘、師襄、老聃\n(E)蜀清守丹穴，利甲天下，其後秦皇帝築女懷清臺", "translation": "(A)所以即使像郢人寫信、燕人誤解那樣穿鑿附會，史書還是保存了名號；晉國的《乘》、楚國的《檮杌》，內容也多有可取之處。(B)曹操面對江水斟酒，橫拿長矛吟詩，本來是一代英雄，如今又在哪裡呢？(C)所以周文王被囚禁時推演《易》，周公顯達時制定禮樂，不因困頓就不努力，不因安樂就改變心思。(D)聖人沒有固定的老師，孔子曾向郯子、萇弘、師襄、老聃學習。(E)巴蜀寡婦清守著丹砂礦，獲利天下第一，後來秦始皇為她築了女懷清臺。", "keywords": [{"w": "郢書燕說", "m": "比喻穿鑿附會、曲解原意"}, {"w": "乘、杌", "m": "晉國史書《乘》、楚國史書《檮杌》"}, {"w": "釃酒", "m": "斟酒"}, {"w": "隱約", "m": "困頓不得志"}, {"w": "加思", "m": "轉移心思"}], "questions": [{"n": 22, "qtype": "多選", "stem": "適當運用典故，可豐富文章內涵，也可使表意委婉含蓄。關於下列文句使用典故的目的，詮釋正確的選項是：", "options": {"A": "是以郢書燕說，猶存其名；晉乘楚杌，語多可採——連橫以燕相穿鑿附會郢人書信事，說明臺灣舊有史籍頗多誤謬闕漏", "B": "釃酒臨江，橫槊賦詩；固一世之雄也，而今安在哉——客用曹孟德之典，意在強調年命雖不可永，但事功終不為人所忘", "C": "故西伯幽而演易，周旦顯而制禮，不以隱約而弗務，不以康樂而加思——曹丕藉西伯、周旦二人之事，指出人的創作意識會隨境遇不同而調整修正", "D": "聖人無常師。孔子師郯子、萇弘、師襄、老聃——韓愈引孔子之例，闡明「術業有專攻」、「師不必賢於弟子」，使士大夫恥於從師的觀念不攻自破", "E": "蜀清守丹穴，利甲天下，其後秦皇帝築女懷清臺——歸有光藉巴蜀寡婦事，申明不甘久處於敗屋、終將有所為的抱負，同時表達對祖母、母親的感念"}, "answer": "DE", "explain": "答案(D)(E)。(D)正確：韓愈舉孔子向郯子等人學習，證明「師不必賢於弟子」「術業有專攻」，打破士大夫恥於從師的觀念。(E)正確：歸有光用巴蜀寡婦清守家業、終被秦皇表揚的事，表明自己雖處破屋也終將有所作為，並含有對守家的祖母、母親的感念。(A)錯：連橫的意思是古代史書即使有穿鑿附會，仍保存了史事，晉、楚的史書也多可採——藉此反襯臺灣連這樣的史書都沒有，不是在說臺灣舊史錯誤多。(B)錯：客引曹操，是說連一代英雄也終歸消逝，強調人生短暫，而不是說事功不被遺忘。(C)錯：曹丕說周文王、周公不論窮困或顯達都不放棄著述，強調「不因境遇改變」，不是「隨境遇調整」。", "skill": "典故題先想「這句話在原文的上下文要證明什麼」，再看選項的詮釋方向是否相同；常見陷阱是把作者的意思說反。"}], "difficulty": "難", "label": "105學測", "year": 105, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "典論論文、師說、赤壁賦、項脊軒志、臺灣通史序"}, {"id": "xc105-23", "exam": "xc105", "nums": [23], "form": "單題", "img": "img/xc105-23.png", "source": "李白〈聽蜀僧濬彈琴〉；洛夫〈客心洗流水，餘響入霜鐘——贈李白〉", "author": "李白、洛夫", "genre": "古典詩詞曲", "types": ["比較閱讀", "詩詞賞析"], "passage": "蜀僧抱綠綺，西下峨眉峰。為我一揮手，如聽萬壑松。客心洗流水，餘響入霜鐘。不覺碧山暮，秋雲暗幾重。（李白〈聽蜀僧濬彈琴〉）", "translation": "蜀地的僧人抱著名琴綠綺，從西邊的峨眉山走下來。他為我揮手彈奏，琴聲好像千山萬谷的松濤。琴聲如流水洗滌了我這個旅人的心，餘音融入秋天的鐘聲裡。不知不覺青山已到黃昏，秋天的雲層層暗了下來。", "keywords": [{"w": "綠綺", "m": "琴名"}, {"w": "萬壑", "m": "千山萬谷"}, {"w": "客心", "m": "旅人的心"}, {"w": "霜鐘", "m": "秋天的鐘聲"}], "questions": [{"n": 23, "qtype": "多選", "stem": "閱讀下列二詩，選出敘述正確的選項：（洛夫詩見截圖）", "options": {"A": "洛夫詩的「客人」和「他」，即李白詩的「蜀僧濬」", "B": "洛夫詩以「廊下羅列的空酒罈」比喻李白懷才不遇的落寞", "C": "李白詩的「暮」、「秋」和洛夫詩的「霜飛」，都含有對時間的感懷", "D": "李白詩的「流水」和洛夫詩的「水盆風波不息」，都形容心情的洶湧紛亂", "E": "洛夫詩借李白原詩的兩句加以延展，呈現李白的生命際遇和波折後的體悟"}, "answer": "BCE", "explain": "答案(B)(C)(E)。(B)正確：洛夫寫「心情寂寂如廊下羅列的空酒罈」，接著寫流放夜郎的不甘，用空酒罈比喻李白不得志的落寞。(C)正確：李白詩的「暮」「秋」、洛夫詩的「霜飛髮揚」都有時光流逝的感慨。(E)正確：洛夫詩題就借用李白的「客心洗流水，餘響入霜鐘」，再延伸寫李白被流放、晚年煉丹、最後找到自己。(A)錯：洛夫詩是「贈李白」，「客人」「他」都指李白，不是蜀僧。(D)錯：李白詩的「流水」是指像流水般的琴聲洗滌心靈，是平靜，不是洶湧紛亂。", "skill": "古今詩對讀：先弄清楚現代詩的主角是誰（看詩題「贈某某」），再把古詩的關鍵句翻成白話，對照選項說法。"}], "difficulty": "中", "label": "105學測", "year": 105, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk105-3", "exam": "zk105", "nums": [3], "form": "單題", "img": "img/zk105-3.png", "source": "《西遊記》第七回", "author": "吳承恩", "genre": "其他", "types": ["句意理解", "文意推論"], "passage": "真個光陰迅速，不覺七七四十九日，老君的火候俱全。忽一日，開爐取丹，那大聖雙手侮著眼，正自揉搓流涕，只聽得爐頭聲響，猛睜睛看見光明，他就忍不住，將身一縱，跳出丹爐。", "translation": "時間過得真快，不知不覺過了四十九天，太上老君的火候已經足夠。有一天，老君開爐取丹，那時孫悟空正用雙手摀著眼睛，揉著擦著流眼淚，忽然聽到爐頂有聲響，猛一睜眼看見亮光，他就忍不住，縱身一跳，跳出了煉丹爐。", "keywords": [{"w": "侮", "m": "同「捂」，遮住"}, {"w": "火候俱全", "m": "煉丹的火候已經足夠"}], "questions": [{"n": 3, "qtype": "單選", "stem": "下列是《西遊記》中的一段文字，請依文意選出排列順序最恰當的選項：真個光陰迅速，甲、老君的火候俱全，乙、只聽得爐頭聲響，丙、猛睜睛看見光明，丁、忽一日，開爐取丹，戊、不覺七七四十九日，己、那大聖雙手侮著眼，正自揉搓流涕，他就忍不住，將身一縱，跳出丹爐。", "options": {"A": "丁戊丙甲乙己", "B": "丁己丙乙甲戊", "C": "戊甲丁己乙丙", "D": "戊乙丙己丁甲"}, "answer": "C", "explain": "先抓時間線：開頭說「光陰迅速」，最自然接的是「不覺七七四十九日」（戊），時間到了，所以「老君的火候俱全」（甲）。火候夠了才會「忽一日，開爐取丹」（丁）。開爐時要描寫悟空當下的樣子：他正摀著眼睛揉眼淚（己），接著「只聽得爐頭聲響」（乙），聲音讓他「猛睜睛看見光明」（丙），最後才「忍不住，將身一縱，跳出丹爐」。順序是戊甲丁己乙丙，選(C)。(A)(B)用「忽一日」開頭，接不上「光陰迅速」；(D)把「爐頭聲響」放在火候俱全之前，因果顛倒。", "skill": "排序題先找時間詞（不覺…日、忽一日）定骨架，再依「聽到→睜眼→行動」的感官因果排細節。"}], "difficulty": "易", "label": "105指考", "year": 105, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk105-4", "exam": "zk105", "nums": [4], "form": "單題", "img": "img/zk105-4.png", "source": "喬吉〈水仙子‧重觀瀑布〉", "author": "喬吉", "genre": "古典詩詞曲", "types": ["詩詞賞析", "主旨寓意"], "passage": "天機織罷月梭閒，石壁高垂雪練寒，冰絲帶雨懸霄漢。幾千年曬未乾，露華涼人怯衣單。似白虹飲澗，玉龍下山，晴雪飛灘。", "translation": "天上的織布機織完了，月亮做的梭子也閒了下來，石壁上高高垂掛著一匹雪白冰冷的白絹，像冰絲帶著雨水懸在天空中。掛了幾千年都曬不乾，水氣涼得讓人覺得衣服太單薄。它像白虹在山澗喝水，像玉龍衝下山來，又像晴天裡雪花飛濺在河灘上。", "keywords": [{"w": "雪練", "m": "雪白的絹，比喻瀑布"}, {"w": "霄漢", "m": "天空"}, {"w": "露華", "m": "水氣、露水"}], "questions": [{"n": 4, "qtype": "單選", "stem": "關於下列散曲的敘寫主題，說明正確的選項是：", "options": {"A": "七夕牛女之會", "B": "山中雪夜之境", "C": "飛瀑奔騰之景", "D": "漂泊無依之情"}, "answer": "C", "explain": "整首曲子一直在用比喻描寫同一個東西：從石壁「高垂」、「懸霄漢」的「雪練」「冰絲」，到「幾千年曬未乾」，再到「白虹飲澗，玉龍下山，晴雪飛灘」，都是從高處垂下、衝進山澗、水花四濺的瀑布，所以是(C)飛瀑奔騰之景。(A)「天機」「月梭」只是借織女織布的意象來比喻白練，並不是寫牛郎織女相會。(B)「雪」「寒」都是比喻水色白、水氣涼，而且「晴雪」說的是晴天，不是雪夜。(D)「人怯衣單」是靠近瀑布感到涼意，不是漂泊之苦。", "skill": "詩詞猜主題時，把所有比喻的「本體」找出來，全篇比喻都指向同一個東西，那就是主題。"}], "difficulty": "易", "label": "105指考", "year": 105, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk105-5", "exam": "zk105", "nums": [5], "form": "單題", "img": "img/zk105-5.png", "source": "盧摯〈沉醉東風〉；選項為古典詩句", "author": "盧摯", "genre": "古典詩詞曲", "types": ["字詞解釋", "詩詞賞析"], "passage": "恰離了綠水青山那搭，早來到竹籬茅舍人家。", "translation": "才剛離開綠水青山那個地方，就已經來到竹籬茅舍的農家。", "keywords": [{"w": "恰", "m": "剛剛、才"}, {"w": "那搭", "m": "那裡、那個地方"}, {"w": "早", "m": "已經（把時間提前的說法）"}], "questions": [{"n": 5, "qtype": "單選", "stem": "盧摯〈沉醉東風〉：「恰離了綠水青山那搭，早來到竹籬茅舍人家」，就事件發生先後而言，「來到竹籬茅舍」實際上晚於「離了綠水青山」，卻加上「早」字把時間刻意提前，使文意靈動有味。下列文句，「早」字具有相同作用的選項是：", "options": {"A": "小荷才露尖尖角，早有蜻蜓立上頭", "B": "午夢任隨鳩喚覺，早朝又聽鹿催班", "C": "回羨耕夫閒勝我，早收雞犬閉柴扉", "D": "定有奸謀陰禍起，早須排備莫惶驚"}, "answer": "A", "explain": "題目的「早」是「才…，早（已經）…」的句型：後發生的事卻說成「已經」發生，讓兩件事幾乎同時，畫面很輕快。(A)楊萬里〈小池〉：荷葉「才」剛露出尖角，蜻蜓「早」已站在上面，蜻蜓停上去其實一定在荷葉露出之後，卻用「早」說得像早就在那兒，和題目同一種作用。(B)「早朝」是早上上朝，是名詞，不是時間提前。(C)「早收雞犬」是說農夫很早就收工關門，只是「時間早」的意思。(D)「早須排備」是「要及早準備」，表示提早預防，不是把後發生的事說成先發生。", "skill": "看到「才／恰……早……」的對照句型，就想到「把後發生的事說成已經發生」的時間壓縮效果。"}], "difficulty": "中", "label": "105指考", "year": 105, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk105-7", "exam": "zk105", "nums": [7], "form": "單題", "img": "img/zk105-7.png", "source": "陸游〈十一月四日風雨大作〉其二、〈暮春〉", "author": "陸游", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感", "比較閱讀"], "passage": "甲、僵臥孤村不自哀，尚思為國戍輪臺。夜闌臥聽風吹雨，鐵馬冰河入夢來。\n乙、數間茅屋鏡湖濱，萬卷藏書不救貧。燕去燕來還過日，花開花落即經春。開編喜見平生友，照水驚非曩歲人。自笑滅胡心尚在，憑高慷慨欲忘身。", "translation": "甲：我直挺挺躺在孤零零的村子裡，卻不為自己悲哀，心裡還想著替國家去守衛邊疆。夜深了躺著聽風吹雨打，夢裡出現披甲戰馬奔過結冰河流的戰場。\n乙：我住在鏡湖邊幾間茅屋裡，藏書萬卷也救不了貧窮。燕子來來去去日子照樣過，花開花落春天又過去了。翻開書像見到一生的老朋友般高興，照著水面卻驚覺自己已不是當年的模樣。自己都覺得好笑：消滅胡人的心還在，登高時情緒激昂，幾乎想奮不顧身。", "keywords": [{"w": "僵臥", "m": "直挺挺躺著，形容年老體衰"}, {"w": "戍輪臺", "m": "守衛邊疆"}, {"w": "夜闌", "m": "夜深"}, {"w": "曩歲", "m": "往年"}, {"w": "忘身", "m": "奮不顧身"}], "questions": [{"n": 7, "qtype": "單選", "stem": "閱讀下列二詩，選出敘述正確的選項：", "options": {"A": "甲詩「不自哀」暗示老驥伏櫪，乙詩「自笑」暗示豪情未減", "B": "甲詩「臥聽」形容置身事外，乙詩「忘身」形容不知老之將至", "C": "甲詩「尚思」表達仍願效力疆場，乙詩「驚非」表達遇見昔日戰友的哀嘆", "D": "甲詩「風吹雨」暗喻國家風雨飄搖，乙詩「燕去燕來」暗喻國運否極泰來"}, "answer": "A", "explain": "兩首詩都是老年陸游的作品，共同主旨是「人老了、心不死」。(A)甲詩人雖僵臥孤村卻「不自哀」，還想「為國戍輪臺」，正是老驥伏櫪、志在千里；乙詩「自笑滅胡心尚在」，笑自己老了還放不下收復失土的心，豪情未減，正確。(B)「臥聽風吹雨」是夜裡躺著聽風雨，接著就夢到「鐵馬冰河」，心一直在戰場，不是置身事外；「忘身」是激動到奮不顧身，不是「不知老之將至」。(C)「尚思」正確，但「照水驚非曩歲人」是照水看到自己的老態，不是遇見戰友；「喜見平生友」的「友」指的是書。(D)「風吹雨」是題目說的實際天氣；「燕去燕來」是寫時光流轉、日子一天天過，和國運好轉無關。", "skill": "讀詩先判斷「實景」還是「比喻」，再用全詩主旨檢查每個詞的解讀方向是否一致。"}], "difficulty": "中", "label": "105指考", "year": 105, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk105-8", "exam": "zk105", "nums": [8], "form": "單題", "img": "img/zk105-8.png", "source": "王陽明《傳習錄》", "author": "王陽明", "genre": "經典語錄", "types": ["主旨寓意", "文意推論"], "passage": "惟是道理自有厚薄。比如身是一體，把手足捍頭目，豈是偏要薄手足？其道理合如此。禽獸與草木同是愛的，把草木去養禽獸，又忍得。人與禽獸同是愛的，宰禽獸以養親，與供祭祀，燕賓客，心又忍得。至親與路人同是愛的，如簞食豆羹，得則生，不得則死。不能兩全，寧救至親，不救路人，心又忍得。這是道理合該如此。", "translation": "道理本來就有厚薄之分。比如身體是一個整體，遇到危險時用手腳去保護頭和眼睛，難道是故意輕視手腳嗎？是道理本來應該這樣。禽獸和草木都是我們愛惜的，但拿草木去餵養禽獸，心裡忍得下。人和禽獸都是我們愛惜的，但宰殺禽獸來奉養父母、祭祀、宴請賓客，心裡也忍得下。至親和陌生人都是我們愛的，但如果只有一碗飯一碗湯，得到就能活、得不到就會死，無法兩全時，寧可救至親而不救陌生人，心裡也忍得下。這是道理本來就該如此。", "keywords": [{"w": "捍", "m": "保護、抵擋"}, {"w": "燕", "m": "同「宴」，宴請"}, {"w": "簞食豆羹", "m": "一小筐飯、一碗湯，指很少的食物"}], "questions": [{"n": 8, "qtype": "單選", "stem": "閱讀下文，選出最符合文中所闡述道理的選項：", "options": {"A": "親親有術，尊賢有等", "B": "人君之道，清淨無為，務在博愛", "C": "弟子，入則孝，出則悌，謹而信，汎愛眾", "D": "聖王之政，普覆兼愛，不私近密，不忽疎遠"}, "answer": "A", "explain": "文章第一句就是主旨：「道理自有厚薄」。萬物都愛，但愛有先後、有輕重，所以親人優先於路人、人優先於禽獸。(A)「親親有術，尊賢有等」說親愛親人有一定的分寸、尊敬賢人有等級差別，正是「愛有差等」，最符合。(B)「清淨無為、務在博愛」是無為與博愛，沒有講厚薄先後。(C)出自《論語》，講孝悌、謹信、汎愛眾，是做人的基本修養，重點不在「愛有厚薄」。(D)「不私近密，不忽疎遠」主張對親近和疏遠的人一樣，恰好和本文「寧救至親，不救路人」相反。", "skill": "說理文先找主旨句（常在第一句），再看選項是「同意」還是「反對」這個主張，反義選項最容易刪。"}], "difficulty": "中", "label": "105指考", "year": 105, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk105-9", "exam": "zk105", "nums": [9], "form": "單題", "img": "img/zk105-9.png", "source": "對聯（出處待查）", "author": "", "genre": "其他", "types": ["文化常識", "典故出處"], "passage": "甲、春暖杏林花吐錦，泉流橘井水生香\n乙、擊之有聲乃成器用，薄其所厚不惜工夫\n丙、隨地可安身莫訝乾坤為逆旅，當前堪適意且邀風月作良朋", "translation": "甲：春天溫暖，杏林裡花開得像錦繡；泉水流過橘井，水也散發香氣。\n乙：敲打它能發出聲響，才成為有用的器物；把厚的打薄，不吝惜花費功夫。\n丙：到哪裡都可以安身，不必驚訝天地就像一間旅館；眼前就能讓人舒適愜意，暫且邀清風明月做好朋友。", "keywords": [{"w": "杏林", "m": "三國董奉替人治病不收錢，只請病人種杏樹，後以杏林代稱醫界"}, {"w": "橘井", "m": "傳說蘇耽以井水、橘葉治病，代稱醫術"}, {"w": "逆旅", "m": "旅館"}, {"w": "岐黃", "m": "岐伯與黃帝，代稱醫學"}], "questions": [{"n": 9, "qtype": "單選", "stem": "根據下列三幅對聯的內容，依序選出相應的題辭，最恰當的選項是：", "options": {"A": "桃李馥郁／開物成務／里仁為美", "B": "桃李馥郁／大筆如椽／近悅遠來", "C": "術精岐黃／大筆如椽／里仁為美", "D": "術精岐黃／開物成務／近悅遠來"}, "answer": "D", "explain": "先判斷每副對聯是給哪一行：甲用「杏林」「橘井」兩個醫學典故，是醫院、診所，配「術精岐黃」（「桃李馥郁」是讚美老師學生多）。乙說敲打成器、把厚的打薄，是打造金屬器具的工坊、五金業，配「開物成務」（開發物資、成就事業）；「大筆如椽」是稱讚文章寫得好。丙說到處可安身、天地是旅館、邀風月為友，是旅館業，配「近悅遠來」（近處的人喜歡、遠方的人來投宿）；「里仁為美」是讚美好鄰居、新居。所以選(D)。", "skill": "題辭題先抓對聯裡的「行業關鍵詞或典故」（杏林、橘井、逆旅），定出行業再對題辭。"}], "difficulty": "中", "label": "105指考", "year": 105, "kind": "指考", "textcat": "生活情境文本", "textcat2": "", "linked_core": ""}, {"id": "zk105-10", "exam": "zk105", "nums": [10, 11], "form": "題組", "img": "img/zk105-10.png", "source": "杜維運〈歷史想像與歷史真理〉（改寫）；選項引蒲松齡〈勞山道士〉、郁永河《裨海紀遊》、陶淵明〈桃花源記〉等", "author": "杜維運", "genre": "說理議論", "types": ["文意推論", "比較閱讀"], "passage": "（第11題選項）\n(A)又一客曰：「今宵最樂，然不勝酒力矣。其餞我於月宮可乎？」三人移席，漸入月中。眾視三人，坐月中飲，鬚眉畢見，如影之在鏡中。\n(B)更進半里，草木不生，地熱如炙。左右兩山多巨石，為硫氣所觸，剝蝕如粉。白氣五十餘道，皆從地底騰激而出，沸珠噴濺，出地尺許。\n(C)村中聞有此人，咸來問訊。自云：「先世避秦時亂，率妻子邑人來此絕境，不復出焉，遂與外人間隔。」問今是何世？乃不知有漢，無論魏、晉。\n(D)（張陵）其書多有禁祕，非其徒也，不得輒觀。至於化金銷玉，行符敕水，奇方妙術，萬等千條，上云羽化飛天，次稱消災滅禍。故好異者往往而尊事之。", "translation": "(A)又一位客人說：「今晚最快樂，可是我酒量不夠了。你們到月宮為我餞行好嗎？」三人移動座位，漸漸走進月亮裡。大家看他們三人坐在月中喝酒，鬍子眉毛都看得清清楚楚，像鏡子裡的影像。\n(B)再往前走半里，草木都不生長，地面熱得像火烤。左右兩座山有很多大石頭，被硫磺氣侵蝕，剝落得像粉末。五十多道白煙從地底翻騰噴出，滾燙的水珠四濺，噴出地面一尺多高。\n(C)村裡的人聽說來了這個人，都來打聽消息。他們說：「祖先為了躲避秦朝的戰亂，帶著妻兒和同鄉來到這個與世隔絕的地方，不再出去，就和外面的人隔絕了。」問現在是什麼朝代？竟不知道有漢朝，更不用說魏、晉了。\n(D)張陵的書有很多祕密禁忌，不是他的門徒不能隨便看。書裡講點金化玉、畫符唸咒治水，奇方妙術千千萬萬，最高說可以成仙飛天，其次說可以消災除禍。所以喜好奇異的人常常尊奉他。", "keywords": [{"w": "餞", "m": "設酒送行"}, {"w": "炙", "m": "烤"}, {"w": "絕境", "m": "與外界隔絕的地方"}, {"w": "輒", "m": "隨便、就"}, {"w": "直刪不妨", "m": "直接刪掉也無妨"}], "questions": [{"n": 10, "qtype": "單選", "stem": "下列敘述，不符合上文意旨的選項是：", "options": {"A": "以合乎情理與否來評斷往事是否可信，是從事歷史研究的重要原則", "B": "古今社會有所差異，史學家不能以當代社會為依據去瞭解古代社會", "C": "史學家對里俗間流傳的果報與符咒等記載，不能不抱持存疑的態度", "D": "即使有文獻記載，史學家仍可對不符現實生活經驗的內容予以否認"}, "answer": "B", "explain": "文章開頭就說「古今是有其絕相類似之處」，最了解當代社會的史學家，最能了解過去的社會。(B)說「不能以當代社會為依據去瞭解古代社會」，正好和作者相反，所以選(B)。(A)文中用「可能發生／必不可能發生」判斷可信度，就是看合不合情理，符合。(C)對誦經獲報、符咒靈驗要「將信將疑」，就是存疑，符合。(D)「必不可能發生的事件，史學家可以不顧前人言之鑿鑿，而斷然予以否認」，符合。", "skill": "「不符合」題先把作者的核心主張（通常是第一句）抓出來，選項和它唱反調的就是答案。"}, {"n": 11, "qtype": "單選", "stem": "下列文句，最符合上文「直刪不妨」的選項是：", "options": {"A": "又一客曰：「今宵最樂，然不勝酒力矣。其餞我於月宮可乎？」三人移席，漸入月中。眾視三人，坐月中飲，鬚眉畢見，如影之在鏡中", "B": "更進半里，草木不生，地熱如炙。左右兩山多巨石，為硫氣所觸，剝蝕如粉。白氣五十餘道，皆從地底騰激而出，沸珠噴濺，出地尺許", "C": "村中聞有此人，咸來問訊。自云：「先世避秦時亂，率妻子邑人來此絕境，不復出焉，遂與外人間隔。」問今是何世？乃不知有漢，無論魏、晉", "D": "（張陵）其書多有禁祕，非其徒也，不得輒觀。至於化金銷玉，行符敕水，奇方妙術，萬等千條，上云羽化飛天，次稱消災滅禍。故好異者往往而尊事之"}, "answer": "A", "explain": "「直刪不妨」指的是「妖異止於怪誕」這種完全不可能發生的神怪內容。(A)出自蒲松齡〈勞山道士〉，人可以走進月亮裡喝酒，現實中絕不可能，屬於怪誕，可以直接刪，正確。(B)出自郁永河《裨海紀遊》，描寫硫磺礦區地熱、噴氣的實景，是真實的地理觀察，可信。(C)〈桃花源記〉裡村民說祖先避秦亂躲進深山，雖然是故事，但人躲到與世隔絕之處在現實中是可能的，不屬妖異。(D)講張陵的符咒、法術，屬於文中說的「符咒靈驗」一類，作者主張「將信將疑」，不是直接刪除。", "skill": "把文中的分類標準（可能／不可能／將信將疑）當篩子，逐一把選項丟進去分類。"}], "difficulty": "中", "label": "105指考", "year": 105, "kind": "指考", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "桃花源記、勞山道士、裨海紀遊"}, {"id": "zk105-12", "exam": "zk105", "nums": [12, 13], "form": "題組", "img": "img/zk105-12.png", "source": "紀昀《閱微草堂筆記》", "author": "紀昀", "genre": "筆記小品", "types": ["句意理解", "主旨寓意"], "passage": "一老儒訓蒙鄉塾，塾側有積柴，狐所居也。鄉人莫敢犯，而學徒頑劣，乃時穢污之。一日，老儒往會葬，約明日返。諸兒因累几為臺，塗朱墨演劇。老儒突返，各撻之流血，恨恨復去。眾以為諸兒大者十一、二，小者七、八歲耳，皆怪師太嚴。次日，老儒返，云昨實未歸，乃知狐報怨也。有欲訟諸土神者，有議除積柴者，有欲往詬詈者。中一人曰：「諸兒實無禮，撻不為過，但太毒耳。吾聞勝妖當以德，以力相角，終無勝理。冤冤相報，吾慮禍不止此也。」眾乃已。此人可謂平心，亦可謂遠慮矣。", "translation": "有位老先生在鄉下私塾教小孩，私塾旁邊有一堆柴，是狐狸住的地方。鄉人都不敢冒犯，可是學生頑皮，常常弄髒柴堆。有一天，老先生去參加喪禮，說好隔天才回來。孩子們就把桌子疊成戲臺，臉上塗紅抹黑演戲。老先生突然回來，把每個孩子打到流血，氣呼呼地又走了。大家認為這些孩子大的才十一二歲，小的七八歲，都怪老師太嚴厲。隔天老先生回來，說昨天根本沒回來，大家才知道是狐狸報仇。有人想去土地神那裡告狀，有人主張把柴堆清掉，有人想去罵狐狸。其中一人說：「孩子們確實無禮，打他們不算過分，只是太狠了。我聽說要勝過妖怪應該靠德行，用武力較量，終究沒有贏的道理。冤冤相報，我擔心災禍不只這樣。」大家這才作罷。這個人可說是心平氣和，也可說是深謀遠慮了。", "keywords": [{"w": "訓蒙", "m": "教導兒童啟蒙"}, {"w": "穢污", "m": "弄髒"}, {"w": "撻", "m": "鞭打"}, {"w": "詬詈", "m": "辱罵"}, {"w": "角", "m": "較量"}], "questions": [{"n": 12, "qtype": "單選", "stem": "下列文句的解釋，正確的選項是：", "options": {"A": "「乃時穢污之」指學童無理取鬧，常出惡言污辱老儒", "B": "「塗朱墨演劇」指學童趁老師不在時，粉墨登場演戲", "C": "「有欲往詬詈者」指有人責怪老儒太嚴厲，想前去痛罵他", "D": "「諸兒實無禮，撻不為過」指學童過於無禮，笞打也沒用"}, "answer": "B", "explain": "(B)老儒出門參加喪禮，孩子們就疊桌子當戲臺、臉上塗紅塗黑演戲，就是粉墨登場，正確。(A)「之」指前面的「積柴」（狐狸的住處），是學童常常弄髒狐狸住的柴堆，不是罵老儒。(C)這時大家已經知道打人的是狐狸假扮的，所以想去罵的是狐狸，不是老儒。(D)「撻不為過」是「打他們並不過分」，不是「打也沒用」。", "skill": "代詞「之」要往前找最近的名詞；判斷情節時要注意「知道真相」前後，人物態度會改變。"}, {"n": 13, "qtype": "單選", "stem": "下列說明，最符合上文主旨的選項是：", "options": {"A": "對於頑劣的學童，適當的處罰仍有其必要性", "B": "老儒以巧計教育學童不可頑劣，不愧為良師", "C": "人狐相爭恐生禍害，因此以力爭勝並非良方", "D": "狐的行為看似報怨，實乃對世人之教育方式"}, "answer": "C", "explain": "故事的重點在最後那個人的話：「勝妖當以德，以力相角，終無勝理。冤冤相報，吾慮禍不止此也」，作者也稱讚他「平心」「遠慮」。所以主旨是不要用武力和狐狸鬥，選(C)。(A)「撻不為過」只是那人話中的一部分，不是全文重點。(B)打人的是狐狸，不是老儒，也沒有巧計。(D)文中明說「乃知狐報怨也」，狐是在報仇，不是要教育世人。", "skill": "筆記小說的主旨常藏在結尾的「評論句」（此人可謂……），先讀結尾再回頭對選項。"}], "difficulty": "易", "label": "105指考", "year": 105, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk105-14", "exam": "zk105", "nums": [14, 15], "form": "題組", "img": "img/zk105-14.png", "source": "劉向《說苑‧立節》", "author": "劉向", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "越甲至齊，雍門子狄請死之。齊王曰：「鼓鐸之聲未聞，矢石未交，長兵未接，子何務死之？為人臣之禮邪？」雍門子狄對曰：「臣聞之：昔者王田於囿，左轂鳴，車右請死之，而王曰：『子何為死？』車右對曰：『為其鳴吾君也。』王曰：『左轂鳴者，工師之罪也，子何事之有焉？』車右曰：『臣不見工師之乘，而見其鳴吾君也。』遂刎頸而死。知有之乎？」齊王曰：「有之。」雍門子狄曰：「今越甲至，其鳴吾君也，豈左轂之下哉？車右可以死左轂，而臣獨不可以死越甲也？」遂刎頸而死。是日，越人引甲而退七十里，曰：「齊王有臣鈞如雍門子狄，擬使越社稷不血食。」遂引甲而歸。", "translation": "越國軍隊來到齊國，雍門子狄請求為此而死。齊王說：「戰鼓的聲音還沒聽到，箭和石頭還沒交鋒，長兵器還沒接觸，你何必急著去死？這是做臣子的禮節嗎？」雍門子狄回答：「我聽說：從前大王在獵場打獵，左邊車軸發出響聲，車右的武士請求為此而死。大王說：『你為什麼要死？』車右回答：『因為它的響聲驚擾了我的君王。』大王說：『車軸會響，是造車工匠的罪過，和你有什麼關係？』車右說：『我沒看見工匠駕車，只看見車軸的響聲驚擾了我的君王。』就割頸自殺了。有這件事嗎？」齊王說：「有。」雍門子狄說：「現在越國軍隊來了，它驚擾我的君王，難道比不上左邊車軸的響聲嗎？車右可以為車軸響而死，我難道不能為越軍到來而死嗎？」就割頸自殺了。這一天，越軍後退七十里，說：「齊王的臣子都像雍門子狄這樣，恐怕會讓越國滅亡、無法祭祀祖先。」就撤兵回國了。", "keywords": [{"w": "越甲", "m": "越國軍隊"}, {"w": "車右", "m": "駕車者右邊的武士"}, {"w": "轂", "m": "車輪中心的軸"}, {"w": "鳴", "m": "發出聲響，此指驚擾"}, {"w": "鈞", "m": "同「均」，都"}, {"w": "血食", "m": "殺牲祭祀，代指國家存續"}], "questions": [{"n": 14, "qtype": "單選", "stem": "依據上文，敘述正確的選項是：", "options": {"A": "齊王指責雍門子狄臨陣脫逃，未善盡人臣之責", "B": "雍門子狄認為使君王陷於危殆，實為臣子之罪", "C": "齊王對於雍門子狄有所誤解，致使他自刎明志", "D": "車右為無力督導工匠製車而自責，故刎頸而死"}, "answer": "B", "explain": "雍門子狄引用車右的例子：車軸響驚擾了君王，車右就認為是自己的責任；如今敵軍逼近、讓君王受到威脅，臣子更應負責，所以(B)正確。(A)齊王只是問他「何務死之」，不是指責他逃跑。(C)齊王沒有誤解他，他是自己要以死盡忠。(D)車右明說「臣不見工師之乘」，他不是為了沒管好工匠，而是為了君王受驚擾而死。", "skill": "對話體古文要分清「誰說的」，再找人物為自己行為給出的理由句（為其……也）。"}, {"n": 15, "qtype": "單選", "stem": "關於越人「引甲而歸」的原因，敘述正確的選項是：", "options": {"A": "見齊國兵車眾多、軍容盛大，自忖無法與之為敵", "B": "車右預知越甲將至，以死勸告齊王務必提前戒備", "C": "認為齊人忠君愛國，若執意攻伐將招致亡國之禍", "D": "敬佩雍門子狄敢為死士，畏懼其不惜犧牲的氣勢"}, "answer": "C", "explain": "越人自己說：「齊王有臣鈞如雍門子狄，擬使越社稷不血食。」意思是齊國臣子都這麼忠心，打下去越國恐怕要亡國，所以撤兵，選(C)。(A)文中沒提到齊國兵車多少，而且「矢石未交」，根本還沒打。(B)車右是很久以前打獵時的事，和越軍來襲無關。(D)越人害怕的是「全齊國的臣子都像他」而導致亡國，不只是敬佩他一個人的氣勢。", "skill": "問「原因」時，直接找當事人的說話內容，原文的「曰」後面往往就是答案。"}], "difficulty": "中", "label": "105指考", "year": 105, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk105-18", "exam": "zk105", "nums": [18], "form": "單題", "img": "img/zk105-18.png", "source": "選項出自陶淵明〈歸去來辭〉、郁永河《裨海紀遊》、劉基〈賣柑者言〉、連橫〈臺灣通史序〉、白居易〈與元微之書〉", "author": "", "genre": "其他", "types": ["字詞解釋", "文化常識"], "passage": "(A)園日涉以成趣，門雖設而常關\n(B)約行二三里，渡兩小溪，皆履而涉\n(C)杭有賣果者，善藏柑，涉寒暑不潰\n(D)追懷先德，眷顧前途，若涉深淵，彌自儆惕\n(E)僕自到九江，已涉三載，形骸且健，方寸甚安", "translation": "(A)每天在園子裡散步自成樂趣，門雖然有卻常關著。\n(B)大約走了兩三里，渡過兩條小溪，都穿著鞋子涉水過去。\n(C)杭州有個賣水果的人，很會保存柑子，經過一整年冷熱都不腐爛。\n(D)追念祖先的德業，顧念未來的前途，好像要渡過深淵一樣，更加警惕自己。\n(E)我從到九江以來，已經過了三年，身體還健康，心情很安定。", "keywords": [{"w": "涉（本義）", "m": "徒步渡水：甲骨文像兩隻腳（止）在水的兩邊"}, {"w": "履", "m": "穿著鞋"}, {"w": "方寸", "m": "心"}], "questions": [{"n": 18, "qtype": "多選", "stem": "依據右表，下列「」內的字義，符合甲骨文「涉」的字形本義的選項是：（表：止＝腳板；水＝流水；涉＝？）", "options": {"A": "園日「涉」以成趣，門雖設而常關", "B": "約行二三里，渡兩小溪，皆履而「涉」", "C": "杭有賣果者，善藏柑，「涉」寒暑不潰", "D": "追懷先德，眷顧前途，若「涉」深淵，彌自儆惕", "E": "僕自到九江，已「涉」三載，形骸且健，方寸甚安"}, "answer": "BD", "explain": "表格告訴我們：「止」是腳，「水」是流水，「涉」就是兩隻腳跨過水，本義是「徒步渡水」。(A)「園日涉」是每天到園中走走，是「遊覽、走動」，不是渡水，錯。(B)渡過小溪、穿著鞋走過去，就是徒步渡水，對。(C)「涉寒暑」是經過冬夏，是「經歷」，錯。(D)「若涉深淵」是像要渡過深水，是渡水的本義（用來比喻戒慎），對。(E)「已涉三載」是已經過了三年，是「經歷」，錯。", "skill": "字形題先用部件拼出本義（腳＋水＝走過水），再看選項的受詞是「水」還是「時間／地方」。"}], "difficulty": "易", "label": "105指考", "year": 105, "kind": "指考", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "裨海紀遊、臺灣通史序"}, {"id": "zk105-19", "exam": "zk105", "nums": [19], "form": "單題", "img": "img/zk105-19.png", "source": "選項出自顏之推〈顏氏家訓〉、《左傳》、蘇軾〈赤壁賦〉、歸有光〈項脊軒志〉、諸葛亮〈出師表〉、王羲之〈蘭亭集序〉、《史記‧項羽本紀》、杜光庭〈虯髯客傳〉、韓愈〈師說〉、方苞〈左忠毅公軼事〉", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)之推不得已而仕於亂世／以其無禮於晉，且貳於楚\n(B)於是飲酒樂甚，扣舷而歌之／娘以指扣門扉曰：兒寒乎\n(C)則漢室之隆，可計日而待也／或取諸懷抱，晤言一室之內\n(D)大行不顧細謹，大禮不辭小讓／乘驢而去，其行若飛，回顧已遠\n(E)惑之不解，或師焉，或不焉／或勸以少休，公曰：吾上恐負朝廷，下恐愧吾師也", "translation": "(A)顏之推不得已在亂世做官／因為鄭國對晉國無禮，而且對楚國有二心。\n(B)於是喝酒喝得很快樂，敲著船舷唱歌／母親用手指敲著門說：孩子冷嗎？\n(C)那麼漢朝的興盛，就指日可待了／有人把心中抱負拿出來，在一間屋子裡面對面談話。\n(D)做大事不必顧及小節，行大禮不必計較小的謙讓／騎著驢子離開，走得像飛一樣，回頭一看已經很遠了。\n(E)有疑惑不能解決，有的去請教老師，有的不去／有人勸他稍微休息，左公說：我上怕辜負朝廷，下怕愧對我的老師。", "keywords": [{"w": "扣", "m": "敲擊"}, {"w": "或", "m": "有的人、有人"}, {"w": "顧", "m": "顧及／回頭看"}], "questions": [{"n": 19, "qtype": "多選", "stem": "下列各組文句「」內的字，前後意義相同的選項是︰", "options": {"A": "之推不得已而仕「於」亂世／以其無禮「於」晉，且貳於楚", "B": "於是飲酒樂甚，「扣」舷而歌之／娘以指「扣」門扉曰：兒寒乎", "C": "則漢「室」之隆，可計日而待也／或取諸懷抱，晤言一「室」之內", "D": "大行不「顧」細謹，大禮不辭小讓／乘驢而去，其行若飛，回「顧」已遠", "E": "惑之不解，「或」師焉，或不焉／「或」勸以少休，公曰：吾上恐負朝廷，下恐愧吾師也"}, "answer": "BE", "explain": "(A)前「於」是「在」（在亂世做官），後「於」是「對」（對晉國無禮），不同。(B)兩個「扣」都是「敲」：敲船舷、敲門，相同。(C)前「室」是王室、朝廷（漢朝），後「室」是房間，不同。(D)前「顧」是顧及、考慮，後「顧」是回頭看，不同。(E)兩個「或」都是不定代詞「有的人／有人」，相同。", "skill": "判斷一字多義時，把字義帶回句子翻譯一遍；能用同一個白話詞順利替換兩句，才算意義相同。"}], "difficulty": "中", "label": "105指考", "year": 105, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "鴻門宴、出師表、蘭亭集序、師說、虬髯客傳、赤壁賦、項脊軒志、左忠毅公軼事"}, {"id": "zk105-22", "exam": "zk105", "nums": [22], "form": "單題", "img": "img/zk105-22.png", "source": "選項出自《荀子‧勸學》、《戰國策‧馮諼客孟嘗君》、賈誼〈過秦論〉、《老子》、歐陽脩〈醉翁亭記〉", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "常人貴遠賤近\n(A)君子之學也以美其身\n(B)孟嘗君怪之，曰：此誰也\n(C)諸侯恐懼，會盟而謀弱秦\n(D)甘其食，美其服，安其居，樂其俗\n(E)人知從太守遊而樂，而不知太守之樂其樂也", "translation": "(A)君子做學問是用來使自身美好。\n(B)孟嘗君覺得奇怪，說：這是誰？\n(C)諸侯害怕，聚會結盟，商量要削弱秦國。\n(D)認為自己的食物香甜，認為自己的衣服美好，安於自己的住所，喜愛自己的風俗。\n(E)人們只知道跟著太守遊玩很快樂，卻不知道太守是以他們的快樂為快樂。", "keywords": [{"w": "意動用法", "m": "「以……為……」：主觀上認為某物怎樣"}, {"w": "使動用法", "m": "「使……怎樣」：讓受詞產生改變"}], "questions": [{"n": 22, "qtype": "多選", "stem": "曹丕〈典論論文〉中「常人貴遠賤近」的「貴」，是「以……為貴」的意思。下列文句「」內的字，與「貴」字用法相同的選項是：", "options": {"A": "君子之學也以「美」其身", "B": "孟嘗君「怪」之，曰：此誰也", "C": "諸侯恐懼，會盟而謀「弱」秦", "D": "「甘」其食，美其服，安其居，樂其俗", "E": "人知從太守遊而樂，而不知太守之「樂」其樂也"}, "answer": "BDE", "explain": "「貴遠」是心裡認為遠的東西可貴，叫「意動用法」（以……為……）。(A)「美其身」是讓自己的身心變美好，是「使……美」的使動用法，錯。(B)「怪之」是認為他奇怪，對。(C)「弱秦」是使秦國變弱，是使動用法，錯。(D)「甘其食」是認為食物香甜，對。(E)「樂其樂」是以百姓的快樂為快樂，對。", "skill": "分辨意動和使動：受詞真的被改變了是「使動」；只是主詞心裡這樣認為是「意動」。"}], "difficulty": "中", "label": "105指考", "year": 105, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "勸學、馮諼客孟嘗君、典論論文、醉翁亭記"}, {"id": "zk105-24", "exam": "zk105", "nums": [24], "form": "單題", "img": "img/zk105-24.png", "source": "《後漢書‧方術列傳》", "author": "范曄", "genre": "史傳人物", "types": ["句意理解", "文意推論"], "passage": "左慈字元放，廬江人也。少有神道。嘗在司空曹操坐，操從容顧眾賓曰：「今日高會，珍羞略備，所少吳松江鱸魚耳。」慈於下坐應曰：「此可得也。」因求銅盤貯水，以竹竿餌釣於盤中，須臾引一鱸魚出。操拊掌大笑，會者皆驚。操曰：「一魚不周坐席，可更得乎？」慈乃更餌鈎沉之，須臾復引出，皆長三寸餘，生鮮可愛。操使目前鱠之，周浹會者。操又謂曰：「既已得魚，恨無蜀中生薑耳。」慈曰：「亦可得也。」操恐其近即所取，因曰：「吾前遣人到蜀買錦，可過勑使者，增市二端。」語頃，即得薑還，并獲操使報命。後操使自蜀反，驗問增錦之狀及時日早晚，若符契焉。", "translation": "左慈字元放，廬江人，年輕時就有神奇的法術。他曾經在司空曹操的宴席上，曹操悠閒地看著賓客說：「今天的盛會，珍貴的菜餚大致都有了，只少了吳淞江的鱸魚。」左慈在下座回答：「這可以弄到。」於是要了一個銅盤裝水，用竹竿掛餌在盤中釣魚，一會兒就釣出一條鱸魚。曹操拍手大笑，在場的人都很驚訝。曹操說：「一條魚不夠大家吃，能再弄到嗎？」左慈又掛上餌把鉤沉下去，不久又釣出來，都有三寸多長，新鮮可愛。曹操叫人當場切成生魚片，分給在場每個人。曹操又說：「既然有了魚，可惜沒有蜀地的生薑。」左慈說：「也可以弄到。」曹操怕他在附近就近買來，就說：「我之前派人到蜀地買錦，你可以順便告訴使者，多買兩端。」話剛說完，左慈就拿著生薑回來了，還帶回曹操使者的回覆。後來曹操的使者從蜀地回來，查問多買錦的情形和時間早晚，完全吻合。", "keywords": [{"w": "珍羞", "m": "珍貴的食物（羞同「饈」）"}, {"w": "拊掌", "m": "拍手"}, {"w": "周", "m": "普遍、足夠分給"}, {"w": "鱠", "m": "把魚肉切細，生魚片"}, {"w": "周浹", "m": "遍及"}, {"w": "勑", "m": "同「敕」，告誡、吩咐"}, {"w": "端", "m": "布帛的長度單位"}, {"w": "符契", "m": "符節契約，比喻完全吻合"}], "questions": [{"n": 24, "qtype": "多選", "stem": "閱讀下文，選出正確的選項：", "options": {"A": "「操拊掌大笑，會者皆驚」是說左慈的表現讓曹操拍案叫絕，讓與會者相當訝異", "B": "「一魚不周坐席」是指魚的分量太少，不夠在場的賓主食用", "C": "「操使目前鱠之」是要求左慈當下變出魚羹，以防他作弊", "D": "「語頃，即得薑還，并獲操使報命」是指話講完不久，曹操的使者已經買回生薑", "E": "「若符契焉」是指曹操派去蜀地的使者，好像被施過符咒一般"}, "answer": "AB", "explain": "(A)左慈在銅盤裡釣出鱸魚，曹操拍手大笑、眾人驚訝，對。(B)「周」是普遍、遍及，一條魚不夠分給整桌人，對。(C)「鱠之」是讓人當場把魚切成生魚片，然後「周浹會者」分給大家吃，不是要左慈變魚羹，也沒有防作弊的意思，錯。(D)拿回生薑的是左慈，他還順便帶回曹操使者的回覆；曹操的使者是「後」來才從蜀地回來，錯。(E)「若符契焉」是說使者回報的內容和左慈說的完全吻合，像符節合在一起，不是被施符咒，錯。", "skill": "注意事件的時間先後（語頃／後）和主詞是誰，很多錯誤選項是故意把動作安在別人身上。"}], "difficulty": "中", "label": "105指考", "year": 105, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk105-nc1", "exam": "zk105", "nums": ["一"], "form": "單題", "img": "img/zk105-nc1.png", "source": "林語堂〈論幽默〉（改寫）、《論語‧先進》", "author": "林語堂；孔子弟子及再傳弟子", "genre": "經典語錄", "types": ["比較閱讀", "人物情感", "文意推論"], "passage": "子路、曾皙、冉有、公西華侍坐。子曰：「以吾一日長乎爾，毋吾以也！居則曰：『不吾知也！』如或知爾，則何以哉？」子路率爾而對曰：「千乘之國，攝乎大國之間，加之以師旅，因之以饑饉，由也為之，比及三年，可使有勇，且知方也。」夫子哂之。……（曾皙）曰：「莫春者，春服既成，冠者五、六人，童子六、七人，浴乎沂，風乎舞雩，詠而歸。」夫子喟然嘆曰：「吾與點也！」三子者出，……（曾皙）曰：「夫子何哂由也？」曰：「為國以禮，其言不讓，是故哂之。」", "translation": "子路、曾皙、冉有、公西華陪孔子坐著。孔子說：「不要因為我比你們年紀大一點，就不敢說話。你們平常總說：『沒有人了解我！』如果有人了解你們，你們要怎麼做呢？」子路急忙搶著回答：「一個擁有千輛兵車的國家，夾在大國中間，外有軍隊侵犯，內有饑荒，讓我來治理，等到三年，可以讓百姓勇敢，而且懂得道理。」孔子微微一笑。……曾皙說：「暮春時節，春天的衣服已經做好，和五六個成年人、六七個孩子，到沂水洗洗澡，在舞雩臺上吹吹風，一路唱著歌回家。」孔子長嘆一聲說：「我贊同曾點啊！」三個人出去後，……曾皙問：「老師為什麼笑子路呢？」孔子說：「治理國家要講禮讓，他說話一點都不謙讓，所以笑他。」", "keywords": [{"w": "毋吾以也", "m": "不要因為我（年長）而拘束"}, {"w": "率爾", "m": "輕率、急忙的樣子"}, {"w": "攝", "m": "夾處"}, {"w": "哂", "m": "微笑"}, {"w": "莫春", "m": "暮春"}, {"w": "風乎舞雩", "m": "在舞雩臺上吹風乘涼"}, {"w": "與", "m": "贊同"}], "questions": [{"n": "一", "qtype": "非選", "stem": "文章解讀（18分）：閱讀框線內甲（林語堂〈論幽默〉）、乙（《論語‧先進》）兩文，回答問題。答案請標明（一）、（二）書寫，合計文長約200—250字（約9—11行）。（一）甲文為何認為老莊和孟子不夠幽默？（二）依據甲文的觀點，為何乙文「吾與點也」可以呈現孔子的幽默？", "options": {}, "answer": "", "ref_answer": "（一）甲文認為幽默是溫厚、從容達觀、輕快自然的。老莊之文「酸辣有餘，溫潤不足」，老子苦笑尖銳、莊子狂笑豪放，容易流於憤世嫉俗，失了溫厚之旨；孟子雖詼諧，卻機警犀利、理智多而情感少，偏於諷刺，所以都不夠幽默。（二）曾點嚮往暮春時與友人、童子浴沂、風舞雩、詠而歸的生活，閒適自在、從容不迫。孔子喟然讚嘆「吾與點也」，顯示他在積極用世之外，也欣賞超脫自適、輕快自然的人生態度，這種溫厚而達觀的情懷，正合甲文所說「幽默自適」的孔子。", "ref_official": false, "explain": "先從甲文找出作者對「幽默」的定義：從容不迫、溫厚、超脫又悲天憫人、輕快自然，而且不等於諷刺。第（一）題就拿這把尺去量：老莊是「酸辣、尖銳、豪放、憤世嫉俗」，缺溫厚；孟子是「機警犀利、理智多情感少」、偏諷刺，缺輕快自然。第（二）題要回到乙文：曾點描述的是春天出遊、洗澡吹風、唱歌回家的悠閒畫面，孔子特別讚嘆他，表示孔子心中也嚮往這種從容自適的境界，這就是甲文說的「幽默自適的孔子」。寫的時候兩小題都要引原文關鍵詞當證據，並把兩文連起來。", "skill": "文章解讀題先從一篇文章抽出「定義或標準」，再拿這個標準去檢驗另一篇的人物或句子。"}], "difficulty": "中", "label": "105指考", "year": 105, "kind": "指考", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "xc106-5", "exam": "xc106", "nums": [5], "form": "單題", "img": "img/xc106-5.png", "source": "《論語》、《孟子》、《中庸》、《墨子》、《禮記‧禮運》", "author": "孔子、孟子、墨子等", "genre": "經典語錄", "types": ["文化常識", "句意理解"], "passage": "(A)士不可以不弘毅，任重而道遠／仁者，人也，親親為大\n(B)愛人利人以得福，惡人賊人以得禍／人不獨親其親，不獨子其子\n(C)非禮勿視，非禮勿聽，非禮勿言，非禮勿動／視人之國若視其國，視人之家若視其家，視人之身若視其身\n(D)己欲立而立人，己欲達而達人／人之於身也，兼所愛；兼所愛，則兼所養也。無尺寸之膚不愛焉，則無尺寸之膚不養也", "translation": "(A)讀書人不能不心胸寬廣、意志堅毅，因為責任重大而路途遙遠／仁就是人的本性，親愛親人最重要。(B)愛人、利人的會得到福報，憎恨人、傷害人的會招來禍害／人們不只親愛自己的父母，不只疼愛自己的子女。(C)不合禮的不看、不聽、不說、不做／看待別人的國家像自己的國家，看待別人的家像自己的家，看待別人的身體像自己的身體。(D)自己想要立足，也幫助別人立足；自己想要通達，也幫助別人通達／人對於自己的身體，每一部分都愛；都愛，就每一部分都保養，沒有一寸皮膚不愛，就沒有一寸皮膚不保養。", "keywords": [{"w": "弘毅", "m": "心胸寬廣、意志堅毅"}, {"w": "賊", "m": "傷害"}, {"w": "兼", "m": "全部、同時"}], "questions": [{"n": 5, "qtype": "單選", "stem": "某校為弘揚儒家、墨家思想，特將新建的兩棟大樓命名為「歸仁堂」、「兼愛樓」，若欲彰顯命名宗旨，則川堂懸掛的字幅依序應是：", "options": {"A": "士不可以不弘毅，任重而道遠／仁者，人也，親親為大", "B": "愛人利人以得福，惡人賊人以得禍／人不獨親其親，不獨子其子", "C": "非禮勿視，非禮勿聽，非禮勿言，非禮勿動／視人之國若視其國，視人之家若視其家，視人之身若視其身", "D": "己欲立而立人，己欲達而達人／人之於身也，兼所愛；兼所愛，則兼所養也。無尺寸之膚不愛焉，則無尺寸之膚不養也"}, "answer": "C", "explain": "答案(C)。「歸仁堂」取自孔子「克己復禮，天下歸仁焉」，接下來顏淵問細目，孔子答「非禮勿視，非禮勿聽，非禮勿言，非禮勿動」，所以前句配儒家；「兼愛樓」要配墨子的兼愛，「視人之國若視其國……」正是《墨子‧兼愛》的話。(A)兩句都是儒家（《論語》、《中庸》）。(B)前句是墨家思想、後句是〈禮運〉大同（儒家），順序顛倒。(D)前句是《論語》，後句出自《孟子‧告子》，講的是愛護己身每一部分，也是儒家，雖有「兼所愛」三字但不是墨家兼愛。", "skill": "學派辨識：看到「禮」「仁」「己欲立而立人」想儒家；看到「視人如己、愛人利人、天必福之」這種講平等互利、報應的，想墨家。別被單一字眼（如「兼」）騙了。"}], "difficulty": "中", "label": "106學測", "year": 106, "kind": "學測", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "大同與小康"}, {"id": "xc106-6", "exam": "xc106", "nums": [6], "form": "單題", "img": "img/xc106-6.png", "source": "佚名〈醉太平〉", "author": "佚名", "genre": "古典詩詞曲", "types": ["主旨寓意", "寫作手法"], "passage": "奪泥燕口，削鐵鍼頭，刮金佛面細搜求。無中覓有。鵪鶉膆裡尋豌豆，鷺鷥腿上劈精肉，蚊子腹內刳脂油。虧老先生下手。", "translation": "從燕子嘴裡搶泥巴，從針頭上削鐵屑，從佛像臉上刮金箔，仔仔細細地搜刮。沒有的東西也要硬找出來。從鵪鶉的嗉囊裡找豌豆，從鷺鷥細腿上割瘦肉，從蚊子肚子裡剖出油脂。真虧這位老先生下得了手！", "keywords": [{"w": "鍼", "m": "針"}, {"w": "膆", "m": "鳥類的嗉囊"}, {"w": "刳", "m": "剖開挖空"}, {"w": "虧", "m": "真虧、難為（反諷語）"}], "questions": [{"n": 6, "qtype": "單選", "stem": "下列元曲運用一連串比喻，所要嘲諷的對象是：", "options": {"A": "汲汲名利，奔走鑽營者", "B": "百般挑剔，吹毛求疵者", "C": "貪圖小利，極力刻剝者", "D": "興風作浪，無中生有者"}, "answer": "C", "explain": "答案(C)。燕子口中的泥、針頭上的鐵、鵪鶉嗉囊的豆、鷺鷥腿上的肉、蚊子肚裡的油——全都是極微小的東西，還要費盡心思去搜刮，嘲諷的就是貪圖蠅頭小利、拼命刻剝的人。(A)沒有寫追求名位、到處鑽營；(B)不是挑別人毛病；(D)「無中覓有」是硬從沒有的地方搜出東西，不是捏造謠言、興風作浪。", "skill": "一連串比喻題：把所有喻體的共同點找出來（這題是『極小的東西＋硬去拿』），共同點就是嘲諷的重點。"}], "difficulty": "易", "label": "106學測", "year": 106, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc106-8", "exam": "xc106", "nums": [8, 9], "form": "題組", "img": "img/xc106-8.png", "source": "菲力浦‧科克《孤獨》（白話）；選項為陳夢林〈望玉山記〉、蘇軾〈赤壁賦〉、郁永河《裨海紀遊》、歐陽脩〈醉翁亭記〉", "author": "菲力浦‧科克等", "genre": "其他", "types": ["文意推論", "主旨寓意"], "passage": "(A)臘月既望，館人奔告：「玉山見矣！」時旁午，風靜無塵，四宇清澈（陳夢林〈望玉山記〉）\n(B)壬戌之秋，七月既望，蘇子與客泛舟遊於赤壁之下。清風徐來，水波不興（蘇軾〈赤壁賦〉）\n(C)明日拉顧君偕往，坐莽葛中，命二番兒操楫。緣溪入，溪盡為內北社，呼社人為導（郁永河《裨海紀遊》）\n(D)人知從太守遊而樂，而不知太守之樂其樂也。醉能同其樂，醒能述以文者，太守也（歐陽脩〈醉翁亭記〉）", "translation": "(A)十二月十六日，館裡的人跑來告訴我：「看得見玉山了！」當時接近中午，風靜無塵，四周清澈。(B)壬戌年秋天，七月十六日，我和客人在赤壁下划船遊玩，清風慢慢吹來，水面不起波浪。(C)第二天拉著顧君一起去，坐著獨木舟，叫兩個原住民少年划槳，沿溪進去，溪的盡頭是內北社，叫社裡的人帶路。(D)人們只知道跟著太守遊玩很快樂，卻不知道太守是因為他們快樂而快樂。醉了能和大家同樂，醒了能寫文章記述的，就是太守。", "keywords": [{"w": "既望", "m": "農曆十六日"}, {"w": "旁午", "m": "接近中午"}, {"w": "莽葛", "m": "獨木舟"}, {"w": "樂其樂", "m": "以他們的快樂為快樂"}], "questions": [{"n": 8, "qtype": "單選", "stem": "下列敘述，符合上文文意的選項是：", "options": {"A": "文學家每為孤獨所困，但描繪的內容都是個人化的經驗，難以引起讀者共鳴", "B": "孤獨和交會的關係就好比陰、陽，二者互滲於對方之中，不可能真正的獨存", "C": "要完整體驗世界必須同時過著孤獨和群體生活，讓自己處於灰色的中間地帶", "D": "太極圖中的白點象徵在孤獨中能安慰我們的朋友，黑點象徵人心深處的黑暗面"}, "answer": "B", "explain": "答案(B)。文中說陰陽兩半「各自包含著對方顏色的若干細線」，代表「沒有純粹的孤獨，也沒有純粹的交會」，兩者互相滲透——就是(B)。(A)作者說文學家的意象「太個人化」，是想找更普遍的意象，沒說文學家為孤獨所困、難以引起共鳴。(C)灰色地帶只是說明兩者互為底景，沒有要人「處於灰色地帶」。(D)白點、黑點分別代表「交會極致中的孤獨」和「孤獨極致中的交會」，不是朋友或黑暗面。", "skill": "說明性文章：選項中每一個比喻的「代表意義」都要回原文核對，作者怎麼定義就怎麼解釋，不可自行引申。"}, {"n": 9, "qtype": "單選", "stem": "下列文字，最能表現上文畫底線處情況的選項是：", "options": {"A": "臘月既望，館人奔告：「玉山見矣！」時旁午，風靜無塵，四宇清澈", "B": "壬戌之秋，七月既望，蘇子與客泛舟遊於赤壁之下。清風徐來，水波不興", "C": "明日拉顧君偕往，坐莽葛中，命二番兒操楫。緣溪入，溪盡為內北社，呼社人為導", "D": "人知從太守遊而樂，而不知太守之樂其樂也。醉能同其樂，醒能述以文者，太守也"}, "answer": "D", "explain": "答案(D)。畫線處是「在人我交會的極致中，人可能突然體驗到最深沉的孤獨」。(D)〈醉翁亭記〉中太守和眾人一起遊宴，熱鬧到極點，但「人知從太守遊而樂，而不知太守之樂其樂」——大家都不懂太守真正快樂的原因，熱鬧中透出不被理解的孤獨，最符合。(A)只是寫天氣晴朗、看見玉山；(B)寫與客泛舟、清風徐來的景色；(C)寫找人帶路入山，都沒有「熱鬧中的孤獨」。", "skill": "文白對讀：先把畫線句改寫成一個情境（熱鬧之中卻有孤單），再翻譯每個文言選項，看哪一句同時具備兩個條件。"}], "difficulty": "中", "label": "106學測", "year": 106, "kind": "學測", "textcat": "部定古文", "textcat2": "文學文本", "linked_core": "醉翁亭記、赤壁賦、裨海紀遊"}, {"id": "xc106-10", "exam": "xc106", "nums": [10, 11], "form": "題組", "img": "img/xc106-10.png", "source": "蘇雪林〈家〉（引程垓〈滿江紅〉）", "author": "蘇雪林、程垓", "genre": "古典詩詞曲", "types": ["比較閱讀", "句意理解", "主旨寓意"], "passage": "湖山好處便為家。\n葺屋為舟，身便是煙波釣客；況人間原是浮家泛宅。秋晚雨聲篷背穩，夜深月影窗櫺白，滿船詩酒滿船書，隨意索。也不怕雲濤隔，也不怕風帆側，但獨醒還睡，自歌還歇。臥後從教鰍鱔舞，醉來一任乾坤窄。恐有時撐向大江頭，占風色。（程垓〈滿江紅〉）", "translation": "湖光山色美好的地方，就是我的家。\n把屋子修整成船的樣子，我就是在煙波上垂釣的人；何況人生本來就像漂浮不定的船家。秋夜雨打在篷背上安穩，深夜月光照得窗格發白，滿船的詩、酒和書，隨我取用。不怕雲濤阻隔，不怕風浪把帆吹斜，只管醒了又睡、自己唱歌又停。躺下後任憑泥鰍黃鱔跳舞，醉了任天地多狹窄。說不定哪天會撐到大江口，看看風向。", "keywords": [{"w": "葺", "m": "修補、修整"}, {"w": "浮家泛宅", "m": "以船為家，漂泊不定"}, {"w": "索", "m": "取"}, {"w": "從教", "m": "任憑"}, {"w": "擘破", "m": "劈開，指船行破開湖面"}], "questions": [{"n": 10, "qtype": "單選", "stem": "下列文句的說明，正確的選項是：", "options": {"A": "「行腳僧煙簑雨笠，到處棲遲」描述行腳僧失意飄泊而浪跡天涯", "B": "「滿船詩酒滿船書，隨意索」說明作者好客，詩、酒及書任人索取", "C": "「獨醒還睡，自歌還歇」描寫眾人皆醉我獨醒與漁歌唱和的情景", "D": "「擘破三萬六千頃青琉璃」意謂行船於澄碧的太湖之中"}, "answer": "D", "explain": "答案(D)。太湖號稱「三萬六千頃」，「青琉璃」形容湖水澄碧如琉璃，「擘破」是船行劃開水面，所以是行船在碧綠的太湖中。(A)作者說行腳僧的生活「富有詩意」，是欣賞，不是失意飄泊。(B)「隨意索」是自己隨意取用，不是任人索取。(C)「獨醒還睡，自歌還歇」是想醒就醒、想睡就睡，自唱自停，寫自在，不是「眾人皆醉我獨醒」的孤高，也沒有漁歌唱和。", "skill": "詩詞句意題：先看上下文的情緒（這裡是悠閒自在），選項若出現『失意』『孤高』等與整體情調相反的解讀就要小心。"}, {"n": 11, "qtype": "單選", "stem": "作者引述髯公詩與程垓詞的用意是：", "options": {"A": "表達依江山勝景而居的嚮往", "B": "流露出無處不可為家的豁達", "C": "慨嘆屋狹而不能滿室詩酒書", "D": "惋惜不能以船為家任意遨遊"}, "answer": "A", "explain": "答案(A)。作者一開頭就說看到好風景就想「在這裡造屋子住」，又引「湖山好處便為家」，還想造船「三江五湖，隨意遨遊」——引詩詞是為了表達想依山水勝景而居的嚮往。(B)作者並不是說哪裡都能當家，而是挑「湖山好處」。(C)作者擔心的是船小放不下書，不是屋狹。(D)文末說船太小太大都不行，是自我解嘲，引詩詞的用意不在惋惜。", "skill": "問「引用用意」：回到作者引用前後自己說的話，引文通常是用來支持作者在那一段的主要想法。"}], "difficulty": "中", "label": "106學測", "year": 106, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc106-14", "exam": "xc106", "nums": [14, 15], "form": "題組", "img": "img/xc106-14.png", "source": "《孔叢子‧抗志》", "author": "孔鮒（舊題）", "genre": "經典語錄", "types": ["文意推論", "主旨寓意"], "passage": "子思見老萊子，老萊子聞穆公將相子思，老萊子曰：「若子事君，將何以為乎？」子思曰：「順吾性情，以道輔之，無死亡焉。」老萊子曰：「不可順子之性也，子性剛而傲不肖，又且無所死亡，非人臣也。」子思曰：「不肖，故人之所傲也。夫事君，道行言聽，則何所死亡？道不行，言不聽，則亦不能事君，所謂無死亡也。」老萊子曰：「子不見夫齒乎？雖堅剛，卒盡相摩；舌柔順，終以不弊。」子思曰：「吾不能為舌，故不能事君。」", "translation": "子思去見老萊子。老萊子聽說魯穆公要任用子思當宰相，就問：「如果你去事奉國君，打算怎麼做？」子思說：「順著我的性情，用正道輔佐他，不會有殺身之禍。」老萊子說：「不能順著你的性子。你個性剛強，又看不起無能的人，又不肯為國君而死，這不是做臣子的樣子。」子思說：「無能的人，本來就是別人看不起的。事奉國君，如果我的主張能實行、我的話能被聽從，哪裡會有殺身之禍？如果主張不能實行、話不被聽從，那我也就不能事奉國君了，這就是我說的不會有殺身之禍。」老萊子說：「你沒看到牙齒嗎？雖然堅硬，最後都互相磨損掉光；舌頭柔軟，卻始終不會壞。」子思說：「我做不到像舌頭那樣，所以不能事奉國君。」", "keywords": [{"w": "相", "m": "任用為宰相（動詞）"}, {"w": "傲不肖", "m": "輕視無能的人"}, {"w": "死亡", "m": "殺身之禍"}, {"w": "弊", "m": "壞、損壞"}], "questions": [{"n": 14, "qtype": "單選", "stem": "關於子思「不能事君」的原因，下列敘述錯誤的選項是：", "options": {"A": "不能順己性情", "B": "不願愚忠枉死", "C": "無法為民喉舌", "D": "難以道行言聽"}, "answer": "C", "explain": "答案(C)。題目問「錯誤」的。子思不能事君的原因：他要「順吾性情」，不肯改變自己剛直的個性（A對）；他不願為國君枉送性命，說「無死亡焉」（B對）；他認為若「道不行，言不聽」就不能事君（D對）。文中完全沒提到「為民喉舌」，(C)是把「舌」字望文生義，所以錯誤。", "skill": "「錯誤的是」題，每個選項都要在原文找到根據；找不到根據的、或只是借用原文某個字（如「舌」）硬套的，就是答案。"}, {"n": 15, "qtype": "單選", "stem": "依據上文，最符合老萊子之意的選項是：", "options": {"A": "君使臣以禮，臣事君以忠", "B": "堅強者死之徒，柔弱者生之徒", "C": "名不正則言不順，言不順則事不成", "D": "行一不義，殺一不辜，而得天下，皆不為也"}, "answer": "B", "explain": "答案(B)。老萊子用「牙齒剛硬卻先磨光，舌頭柔軟反而長存」比喻柔弱才能保全，正是老子「堅強者死之徒，柔弱者生之徒」。(A)是孔子講君臣相處之道；(C)是孔子講正名；(D)是孟子講不做不義的事。三者都沒有「以柔克剛」的意思。", "skill": "看到齒與舌、水與石這類「柔勝剛」的比喻，聯想道家老子思想。"}], "difficulty": "中", "label": "106學測", "year": 106, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc106-16", "exam": "xc106", "nums": [16], "form": "單題", "img": "img/xc106-16.png", "source": "〈岳陽樓記〉、〈始得西山宴遊記〉、《論語》、〈馮諼客孟嘗君〉、〈左忠毅公軼事〉、〈出師表〉、〈典論論文〉、〈臺灣通史序〉、黃庭堅〈寄黃幾復〉、〈勞山道士〉", "author": "多家", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)北通巫峽，南極瀟湘／意有所極，夢亦同趣\n(B)比及三年，可使足民／孟嘗君曰：為之駕，比門下之車客\n(C)史公治兵，往來桐城，必躬造左公第／臣本布衣，躬耕於南陽\n(D)文非一體，鮮能備善／朱、林以下，輒啟兵戎，喋血山河，藉言恢復，而舊志亦不備載也\n(E)我居北海君南海，寄雁傳書謝不能／王果去牆數步，奔而入，及牆，虛若無物，回視，果在牆外矣。大喜，入謝", "translation": "(A)北邊通到巫峽，南邊到達瀟水、湘水／心裡想到哪裡，夢也就到哪裡。(B)等到三年，可以使人民富足／孟嘗君說：替他準備車子，比照門下有車坐的門客。(C)史公帶兵往來桐城，一定親自到左公家拜訪／我本來是平民，親自在南陽耕田。(D)文章不只一種體裁，很少人能各體都擅長／朱一貴、林爽文以後，動不動就發動戰爭，血流山河，假借恢復明朝之名，舊方志也不完整記載。(E)我住北海你住南海，想託雁傳信，雁卻推辭做不到／王生果然離牆幾步，跑著衝進去，到了牆邊，好像沒東西一樣，回頭一看，果然在牆外了。非常高興，進去道謝。", "keywords": [{"w": "極", "m": "到達"}, {"w": "比", "m": "等到；比照"}, {"w": "躬", "m": "親自"}, {"w": "備", "m": "完備、全部"}, {"w": "謝", "m": "推辭；道謝"}], "questions": [{"n": 16, "qtype": "多選", "stem": "下列各組文句「」內的字，前後意義相同的選項是：", "options": {"A": "北通巫峽，南「極」瀟湘／意有所「極」，夢亦同趣", "B": "「比」及三年，可使足民／孟嘗君曰：為之駕，「比」門下之車客", "C": "史公治兵，往來桐城，必「躬」造左公第／臣本布衣，「躬」耕於南陽", "D": "文非一體，鮮能「備」善／朱、林以下，輒啟兵戎，喋血山河，藉言恢復，而舊志亦不「備」載也", "E": "我居北海君南海，寄雁傳書「謝」不能／王果去牆數步，奔而入，及牆，虛若無物，回視，果在牆外矣。大喜，入「謝」"}, "answer": "ACD", "explain": "答案(A)(C)(D)。(A)兩個「極」都是「到達」：南邊到達瀟湘／心意到達之處。(C)兩個「躬」都是「親自」。(D)兩個「備」都是「完備、全部」：很少人能各體都完備擅長／舊志不完整記載。(B)前「比及」是「等到」，後「比門下之車客」是「比照」。(E)前「謝不能」是「推辭」，後「入謝」是「道謝」。", "skill": "一字多義：「謝」常見四義——道謝、推辭、道歉、凋落；「比」常見——等到、比照、靠近、接連，背熟常見義再代入句子。"}], "difficulty": "中", "label": "106學測", "year": 106, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "馮諼客孟嘗君、典論論文、出師表、始得西山宴遊記、岳陽樓記、勞山道士、左忠毅公軼事、臺灣通史序"}, {"id": "xc106-17", "exam": "xc106", "nums": [17], "form": "單題", "img": "img/xc106-17.png", "source": "《尚書》、韓愈〈師說〉、《左傳‧燭之武退秦師》、《孟子‧梁惠王上》、顧炎武〈廉恥〉", "author": "多家", "genre": "其他", "types": ["虛詞句式", "句意理解"], "passage": "(A)怨不在大，可畏惟人\n(B)聞道有先後，術業有專攻\n(C)若亡鄭而有益於君，敢以煩執事\n(D)斧斤以時入山林，材木不可勝用也\n(E)人之不廉而至於悖禮犯義，其原皆生於無恥也", "translation": "(A)怨恨不在於大小，可怕的是人心。(B)懂得道理有先有後，學問技能各有專精。(C)如果滅掉鄭國對您有好處，那就敢麻煩您的手下（動手吧）。(D)按照季節才拿斧頭進山林砍樹，木材就用不完。(E)人不廉潔以致違背禮義，根源都出在不知羞恥。", "keywords": [{"w": "執事", "m": "辦事人員，敬稱對方"}, {"w": "以時", "m": "按照時節"}, {"w": "不可勝用", "m": "用不完"}, {"w": "悖", "m": "違背"}], "questions": [{"n": 17, "qtype": "多選", "stem": "「一分耕耘，一分收穫」之語意關係可以是「如有一分耕耘，則得一分收穫」，下列文字前後句具有相同語意關係的選項是：", "options": {"A": "怨不在大，可畏惟人", "B": "聞道有先後，術業有專攻", "C": "若亡鄭而有益於君，敢以煩執事", "D": "斧斤以時入山林，材木不可勝用也", "E": "人之不廉而至於悖禮犯義，其原皆生於無恥也"}, "answer": "CD", "explain": "答案(C)(D)。題目要找「如果……就……」的假設條件關係。(C)「若亡鄭而有益於君，（則）敢以煩執事」——如果滅鄭有益，就麻煩您動手，明顯是假設。(D)「（如果）斧斤以時入山林，（則）材木不可勝用」——條件成立就有結果。(A)是講人心可怕，前後是並列說明，不是條件；(B)前後兩件事並列；(E)是「原因在於……」的因果解釋，後句說明前句的根源，不是假設條件。", "skill": "判斷假設關係：試著在前句加「如果」、後句加「就」，讀起來通順且意思不變，就是假設條件句。"}], "difficulty": "中", "label": "106學測", "year": 106, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "燭之武退秦師、師說、廉恥"}, {"id": "xc106-19", "exam": "xc106", "nums": [19], "form": "單題", "img": "img/xc106-19.png", "source": "白居易〈畫竹歌〉、杜甫〈奉先劉少府新畫山水障歌〉等題畫詩", "author": "白居易、杜甫等", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "(A)嬋娟不失筠粉態，蕭颯盡得風煙情。舉頭忽看不似畫，低耳靜聽疑有聲\n(B)興來寫菊似塗鴉，誤作枯藤纏數花。筆落一時收不住，石棱留得一拳斜\n(C)北苑時翻硯池墨，疊起烟雲隱霹靂。短縑尺楮信手揮，若有蛟龍在昏黑\n(D)名工繹思揮彩筆，驅山走海置眼前。滿堂空翠如可掃，赤城霞氣蒼梧烟\n(E)峰頭黛色晴猶濕，筆底春雲暗不開。墨花淋漓翠微斷，隱几忽聞山雨來", "translation": "(A)竹子秀美，保有竹皮白粉的姿態；蕭瑟搖曳，畫出了風煙中的情味。抬頭一看不像是畫，低頭靜聽好像有聲音。(B)興致來了畫菊花像塗鴉，不小心畫成枯藤纏著幾朵花；筆一落下收不住，石頭的稜角留下一團斜斜的墨。(C)董源時常翻動硯池的墨，堆疊出雲煙，雲中隱藏雷電；小小的絹紙隨手揮灑，好像有蛟龍在昏暗中。(D)名畫家構思揮動彩筆，把山海搬到眼前；滿屋子青翠的山色好像可以掃起來，赤城山的霞光、蒼梧山的雲煙都在畫中。(E)山頭的青黑色在晴天看起來還是濕的，筆下的春雲濃暗化不開；墨色淋漓，青翠山腰被雲斷開，靠著几案忽然好像聽到山雨要來。", "keywords": [{"w": "嬋娟", "m": "姿態美好"}, {"w": "筠", "m": "竹子"}, {"w": "縑、楮", "m": "絹與紙"}, {"w": "空翠", "m": "青翠的山色"}, {"w": "隱几", "m": "靠著几案"}], "questions": [{"n": 19, "qtype": "多選", "stem": "傳統文人常針對畫作題詠。下列詩句，意在強調畫作逼真的選項是：", "options": {"A": "嬋娟不失筠粉態，蕭颯盡得風煙情。舉頭忽看不似畫，低耳靜聽疑有聲", "B": "興來寫菊似塗鴉，誤作枯藤纏數花。筆落一時收不住，石棱留得一拳斜", "C": "北苑時翻硯池墨，疊起烟雲隱霹靂。短縑尺楮信手揮，若有蛟龍在昏黑", "D": "名工繹思揮彩筆，驅山走海置眼前。滿堂空翠如可掃，赤城霞氣蒼梧烟", "E": "峰頭黛色晴猶濕，筆底春雲暗不開。墨花淋漓翠微斷，隱几忽聞山雨來"}, "answer": "ACDE", "explain": "答案(A)(C)(D)(E)。題目要找「強調畫作逼真」——把畫看成真的。(A)「舉頭忽看不似畫，低耳靜聽疑有聲」，竹子畫得像真的，彷彿聽得到風吹竹聲。(C)「若有蛟龍在昏黑」，畫中雲煙逼真到像有蛟龍在其中。(D)「滿堂空翠如可掃」，山色青翠彷彿伸手可掃。(E)「隱几忽聞山雨來」，看畫竟像聽見山雨將至。(B)是畫家自述畫菊失手像塗鴉、隨興揮灑，寫的是作畫過程與自嘲，沒有強調逼真。", "skill": "題畫詩找「逼真」：留意『疑』『若』『如』『忽聞』等字，表示觀者把畫當真，產生視覺、聽覺上的錯覺。"}], "difficulty": "中", "label": "106學測", "year": 106, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc106-20", "exam": "xc106", "nums": [20], "form": "單題", "img": "img/xc106-20.png", "source": "葉燮《原詩》、顧炎武《日知錄》", "author": "葉燮、顧炎武", "genre": "說理議論", "types": ["比較閱讀", "主旨寓意"], "passage": "甲、詩是心聲，不可違心而出，亦不能違心而出。功名之士，決不能為泉石淡泊之音；輕浮之子，必不能為敦龐大雅之響。故陶潛多素心之語，李白有遺世之句，杜甫興「廣廈萬間」之願，蘇軾師「四海弟昆」之言。凡如此類，皆應聲而出。（葉燮《原詩》）\n乙、詩文之所以代變，有不得不變者。一代之文沿襲已久，不容人人皆道此語。今且千數百年矣，而猶取古人之陳言一一而摹仿之，以是為詩，可乎？故不似則失其所以為詩，似則失其所以為我。李、杜之詩所以獨高於唐人者，以其未嘗不似，而未嘗似也。知此者，可與言詩也已矣。（顧炎武《日知錄》）", "translation": "甲、詩是內心的聲音，不可以違背本心寫出來，也沒辦法違背本心寫出來。追求功名的人，絕對寫不出山水間恬淡的作品；輕浮的人，一定寫不出敦厚宏大的雅正之聲。所以陶淵明多質樸本心的話，李白有超脫塵世的句子，杜甫發出「廣廈千萬間」的心願，蘇軾效法「四海之內皆兄弟」的話。這些都是隨著心聲自然寫出來的。\n乙、詩文每個時代都會改變，是有不得不變的原因。一個時代的文風沿用久了，就不能人人都說同樣的話。現在已經過了一千多年，還拿古人的陳舊言語一一模仿，這樣寫詩可以嗎？所以不像古人，就失去詩的本質；太像古人，就失去自我。李白、杜甫的詩之所以比其他唐人高明，是因為他們沒有不像古人的地方，卻也從來沒有只是像古人。懂得這個道理，才可以和他談詩。", "keywords": [{"w": "違心", "m": "違背本心"}, {"w": "敦龐", "m": "敦厚宏大"}, {"w": "代變", "m": "隨時代改變"}, {"w": "陳言", "m": "陳舊的言語"}], "questions": [{"n": 20, "qtype": "多選", "stem": "閱讀下列二文，選出敘述正確的選項：", "options": {"A": "甲文主張詩歌是作者主體情感的自然流露，不可虛矯造作", "B": "乙文主張創作既要接續傳統，又要開創出自我獨特的面貌", "C": "甲文著重文學與時代的關聯，乙文留意作品與情志的聯結", "D": "二文論及李白與杜甫詩作，皆著眼於二人雄渾高遠的詩境", "E": "二文皆主張詩文本於心性，故當先涵養心性後再專研詩藝"}, "answer": "AB", "explain": "答案(A)(B)。(A)正確：甲文說「詩是心聲，不可違心而出」，詩是真情自然流露，不能虛假做作。(B)正確：乙文說「不似則失其所以為詩，似則失其所以為我」，李杜「未嘗不似，而未嘗似」——既承接傳統又有自我面貌。(C)說反了：甲文重的是作品與作者情志的關係，乙文才談到時代變化。(D)甲文舉李白的「遺世」、杜甫的「廣廈之願」是說詩反映人格；乙文講李杜能繼承又創新，兩文都沒談「雄渾高遠」。(E)乙文沒有談心性涵養。", "skill": "兩文比較：先各用一句話寫出主旨（甲：詩是心聲；乙：要繼承又要創新），再檢查選項有沒有把甲乙的重點對調。"}], "difficulty": "中", "label": "106學測", "year": 106, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc106-ns2", "exam": "xc106", "nums": ["二"], "form": "單題", "img": "img/xc106-ns2.png", "source": "杜光庭〈虬髯客傳〉", "author": "杜光庭", "genre": "史傳人物", "types": ["人物情感", "寫作手法"], "passage": "靖歸逆旅。其夜五更初，忽聞扣門而聲低者，靖起問焉。乃紫衣戴帽人，杖揭一囊。靖問：「誰？」曰：「妾，楊家之紅拂妓也。」靖遽延入。脫衣去帽，乃十八九佳麗人也。素面華衣而拜。靖驚答拜。曰：「妾侍楊司空久，閱天下之人多矣，未有如公者。絲蘿非獨生，願託喬木，故來奔耳。」靖曰：「楊司空權重京師，如何？」曰：「彼屍居餘氣，不足畏也。諸妓知其無成，去者眾矣。彼亦不甚逐也。計之詳矣，幸無疑焉。」問其姓，曰：「張。」問伯仲之次，曰：「最長。」觀其肌膚、儀狀、言詞、氣性，真天人也。靖不自意獲之，愈喜愈懼，瞬息萬慮不安，而窺戶者足無停屨。", "translation": "李靖回到旅店。那天夜裡五更剛過，忽然聽到有人小聲敲門，李靖起來問是誰。原來是一個穿紫衣、戴帽子的人，用手杖挑著一個布袋。李靖問：「是誰？」回答：「我是楊家拿紅拂的歌妓。」李靖連忙請她進來。她脫下外衣、帽子，原來是十八九歲的美女，素淨的臉、華麗的衣服，向李靖行禮。李靖吃驚地回禮。她說：「我服侍楊司空很久，看過天下的人很多，沒有像您這樣的。絲蘿不能單獨生長，希望依託在高大的樹木上，所以來投奔您。」李靖說：「楊司空在京城權勢很大，怎麼辦？」她說：「他不過是只剩一口氣的活死人，不值得害怕。歌妓們知道他成不了事，離開的很多了，他也不太追究。我已經仔細盤算過了，希望您不要疑慮。」問她姓什麼，說：「姓張。」問她排行，說：「老大。」看她的肌膚、儀態、言談、氣質，真是天仙一般。李靖沒想到能得到她，越高興越害怕，一瞬間各種念頭都不安，頻頻到門口偷看有沒有人追來，腳步不停。", "keywords": [{"w": "逆旅", "m": "旅店"}, {"w": "杖揭一囊", "m": "用手杖挑著一個袋子"}, {"w": "遽", "m": "立刻、急忙"}, {"w": "絲蘿", "m": "菟絲、女蘿，攀附他物生長，比喻女子"}, {"w": "喬木", "m": "高大的樹，比喻可依託的男子"}, {"w": "屍居餘氣", "m": "像屍體只剩一口氣，比喻人將死、無作為"}, {"w": "足無停屨", "m": "腳步不停"}], "questions": [{"n": "二", "qtype": "非選", "stem": "閱讀〈虬髯客傳〉「紅拂女夜奔李靖」一段文字，答案請標明（一）、（二）書寫，文長約250-300字。（一）分析李靖在整段事件過程中的情緒變化。（二）闡述紅拂女如何運用說話技巧，使李靖接受她的投靠。", "options": {}, "answer": "", "ref_answer": "（一）李靖的情緒變化：深夜有人低聲敲門，「起問焉」——疑惑；見來人竟是佳麗而下拜，「驚答拜」——驚訝；想到楊素權重京師，問「如何？」——擔憂；聽完說明、看她「真天人也」，「不自意獲之」——驚喜；但「愈喜愈懼，瞬息萬慮不安，而窺戶者足無停屨」——惶懼不安。\n（二）紅拂女的說話技巧：1.先讚美對方：「閱天下之人多矣，未有如公者」，以見多識廣的身分肯定李靖，使他動心。2.以比喻委婉表達心意：「絲蘿非獨生，願託喬木」，把自己比作需要依附的絲蘿、李靖比作喬木，既謙遜又尊崇對方。3.分析情勢化解顧慮：說楊素「屍居餘氣，不足畏」，並舉「諸妓知其無成，去者眾矣，彼亦不甚逐」為證，消除李靖對楊素的疑懼。4.表明深思熟慮：「計之詳矣，幸無疑焉」，展現果決，讓李靖安心。5.問答簡潔坦率（「張」「最長」），顯出大方自信。", "ref_official": false, "explain": "第（一）小題要「按事件順序」找出每個情緒的文字證據：起問（疑）→驚答拜（驚）→如何？（憂）→不自意獲之（喜）→愈喜愈懼、窺戶（懼）。每個情緒都要引一小段原文再解釋，不要只抄原文。第（二）小題要先歸納出「技巧名稱」（讚美、比喻、分析利害、表明決心），再配上原文說明效果——為什麼這句話能讓李靖接受。", "skill": "寫人物情緒變化：先在原文圈出所有動作與心理詞，排成時間軸，每一格寫『情緒＋原文證據＋原因』，就不會漏。"}], "difficulty": "中", "label": "106學測", "year": 106, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "虬髯客傳"}, {"id": "zk106-3", "exam": "zk106", "nums": [3], "form": "單題", "img": "img/zk106-3.png", "source": "司馬光〈諫院題名記〉", "author": "司馬光", "genre": "書信序跋", "types": ["句意理解", "文意推論"], "passage": "古者諫無官，自公卿大夫，至於工商，無不得諫者。漢興以來，始置官。夫以天下之政，四海之眾，得失利病，萃於一官使言之，其為任亦重矣。居是官者，當志其大，舍其細，先其急，後其緩，專利國家，而不為身謀。", "translation": "古時候進諫沒有專設的官職，從公卿大夫到工匠商人，沒有誰不能進諫。漢朝建立以來，才設置專門的諫官。把天下的政事、全國百姓的得失利弊，集中交給一個官職去說，這個責任也實在重大了。擔任這個官職的人，應該記住大事、放下小事，先說急事、後說緩事，一心為國家謀利，而不為自己打算。", "keywords": [{"w": "萃", "m": "聚集"}, {"w": "志", "m": "記住、留意"}, {"w": "專利國家", "m": "一心為國家謀利"}], "questions": [{"n": 3, "qtype": "單選", "stem": "下列是一段古文，請依文意選出排列順序最恰當的選項：古者諫無官，甲、漢興以來，始置官　乙、使言之，其為任亦重矣　丙、自公卿大夫，至於工商，無不得諫者　丁、居是官者，當志其大，舍其細，先其急，後其緩　戊、夫以天下之政，四海之眾，得失利病，萃於一官　專利國家，而不為身謀。", "options": {"A": "甲乙丁戊丙", "B": "甲丁戊乙丙", "C": "丙甲戊乙丁", "D": "丙戊乙甲丁"}, "answer": "C", "explain": "文章由古到今、由制度到人：開頭「古者諫無官」，接著要說明「沒有諫官」是什麼情形——人人都能進諫（丙）。然後轉到後來「漢興以來，始置官」（甲）。有了諫官，就說天下大事都「萃於一官」（戊），而且「使言之」，所以「其為任亦重矣」（乙）——戊和乙是一句話拆開的，「萃於一官使言之」要連在一起。最後才講擔任此官的人該怎麼做（丁），並接上結尾「專利國家，而不為身謀」。順序是丙甲戊乙丁，選(C)。", "skill": "排序題先找「被拆開的一句話」（如「萃於一官」＋「使言之」），把它們綁在一起，順序就少了一大半。"}], "difficulty": "中", "label": "106指考", "year": 106, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk106-5", "exam": "zk106", "nums": [5], "form": "單題", "img": "img/zk106-5.png", "source": "錢基博《現代中國文學史》", "author": "錢基博", "genre": "史傳人物", "types": ["句意理解", "人物情感"], "passage": "王闓運，字壬秋，又字壬父。生時，父夢神榜其門曰：「天開文運」，因以闓運為名。顧天性愚魯，幼讀書，日誦不及百言，又不能盡解，同塾者皆嗤之。師曰：「學而嗤於人，是可羞也。嗤於人而不奮，無寧已。」闓運聞而泣，退益刻勵，昕所習者，不成誦不食；夕所誦者，不得解不寢。年十五，始明訓故。", "translation": "王闓運，字壬秋，又字壬父。他出生時，父親夢見神明在家門上掛了一塊匾，寫著「天開文運」，所以取名闓運。可是他天生資質遲鈍，小時候讀書，一天背不到一百個字，又不能完全理解，同學都嘲笑他。老師說：「求學卻被人嘲笑，這是可恥的。被人嘲笑卻不發憤，還不如乾脆不要讀了。」闓運聽了哭了，回去後更加刻苦努力：早上學的，沒背熟就不吃飯；晚上讀的，沒弄懂就不睡覺。到十五歲，才通曉文字訓詁。", "keywords": [{"w": "榜", "m": "題字、掛匾"}, {"w": "顧", "m": "但是、可是"}, {"w": "嗤", "m": "譏笑"}, {"w": "無寧已", "m": "不如停止"}, {"w": "昕", "m": "清晨"}, {"w": "訓故", "m": "同「訓詁」，解釋古書字義"}], "questions": [{"n": 5, "qtype": "單選", "stem": "依據下文，關於王闓運的敘述，正確的選項是：", "options": {"A": "出身書香世家，嘗夢來日必登金榜", "B": "塾師見其困學，斥以自餒不如放棄", "C": "讀書不求甚解，疏於考究典籍訓故", "D": "重理解捨記誦，能自樂至廢寢忘食"}, "answer": "B", "explain": "(B)老師看他讀得辛苦又被人笑，就說「嗤於人而不奮，無寧已」——被嘲笑卻不發憤，不如別讀了，這是用重話激勵他，正確。(A)作夢的是他父親，夢的是神明題「天開文運」，不是他自己夢見考上金榜；文中也沒說是書香世家。(C)他一開始「不能盡解」，但後來「不得解不寢」，十五歲「始明訓故」，非常講究理解。(D)他是「不成誦不食」、「不得解不寢」，記誦和理解兩者都要，不是捨棄記誦；也不是自得其樂，而是發憤苦讀。", "skill": "人物傳記要注意「前後轉折」（顧、退益刻勵），選項常拿轉折前的狀態冒充人物最後的樣子。"}], "difficulty": "易", "label": "106指考", "year": 106, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk106-6", "exam": "zk106", "nums": [6], "form": "單題", "img": "img/zk106-6.png", "source": "對聯（出處待查）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "甲、剛正不阿，留得正氣衝霄漢；幽愁發憤，著成信史照塵寰\n乙、占事考祥，明有徵驗，開國文臣第一；運籌畫計，動中機宜，渡江策士無雙\n丙、衝破樊籬，教性靈直出，行雲流水壯文瀾，人皆仰止；追思聖傑，讓氣脈相通，麗句清詞吟柳浪，公可安然", "translation": "甲：剛強正直不逢迎，留下的正氣直衝雲霄；在憂愁中發憤，寫成可信的史書照耀人間。\n乙：占卜國事、考察吉凶，靈驗分明，是開國第一文臣；運籌帷幄、出謀劃策，都切合時機，是渡江以來無人能比的謀士。\n丙：衝破束縛，讓真性靈直接流露，像行雲流水般壯大文章波瀾，人人景仰；追念古聖先賢，讓文脈相通，用清麗的詞句吟詠柳浪美景，先生可以安息了。", "keywords": [{"w": "信史", "m": "可信的史書"}, {"w": "占事考祥", "m": "占卜事情、考察吉凶"}, {"w": "性靈", "m": "真性情，公安派「獨抒性靈」"}, {"w": "柳浪", "m": "西湖「柳浪聞鶯」，袁宏道曾作〈西湖〉遊記"}], "questions": [{"n": 6, "qtype": "單選", "stem": "右列甲、乙、丙三聯依序對應的人物，正確的選項是：", "options": {"A": "孟軻／劉基／蘇軾", "B": "孟軻／諸葛亮／袁宏道", "C": "司馬遷／劉基／袁宏道", "D": "司馬遷／諸葛亮／蘇軾"}, "answer": "C", "explain": "甲：「幽愁發憤，著成信史」說的是受宮刑後發憤寫《史記》的司馬遷，「剛正不阿」指他替李陵說話；孟子沒有寫史書。乙：「開國文臣第一」「渡江策士」，是輔佐朱元璋渡江打天下、明朝開國的劉基（劉伯溫），他還精通占卜（占事考祥）；諸葛亮不是開國第一文臣，也沒有「渡江」。丙：「衝破樊籬，教性靈直出」正是公安派袁宏道「獨抒性靈，不拘格套」的主張；「吟柳浪」指他寫西湖的遊記。所以選(C)。", "skill": "人物對聯題找最「專屬」的關鍵詞：著史→司馬遷、開國文臣→劉基、性靈→袁宏道，一個詞就能定人。"}], "difficulty": "中", "label": "106指考", "year": 106, "kind": "指考", "textcat": "生活情境文本", "textcat2": "", "linked_core": ""}, {"id": "zk106-7", "exam": "zk106", "nums": [7], "form": "單題", "img": "img/zk106-7.png", "source": "《呂氏春秋‧功名》", "author": "呂不韋門客", "genre": "說理議論", "types": ["主旨寓意", "寫作手法"], "passage": "彊令之笑不樂；彊令之哭不悲；彊令之為道也，可以成小，而不可以成大。缶醯黃，蚋聚之，有酸，徒水則必不可。以貍致鼠，以冰致蠅，雖工，不能。以茹魚去蠅，蠅愈至，不可禁，以致之之道去之也。桀、紂以去之之道致之也，罰雖重，刑雖嚴，何益？", "translation": "強迫人笑，他不會真的快樂；強迫人哭，他不會真的悲傷；用強迫的方法做事，只能成就小事，不能成就大事。缸裡的醋變黃了，蚊蚋就聚過來，因為有酸味；如果只是清水，就一定招不來。用貓去招老鼠，用冰去招蒼蠅，方法再巧也做不到。用腐臭的魚去趕蒼蠅，蒼蠅反而來得更多，擋都擋不住，因為是用招來蒼蠅的方法去趕走牠。夏桀、商紂用趕走人民的方法想招來人民，刑罰再重再嚴，又有什麼用呢？", "keywords": [{"w": "彊", "m": "同「強」，勉強"}, {"w": "醯", "m": "醋"}, {"w": "蚋", "m": "小飛蟲"}, {"w": "徒水", "m": "只是清水"}, {"w": "致", "m": "招來"}, {"w": "茹魚", "m": "腐臭的魚"}], "questions": [{"n": 7, "qtype": "單選", "stem": "依據下文，符合全文旨意的選項是：", "options": {"A": "興衰成敗有數，不可力強而致", "B": "治國悖離民心，如同為淵驅魚", "C": "大材不宜小用，割雞焉用牛刀", "D": "國君用人之術，務在明賞慎罰"}, "answer": "B", "explain": "文章用一連串比喻說：要招來東西，得用吸引它的方法；用趕走它的方法（貓招鼠、冰招蠅）一定失敗。最後落到治國：桀、紂用嚴刑重罰這種「趕走人民」的方法，想讓人民歸附，當然沒用。這就是「為淵驅魚」——把魚趕到深淵去，治國違背民心反而把人民推走，選(B)。(A)文章講的是方法對不對，不是命中注定。(C)文中「成小不可成大」說的是強迫的手段，不是人才大小。(D)文章反對靠「罰重刑嚴」，沒有談明賞慎罰的用人之術。", "skill": "連串比喻的說理文，答案在最後「落到人事」的那一句（桀、紂……），前面的比喻只是鋪陳。"}], "difficulty": "中", "label": "106指考", "year": 106, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk106-8", "exam": "zk106", "nums": [8], "form": "單題", "img": "img/zk106-8.png", "source": "出處待查（賦體文字）", "author": "", "genre": "其他", "types": ["主旨寓意", "句意理解"], "passage": "或北陸初結，或東風始興。睹之也知其脆易破，涉之也恐其任不勝。由是屏氣而行，虛心而進。在陽敢思乎不冶，通陰庶懷乎克慎。", "translation": "有時是冬天剛結冰，有時是春風剛吹起（冰要融化）。看著它就知道冰又脆又容易破，走在上面就怕它承受不住。因此屏住呼吸走路，小心謹慎地前進。……處處都懷著戒慎的心。", "keywords": [{"w": "北陸", "m": "古代以太陽運行到北陸代指冬天"}, {"w": "任不勝", "m": "承受不住"}, {"w": "屏氣", "m": "屏住呼吸"}, {"w": "克慎", "m": "能夠謹慎"}], "questions": [{"n": 8, "qtype": "單選", "stem": "依據下文，符合全文旨意的選項是：", "options": {"A": "安步當車", "B": "臨深履薄", "C": "盈科後進", "D": "危言危行"}, "answer": "B", "explain": "文章寫冬天初結或春天將融的薄冰，看了知道它脆、走上去怕它撐不住，所以「屏氣而行，虛心而進」，處處小心。這正是《詩經》「如臨深淵，如履薄冰」的「臨深履薄」，形容戒慎恐懼，選(B)。(A)「安步當車」是慢慢走路代替坐車，形容安貧從容，和戒慎無關。(C)「盈科後進」是水把坑洞填滿才往前流，比喻循序漸進。(D)「危言危行」是說話正直、行為端正，和走薄冰的小心不同。", "skill": "文中出現「冰、脆、屏氣、虛心而進」等畫面，先在腦中想像場景，再找能概括這個畫面的成語。"}], "difficulty": "易", "label": "106指考", "year": 106, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk106-10", "exam": "zk106", "nums": [10], "form": "單題", "img": "img/zk106-10.png", "source": "洪繻〈西螺柑賦〉", "author": "洪繻", "genre": "其他", "types": ["句意理解", "寫作手法"], "passage": "圍爐飲酒，對燭讀書。熱腸之際，燥吻之餘。嗽其清津，醉意能醒；吮其玉液，夢慵亦舒。幾回寒味，醰醲流甘之後；一座冷香，繚繞擘瓣之初。", "translation": "圍著火爐喝酒，對著燭光讀書。在肚腸燥熱、嘴唇乾渴的時候，吸一口它清涼的汁液，醉意就能清醒；吮一口它甘美的果汁，睡夢中的慵懶也舒展開來。幾次嚐到清涼的滋味，在醇厚甘甜流過之後；滿座清冷的香氣，在剛剝開果瓣時繚繞不散。", "keywords": [{"w": "燥吻", "m": "乾燥的嘴唇"}, {"w": "嗽", "m": "吸吮"}, {"w": "清津、玉液", "m": "指柑橘的汁液"}, {"w": "醰醲", "m": "味道醇厚"}, {"w": "擘", "m": "剝開"}], "questions": [{"n": 10, "qtype": "單選", "stem": "下文所描寫的西螺柑特質，理解正確的選項是：", "options": {"A": "驅寒生暖，宜共品嘗", "B": "清熱醒酒，足資入藥", "C": "滋味清芳，沁人心脾", "D": "可製佳釀，吟詠助興"}, "answer": "C", "explain": "文中說柑汁「醉意能醒」、「夢慵亦舒」，又有「寒味」「流甘」「冷香」，重點是滋味清涼甘甜、香氣清新，讓人身心舒暢，就是(C)滋味清芳、沁人心脾。(A)柑子是「寒味」「冷香」，是消熱，不是驅寒生暖。(B)能醒酒沒錯，但文中沒說可以入藥。(D)「圍爐飲酒」的酒不是柑子做的，文中也沒說可釀酒。", "skill": "描寫型賦文，把感官字（寒、甘、冷香、醒）挑出來歸納特質；選項多出原文沒提的功能（入藥、釀酒）就刪。"}], "difficulty": "易", "label": "106指考", "year": 106, "kind": "指考", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "鹿港乘桴記"}, {"id": "zk106-11", "exam": "zk106", "nums": [11], "form": "單題", "img": "img/zk106-11.png", "source": "《西遊記》第十回", "author": "吳承恩", "genre": "書信序跋", "types": ["文化常識", "句意理解"], "passage": "辱愛弟魏徵，頓首書拜，大都案契兄崔老先生台下：憶昔交遊，音容如在。倏爾數載，不聞清教。常只是遇節令，設蔬品奉祭，未卜享否？又承不棄，夢中臨示，始知我兄長大人高遷。奈何陰陽兩隔，天各一方，不能面覿。今因我太宗文皇帝倏然而故，料是對案三曹，必然得與兄長相會。萬祈俯念生日交情，方便一二，放我陛下回陽，殊為愛也。容再修謝。不盡。", "translation": "承蒙厚愛的弟弟魏徵，叩頭寫信拜上陰間大都案結拜兄長崔老先生：回想從前交往，您的聲音容貌好像還在眼前。轉眼過了幾年，沒聽到您的教誨。我只能在逢年過節時，準備素菜祭拜您，不知道您是否享用了？又承蒙您不嫌棄，在夢中指點我，才知道兄長已經升官。無奈陰陽兩隔，各在一方，不能見面。如今我們太宗文皇帝突然過世，想必要三方對質審案，一定能和兄長見面。千萬請您顧念我們生前的交情，行個方便，放我們皇上回到陽間，那就是對我最大的恩惠了。以後再寫信道謝。話說不完。", "keywords": [{"w": "辱愛", "m": "謙詞，承蒙厚愛"}, {"w": "契兄", "m": "結拜兄長"}, {"w": "台下", "m": "書信提稱語，用於平輩"}, {"w": "面覿", "m": "見面"}, {"w": "生日", "m": "生前的日子"}], "questions": [{"n": 11, "qtype": "單選", "stem": "依據下列《西遊記》中的書信，敘述正確的選項是：", "options": {"A": "寄信者是崔老先生，受信者是魏徵", "B": "崔老先生請魏徵多照顧太宗皇帝，免其懸念", "C": "由提稱語「台下」可推知，崔老先生為魏徵的長輩", "D": "魏徵無法在人世間見到崔老先生，但仍按時備清饌表達懷思"}, "answer": "D", "explain": "(D)信中說「陰陽兩隔……不能面覿」，可見崔老先生已在陰間，但魏徵「遇節令，設蔬品奉祭」，按時準備素菜祭拜表達思念，正確。(A)開頭「愛弟魏徵……書拜……崔老先生台下」，寫信的是魏徵，收信的是崔老先生，弄反了。(B)是魏徵請崔老先生「放我陛下回陽」，不是崔請魏照顧太宗。(C)「台下」是平輩用的提稱語，而且魏徵稱崔為「契兄」，兩人是結拜兄弟，屬於平輩。", "skill": "書信題先看開頭格式：「自稱＋署名……對方稱謂＋提稱語」，就能分清寄信人與收信人和輩分。"}], "difficulty": "易", "label": "106指考", "year": 106, "kind": "指考", "textcat": "生活情境文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "zk106-12", "exam": "zk106", "nums": [12, 13], "form": "題組", "img": "img/zk106-12.png", "source": "宇文所安《中國古典文學中的往事再現》（改寫）；第13題選項引文天祥〈正氣歌〉、李煜〈子夜歌〉、劉長卿〈長沙過賈誼宅〉、丘逢甲〈離臺詩〉", "author": "宇文所安", "genre": "說理議論", "types": ["文意推論", "人物情感"], "passage": "（第13題選項詩句）\n(A)鼎鑊甘如飴，求之不可得。（文天祥）\n(B)故國夢重歸，覺來雙淚垂。（李煜）\n(C)三年謫宦此棲遲，萬古惟留楚客悲。（詠賈誼）\n(D)扁舟去作鴟夷子，回首河山意黯然。（丘逢甲）", "translation": "(A)就算被丟進鍋裡烹煮也甘之如飴，想求這樣的死都求不到。\n(B)夢中又回到故國，醒來兩行淚流下。\n(C)被貶官在這裡滯留了三年，千古只留下這位楚地遊子的悲哀。\n(D)坐著小船離去，像范蠡（鴟夷子皮）那樣隱退，回頭看著故鄉山河，心情黯然。", "keywords": [{"w": "鼎鑊", "m": "烹人的刑具"}, {"w": "飴", "m": "麥芽糖"}, {"w": "棲遲", "m": "滯留"}, {"w": "鴟夷子", "m": "范蠡助越滅吳後泛舟而去，自號鴟夷子皮"}], "questions": [{"n": 12, "qtype": "單選", "stem": "下列敘述，符合作者看法的選項是：", "options": {"A": "西方的悲劇英雄雖然早已預知難逃毀滅，仍堅持抗爭不懈", "B": "中國傳統中的「命」具有非人格的神祕性，人們無從窺知", "C": "中國缺乏西方意義的悲劇，乃因人們習於順「命」而遠遁", "D": "無論西方或中國的傳統，皆有人們無法超越必然性的思維"}, "answer": "D", "explain": "西方悲劇說人受「更大的意志」支配、無可奈何地走向毀滅；中國則有「周而復始的自然」這種必然性，稱為「命」，兩者都承認有人無法超越的必然性，所以(D)正確。(A)西方悲劇英雄是「從懵然無知到恍然大悟」，不是早已預知；早就知道結局的是中國的人物。(B)作者說中國的「命」完全能為人所理解，還會出現徵兆，不是無從窺知。(C)中國的人物是「知其不可而為之」，克服絕望，不是逃避。", "skill": "比較型文章先做一張「西方／中國」對照表，選項常把兩邊的特徵對調。"}, {"n": 13, "qtype": "單選", "stem": "下列人物，符合作者所謂「與悲劇英雄對應的人物」的選項是：", "options": {"A": "「鼎鑊甘如飴，求之不可得」的文天祥", "B": "「故國夢重歸，覺來雙淚垂」的李後主", "C": "「三年謫宦此棲遲，萬古惟留楚客悲」的賈誼", "D": "「扁舟去作鴟夷子，回首河山意黯然」的丘逢甲"}, "answer": "A", "explain": "作者說的中國式悲劇人物有三個條件：早知結局不可避免、不抗爭命運卻「知其不可而為之」、克服絕望令人崇敬。(A)文天祥被俘後明知必死，卻說就算受鼎鑊之刑也甘心，堅守氣節，正符合。(B)李後主只是夢回故國、醒來流淚，是亡國的悲傷懷念，沒有「知其不可而為之」。(C)寫賈誼被貶後滯留長沙的悲哀，是抑鬱不得志。(D)丘逢甲抗日失敗後離臺，像范蠡那樣乘舟遠去，心情黯然，是退離而不是堅持。", "skill": "把文中的定義拆成幾個條件，逐一檢查選項人物「知道結局嗎？還堅持嗎？」。"}], "difficulty": "中", "label": "106指考", "year": 106, "kind": "指考", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "zk106-14", "exam": "zk106", "nums": [14, 15], "form": "題組", "img": "img/zk106-14.png", "source": "呂叔湘《文言虛字》（改寫）；第15題選項引《論語‧憲問》、顧炎武〈廉恥〉、陶淵明〈桃花源記〉、《荀子‧勸學》", "author": "呂叔湘", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "（文中例句）孔融幼時，與諸兄食梨，取其小者。／始作俑者其無後乎？／爾其無忘乃父之志！\n（第15題選項）\n(A)微管仲，吾其被髮左衽矣\n(B)天下其有不亂，國家其有不亡者乎\n(C)餘人各復延至其家，皆出酒食\n(D)蘭槐之根是為芷，其漸之滫，君子不近", "translation": "孔融小時候和哥哥們吃梨，拿其中小的。／最先做人俑陪葬的人，大概會絕子絕孫吧？／你可不要忘了你父親的志向！\n(A)如果沒有管仲，我們大概都要披散頭髮、衣襟向左開（被夷狄統治）了。\n(B)天下哪有不亂、國家哪有不亡的呢？\n(C)其他人也各自邀請漁人到他們家裡，都拿出酒飯招待。\n(D)蘭槐的根叫做芷，如果把它浸在臭水裡，君子就不會靠近。", "keywords": [{"w": "其（指稱）", "m": "他的、那個、其中的"}, {"w": "其（測度）", "m": "大概、恐怕，同「殆」"}, {"w": "其（勸勉）", "m": "可要、應當"}, {"w": "其（假設）", "m": "如果"}, {"w": "滫", "m": "臭水、淘米水"}], "questions": [{"n": 14, "qtype": "單選", "stem": "依據上文，符合作者看法的選項是：", "options": {"A": "「殆」、「可」、「其」三者作為語氣詞，意義可相通", "B": "表示語氣的「其」，是從作為「其中之」的「其」變化而來", "C": "「其」作「他的」講和作「那個」講，是為了白話理解之便", "D": "古文中「其」作為語氣只有一種用法，在白話才有測度和勸勉的區別"}, "answer": "C", "explain": "(C)作者認為古人心中只有一個指稱的「其」；現代人把它分成「他的」和「那個」兩種講法，是因為白話剛好用兩個不同的詞來翻譯，方便用白話理解，所以選(C)。(A)作者說表測度的「其」相當於「殆」（大概），表勸勉的「其」相當於白話的「可」，這是兩種不同的意思，「殆」和「可」並不能互換，說三者意義相通是錯的。(B)作者明說語氣的「其」和指稱用法毫無關係，是兩個不同的詞，不是變化而來。(D)文中的測度、勸勉兩種，本來就是古文裡「其」的語氣用法，不是到白話才分出來的。", "skill": "語法說明文要抓作者的判斷句（毫無關係、應該是、相當於）；選項把兩個不同的「相當於」硬說成「相通」，就是在偷換。"}, {"n": 15, "qtype": "單選", "stem": "依據上文，下列文句中「其」的說明，正確的選項是：", "options": {"A": "微管仲，吾「其」被髮左衽矣：測度語氣，「殆」之意", "B": "天下其有不亂，國家「其」有不亡者乎：勸勉語氣，「可」之意", "C": "餘人各復延至「其」家，皆出酒食：指稱用法，「其中之」之意", "D": "蘭槐之根是為芷，「其」漸之滫，君子不近：指稱用法，「那個」之意"}, "answer": "A", "explain": "(A)孔子說要不是管仲，我們「大概」都成了夷狄打扮，「其」是推測，等於「殆」，正確。(B)這句是反問：天下哪有不亂、國家哪有不亡的呢？「其」是加強反問的語氣（豈），不是勸勉。(C)「其家」是「他們的家」，是「他的」意思，不是「其中之」。(D)「其漸之滫」是「如果把它浸在臭水裡」，「其」表假設，不是指稱。", "skill": "判斷「其」先翻成白話試試：能換成「大概」是測度、換成「可要」是勸勉、換成「他的／其中」是指稱、換成「如果」是假設。"}], "difficulty": "難", "label": "106指考", "year": 106, "kind": "指考", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "勸學、桃花源記、廉恥"}, {"id": "zk106-16", "exam": "zk106", "nums": [16, 17], "form": "題組", "img": "img/zk106-16.png", "source": "謝枋得〈慶全庵桃花〉、徐孚遠〈桃花〉", "author": "謝枋得、徐孚遠", "genre": "古典詩詞曲", "types": ["詩詞賞析", "典故出處", "比較閱讀"], "passage": "慶全庵桃花　謝枋得\n尋得桃源好避秦，桃紅又見一年春。花飛莫遣隨流水，怕有漁郎來問津。\n桃花　徐孚遠\n海山春色等閒來，朵朵還如人面開。千載避秦真此地，問君何必武陵回。", "translation": "謝詩：我找到了一處像桃花源的好地方，可以躲避暴秦（元朝），桃花紅了，又過了一年春天。花瓣飄落時，別讓它隨著流水漂出去，怕有漁夫順著花瓣來打聽路。\n徐詩：海島山間的春色輕易就來了，朵朵桃花仍像人的笑臉一樣綻放。千年來說的避秦之地，真正就是這裡，請問你何必回到武陵去呢？", "keywords": [{"w": "避秦", "m": "〈桃花源記〉中先人避秦亂入桃源，此借指躲避異族統治"}, {"w": "問津", "m": "打聽渡口、探訪"}, {"w": "等閒", "m": "輕易、平常"}, {"w": "人面", "m": "借崔護「人面桃花相映紅」"}, {"w": "武陵", "m": "〈桃花源記〉漁人來自武陵，代指桃源之外的世界"}], "questions": [{"n": 16, "qtype": "單選", "stem": "下列關於謝、徐二人詩中「桃花源」的敘述，正確的選項是：", "options": {"A": "謝枋得希望所居的「桃花源」不受外界打擾", "B": "徐孚遠認為「桃花源」之地不適合安居久留", "C": "二人都因傾慕陶淵明而四處尋訪「桃花源」", "D": "二人皆自認已找到陶淵明的「桃花源」遺址"}, "answer": "A", "explain": "(A)謝詩「花飛莫遣隨流水，怕有漁郎來問津」，不想讓花瓣漂出去引來外人，就是希望隱居處不受打擾，正確。(B)徐詩說「千載避秦真此地，問君何必武陵回」，這裡才是真正的避秦之地，何必回去，表示正適合久居。(C)兩人是因為國家滅亡、不願受異族統治才隱居，不是因為傾慕陶淵明去四處尋訪。(D)兩人都是把自己住的地方比作桃花源，不是找到真正的遺址。", "skill": "讀用典的詩，先問「作者把典故裡的什麼，比成自己的什麼」，不要把比喻當成真事。"}, {"n": 17, "qtype": "單選", "stem": "若謝詩作於福建，徐詩作於臺灣，下列敘述正確的選項是：", "options": {"A": "徐詩「問君何必武陵回」的「武陵」，是暗指臺灣", "B": "謝詩「怕有漁郎來問津」的「漁郎」，是暗指作者自己", "C": "二詩運用「避秦」典故時，皆將原本避亂之地引申為不受異族統治之地", "D": "二詩的「花飛莫遣隨流水」、「朵朵還如人面開」，皆流露避世而居的喜悅"}, "answer": "C", "explain": "(C)謝枋得在南宋亡後隱居福建、拒絕元朝徵聘；徐孚遠在明亡後隨鄭成功來臺。他們說的「避秦」都是躲開元、清這些異族政權，正確。(A)「此地」才是臺灣；「武陵」是漁人原來住的外面世界，暗指被清朝統治的中原。(B)「漁郎」是可能來打擾的外人（例如來徵聘他的元朝官員），不是作者自己。(D)「花飛莫遣隨流水」是擔心被發現，帶著憂慮，不是喜悅。", "skill": "題目給的作者生平就是鑰匙：把「秦」換成作者當時的敵人，再檢查每個意象的對應。"}], "difficulty": "中", "label": "106指考", "year": 106, "kind": "指考", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "桃花源記"}, {"id": "zk106-19", "exam": "zk106", "nums": [19], "form": "單題", "img": "img/zk106-19.png", "source": "選項出自賈誼〈過秦論〉、《戰國策‧馮諼客孟嘗君》、蒲松齡〈勞山道士〉、《左傳‧燭之武退秦師》、曹丕〈典論論文〉、「淡屬」句（出處待查，疑為臺灣方志）、《史記‧伯夷列傳》、方苞〈左忠毅公軼事〉、黃宗羲〈原君〉、《史記‧項羽本紀》", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)執捶拊以鞭笞天下，威振四海／今君有區區之薛，不拊愛子其民\n(B)一夕歸，見二人與師共酌／舍鄭以為東道主，行李之往來，共其乏困\n(C)武仲以能屬文為蘭臺令史／淡屬素敦古處，新、艋尤為菁華所聚之區\n(D)余登箕山，其上蓋有許由冢云／與先君子善，謂獄中語乃親得之於史公云\n(E)毅宗之語公主，亦曰：若何為生我家／君王為人不忍。若入，前為壽，壽畢，請以劍舞", "translation": "(A)拿著刑杖鞭打天下，威勢震動四海／現在您只有小小的薛地，卻不愛護那裡的百姓、把他們當子女看待。\n(B)一天晚上回來，看見兩個人和師父一起喝酒／如果放過鄭國，讓它當東方路上的主人，使者往來時，供應他們缺少的東西。\n(C)傅毅（武仲）因為會寫文章當上蘭臺令史／淡水一帶向來敦厚守古風，新莊、艋舺尤其是精華聚集的地方。\n(D)我登上箕山，山上大概有許由的墳墓吧／（他）和我父親交好，說獄中的那些話是親自從史可法那裡聽來的。\n(E)崇禎皇帝對公主說：你為什麼要生在我家／君王為人心軟。你進去，上前敬酒，敬完酒，請求表演舞劍。", "keywords": [{"w": "捶拊", "m": "鞭杖之類的刑具"}, {"w": "拊愛", "m": "撫愛"}, {"w": "共", "m": "一起／同「供」，供應"}, {"w": "屬文", "m": "寫文章"}, {"w": "屬", "m": "隸屬、所轄之地"}, {"w": "云", "m": "句末語助詞，無義"}, {"w": "若", "m": "你"}], "questions": [{"n": 19, "qtype": "多選", "stem": "下列各組文句「」內的字，前後意義相同的選項是︰", "options": {"A": "執捶「拊」以鞭笞天下，威振四海／今君有區區之薛，不「拊」愛子其民", "B": "一夕歸，見二人與師「共」酌／舍鄭以為東道主，行李之往來，「共」其乏困", "C": "武仲以能「屬」文為蘭臺令史／淡「屬」素敦古處，新、艋尤為菁華所聚之區", "D": "余登箕山，其上蓋有許由冢「云」／與先君子善，謂獄中語乃親得之於史公「云」", "E": "毅宗之語公主，亦曰：「若」何為生我家／君王為人不忍。「若」入，前為壽，壽畢，請以劍舞"}, "answer": "DE", "explain": "(A)前「拊」和「捶」連用，是刑杖一類的東西（名詞）；後「拊」是撫愛（動詞），不同。(B)前「共」是一起，後「共」通「供」，供應，不同。(C)前「屬文」是寫文章，後「淡屬」是淡水所轄的地區，不同。(D)兩個「云」都放在句尾，是語助詞，沒有實際意思，相同。(E)兩個「若」都是第二人稱「你」，相同。", "skill": "注意通同字（共＝供）和詞性：同一字當名詞、動詞時意思常常不同，先判斷詞性再翻譯。"}], "difficulty": "中", "label": "106指考", "year": 106, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "燭之武退秦師、馮諼客孟嘗君、鴻門宴、典論論文、原君、勞山道士、左忠毅公軼事"}, {"id": "zk106-23", "exam": "zk106", "nums": [23], "form": "單題", "img": "img/zk106-23.png", "source": "古龍《浣花洗劍錄》；選項出自《莊子‧外物》、《老子》第41章、《老子》第78章、《老子》第48章、《莊子‧大宗師》", "author": "古龍", "genre": "經典語錄", "types": ["比較閱讀", "主旨寓意"], "passage": "(A)言者所以在意，得意而忘言\n(B)大音希聲，大象無形，道隱無名\n(C)受國之垢，是謂社稷主；受國不祥，是為天下王\n(D)為學日益，為道日損。損之又損，以至於無為，無為而無不為\n(E)泉涸，魚相與處於陸，相呴以濕，相濡以沫，不如相忘於江湖", "translation": "(A)語言是用來表達意思的，懂得意思就可以忘掉語言。\n(B)最大的聲音反而聽起來沒有聲音，最大的形象反而看不出形狀，道隱藏起來沒有名稱。\n(C)能承受國家的屈辱，才算是國家的君主；能承擔國家的災禍，才能做天下的王。\n(D)求學問一天比一天增加，修道一天比一天減少；減少再減少，直到無為的境界，無為卻沒有什麼做不到。\n(E)泉水乾了，魚一起困在陸地上，互相吐氣、用口沫濕潤對方，不如在江湖中彼此忘記。", "keywords": [{"w": "希", "m": "稀少、聽不見"}, {"w": "垢", "m": "屈辱"}, {"w": "損", "m": "減少"}, {"w": "呴", "m": "吐氣"}], "questions": [{"n": 23, "qtype": "多選", "stem": "武俠小說論及武術武道，多受傳統文化影響。依據古龍《浣花洗劍錄》中紫衣侯對劍法的論述，可與其觀點相應的選項是：", "options": {"A": "言者所以在意，得意而忘言", "B": "大音希聲，大象無形，道隱無名", "C": "受國之垢，是謂社稷主；受國不祥，是為天下王", "D": "為學日益，為道日損。損之又損，以至於無為，無為而無不為", "E": "泉涸，魚相與處於陸，相呴以濕，相濡以沫，不如相忘於江湖"}, "answer": "ABD", "explain": "紫衣侯說：師兄把劍法全部忘記後才悟出「劍意」，沒有固定招式卻招招精妙；自己記得所有劍法，只得到「形骸」。重點是「忘掉招式、得到精神」和「最高境界沒有固定形式」。(A)懂了意思就忘掉語言，正如忘了招式得到劍意，對。(B)最大的形象沒有形狀，正如最高的劍法「無一固定的招式」，對。(C)講君主要能承受屈辱災禍，和劍法無關，錯。(D)求道要不斷減損，減到無為卻無所不為，正如把劍招忘光反而「隨心所欲」，對。(E)講魚在困境中互相濕潤，不如在江湖中相忘，重點在擺脫困境、回歸自然的人際關係，不是忘記技巧得到精髓，錯。", "skill": "先把白話文的核心概念濃縮成兩三個關鍵詞（忘形得意、無固定形式），再拿去比對文言選項。"}], "difficulty": "中", "label": "106指考", "year": 106, "kind": "指考", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "zk106-24", "exam": "zk106", "nums": [24], "form": "單題", "img": "img/zk106-24.png", "source": "高明《琵琶記》〈水調歌頭〉、沈璟〈二郎神‧論曲〉", "author": "高明、沈璟", "genre": "古典詩詞曲", "types": ["比較閱讀", "主旨寓意"], "passage": "甲、秋燈明翠幕，夜案覽芸編。今來古往，其間故事幾多般。少甚佳人才子，也有神仙幽怪，瑣碎不堪觀。正是不關風化體，縱好也徒然。論傳奇，樂人易，動人難。知音君子，這般另作眼兒看：休論插科打諢，也不尋宮數調，只看子孝共妻賢。正是驊騮方獨步，萬馬敢爭先？\n乙、何元朗，一言兒啟詞中寶藏。道欲度新聲休走樣。名為樂府，須教合律依腔。寧使時人不鑑賞，無使人撓喉捩嗓。說不得才長。越有才，越當著意斟量。", "translation": "甲：秋夜燈光照著翠綠帷幕，夜裡在案頭讀書。古往今來，故事有多少種。才子佳人的不少，也有神仙鬼怪，瑣碎得不值得看。那些和教化風俗無關的作品，就算寫得好也沒用。說到傳奇戲曲，讓人快樂容易，讓人感動難。懂戲的君子，請另眼看待這部戲：不要計較有沒有插科打諢，也不要挑剔宮調格律，只看它寫兒子孝順、妻子賢慧。這正是駿馬獨自領先，其他萬匹馬哪敢爭先？\n乙：何元朗的一句話，打開了作曲的寶藏。他說想譜新曲就不要走樣。既然叫做樂府，就必須合乎格律、依照腔調。寧可讓當時的人不欣賞，也不要讓人唱得扭喉嚨、彆嗓子。不要只說自己才華高，越有才華，越要用心斟酌（音律）。", "keywords": [{"w": "芸編", "m": "書籍"}, {"w": "風化", "m": "風俗教化"}, {"w": "插科打諢", "m": "戲曲中逗笑的動作和台詞"}, {"w": "尋宮數調", "m": "講究宮調格律"}, {"w": "驊騮", "m": "駿馬"}, {"w": "撓喉捩嗓", "m": "唱起來彆扭、拗嗓"}], "questions": [{"n": 24, "qtype": "多選", "stem": "下列二段文字論述曲的創作，選出敘述正確的選項：", "options": {"A": "甲文主張傳奇宜透過故事的演出，達到移易風俗的作用", "B": "乙文認為作者越是有才華，越當以通俗為標準斟酌文詞", "C": "甲文強調戲曲的趣味性與娛樂性，乙文強調作家的才情", "D": "甲文重視戲曲教化效果，乙文不太在意曲作是否受賞識", "E": "甲乙二文皆主張作曲應費心經營，務必使曲文協合音律"}, "answer": "AD", "explain": "甲文說「不關風化體，縱好也徒然」「只看子孝共妻賢」，重教化；乙文說「須教合律依腔」「寧使時人不鑑賞，無使人撓喉捩嗓」，重音律。(A)甲文要靠戲曲故事達到風俗教化，對。(B)乙文的「斟量」是斟酌是否合律依腔，不是以通俗為標準，錯。(C)甲文說「休論插科打諢」，反而不重娛樂；乙文說「說不得才長」，不強調才情，錯。(D)甲重教化；乙「寧使時人不鑑賞」，不太在意是否被賞識，對。(E)甲文說「也不尋宮數調」，不講究音律，只有乙文主張合律，錯。", "skill": "兩段比較題先各用四個字概括立場（甲：重視教化；乙：重視音律），再檢查選項有沒有張冠李戴。"}], "difficulty": "中", "label": "106指考", "year": 106, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk106-nc1", "exam": "zk106", "nums": ["一"], "form": "單題", "img": "img/zk106-nc1.png", "source": "李斯〈諫逐客書〉（甲）；乙、丙為命題材料", "author": "李斯", "genre": "書信序跋", "types": ["文意推論", "主旨寓意"], "passage": "臣聞地廣者粟多，國大者人眾，兵彊者則士勇。是以泰山不讓土壤，故能成其大；河海不擇細流，故能就其深；王者不卻眾庶，故能明其德。是以地無四方，民無異國，四時充美，鬼神降福，此五帝三王之所以無敵也。今乃棄黔首以資敵國，卻賓客以業諸侯，使天下之士退而不敢西向，裹足不入秦，此所謂藉寇兵而齎盜糧者也。", "translation": "我聽說土地廣大糧食就多，國家大人口就多，兵力強士兵就勇敢。所以泰山不推辭一小撮土，才能成就它的高大；河海不挑剔細小的水流，才能成就它的深廣；君王不拒絕眾多百姓，才能彰顯他的德行。因此土地不分東西南北，百姓不分哪國人，一年四季都充實美好，鬼神也降福，這就是五帝三王天下無敵的原因。現在卻拋棄百姓去幫助敵國，拒絕賓客去成就諸侯的霸業，讓天下的人才退縮不敢往西來，停下腳步不進入秦國，這就是所謂把武器借給敵寇、把糧食送給盜賊啊。", "keywords": [{"w": "讓", "m": "推辭、拒絕"}, {"w": "卻", "m": "拒絕、退回"}, {"w": "黔首", "m": "百姓"}, {"w": "資", "m": "資助"}, {"w": "業", "m": "使……成就功業"}, {"w": "藉", "m": "借給"}, {"w": "齎", "m": "送給"}], "questions": [{"n": "一", "qtype": "非選", "stem": "觀點闡述（18分）：參考框線內的甲（李斯〈諫逐客書〉）、乙（本國人才受他國優渥條件吸引，造成人才外流）、丙（輸入人才有助競爭力，但也會剝奪本國就業、瓜分資源、衍生文化衝擊）三則材料，發表你對「國際人才流動」的看法。文長限200－250字（約9－11行）。", "options": {}, "answer": "", "ref_answer": "可先指出甲文主旨：秦國若「不讓土壤、不擇細流」廣納各國人才，就能強大；驅逐客卿則是「藉寇兵而齎盜糧」，等於資助敵國。再連結乙、丙：人才流動是雙面刃——對輸出國可能造成人才外流（乙），對輸入國則能提升競爭力，但也有就業排擠、資源分配與文化衝擊（丙）。最後提出自己的立場與做法，例如：國家應如李斯所說以開放胸襟延攬人才，同時改善本國薪資與環境留住人才，並配套就業保障與文化融合措施，讓人才流動成為互利循環。", "ref_official": false, "explain": "這題要「綜整三則材料」再說自己的看法。先讀懂甲文：李斯用泰山、河海的比喻說明「包容才能壯大」，最後一句「藉寇兵而齎盜糧」是說趕走人才等於幫敵人。乙說人才流出的壞處，丙說人才流入的好處和壞處。寫作時可以用「甲文說明延攬人才的好處→乙、丙補充流動的兩面→我主張如何兼顧」的順序，引用文言關鍵句當論據，結論要明確。", "skill": "觀點闡述題：先替每則材料寫一句摘要，找出它們之間的關係（支持、補充、對立），再亮出自己的立場。"}], "difficulty": "中", "label": "106指考", "year": 106, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "諫逐客書"}, {"id": "xc107-4", "exam": "xc107", "nums": [4], "form": "單題", "img": "img/xc107-4.png", "source": "王國維《東山雜記》（引葉夢得《避暑錄話》）", "author": "王國維", "genre": "說理議論", "types": ["文意推論", "字詞解釋"], "passage": "葉石林《避暑錄話》中多精語。其論人才曰：「唐自懿、僖以後，人才日削，至於五代，謂之□□□□可也。然吾觀浮屠中乃有雲門、臨濟、德山、趙州數十輩人，卓然超世，是可與扶持天下，配古名臣。然後知其散而橫潰者，又有在此者也」云云。此論天下人才有定量，不出於此則出於彼，學問亦然。元明二代，於學術蓋無可言，至於詩文，亦不能出唐宋範圍，然書畫大家□□□□。國朝則學盛而藝衰。物莫能兩大，亦自然之勢也。", "translation": "葉夢得《避暑錄話》裡有很多精闢的話。他論人才說：「唐朝從懿宗、僖宗以後，人才一天天減少，到了五代，可以說是□□□□了。但我看佛門中卻有雲門、臨濟、德山、趙州等幾十位高僧，卓越超群，可以扶持天下，媲美古代名臣。這才知道那些散失潰亂的人才，原來跑到這裡了。」這是說天下人才有固定的量，不出現在這裡就出現在那裡，學問也一樣。元、明兩代，學術上沒什麼可說的，詩文也跳不出唐宋的範圍，但書畫大家卻□□□□。本朝則是學術興盛而藝術衰落。萬物不能兩方面同時強大，也是自然的趨勢。", "keywords": [{"w": "日削", "m": "一天天減少"}, {"w": "浮屠", "m": "佛教、僧人"}, {"w": "橫潰", "m": "潰散"}, {"w": "國朝", "m": "本朝（指清朝）"}, {"w": "接武", "m": "腳步相接，比喻接連不斷"}], "questions": [{"n": 4, "qtype": "單選", "stem": "閱讀下文，最適合填入□□□□內的語詞依序是：", "options": {"A": "空國無人／沒沒無聞", "B": "空國無人／接武而起", "C": "人才輩出／沒沒無聞", "D": "人才輩出／接武而起"}, "answer": "B", "explain": "答案(B)。第一空：前面說唐末「人才日削」，所以五代要填「空國無人」（國中沒有人才），不能填「人才輩出」。第二空：文章主張「人才有定量，不出於此則出於彼」，元明學術、詩文不行，人才就跑到書畫上去，所以書畫大家「接武而起」（一個接一個出現），不會是「沒沒無聞」。", "skill": "填空題先找文章的主張（人才總量固定，此消彼長），再用前後文的轉折詞（『然』）判斷空格是正面還是負面。"}], "difficulty": "中", "label": "107學測", "year": 107, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc107-10", "exam": "xc107", "nums": [10], "form": "單題", "img": "img/xc107-10.png", "source": "宋濂《燕書》", "author": "宋濂", "genre": "寓言故事", "types": ["主旨寓意", "文意推論"], "passage": "豚澤之人養蜀雞，有文而赤翁。有群雓周周鳴。忽晨風過其上，雞遽翼諸雓，晨風不得捕，去。已而有烏來，與雓同啄。雞視之兄弟也，與之下上，甚馴。烏忽銜其雓飛去。雞仰視悵然，似悔為其所賣也。", "translation": "豚澤有人養了一隻蜀雞，羽毛有花紋，頸毛是紅色的。牠帶著一群小雞啾啾叫。忽然一隻晨風鳥（猛禽）從上空飛過，母雞立刻張開翅膀護住小雞，晨風抓不到，就飛走了。不久來了一隻烏鴉，和小雞一起啄食。母雞把牠當兄弟看待，和牠一起上上下下，非常溫順。烏鴉忽然叼走一隻小雞飛了。母雞抬頭看著，很失落，好像後悔被牠出賣了。", "keywords": [{"w": "赤翁", "m": "紅色頸毛"}, {"w": "雓", "m": "小雞"}, {"w": "翼", "m": "用翅膀護住（名詞作動詞）"}, {"w": "賣", "m": "出賣、欺騙"}], "questions": [{"n": 10, "qtype": "單選", "stem": "依據下文，最能與文旨呼應的是：", "options": {"A": "螳螂捕蟬，黃雀在後", "B": "鳥盡弓藏，兔死狗烹", "C": "福生於畏，禍起於忽", "D": "失之東隅，收之桑榆"}, "answer": "C", "explain": "答案(C)。母雞對明顯的敵人晨風很警覺，所以小雞沒事；對看起來友善的烏鴉卻放下戒心，結果小雞被叼走——「福生於畏（有戒心就有福），禍起於忽（疏忽就招禍）」。(A)是只顧眼前利益、不知背後有危險；(B)是事成之後功臣被拋棄；(D)是先失去、後來在別處得到補償。都不合。", "skill": "寓言題：比較故事中的「兩次事件」結果為何不同（這題是警覺 vs. 疏忽），差別處就是寓意。"}], "difficulty": "易", "label": "107學測", "year": 107, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc107-11", "exam": "xc107", "nums": [11], "form": "單題", "img": "img/xc107-11.png", "source": "黃宗羲〈原君〉、《商君書‧壹言》、《墨子‧天志》", "author": "黃宗羲、商鞅、墨子", "genre": "說理議論", "types": ["文化常識", "主旨寓意"], "passage": "甲、古者以天下為主，君為客，凡君之所畢世而經營者，為天下也；今也以君為主，天下為客，凡天下之無地而得安寧者，為君也。是以其未得之也，屠毒天下之肝腦，離散天下之子女，以博我一人之產業，曾不慘然！乙、凡將立國，制度不可不察也，治法不可不慎也，國務不可不謹也，事本不可不摶也。制度時，則國俗可化，而民從制。治法明，則官無邪。國務壹，則民應用。事本摶，則民喜農而樂戰。丙、處大國不攻小國，處大家不篡小家，強者不劫弱，貴者不傲賤，多詐者不欺愚。此必上利於天，中利於鬼，下利於人。三利，無所不利，故舉天下美名加之，謂之聖王。", "translation": "甲、古時候以天下百姓為主，君主為客，君主一生經營的，都是為了天下；現在以君主為主，天下為客，天下沒有一處能得到安寧，都是因為君主。所以他還沒得到天下時，殘害天下人的性命，拆散天下人的子女，來換取他一個人的產業，竟然一點也不難過！\n乙、凡是要建立國家，制度不能不仔細考察，法令不能不謹慎，國家政務不能不專一，根本事業（農戰）不能不集中力量。制度合乎時宜，民俗就能改變，人民就會服從。法令明確，官吏就不會作惡。政務專一，人民就能被使用。根本集中，人民就喜歡農耕、樂於作戰。\n丙、大國不攻打小國，大家族不掠奪小家族，強的不搶弱的，貴的不輕視賤的，狡詐的不欺負愚笨的。這樣一定對上有利於天，中有利於鬼神，下有利於人民。三方面都有利，就無所不利，所以天下把一切美名都加給他，稱他為聖王。", "keywords": [{"w": "畢世", "m": "一生"}, {"w": "博", "m": "換取"}, {"w": "摶", "m": "集中、專一"}, {"w": "篡", "m": "奪取"}], "questions": [{"n": 11, "qtype": "單選", "stem": "下引文句之學派歸屬，排列順序正確的是：", "options": {"A": "法家／道家／墨家", "B": "法家／儒家／道家", "C": "儒家／法家／墨家", "D": "儒家／墨家／道家"}, "answer": "C", "explain": "答案(C)。甲是黃宗羲〈原君〉，批評君主以天下為私產，主張「天下為主，君為客」，屬儒家民本思想。乙強調制度、法令、國務專一，「民喜農而樂戰」，是商鞅的法家。丙講「不攻小國、強不劫弱」以及「利於天、鬼、人」，是墨家的非攻、天志、明鬼思想。", "skill": "學派關鍵字：儒——民本、仁義；法——法、制度、農戰、賞罰；墨——兼愛、非攻、天志、明鬼、利；道——無為、自然。"}], "difficulty": "中", "label": "107學測", "year": 107, "kind": "學測", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "原君"}, {"id": "xc107-12", "exam": "xc107", "nums": [12, 13, 14], "form": "題組", "img": "img/xc107-12.png", "source": "韓愈〈師說〉", "author": "韓愈", "genre": "說理議論", "types": ["句意理解", "主旨寓意", "比較閱讀"], "passage": "古之學者必有師。師者，所以傳道、受業、解惑也。人非生而知之者，孰能無惑？惑而不從師，其為惑也終不解矣！生乎吾前，其聞道也，固先乎吾，吾從而師之；生乎吾後，其聞道也，亦先乎吾，吾從而師之。吾師道也，夫庸知其年之先後生於吾乎？是故無貴、無賤、無長、無少，道之所存，師之所存也。\n聖人無常師：孔子師郯子、萇弘、師襄、老聃。郯子之徒，其賢不及孔子。孔子曰：「三人行，則必有我師」。是故弟子不必不如師，師不必賢於弟子。聞道有先後，術業有專攻，如是而已。", "translation": "古代求學的人一定有老師。老師是用來傳授道理、教授學業、解答疑惑的。人不是生下來就懂道理的，誰能沒有疑惑？有疑惑卻不跟老師學，那疑惑就永遠解不開了。比我早出生的人，他懂道理本來就比我早，我跟他學；比我晚出生的人，如果他懂道理也比我早，我也跟他學。我學的是道理，哪管他年紀比我大或小呢？所以不論地位高低、年紀大小，道理在哪裡，老師就在哪裡。\n聖人沒有固定的老師：孔子曾向郯子、萇弘、師襄、老聃學習。郯子這些人，賢能比不上孔子。孔子說：「三個人同行，其中一定有可以當我老師的人。」所以學生不一定不如老師，老師不一定比學生賢能。懂得道理有先有後，學問技藝各有專精，就是這樣罷了。", "keywords": [{"w": "受", "m": "通「授」，傳授"}, {"w": "師", "m": "學習、以…為師（動詞）"}, {"w": "庸", "m": "哪裡、何必"}, {"w": "常師", "m": "固定的老師"}, {"w": "之徒", "m": "這些人"}], "questions": [{"n": 12, "qtype": "單選", "stem": "依據上文，下列闡釋正確的是：", "options": {"A": "「人非生而知之者，孰能無惑」，謂人皆不免有惑，故須從師以解惑", "B": "「吾師道也，夫庸知其年之先後生於吾」，謂無論少長均應學習師道", "C": "「聖人無常師」，謂聖人的教育方法異於一般教師，因此能啟迪後進", "D": "「郯子之徒，其賢不及孔子」，謂郯子等人的學生不如孔子弟子優秀"}, "answer": "A", "explain": "答案(A)。「人非生而知之者，孰能無惑」——人不是天生就懂，一定有疑惑，所以要從師解惑，(A)正確。(B)「吾師道也」是「我學習的是道」，「師」當動詞，意思是不管年紀只看道，不是「少長都應學習師道」。(C)「聖人無常師」是聖人沒有固定的老師，誰懂就跟誰學，不是教育方法特別。(D)「郯子之徒」是「郯子這些人」，不是郯子的學生。", "skill": "「之徒」「之屬」常指『這一類人』；「師」接受詞時多當動詞『學習』。"}, {"n": 13, "qtype": "單選", "stem": "依據上文，最符合韓愈對「學習」看法的是：", "options": {"A": "只要有心一定能聞道，學習永遠不嫌遲", "B": "智愚之別會影響學習，故聞道有先有後", "C": "學無止境，自少至長都應該精進地學習", "D": "尊重專業，擇師學習不需計較身分年齡"}, "answer": "D", "explain": "答案(D)。韓愈說「無貴、無賤、無長、無少，道之所存，師之所存」，又說「術業有專攻」——誰在某方面專精就向誰學，不必計較身分和年齡，正是(D)。(A)文中沒說「有心一定能聞道、永遠不嫌遲」；(B)韓愈說聞道先後和年齡無關，沒有談智愚；(C)文中沒有強調「學無止境」。", "skill": "主旨題：選項必須是作者「明白說出」的論點，合理但原文沒說的（如學無止境）不能選。"}, {"n": 14, "qtype": "單選", "stem": "下列文句，與「惑而不從師，其為惑也終不解矣」同樣強調運用資源以追求成長的是：", "options": {"A": "君子生非異也，善假於物也", "B": "梓匠輪輿，能與人規矩，不能使人巧", "C": "君子博學而日參省乎己，則知明而行無過", "D": "日知其所亡，月無忘其所能，可謂好學也已矣"}, "answer": "A", "explain": "答案(A)。「惑而不從師，其為惑也終不解」強調要借助老師這個外在資源來突破自己。(A)荀子〈勸學〉「君子生非異也，善假於物也」——君子天生和別人一樣，只是善於借助外物，同樣是運用資源求成長。(B)孟子說工匠能教人規矩，卻不能使人巧，強調巧要靠自己體會；(C)荀子講博學加上每天自我反省，重點在自省；(D)子夏講每天學新的、每月不忘舊的，重點在溫故知新。", "skill": "比較題先抽出題幹的「關鍵動作」（這題是借助外在資源），選項要有『假』『借』這類向外求助的意思才對。"}], "difficulty": "易", "label": "107學測", "year": 107, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "師說"}, {"id": "xc107-17", "exam": "xc107", "nums": [17, 18], "form": "題組", "img": "img/xc107-17.png", "source": "詠史詩五首（詠項羽、劉邦、范增，作者未標）", "author": "出處待查", "genre": "古典詩詞曲", "types": ["典故出處", "詩詞賞析", "文化常識"], "passage": "42：天亡非戰罪，末路困英雄。氣盡虞同死，司晨笑沛公。\n43：世間快意寧有此，亭長還鄉作天子。沛宮不樂復何為，諸母父兄知舊事。\n66：今日歌大風，明朝歌鴻鵠。為語戚夫人，高皇是假哭。\n98：七十衰翁兩鬢霜，西來一笑火咸陽。平生奇計無他事，只勸鴻門殺漢王。\n99：不修仁德合文明，天道如何擬力爭。隔岸故鄉歸不得，十年空負拔山名。", "translation": "42：（項羽說）是天要亡我，不是作戰的過錯，英雄走到末路受困。氣數已盡，虞姬也一同赴死，連報曉的雞都在嘲笑沛公。（詠項羽）\n43：世上哪有比這更痛快的事，當年的亭長回鄉當了天子。在沛宮歡宴怎能不快樂，鄉里的長輩們都知道他從前的事。（詠劉邦）\n66：今天唱〈大風歌〉，明天唱〈鴻鵠歌〉。告訴戚夫人吧，高皇帝那是假哭。（詠劉邦）\n98：七十歲的老翁兩鬢斑白，西進時看著咸陽大火一笑。他一生的奇計沒有別的，只是勸項羽在鴻門宴殺掉漢王。（詠范增）\n99：不修仁德去順應天理，怎能和天道力爭？故鄉就在江的對岸卻回不去，十年白白背負力能拔山的名聲。（詠項羽）", "keywords": [{"w": "亭長", "m": "劉邦起事前的小官"}, {"w": "大風", "m": "劉邦〈大風歌〉"}, {"w": "鴻鵠", "m": "劉邦為戚夫人作〈鴻鵠歌〉"}, {"w": "拔山", "m": "項羽〈垓下歌〉「力拔山兮氣蓋世」"}, {"w": "鴻門", "m": "鴻門宴，范增勸項羽殺劉邦"}], "questions": [{"n": 17, "qtype": "單選", "stem": "假設某局你的手中尚餘「42」、「43」、「66」、「98」、「99」五張牌卡，下列組合，符合「可出牌型」的是：", "options": {"A": "42＋99", "B": "66＋98", "C": "42＋98＋99", "D": "43＋66＋98"}, "answer": "A", "explain": "答案(A)。先判斷每張牌詠的人：42「末路困英雄、虞同死」是項羽；43「亭長還鄉作天子、沛宮」是劉邦；66「歌大風、戚夫人、高皇」是劉邦；98「七十衰翁、勸鴻門殺漢王」是范增；99「隔岸故鄉歸不得、拔山名」是項羽。出2張或3張須是同一人：(A)42＋99都是項羽，可以。(B)66劉邦＋98范增，不行。(C)多了范增98。(D)43、66是劉邦，98是范增，不行。", "skill": "詠史詩辨人物：抓典故關鍵詞——虞姬、拔山、烏江→項羽；亭長、大風、沛→劉邦；鴻門勸殺、七十老翁→范增。"}, {"n": 18, "qtype": "單選", "stem": "假設在本輪時，你的手中尚餘上述五張牌卡，上一家以【出1張】的牌型打出「55」這張牌，接著由你出牌。若你想取得此局冠軍，下列預想的出牌策略，符合「正確、快速、穩妥」條件的是：", "options": {"A": "①本輪：先出66，再出98，再出99，取得攻牌權；②末輪：出42＋43", "B": "①本輪：出99，取得攻牌權；②末輪：先出42，再出43，再出66，再出98", "C": "①本輪：出98，取得攻牌權；②次輪：出42＋99，取得攻牌權；③末輪：出43＋66", "D": "①本輪：出99，取得攻牌權；②次輪：出43＋66＋98，取得攻牌權；③末輪：出42"}, "answer": "C", "explain": "答案(C)。手上可以配成：項羽一對（42＋99）、劉邦一對（43＋66）、范增單張（98）。本輪上家出1張55，出98（范增）一定大於55，取得攻牌權；次輪出42＋99這對，99是最大號，別人壓不過，再拿攻牌權；末輪出43＋66，出完。三輪結束，又穩又快。(A)一輪只能出一次牌型，不能連出三張，而且42＋43不是同一人。(B)末輪一張一張出，不符合牌型規則，也最慢。(D)43＋66＋98不是同一人，不能出。", "skill": "規則型閱讀題：先把規則條列（同人才能湊對、牌號大者勝），再把手牌分組，最後逐步模擬每個策略是否違規。"}], "difficulty": "中", "label": "107學測", "year": 107, "kind": "學測", "textcat": "生活情境文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "xc107-19", "exam": "xc107", "nums": [19, 20], "form": "題組", "img": "img/xc107-19.png", "source": "賀鑄〈天香〉", "author": "賀鑄", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "煙絡橫林，山沉遠照，邐迤黃昏鐘鼓。燭映簾櫳，蛩催機杼，共苦清秋風露。不眠思婦，齊應和，幾聲砧杵。驚動天涯倦宦，駸駸歲華行暮。當年酒狂自負，謂東君，以春相付。流浪征驂北道，客檣南浦。幽恨無人晤語，賴明月曾知舊遊處。好伴雲來，還將夢去。", "translation": "煙霧籠罩著橫向延伸的樹林，山頭沉沒了遠方的夕照，黃昏的鐘鼓聲一路綿延傳來。燭光映著窗簾，蟋蟀聲像在催促織布，一起承受清秋夜晚的風露之苦。睡不著的思婦們，一齊應和著幾聲搗衣聲。這驚動了遠在天涯、對做官感到疲倦的我，時光飛快，一年又將盡了。\n當年我縱酒狂放、自命不凡，以為春神會把春天交給我。後來卻在北方道路上奔波，在南方水邊乘船漂泊。內心的幽恨沒有人可以傾訴，只有明月知道我從前遊歷的地方。希望它陪伴著雲來，再帶著我的夢回去。", "keywords": [{"w": "邐迤", "m": "連綿不斷"}, {"w": "簾櫳", "m": "窗簾與窗戶"}, {"w": "蛩", "m": "蟋蟀"}, {"w": "砧杵", "m": "搗衣石與棒槌，指搗衣聲"}, {"w": "倦宦", "m": "厭倦做官的人"}, {"w": "駸駸", "m": "急速"}, {"w": "東君", "m": "春神"}, {"w": "征驂", "m": "遠行的車馬"}], "questions": [{"n": 19, "qtype": "單選", "stem": "關於本闋詞的敘述，正確的是：", "options": {"A": "通篇傳達孤老無依、大限將至的悲涼", "B": "上片描寫秋夜清冷蕭索和羈旅獨居的悲愁", "C": "下片慨歎己身生涯坎坷，自責愧對妻兒子女", "D": "以蛩聲、鐘鼓聲、砧杵聲寄寓對家事、國事、天下事的關懷"}, "answer": "B", "explain": "答案(B)。上片寫黃昏煙林、鐘鼓、燭光、蟋蟀、搗衣聲，一片秋夜清冷，最後「驚動天涯倦宦」，帶出羈旅在外的愁苦，(B)正確。(A)詞中是感嘆年華老去、漂泊失意，沒有「孤老無依、大限將至」。(C)下片感嘆當年自負、如今漂泊、幽恨無人訴，沒有自責愧對妻兒。(D)蛩聲、砧杵聲是秋夜引發鄉愁的聲音，沒有寄託家國天下的關懷。", "skill": "詞的上下片分工：上片多寫景、下片多抒情；先分別概括，再對照選項。"}, {"n": 20, "qtype": "單選", "stem": "關於本闋詞的理解，不恰當的是：", "options": {"A": "「煙絡橫林，山沉遠照，邐迤黃昏鐘鼓」為詞人遠眺所見所聞", "B": "「燭映簾櫳，蛩催機杼，共苦清秋風露」描繪詞人與思婦共感淒風寒露之苦", "C": "「流浪征驂北道，客檣南浦」對比「當年酒狂自負」，營造失落之感", "D": "「明月」象徵國君，「幽恨無人晤語」表達作者懷才不遇的感傷"}, "answer": "D", "explain": "答案(D)。題目問「不恰當」。「明月曾知舊遊處」是說只有明月知道我從前遊歷的地方，明月是陪伴、見證的知己，不是象徵國君；「幽恨無人晤語」是孤獨無人可訴，不能直接解成懷才不遇。(A)煙林、遠山、黃昏鐘鼓是遠望所見所聞，恰當。(B)燭光、蟋蟀、秋風露，寫詞人與思婦同在清秋之夜受苦，恰當。(C)用如今北道南浦的漂泊，對比當年酒狂自負，營造失落，恰當。", "skill": "詩詞中的意象不要過度引申：沒有上下文支持時，『明月』多是思念、見證或陪伴，不要隨便解成國君。"}], "difficulty": "難", "label": "107學測", "year": 107, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc107-21", "exam": "xc107", "nums": [21, 22, 23, 24], "form": "題組", "img": "img/xc107-21.png", "source": "孫康宜〈揭開陶潛的面具〉（白話，引龔自珍、杜甫、陶潛詩）", "author": "孫康宜", "genre": "古典詩詞曲", "types": ["文意推論", "比較閱讀", "詩詞賞析"], "passage": "陶潛酷似臥龍豪，萬古潯陽松菊高。莫信詩人竟平淡，二分梁甫一分騷。（龔自珍〈己亥雜詩〉）\n陶潛避俗翁，未必能達道。觀其著詩集，頗亦恨枯槁。（杜甫〈遣興〉）\n顏生稱為仁，榮公言有道。屢空不獲年，長飢至於老。雖留後世名，一生亦枯槁……（陶淵明〈飲酒〉第十一首）\n嘲淵明，自嘲也。假一淵明為本身象贊。（浦起龍評杜甫〈遣興〉）\n子美之不甚喜陶詩，而恨其枯槁也。（胡應麟《詩藪》）", "translation": "龔自珍：陶潛很像臥龍諸葛亮那樣豪邁，在潯陽的松菊之間萬古崇高。不要相信詩人真的平淡，他的心裡有兩分〈梁甫吟〉、一分〈離騷〉。\n杜甫：陶潛是避開世俗的老翁，卻不一定能通達大道。看他的詩集，常常怨恨自己一生窮困。\n陶潛：顏回被稱為仁者，榮啟期被說是有道的人。顏回常常窮得一無所有又短命，榮啟期長期挨餓直到老。雖然留下後世的名聲，一生也是窮困潦倒。\n浦起龍：杜甫嘲笑淵明，其實是自嘲，借淵明來替自己畫像寫贊。\n胡應麟：杜甫不太喜歡陶詩，是嫌它枯槁（風格平淡）。", "keywords": [{"w": "臥龍", "m": "諸葛亮"}, {"w": "梁甫", "m": "〈梁甫吟〉，諸葛亮好吟此詩"}, {"w": "騷", "m": "屈原〈離騷〉"}, {"w": "枯槁", "m": "窮困潦倒；（被誤讀為）風格平淡"}, {"w": "屢空", "m": "常常窮得一無所有"}, {"w": "象贊", "m": "畫像與贊語"}], "questions": [{"n": 21, "qtype": "單選", "stem": "下列敘述，符合文中龔自珍對陶潛看法的是：", "options": {"A": "陶潛一生固窮守節，為傳統知識分子的典型", "B": "陶潛與屈原、諸葛亮相同，均懷有濟世之志", "C": "陶潛才德堪比諸葛亮，竟自甘於平淡，令人惋惜", "D": "陶詩風格平淡，實受〈梁甫吟〉、〈離騷〉影響"}, "answer": "B", "explain": "答案(B)。龔自珍說陶潛「酷似臥龍豪」，又說他「二分梁甫一分騷」——梁甫吟代表諸葛亮的經世抱負，離騷代表屈原的忠憤，意思是陶潛和屈原、諸葛亮一樣懷有濟世之志。(A)文中說龔自珍把陶潛看成「有出仕的凌雲之志」，不是強調固窮守節。(C)龔自珍說「莫信詩人竟平淡」，認為陶潛並不平淡，不是惋惜他甘於平淡。(D)「梁甫」「騷」是說陶潛的心志，不是說陶詩風格受它們影響。", "skill": "讀詩論先翻譯詩句：『莫信……竟平淡』是否定平淡，『二分……一分……』是比例組成，說的是內心成分。"}, {"n": 22, "qtype": "單選", "stem": "作者認為歷來批評家對杜甫〈遣興〉一詩，所產生的誤讀是：", "options": {"A": "以為杜甫嘲諷陶潛猶未能達道", "B": "以為杜甫批評陶潛的詩風枯槁", "C": "認為杜甫質疑陶潛的隱士形象", "D": "認為杜甫藉陶潛自嘲窮困潦倒"}, "answer": "B", "explain": "答案(B)。文章第三段說：批評家常把「枯槁」解作「風格上的平淡」，因此認定杜甫是在批評陶潛的詩風——這就是誤讀。作者認為「枯槁」其實是「窮困潦倒」。(A)(C)是杜甫原本的意思（質疑陶潛未能達道、質疑隱士形象），不是誤讀；(D)是浦起龍的解讀，作者認同。", "skill": "「誤讀」題：找文中「然而……誤讀……由於……」這段，被作者否定的那種理解就是答案。"}, {"n": 23, "qtype": "單選", "stem": "依據上文，作者所不認同的前人論述是：", "options": {"A": "杜甫對陶潛詩的詮釋", "B": "龔自珍對陶潛的評論", "C": "浦起龍對杜詩的詮釋", "D": "胡應麟對杜甫的評論"}, "answer": "D", "explain": "答案(D)。作者說「這種誤解導致明代學者胡應麟……以為『子美之不甚喜陶詩，而恨其枯槁也』」，明確指出胡應麟的說法是誤讀，所以不認同。(A)杜甫的詮釋作者是同意的（李華的解讀「很有理由」）；(B)龔自珍的看法作者只是引用說明；(C)浦起龍「嘲淵明，自嘲也」作者也採用。", "skill": "找作者態度：看作者引用每個人時用的評語——『很有理由』『便指出』是贊同，『誤解』『導致』是反對。"}, {"n": 24, "qtype": "單選", "stem": "上文認為「經典化的作者，是讀者反饋的產物」，圖像也是讀者反饋的一種形式。甲、乙二圖皆以陶潛的歸隱生活為背景，下列敘述，最無法從圖中獲悉的是：", "options": {"A": "甲圖藉「採菊東籬」、「見南山」表現陶潛的閒適", "B": "乙圖用飢餓難耐、流眼淚顛覆陶潛清貧自守的形象", "C": "甲圖描繪陶潛功成不居，乙圖則描繪陶潛樂極生悲", "D": "對陶潛形象的詮釋，甲圖重精神面，乙圖重物質面"}, "answer": "C", "explain": "答案(C)。題目問「最無法」從圖中看出的。甲圖陶潛在菊花籬邊、遠處有山，表現閒適，(A)看得出；乙圖陶潛看著飯碗流淚、肚子咕嚕叫，顛覆清貧自守的形象，(B)看得出；甲圖重精神、乙圖重物質，(D)看得出。(C)甲圖沒有任何「功成不居」的內容，乙圖是窮困挨餓，不是「樂極生悲」，所以最無法獲悉。", "skill": "圖文題：選項每一個描述都要在圖上找到對應的畫面；圖上看不到的抽象評價（功成不居）就是答案。"}], "difficulty": "中", "label": "107學測", "year": 107, "kind": "學測", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": "桃花源記"}, {"id": "xc107-27", "exam": "xc107", "nums": [27, 28, 29, 30], "form": "題組", "img": "img/xc107-27.png", "source": "南懷仁《坤輿圖說》（甲）；國家地理雜誌中文網（乙，白話）", "author": "南懷仁", "genre": "筆記小品", "types": ["比較閱讀", "寫作手法", "文意推論"], "passage": "利未亞州東北厄日多國産魚，名喇加多，約三丈餘。長尾，堅鱗甲，刀箭不能入。足有利爪，鋸牙滿口，性甚獰惡。色黄，口無舌，唯用上齶食物。入水食魚，登陸每吐涎于地，人畜踐之即仆，因就食之。見人遠則哭，近則噬。冬月則不食物，睡時嘗張口吐氣。", "translation": "非洲東北部的埃及出產一種魚，叫做喇加多（鱷魚），長三丈多。尾巴很長，鱗甲堅硬，刀箭都射不進去。腳有銳利的爪子，滿口像鋸子的牙齒，性情非常兇猛。顏色是黃的，口中沒有舌頭，只用上顎吃東西。下水吃魚，上岸時常把口水吐在地上，人或牲畜踩到就跌倒，牠就趁機把他們吃掉。看見人在遠處就哭，靠近了就咬。冬天不吃東西，睡覺時常常張開嘴吐氣。", "keywords": [{"w": "利未亞州", "m": "非洲"}, {"w": "厄日多", "m": "埃及"}, {"w": "喇加多", "m": "鱷魚"}, {"w": "涎", "m": "口水"}, {"w": "仆", "m": "跌倒"}, {"w": "噬", "m": "咬"}], "questions": [{"n": 27, "qtype": "單選", "stem": "下列關於甲文敘寫「喇加多」的分析，錯誤的是：", "options": {"A": "先談外形，再寫習性；習性再分「獵食」、「避敵」兩線敘寫", "B": "以「利爪」、「鋸牙」襯托「獰惡」，以「刀箭不能入」強化「堅鱗甲」特徵", "C": "以「入水」、「登陸」的活動範圍，描述其生活特性，也寫獵食對象甚廣", "D": "藉「吐涎于地」和「遠則哭，近則噬」二事揭露其獵食技倆"}, "answer": "A", "explain": "答案(A)。題目問「錯誤」的。甲文先寫外形（長尾、鱗甲、利爪、鋸牙），再寫習性，但習性寫的是獵食（入水食魚、吐涎、見人遠哭近噬）、冬天不吃、睡時張口，並沒有「避敵」這條線，所以(A)錯。(B)利爪鋸牙襯托獰惡、刀箭不能入強化鱗甲堅硬，正確。(C)入水、登陸都能獵食，對象有魚、人畜，正確。(D)吐涎使人畜跌倒、遠哭近噬，都是獵食手段，正確。", "skill": "分析寫作結構題：自己先把原文分段標出『寫什麼』，再對照選項說的分類，多出來的類別（避敵）就是陷阱。"}, {"n": 28, "qtype": "單選", "stem": "甲文「人畜踐之即仆」的鱷魚涎液，若依乙文的看法，最可能的分泌來源是：", "options": {"A": "哈氏腺", "B": "舌下腺", "C": "淚腺", "D": "鼻腺"}, "answer": "B", "explain": "答案(B)。「吐涎于地」的涎液是從嘴裡吐出來的；乙文說鹹水鱷、美洲鱷「鹽腺都位在舌下腺中，舌頭表面的孔洞會分泌出高鹽分的液體」，所以嘴裡的涎液最可能來自舌下腺。哈氏腺在眼睛瞬膜、淚腺和鼻腺是其他動物的鹽腺位置，都不是從嘴巴出來的。", "skill": "文白對讀：先確定甲文現象發生的『部位』（嘴巴），再到乙文找同一部位的說明。"}, {"n": 29, "qtype": "單選", "stem": "甲文謂鱷魚「見人遠則哭」，若依乙文的看法，其主要原因應是：", "options": {"A": "引誘獵物", "B": "排除鹽分", "C": "哀傷憐憫", "D": "潤滑眼睛"}, "answer": "D", "explain": "答案(D)。「見人遠則哭」是在陸地上流眼淚；乙文說「鱷魚通常在陸地待了一段時間後，位於瞬膜的哈氏腺便會分泌鹹液潤滑眼睛」，所以流淚主要是為了潤滑眼睛。(B)乙文說科學家後來發現排鹽的是舌下腺，不是眼睛；(A)(C)是傳說中的擬人說法，乙文沒有支持。", "skill": "注意乙文的「先前認為／後來發現」：被推翻的舊說法常被拿來當錯誤選項。"}, {"n": 30, "qtype": "單選", "stem": "乙文第二段列舉數種鱷魚，最主要是為了說明：", "options": {"A": "不同棲息地的鱷魚，鹽腺的效能也隨之有別", "B": "不同種類的鱷魚，鹽腺所在的位置也不相同", "C": "鱷魚鹽腺的位置，會隨棲地鹽分多寡而改變", "D": "鱷魚鹽腺的退化，係經過長時間的演化歷程"}, "answer": "A", "explain": "答案(A)。乙文第二段先說住在河口淺海的鹹水鱷、美洲鱷舌下鹽腺會排鹽；同屬的淡水鱷「效能略遜一籌」；淡水的短吻鱷科「排鹽效率奇差」甚至「完全不會排出鹽分」——列舉的目的是說明棲息地不同，鹽腺效能就不同。(B)這些鱷魚的鹽腺都在舌下，位置相同；(C)沒說位置會隨棲地改變；(D)沒有談演化歷程。", "skill": "「列舉的目的」題：把例子按順序排一排，看它們『哪一項在變』（棲地）、『哪一項跟著變』（效能），就是要說明的重點。"}], "difficulty": "中", "label": "107學測", "year": 107, "kind": "學測", "textcat": "科普文本", "textcat2": "", "linked_core": ""}, {"id": "xc107-31", "exam": "xc107", "nums": [31, 32], "form": "題組", "img": "img/xc107-31.png", "source": "《莊子‧德充符》", "author": "莊子", "genre": "經典語錄", "types": ["文意推論", "字詞解釋"], "passage": "惠子謂莊子曰：「人故无情乎？」莊子曰：「然。」惠子曰：「人而无情，何以謂之人？」莊子曰：「道與之貌，天與之形，惡得不謂之人？」惠子曰：「既謂之人，惡得无情？」莊子曰：「是非吾所謂情也。吾所謂无情者，言人之不以好惡內傷其身，常因自然而不益生也。」", "translation": "惠子對莊子說：「人本來就沒有情嗎？」莊子說：「對。」惠子說：「人如果沒有情，怎麼能叫做人？」莊子說：「道給了人容貌，天給了人形體，怎麼不能叫做人？」惠子說：「既然叫做人，怎麼能沒有情？」莊子說：「這不是我所說的情。我所說的無情，是說人不因為喜好和厭惡而在內心傷害自己的身體，常常順應自然，而不刻意去增益生命。」", "keywords": [{"w": "无", "m": "同「無」"}, {"w": "與", "m": "給予"}, {"w": "惡得", "m": "怎麼能"}, {"w": "好惡", "m": "喜好與厭惡"}, {"w": "益生", "m": "刻意增益生命"}], "questions": [{"n": 31, "qtype": "單選", "stem": "下列敘述，符合惠子、莊子二人對有情無情看法的是：", "options": {"A": "惠子：人的形貌乃根源於無情", "B": "惠子：人既可無情亦可以有情", "C": "莊子：不因情傷天性是謂無情", "D": "莊子：順自然而無情不利養生"}, "answer": "C", "explain": "答案(C)。莊子說「吾所謂无情者，言人之不以好惡內傷其身」——不讓喜怒好惡傷害自己，就是他說的無情，(C)正確。(A)說「人的形貌來自道與天」的是莊子，不是惠子，也沒說源於無情。(B)惠子認為人一定有情（「既謂之人，惡得无情」），沒說可以無情。(D)莊子主張「常因自然」，順應自然正是養生之道，不是不利養生。", "skill": "對話題：先標清楚每句話是誰說的，再整理雙方立場（惠子：人必有情；莊子：無情＝不以好惡傷身）。"}, {"n": 32, "qtype": "單選", "stem": "下列文句中的「與」，和上文「道與之貌」的「與」意思相同的是：", "options": {"A": "選賢「與」能，講信修睦", "B": "可「與」言而不與之言，失人", "C": "人知之者，其謂「與」埳井之蛙何異", "D": "既以為人，己愈有；既以「與」人，己愈多"}, "answer": "D", "explain": "答案(D)。「道與之貌」的「與」是「給予」。(D)「既以與人，己愈多」——拿去給別人，自己反而更多，也是「給予」。(A)「選賢與能」的「與」通「舉」，選拔；(B)「可與言」的「與」是「和、跟」；(C)「與埳井之蛙何異」的「與」也是「和」。", "skill": "「與」的常見義：給予（動詞）、和（介詞／連詞）、通『舉』、通『歟』（語氣）。後面直接接人並帶受詞時，多是『給予』。"}], "difficulty": "中", "label": "107學測", "year": 107, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc107-33", "exam": "xc107", "nums": [33, 34], "form": "題組", "img": "img/xc107-33.png", "source": "元結〈菊圃記〉", "author": "元結", "genre": "說理議論", "types": ["文意推論", "主旨寓意"], "passage": "舂陵俗不種菊，前時自遠致之，植於前庭牆下。及再來也，菊已無矣。徘徊舊圃，嗟嘆久之。誰不知菊也，芳華可賞，在藥品是良藥，為蔬菜是佳蔬。縱須地趨走，猶宜徙植修養，而忍蹂踐至盡，不愛惜乎！於戲！賢士君子自植其身，不可不慎擇所處。一旦遭人不愛重如此菊也，悲傷奈何！於是更為之圃，重畦植之。其地近宴息之堂，吏人不此奔走；近登望之亭，旌旄不此行列。縱參歌妓，菊非可惡之草；使有酒徒，菊為助興之物。為之作記，以託後人；並錄藥經，列於記後。", "translation": "舂陵的習俗不種菊花，我先前從遠方運來，種在前庭牆下。等我再來時，菊花已經沒有了。我在舊花圃前徘徊，嘆息了很久。誰不知道菊花呢？花朵芳香可以欣賞，在藥材中是好藥，當蔬菜是好菜。就算需要這塊地讓人走動，也應該移植照顧，怎麼忍心把它踩踏殆盡，不愛惜呢！唉！賢士君子安頓自身，不能不慎重選擇所處的地方。一旦遭到別人像對待這菊花一樣不愛惜，那該多悲傷啊！於是我重新為它闢了花圃，一畦一畦地種上。這地方靠近休息的廳堂，官吏不會在這裡奔走；靠近登高眺望的亭子，儀仗旗幟不會在這裡排列。即使有歌妓來，菊花也不是讓人討厭的草；假使有酒客，菊花還是助興的東西。我替它寫了這篇記，託付給後人；並抄錄藥經上的記載，附在記後面。", "keywords": [{"w": "致", "m": "運來、取得"}, {"w": "趨走", "m": "奔走、往來"}, {"w": "蹂踐", "m": "踐踏"}, {"w": "於戲", "m": "同「嗚呼」"}, {"w": "自植其身", "m": "安頓自己"}, {"w": "旌旄", "m": "旗幟，指儀仗"}], "questions": [{"n": 33, "qtype": "單選", "stem": "菊花在「前庭牆下」消失的原因，敘述最適當的是：", "options": {"A": "菊花不如良藥、佳蔬用途廣大，因此遭眾人鄙薄厭棄", "B": "菊花係遠方品種，移植舂陵而不服水土，致枯萎凋零", "C": "菊花栽植於人來人往之處，被踩踏蹂躪，因而凋枯萎謝", "D": "菊花形貌樸素，雖非可惡之草，但不受人喜愛而遭棄養"}, "answer": "C", "explain": "答案(C)。作者說「縱須地趨走，猶宜徙植修養，而忍蹂踐至盡」——前庭牆下是人來人往的地方，菊花被踩踏光了，所以(C)正確；後來他特地選在「吏人不此奔走」的地方重種，也可印證。(A)作者稱讚菊花「在藥品是良藥，為蔬菜是佳蔬」；(B)文中沒說不服水土；(D)菊花不是因為樣子樸素被丟棄。", "skill": "原因題：找原文中的感嘆或反問句（『而忍蹂踐至盡，不愛惜乎』），作者的情緒常直接點出原因。"}, {"n": 34, "qtype": "單選", "stem": "作者藉種植菊花而感悟處世之理，下列敘述最適當的是：", "options": {"A": "立身處世應具良禽擇木而棲的智慧", "B": "順境僅成就平凡而逆境可造就不凡", "C": "具備多元能力，可在競爭時代勝出", "D": "正直友可礪品格，酒肉交將招災禍"}, "answer": "A", "explain": "答案(A)。作者由菊花種錯地方而被踩死，感悟到「賢士君子自植其身，不可不慎擇所處」——要謹慎選擇安身之處，就像「良禽擇木而棲」。(B)文中沒有談順境逆境；(C)菊花用途多是在說它可貴，不是說多元能力能勝出；(D)文中的「酒徒」是說菊花可助興，沒有談交友。", "skill": "託物言志：找作者從物轉到人的那句話（常有『賢士君子』『人亦如是』），那句就是主旨。"}], "difficulty": "易", "label": "107學測", "year": 107, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc107-35", "exam": "xc107", "nums": [35], "form": "單題", "img": "img/xc107-35.png", "source": "〈孔雀東南飛〉、《孟子》、諸葛亮〈出師表〉、白居易〈琵琶行并序〉", "author": "多家", "genre": "其他", "types": ["文化常識", "字詞解釋"], "passage": "(A)一心抱區區，懼君不識察（〈孔雀東南飛〉）\n(B)鄰國之民不加少，寡人之民不加多，何也（《孟子‧梁惠王上》）\n(C)愚以為營中之事，悉以咨之，必能使行陣和睦（諸葛亮〈出師表〉）\n(D)中也養不中，才也養不才，故人樂有賢父兄也（《孟子‧離婁下》）\n(E)余出官二年，恬然自安，感斯人言，是夕始覺有遷謫意（白居易〈琵琶行并序〉）", "translation": "(A)我一心懷著誠摯的情意，只怕你不能體察。(B)鄰國的百姓沒有減少，我的百姓沒有增加，為什麼呢？(C)我認為軍中的事，都拿去問他，一定能使軍隊和睦。(D)品德好的人教養品德不好的人，有才能的人教養沒有才能的人，所以人們樂於有賢能的父兄。(E)我被貶官兩年，心情平靜安適，被這個人的話觸動，這天晚上才感覺到被貶謫的心情。", "keywords": [{"w": "區區", "m": "誠摯的心意"}, {"w": "寡人", "m": "寡德之人，君王謙稱"}, {"w": "愚", "m": "自謙之詞，我"}, {"w": "不才", "m": "沒有才能的人"}, {"w": "出官", "m": "被貶出京城做官"}], "questions": [{"n": 35, "qtype": "多選", "stem": "下列文句「」內的詞，屬於謙詞用法的是：", "options": {"A": "一心抱「區區」，懼君不識察", "B": "鄰國之民不加少，「寡人」之民不加多，何也", "C": "「愚」以為營中之事，悉以咨之，必能使行陣和睦", "D": "中也養不中，才也養「不才」，故人樂有賢父兄也", "E": "「余」出官二年，恬然自安，感斯人言，是夕始覺有遷謫意"}, "answer": "BC", "explain": "答案(B)(C)。(B)「寡人」是寡德之人，國君的謙稱。(C)「愚」是臣子對君主的謙稱，等於「我」。(A)「區區」在此是「誠摯的心意」，不是謙詞。(D)「不才」指沒有才能的人（受教的對象），不是說話者自稱。(E)「余」是一般的第一人稱「我」，沒有謙抑意味。", "skill": "謙詞要符合兩個條件：①指說話者自己、②帶有貶低自己的意思。只是『我』（余、吾）不算；指別人的也不算。"}], "difficulty": "中", "label": "107學測", "year": 107, "kind": "學測", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "出師表"}, {"id": "xc107-36", "exam": "xc107", "nums": [36], "form": "單題", "img": "img/xc107-36.png", "source": "〈諫太宗十思疏〉、〈蘭亭集序〉、〈諫逐客書〉、〈工之僑獻琴〉、〈左忠毅公軼事〉、〈勞山道士〉、〈典論論文〉、〈北投硫穴記〉等", "author": "多家", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)仁者播其惠，信者效其忠／足以極視聽之娛，信可樂也\n(B)以此伏事公卿，無不寵愛／遂散六國之從，使之西面事秦\n(C)工之僑以歸，謀諸漆工，作斷紋焉／持五十金，涕泣謀於禁卒，卒感焉\n(D)虎嘯風生，龍吟雲萃，固非偶然也／道士笑曰：我固謂不能作苦，今果然\n(E)常人貴遠賤近，向聲背實／始悟向之倒峽崩崖，轟耳不輟者，是硫穴沸聲也", "translation": "(A)仁德的人施予恩惠，守信的人獻出忠誠／足以盡情享受視聽的樂趣，實在快樂啊。(B)憑這個事奉公卿，沒有不寵愛的／於是拆散六國的合縱，使他們向西事奉秦國。(C)工之僑帶回家，和漆匠商量，做出斷紋／拿著五十兩銀子，哭著和看守的獄卒商量，獄卒被感動了。(D)虎嘯就起風，龍吟就聚雲，本來就不是偶然的／道士笑說：我本來就說你吃不了苦，現在果然如此。(E)一般人重視遠的、輕視近的，嚮往名聲而背棄實際／這才明白先前那如山峽崩塌、不停震耳的聲音，是硫穴沸騰的聲音。", "keywords": [{"w": "信", "m": "守信的人；確實"}, {"w": "事", "m": "事奉"}, {"w": "謀", "m": "商量"}, {"w": "固", "m": "本來"}, {"w": "向", "m": "嚮往；先前"}], "questions": [{"n": 36, "qtype": "多選", "stem": "下列各組文句「」內的詞，前後意義相同的是：", "options": {"A": "仁者播其惠，「信」者效其忠／足以極視聽之娛，「信」可樂也", "B": "以此伏「事」公卿，無不寵愛／遂散六國之從，使之西面「事」秦", "C": "工之僑以歸，「謀」諸漆工，作斷紋焉／持五十金，涕泣「謀」於禁卒，卒感焉", "D": "虎嘯風生，龍吟雲萃，「固」非偶然也／道士笑曰：我「固」謂不能作苦，今果然", "E": "常人貴遠賤近，「向」聲背實／始悟「向」之倒峽崩崖，轟耳不輟者，是硫穴沸聲也"}, "answer": "BCD", "explain": "答案(B)(C)(D)。(B)兩個「事」都是「事奉」。(C)兩個「謀」都是「商量」：和漆工商量、和獄卒商量。(D)兩個「固」都是「本來」。(A)前「信者」是「守信的人」，後「信可樂也」是「確實」。(E)前「向聲背實」是「嚮往、趨向」，後「向之」是「先前」。", "skill": "「向」在文言常見三義：嚮往、面向、先前（向之＝先前的）；看到『向之＋名詞』多半是『先前的』。"}], "difficulty": "中", "label": "107學測", "year": 107, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "諫逐客書、典論論文、蘭亭集序、諫太宗十思疏、郁離子選、勞山道士、左忠毅公軼事"}, {"id": "xc107-39", "exam": "xc107", "nums": [39], "form": "單題", "img": "img/xc107-39.png", "source": "杜審言〈和晉陵陸丞早春遊望〉、王勃〈送杜少府之任蜀州〉", "author": "杜審言、王勃", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀"], "passage": "甲、獨有宦遊人，偏驚物候新。雲霞出海曙，梅柳渡江春。淑氣催黃鳥，晴光轉綠蘋。忽聞歌古調，歸思欲霑巾。（杜審言〈和晉陵陸丞早春遊望〉）\n乙、城闕輔三秦，風煙望五津。與君離別意，同是宦遊人。海內存知己，天涯若比鄰。無為在歧路，兒女共霑巾。（王勃〈送杜少府之任蜀州〉）", "translation": "甲、只有在外做官的人，特別容易被節候景物的變化所驚動。雲霞從海上升起，天亮了；梅花柳樹渡過長江，春天到了。溫暖的春氣催促黃鶯鳴叫，晴朗的陽光讓水中浮萍轉綠。忽然聽見你吟唱古雅的曲調，思鄉之情讓我幾乎淚濕衣巾。\n乙、三秦之地護衛著長安城，遠望蜀地五津只見風煙一片。和你離別的心情，因為我們都是在外做官的人。四海之內只要有知己，即使遠在天涯也像鄰居一樣近。不要在分手的岔路上，像小兒女一樣哭濕手巾。", "keywords": [{"w": "宦遊人", "m": "在外做官的人"}, {"w": "物候", "m": "節候景物"}, {"w": "淑氣", "m": "溫和的春氣"}, {"w": "城闕", "m": "城樓，指長安"}, {"w": "霑巾", "m": "淚濕手巾"}], "questions": [{"n": 39, "qtype": "多選", "stem": "關於下列甲、乙二詩的解讀，正確的是：甲、獨有宦遊人，偏驚物候新。雲霞出海曙，梅柳渡江春。淑氣催黃鳥，晴光轉綠蘋。忽聞歌古調，歸思欲霑巾。（杜審言〈和晉陵陸丞早春遊望〉）乙、城闕輔三秦，風煙望五津。與君離別意，同是宦遊人。海內存知己，天涯若比鄰。無為在歧路，兒女共霑巾。三秦：陝西關中一帶。（王勃〈送杜少府之任蜀州〉）五津：岷江中五個渡口。", "options": {"A": "甲詩藉由「淑氣催黃鳥，晴光轉綠蘋」，點出詩題的「早春」", "B": "乙詩藉由「城闕輔三秦，風煙望五津」，照應詩題的地理空間", "C": "二詩題材不盡相同，甲詩側重自然景物，乙詩則偏向人生際遇", "D": "二詩作者均因長期在外宦遊，故離愁別緒觸景而生，哀傷難抑", "E": "二詩皆以思鄉作結，且均藉「霑巾」抒寫遊子落葉歸根的期望"}, "answer": "ABC", "explain": "答案(A)(B)(C)。(A)黃鳥鳴、綠蘋生，都是早春景象，點出「早春」。(B)「城闕輔三秦」是送別的長安，「風煙望五津」是杜少府要去的蜀州，照應題目中的地點。(C)甲詩多寫春天景物，乙詩寫友情與人生聚散，題材不同。(D)乙詩是送朋友赴任，態度豁達，勸對方不要哭，並非「哀傷難抑」。(E)乙詩結尾是勸勉不要像兒女般哭泣，不是思鄉，也沒有落葉歸根的期望。", "skill": "兩首詩比較時，特別注意結尾句的情緒：同樣是『霑巾』，甲是真的想哭，乙是『無為』——不要哭，意思相反。"}], "difficulty": "中", "label": "107學測", "year": 107, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc107-40", "exam": "xc107", "nums": [40], "form": "單題", "img": "img/xc107-40.png", "source": "詠物詩（李嶠〈風〉等）", "author": "多家", "genre": "古典詩詞曲", "types": ["詩詞賞析", "典故出處"], "passage": "(A)去來固無跡，動息如有情。日落山水靜，為君起松聲\n(B)不是人間種，移從月窟來。廣寒香一點，吹得滿山開\n(C)春紅始謝又秋紅，息國亡來入楚宮。應是蜀冤啼不盡，更憑顏色訴西風\n(D)史氏只應歸道直，江淹何獨偶靈通。班超握管不成事，投擲翻從萬里戎\n(E)千形萬象竟還空，映水藏山片復重。無限旱苗枯欲盡，悠悠閒處作奇峰", "translation": "(A)來去本來沒有蹤跡，動與停好像有感情。太陽下山、山水寂靜時，為你吹響松濤聲。(B)不是人間的品種，是從月宮移植來的。廣寒宮的一點香氣，吹得滿山都開花。(C)春天的紅花剛謝，秋天又開紅花；就像息國滅亡後息夫人被納入楚宮。應該是蜀帝的冤魂啼叫不完，又藉著花的顏色向西風訴說。(D)史官的筆應該用來秉筆直書，江淹為什麼偏偏夢到它而有靈感？班超拿著它成不了事，丟下它反而去萬里從軍。(E)變化出千萬種形象最後還是一場空，映在水中、藏住山頭，一片又一片。無數乾旱的禾苗快要枯死了，它卻在閒處悠悠地堆成奇特的山峰。", "keywords": [{"w": "月窟", "m": "月宮"}, {"w": "廣寒", "m": "廣寒宮，月宮"}, {"w": "蜀冤", "m": "蜀帝杜宇化為杜鵑啼血的傳說"}, {"w": "江淹", "m": "傳說夢見神人收回五色筆而才盡"}, {"w": "班超", "m": "投筆從戎"}], "questions": [{"n": 40, "qtype": "多選", "stem": "下列詩句所歌詠的對象，正確的是：", "options": {"A": "去來固無跡，動息如有情。日落山水靜，為君起松聲─雨", "B": "不是人間種，移從月窟來。廣寒香一點，吹得滿山開─桂", "C": "春紅始謝又秋紅，息國亡來入楚宮。應是蜀冤啼不盡，更憑顏色訴西風─楓", "D": "史氏只應歸道直，江淹何獨偶靈通。班超握管不成事，投擲翻從萬里戎─筆", "E": "千形萬象竟還空，映水藏山片復重。無限旱苗枯欲盡，悠悠閒處作奇峰─雲"}, "answer": "BDE", "explain": "答案(B)(D)(E)。(B)月窟、廣寒香，月宮有桂樹，是桂花。(D)史官秉筆直書、江淹夢筆、班超投筆從戎，都是「筆」的典故。(E)千變萬化、映水藏山、不為旱苗降雨卻在空中堆成奇峰，是雲。(A)無形跡、動靜如有情、吹起松聲——是「風」，不是雨。(C)蜀帝冤魂化杜鵑鳥啼血，「更憑顏色訴西風」——詠的應是杜鵑花，不是楓。", "skill": "詠物詩找『專屬特徵』與『典故』：起松聲→風；月宮廣寒→桂；蜀帝啼血→杜鵑；夢筆、投筆→筆。"}], "difficulty": "中", "label": "107學測", "year": 107, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk107-3", "exam": "zk107", "nums": [3], "form": "單題", "img": "img/zk107-3.png", "source": "韓愈〈師說〉、李斯〈諫逐客書〉、魏徵〈諫太宗十思疏〉、鄭用錫〈勸和論〉", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "論辨體", "m": "說明道理、辨析是非的文章"}, {"w": "奏疏體", "m": "臣子上給君王的文書，如書、疏、表"}, {"w": "注疏", "m": "解釋經書的文字"}, {"w": "詔令體", "m": "君王對臣民下達的文書"}], "questions": [{"n": 3, "qtype": "單選", "stem": "下列各篇內容與其所屬文體，敘述最適當的是：", "options": {"A": "〈師說〉：韓愈追述儒道先師，屬探究事物本源的論辨體", "B": "〈諫逐客書〉：李斯揣摩秦王心理，陳述逐客之弊，屬奏疏體", "C": "〈諫太宗十思疏〉：魏徵逐一評述太宗所提的十種治道，屬注疏體", "D": "〈勸和論〉：鄭用錫為避免械鬥，代官府勸導百姓，屬上對下的詔令體"}, "answer": "B", "explain": "(B)李斯是臣子，寫給秦王的「書」，從秦國利益出發說服秦王收回逐客令，屬於奏疏（奏議）類，正確。(A)〈師說〉是論說從師的重要，批評當時恥於從師的風氣，不是追述儒家先師；而且是「說」體，以議論為主，並非「探究事物本源」的「原」體。(C)「十思」是魏徵自己提出、勸太宗要思考的十件事，不是太宗提的；「疏」是臣子給君王的奏疏，不是解釋經書的注疏。(D)鄭用錫是以地方士紳身分寫文章勸大家和睦、停止械鬥，屬於論說文；不是代官府發布，更不是皇帝的詔令。", "skill": "文體題記住兩件事：作者和讀者是什麼關係（臣對君→奏議）、文章目的是什麼（說理→論說），再核對內容細節。"}], "difficulty": "中", "label": "107指考", "year": 107, "kind": "指考", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "諫逐客書、師說、諫太宗十思疏、勸和論"}, {"id": "zk107-4", "exam": "zk107", "nums": [4], "form": "單題", "img": "img/zk107-4.png", "source": "連橫《雅堂文集‧詩薈餘墨》", "author": "連橫", "genre": "說理議論", "types": ["文意推論", "文化常識"], "passage": "詩有別才，不必讀書，此欺人語爾。少陵為詩中宗匠，猶曰：「讀書破萬卷，下筆如有神」，今人讀過一本《香草箋》，便欲作詩，出而應酬，何其容易！余意欲學詩者，經史雖不能讀破，亦須略知二、三，然後取唐人名家全集讀之，沉浸穠郁，含英咀華，俟有所得。乃有所得，乃可旁及，自不至紊亂無序，而下筆可觀矣。", "translation": "說寫詩需要特別的才華、不必讀書，這是騙人的話。杜甫是詩壇的大師，還說「讀書破萬卷，下筆如有神」；現在的人讀過一本《香草箋》，就想寫詩，拿出去應酬，多麼輕率啊！我認為想學詩的人，經書史書雖然不能讀透，也要略懂一些，然後拿唐代名家的全集來讀，沉浸在濃郁的詩味中，細細品味其中的精華，等到有所收穫。有了收穫，才可以廣泛涉獵其他作品，自然不會雜亂沒有條理，寫出來的詩也就值得一看了。", "keywords": [{"w": "別才", "m": "特殊的才能"}, {"w": "少陵", "m": "杜甫，號少陵野老"}, {"w": "含英咀華", "m": "細細品味文章的精華"}, {"w": "俟", "m": "等待"}, {"w": "旁及", "m": "廣泛涉及其他"}], "questions": [{"n": 4, "qtype": "單選", "stem": "連橫認為學詩須讀書以立根基，下列選項的閱讀次第，符合文中觀點的是：", "options": {"A": "香草箋→王右丞集→詩經", "B": "詩經→黃山谷詩集→香草箋", "C": "杜工部集→左傳→王右丞集", "D": "左傳→杜工部集→黃山谷詩集"}, "answer": "D", "explain": "連橫說的順序有三步：先「經史」略知二三 → 再讀「唐人名家全集」 → 有所得後才「旁及」其他。(D)《左傳》是經史，《杜工部集》是唐代杜甫的全集，《黃山谷詩集》是宋代黃庭堅的作品，屬於後來的旁及，完全符合。(A)一開始就讀《香草箋》，正是連橫批評的做法。(B)讀完經書直接跳到宋人黃山谷，略過唐人名家，最後還讀《香草箋》，不合。(C)先讀唐人杜甫再讀《左傳》，把經史放到後面，順序顛倒。", "skill": "把文中「然後、乃可」等表示順序的詞圈起來，整理成步驟，再一一對照選項的先後。"}], "difficulty": "易", "label": "107指考", "year": 107, "kind": "指考", "textcat": "延伸", "textcat2": "學術文本", "linked_core": "臺灣通史序"}, {"id": "zk107-5", "exam": "zk107", "nums": [5], "form": "單題", "img": "img/zk107-5.png", "source": "羅貫中《三國演義》第57回", "author": "羅貫中", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "早有人報到許昌，言劉備有諸葛亮、龐統為謀士，招軍買馬，積草屯糧，連結東吳，早晚必興兵北伐。曹操聞之，遂聚眾謀士商議南征。荀攸進曰：「周瑜新死，可先取孫權，次攻劉備。」操曰：「我若遠征，恐馬騰來襲許都。前在赤壁之時，軍中有訛言，亦傳西涼入寇之事，今不可不防也。」荀攸曰：「以愚所見，不若降詔，加馬騰為征南將軍，使討孫權，誘入京師，先除此人，則南征無患矣。」操大喜。", "translation": "早就有人報告到許昌，說劉備有諸葛亮、龐統當謀士，招兵買馬，囤積糧草，又聯合東吳，早晚一定會出兵北伐。曹操聽了，就召集謀士商議南征。荀攸建議說：「周瑜剛死，可以先攻取孫權，再攻打劉備。」曹操說：「我如果遠征，怕馬騰來襲擊許都。之前在赤壁時，軍中就有謠言，也傳說西涼兵要來進犯，現在不能不防。」荀攸說：「依我看，不如下詔書，封馬騰為征南將軍，讓他去討伐孫權，藉此把他騙進京城，先除掉這個人，南征就沒有後顧之憂了。」曹操非常高興。", "keywords": [{"w": "訛言", "m": "謠言"}, {"w": "入寇", "m": "入侵"}, {"w": "降詔", "m": "頒下詔書"}], "questions": [{"n": 5, "qtype": "單選", "stem": "依據下文，關於曹操的想法，敘述最適當的是：", "options": {"A": "欲採荀攸建議，趁孫權陣營發生變故時南征", "B": "知馬騰有反意，防他趁曹軍南征時攻取西涼", "C": "有意自孫權陣營招降馬騰，再使之討伐孫權", "D": "同意荀攸之計，誘馬騰與孫權互鬥進而兩傷"}, "answer": "A", "explain": "(A)荀攸說「周瑜新死，可先取孫權」，曹操本來就在商議南征，只是擔心馬騰，可見他想趁東吳失去周瑜這個變故時出兵，正確。(B)曹操怕的是馬騰「來襲許都」（自己的根據地），而且西涼本來就是馬騰的地盤，不是「攻取西涼」。(C)馬騰是西涼的勢力，不是孫權陣營的人，也沒有「招降」。(D)荀攸的計策是用討伐孫權當藉口把馬騰「誘入京師，先除此人」，不是讓他和孫權互鬥。", "skill": "人物「想法」題，要找他自己說的話（操曰）與他的反應（操大喜），再核對選項中的地名、人物關係有沒有被調包。"}], "difficulty": "易", "label": "107指考", "year": 107, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk107-8", "exam": "zk107", "nums": [8, 9], "form": "題組", "img": "img/zk107-8.png", "source": "余蓮《淡之頌》（改寫）；第9題選項引左思〈詠史〉、屈原〈漁父〉、陸游〈書憤〉、蘇轍（篇名待查）", "author": "余蓮", "genre": "說理議論", "types": ["文意推論", "比較閱讀"], "passage": "（第9題選項）\n(A)鉛刀貴一割，夢想騁良圖。左眄澄江湘，右盼定羌胡。\n(B)新沐者必彈冠，新浴者必振衣，安能以身之察察，受物之汶汶者乎？\n(C)早歲那知世事艱，中原北望氣如山。樓船夜雪瓜洲渡，鐵馬秋風大散關。\n(D)當憂則憂，遇喜則喜，忽然憂樂兩忘，則隨所遇而皆適，未嘗有擇於其間。", "translation": "(A)鈍刀也希望能派上一次用場，我夢想施展遠大的計畫：向左看平定江湘，向右看平定羌胡。\n(B)剛洗過頭的人一定要彈掉帽子上的灰，剛洗過澡的人一定要抖掉衣服上的塵土，怎麼能讓乾淨的身體，沾染外界的污濁呢？\n(C)年輕時哪知道世事艱難，北望中原，收復失土的氣概像山一樣。曾在雪夜乘著戰船守瓜洲渡，在秋風中騎著戰馬駐守大散關。\n(D)該憂愁時就憂愁，遇到喜事就歡喜，忽然間把憂和樂都忘了，那麼不管遇到什麼都能自在，從來不在其中挑選。", "keywords": [{"w": "鉛刀", "m": "鈍刀，作者自謙"}, {"w": "眄", "m": "斜看"}, {"w": "察察", "m": "潔白乾淨"}, {"w": "汶汶", "m": "污濁"}, {"w": "適", "m": "自在、舒適"}], "questions": [{"n": 8, "qtype": "單選", "stem": "依據文意，最符合文中觀點的敘述是：", "options": {"A": "退隱閒逸，能使人心境平淡，體驗人生百態進而陶鑄美德", "B": "保持彈性，抱持英雄主義者能順時而為，與世界脈動同步", "C": "不偏不執，成就性格的完整性，能因應變化而不偏離常道", "D": "博採眾長，虛心接受不同意見，可有效處理各種緊急情況"}, "answer": "C", "explain": "文章說「淡」讓人不往任何一方突出、不陷溺於任何一種美德，所以性格完整、能隨情境應變，最後說天道「看起來經常變化，卻永遠不偏移」，就是(C)。(A)文中說聖人可以出仕也可以退隱，不是靠退隱才平淡。(B)作者說最理想的「不是英雄主義式的投入」，所以抱持英雄主義者不符。(D)文中的「虛待」是心態上保持空靈，不是虛心接受別人意見。", "skill": "抽象論述文，抓作者用「不是……而是……」強調的句子，那就是觀點核心。"}, {"n": 9, "qtype": "單選", "stem": "下列文句，最符合文中「平淡」境界的是：", "options": {"A": "鉛刀貴一割，夢想騁良圖。左眄澄江湘，右盼定羌胡", "B": "新沐者必彈冠，新浴者必振衣，安能以身之察察，受物之汶汶者乎", "C": "早歲那知世事艱，中原北望氣如山。樓船夜雪瓜洲渡，鐵馬秋風大散關", "D": "當憂則憂，遇喜則喜，忽然憂樂兩忘，則隨所遇而皆適，未嘗有擇於其間"}, "answer": "D", "explain": "文中的「平淡」是不偏執某一方向，隨所處情境自然應變。(D)該憂就憂、該喜就喜，最後憂樂兩忘，遇到什麼都自在，「未嘗有擇」就是不偏執，最符合。(A)左思一心想建功立業、平定天下，是強烈的英雄主義投入。(B)屈原堅持清白、不肯同流合污，是把「潔身自好」這種美德推到極致，正是作者說的「陷溺在某一種美德」。(C)陸游回憶年輕時收復中原的豪情，也是強烈投入的英雄情懷。", "skill": "把文言選項用一個詞定性（建功、潔身、豪情、隨遇而安），再拿去和白話文章的核心概念比對。"}], "difficulty": "中", "label": "107指考", "year": 107, "kind": "指考", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "zk107-13", "exam": "zk107", "nums": [13, 14, 15], "form": "題組", "img": "img/zk107-13.png", "source": "甲文為白話說明；乙表引《東觀漢記》、《冊府元龜》、孟元老《東京夢華錄》", "author": "", "genre": "其他", "types": ["文意推論", "比較閱讀"], "passage": "漢：（漢光武帝）後之長安，受《尚書》於中大夫廬江許子威。資用乏，與同舍生韓子合錢買驢，令從者僦，以給諸公費。（《東觀漢記》）\n唐：京兆府奏：兩京之間多有百姓僦驢，俗謂之驛驢，往來甚速，有同驛騎。犯罪之人因茲奔竄，臣請禁絕。從之。尋又不行。（《冊府元龜》）\n宋：若凶事出殯，自上而下，凶肆各有體例。如方相、車轝、結絡、綵帛，皆有定價，不須勞力。尋常出街市幹事，稍似路遠倦行，逐坊巷橋市，自有假賃鞍馬者，不過百錢。（《東京夢華錄》）", "translation": "漢：漢光武帝後來到長安，跟中大夫廬江人許子威學《尚書》。錢不夠用，就和同宿舍的韓子合資買驢，讓隨從把驢租出去，賺錢來支付大家的開銷。\n唐：京兆府上奏說：長安、洛陽兩京之間有很多百姓出租驢子，俗稱「驛驢」，往來非常快，和官方的驛馬一樣。犯罪的人因此逃竄，請求禁止。皇帝同意了。不久又不執行了。\n宋：如果辦喪事出殯，從上到下，喪葬店各有一套規矩。像開道的方相、靈車、結彩、綵帛，都有固定價格，不必自己費力。平常上街辦事，如果路有點遠走累了，各個街坊巷口橋邊市場，自然有出租鞍馬的，不超過一百錢。", "keywords": [{"w": "僦", "m": "租賃"}, {"w": "資用乏", "m": "錢財不夠用"}, {"w": "尋", "m": "不久"}, {"w": "凶肆", "m": "辦喪事的店鋪"}, {"w": "方相", "m": "出喪時在隊伍前開道驅鬼的神像"}, {"w": "假賃", "m": "出租"}], "questions": [{"n": 13, "qtype": "單選", "stem": "依據甲文，關於「共享經濟」的敘述，最適當的是：", "options": {"A": "資源的「所有權」與「使用權」脫勾", "B": "資源提供者分享閒置資源，不宜收取報酬", "C": "第一類型與第二類型的區別，在於科技平臺素質的良莠", "D": "第二類型有違共享經濟初衷，但資源提供者有損失時，可獲平臺業者賠償"}, "answer": "A", "explain": "(A)定義說「有償讓渡資源使用權給他人」，東西還是自己的（所有權），只是把使用權租出去，兩者分開，正確。(B)定義明說「有償」，可以收錢。(C)兩類的區別是「個人閒置資源共享」與「標準化的商業資源共享」，良莠不齊指的是提供者的素質，不是平臺。(D)文中說平臺與提供者沒有勞雇關係，提供者可能「自行承擔損失風險」，不會獲得賠償。", "skill": "定義題回到第一段的定義句，逐字對照選項中的關鍵詞（有償、使用權）。"}, {"n": 14, "qtype": "單選", "stem": "依據乙表，關於「古代租賃」的敘述，最適當的是：", "options": {"A": "漢代從事租賃業的門檻頗高，貴族富豪方能參與", "B": "唐代驢子租賃市場活絡，因影響治安而遭長期禁絕", "C": "宋代喪葬業可按不同需求提供租賃服務，而鞍馬出租價格親民", "D": "歷代租賃業均只有個人對個人的模式，沒有商家對個人的模式"}, "answer": "C", "explain": "(C)宋代喪葬店「各有體例」，方相、車轝等「皆有定價」，可依需要租用；街上租鞍馬「不過百錢」，價格便宜，正確。(A)漢光武帝當時是缺錢的學生，和同學合買一頭驢出租，可見門檻不高。(B)唐代確實因犯人逃竄而奏請禁絕，但「尋又不行」——不久禁令就不執行了，不是長期禁絕。(D)宋代的「凶肆」就是商家，屬於商家對個人的模式。", "skill": "注意文言的時間副詞「尋」（不久），它常常是翻轉結論的關鍵字。"}, {"n": 15, "qtype": "單選", "stem": "綜合甲文、乙表，關於「共享經濟」與「古代租賃」的比較，敘述最適當的是：", "options": {"A": "共享經濟：重視閒置資源的流通與再利用／古代租賃：重視私有財產的廉讓與公益化", "B": "共享經濟：供需市場大，獲取資源極容易／古代租賃：供需市場小，獲取資源費心力", "C": "共享經濟：品質精良、服務標準化為訴求／古代租賃：價格透明、產品多樣化為訴求", "D": "共享經濟：供需雙方可經由網路平臺媒合／古代租賃：租賃交易須透過實際接觸完成"}, "answer": "D", "explain": "(D)甲文說共享經濟靠手機與「第三方創建的媒合平臺」；乙表的古代租賃都是直接找人租驢、到店裡或街口租馬，必須面對面完成，正確。(A)古代租賃也要收錢（不過百錢），不是把私產廉讓做公益。(B)唐代驢子租賃「多有」「往來甚速」、宋代「自有假賃鞍馬者」，看不出市場小、取得困難；甲文也沒說「極容易」。(C)甲文說提供者「良莠不齊」，標準化只是第二類型的發展，不能說共享經濟整體以品質精良為訴求。", "skill": "比較表格題要兩欄都檢查，只要一邊說錯就整個選項錯。"}], "difficulty": "中", "label": "107指考", "year": 107, "kind": "指考", "textcat": "生活情境文本", "textcat2": "學術文本", "linked_core": ""}, {"id": "zk107-16", "exam": "zk107", "nums": [16, 17, 18, 19], "form": "題組", "img": "img/zk107-16.png", "source": "鄭毓瑜〈由修禊事論蘭亭詩、蘭亭序「達」與「未達」的意義〉（改寫）；文中引王羲之〈蘭亭集序〉", "author": "鄭毓瑜", "genre": "說理議論", "types": ["文意推論", "主旨寓意", "比較閱讀"], "passage": "（文中引用〈蘭亭集序〉語句）流觴曲水／仰觀俯察／暢敘幽情／遊目騁懷／因寄所託，放浪形骸之外／欣於所遇，暫得於己，快然自足，不知老之將至／及其所之既倦，情隨事遷，感慨係之矣／況修短隨化，終期於盡／死生亦大矣，豈不痛哉／每覽昔人興感之由，若合一契／固知一死生為虛誕，齊彭殤為妄作／後之視今，亦猶今之視昔／雖世殊事異，所以興懷，其致一也", "translation": "引曲水讓酒杯漂流飲酒／抬頭看天、低頭看萬物／盡情抒發內心的情懷／放眼遠望、舒展胸懷／寄託心志於外物，不拘形跡、放縱自在／對所遇到的事物感到高興，暫時自得，快樂滿足，竟不知道衰老將要來臨／等到對所追求的事物厭倦了，心情隨著事物改變，感慨就隨之而來／何況壽命長短聽憑造化，終究要走到盡頭／死生是件大事啊，怎能不痛心／每次看到古人產生感慨的原因，都和我的感受像符契一樣吻合／這才知道把死和生看成一樣是荒誕的，把長壽和短命看成相同是胡說／後人看今天，也就像今天的人看從前一樣／即使時代不同、事情不同，但引發感慨的原因，道理是一樣的。", "keywords": [{"w": "修禊", "m": "三月上巳在水邊洗濯以除不祥的習俗"}, {"w": "彭殤", "m": "彭祖（長壽）與殤子（早夭）"}, {"w": "齊彭殤", "m": "把長壽和短命看成一樣，莊子思想"}, {"w": "一死生", "m": "把死和生看成一樣"}, {"w": "若合一契", "m": "像符契相合一樣完全一致"}], "questions": [{"n": 16, "qtype": "單選", "stem": "依據上文，〈蘭亭序〉由「不知老之將至」的大樂，翻轉而為「死生亦大矣」的至痛，關鍵在於：", "options": {"A": "齊契玄同的欣喜，唯在逍遙山林、棄絕塵俗的豁達中方能獲致", "B": "言不盡意，蘭亭勝景與天人合契的同情共感，難以用文字重現", "C": "重覽當日詩作，賞心樂事已難踪跡，故知種種美好終究難永存", "D": "欲以放浪形骸之外的任性灑脫，逃避死滅的束縛，而終不可得"}, "answer": "C", "explain": "文章說序文後半「換由事過境遷、讀者閱覽的角度發言」：重讀當日的詩，「感慨樂事難繼，僅能由徒留的字跡詩痕，緬懷當日」，快樂不再，才體悟人「終期於盡」，於是嘆「死生亦大」，所以是(C)。(A)是前半段描寫群賢的意向，不是翻轉的關鍵。(B)文中沒有說文字無法表達勝景。(D)文章沒說王羲之想靠放浪形骸逃避死亡。", "skill": "問「翻轉的關鍵」，就去找文中出現轉折的段落開頭（如「序文後半，則換由……」）。"}, {"n": 17, "qtype": "單選", "stem": "依據上文，關於《蘭亭詩》和〈蘭亭序〉的比較，最適當的敘述是：", "options": {"A": "《蘭亭詩》表達對於長生久視的渴望／〈蘭亭序〉抒發不別死生的玄心遠想", "B": "《蘭亭詩》抒發不別死生的玄心遠想／〈蘭亭序〉照見古今創作緣由的契合", "C": "《蘭亭詩》照見古今創作緣由的契合／〈蘭亭序〉追述修禊當日的可賞可樂", "D": "《蘭亭詩》追述修禊當日的可賞可樂／〈蘭亭序〉表達對於長生久視的渴望"}, "answer": "B", "explain": "文中說《蘭亭詩》「帶出玄心遠想，乃至齊彭殤、達至樂」，就是把生死、長短看成一樣的「不別死生」。〈蘭亭序〉則由「若合一契」「後之視今猶今之視昔」，看出古今「其致一也」的創作動機，就是「照見古今創作緣由的契合」，所以選(B)。(A)把兩者對調，而且〈蘭亭序〉恰恰否定齊彭殤。(C)「照見古今」是序，不是詩。(D)「長生渴慕」是作者分析興感的由來，並非〈蘭亭序〉直接表達的主旨。", "skill": "兩篇比較，先各找一句作者對它的評語，再看選項有沒有左右對調。"}, {"n": 18, "qtype": "單選", "stem": "上文□內最適合填入的是：（羲之更將此種閱覽的感懷置放在□中考察）", "options": {"A": "空間之變", "B": "時間之流", "C": "仕隱選擇", "D": "因緣生滅"}, "answer": "B", "explain": "空格後面接著講「若合一契」「後之視今猶今之視昔」「貫通古今」「世殊事異」，都是把古人、今人、後人放在一條時間線上比較，所以是「時間之流」，選(B)。文中沒有談空間、仕隱或佛教因緣。", "skill": "填空題看空格「後面」的例證，例證共同的範疇（古今→時間）就是答案。"}, {"n": 19, "qtype": "單選", "stem": "上文認為〈蘭亭序〉否定蘭亭詩人的方案，所揭示的生命態度是：", "options": {"A": "正視悅生惡死的人性，直面悲欣交集的人生", "B": "死亡既難以迴避，何妨快意暢情，不虛此生", "C": "珍惜有限人生，以積極入世消解死亡的悲感", "D": "棲隱山林，放志逍遙，在大自然中找尋自我"}, "answer": "A", "explain": "文末說〈蘭亭序〉「揭露人計較彭殤、在乎生死的常情本性」，王羲之「既不因一時陶然而從此忘我出世，亦不因現實悲涼而一味悵惘逃避，願意直接嚐受一切並加以回應」，正是(A)正視人性、直面悲喜。(B)「快意暢情」是一時陶然，正是作者說他沒有停留的狀態。(C)文中沒有提到積極入世。(D)棲隱山林是蘭亭詩人的方案，正是被否定的。", "skill": "「否定A，揭示B」的題目，先把A刪掉（逍遙山林、忘我出世），剩下的才可能是答案。"}], "difficulty": "難", "label": "107指考", "year": 107, "kind": "指考", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "蘭亭集序"}, {"id": "zk107-23", "exam": "zk107", "nums": [23, 24, 25], "form": "題組", "img": "img/zk107-23.png", "source": "戴吾三《解開成語中的科學密碼》（改寫）；文中及選項引《詩經‧小宛》、揚雄《法言》、陶弘景《本草經集注》、韓保昇《蜀本草》、蘇頌《圖經本草》、寇宗奭《本草衍義》、李時珍《本草綱目》", "author": "戴吾三", "genre": "說理議論", "types": ["文意推論", "比較閱讀"], "passage": "螟蛉有子，蜾蠃負之。（《詩經‧小宛》）\n螟蛉之子殪而逢蜾蠃，祝之曰：「類我！類我！」久則肖之矣。（揚雄《法言》）\n其（土蜂）生子如粟米大，置中，乃捕取草上青蜘蛛十餘枚，滿中，仍塞口，以待其子大為糧也。……《詩》云：「螟蛉有子，蜾蠃負之」。言細腰之物無雌，皆取青蟲教祝，便變成己子，斯為謬矣。（陶弘景《本草經集注》）\n①螟蛉，桑蟲也。蜾蠃，蒲盧也。言蒲盧負桑蟲以成其子也，亦負他蟲封之，數日則成蜂飛去。今有人候其封穴，壞而看之，見有卵如粟，在死蟲之上。（韓保昇《蜀本草》）\n②物類變化，固不可度。蚱蟬生於轉丸、衣魚生於瓜子之類，非一。桑蟲、蜘蛛之變為蜂，不為異也。如陶所說卵如粟者，未必非祝蟲而成之也。（蘇頌《圖經本草》）\n③嘗拆（土蜂）窠視之，果有子如半粟米大，色白而微黃。所負青菜蟲，卻在子下。（寇宗奭《本草衍義》）\n④今屢破其（土蜂）房，見子與他蟲同處，或子已去而蟲存空殼，或蟲成蛹而子尚小。蓋蟲終不壞，至其成蛹，子乃食之而出也。（李時珍《本草綱目》）", "translation": "螟蛉生了幼蟲，蜾蠃把牠背走。\n螟蛉的幼蟲快死時遇到蜾蠃，蜾蠃對牠念咒說：「像我！像我！」時間久了就變得像蜾蠃了。\n土蜂產下像粟米大的卵，放在窩裡，再捕捉十幾隻草上的青蜘蛛塞滿窩，然後封住洞口，等牠的幼蟲長大當食物。《詩經》說「螟蛉有子，蜾蠃負之」，有人說細腰蜂沒有雌的，都抓青蟲來念咒教化變成自己的孩子，這是錯的。\n①螟蛉就是桑蟲，蜾蠃就是蒲盧。說蒲盧背桑蟲來養成自己的孩子，也背別的蟲封在洞裡，幾天後就變成蜂飛走。現在有人守在牠封好的洞穴旁，挖開來看，看見有粟粒般的卵，在死蟲身上。\n②萬物的變化，本來就難以揣測。蚱蟬從糞球生出、衣魚從瓜子生出這類事不只一件。桑蟲、蜘蛛變成蜂，也不奇怪。像陶弘景說的粟粒般的卵，未必不是念咒讓蟲變成的。\n③我曾拆開土蜂的窩來看，果然有半粒粟米大的卵，顏色白而帶點黃。牠背來的青菜蟲，卻在卵的下面。\n④現在我多次拆開土蜂的窩，看見卵和別的蟲在一起，有的卵已經孵出離開而蟲只剩空殼，有的蟲已變成蛹而卵還很小。原來蟲始終不會腐壞，等到卵長成蛹，幼蜂就把蟲吃掉而出來。", "keywords": [{"w": "負", "m": "背、攜帶"}, {"w": "殪", "m": "死、將死"}, {"w": "祝", "m": "念咒"}, {"w": "肖", "m": "像"}, {"w": "斯為謬矣", "m": "這是錯誤的"}, {"w": "度", "m": "揣測"}, {"w": "窠", "m": "巢穴"}], "questions": [{"n": 23, "qtype": "單選", "stem": "依據上文，「螟蛉有子，蜾蠃負之」的真實生態現象最可能是：", "options": {"A": "蜾蠃奪螟蛉之巢以育子", "B": "蜾蠃是螟蛉之子的宿主", "C": "蜾蠃代替螟蛉餵養幼蟲", "D": "蜾蠃捕捉螟蛉以餵幼蟲"}, "answer": "D", "explain": "陶弘景觀察到土蜂把卵產在窩裡，再抓青蟲（蜘蛛）塞滿，「以待其子大為糧」；法布爾也證明細腰蜂的幼蟲以儲備的蜘蛛為食。所以蜾蠃背走螟蛉，是拿去給自己的幼蟲當糧食，選(D)。(A)不是奪巢。(B)宿主是被寄生的一方，這裡被吃的是螟蛉，關係顛倒。(C)蜾蠃不是在養螟蛉的孩子，而是把牠當食物。", "skill": "科學類文章，抓「觀察證據」那一段的關鍵動作（產卵→捕蟲→當糧），再對選項。"}, {"n": 24, "qtype": "單選", "stem": "關於陶弘景對細腰蜂觀察的敘述，最適當的是：", "options": {"A": "經過實證後轉為支持揚雄之見", "B": "蒐集實證以補充《詩經》所述", "C": "以《詩經》所述駁斥揚雄之見", "D": "依揚雄之見糾正《詩經》所述"}, "answer": "B", "explain": "陶弘景自己觀察土蜂：產下小卵、再捕青蜘蛛塞滿窩、封口，等幼蟲長大當糧食。這是用親眼看到的證據，把《詩經》「蜾蠃負之」到底在做什麼說清楚，所以選(B)。他批評的是後人把詩句解釋成「念咒讓青蟲變成自己的孩子」（斯為謬矣），不是批評《詩經》本身。(A)他反對揚雄的說法，不是轉為支持。(C)他駁斥揚雄靠的是自己的觀察，不是拿《詩經》的句子去駁斥。(D)他沒有依揚雄的說法，也沒有糾正《詩經》。", "skill": "分清三層：原典（《詩經》）、後人的解釋（揚雄）、觀察證據（陶弘景）。被反駁的往往是解釋，而原典是被證據補充說明的。"}, {"n": 25, "qtype": "單選", "stem": "上文□內若要擇用下列方框裡的論述，則對①、②、③、④的判斷，最適當的是：（陶弘景的看法後來得到更多證實，例如□）", "options": {"A": "①、②適用；③、④不適用", "B": "①、③適用；②、④不適用", "C": "①、③、④適用；②不適用", "D": "②、③、④適用；①不適用"}, "answer": "C", "explain": "空格要放「證實陶弘景看法」的例子，也就是觀察到卵和被捕來的蟲在一起、蟲是幼蜂的糧食。①挖開封穴「見有卵如粟，在死蟲之上」，適用。②蘇頌認為蟲變成蜂不奇怪，「未必非祝蟲而成之」，是支持揚雄，不適用。③拆窩看到卵，「所負青菜蟲，卻在子下」，適用。④看見卵和蟲同處，「子乃食之而出」，證明蟲是食物，適用。所以①③④適用、②不適用，選(C)。", "skill": "例證填空，先確定空格要支持的論點，再逐條判斷每則材料是「支持」還是「反對」。"}], "difficulty": "中", "label": "107指考", "year": 107, "kind": "指考", "textcat": "科普文本", "textcat2": "", "linked_core": ""}, {"id": "zk107-26", "exam": "zk107", "nums": [26, 27], "form": "題組", "img": "img/zk107-26.png", "source": "張輔〈名士優劣論〉", "author": "張輔", "genre": "說理議論", "types": ["文意推論", "比較閱讀"], "passage": "世人論司馬遷、班固，多以固為勝，余以為失。遷之著述，辭約而事舉，敘三千年事，唯五十萬言。班固敘二百年事，乃八十萬言，煩省不敵，固之不如遷一也。良史述事，善足以獎勸，惡足以監誡。人道之常，中流小事，亦無取焉，而班皆書之，不如二也。毀貶晁錯，傷忠臣之道，不如三也。遷既造創，固又因循，難易益不同矣。又遷為蘇秦、張儀、范雎、蔡澤作傳，逞詞流離，亦足以明其大才。故述辯士則辭藻華靡，敘實錄則隱核名檢，此所以稱遷良史也。", "translation": "世人評論司馬遷和班固，大多認為班固較好，我認為錯了。司馬遷的著作，文辭簡要而事情完備，記述三千年的事，只用五十萬字；班固記述二百年的事，卻用了八十萬字，繁簡差距太大，這是班固不如司馬遷的第一點。好的史家記事，好事足以獎勵勸勉，壞事足以讓人警惕。人生的平常事、一般的小事，就不必收錄，但班固全都寫進去，這是不如的第二點。他詆毀貶低晁錯，損害了忠臣之道，這是不如的第三點。司馬遷是開創，班固是沿襲，難易程度更不相同。另外，司馬遷替蘇秦、張儀、范雎、蔡澤寫傳，文辭奔放流暢，也足以顯示他的大才。所以寫辯士時辭藻華麗，記實事時就嚴謹考核名實，這就是稱司馬遷為良史的原因。", "keywords": [{"w": "辭約而事舉", "m": "文辭簡要而事情完備"}, {"w": "煩省不敵", "m": "繁簡不相當"}, {"w": "監誡", "m": "借鑑、警戒"}, {"w": "因循", "m": "沿襲前人"}, {"w": "逞詞流離", "m": "文辭奔放流暢"}, {"w": "隱核名檢", "m": "審慎考核名實"}], "questions": [{"n": 26, "qtype": "單選", "stem": "依據上文的看法，《漢書》不如《史記》之處在於：", "options": {"A": "取材雜蕪，有失精審", "B": "抄撮眾說，有失創新", "C": "隱惡揚善，有失客觀", "D": "用詞典麗，有失質樸"}, "answer": "A", "explain": "文中列出班固三點不如：文字太繁、把「中流小事」都寫進去、貶低忠臣晁錯。前兩點都是寫太多、不懂取捨，就是(A)取材雜蕪、不夠精審。(B)雖然提到「遷既造創，固又因循」，但作者說的是難易不同，不是列為「不如」的理由，且沒說他抄撮眾說。(C)班固是「毀貶晁錯」，是貶損忠臣，不是隱惡揚善。(D)文中沒有批評《漢書》用詞太華麗。", "skill": "作者列「一也、二也、三也」時，把三點歸納成一個共同點，答案常是那個上位概念。"}, {"n": 27, "qtype": "單選", "stem": "上文述及「蘇秦、張儀、范雎、蔡澤」的用意，是為了說明司馬遷撰作《史記》：", "options": {"A": "能依所敘人物選用最合宜的筆法", "B": "能發掘不被其他史家注意的史料", "C": "善透過所敘人物寄寓其落拓之悲", "D": "善學縱橫家言辭以充實史家才識"}, "answer": "A", "explain": "結論說「述辯士則辭藻華靡，敘實錄則隱核名檢」：寫蘇秦、張儀這些辯士，就用華麗奔放的文字；寫一般史實，就嚴謹考核。可見司馬遷會依寫作對象調整筆法，選(A)。(B)文中沒提發掘史料。(C)沒有提到寄寓落拓之悲。(D)是司馬遷用適合辯士的筆法來寫他們，不是去學縱橫家的言辭。", "skill": "找舉例後面的「故……」總結句，舉例的用意就寫在那裡。"}], "difficulty": "中", "label": "107指考", "year": 107, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk107-28", "exam": "zk107", "nums": [28, 29, 30, 31, 32], "form": "題組", "img": "img/zk107-28.png", "source": "《史記‧仲尼弟子列傳》、王安石〈子貢論〉", "author": "司馬遷、王安石", "genre": "史傳人物", "types": ["文意推論", "句意理解", "比較閱讀", "典故出處"], "passage": "甲、田常欲作亂於齊，憚高、國、鮑、晏，故移其兵，欲以伐魯。孔子聞之，謂門弟子曰：「夫魯，墳墓所處，父母之國，國危如此，二三子何為莫出？」子路請出，孔子止之。子張、子石請行，孔子弗許。子貢請行，孔子許之。遂行，至齊，說田常曰：「君之伐魯過矣。夫魯，難伐之國，其城薄以卑，其地狹以泄，其君愚而不仁，大臣偽而無用，其士民又惡甲兵之事，此不可與戰。君不如伐吳。夫吳，城高以厚，地廣以深，甲堅以新，士選以飽，重器精兵盡在其中，又使明大夫守之，此易伐也。」田常忿然作色曰：「子之所難，人之所易；子之所易，人之所難；而以教常，何也？」子貢曰：「臣聞之，憂在內者攻強，憂在外者攻弱。今君憂在內。吾聞君三封而三不成者，大臣有不聽者也。今君破魯以廣齊，戰勝以驕主，破國以尊臣，而君之功不與焉，則交日疏於主。是君上驕主心，下恣群臣，求以成大事，難矣。夫上驕則恣，臣驕則爭，是君上與主有郤，下與大臣交爭也。如此，則君之立於齊危矣。故曰不如伐吳。伐吳不勝，民人外死，大臣內空，是君上無強臣之敵，下無民人之過，孤主制齊者唯君也。」田常曰：「善。」\n乙、《史記》曰：「齊伐魯，孔子聞之，曰：『魯，墳墓之國。國危如此，二三子何為莫出？』子貢因行，說齊以伐吳，說吳以救魯，復說越，復說晉，五國由是交兵。或強，或破，或亂，或霸，卒以存魯。」觀其言，迹其事，儀、秦、軫、代，無以異也。嗟乎！孔子曰：「□」，己以墳墓之國而欲全之，則齊、吳之人豈無是心哉？奈何使之亂歟？吾所以知傳者之妄。", "translation": "甲：田常想在齊國作亂，但忌憚高、國、鮑、晏四大家族，所以想調動軍隊去攻打魯國。孔子聽說了，對學生說：「魯國是祖先墳墓所在、父母之邦，國家危險到這種地步，你們為什麼沒有人出面？」子路請求前往，孔子阻止他。子張、子石請求前往，孔子不答應。子貢請求前往，孔子答應了。子貢到了齊國，勸田常說：「您攻打魯國錯了。魯國是難打的國家：城牆又薄又矮，土地又窄又淺，國君愚昧不仁，大臣虛偽無用，士人百姓又討厭打仗，這種國家不能和它作戰。您不如攻打吳國。吳國城牆又高又厚，土地又廣又深，鎧甲堅固嶄新，士兵精選又吃得飽，貴重器物和精兵都在那裡，又派賢明的大夫守著，這才容易打。」田常氣得變了臉色說：「你說難的，是別人說容易的；你說容易的，是別人說難的；你拿這些來教我，是什麼意思？」子貢說：「我聽說，憂患在國內的要攻打強國，憂患在國外的要攻打弱國。現在您的憂患在國內。我聽說您三次要受封都沒成功，是因為有大臣不聽從。現在您攻破魯國擴張齊國，打勝仗會讓國君驕傲，攻破別國會讓大臣地位提高，而您卻沒有功勞，那麼您和國君的關係就會一天天疏遠。這樣您對上讓國君驕縱，對下讓群臣放肆，想要成就大事，就難了。國君驕傲就會放縱，大臣驕傲就會爭權，這樣您對上和國君有嫌隙，對下和大臣相爭。如此一來，您在齊國的地位就危險了。所以說不如攻打吳國。攻打吳國打不贏，百姓死在外面，大臣在朝中失去勢力，這樣您上面沒有強臣做對手，下面沒有百姓的責難，孤立國君、控制齊國的就只有您了。」田常說：「好。」\n乙：《史記》說：齊國攻打魯國，孔子說魯國是祖先墳墓所在，國家這麼危急，你們為什麼不出面？子貢於是出發，勸齊國攻打吳國，勸吳國救魯國，又遊說越國、晉國，五個國家因此互相攻打，有的變強、有的被攻破、有的發生內亂、有的稱霸，最後保全了魯國。看他的言論、考察他的事跡，和張儀、蘇秦、陳軫、蘇代這些說客沒有兩樣。唉！孔子說「己所不欲，勿施於人」，自己因為是祖墳所在的國家而想保全它，那麼齊國、吳國的人難道沒有這種心嗎？為什麼要讓他們的國家陷入動亂呢？這就是我知道傳記記載錯誤的原因。", "keywords": [{"w": "憚", "m": "害怕、忌憚"}, {"w": "泄", "m": "淺"}, {"w": "忿然作色", "m": "氣得變了臉色"}, {"w": "驕主", "m": "使國君驕傲"}, {"w": "尊臣", "m": "使大臣地位尊貴"}, {"w": "郤", "m": "同「隙」，嫌隙"}, {"w": "孤主制齊", "m": "孤立國君、控制齊國"}, {"w": "迹", "m": "考察"}, {"w": "傳者之妄", "m": "傳記記載的錯誤"}], "questions": [{"n": 28, "qtype": "單選", "stem": "甲文中，田常聽完子貢的陳述「忿然作色」，是因為子貢：", "options": {"A": "斥責齊國不仁不義", "B": "諷刺田常短視狹隘", "C": "論調荒謬悖於常理", "D": "分析戰情淺薄空泛"}, "answer": "C", "explain": "子貢把城薄地狹的魯國說成「難伐」，把城高兵精的吳國說成「易伐」，完全違反常識，所以田常生氣地說「子之所難，人之所易；子之所易，人之所難」，選(C)。(A)子貢說的是魯君不仁，不是罵齊國。(B)子貢還沒講到田常的私心，沒有諷刺他。(D)子貢分析得很具體，田常氣的是結論顛倒，不是空泛。", "skill": "人物情緒的原因，通常就在他緊接著說的那句話裡。"}, {"n": 29, "qtype": "單選", "stem": "甲文中，「戰勝以驕主，破國以尊臣」的意思是：", "options": {"A": "田常戰功彪炳，故國君引以為傲，群臣亦相推尊", "B": "田常開疆闢土，令國君自覺驕豪、大臣更加尊貴", "C": "倘若田常恃功而驕，雖一時尊榮但終致身敗國亡", "D": "倘若田常欲掌大權，當建功沙場以傲視國君群臣"}, "answer": "B", "explain": "「驕主」是使國君驕傲，「尊臣」是使大臣尊貴（使動用法）。意思是：田常打下魯國，功勞會讓國君更驕傲、大臣更有地位，「而君之功不與焉」，田常自己反而得不到好處，選(B)。(A)不是群臣推尊田常，而是大臣自己變尊貴。(C)驕傲的是國君不是田常，也沒說國亡。(D)子貢是勸他不要這樣打，不是叫他建功傲視君臣。", "skill": "「動詞＋以＋形容詞＋名詞」常是使動用法：驕主＝使主驕，尊臣＝使臣尊。"}, {"n": 30, "qtype": "單選", "stem": "甲文中，田常願意接受子貢的建議，乃因伐吳能讓他：", "options": {"A": "擺脫強臣掣肘", "B": "擺脫齊君脅迫", "C": "獲得百姓擁戴", "D": "獲得魯國支援"}, "answer": "A", "explain": "子貢說伐吳打不贏，「大臣內空，是君上無強臣之敵」，強大的對手大臣會損耗在戰場上，田常就能「孤主制齊」，所以是(A)擺脫強臣掣肘。(B)田常要的是孤立國君，不是被國君脅迫。(C)「下無民人之過」是說百姓不會責怪他，不是擁戴。(D)文中沒提魯國支援。", "skill": "說服成功的關鍵在對方的「利益」，找說客最後點出的好處（無強臣之敵）。"}, {"n": 31, "qtype": "單選", "stem": "乙文□內最適合填入的是：", "options": {"A": "不在其位，不謀其政", "B": "己所不欲，勿施於人", "C": "用之則行，舍之則藏", "D": "道之以德，齊之以禮"}, "answer": "B", "explain": "空格後面說：你自己因為是祖國而想保全魯國，那齊國、吳國的人難道不也想保全自己的國家？為什麼要讓他們大亂？這正是推己及人，「己所不欲，勿施於人」，選(B)。(A)講不在職位就不管那件政事。(C)講被任用就出來做事、不被任用就隱退。(D)講用德行和禮來治理百姓。都接不上後文。", "skill": "引文填空看「後一句」怎麼推論，推論的邏輯（推己及人）就是要填的那句話。"}, {"n": 32, "qtype": "單選", "stem": "綜合甲、乙二文，王安石質疑甲文對子貢作為的描述，主要基於子貢：", "options": {"A": "以利為餌，誘使田常接受建議", "B": "降志辱身，為達目的貶抑魯國", "C": "以鄰為壑，不符孔子儒學精神", "D": "能言善道，刻意離間齊國君臣"}, "answer": "C", "explain": "王安石認為，子貢為了保全魯國而挑動齊、吳等國交戰，像戰國說客一樣，把禍患推給鄰國，違背孔子「己所不欲，勿施於人」的仁恕之道，所以他判斷傳記是假的，選(C)「以鄰為壑」。(A)(B)(D)都是甲文中子貢的手法，但王安石質疑的核心是違反儒家精神，不是這些技巧本身。", "skill": "「質疑的理由」要從作者的立場出發：王安石是儒者，就從儒家價值找答案。"}], "difficulty": "難", "label": "107指考", "year": 107, "kind": "指考", "textcat": "延伸", "textcat2": "學術文本", "linked_core": "鴻門宴"}, {"id": "zk107-33", "exam": "zk107", "nums": [33, 34], "form": "題組", "img": "img/zk107-33.png", "source": "獨逸窩退士《笑笑錄》", "author": "獨逸窩退士", "genre": "筆記小品", "types": ["句意理解", "典故出處", "人物情感"], "passage": "南唐彭利用對家人奴隸言，必據書史以代常談，俗謂之掉書袋，因自謂彭書袋。其僕有過，利用責之曰：「始予以為紀綱之僕，人百其身，賴爾同心同德，左之右之。今乃中道而廢，侮慢自賢。若而今而後，過而弗改，當撻之市朝，任汝自西自東，以遨以游而已。」鄰家火災，利用望之曰：「煌煌然，赫赫然，不可向邇，自鑽燧以降，未有若斯之盛，其可撲滅乎！」", "translation": "南唐的彭利用對家人、僕人說話，一定要引用書上的句子代替平常話，人們稱這叫「掉書袋」，他也就自稱「彭書袋」。他的僕人犯了錯，彭利用責備他說：「當初我以為你是能管事的僕人，願意為我竭盡心力，依靠你和我同心同德，在我左右幫忙。現在你卻半途而廢，傲慢自以為了不起。如果從今以後，犯錯還不改，就要在市集上鞭打你，讓你愛往東往西都隨便，到處遊蕩去吧（把你趕走）。」鄰居家失火，彭利用看著說：「火光明亮、氣勢盛大，無法靠近，自從鑽木取火以來，沒有像這樣旺盛的，這能撲滅嗎！」", "keywords": [{"w": "掉書袋", "m": "說話愛引經據典、賣弄學問"}, {"w": "紀綱之僕", "m": "能管理家務的僕人"}, {"w": "人百其身", "m": "願以百身相贖，此指竭盡心力"}, {"w": "中道而廢", "m": "半途而廢"}, {"w": "撻之市朝", "m": "在市集上鞭打"}, {"w": "向邇", "m": "靠近"}, {"w": "鑽燧", "m": "鑽木取火"}], "questions": [{"n": 33, "qtype": "單選", "stem": "下列文意解釋，最適當的是：", "options": {"A": "「賴爾同心同德，左之右之」，指僕人耍賴失德，三心二意", "B": "「今乃中道而廢，侮慢自賢」，指因僕人半途辭職，有損主人的賢名", "C": "「任汝自西自東，以遨以游而已」，指將僕役逐出家門", "D": "「自鑽燧以降，未有若斯之盛，其可撲滅乎！」指彭利用讚嘆火勢盛大，阻止鄰人將其撲滅"}, "answer": "C", "explain": "(C)「任汝自西自東，以遨以游」是讓你愛去哪就去哪、到處遊蕩，前面又說要「撻之市朝」，意思就是把僕人趕出家門，正確。(A)「賴」是依靠，是說當初依靠僕人同心同德幫忙，不是耍賴。(B)「中道而廢」是做事半途而廢（不再盡心），「侮慢自賢」是僕人傲慢自以為是，不是辭職、也不是損害主人名聲。(D)「其可撲滅乎」是問「這還能撲滅嗎」，是在火災現場還掉書袋地感嘆，不是阻止別人救火。", "skill": "笑話類文言要先還原「正常說法」，彭利用每句話其實都只是很普通的意思，只是包裝成典故。"}, {"n": 34, "qtype": "單選", "stem": "依據上文，最符合彭利用說話方式的是：", "options": {"A": "自負博學，盛氣凌人", "B": "廢話連篇，誇大不實", "C": "曲解經典，胡吹亂謅", "D": "賣弄學問，滿口典故"}, "answer": "D", "explain": "文章開頭就說他「必據書史以代常談，俗謂之掉書袋」，罵僕人、看火災都用《詩經》《書經》《禮記》的句子，就是賣弄學問、滿口典故，選(D)。(A)文中沒有寫他欺壓人的態度。(B)他說的內容並不誇大，只是不合場合。(C)他引用的典故意思大致用對了，問題在於不分場合亂用，不是曲解經典。", "skill": "人物特色題，第一句的介紹（俗謂之……）通常已經直接給答案。"}], "difficulty": "易", "label": "107指考", "year": 107, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk107-36", "exam": "zk107", "nums": [36], "form": "單題", "img": "img/zk107-36.png", "source": "選項出自《孟子‧梁惠王上》、歸有光〈項脊軒志〉、韓愈〈師說〉、《莊子‧養生主》、曹丕〈典論論文〉、《荀子‧勸學》、賈誼〈過秦論〉、杜光庭〈虯髯客傳〉、諸葛亮〈出師表〉、《史記‧項羽本紀》", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)斧斤以時入山林／小鳥時來啄食，人至不去\n(B)士大夫之族，曰師、曰弟子云者／族庖月更刀，折也\n(C)夫然，則古人賤尺璧而重寸陰／其質非不美也，所漸者然也\n(D)信臣精卒，陳利兵而誰何／四人對饌訖，陳女樂二十人，列奏於前\n(E)諮諏善道，察納雅言／楚左尹項伯者，項羽季父也，素善留侯張良", "translation": "(A)按照季節才拿斧頭進山林砍樹／小鳥時常飛來啄食，人走近也不飛走。\n(B)士大夫這類人，一說到老師、學生／一般的廚師每個月換一把刀，因為是用刀去砍斷骨頭。\n(C)既然這樣，那麼古人輕視一尺的玉璧而重視一寸的光陰／它的本質不是不好，是浸泡它的東西讓它變成這樣。\n(D)可靠的大臣、精銳的士兵，擺出鋒利的兵器，盤問來往的人／四個人吃完飯，又排列出二十個歌舞女伎，在面前演奏。\n(E)詢問治國的好方法，明察採納正直的言論／楚國左尹項伯是項羽的叔父，向來和留侯張良交好。", "keywords": [{"w": "以時", "m": "按季節"}, {"w": "族", "m": "類／眾、一般"}, {"w": "然", "m": "這樣、如此"}, {"w": "陳", "m": "陳列、擺出"}, {"w": "善", "m": "好的／交好"}], "questions": [{"n": 36, "qtype": "多選", "stem": "下列各組文句「」內的詞，前後意義相同的是：", "options": {"A": "斧斤以「時」入山林／小鳥「時」來啄食，人至不去", "B": "士大夫之「族」，曰師、曰弟子云者／「族」庖月更刀，折也", "C": "夫「然」，則古人賤尺璧而重寸陰／其質非不美也，所漸者「然」也", "D": "信臣精卒，「陳」利兵而誰何／四人對饌訖，「陳」女樂二十人，列奏於前", "E": "諮諏「善」道，察納雅言／楚左尹項伯者，項羽季父也，素「善」留侯張良"}, "answer": "CD", "explain": "(A)前「時」是季節、適當時機（以時＝按季節），後「時」是時常，不同。(B)前「族」是「類、群」（士大夫這一類人），後「族」是「眾、一般」（一般的廚師），不同。(C)兩個「然」都是「這樣、如此」，相同。(D)兩個「陳」都是「陳列、擺出」，相同。(E)前「善」是好的（形容詞），後「善」是交好、友好（動詞），不同。", "skill": "判斷同不同，把一個義項代入兩句都要通順；詞性不同（形容詞／動詞）通常意思就不同。"}], "difficulty": "中", "label": "107指考", "year": 107, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "勸學、鴻門宴、典論論文、出師表、師說、虬髯客傳、項脊軒志"}, {"id": "zk107-37", "exam": "zk107", "nums": [37], "form": "單題", "img": "img/zk107-37.png", "source": "選項出自《戰國策‧馮諼客孟嘗君》、杜光庭〈虯髯客傳〉、方苞〈左忠毅公軼事〉、陶淵明〈桃花源記〉、蒲松齡〈勞山道士〉", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "已而夕陽在山，人影散亂，太守歸而賓客從也。（歐陽脩〈醉翁亭記〉）\n(A)左右以君賤之也，食以草具\n(B)及期，入太原候之，相見大喜\n(C)呈卷，即面署第一；召入，使拜夫人\n(D)見漁人，乃大驚，問所從來，具答之，便要還家\n(E)一道士坐蒲團上，素髮垂領，而神觀爽邁。叩而與語，理甚玄妙", "translation": "不久夕陽落到山邊，人影零亂，太守回去了，賓客跟著他。\n(A)左右的人因為孟嘗君看不起馮諼，就拿粗劣的飯菜給他吃。\n(B)到了約定的日期，進太原城等候他，兩人相見非常高興。\n(C)交上考卷，左光斗當面批為第一名；叫他進內室，讓他拜見夫人。\n(D)村人看見漁人，非常驚訝，問他從哪裡來，漁人詳細回答，村人就邀請他回家。\n(E)一位道士坐在蒲團上，白髮垂到頸部，精神清爽超逸。王生向他叩頭並和他交談，道理非常玄妙。", "keywords": [{"w": "食", "m": "ㄙˋ，給人吃"}, {"w": "使", "m": "讓、叫"}, {"w": "要", "m": "同「邀」，邀請"}, {"w": "省略賓語", "m": "動詞後省略了動作對象（多半可補「之」）"}], "questions": [{"n": 37, "qtype": "多選", "stem": "〈醉翁亭記〉：「已而夕陽在山，人影散亂，太守歸而賓客從也。」句中「賓客」所「從」有其對象（即「太守」），故相當於「太守歸而賓客從『之』也」。下列文句畫底線的動詞之後，也省略對象的是：（底線字依序為：A食、B見、C使、D要、E語）", "options": {"A": "左右以君賤之也，食以草具", "B": "及期，入太原候之，相見大喜", "C": "呈卷，即面署第一；召入，使拜夫人", "D": "見漁人，乃大驚，問所從來，具答之，便要還家", "E": "一道士坐蒲團上，素髮垂領，而神觀爽邁。叩而與語，理甚玄妙"}, "answer": "ACD", "explain": "方法：在底線動詞後補「之」看通不通、有沒有明確對象。(A)「食以草具」＝「食之以草具」，給馮諼吃粗食，省略對象，對。(B)「相見」的「相」已經指出對象（彼此、對方），「見」後不用再補，錯。(C)「使拜夫人」＝「使之（史可法）拜夫人」，省略對象，對。(D)「便要還家」＝「便要之（漁人）還家」，省略對象，對。(E)「叩而與語」，對象「道士」省略在介詞「與」的後面（與之語），「語」本身是不及物的「交談」，動詞後沒有省略，錯。", "skill": "補「之」測試法：在動詞後補上「之」，句子通順且指得出是誰，就是省略賓語；若有「相」或省略在介詞後，就不算。"}], "difficulty": "難", "label": "107指考", "year": 107, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "馮諼客孟嘗君、桃花源記、虬髯客傳、醉翁亭記、勞山道士、左忠毅公軼事"}, {"id": "zk107-38", "exam": "zk107", "nums": [38], "form": "單題", "img": "img/zk107-38.png", "source": "黃滔〈賈客〉", "author": "黃滔", "genre": "古典詩詞曲", "types": ["詩詞賞析", "主旨寓意"], "passage": "大舟有深利，滄海無淺波。利深波也深，君意竟如何？鯨鯢齒上路，何如少經過□", "translation": "大船出海能賺到豐厚的利潤，但大海沒有淺淺的波浪。利潤有多深，風浪就有多深，你的心意到底如何？那是在鯨魚牙齒上行走的路，不如少走為妙吧。", "keywords": [{"w": "賈客", "m": "商人"}, {"w": "鯨鯢", "m": "大鯨魚，比喻凶險"}, {"w": "何如", "m": "不如（句號時）／怎麼樣（問號時）"}], "questions": [{"n": 38, "qtype": "多選", "stem": "有五位學生嘗試分析右詩，其中適當的是：", "options": {"A": "甲生：□的標點符號如果是句號，表示作者認為大利多風險，少碰為妙", "B": "乙生：□的標點符號如果是問號，表示作者想知道怎樣既獲大利又不涉風險", "C": "丙生：本詩將行商比為行船，商人謀生如同在鯨鯢齒上行走般艱險", "D": "丁生：本詩警告行商艱險難測，提醒世人不貪眼前小利，方能獲取大利", "E": "戊生：本詩期許商人應擁有鯨鯢般的雄心壯志，切莫因處境凶險便膽怯"}, "answer": "AC", "explain": "全詩說：利越大、風浪越大，像走在鯨魚牙齒上。(A)若是句號，「何如少經過」＝「不如少走這條路」，就是大利多風險、少碰為妙，對。(B)若是問號，是反問「何不少走一點呢？」或問對方意思，仍是勸人避險，並不是想知道怎樣兩全其美，錯。(C)出海經商就是行船，「鯨鯢齒上路」比喻謀生艱險，對。(D)詩是勸人不要為大利冒險，不是叫人不貪小利以獲取大利，錯。(E)鯨鯢比喻凶險的危機，不是雄心壯志，詩也是勸人少冒險，錯。", "skill": "標點題把兩種標點各讀一遍，看語氣是「勸告」還是「詢問」，再看是否仍符合全詩主旨。"}], "difficulty": "中", "label": "107指考", "year": 107, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk107-39", "exam": "zk107", "nums": [39], "form": "單題", "img": "img/zk107-39.png", "source": "《韓非子‧主道》", "author": "韓非", "genre": "說理議論", "types": ["文意推論", "主旨寓意"], "passage": "人主之道，靜退以為寶。不自操事而知拙與巧，不自計慮而知福與咎。是以不言而善應，不約而善增。言已應則執其契，事已增則操其符。符契之所合，賞罰之所生也。故群臣陳其言，君以其言授其事，事以責其功。功當其事，事當其言，則賞；功不當其事，事不當其言，則誅。明君之道，臣不得陳言而不當。是故明君之行賞也，曖乎如時雨，百姓利其澤；其行罰也，畏乎如雷霆，神聖不能解也。故明君無偷賞，無赦罰。賞偷則功臣墮其業，赦罰則奸臣易為非。是故誠有功則雖疏賤必賞，誠有過則雖近愛必誅。疏賤必賞，近愛必誅，則疏賤者不怠，而近愛者不驕也。", "translation": "君主的治國之道，以虛靜退讓為寶。不親自做事卻知道臣子做得好壞，不親自謀劃卻知道結果吉凶。所以君主不說話，臣子就會好好回應；不約束，臣子就會好好增進事功。臣子的話已經說出，君主就握住這張「契」；事情已經推進，君主就握住那張「符」。符契相合的地方，就是賞罰產生的依據。所以群臣陳述意見，君主依他說的話交付工作，再依工作要求他的成效。成效符合工作、工作符合他說的話，就賞；不符合，就罰。英明君主的原則，是臣子不能說了話卻不兌現。所以明君賞賜時，溫暖得像及時雨，百姓都得到恩澤；處罰時，嚇人得像雷霆，連神聖也解救不了。所以明君不隨便賞賜，也不赦免該罰的。隨便賞賜，有功的臣子就會荒廢事業；赦免罪罰，奸臣就容易為非作歹。因此真有功勞，即使是疏遠卑賤的人也一定賞；真有過錯，即使是親近寵愛的人也一定罰。這樣疏遠卑賤的人就不會懈怠，親近寵愛的人也不會驕縱。", "keywords": [{"w": "靜退", "m": "虛靜退讓"}, {"w": "咎", "m": "災禍"}, {"w": "契、符", "m": "憑證，此指臣子的言論與事功"}, {"w": "曖", "m": "溫和"}, {"w": "偷賞", "m": "苟且、隨便地賞賜"}, {"w": "誅", "m": "懲罰"}], "questions": [{"n": 39, "qtype": "多選", "stem": "依據下文，關於國君治術的敘述，適當的是：", "options": {"A": "不自操事、不自計慮，顯示法家的治術也重虛靜無為", "B": "行時雨之賞、雷霆之罰，根於法家趨利避害的人性論", "C": "因臣子之言而授其事、責其功，循名責實以施行賞罰", "D": "嚴罰以防奸，偷賞以勵善，建構恩威並施的管理方法", "E": "賞疏賤、誅近愛，令疏賤者自戒不驕，近愛勤勉不怠"}, "answer": "ABC", "explain": "(A)開頭「人主之道，靜退以為寶」「不自操事」「不自計慮」，君主自己不動手而能掌握一切，顯示法家吸收了道家虛靜無為的思想，對。(B)賞像時雨讓人得利、罰像雷霆讓人害怕，正是利用人喜歡利益、害怕懲罰的天性，對。(C)臣子說了什麼（名）就交付什麼事，再看成效（實）符不符合來賞罰，就是循名責實，對。(D)文中明說「明君無偷賞」，不能隨便賞，錯。(E)文中是「疏賤者不怠，而近愛者不驕」，選項把「不驕」和「不怠」對調了，錯。", "skill": "多選題特別留意「對調」陷阱：原文 A配B、C配D，選項常改成 A配D。"}], "difficulty": "中", "label": "107指考", "year": 107, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk107-40", "exam": "zk107", "nums": [40], "form": "單題", "img": "img/zk107-40.png", "source": "語法說明文（命題者自撰）；例句出自屈原〈漁父〉、蘇軾〈赤壁賦〉、《史記》、賈誼〈過秦論〉、《韓非子》、袁宏道〈晚遊六橋待月記〉、《史記‧項羽本紀》", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "是以見放／此非孟德之困於周郎者乎／蔡澤見逐於趙／為天下笑／使身死而為刑戮／余時為桃花所戀，竟不忍去湖上／若屬皆且為所虜", "translation": "因此被放逐／這不就是曹操被周瑜圍困的地方嗎／蔡澤被趙國趕走／被天下人恥笑／使自己被殺而受刑／我當時被桃花迷戀住，竟捨不得離開西湖／你們這些人都將被他俘虜。", "keywords": [{"w": "見", "m": "放在動詞前表被動"}, {"w": "於", "m": "放在動詞後引出施動者"}, {"w": "為……所……", "m": "被……所……"}, {"w": "施動者", "m": "動作的發出者"}], "questions": [{"n": 40, "qtype": "多選", "stem": "依據下文，關於「被動句」的敘述，適當的是：（文章說明現代漢語「被」字句與文言「見」「於」「為」「為……所」等被動句式，例句見 passage）", "options": {"A": "用「被」表被動，施動者的位置無論在動詞前或後皆可", "B": "「見」和「為」表被動，都可直接將施動者加在動詞前", "C": "文言被動如施動者出現在動詞後，可以用「於」字引出", "D": "「為」後的施動者若省略，只能出現在「為……所」式", "E": "「為」和「被」出現在被動句，施動者可出現也可省略"}, "answer": "CE", "explain": "(A)文中「被」字句的施動者只出現在動詞前（被人騙），錯。(B)「見」只能加在動詞前表被動，若要引出施動者，要在動詞後加「於」（見逐於趙），不能直接把施動者放在動詞前；只有「為」可以（為天下笑），錯。(C)「困於周郎」「見逐於趙」，施動者在動詞後，用「於」引出，對。(D)「使身死而為刑戮」就是「為」後省略施動者，但不是「為……所」式，所以不是「只能」，錯。(E)「為」：為天下笑（出現）、為刑戮（省略）；「被」：被人騙（出現）、被騙（省略），對。", "skill": "語法說明題把文中每個例句歸類做成表格（句式／施動者位置／可否省略），再逐一核對選項。"}], "difficulty": "中", "label": "107指考", "year": 107, "kind": "指考", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "漁父、鴻門宴、赤壁賦、晚遊六橋待月記"}, {"id": "zk107-41", "exam": "zk107", "nums": [41, 42], "form": "題組", "img": "img/zk107-41.png", "source": "甲文為白話說明（引〈秦淮鬥草篇〉、李白、王建、白居易、柳永、范成大詩句）；乙文為李汝珍《鏡花緣》第76～77回", "author": "李汝珍", "genre": "其他", "types": ["文意推論", "比較閱讀", "文化常識"], "passage": "（甲文引用詩句）\n蘭皋藉作爭衡地，蕙畹翻為角敵場。分行花隊逐，對壘葉旗張。花花非一色，葉葉兩相當。／君有合歡枝，妾有相思子。（〈秦淮鬥草篇〉）\n禁庭春晝，鶯羽披新繡，百草巧求花下鬥，只賭珠璣滿斗。（李白）\n水中芹葉土中花，拾得還將避眾家。總待別人般數盡，袖中拈出鬱金芽。（王建）\n弄塵復鬥草，盡日樂嬉嬉。（白居易）\n春困厭厭，拋擲鬥草工夫，冷落踏青心緒。（柳永）\n青枝滿地花狼藉，知是兒孫鬥草來。（范成大）", "translation": "長蘭草的水岸變成爭勝之地，種蕙草的田地成了比賽場。花朵排成隊伍追逐，葉子像兩軍對壘時張開的旗幟。花朵每朵顏色不同，葉子兩兩相當。／你有合歡枝，我有相思子（用花草名配對）。\n宮中春天的白晝，黃鶯羽毛像披上新繡衣，大家在花下巧妙地找各種花草來比賽，只賭滿滿一斗的珍珠。\n水中的芹葉、土裡的花，撿到了還要躲開大家藏好；一直等到別人把種類都數完，才從袖子裡拿出一株鬱金芽。\n玩泥土又玩鬥草，整天快快樂樂。\n春天睏倦無力，把鬥草的功夫都拋開，連踏青的心情也冷淡了。\n綠枝落滿地、花朵散亂，就知道是孫兒們鬥草玩過了。", "keywords": [{"w": "鬥草", "m": "古代比賽花草的遊戲，分武鬥（拉扯草莖）與文鬥（比種類、對花名）"}, {"w": "珠璣", "m": "珍珠，此指賭注"}, {"w": "般", "m": "種類"}, {"w": "狼藉", "m": "散亂"}], "questions": [{"n": 41, "qtype": "多選", "stem": "依據甲文，關於「鬥草」的敘述，適當的是：", "options": {"A": "唐代玩此遊戲，有時會以物品當賭注", "B": "透過此遊戲，有機會可以認識各種藥草名稱", "C": "王建詩中所述，應以持有花草與眾不同者勝出", "D": "此遊戲源自端午習俗，歷來只在過節當日進行", "E": "武鬥致勝關鍵，在於熟記植物名稱與玩家力氣大小"}, "answer": "ABC", "explain": "(A)李白詩「只賭珠璣滿斗」，用一斗珍珠當賭注，對。(B)鬥草和古人的藥草觀念有關，文鬥又要比採摘花草的種類，玩的時候自然會認識各種藥草，對。(C)王建詩說撿到後要躲開大家，等別人的種類數完，才從袖中拿出鬱金芽，表示要用別人沒有的稀奇花草取勝，對。(D)文中說「通常」在五月五日、「大概」與藥草觀念有關，唐宋詩也寫到春天鬥草，並非只在過節當日，錯。(E)武鬥比的是草莖韌性，拉扯不斷者勝，和熟記植物名稱無關，錯。", "skill": "文中的「通常、大概」是保留語氣，選項若改成「只、歷來」等絕對用語，多半是錯的。"}, {"n": 42, "qtype": "多選", "stem": "依據甲、乙二文，關於「文鬥」的敘述，適當的是：", "options": {"A": "甲文所述《紅樓夢》的玩法，即乙文所謂的舊套", "B": "決定勝負的條件，由辨識植物種類擴及語文素養", "C": "因花草珍貴，故紫芝提議的新玩法可以自創植物名", "D": "依據花草名對仗的要求，「鼠姑心」能對「龍鬚柏」", "E": "兩部小說的相關記載，提供古代婦女詞采展現與人際交流的資訊"}, "answer": "ABE", "explain": "(A)《紅樓夢》是採摘花草後再擺出來對（觀音柳對羅漢松），仍要折草；乙文紫芝說要「脫了舊套」「也不折草」，所以紅樓夢的玩法屬於舊套，對。(B)從比採到的種類數量，發展到「花草名對仗」、說出名字來對，需要語文能力，對。(C)紫芝說「只要見之於書，就可用得」，名字必須有書可查，不能自創，錯。(D)對仗要求字面工整，「鼠姑心」對「龍鬚柏」：鼠對龍可以，但「心」不是植物名而「柏」是，詞性結構不對稱，所以不能對，錯。(E)兩部小說都寫閨閣女子一起鬥草、對花名，可以看出古代婦女展現詞采和互動交流，對。", "skill": "對仗判斷：逐字比對詞性與類別（動物對動物、器物對器物、植物對植物），有一處不對就不算工整。"}], "difficulty": "中", "label": "107指考", "year": 107, "kind": "指考", "textcat": "生活情境文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "xc108-3", "exam": "xc108", "nums": [3], "form": "單題", "img": "img/xc108-3.png", "source": "司馬遷《史記‧項羽本紀》", "author": "司馬遷", "genre": "史傳人物", "types": ["文意推論", "句意理解"], "passage": "夫秦失其政，陳涉首難，豪傑蜂起，相與並爭，不可勝數。然羽非有尺寸，乘勢起隴畝之中，三年，遂將五諸侯滅秦，分裂天下而封王侯，政由羽出，號為霸王。", "translation": "秦朝政治敗壞，陳勝首先起事，各地豪傑像蜂群一樣紛紛起兵，互相爭奪，數都數不清。但項羽沒有一點點封地權勢，趁著時勢從田野間崛起，三年之內就率領五國諸侯滅了秦朝，分割天下、封立王侯，政令都由項羽發出，號稱「霸王」。", "keywords": [{"w": "首難", "m": "首先起事"}, {"w": "尺寸", "m": "一尺一寸的土地，比喻極少的憑藉"}, {"w": "隴畝", "m": "田野"}, {"w": "將", "m": "率領"}], "questions": [{"n": 3, "qtype": "單選", "stem": "下列是一段古文，依據文意，甲、乙、丙、丁排列順序最適當的是：（原文見截圖）", "options": {"A": "甲丙丁乙", "B": "乙丁丙甲", "C": "丙丁甲乙", "D": "丁乙丙甲"}, "answer": "C", "explain": "答案(C)。「豪傑蜂起」後接丙「相與並爭，不可勝數」，說群雄並起；丁用「然」轉折，說項羽沒有憑藉卻崛起；甲「三年，遂將五諸侯滅秦」接在崛起之後；乙「分裂天下而封王侯，政由羽出」，最後接「號為霸王」。所以是丙丁甲乙。", "skill": "排序題抓轉折詞與時間詞：『然』前面通常是大背景、後面轉到主角；『三年，遂……』表示結果，要接在起事之後；最後一句要能接上結尾。"}], "difficulty": "易", "label": "108學測", "year": 108, "kind": "學測", "textcat": "延伸", "textcat2": "學術文本", "linked_core": "鴻門宴"}, {"id": "xc108-5", "exam": "xc108", "nums": [5], "form": "單題", "img": "img/xc108-5.png", "source": "宣鼎〈雅賺〉", "author": "宣鼎", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "（鄭板橋）為秀才時，三至邗江，售書賣畫，無識者，落拓可憐。復舉於鄉，旋登甲榜，聲名大震。再至邗江，則爭索先生墨妙者，戶外履常滿。先生固寒士，至是益盛自寶重，非重價，不與索。沈凡民先生代鐫小印，文曰「二十年前舊板橋」，志憤也。", "translation": "鄭板橋當秀才時，三次到揚州賣字畫，沒有人賞識，落魄得令人同情。後來考中舉人，接著又中了進士，名聲大振。再到揚州時，搶著求他字畫的人，門外的鞋子常常擺滿。鄭板橋本來是貧寒的讀書人，到這時更加愛惜自己的作品，不是高價就不給。沈凡民先生替他刻了一方小印，印文是「二十年前舊板橋」，這是用來記下他的憤慨。", "keywords": [{"w": "邗江", "m": "揚州"}, {"w": "落拓", "m": "窮困失意"}, {"w": "舉於鄉", "m": "考中舉人"}, {"w": "甲榜", "m": "進士"}, {"w": "履常滿", "m": "門外的鞋常常滿了，形容訪客多"}, {"w": "志", "m": "記"}], "questions": [{"n": 5, "qtype": "單選", "stem": "依據下文，鄭板橋所「志」的「憤」最可能是：", "options": {"A": "世人盲從，唯重聲名", "B": "小人當道，懷才不遇", "C": "宦海浮沉，身不由己", "D": "聲聞過實，浪得虛名"}, "answer": "A", "explain": "答案(A)。同一個鄭板橋、同樣的字畫，沒名氣時「無識者」，考中進士出名後卻「戶外履常滿」——人們看的不是作品，而是名聲。「二十年前舊板橋」意思是「我還是二十年前那個板橋」，憤的是世人盲從、只重聲名。(B)文中沒有小人當道；(C)沒有寫官場沉浮；(D)鄭板橋不是覺得自己浪得虛名。", "skill": "找人物情緒的原因：比較事件前後的『反差』（無識者→爭索），反差背後的不合理就是他憤慨的對象。"}], "difficulty": "易", "label": "108學測", "year": 108, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc108-6", "exam": "xc108", "nums": [6], "form": "單題", "img": "img/xc108-6.png", "source": "劉義慶《世說新語‧捷悟》、孔平仲《續世說‧捷悟》", "author": "劉義慶、孔平仲", "genre": "筆記小品", "types": ["文意推論", "比較閱讀"], "passage": "甲、楊德祖為魏武主簿，時作相國門，始搆榱桷，魏武自出看，使人題門作「活」字便去。楊見，即令壞之。既竟，曰：「門中『活』，『闊』字，王正嫌門大也。」（《世說新語‧捷悟》）乙、梁蕭琛醉伏於御筵，武帝以棗投之，琛取栗擲上，正中面。帝動色，琛曰：「陛下投臣以赤心，臣敢不報以戰慄。」上大悅。（《續世說‧捷悟》）", "translation": "甲、楊德祖（楊修）擔任魏武帝曹操的主簿，當時正在建相國府的大門，剛架好屋椽，曹操親自出來看，叫人在門上寫一個「活」字就走了。楊修看到，立刻叫人把門拆掉。拆完後說：「門中加一個『活』字，就是『闊』字，魏王正是嫌門太大了。」\n乙、梁朝蕭琛在御宴上喝醉趴著，梁武帝拿棗子丟他，蕭琛拿起栗子丟回去，正好打中武帝的臉。武帝變了臉色，蕭琛說：「陛下拿赤心（紅棗）投給臣，臣怎敢不報以戰慄（栗子）。」武帝非常高興。", "keywords": [{"w": "主簿", "m": "掌管文書的官"}, {"w": "榱桷", "m": "屋椽"}, {"w": "動色", "m": "變了臉色"}, {"w": "赤心", "m": "紅棗／忠心（雙關）"}, {"w": "戰慄", "m": "栗子／恐懼發抖（雙關）"}], "questions": [{"n": 6, "qtype": "單選", "stem": "依據甲、乙二文，最符合文意的解說是：", "options": {"A": "楊德祖透過文字部件的組合方式，察覺魏武諷其好大喜功", "B": "蕭琛運用諧音雙關，將宴會上失禮的行為解釋為恭敬之舉", "C": "楊德祖與蕭琛皆善於揣摩逢迎，洞悉主上言行背後的暗示", "D": "楊德祖急中生智未讓主上失望，蕭琛大智若愚令主上激賞"}, "answer": "B", "explain": "答案(B)。蕭琛把栗子丟到皇帝臉上，本來很失禮，他用諧音雙關：棗是「赤心」、栗是「戰慄」，把失禮說成「您對我真心，我敬畏戰慄回報」，所以武帝大悅，(B)正確。(A)「門中活」是「闊」字，曹操嫌門太大，並沒有諷刺楊修好大喜功。(C)蕭琛是機智化解失禮，不是揣摩主上暗示。(D)楊修是看懂字謎，不是急中生智；蕭琛是急中生智，不是大智若愚。", "skill": "機智故事題：先弄清楚『難題是什麼』（甲：猜字謎；乙：化解失禮），再看主角用什麼方法（拆字、諧音），就能判斷選項。"}], "difficulty": "易", "label": "108學測", "year": 108, "kind": "學測", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "世說新語選"}, {"id": "xc108-7", "exam": "xc108", "nums": [7], "form": "單題", "img": "img/xc108-7.png", "source": "蘇軾〈淨因院畫記〉", "author": "蘇軾", "genre": "說理議論", "types": ["文意推論", "主旨寓意"], "passage": "余嘗論畫，以為人禽宮室器用皆有常形。至於山石竹木、水波煙雲，雖無常形而有常理。常形之失，人皆知之。常理之不當，雖曉畫者有不知。故凡可以欺世而取名者，必託於無常形者也。雖然，常形之失，止於所失，而不能病其全，若常理之不當，則舉廢之矣。以其形之無常，是以其理不可不謹也。世之工人，或能曲盡其形，而至於其理，非高人逸才不能辨。", "translation": "我曾經評論繪畫，認為人物、禽鳥、宮殿、器物都有固定的形體。至於山石竹木、水波煙雲，雖然沒有固定形體，卻有固定的道理。形體畫錯了，人人都看得出來；道理不恰當，即使懂畫的人也有看不出來的。所以凡是想欺騙世人來博取名聲的人，一定借助沒有固定形體的東西來畫。雖然如此，形體畫錯了，只錯在那一處，不會影響全畫；如果道理不恰當，整幅畫就毀了。正因為它的形體不固定，所以它的道理不能不謹慎。世上的畫匠，有的能把形體畫得非常細緻，但說到其中的道理，不是高人逸士就無法分辨。", "keywords": [{"w": "常形", "m": "固定的形體"}, {"w": "常理", "m": "固定的道理、內在規律"}, {"w": "病", "m": "損害（動詞）"}, {"w": "舉廢", "m": "全部廢棄"}, {"w": "曲盡", "m": "委婉詳盡地表現"}], "questions": [{"n": 7, "qtype": "單選", "stem": "依據下文，不符合文意的解說是：", "options": {"A": "畫作成敗的關鍵，往往在於常理得當與否", "B": "常形失誤，較常理失當容易被一般人發現", "C": "欺世盜名的畫作，往往以無常形之物掩飾不足", "D": "高逸者多繪山石竹木、水波煙雲，故能辨常理"}, "answer": "D", "explain": "答案(D)。題目問「不符合」。原文說畫匠或許能畫出形，但說到理「非高人逸才不能辨」，意思是只有高人才能分辨常理，並沒有說高人多畫山石竹木、水波煙雲，也沒有因果關係，所以(D)錯。(A)常理不當則「舉廢之」，常形之失只「止於所失」，可見成敗關鍵在常理，正確。(B)「常形之失，人皆知之；常理之不當，雖曉畫者有不知」，正確。(C)「欺世而取名者，必託於無常形者」，正確。", "skill": "選項若出現原文沒有的『故』『因此』，就要檢查原文是否真有這個因果關係。"}], "difficulty": "中", "label": "108學測", "year": 108, "kind": "學測", "textcat": "延伸", "textcat2": "學術文本", "linked_core": "赤壁賦"}, {"id": "xc108-13", "exam": "xc108", "nums": [13, 14], "form": "題組", "img": "img/xc108-13.png", "source": "張曉風〈這些芒果，是偷來的嗎？〉（甲，白話）；歸有光〈項脊軒志〉（乙）", "author": "歸有光", "genre": "其他", "types": ["比較閱讀", "人物情感", "寫作手法"], "passage": "余既為此志，後五年，吾妻來歸，時至軒中，從余問古事，或憑几學書。吾妻歸寧，述諸小妹語曰：「聞姊家有閤子，且何謂閤子也？」其後六年，吾妻死，室壞不修。其後二年，余久臥病無聊，乃使人復葺南閤子，其制稍異於前。然自後余多在外，不常居。庭有枇杷樹，吾妻死之年所手植也，今已亭亭如蓋矣。", "translation": "我寫完這篇記以後，過了五年，妻子嫁過來，時常到軒中，向我請教古代的事，有時靠著桌子學寫字。妻子回娘家，轉述她妹妹們的話說：「聽說姊姊家有個閣子，什麼叫閣子呢？」又過了六年，妻子去世，屋子破了也沒修。再過兩年，我久病無聊，就叫人重新修整南閣子，格局和以前稍有不同。但此後我多半在外地，不常住在這裡。庭院裡有一棵枇杷樹，是妻子去世那年親手種的，如今已經高高挺立，枝葉像車蓋一樣了。", "keywords": [{"w": "來歸", "m": "出嫁過來"}, {"w": "歸寧", "m": "回娘家"}, {"w": "閤子", "m": "小閣樓"}, {"w": "葺", "m": "修補"}, {"w": "亭亭如蓋", "m": "高挺直立，枝葉茂密如車蓋"}], "questions": [{"n": 13, "qtype": "單選", "stem": "下列有關甲、乙二文中「故居」的敘述，最適當的是：", "options": {"A": "二文皆是作者離鄉多年後，偶爾回故居暫住的憶往之作", "B": "二文皆透過作者與親人昔日在故居中的對話，表達對親人已逝的傷懷", "C": "甲文的「重返故居」顯示思親之切，乙文的「室壞不修」暗示作者尚未走出喪妻之痛", "D": "甲文直接指出作者與家人曾同住故居62年，乙文則以「五年」、「六年」揭示作者與妻曾同住故居11年"}, "answer": "C", "explain": "答案(C)。甲文作者特地跑回已經不屬於自己的故宅摘芒果，「來重溫我猶暖的對雙親的感念」，顯示思親之切；乙文妻子死後「室壞不修」，連屋子都無心整理，暗示還走不出喪妻之痛。(A)甲文作者只是去摘芒果，沒有暫住；乙文作者後來重修閣子，但「多在外，不常居」，也不是「離鄉多年偶爾回來暫住」的憶往。(B)甲文的對話是父親對母親說的，乙文是妻子轉述小妹的話，都不是作者與親人的對話。(D)甲文62年是家裡擁有宿舍的時間，作者後來住臺北，不能說同住62年；乙文妻子嫁來後六年就過世，同住不是11年。", "skill": "比較題的數字選項要自己算一遍，並確認數字指的是什麼（擁有宿舍的時間≠同住時間）。"}, {"n": 14, "qtype": "單選", "stem": "「樹」在甲、乙二文中的意義，最適當的解說是：", "options": {"A": "甲文的芒果樹象徵父母安康", "B": "乙文的枇杷樹象徵思念長存", "C": "二文作者皆於親人亡故後「植樹」紀念", "D": "二文皆透過「樹在人去」領悟生死有命"}, "answer": "B", "explain": "答案(B)。乙文枇杷樹是「吾妻死之年所手植」，如今「亭亭如蓋」，樹越長越大，人卻已不在，象徵思念隨時間長存，(B)正確。(A)甲文芒果樹是故宅的樹，作者藉吃芒果懷念雙親，不是象徵父母安康。(C)甲文的芒果樹不是父母死後種的；乙文是妻子生前親手種的，不是作者紀念而種。(D)兩文都在抒發思念，沒有「領悟生死有命」。", "skill": "『樹在人亡』是常見寫法：樹的成長＝時間的流逝＝思念的累積。看清楚樹是誰、何時種的。"}], "difficulty": "中", "label": "108學測", "year": 108, "kind": "學測", "textcat": "部定古文", "textcat2": "文學文本", "linked_core": "項脊軒志"}, {"id": "xc108-15", "exam": "xc108", "nums": [15, 16, 17], "form": "題組", "img": "img/xc108-15.png", "source": "潘耒〈徐霞客遊記序〉", "author": "潘耒", "genre": "書信序跋", "types": ["文意推論", "主旨寓意", "比較閱讀"], "passage": "文人達士，多喜言遊。遊未易言也，……淺遊不奇，便遊不暢，群遊不久，自非置身物外，棄絕百事，而孤行其意，雖遊猶弗遊也。余覽往昔諸名人遊記，驗諸目覩身經，知其皆嘗一臠，披一節，略涉門庭，鮮窺閫奧。……霞客之遊，在中州者無大過人；其奇絕者，閩粵楚蜀滇黔，百蠻荒徼之區，皆往返再四。其行不從官道，但有名勝，輒迂迴屈曲以尋之；先審視山脈如何去來，水脈如何分合，既得大勢後，一丘一壑，支搜節討。登不必有徑，荒榛密箐，無不穿也。……記文排日編次，直敘情景，未嘗刻畫為文。……故吾於霞客之遊，不服其闊遠，而服其精詳；於霞客之書，不多其博辨，而多其真實。……霞客果何所為？夫惟無所為而為，故志專；志專，故行獨；行獨，故去來自如，無所不達。意造物者不欲使山川靈異久祕不宣，故生斯人以揭露之耶？", "translation": "文人雅士大多喜歡談旅遊。但旅遊不是容易談的……遊得淺就不奇特，遊得方便就不暢快，成群結隊地遊就不能持久。如果不能置身事外、拋開一切事務、獨自堅持自己的心意，即使遊了也等於沒遊。我讀以前許多名人的遊記，再用自己親眼所見、親身經歷來驗證，知道他們都只是嘗了一塊肉、翻了一節書，只在門口走走，很少看到深處。……徐霞客的遊歷，在中原地區的並沒有大大勝過別人；他奇特超絕的，是福建、廣東、湖南湖北、四川、雲南、貴州這些偏遠蠻荒的地區，都來回好幾次。他走路不走官道，只要有名勝，就繞遠路曲折地去找；先觀察山脈怎麼來去、水脈怎麼分合，掌握大勢後，再把每座山丘、每條溝壑仔細搜尋探討。登山不一定要有路，荒草密竹，沒有穿不過去的。……遊記按日期編排，直接敘述情景，從不刻意雕琢文字。……所以我對徐霞客的遊歷，不佩服它的遼闊遙遠，而佩服它的精細詳盡；對徐霞客的書，不推崇它的廣博善辯，而推崇它的真實。……徐霞客到底為了什麼？正因為沒有目的而做，所以志向專一；志向專一，所以能獨自前行；獨自前行，所以來去自如，沒有到不了的地方。想來是造物者不願讓山川的神奇長久隱藏，所以生下這個人來揭露它吧？", "keywords": [{"w": "嘗一臠", "m": "只嘗一塊肉，比喻淺嘗即止"}, {"w": "閫奧", "m": "深處（題目注為幽深的山林）"}, {"w": "荒徼", "m": "偏遠的邊境"}, {"w": "支搜節討", "m": "一枝一節地仔細搜尋探究"}, {"w": "箐", "m": "大竹林"}, {"w": "排日編次", "m": "按日期編排"}, {"w": "多", "m": "推崇、稱讚（動詞）"}], "questions": [{"n": 15, "qtype": "單選", "stem": "依據上文，不符合作者想法的是：", "options": {"A": "便遊、群遊與淺遊，屬嘗一臠披一節式的遊覽", "B": "欣賞徐霞客的邊疆之記，更勝於他的中原之錄", "C": "徐霞客按日期先後記錄，真實與精詳是其優點", "D": "徐霞客以華藻曲筆狀寫情景，揭露造物的奇祕"}, "answer": "D", "explain": "答案(D)。題目問「不符合」。原文說徐霞客的遊記「直敘情景，未嘗刻畫為文」，不用華麗的文辭，所以(D)「以華藻曲筆狀寫情景」錯。(A)作者說「淺遊不奇，便遊不暢，群遊不久」，而一般名人遊記「嘗一臠，披一節」，正確。(B)「在中州者無大過人；其奇絕者，閩粵楚蜀滇黔」，可見更欣賞他邊疆的記錄，正確。(C)「排日編次」「服其精詳」「多其真實」，正確。", "skill": "『不符合』題，找與原文用詞『剛好相反』的選項（未嘗刻畫↔華藻曲筆）。"}, {"n": 16, "qtype": "單選", "stem": "下列文句，最符合上文「其行不從官道」、「登不必有徑」的是：", "options": {"A": "山行六七里，漸聞水聲潺潺，而瀉出於兩峰之間者，釀泉也。峰回路轉，有亭翼然臨於泉上者，醉翁亭也", "B": "由斷橋至蘇堤一帶，綠煙紅霧，彌漫二十餘里。歌吹為風，粉汗為雨，羅紈之盛，多於堤畔之草，豔冶極矣", "C": "今年九月二十八日，因坐法華西亭，望西山，始指異之。遂命僕過湘江，緣染溪，斫榛莽，焚茅茷，窮山之高而止", "D": "暮春之初，會於會稽山陰之蘭亭，脩禊事也。群賢畢至，少長咸集。此地有崇山峻嶺，茂林脩竹，又有清流激湍，映帶左右"}, "answer": "C", "explain": "答案(C)。「其行不從官道」「登不必有徑」是不走現成的路、自己開路深入。(C)柳宗元「過湘江，緣染溪，斫榛莽，焚茅茷，窮山之高而止」——砍掉雜草、燒掉茅草開路，一路登到山頂，最符合。(A)醉翁亭有路可循，「峰回路轉」就到；(B)袁宏道寫西湖斷橋到蘇堤遊人如織，走的是熱門路線；(D)蘭亭雅集描寫環境，沒有開路探險。", "skill": "文言相似情境題：把題目關鍵句翻成具體動作（自己開路），再找選項中有相同動作的動詞（斫、焚、窮）。"}, {"n": 17, "qtype": "單選", "stem": "某旅行社打算推出仿徐霞客行旅的套裝行程，下列文案最接近其行遊精神的是：", "options": {"A": "一步一腳印走入隱世祕境，在人際交流中發現世界，盡嘗家與人情的味道", "B": "沿縣道公路深入風景勝地，登高盡攬海天一色，文青族、背包客一網打盡", "C": "世界上不缺少美，只是缺少發現，專業背包客帶您在田園裡與自我心靈對話", "D": "專攻高端背包客，不走常規景點，壯遊千里探祕勝，在冒險中尋找自我肯定"}, "answer": "D", "explain": "答案(D)。徐霞客的精神是「不從官道」、走偏遠「百蠻荒徼」、「孤行其意」、深入探勝。(D)「不走常規景點，壯遊千里探祕勝，在冒險中尋找自我肯定」最接近。(A)「在人際交流中發現世界」不合「孤行其意」；(B)「沿縣道公路」正好是走官道；(C)「在田園裡與自我心靈對話」偏向悠閒休憩，不是探險深入。", "skill": "應用題：先列出原文人物的2～3個關鍵特質（不走官道、深入荒僻、獨行），選項必須全部符合、不能有相反條件。"}], "difficulty": "中", "label": "108學測", "year": 108, "kind": "學測", "textcat": "學術文本", "textcat2": "生活情境文本", "linked_core": ""}, {"id": "xc108-31", "exam": "xc108", "nums": [31, 32], "form": "題組", "img": "img/xc108-31.png", "source": "方孝孺〈越巫〉", "author": "方孝孺", "genre": "寓言故事", "types": ["人物情感", "寫作手法", "主旨寓意"], "passage": "越巫自詭善驅鬼物。人病，立壇場，鳴角振鈴。跳擲叫呼，為胡旋舞，禳之。病幸已，饌酒食，持其貲去，死則諉以它故，終不自信其術之妄。恆誇人曰：「我善治鬼，鬼莫敢我抗。」惡少年慍其誕，瞷其夜歸，分五六人棲道旁木上，相去各里所，候巫過，下砂石擊之。巫以為真鬼也，即旋其角，且角且走，心大駭，首岑岑加重，行不知足所在。稍前，駭頗定，木間砂亂下如初，又旋而角；角不能成音，走愈急。復至前，復如初，手慄氣懾不能角，角墜；振其鈴，既而鈴墜，惟大叫以行。行聞履聲及葉鳴谷響，亦皆以為鬼號，求救於人甚哀。夜半抵家，大哭叩門，其妻問故，舌縮不能言，惟指床曰：「亟扶我寢，我遇鬼，今死矣！」扶至床，膽裂，死，膚色如藍。巫至死不知其非鬼。", "translation": "越地有個巫師，假稱自己擅長驅趕鬼怪。有人生病，他就設立祭壇，吹號角、搖鈴鐺，跳躍叫喊，跳胡旋舞，來消災祈福。病人僥倖好了，他就大吃大喝，拿了錢財走人；病人死了，就推說是別的原因，始終不承認自己的法術是假的。他常對人誇口：「我擅長治鬼，鬼不敢反抗我。」一群不良少年痛恨他的荒誕，趁他晚上回家，分成五六個人躲在路旁的樹上，彼此相隔大約一里，等巫師經過，就丟沙石打他。巫師以為真的有鬼，立刻吹起號角，一邊吹一邊跑，心裡非常害怕，頭昏腦脹越來越重，走路都不知道腳放在哪裡。走了一段，驚恐稍微平定，樹間的沙子又像先前一樣亂丟下來，他又吹號角，號角吹不成聲，跑得更急。再往前，又是一樣，手發抖、氣都喘不過來，吹不了號角，號角掉了；改搖鈴，鈴也掉了，只能大叫著走。走路時聽到自己的腳步聲、樹葉聲、山谷回音，都以為是鬼在叫，向人求救，叫得很可憐。半夜到家，大哭敲門，妻子問怎麼了，他舌頭縮著說不出話，只指著床說：「快扶我睡，我遇到鬼了，現在要死了！」扶到床上，嚇破了膽，死了，皮膚發青。巫師到死都不知道那不是鬼。", "keywords": [{"w": "自詭", "m": "自己假稱"}, {"w": "禳", "m": "祈福消災"}, {"w": "諉", "m": "推託"}, {"w": "慍", "m": "惱怒"}, {"w": "瞷", "m": "窺伺"}, {"w": "里所", "m": "一里左右"}, {"w": "岑岑", "m": "煩悶、頭昏脹"}, {"w": "懾", "m": "恐懼"}], "questions": [{"n": 31, "qtype": "單選", "stem": "依據上文，對於越巫形象的描寫，最適當的是：", "options": {"A": "仗恃靈力，脅制鄉里", "B": "惡行易改，心魔難除", "C": "設壇召魅，作法自斃", "D": "無知自是，誤人害己"}, "answer": "D", "explain": "答案(D)。越巫「終不自信其術之妄」「至死不知其非鬼」——無知又自以為是；他假裝能治鬼，騙病人家屬錢財，害了別人，最後自己被嚇死，正是「無知自是，誤人害己」。(A)他只是騙錢，沒有脅迫控制鄉里；(B)文中沒有說他改過惡行；(C)他是設壇「驅」鬼，不是「召」鬼，最後是被少年嚇死，不是作法自斃。", "skill": "人物形象題：從文首（自詭、終不自信其術之妄）和文末（至死不知）兩處抓作者給的定評。"}, {"n": 32, "qtype": "單選", "stem": "關於上文的寫作手法與文意，敘述最適當的是：", "options": {"A": "以「相去各里所」暗示少年們對越巫心存畏怯，彼此守望照應", "B": "以「即旋其角」、「角不能成音」、「手慄氣懾不能角」描寫越巫因又懼又急而法力愈加減弱", "C": "以「且角且走」、「角墜；振其鈴，既而鈴墜，惟大叫以行」表現越巫從試圖自欺到心神失控的狼狽", "D": "以「行聞履聲及葉鳴谷響，亦皆以為鬼號」凸顯越巫仍想藉由周遭聲響研判鬼的行蹤，求得活命機會"}, "answer": "C", "explain": "答案(C)。「且角且走」是邊吹號角邊跑，還想用法術給自己壯膽（自欺）；接著號角掉、鈴也掉，「惟大叫以行」，完全失控，(C)正確。(A)少年們相隔一里左右，是為了一路接連嚇他，不是畏怯互相照應。(B)越巫本來就沒有法力，「角不能成音」寫的是他越來越害怕，不是法力減弱。(D)他把所有聲音都當成鬼叫，是驚恐過度，不是冷靜研判鬼的行蹤。", "skill": "寫作手法題：把一連串動作排成『層層遞進』（吹角→角不成音→角墜→鈴墜→大叫），想想作者要表現的是什麼變化。"}], "difficulty": "中", "label": "108學測", "year": 108, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc108-33", "exam": "xc108", "nums": [33, 34], "form": "題組", "img": "img/xc108-33.png", "source": "羅大經〈能言鸚鵡〉（《鶴林玉露》）", "author": "羅大經", "genre": "筆記小品", "types": ["主旨寓意", "比較閱讀"], "passage": "上蔡先生云：「透得名利關，方是小歇處。今之士大夫何足道，真能言之鸚鵡也。」朱文公曰：「今時秀才，教他說廉，直是會說廉；教他說義，直是會說義。及到做來，只是不廉不義。」此即能言鸚鵡也。夫下以言語為學，上以言語為治，世道之所以日降也。而或者見能言之鸚鵡，乃指為鳳凰、鸑鷟，唯恐其不在靈囿間，不亦異乎!", "translation": "上蔡先生（謝良佐）說：「能看透名利這一關，才算是稍可歇腳的地方。現在的士大夫有什麼值得一提？真是會說話的鸚鵡罷了。」朱熹說：「現在的讀書人，教他講廉潔，真的很會講廉潔；教他講道義，真的很會講道義。等到真的去做，卻是不廉不義。」這就是會說話的鸚鵡。在下位的人把說話當學問，在上位的人把說話當治理，這就是世道一天天衰落的原因。而有些人看到會說話的鸚鵡，竟然把牠當成鳳凰、鸑鷟這類神鳥，唯恐牠不在皇家園林裡，不也很奇怪嗎？", "keywords": [{"w": "透得", "m": "看透、突破"}, {"w": "直是", "m": "真是、確實"}, {"w": "日降", "m": "一天天衰落"}, {"w": "鸑鷟", "m": "鳳凰一類的神鳥"}, {"w": "靈囿", "m": "帝王的園林"}], "questions": [{"n": 33, "qtype": "單選", "stem": "依據上文，今日世風之弊在於：", "options": {"A": "豢養珍禽，玩物喪志", "B": "模仿剽竊，寡廉鮮恥", "C": "蔽於表象，不辨虛實不務踐履", "D": "器識褊狹，唯學鸚鵡不慕鳳凰"}, "answer": "C", "explain": "答案(C)。作者批評兩件事：一是讀書人只會說不會做——「教他說廉，直是會說廉……及到做來，只是不廉不義」，也就是不務踐履；二是有人把會說話的鸚鵡當成鳳凰——被表象蒙蔽、不辨虛實。(C)兩點都說到了。(A)鸚鵡是比喻，不是真的在養珍禽；(B)文中沒有說模仿剽竊；(D)作者不是批評人「只學鸚鵡不慕鳳凰」，而是批評人把鸚鵡誤認為鳳凰。", "skill": "比喻型文章先把喻體還原：鸚鵡＝只會說的人，鳳凰＝真正的賢才，選項若停留在字面（養鳥）就錯。"}, {"n": 34, "qtype": "單選", "stem": "下列文句，最能呼應上文觀點的是：", "options": {"A": "君子欲訥於言而敏於行", "B": "寡言者可以杜忌，寡行者可以藏拙", "C": "言行，君子之樞機，樞機之發，榮辱之主也", "D": "聽言觀行，不以功用為之的彀，言雖至察，行雖至堅，則妄發之說也"}, "answer": "A", "explain": "答案(A)。文章批評「能說不能做」，主張言要落實為行。(A)孔子「君子欲訥於言而敏於行」——說話謹慎遲鈍、做事勤快敏捷，最能呼應。(B)講少說少做可以避禍藏拙，是處世保身；(C)講言行是君子榮辱的關鍵，沒有特別強調重行輕言；(D)韓非子主張用實際功效來檢驗言行，重點在『功用』標準，不是批評光說不做。", "skill": "呼應題：先用自己的話寫出文章主張（重行不重言），再找選項中『言』『行』輕重關係相同的句子。"}], "difficulty": "中", "label": "108學測", "year": 108, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc108-35", "exam": "xc108", "nums": [35], "form": "單題", "img": "img/xc108-35.png", "source": "范仲淹〈岳陽樓記〉、《史記‧鴻門宴》、劉基〈工之僑獻琴〉、屈原〈漁父〉、《聊齋誌異‧勞山道士》、全祖望〈梅花嶺記〉、蘇軾〈赤壁賦〉、魏徵〈諫太宗十思疏〉、黃宗羲〈原君〉等", "author": "多家", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)去國懷鄉，憂讒畏譏／欲呼張良與俱去\n(B)斫而為琴，弦而鼓之／何故深思高舉，自令放為\n(C)叩而與語，理甚玄妙／叩之寺僧，則史公可法也\n(D)蘇子愀然，正襟危坐而問客／念高危，則思謙沖而自牧\n(E)奢貴自奉，禮異人臣／離散天下之子女，以奉我一人之淫樂", "translation": "(A)離開國都、懷念家鄉，擔心讒言、害怕譏諷／想叫張良和他一起離開。(B)砍下來做成琴，裝上弦來彈奏／為什麼要想得那麼深、行為那麼高潔，讓自己被放逐呢？(C)向他叩拜並和他交談，道理非常玄妙／向寺裡的和尚打聽，原來是史可法。(D)蘇子臉色變得嚴肅，整理衣襟端正坐好問客人／想到自己地位高而危險，就要謙虛自我修養。(E)奢侈富貴地供養自己，禮儀和一般臣子不同／拆散天下人的子女，來供養我一個人的淫樂。", "keywords": [{"w": "去", "m": "離開"}, {"w": "為", "m": "做成；被"}, {"w": "叩", "m": "叩拜；詢問"}, {"w": "危", "m": "端正；危險"}, {"w": "奉", "m": "供養、供給"}], "questions": [{"n": 35, "qtype": "多選", "stem": "下列各組文句「」內的詞，前後意義相同的是：", "options": {"A": "「去」國懷鄉，憂讒畏譏／欲呼張良與俱「去」", "B": "斫而「為」琴，弦而鼓之／何故深思高舉，自令放「為」", "C": "「叩」而與語，理甚玄妙／「叩」之寺僧，則史公可法也", "D": "蘇子愀然，正襟「危」坐而問客／念高「危」，則思謙沖而自牧", "E": "奢貴自「奉」，禮異人臣／離散天下之子女，以「奉」我一人之淫樂"}, "answer": "AE", "explain": "答案(A)(E)。(A)兩個「去」都是「離開」：離開國都／和張良一起離開。(E)兩個「奉」都是「供養、供給」：奢侈地供養自己／供養我一人的淫樂。(B)前「為琴」是「做成」，後「自令放為」的「為」是「被」。(C)前「叩而與語」是「叩拜」，後「叩之寺僧」是「詢問」。(D)前「危坐」是「端正」，後「高危」是「高而危險」。", "skill": "注意「為」放在句尾、動詞後（放為、見笑為）常是『被』；「危坐」固定指端坐。"}], "difficulty": "中", "label": "108學測", "year": 108, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "漁父、鴻門宴、諫太宗十思疏、岳陽樓記、赤壁賦、郁離子選、原君、勞山道士"}, {"id": "xc108-37", "exam": "xc108", "nums": [37], "form": "單題", "img": "img/xc108-37.png", "source": "鄭用錫〈勸和論〉、李斯〈諫逐客書〉、顧炎武〈廉恥〉、連橫〈臺灣通史序〉、丘遲〈與陳伯之書〉", "author": "多家", "genre": "其他", "types": ["虛詞句式", "句意理解"], "passage": "(A)天地有好生之德，人心無不轉之時\n(B)此五子者，不產於秦，而繆公用之\n(C)松柏後凋於歲寒，雞鳴不已於風雨\n(D)（連）橫不敏，昭告神明，發誓述作，兢兢業業，莫敢自遑\n(E)朱鮪涉血於友于，張繡剚刃於愛子，漢主不以為疑，魏君待之若舊", "translation": "(A)天地有愛惜生命的德性，人心沒有不能回轉的時候。(B)這五個人都不是秦國人，秦穆公卻任用他們。(C)松柏在嚴寒中最後凋零，雞在風雨中仍啼叫不停。(D)我連橫雖然不聰明，仍向神明禱告，發誓寫作，戰戰兢兢，不敢讓自己閒下來。(E)朱鮪殺了漢光武帝的哥哥，張繡殺了曹操的愛子，光武帝卻不懷疑朱鮪，曹操對待張繡仍像從前一樣。", "keywords": [{"w": "不敏", "m": "不聰明（謙詞）"}, {"w": "自遑", "m": "自己閒暇"}, {"w": "友于", "m": "兄弟"}, {"w": "剚刃", "m": "用刀刺殺"}], "questions": [{"n": 37, "qtype": "多選", "stem": "〈馮諼客孟嘗君〉：「梁使三反，孟嘗君固辭不往也」，前、後句有「縱使……卻依然……」的語意邏輯關係，意指「孟嘗君固辭不往」這件事，縱使「梁使三反」也不會改變。下列文句畫實線與虛線處，具有相同語意邏輯關係的是：（畫線位置見截圖）", "options": {"A": "天地有好生之德，人心無不轉之時", "B": "此五子者，不產於秦，而繆公用之", "C": "松柏後凋於歲寒，雞鳴不已於風雨", "D": "（連）橫不敏，昭告神明，發誓述作，兢兢業業，莫敢自遑", "E": "朱鮪涉血於友于，張繡剚刃於愛子，漢主不以為疑，魏君待之若舊"}, "answer": "BDE", "explain": "答案(B)(D)(E)。(B)縱使五子「不產於秦」，秦穆公卻依然任用他們。(D)縱使「橫不敏」（自己不聰明），卻依然「昭告神明，發誓述作」。(E)縱使朱鮪、張繡殺了對方的親人，漢光武、曹操卻依然不懷疑、待之如舊。(A)前後是並列的兩件道理，沒有讓步轉折。(C)「松柏後凋於歲寒」和「雞鳴不已於風雨」是兩個並列的比喻，畫線處之間沒有「縱使……依然」的關係。", "skill": "讓步轉折句的判斷：在前句加『縱使』、後句加『卻依然』，讀起來合理，且後句結果和前句條件相反，就是這種關係。"}], "difficulty": "中", "label": "108學測", "year": 108, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "諫逐客書、馮諼客孟嘗君、與陳伯之書、廉恥、勸和論、臺灣通史序"}, {"id": "xc108-38", "exam": "xc108", "nums": [38], "form": "單題", "img": "img/xc108-38.png", "source": "陸游《老學庵筆記》", "author": "陸游", "genre": "筆記小品", "types": ["文意推論", "寫作手法", "文化常識"], "passage": "甲、田登作郡，自諱其名，觸者必怒，吏卒多被榜笞。於是舉州皆謂燈為火。上元放燈，許人入州治遊觀，吏人遂書榜揭於市曰：「本州依例放火三日。」乙、今人謂賤丈夫曰漢子，蓋始於五胡亂華時。北齊魏愷自散騎常侍遷青州長史，固辭之。宣帝大怒，曰：「何物漢子，與官不受！」此其證也。承平日，有宗室名宗漢，自惡人犯其名，謂漢子曰兵士，舉宮皆然。其妻供羅漢，其子授漢書，宮中人曰：「今日夫人召僧供十八大阿羅兵士，大保請官教點兵士書。」都下鬨然傳以為笑。", "translation": "甲、田登當州官，避諱自己的名字，觸犯的人他一定發怒，很多吏卒被他鞭打。於是全州的人都把「燈」叫做「火」。元宵節放燈，准許百姓進入州府遊覽，官吏就寫了告示貼在市集上：「本州依照慣例放火三天。」\n乙、現在人們把卑賤的男子叫做「漢子」，大概始於五胡亂華的時候。北齊魏愷由散騎常侍調任青州長史，堅決推辭。文宣帝大怒說：「什麼漢子，給官都不接受！」這就是證據。太平時，有個宗室名叫宗漢，討厭別人觸犯他的名字，把「漢子」叫做「兵士」，全宮都這樣。他的妻子供奉羅漢，他的兒子讀《漢書》，宮中的人就說：「今天夫人請和尚來供奉十八大阿羅兵士，大保請老師教讀兵士書。」京城的人哄然傳為笑談。", "keywords": [{"w": "諱", "m": "避諱"}, {"w": "榜笞", "m": "鞭打"}, {"w": "榜", "m": "告示"}, {"w": "賤丈夫", "m": "卑賤的男子"}, {"w": "鬨然", "m": "眾人大笑貌"}], "questions": [{"n": 38, "qtype": "多選", "stem": "關於下列陸游《老學庵筆記》二則引文，敘述適當的是：", "options": {"A": "「吏卒多被榜笞」，是違反田登禁忌的下場", "B": "書榜「本州依例放火三日」，表示吏人已經避開田登名諱", "C": "宗漢不喜他人觸犯名諱，乃因「漢子」一詞在當時含有貶義", "D": "「舉州皆謂燈為火」、「舉宮皆然」，顯示州民、宮人欣然認同避諱", "E": "選用避諱之例，如「放火」、「十八大阿羅兵士」、「兵士書」，應寓有嘲諷之意"}, "answer": "ABCE", "explain": "答案(A)(B)(C)(E)。(A)「觸者必怒，吏卒多被榜笞」，被打是因為觸犯田登的名諱，正確。(B)吏人把「放燈」寫成「放火」，就是避開「燈（登）」字，正確。(C)文中先說「漢子」是對卑賤男子的稱呼，所以宗漢討厭別人說「漢子」，正確。(D)州民、宮人是怕被處罰才避諱，「都下鬨然傳以為笑」，不是欣然認同。(E)「放火三日」「十八大阿羅兵士」「兵士書」都荒唐可笑，作者選這些例子是在嘲諷避諱過頭，正確。這也是俗語「只許州官放火，不許百姓點燈」的由來。", "skill": "筆記小品常藉荒謬結果諷刺人事，看到『傳以為笑』這類結尾，就知道作者態度是嘲諷。"}], "difficulty": "易", "label": "108學測", "year": 108, "kind": "學測", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "xc108-39", "exam": "xc108", "nums": [39], "form": "單題", "img": "img/xc108-39.png", "source": "劉禹錫〈臺城〉、謝鯉魚〈鹿耳門懷古〉", "author": "劉禹錫、謝鯉魚", "genre": "古典詩詞曲", "types": ["詩詞賞析", "典故出處", "比較閱讀"], "passage": "甲、臺城六代競豪華，結綺臨春事最奢。萬戶千門成野草，只緣一曲後庭花。（劉禹錫〈臺城〉）\n乙、鹿耳潮落吼聲遲，閱盡興亡眼力疲。惆悵騎鯨人去後，江山今又屬阿誰。（謝鯉魚〈鹿耳門懷古〉）", "translation": "甲、臺城歷經六個朝代，爭相比豪華，陳後主建的結綺閣、臨春閣最奢侈。千門萬戶的宮殿如今都成了野草，只因為一曲〈玉樹後庭花〉。\n乙、鹿耳門潮水退去，濤聲也變得遲緩，看盡了興亡，眼睛都疲倦了。令人惆悵的是騎鯨的鄭成功走了以後，這片江山如今又屬於誰呢？", "keywords": [{"w": "臺城", "m": "六朝宮禁所在"}, {"w": "結綺、臨春", "m": "陳後主所建樓閣"}, {"w": "後庭花", "m": "陳後主〈玉樹後庭花〉，亡國之音"}, {"w": "騎鯨人", "m": "指鄭成功"}, {"w": "阿誰", "m": "誰"}], "questions": [{"n": 39, "qtype": "多選", "stem": "關於下列甲、乙二詩的詩意或作法，敘述適當的是：", "options": {"A": "甲詩譏刺君王耽溺享樂，導致國破家亡", "B": "乙詩藉由自然景觀，寄寓歷史滄桑之感", "C": "二詩均以景物今昔的變化，強化懷古的感傷", "D": "二詩均運用典故，使意象更鮮明、情感更深刻", "E": "二詩均透過刻畫景物，具體呈現詩人移動的蹤跡"}, "answer": "ABD", "explain": "答案(A)(B)(D)。(A)「只緣一曲後庭花」，把亡國歸因於陳後主耽溺聲色，譏刺君王享樂導致國破，正確。(B)藉鹿耳門潮落、濤聲漸緩，寄託看盡興亡的滄桑，正確。(D)甲用「後庭花」典故，乙用鄭成功「騎鯨」傳說，正確。(C)甲有「萬戶千門成野草」的今昔對比，乙卻沒有寫景物今昔的變化。(E)兩首都是定點懷古，沒有寫詩人移動的路線。", "skill": "懷古詩常見三要素：眼前景、歷史典故、興亡感慨；先找出每首詩的典故，再判斷景物有沒有『今昔對照』。"}], "difficulty": "中", "label": "108學測", "year": 108, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc108-40", "exam": "xc108", "nums": [40], "form": "單題", "img": "img/xc108-40.png", "source": "論詞文字（出處待查）", "author": "出處待查", "genre": "說理議論", "types": ["文化常識", "句意理解"], "passage": "五代之詞，止於嘲風弄月，懷土傷離，節促情殷，辭纖韻美。入宋則由令化慢，由簡化繁，情不囿於燕私，辭不限於綺語，上之可尋聖賢之名理，大之可發忠愛之熱忱。", "translation": "五代的詞，只限於吟詠風月、懷念故土、感傷離別，節奏短促而情感濃烈，文辭纖細而韻味優美。到了宋代，就由小令發展為慢詞，由簡短變得繁複，情感不再侷限於宴樂私情，文辭不只限於華美的豔語，往上可以探求聖賢的義理，往大處可以抒發忠君愛國的熱情。", "keywords": [{"w": "令", "m": "小令，短的詞調"}, {"w": "慢", "m": "慢詞，長的詞調"}, {"w": "燕私", "m": "宴飲私情"}, {"w": "綺語", "m": "華麗豔美的言辭"}, {"w": "名理", "m": "義理"}], "questions": [{"n": 40, "qtype": "多選", "stem": "國文課堂上，學生想嘗試從「詞」的文學知識解說下文，下列解說，適當的是：（引文見 passage）", "options": {"A": "五代詞以私情綺語擅場，宋代詞家不復纖辭美韻，崇尚思理，風格弘闊", "B": "五代詞因篇幅短而合音節，宋代詞則因篇幅長而音節漸失，難於演唱", "C": "李煜詞在亡國前多「嘲風弄月」，亡國後則多「懷土傷離」", "D": "蘇軾的詞，可視為「情不囿於燕私，辭不限於綺語」的代表", "E": "在辛棄疾的詞作中，可找到「大之可發忠愛之熱忱」的例子"}, "answer": "CDE", "explain": "答案(C)(D)(E)。(C)李煜亡國前多寫宮廷風月，亡國後多寫故國之思、離別之痛，正好對應「嘲風弄月」「懷土傷離」，正確。(D)蘇軾以詩為詞，題材擴大到懷古、哲理、生活，正是「情不囿於燕私，辭不限於綺語」，正確。(E)辛棄疾詞多抒發恢復中原的愛國熱忱，符合「大之可發忠愛之熱忱」，正確。(A)引文說宋詞「不限於綺語」，是範圍擴大，不是「不復纖辭美韻」（不再有）。(B)引文只說由令化慢、由簡化繁，沒有說宋詞音節漸失、難以演唱。", "skill": "注意『不限於』≠『不再有』：範圍擴大不代表原來的特色消失，這類偷換程度的選項很常見。"}], "difficulty": "中", "label": "108學測", "year": 108, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc108-41", "exam": "xc108", "nums": [41], "form": "單題", "img": "img/xc108-41.png", "source": "《老子》第三十八章、《論語‧陽貨》、吳子良語、《朱子語類》", "author": "老子、孔子、吳子良、朱熹", "genre": "經典語錄", "types": ["比較閱讀", "文意推論", "文化常識"], "passage": "老子：失道而後德，失德而後仁，失仁而後義，失義而後禮。夫禮者，忠信之薄而亂之首。\n孔子：禮云禮云，玉帛云乎哉？樂云樂云，鐘鼓云乎哉？\n吳子良：蓋聃之於禮，尚其意不尚其文，然使文而可廢，則意亦不能獨立矣。此（指「禮者忠信之薄而亂之首」）老子鑑文之弊，而矯枉過正之言也。\n學生：老子云：「夫禮，忠信之薄而亂之首」，孔子又卻問禮於他，不知何故？\n朱熹：他曾為柱下史，故禮自是理會得，所以與孔子說得如此好。只是他又說這箇物事不用得亦可，一似聖人用禮時反若多事，所以如此說。〈禮運〉中「謀用是作，而兵由此起」等語，便自有這箇意思。", "translation": "老子：失去了道才講德，失去了德才講仁，失去了仁才講義，失去了義才講禮。禮，是忠信淡薄的表現，也是禍亂的開端。\n孔子：禮啊禮啊，難道只是指玉帛這些禮物嗎？樂啊樂啊，難道只是指鐘鼓這些樂器嗎？\n吳子良：老子對禮，看重的是它的精神，不看重它的形式；但如果形式可以廢除，精神也無法單獨存在。老子這句話，是看到形式的流弊，而矯枉過正的說法。\n學生：老子說禮是忠信淡薄、禍亂開端，孔子卻又向他問禮，不知道為什麼？\n朱熹：老子曾當過管理典籍的柱下史，所以對禮本來就很懂，因此能和孔子談得這麼好。只是他又說禮這東西不用也可以，好像聖人用禮反而多事，所以才那樣說。〈禮運〉裡「計謀因此產生，戰爭由此興起」這類話，就有這個意思。", "keywords": [{"w": "薄", "m": "淡薄、衰微"}, {"w": "首", "m": "開端"}, {"w": "玉帛", "m": "行禮用的玉器絲帛"}, {"w": "文", "m": "外在形式"}, {"w": "柱下史", "m": "周朝掌管典籍的官"}, {"w": "理會得", "m": "懂得、明白"}], "questions": [{"n": 41, "qtype": "多選", "stem": "韓愈〈師說〉：「孔子師郯子、萇弘、師襄、老聃」，相傳孔子曾問「禮」於老聃。閱讀下列有關老子、孔子論「禮」以及後學的相關討論，選出解釋適當的敘述：", "options": {"A": "依老子的看法，人間若有「道」，便無須用「禮」", "B": "孔子「玉帛云乎哉」的看法，即憂心「禮」僅「尚其意不尚其文」", "C": "吳子良認為：「禮」的形式與內在應為一體，老子有矯枉過正之弊", "D": "吳子良和朱熹都認為：老子對「禮」缺乏深度認知，故評論有失偏頗", "E": "朱熹認為：〈禮運〉所云：「謀用是作，而兵由此起」，與老子對「禮」的看法相似"}, "answer": "ACE", "explain": "答案(A)(C)(E)。(A)老子說「失道而後德……失義而後禮」，禮是道失去之後才出現的，所以有道就不需要禮，正確。(C)吳子良說「使文而可廢，則意亦不能獨立」——形式和精神要合一，並批評老子「矯枉過正」，正確。(E)朱熹說〈禮運〉「謀用是作，而兵由此起」有老子說禮是「亂之首」的意思，正確。(B)孔子「玉帛云乎哉」是擔心禮只剩下玉帛等形式而失去精神，也就是只「尚文」不「尚意」，選項說反了。(D)朱熹說老子「禮自是理會得」，很懂禮，並非缺乏深度認知。", "skill": "多人論述題：為每個人寫一句『對禮的態度』，再逐一核對選項；特別小心「尚意／尚文」這類一字之差的對調。"}], "difficulty": "難", "label": "108學測", "year": 108, "kind": "學測", "textcat": "延伸", "textcat2": "學術文本", "linked_core": "師說"}, {"id": "zk108-05", "exam": "zk108", "nums": [5], "form": "單題", "img": "img/zk108-05.png", "source": "《老子》、《論語》、黃宗羲〈原君〉、《大學》、《荀子‧勸學》、《孫子‧謀攻》、《墨子‧非攻》", "author": "", "genre": "經典語錄", "types": ["句意理解", "比較閱讀"], "passage": "", "translation": "(A)聖人想居於百姓之上，一定言語謙下；想走在百姓前面，一定把自己放在後面。／（為政）要帶頭做在百姓前面，並且自己辛勞。\n(B)不把自己一人的利益當利益，而讓天下人得到利益；不把自己一人的禍害當禍害，而讓天下人免除禍害。／百姓喜歡的就喜歡，百姓厭惡的就厭惡。\n(C)沒有專精沉潛的心志，就沒有顯著的成就；沒有專心致志的努力，就沒有顯赫的功業。／多聽而保留有疑問的，謹慎說其餘有把握的，就少犯錯；多看而保留不安的，謹慎做其餘有把握的，就少後悔。\n(D)攻下別人的城不靠硬攻，滅了別人的國不必久戰，一定用保全的方式爭天下，所以兵力不受損而利益可以保全。／殺十個人是十倍的不義，就該有十個死罪；殺一百人就有一百個死罪。", "keywords": [{"w": "上民", "m": "居於百姓之上"}, {"w": "冥冥、惛惛", "m": "專默精誠、專心致志"}, {"w": "闕疑", "m": "保留有疑問的部分"}, {"w": "頓", "m": "困頓、受損"}], "questions": [{"n": 5, "qtype": "單選", "stem": "下列各組文句，前後意義最相近的是：", "options": {"A": "聖人欲上民，必以言下之；欲先民，必以身後之／先之，勞之", "B": "不以一己之利為利，而使天下受其利；不以一己之害為害，而使天下釋其害／民之所好好之，民之所惡惡之", "C": "無冥冥之志者，無昭昭之明；無惛惛之事者，無赫赫之功／多聞闕疑，慎言其餘，則寡尤；多見闕殆，慎行其餘，則寡悔", "D": "拔人之城而非攻也，毀人之國而非久也，必以全爭於天下，故兵不頓，而利可全／殺十人十重不義，必有十死罪矣；殺百人百重不義，必有百死罪矣"}, "answer": "B", "explain": "(B)前句是黃宗羲〈原君〉說古代君主以天下之利為利；後句是《大學》「民之所好好之，民之所惡惡之」，兩句都在說：在上位者要以百姓的好惡利害為依歸，意思最相近。\n(A)前句是老子主張「謙下、退後」才能領導百姓；後句是《論語》要為政者「率先帶頭、親身勞苦」，一個講退後、一個講帶頭，方向不同。\n(C)前句是《荀子‧勸學》強調專心致志才有成就；後句是《論語》講言行謹慎才少過失，主題不同。\n(D)前句是《孫子》講不戰而全勝的謀略；後句是《墨子‧非攻》譴責殺人越多罪越重，一講用兵策略、一講反戰道德，不同。", "skill": "比較兩句意義時，先用一句白話各自寫出「主張什麼」，再看兩個主張的方向是否一致。"}], "difficulty": "難", "label": "108指考", "year": 108, "kind": "指考", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "勸學、原君"}, {"id": "zk108-10", "exam": "zk108", "nums": [10], "form": "單題", "img": "img/zk108-10.png", "source": "李白〈行路難〉其三", "author": "李白", "genre": "古典詩詞曲", "types": ["主旨寓意", "典故出處", "詩詞賞析"], "passage": "有耳莫洗潁川水，有口莫食首陽蕨。含光混世貴無名，何用孤高比雲月？吾觀自古賢達人，功成不退皆殞身。子胥既棄吳江上，屈原終投湘水濱。陸機雄才豈自保？李斯稅駕苦不早。華亭鶴唳詎可聞？上蔡蒼鷹何足道。君不見吳中張翰稱達生，秋風忽憶江東行。且樂生前一杯酒，何須身後千載名？", "translation": "有耳朵不必像許由那樣到潁水洗耳，有嘴巴不必像伯夷、叔齊那樣在首陽山採蕨充飢。收斂光芒、混跡世間，可貴的是不求名聲，何必用高潔孤傲去和雲月相比？我看自古以來的賢能通達之人，功業成就後不肯退隱的都喪了命。伍子胥被拋屍吳江，屈原終於投身湘水。陸機才華雄偉又怎能保全自己？李斯苦於沒能早點停下腳步。華亭的鶴鳴哪裡還能再聽到？上蔡牽黃犬、架蒼鷹打獵的日子又何足稱道。你沒看到吳中的張翰被稱為通達之人，秋風一起想起家鄉就辭官回江東。姑且享受生前的一杯酒，何必追求死後千年的名聲？", "keywords": [{"w": "潁川水", "m": "許由洗耳的典故，代表避世清高"}, {"w": "首陽蕨", "m": "伯夷叔齊隱居首陽山採蕨"}, {"w": "含光混世", "m": "收斂才華，混同世俗"}, {"w": "稅駕", "m": "解下車駕，指停止、退隱"}, {"w": "殞身", "m": "喪命"}], "questions": [{"n": 10, "qtype": "單選", "stem": "閱讀下列詩句，最符合詩中所示的人生態度是：", "options": {"A": "顯貴無常，急流勇退", "B": "養身隱逸，志在清高", "C": "放浪形骸，任俠行義", "D": "順處逆境，不求顯達"}, "answer": "A", "explain": "全詩用伍子胥、屈原、陸機、李斯「功成不退皆殞身」的例子，對比張翰見秋風就辭官回鄉，勸人看清富貴不長久、要懂得及時抽身，所以是(A)「顯貴無常，急流勇退」。\n(B)詩一開頭就說不必洗耳、採蕨，「何用孤高比雲月」，反對刻意標榜清高。\n(C)詩中沒有放浪形骸或行俠仗義的內容。\n(D)詩的重點是「功成之後要退」，不是講身處逆境時安然自處。", "skill": "詩中連續舉例時，先找這些人物的共同下場（功成不退→殞身），主旨就是避開這個下場的方法。"}], "difficulty": "中", "label": "108指考", "year": 108, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk108-11", "exam": "zk108", "nums": [11], "form": "單題", "img": "img/zk108-11.png", "source": "《淮南子‧人間訓》等", "author": "", "genre": "寓言故事", "types": ["主旨寓意", "比較閱讀"], "passage": "", "translation": "(A)喜鵲預先知道今年多風，就離開高樹，把巢築在低矮的枝條上。結果大人經過就掏走雛鳥，小孩經過就挑走鳥蛋。\n(B)鄭縣人卜子叫妻子做褲子，妻子問：「新褲要做成什麼樣子？」丈夫說：「像我的舊褲子。」妻子就把新褲弄破，做得像舊褲一樣。\n(C)周地有人喜歡皮衣又愛吃美食，想做價值千金的皮衣就去和狐狸商量要牠的皮，想準備羊豬的佳餚就和羊商量要牠的肉。話還沒說完，狐狸成群逃到重重山丘下，羊互相呼喚躲進深林裡。\n(D)從前齊國有個想要金子的人，清早穿戴整齊到市場，走到賣金子的地方，就抓了金子跑。官吏抓到他，問：「大家都在場，你為何搶人金子？」他回答：「拿金子的時候，我沒看見人，只看見金子。」", "keywords": [{"w": "巢扶枝", "m": "在低矮旁枝上築巢"}, {"w": "鷇", "m": "雛鳥"}, {"w": "少牢", "m": "羊、豬二牲的祭品，指美食"}, {"w": "攫", "m": "抓取"}], "questions": [{"n": 11, "qtype": "單選", "stem": "《淮南子‧人間訓》曰：「知備遠難而忘近患」，意指僅知道防備遠處的禍害，卻忽略近處的危機，有失明智。下列選項，最切合上述旨意的是：", "options": {"A": "夫鵲先識歲之多風也，去高木而巢扶枝。大人過之則探鷇，嬰兒過之則挑其卵", "B": "鄭縣人卜子使其妻為褲，其妻問曰：「今褲何如？」夫曰：「像吾故褲。」妻子因毀新，令如故褲", "C": "周人有愛裘而好珍饈，欲為千金之裘而與狐謀其皮，欲具少牢之珍而與羊謀其饈。言未卒，狐相率逃於重丘之下，羊相呼藏於深林之中", "D": "昔齊人有欲金者，清旦衣冠而之市，適鬻金者之所，因攫其金而去。吏捕得之，問曰：「人皆在焉，子攫人之金何？」對曰：「取金之時，不見人，徒見金」"}, "answer": "A", "explain": "題目要找「只防遠處的禍，卻忽略眼前的危險」。(A)喜鵲為了躲避大風（遠難）把巢築低，卻讓人輕易掏走雛鳥和蛋（近患），完全吻合。\n(B)妻子死板照抄舊褲，諷刺拘泥不知變通。\n(C)和狐狸要皮、和羊要肉，諷刺跟利害衝突的對象商量事情（與狐謀皮）。\n(D)搶金子的人只看見金子看不見人，諷刺利令智昏。", "skill": "先把題目給的旨意拆成「A 情況＋B 後果」，再到選項裡找能對上兩個部分的故事。"}], "difficulty": "中", "label": "108指考", "year": 108, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk108-12", "exam": "zk108", "nums": [12], "form": "單題", "img": "img/zk108-12.png", "source": "國學常識：先秦諸子", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [], "questions": [{"n": 12, "qtype": "單選", "stem": "下列關於先秦典籍的敘述，最適當的是：", "options": {"A": "《荀子》文字風格簡淨，宛如格言", "B": "《老子》多長篇大論，善用譬喻說理", "C": "《墨子》文章華美，深具辭采，獨樹一格", "D": "《莊子》想像力豐富，善以寓言傳達哲思"}, "answer": "D", "explain": "(D)《莊子》想像奇特，大量用寓言（如庖丁解牛、鯤鵬）說道理，正確。\n(A)《荀子》多長篇論說文，層層推論，「簡淨如格言」比較像《論語》或《老子》。\n(B)《老子》只有五千多字，句子短、多韻語格言，不是長篇大論。\n(C)《墨子》重實用，文字質樸、少文采，不是「文章華美」。", "skill": "背諸子特色可記成對：論語語錄、老子簡短韻語、孟子雄辯、莊子寓言、荀子長篇論說、墨子質樸、韓非峻刻。"}], "difficulty": "易", "label": "108指考", "year": 108, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk108-17", "exam": "zk108", "nums": [17, 18, 19], "form": "題組", "img": "img/zk108-17.png", "source": "出處待查（明人論茶盞文字）", "author": "", "genre": "其他", "types": ["比較閱讀", "文意推論", "文化常識"], "passage": "茶盞惟宣窯壇盞為最，質厚白瑩，樣式古雅，有等宣窯印花白甌，式樣得中，而瑩然如玉。次則嘉窯心內茶字小盞為美，欲試茶色貴白，豈容青花亂之？", "translation": "茶杯只有宣德窯的壇盞最好，質地厚實、潔白晶瑩，樣式古樸典雅；還有一種宣德窯印花白碗，樣式適中，晶瑩如玉。其次是嘉靖窯杯心寫有「茶」字的小杯最美。想要看清茶色，杯子以白色為貴，怎能容許青花來擾亂呢？", "keywords": [{"w": "宣窯", "m": "明宣德年間官窯"}, {"w": "嘉窯", "m": "明嘉靖年間官窯"}, {"w": "瑩然", "m": "晶瑩的樣子"}, {"w": "甌", "m": "小碗、小杯"}], "questions": [{"n": 17, "qtype": "單選", "stem": "依據上文，下列關於瓷器的敘述，最適當的是：", "options": {"A": "瓷器輕巧，故取代銅器成為日常用品", "B": "漢代因釉水不佳，瓷器無法製成茶具", "C": "宋代瓷茶具崇尚質樸淡雅，道器合一", "D": "明代流行青花瓷，素色瓷質精而稀有"}, "answer": "C", "explain": "第一段說宋代「以玄素為美」，瓷器的靜定素淨和道相應，「道與器相應，可以參悟」，所以(C)「質樸淡雅、道器合一」正確。\n(A)文中沒說瓷器輕巧、取代銅器成為日常用品；漢代原始瓷是仿銅器做陪葬明器。\n(B)文中只說漢代原始瓷不好看，沒說無法製成茶具。\n(D)明代青花「大器為多」，素色瓷「燒得很好」，沒有說素色瓷稀有。", "skill": "選項裡的因果（故、因）要回原文找有沒有寫，文中沒寫的因果就是陷阱。"}, {"n": 18, "qtype": "單選", "stem": "依據上文，下列文字的鑑賞觀點，最可能屬於：", "options": {"A": "漢代", "B": "魏晉", "C": "宋代", "D": "明代"}, "answer": "D", "explain": "引文提到「宣窯」「嘉窯」（明代宣德、嘉靖的官窯），推崇白瓷「質厚白瑩」，還說「豈容青花亂之」。這和原文「明初宮中還是以素白為美，甜白瓷是此時的代表」相合，所以是(D)明代。\n(A)漢代是灰綠的原始瓷；(B)魏晉以翠綠帶灰的越窯為上；(C)宋代以玄素為美，但引文的窯名都是明代年號。", "skill": "文言引文中的年號、地名（宣德、嘉靖）是判斷時代最快的線索。"}, {"n": 19, "qtype": "單選", "stem": "依據上文，對於下列甲、乙兩項推論，最適當的判斷是：\n甲、茶葉沖泡方式影響杯盞瓷器的形製。\n乙、宋代人常依茶湯顏色選用合適茶碗。", "options": {"A": "甲、乙皆正確", "B": "甲錯誤，乙正確", "C": "甲、乙皆無法判斷", "D": "甲正確，乙無法判斷"}, "answer": "D", "explain": "甲：文中說朱元璋改團茶、點茶為茶湯後，用小壺小杯喝茶，「所以瓷器小杯變多了」，可見沖泡方式影響杯盞形製，正確。\n乙：文中談宋代只說以玄素為美、人與茶碗相應，沒有提到依茶湯顏色選碗，無法判斷。所以選(D)。", "skill": "「無法判斷」題：只要原文找不到直接依據，就不能自行補充常識判對錯。"}], "difficulty": "中", "label": "108指考", "year": 108, "kind": "指考", "textcat": "科普文本", "textcat2": "生活情境文本", "linked_core": ""}, {"id": "zk108-20", "exam": "zk108", "nums": [20, 21, 22], "form": "題組", "img": "img/zk108-20.png", "source": "《水滸傳》第39回", "author": "施耐庵", "genre": "其他", "types": ["人物情感", "詩詞賞析", "文意推論"], "passage": "（宋江酒樓題反詩）「自幼曾攻經史，長成亦有權謀。恰如猛虎臥荒丘，潛伏爪牙忍受。不幸刺文雙頰，那堪配在江州。他年若得報冤讎，血染潯陽江口。」……「心在山東身在吳，飄蓬江海謾嗟吁。他時若遂凌雲志，敢笑黃巢不丈夫。」", "translation": "〈西江月〉：我從小讀過經書史書，長大後也有謀略。就像一頭猛虎躺在荒涼山丘上，暫時藏起爪牙忍耐著。不幸臉上被刺了字，怎能忍受被發配到江州。將來如果能報仇雪恨，一定要讓血染紅潯陽江口。\n七絕：我的心在山東，人卻在吳地，像飛蓬一樣漂泊江海，空自嘆息。將來如果實現了凌雲壯志，我敢笑黃巢不算大丈夫。", "keywords": [{"w": "刺文雙頰", "m": "臉上刺字，宋代罪犯的刑罰"}, {"w": "配", "m": "發配、流放"}, {"w": "飄蓬", "m": "像斷根的蓬草隨風飄，比喻漂泊"}, {"w": "謾", "m": "空自、徒然"}, {"w": "凌雲志", "m": "高遠的志向"}], "questions": [{"n": 20, "qtype": "單選", "stem": "上文藉描寫「宋江飲酒賦詩」，凸顯宋江的性格是：", "options": {"A": "風雅而富詩興", "B": "落拓而有豪情", "C": "慷慨而交遊廣", "D": "權謀而城府深"}, "answer": "B", "explain": "宋江是犯罪被發配的人，想到「名又不成，功又不就，倒被文了雙頰」，潸然淚下，這是「落拓」（失意不得志）；酒後寫下「血染潯陽江口」「敢笑黃巢不丈夫」，狂蕩手舞足蹈，這是「豪情」，所以選(B)。\n(A)他題的是發洩怨恨、立誓報仇的詩，重點不在風雅。\n(C)只提到結識江湖人、多賞酒保銀子，並非本段重點。\n(D)醉後在公開牆上題反詩還署名，正好顯示他當下沒有城府。", "skill": "判斷人物性格，抓「處境＋反應」：處境決定他的失意，反應決定他的豪氣。"}, {"n": 21, "qtype": "單選", "stem": "關於宋江題於壁上的詩詞，解釋最適當的是：", "options": {"A": "「恰如猛虎臥荒丘」意謂才高卻無處施展抱負", "B": "「敢笑黃巢不丈夫」意謂不齒黃巢舉兵動搖朝廷", "C": "「報冤讎」、「遂凌雲志」指掃除匪寇以安定江州", "D": "「潛伏爪牙」、「飄蓬江海」指暗中在四處招兵買馬"}, "answer": "A", "explain": "(A)「猛虎臥荒丘，潛伏爪牙忍受」：猛虎比喻自己有本領，卻困在荒丘只能忍耐，意思是才高而無處施展，正確。\n(B)「敢笑黃巢不丈夫」是說自己將來的作為要超過黃巢，連黃巢都要被我笑，不是不齒黃巢造反。\n(C)「報冤讎，血染潯陽江口」是要報自己的仇，不是掃除匪寇安定江州。\n(D)「潛伏爪牙」是隱忍，「飄蓬江海」是漂泊，都沒有招兵買馬的意思。", "skill": "詩中的比喻句先還原「誰比誰」：猛虎＝宋江，臥荒丘＝不得志。"}, {"n": 22, "qtype": "單選", "stem": "下列六句是今日九江潯陽樓上的一副對聯，請依文意與對聯格式，選出排列順序正確的選項：\n甲、如無水滸傳者　乙、果有潯陽樓乎　丙、就會無影無蹤　丁、寫得有聲有色　戊、則梁山聚義替天行道　己、將宋江醉酒壁上題詩", "options": {"A": "上聯 甲－戊－丙／下聯 乙－己－丁", "B": "上聯 甲－己－丁／下聯 乙－戊－丙", "C": "上聯 乙－戊－丙／下聯 甲－己－丁", "D": "上聯 乙－己－丁／下聯 甲－戊－丙"}, "answer": "D", "explain": "先依文意配對：「果有潯陽樓乎」（真的有潯陽樓），才能「將宋江醉酒壁上題詩，寫得有聲有色」；「如無水滸傳者」（如果沒有水滸傳），「則梁山聚義替天行道，就會無影無蹤」。再看格式：上聯最後一字要仄聲、下聯最後一字要平聲，「色」是仄聲、「蹤」是平聲，所以上聯是乙－己－丁，下聯是甲－戊－丙，選(D)。", "skill": "對聯排序兩步：先用文意把句子接成兩串，再用「上聯尾字仄、下聯尾字平」決定上下。"}], "difficulty": "中", "label": "108指考", "year": 108, "kind": "指考", "textcat": "文學文本", "textcat2": "生活情境文本", "linked_core": ""}, {"id": "zk108-23", "exam": "zk108", "nums": [23, 24], "form": "題組", "img": "img/zk108-23.png", "source": "選項引文：李商隱〈賈生〉、《論語‧子路》、袁了凡《了凡四訓》等", "author": "", "genre": "其他", "types": ["主旨寓意", "文意推論"], "passage": "(A)天命有歸，豈是人力\n(B)可憐夜半虛前席，不問蒼生問鬼神\n(C)名不正，則言不順；言不順，則事不成\n(D)從前種種，譬如昨日死；以後種種，譬如今日生", "translation": "(A)天命早有歸屬，哪是人力能改變的。\n(B)可惜漢文帝半夜向賈誼挪近座位傾聽，問的卻不是百姓的事，而是鬼神之事。\n(C)名分不正當，說話就不順理；說話不順理，事情就辦不成。\n(D)過去的種種，就當作昨天已經死去；以後的種種，就當作今天重新出生。", "keywords": [{"w": "虛前席", "m": "向前挪動座位，表示專心聽"}, {"w": "蒼生", "m": "百姓"}], "questions": [{"n": 23, "qtype": "單選", "stem": "關於上文對《封神演義》的詮釋，最適當的敘述是：", "options": {"A": "天命有歸，豈是人力", "B": "可憐夜半虛前席，不問蒼生問鬼神", "C": "名不正，則言不順；言不順，則事不成", "D": "從前種種，譬如昨日死；以後種種，譬如今日生"}, "answer": "A", "explain": "文章說封神榜早已注定誰要歷劫、誰要封神，「最後的結果早已在冥冥中被決定」，戰爭只是天命大方向下的微細現象，所以是(A)「天命有歸，豈是人力」。\n(B)李商隱〈賈生〉諷刺君王不關心百姓只問鬼神，和本文無關。\n(C)《論語》談正名，和輪迴、天命無關。\n(D)勸人痛改前非、重新做人，不是文中的觀點。", "skill": "主旨題先找文中最「總結性」的一句（結果早已被決定），再拿去對選項的白話意思。"}, {"n": 24, "qtype": "單選", "stem": "上文□□□□內最適合填入的是：", "options": {"A": "超越勝負", "B": "坐觀成敗", "C": "旋生幻滅", "D": "曠然太平"}, "answer": "A", "explain": "空格後說「戰爭不是殲滅對手，而是吸納與融合的過程」，前面又說助周、助商的死者都被封神，代表封神不看輸贏，所以填(A)「超越勝負」。\n(B)坐觀成敗是旁觀等結果，和「吸納融合」不合。\n(C)旋生幻滅是一下出現一下消失，不合。\n(D)曠然太平是說天下太平，沒有對應文意。", "skill": "填空題前後各讀一句，空格內容通常就是後一句的濃縮。"}], "difficulty": "中", "label": "108指考", "year": 108, "kind": "指考", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "zk108-25", "exam": "zk108", "nums": [25, 26], "form": "題組", "img": "img/zk108-25.png", "source": "選項詩句：杜甫〈旅夜書懷〉、李白〈長干行〉、黃庭堅〈寄黃幾復〉、陸游〈書憤〉", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "(A)飄飄何所似？天地一沙鷗\n(B)妾髮初覆額，折花門前劇\n(C)持家但有四立壁，治病不蘄三折肱\n(D)出師一表真名世，千載誰堪伯仲間", "translation": "(A)我漂泊不定像什麼呢？就像天地之間一隻孤單的沙鷗。\n(B)我的頭髮剛蓋住額頭時，常折花在門前遊戲。\n(C)你持家只有四面牆壁（家徒四壁），治病（治國之才）不必多次折斷手臂就已精通。\n(D)諸葛亮一篇〈出師表〉真正名揚於世，千年以來誰能和他相提並論？", "keywords": [{"w": "劇", "m": "嬉戲"}, {"w": "蘄", "m": "通「祈」，求"}, {"w": "三折肱", "m": "多次折斷手臂而成良醫，比喻經驗豐富"}, {"w": "伯仲間", "m": "不相上下"}], "questions": [{"n": 25, "qtype": "單選", "stem": "依據上文，中國古典詩歌以間接烘襯方式表達情感的原因是：", "options": {"A": "詩以言志", "B": "言不盡意", "C": "得意忘言", "D": "意在筆先"}, "answer": "B", "explain": "文中說間接烘襯成為主要手法，是因為「對語言表意功能的質疑」，認為語言「有所不足，甚或不完備」，這就是(B)「言不盡意」。\n(A)詩以言志說的是詩的本質是表達心志，不是間接表達的原因。\n(C)得意忘言是領會意思後就不必在意語言，重點不同。\n(D)意在筆先是下筆前先構思，和文意無關。", "skill": "問「原因」就回原文找「根源於……」「由於……」等表原因的句子。"}, {"n": 26, "qtype": "單選", "stem": "下列詩句，最符合上文畫底線處所述表意方式的是：", "options": {"A": "飄飄何所似？天地一沙鷗", "B": "妾髮初覆額，折花門前劇", "C": "持家但有四立壁，治病不蘄三折肱", "D": "出師一表真名世，千載誰堪伯仲間"}, "answer": "A", "explain": "畫線處說情意是「間接借助語言文字所呈示的對象加以烘襯」。(A)杜甫不直說孤獨漂泊，而是借「天地一沙鷗」的景象烘托出來，最符合。\n(B)直接敘述童年在門前玩耍，是直敘。\n(C)直接用典故說黃幾復家貧而有才，是直述加用典。\n(D)直接評論諸葛亮的〈出師表〉無人能比，是議論。", "skill": "找「間接烘襯」就找用一個景物、意象代替說出情感的句子；直接說出評價或經過的都不是。"}], "difficulty": "中", "label": "108指考", "year": 108, "kind": "指考", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "zk108-27", "exam": "zk108", "nums": [27, 28, 29], "form": "題組", "img": "img/zk108-27.png", "source": "蘇軾〈烏說〉", "author": "蘇軾", "genre": "寓言故事", "types": ["字詞解釋", "主旨寓意", "比較閱讀"], "passage": "烏於人最黠，伺人音色有異，輒去不留，雖捷矢巧彈，不能得其便也。閩中民狃烏性，以謂物無不可以性取者，則之野，挈罌飯、楮錢，陽哭冢間，若祭者然。哭竟，裂錢棄飯而去。烏則爭下啄，啄盡；哭者復立他冢，裂錢棄飯如初。烏不疑其紿也，益鳴爭，乃至三四，皆飛從之。稍狎，迫於羅，因舉獲其烏焉。今夫世之人，自謂智足以周身，而不知禍藏於所伏者，幾何不見賣於哭者哉！", "translation": "烏鴉對人最狡猾，一察覺人的聲音臉色和平常不同，就立刻飛走不停留，即使有快箭、巧彈也找不到機會射中牠。福建一帶的百姓了解烏鴉的習性，認為萬物沒有不能順著牠的本性捕捉的，於是到野外，提著一罐飯和紙錢，假裝在墳間哭，好像在祭拜一樣。哭完了，撕碎紙錢、丟下飯就走了。烏鴉就爭著飛下來啄食，吃光了；哭的人又站到另一座墳前，像先前一樣撕錢丟飯。烏鴉不懷疑這是騙局，叫得更起勁、搶得更兇，到了第三、四次，全都跟著飛過去。漸漸和人親近，接近了羅網，人們就把烏鴉全部捕獲。現在世上的人，自認為聰明足以保全自己，卻不知道災禍就藏在倚靠的事物裡，有幾個不被那「哭墳的人」出賣呢！", "keywords": [{"w": "黠", "m": "聰明狡猾"}, {"w": "伺", "m": "觀察"}, {"w": "狃", "m": "了解、習知"}, {"w": "陽", "m": "通「佯」，假裝"}, {"w": "紿", "m": "欺騙"}, {"w": "狎", "m": "親近而不戒備"}, {"w": "舉", "m": "全部"}], "questions": [{"n": 27, "qtype": "單選", "stem": "下列關於甲文的解說，最不適當的是：", "options": {"A": "「音色有異」指人們聲音和表情不同於往常", "B": "「裂錢棄飯」指人們怕遭攻擊而丟下錢和飯", "C": "「不疑其紿」指烏鴉不懷疑人們的欺騙手法", "D": "「舉獲其烏」指烏鴉全部都被人們網羅捕捉"}, "answer": "B", "explain": "本題選「不適當」。(B)「裂錢棄飯」是假裝祭拜完畢，撕碎紙錢、留下飯菜，目的是引誘烏鴉下來吃，不是怕遭攻擊，所以錯誤。\n(A)「伺人音色有異」：觀察人的聲音臉色不同於平常，正確。\n(C)「紿」是欺騙，「不疑其紿」就是不懷疑這是騙局，正確。\n(D)「舉」是全部，「舉獲其烏」是把烏鴉全部捉到，正確。", "skill": "解釋動作題，要放回故事目的看：人做這個動作是為了「誘捕」，動機就不會是「害怕」。"}, {"n": 28, "qtype": "單選", "stem": "下列關於乙文的解說，最適當的是：", "options": {"A": "認為烏鴉無組織、無紀律，是人們經過長期觀察的定見", "B": "日本東京、印度孟買等城市的烏鴉比臺灣的烏鴉有紀律", "C": "烏鴉的智慧與學習能力，比其他鳥類和哺乳類動物高明", "D": "烏鴉為取食蛤蜊，會探索適當的地點和合宜的擲落高度"}, "answer": "D", "explain": "(D)乙文說烏鴉取食蛤蜊要掌握適當高度，還要丟在質地硬的地方，發現好地點和高度後其他烏鴉會模仿，正確。\n(A)文章說烏鴉「乍看」無紀律，仔細觀察其實有紀律，所以「無紀律」不是定見。\n(B)文中只說臺灣平地少見烏鴉，沒有比較兩地烏鴉的紀律。\n(C)原文是比「其他鳥類及猴子、海豚之外的哺乳類」高明，選項省略了例外，說得太絕對。", "skill": "比較句要看清範圍限定詞（之外、部分、乍看），被刪掉就是錯。"}, {"n": 29, "qtype": "單選", "stem": "下列關於甲、乙二文文意的說明，最適當的是：", "options": {"A": "甲文提醒人們勿如烏鴉爭奪楮錢而陷入羅網", "B": "甲文警惕人們不要只看到眼前近利而忽略隱藏的災禍", "C": "乙文從動物行為學觀點證成「烏合之眾」一詞是指有紀律的群眾", "D": "乙文藉烏鴉毫無紀律地聚集、啄食、行動，證明「烏合」之說法其來有自"}, "answer": "B", "explain": "(B)甲文結尾說世人自以為聰明足以保身，卻不知禍藏在所倚靠的地方，就像烏鴉貪吃眼前的飯而落網，正是警惕只看近利而忽略隱藏的災禍。\n(A)烏鴉爭吃的是飯，不是紙錢，而且主旨在提醒人，不只是烏鴉。\n(C)乙文說烏鴉其實有紀律，但沒有說「烏合之眾」指有紀律的群眾。\n(D)乙文正是要推翻「烏鴉毫無紀律」的印象，不是證明它。", "skill": "寓言的寓意通常在最後一句「今夫世之人……」，直接拿那句翻譯對照選項。"}], "difficulty": "中", "label": "108指考", "year": 108, "kind": "指考", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "赤壁賦"}, {"id": "zk108-30", "exam": "zk108", "nums": [30, 31], "form": "題組", "img": "img/zk108-30.png", "source": "陳高〈送族弟祥遊金陵序〉", "author": "陳高", "genre": "書信序跋", "types": ["文意推論", "主旨寓意", "典故出處"], "passage": "故車之堅可以任重也，而人斯載之；故弓之良可以射遠也，而人斯彀之。苟汝治車而堅矣，為弓而良矣，焉往而不為人所求。不此之務，而急急焉以求人知為事，則非予之所望于汝也。", "translation": "所以車子堅固可以載重，人們就會用它來載運；弓精良可以射遠，人們就會拉開它來射。如果你造的車堅固、做的弓精良，到哪裡會不被人需要呢？不致力於這一點，卻急急忙忙把求人知道自己當成要事，那就不是我對你的期望了。", "keywords": [{"w": "任重", "m": "承載重物"}, {"w": "斯", "m": "就"}, {"w": "彀", "m": "拉滿弓"}, {"w": "不此之務", "m": "不務此，不致力於這件事"}], "questions": [{"n": 30, "qtype": "單選", "stem": "陳高在上文中提及「車之堅」、「弓之良」，用意是：", "options": {"A": "自許為堅車良弓的能工巧匠", "B": "勉勵族弟以製作堅車良弓為務", "C": "勸告族弟充實自身，如治堅車為良弓", "D": "強調自身如堅車可任重，如良弓可射遠"}, "answer": "C", "explain": "陳高用「車堅才有人坐、弓良才有人用」作比喻，勸族弟先把自己培養成堅車良弓，充實實力自然會被重用，所以是(C)。\n(A)(D)陳高不是在誇自己，而是在勸族弟。\n(B)堅車良弓只是比喻，不是要族弟真的去做車做弓。", "skill": "序文、書信中的比喻，先問「這是對誰說的」，再把比喻換回人事。"}, {"n": 31, "qtype": "單選", "stem": "依據上文，陳高所要闡釋的論點是：", "options": {"A": "士不可以不弘毅，任重而道遠", "B": "君子病無能焉，不病人之不己知", "C": "知之者不如好之者，好之者不如樂之者", "D": "君子無所爭，必也射乎！揖讓而升，下而飲，其爭也君子"}, "answer": "B", "explain": "陳高的論點是：只要自己有真本事就不怕沒人用，不要急著求人知道，正是(B)《論語》「君子病無能焉，不病人之不己知」（只擔心自己沒能力，不擔心別人不了解自己）。\n(A)講士人要有弘大剛毅的心志，責任重大；(C)講學習的層次是知、好、樂；(D)講君子即使比賽射箭也合乎禮。三者都和「充實自己而不求人知」無關。", "skill": "找論點對應的經典句，先把文章濃縮成「重點在○○，不在××」，再找同樣結構的句子。"}], "difficulty": "易", "label": "108指考", "year": 108, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk108-32", "exam": "zk108", "nums": [32, 33, 34], "form": "題組", "img": "img/zk108-32.png", "source": "宋濂《宋文憲公全集》（〈燕書〉）", "author": "宋濂", "genre": "寓言故事", "types": ["字詞解釋", "主旨寓意", "句意理解"], "passage": "趙成陽堪，其宮火，欲滅之，無階可升，使其子朒假於奔水氏。朒盛冠服，委蛇而往。既見奔水氏，三揖而後升堂，默坐西楹間。奔水氏命儐者設筵，薦脯醢觴朒。朒起，執爵啐酒，且酢主人。觴已，奔水氏曰：「夫子辱臨敝廬，必有命我者，敢問？」朒方白曰：「天降禍於我家，鬱攸是崇，虐焰方熾，欲緣高沃之，肘弗加翼，徒望宮而號。聞子有階可登，盍乞我？」奔水氏頓足曰：「子何其迂也！子何其迂也！飯山逢彪，必吐哺而逃；濯谿見鱷，必棄履而走。宮火已焰，乃子揖讓時耶！」急舁階從之，至，則宮已燼矣。", "translation": "趙國的成陽堪，家中房屋失火，想要滅火，卻沒有梯子可以爬上去，就派他的兒子成陽朒向奔水氏借梯子。朒穿戴整齊華麗的衣帽，從容不迫地前往。見到奔水氏後，作揖三次才登上廳堂，默默坐在西邊柱子之間。奔水氏叫接待的人擺設筵席，獻上肉乾肉醬，向朒敬酒。朒站起來，拿著酒杯嘗了酒，又回敬主人。飲酒完畢，奔水氏說：「您屈尊來到我家，一定有要吩咐我的事，請問是什麼？」朒這才說：「上天降禍給我家，發生火災，猛火正旺，想爬上高處澆水，手臂上又長不出翅膀，只能望著房子哭喊。聽說您有梯子可以攀登，何不借給我？」奔水氏跺腳說：「你怎麼這麼迂腐啊！你怎麼這麼迂腐啊！在山上吃飯遇到老虎，一定會吐出口中的飯趕快逃；在溪邊洗腳看見鱷魚，一定會丟下鞋子就跑。房子已經燒起來了，這是你行禮作揖的時候嗎！」急忙抬著梯子跟他去，到了，房子已經燒成灰燼了。", "keywords": [{"w": "假", "m": "借"}, {"w": "委蛇", "m": "從容自得的樣子"}, {"w": "酢", "m": "回敬酒"}, {"w": "辱臨", "m": "謙詞，屈尊光臨"}, {"w": "鬱攸是崇", "m": "火氣聚積，指發生火災"}, {"w": "盍", "m": "何不"}, {"w": "彪", "m": "老虎"}, {"w": "舁", "m": "抬"}, {"w": "燼", "m": "燒完"}], "questions": [{"n": 32, "qtype": "單選", "stem": "依據上文，下列文意解說最適當的是：", "options": {"A": "「委蛇而往」是因為心虛以至於膽怯地前往", "B": "「必有命我者」是相信對方一定能救我的命", "C": "「盍乞我」是埋怨對方怎麼不把梯子借給我", "D": "「飯山逢彪」是在山上吃飯的時候遇到老虎"}, "answer": "D", "explain": "(D)「飯山逢彪」：在山上吃飯時遇到老虎，彪就是老虎，正確。\n(A)「委蛇」是從容自得、慢條斯理的樣子，正顯示他不急，不是心虛膽怯。\n(B)「命」是吩咐、指教，「必有命我者」是「一定有要吩咐我的事」，不是救命。\n(C)「盍乞我」是「何不借給我」，是請求，不是埋怨。", "skill": "文言的「命」「盍」等常見字先用最基本義（吩咐、何不）代入，通常就能排除錯誤選項。"}, {"n": 33, "qtype": "單選", "stem": "下列各組文句「」內的字，前後意義相同的是：", "options": {"A": "濯谿「見」鱷／若有招待不周之處，請您「見」諒", "B": "必棄履而「走」／快「走」運動有益全民身心健康", "C": "「假」於奔水氏／歲末音樂會將「假」文化中心舉行", "D": "「乃」子揖讓時耶／竊盜屬公訴罪，非告訴「乃」論"}, "answer": "C", "explain": "(C)兩個「假」都是借：向奔水氏借梯子／借文化中心舉辦音樂會，相同。\n(A)「濯谿見鱷」的見是看見；「見諒」的見是放在動詞前表示對我，意思是原諒我。\n(B)「棄履而走」的走是逃跑；「快走運動」的走是步行。\n(D)「乃子揖讓時耶」的乃是「是、就是」；「告訴乃論」的乃是「才」。", "skill": "一字多義題，把兩邊都翻成白話詞，翻出來不同字就不同義。"}, {"n": 34, "qtype": "單選", "stem": "上文藉由故事人物的言行寄寓主旨，下列說明最適當的是：", "options": {"A": "藉奔水氏批判虛榮浮誇、惺惺作態的人", "B": "藉奔水氏表彰指揮若定、功成不居的人", "C": "藉成陽朒諷刺食古不化、不知變通的人", "D": "藉成陽朒讚美處變不驚、溫文有禮的人"}, "answer": "C", "explain": "成陽朒家裡失火，卻還盛裝前往、三揖升堂、喝酒回敬，最後才說要借梯子，結果房子燒光，作者藉他諷刺死守禮節、不知緊急時要變通的人，選(C)。\n(A)(B)奔水氏是點醒他的人，沒有虛榮浮誇，也沒有指揮若定、功成不居的描寫。\n(D)朒的「溫文有禮」正是被嘲諷的對象，不是讚美。", "skill": "寓言找主旨，看誰造成了壞結果、他錯在哪一個行為，主旨就是批判那個行為。"}], "difficulty": "中", "label": "108指考", "year": 108, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk108-35", "exam": "zk108", "nums": [35], "form": "單題", "img": "img/zk108-35.png", "source": "陶淵明〈桃花源記〉、郁永河〈北投硫穴記〉、柳宗元〈始得西山宴遊記〉、連橫〈臺灣通史序〉、司馬光〈訓儉示康〉", "author": "", "genre": "其他", "types": ["句意理解"], "passage": "", "translation": "(A)田間小路交錯相通，雞鳴狗叫聲彼此都聽得到。裡面來往耕種的人，男女的穿著都和外地人一樣。\n(B)大概周圍百畝之間，其實是一口大沸鍋，我正走在鍋蓋上，能不陷下去，全靠熱氣把它鼓托住罷了。\n(C)深青色的暮色從遠處漸漸到來，到了什麼都看不見，還是不想回去。心神凝聚、形體好像消散，和萬物自然融合在一起。\n(D)草莽中的群雄先後崛起，從朱一貴、林爽文以下，動不動就起兵，血流山河，假借恢復明朝為名，舊的方志也沒有完整記載。\n(E)近來士大夫家，酒不是宮廷祕方釀的、果品菜餚不是遠方珍奇的、食物種類不多、器皿沒擺滿桌，就不敢宴請賓客；常常籌備好幾個月，才敢發出請帖。", "keywords": [{"w": "阡陌", "m": "田間小路"}, {"w": "交通", "m": "交錯相通"}, {"w": "鑊", "m": "鍋"}, {"w": "心凝形釋", "m": "精神凝聚，形體好像消散"}, {"w": "藉言恢復", "m": "假借恢復明室為名"}, {"w": "內法", "m": "宮中釀酒的方法"}], "questions": [{"n": 35, "qtype": "多選", "stem": "關於下列文句的意涵，敘述適當的是：", "options": {"A": "「阡陌交通，雞犬相聞。其中往來種作，男女衣著，悉如外人」：桃花源中交通發達，人來人往，聲音嘈雜", "B": "「蓋周廣百畝間，實一大沸鑊，余身乃行鑊蓋上，所賴以不陷者，熱氣鼓之耳」：硫穴地勢低窪，宛如置身鍋底般炎熱", "C": "「蒼然暮色，自遠而至，至無所見，而猶不欲歸。心凝形釋，與萬化冥合」：天色漸暗，卻流連忘返，進入忘我境界，與大自然合為一體", "D": "「草澤群雄，後先崛起，朱、林以下，輒起兵戎，喋血山河，藉言恢復，而舊志亦不備載也」：朱、林以「反清復明」為藉口，清廷視為叛逆，舊志記載不詳", "E": "「近日士大夫家，酒非內法，果、肴非遠方珍異，食非多品，器皿非滿案，不敢會賓友；常數月營聚，然後敢發書」：士大夫家宴客，竭盡心力張羅，顯示待客之真誠"}, "answer": "CD", "explain": "(C)正確：天色漸暗仍不想回去，心凝形釋、與萬化冥合，就是進入忘我、與自然合一的境界。\n(D)正確：朱一貴、林爽文以「恢復」為名起事，清朝視為叛亂，所以舊志不詳細記載。\n(A)錯：「阡陌交通」是田間小路縱橫相通，「雞犬相聞」顯示安寧，不是交通發達、聲音嘈雜。\n(B)錯：作者是走在「鍋蓋上」，靠熱氣托著才不陷落，不是置身低窪的鍋底。\n(E)錯：司馬光是批評當時宴客講究排場、奢侈成風，不是讚美待客真誠。", "skill": "課文句意題，最常見的陷阱是「古今異義」（交通）和「把批評說成讚美」，要回想文章整體態度。"}], "difficulty": "中", "label": "108指考", "year": 108, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "桃花源記、始得西山宴遊記、裨海紀遊、臺灣通史序"}, {"id": "zk108-36", "exam": "zk108", "nums": [36], "form": "單題", "img": "img/zk108-36.png", "source": "范仲淹〈岳陽樓記〉、韓愈〈原道〉、曹丕〈典論論文〉、司馬遷〈鴻門宴〉、諸葛亮〈出師表〉、歐陽脩〈醉翁亭記〉、《左傳‧燭之武退秦師》、蒲松齡〈勞山道士〉、杜光庭〈虬髯客傳〉、《莊子‧養生主》", "author": "", "genre": "其他", "types": ["字詞解釋", "虛詞句式"], "passage": "", "translation": "", "keywords": [{"w": "微", "m": "若非、沒有／衰微"}, {"w": "耳", "m": "而已"}, {"w": "臨", "m": "將要／靠近"}, {"w": "且", "m": "而且、並且"}, {"w": "因", "m": "透過／順著"}], "questions": [{"n": 36, "qtype": "多選", "stem": "下列各組「」內的字，前後意義相同的是：", "options": {"A": "「微」斯人，吾誰與歸／三代以下，世衰道「微」", "B": "傅毅之於班固，伯仲之間「耳」／從此道至吾軍，不過二十里「耳」", "C": "先帝知臣謹慎，故「臨」崩寄臣以大事也／「臨」谿而漁，谿深而魚肥", "D": "以其無禮於晉，「且」貳於楚也／於案上取壺酒，分賚諸徒，「且」囑盡醉", "E": "靖之友劉文靜者與之狎，「因」文靜見之可也／批大郤，導大窾，「因」其固然"}, "answer": "BD", "explain": "(B)相同：「伯仲之間耳」「不過二十里耳」的耳都是「而已、罷了」。\n(D)相同：「且貳於楚也」是「而且又對楚國有二心」；「且囑盡醉」是「並且吩咐大家盡量喝醉」，都是連詞「而且、並且」。\n(A)不同：「微斯人」的微是「如果沒有」；「世衰道微」的微是衰微。\n(C)不同：「臨崩」的臨是「將要、面臨」；「臨谿而漁」的臨是「靠近」。\n(E)不同：「因文靜見之」的因是「透過、經由」；「因其固然」的因是「順著、依循」。", "skill": "虛字題把字換成白話代入整句，讀起來通順的那個意思就是答案。"}], "difficulty": "中", "label": "108指考", "year": 108, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "燭之武退秦師、鴻門宴、典論論文、出師表、虬髯客傳、岳陽樓記、醉翁亭記、勞山道士"}, {"id": "zk108-37", "exam": "zk108", "nums": [37], "form": "單題", "img": "img/zk108-37.png", "source": "《楚辭‧漁父》、魏徵〈諫太宗十思疏〉、劉基〈工之僑獻琴〉、方苞〈左忠毅公軼事〉、王羲之〈蘭亭集序〉", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "", "translation": "(A)大家都喝醉了，為何不也吃那酒糟、喝那薄酒呢？\n(B)水能載舟也能覆舟，應當非常謹慎；用腐朽的繩子駕馭奔馳的車，怎能疏忽呢？\n(C)又和刻字的工匠商量，刻上古代的款識；把琴裝進匣子埋在土裡，一年後才取出。\n(D)讓史可法換上破衣草鞋，背著竹筐，手拿長鑱，假扮成清除穢物的人。\n(E)雖然沒有音樂的盛況，但喝一杯酒、吟一首詩，也足以暢快抒發幽深的情懷。", "keywords": [{"w": "餔", "m": "吃"}, {"w": "歠", "m": "喝"}, {"w": "匣", "m": "名詞作動詞，裝入匣中"}, {"w": "手", "m": "名詞作動詞，用手拿"}, {"w": "觴", "m": "名詞作動詞，飲酒"}], "questions": [{"n": 37, "qtype": "多選", "stem": "〈馮諼客孟嘗君〉：「孟嘗君客我」，「客」是名詞當動詞使用。下列文句「」內的詞，也將名詞當動詞使用的是：", "options": {"A": "眾人皆醉，何不「餔」其糟而歠其釃", "B": "載舟覆舟，所宜深慎，奔車朽「索」，其可忽乎", "C": "又謀諸篆工，作古窾焉；「匣」而埋諸土，朞年出之", "D": "使史公更敝衣草屨，背筐，「手」長鑱，為除不潔者", "E": "雖無絲竹管絃之盛，一「觴」一詠，亦足以暢敘幽情"}, "answer": "CDE", "explain": "(C)「匣」本是名詞匣子，這裡是「裝進匣子」，名詞當動詞。\n(D)「手」本是名詞，這裡是「手拿」長鑱，名詞當動詞。\n(E)「觴」本是酒杯，「一觴一詠」的觴是「喝一杯酒」，名詞當動詞。\n(A)「餔」本來就是動詞「吃」，沒有詞性轉變。\n(B)「奔車朽索」的索是繩子，仍是名詞。", "skill": "名詞活用為動詞的訊號：名詞後面直接接受詞（手長鑱）、或前後有「而」連接另一個動作（匣而埋）。"}], "difficulty": "中", "label": "108指考", "year": 108, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "漁父、馮諼客孟嘗君、蘭亭集序、諫太宗十思疏、郁離子選、左忠毅公軼事"}, {"id": "zk108-38", "exam": "zk108", "nums": [38], "form": "單題", "img": "img/zk108-38.png", "source": "歸有光〈項脊軒志〉、《論語‧學而》、丘遲〈與陳伯之書〉、《禮記‧禮運》等", "author": "", "genre": "其他", "types": ["句意理解", "寫作手法"], "passage": "", "translation": "(A)在前面開了四扇窗，用矮牆圍住庭院，用來承接南面的陽光，陽光反照，屋裡才明亮起來。\n(B)「友」字由兩隻手構成，「朋」字由兩塊肉構成，意思是朋友就像自己身上的左右手、就是自己身上的肉。\n(C)我每天多次反省自己：替人謀事有沒有不盡心？和朋友交往有沒有不誠信？老師傳授的有沒有不溫習？\n(D)主上寬貸法令、施予恩惠，連吞舟大魚般的大罪也放過；將軍家祖墳的松柏沒被砍伐，親戚安然居住，房舍沒倒，愛妾也還在。\n(E)如今大道已經隱沒，天下成為一家所有，人們各自只親愛自己的親人、只慈愛自己的子女，財物和勞力都為自己，諸侯世代相傳成為禮制，用城牆護城河來鞏固。", "keywords": [{"w": "垣牆周庭", "m": "用矮牆圍繞庭院"}, {"w": "屈法申恩", "m": "委屈法令來施展恩德"}, {"w": "吞舟是漏", "m": "漏掉吞舟大魚，比喻寬赦大罪"}, {"w": "大人世及", "m": "諸侯世襲"}], "questions": [{"n": 38, "qtype": "多選", "stem": "下列畫底線的文句，是進一步解釋前句「」內所述之內涵的是：", "options": {"A": "前闢四窗，垣牆周庭，「以當南日」，日影反照，室始洞然", "B": "「友從兩手，朋從兩肉」，是朋友如一身左右手，即吾身之肉", "C": "吾日「三省吾身」，為人謀而不忠乎，與朋友交而不信乎，傳不習乎", "D": "主上「屈法申恩，吞舟是漏」，將軍松柏不翦，親戚安居，高臺未傾，愛妾尚在", "E": "今「大道既隱，天下為家」，各親其親，各子其子，貨力為己，大人世及以為禮，城郭溝池以為固"}, "answer": "BCDE", "explain": "(B)正確：後句說明「友從兩手，朋從兩肉」的意涵——朋友像自己的左右手、身上的肉。\n(C)正確：後三句就是「三省吾身」的三項內容。\n(D)正確：「松柏不翦，親戚安居，高臺未傾，愛妾尚在」具體說明朝廷如何「屈法申恩」寬待陳伯之。\n(E)正確：「各親其親……城郭溝池以為固」具體描述「大道既隱，天下為家」的社會樣貌。\n(A)錯誤：「日影反照，室始洞然」是「以當南日」造成的結果（屋裡變亮），不是在解釋它的內涵。", "skill": "分辨「解釋」與「結果」：後句能用「也就是說」接上的是解釋，能用「於是」接上的是結果。"}], "difficulty": "中", "label": "108指考", "year": 108, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "大同與小康、與陳伯之書、項脊軒志"}, {"id": "zk108-40", "exam": "zk108", "nums": [40], "form": "單題", "img": "img/zk108-40.png", "source": "辛棄疾〈醜奴兒近〉（博山道中效李易安體）", "author": "辛棄疾", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "千峰雲起，驟雨一霎兒價。更遠樹斜陽，風景怎生圖畫？青旗賣酒，山那畔別有人家，只消山水光中，無事過這一夏。\n午醉醒時，松窗竹戶，萬千瀟灑。野鳥飛來，又是一般閑暇。卻怪白鷗，覷著人欲下未下。舊盟都在，新來莫是，別有說話？", "translation": "千山萬峰湧起雲霧，一陣急雨一下子就下完了。再加上遠樹映著斜陽，這樣的風景怎能畫得出來？青色酒旗招展賣酒，山的那一邊另有人家。只要在這山光水色中，無憂無事地度過這個夏天就好。\n中午醉後醒來，松竹圍繞的窗戶門戶，十分瀟灑自在。野鳥飛來，也是一樣悠閒。卻奇怪那白鷗，看著人想飛下來又不飛下來。我們以前的盟約都還在呀，難道最近你另有什麼話要說？", "keywords": [{"w": "一霎兒價", "m": "一會兒工夫"}, {"w": "怎生", "m": "怎麼"}, {"w": "青旗", "m": "酒旗"}, {"w": "覷", "m": "看"}, {"w": "舊盟", "m": "與鷗鳥結盟，指隱居忘機的約定"}], "questions": [{"n": 40, "qtype": "多選", "stem": "關於下列辛棄疾詞作，敘述適當的是：", "options": {"A": "詞作的上下片均是即景抒情，情景相生", "B": "上片寫夏日陣雨後景致，藉沐雨洗淨心中哀愁", "C": "下片藉由「野鳥」的動態反襯「白鷗」的靜態", "D": "全詞語言不假雕飾，明白如話，結尾清新幽默", "E": "上下片的時間藉「午醉」過渡，寫出浪跡江湖青旗賣酒者的心情"}, "answer": "AD", "explain": "(A)正確：上片寫雨後山景而想「無事過這一夏」，下片寫午醉醒來松竹、野鳥、白鷗而抒閒適之情，都是即景抒情、情景交融。\n(D)正確：用「一霎兒價」「怎生」「莫是」等口語，明白如話；結尾責怪白鷗是不是忘了舊盟「別有說話」，清新又幽默。\n(B)錯：上片寫的是陣雨後的美景與閒適，詞中沒有洗淨哀愁的意思。\n(C)錯：野鳥飛來是寫牠「一般閑暇」，白鷗「欲下未下」也是動作，不是動靜反襯。\n(E)錯：「午醉」確實接續時間，但寫的是作者自己閒居的心情，不是賣酒人的心情。", "skill": "詞的上下片分析：先各用一句話寫出「看到什麼＋心情如何」，再檢查選項是否無中生有。"}], "difficulty": "中", "label": "108指考", "year": 108, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk108-41", "exam": "zk108", "nums": [41, 42], "form": "題組", "img": "img/zk108-41.png", "source": "選項引文：《孟子‧盡心上》、《莊子‧養生主》、蘇軾〈赤壁賦〉、《孟子‧告子上》、李斯〈諫逐客書〉", "author": "", "genre": "其他", "types": ["文意推論", "比較閱讀"], "passage": "(A)萬物皆備於我矣。反身而誠，樂莫大焉\n(B)方今之時，臣以神遇而不以目視，官知止而神遇行\n(C)惟江上之清風，與山間之明月，耳得之而為聲，目遇之而成色\n(D)生，亦我所欲也；義，亦我所欲也；二者不可得兼，舍生而取義者也\n(E)今棄擊甕叩缶而就鄭、衛，退彈箏而取韶虞，若是者何也？快意當前，適觀而已矣", "translation": "(A)萬物的道理都具備在我身上了。反省自己而做到真誠，沒有比這更大的快樂。\n(B)現在我是用精神去接觸牛，而不用眼睛看，感官的作用停止了，只憑精神在運作。\n(C)只有江上的清風和山間的明月，耳朵聽到就成為聲音，眼睛看到就成為景色。\n(D)生命是我想要的，義也是我想要的，兩者不能同時得到，就捨棄生命而選擇義。\n(E)如今放棄敲瓦甕、打瓦缶的秦國音樂而改聽鄭、衛之音，不彈箏而採用韶、虞之樂，這是為什麼呢？只是為了眼前快意、看起來舒服罷了。", "keywords": [{"w": "反身而誠", "m": "反省自身而真誠"}, {"w": "官知止", "m": "感官的作用停止"}, {"w": "舍", "m": "捨棄"}, {"w": "適觀", "m": "看起來舒服"}], "questions": [{"n": 41, "qtype": "多選", "stem": "依據上文，符合文中對人類「本能」與「反射」說明的是：", "options": {"A": "人一出生即具有自給自足的本能", "B": "人具有複雜的本能，其他動物沒有", "C": "因環境發展出各地不同的飲食，是人的本能", "D": "人會避開迎面而來的衝撞，屬於反射而非本能", "E": "從社會學的觀點，人的基本生存能力是藉後天學習而來"}, "answer": "DE", "explain": "(D)正確：文中說被打時閃躲是「反射行為，不是本能」。\n(E)正確：社會學認為人類基本生存能力來自「社會化」，也就是後天學習。\n(A)錯：剛出生的孩子沒有大人幫助會在幾小時內死亡，不能自給自足。\n(B)錯：文中說人類「不具備其他動物的生物本能」，正好相反。\n(C)錯：獲得飲食的方式千差萬別，是後天選擇與學習，不是本能。", "skill": "科學定義題，把文中的定義（本能＝基因決定的複雜行為；反射＝單一反應）當尺，一一量選項。"}, {"n": 42, "qtype": "多選", "stem": "下列文句，符合上文畫底線處所述情形的是：", "options": {"A": "萬物皆備於我矣。反身而誠，樂莫大焉", "B": "方今之時，臣以神遇而不以目視，官知止而神遇行", "C": "惟江上之清風，與山間之明月，耳得之而為聲，目遇之而成色", "D": "生，亦我所欲也；義，亦我所欲也；二者不可得兼，舍生而取義者也", "E": "今棄擊甕叩缶而就鄭、衛，退彈箏而取韶虞，若是者何也？快意當前，適觀而已矣"}, "answer": "DE", "explain": "畫線處是說：人在行動前會思考、選擇行為方式、衡量後果與利弊。\n(D)正確：生與義不能兼得時，經過衡量而「舍生取義」，是思考後做出的選擇。\n(E)正確：秦王捨棄秦樂改用外國音樂，是衡量「快意當前，適觀而已」後的選擇。\n(A)錯：講反省自身而達到真誠的快樂，不是行動前衡量利弊。\n(B)錯：庖丁憑精神運刀、超越感官，是技藝純熟，不是選擇。\n(C)錯：清風明月耳聽成聲、目見成色，是感官自然接收，沒有思考選擇。", "skill": "把畫線句簡化成關鍵動作（思考→選擇→衡量後果），再看選項裡有沒有「取捨」的動作。"}], "difficulty": "中", "label": "108指考", "year": 108, "kind": "指考", "textcat": "科普文本", "textcat2": "部定古文", "linked_core": "諫逐客書、赤壁賦"}, {"id": "xc109-4", "exam": "xc109", "nums": [4], "form": "單題", "img": "img/xc109-4.png", "source": "古典對聯", "author": "", "genre": "其他", "types": ["虛詞句式", "句意理解"], "passage": "甲、書從疑處□成悟，文到窮時自有神\n乙、除卻詩書□所癖，獨於山水不能廉\n丙、使我開懷□夜月，令人滌省是晨鐘", "translation": "甲、讀書在起疑的地方，反而能有所領悟；寫文章到了山窮水盡時，自然會有神來之筆。\n乙、除了詩書以外，還有什麼嗜好呢？只有對山水，沒辦法節制。\n丙、讓我心胸開朗的，只有夜裡的明月；讓人洗滌心靈、反省自己的，是清晨的鐘聲。", "keywords": [{"w": "翻", "m": "反而"}, {"w": "何所癖", "m": "有什麼嗜好"}, {"w": "廉", "m": "節制、少取"}, {"w": "惟", "m": "只有"}], "questions": [{"n": 4, "qtype": "單選", "stem": "下列對聯□內最適合填入的字詞依序是：", "options": {"A": "何／惟／翻", "B": "何／翻／惟", "C": "翻／惟／何", "D": "翻／何／惟"}, "answer": "D", "explain": "對聯上下句要對得起來，先看下聯找線索。甲：上聯「疑處□成悟」對下聯「窮時自有神」，起疑本來是困惑，卻「反而」變成領悟，填「翻」（反而）。乙：「除卻詩書□所癖」後面接「獨於山水不能廉」，意思是「除了詩書還有什麼嗜好？只有山水讓我停不下來」，用疑問「何」。丙：下聯「令人滌省是晨鐘」是判斷「就是晨鐘」，上聯對成「使我開懷惟夜月」——只有夜月，填「惟」。所以是 翻／何／惟，選D。A、B把「何」放在甲，變成「何成悟」講不通；C把「惟」放乙、「何」放丙，「除卻詩書惟所癖」語意矛盾，「何夜月」也對不上「是晨鐘」。", "skill": "填對聯先找對面那一句的同位置字：下聯是「是」，上聯常用「惟」相對；有「獨於」就表示前面在問「還有什麼」。"}], "difficulty": "中", "label": "109學測", "year": 109, "kind": "學測", "textcat": "生活情境文本", "textcat2": "", "linked_core": ""}, {"id": "xc109-9", "exam": "xc109", "nums": [9], "form": "單題", "img": "img/xc109-9.png", "source": "《紅樓夢》第2回；元雜劇《秋胡戲妻》；《史記‧周本紀》", "author": "曹雪芹；石君寶；司馬遷", "genre": "其他", "types": ["文化常識", "句意理解"], "passage": "甲、因聞得鹽政欲聘一□□，雨村便相托友力，謀了進去，且作安身之計。（《紅樓夢》第2回）\n乙、空著我埋怨爹娘，選揀□□，相貌堂堂，自一夜花燭洞房，怎提防這一場。（元雜劇《秋胡戲妻》）\n丙、周公行政七年，成王長，周公反政成王，□□就群臣之位。（《史記‧周本紀》）", "translation": "甲、聽說鹽政大人想聘請一位家庭教師，賈雨村就託朋友幫忙，謀得這個職位，暫且作為安身的辦法。\n乙、我白白埋怨爹娘，替我挑選女婿，看他相貌堂堂，誰知洞房花燭一夜之後，怎料到會有這一場禍事。\n丙、周公代理國政七年，成王長大了，周公把政權歸還成王，自己面向北方，回到臣子的位置。", "keywords": [{"w": "西賓", "m": "家庭教師、幕賓（古代主人坐東、賓客坐西）"}, {"w": "東床", "m": "女婿（王羲之東床坦腹的典故）"}, {"w": "北面", "m": "臣子之位（君王坐北朝南，臣子面北）"}, {"w": "反政", "m": "歸還政權"}], "questions": [{"n": 9, "qtype": "單選", "stem": "依據下文，□□內最適合填入的詞語依序是：", "options": {"A": "西賓／東床／北面", "B": "西賓／西席／南面", "C": "東道／東床／南面", "D": "東道／西席／北面"}, "answer": "A", "explain": "甲：鹽政要「聘」人，賈雨村去當林黛玉的老師，家庭教師稱「西賓」或「西席」；「東道」是請客的主人，不對。乙：女子埋怨爹娘「選揀」了一個相貌堂堂的人，選的是丈夫，也就是「東床」（女婿）；「西席」是老師，不合。丙：周公把政權還給成王，自己回到群臣的位置，臣子面朝北，所以是「北面」；「南面」是君王之位。答案 西賓／東床／北面，選A。", "skill": "方位稱謂背口訣：君南面、臣北面；主人東（東道）、老師賓客西（西席、西賓）；女婿是東床。"}], "difficulty": "中", "label": "109學測", "year": 109, "kind": "學測", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "xc109-10", "exam": "xc109", "nums": [10], "form": "單題", "img": "img/xc109-10.png", "source": "《荀子‧禮論》", "author": "荀子", "genre": "說理議論", "types": ["主旨寓意", "文意推論"], "passage": "人生而有欲，欲而不得，則不能無求。求而無度量分界，則不能不爭；爭則亂，亂則窮。先王惡其亂也，故制禮義以分之，以養人之欲，給人之求。", "translation": "人生下來就有欲望，想要卻得不到，就不能不去追求。追求如果沒有限度和分寸，就不能不互相爭奪；一爭奪就混亂，一混亂就窮困。古代聖王厭惡這種混亂，所以制定禮義來劃分界限，用來調養人的欲望，供給人的需求。", "keywords": [{"w": "度量分界", "m": "限度與界線"}, {"w": "窮", "m": "困窘、走投無路"}, {"w": "惡", "m": "厭惡（音ㄨˋ）"}, {"w": "分", "m": "劃分（名分、界限）"}, {"w": "養", "m": "調養、滿足"}], "questions": [{"n": 10, "qtype": "單選", "stem": "依據下文，最符合主旨的是：", "options": {"A": "王道無偏", "B": "無欲則治", "C": "爭起於分界", "D": "禮源於治亂"}, "answer": "D", "explain": "這段是荀子說「禮從哪裡來」：欲望→追求→沒有界限就爭→爭就亂→聖王為了治理這種亂，才制定禮義。所以主旨是「禮的起源在於治理混亂」，選D。A「王道無偏」文中沒提。B荀子並不要人無欲，反而說禮是用來「養人之欲」。C說反了：爭是因為「無」度量分界，不是因為有分界。", "skill": "找主旨看最後的結論句「故制禮義以……」，前面一長串因果只是鋪陳。"}], "difficulty": "易", "label": "109學測", "year": 109, "kind": "學測", "textcat": "延伸", "textcat2": "學術文本", "linked_core": "勸學"}, {"id": "xc109-11", "exam": "xc109", "nums": [11], "form": "單題", "img": "img/xc109-11.png", "source": "四書（《論語‧公冶長》）", "author": "", "genre": "經典語錄", "types": ["典故出處", "句意理解"], "passage": "人不能不與世為酬酢，言色恭行焉。情之不可已，本自有當然之則也。乃巧好為言，容悅為色，周旋舉止，悉邪為之。", "translation": "人不可能不和世人往來應對，於是言語、神色、恭敬的舉動就出現了。這些情感表現是停不下來的，本來就有應當遵守的準則。可是有人卻用乖巧討好來說話，用逢迎取悅來擺臉色，一舉一動都出於邪曲。", "keywords": [{"w": "酬酢", "m": "應對往來"}, {"w": "已", "m": "停止"}, {"w": "巧好", "m": "乖巧討好"}, {"w": "容悅", "m": "逢迎取悅"}, {"w": "足恭", "m": "過分恭敬"}], "questions": [{"n": 11, "qtype": "單選", "stem": "某秀才參加鄉試，題目出自「四書」。他在文中闡釋題意：「人不能不與世為酬酢，言色恭行焉。情之不可已，本自有當然之則也。乃巧好為言，容悅為色，周旋舉止，悉邪為之。」則試卷題目最可能是：", "options": {"A": "色厲而內荏", "B": "一言可以興邦", "C": "巧言令色足恭", "D": "名不正則言不順"}, "answer": "C", "explain": "秀才的文章三個重點剛好一一對應：「巧好為言」＝巧言，「容悅為色」＝令色，「周旋舉止，悉邪為之」＝過分做作的恭敬，也就是「足恭」。所以題目是《論語》的「巧言令色足恭」，選C。A「色厲而內荏」是外表嚴厲、內心怯懦，講的是虛張聲勢。B講一句話可以使國家興盛。D講名分與言語，都沒有提到討好的言語神色。", "skill": "把闡釋文字拆成關鍵詞（言、色、舉止），再去選項找一一對應的那一個。"}], "difficulty": "中", "label": "109學測", "year": 109, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc109-12", "exam": "xc109", "nums": [12], "form": "單題", "img": "img/xc109-12.png", "source": "《聊齋誌異‧黃英》", "author": "蒲松齡", "genre": "筆記小品", "types": ["人物情感", "文意推論"], "passage": "陶一日謂馬曰：「君家固不豐，僕日以口腹累知交，胡可為常？為今計，賣菊亦足謀生。」馬素介，聞陶言，甚鄙之，曰：「僕以君風流高士，當能安貧。今作是論，則以東籬為市井，有辱黃花矣。」陶笑曰：「自食其力不為貪，販花為業不為俗。人固不可苟求富，然亦不必務求貧也。」", "translation": "有一天陶生對馬子才說：「您家本來就不富裕，我每天為了吃飯拖累朋友，怎麼能長久這樣？為現在打算，賣菊花也足以謀生。」馬子才一向耿介，聽了很瞧不起，說：「我以為您是風雅高潔的人，應該能安於貧窮。現在說這種話，是把種菊的東籬當成市場，玷辱了菊花啊。」陶生笑說：「靠自己的力氣吃飯不算貪，以賣花為業不算俗。人固然不可以隨便追求富貴，但也不必刻意追求貧窮。」", "keywords": [{"w": "累", "m": "拖累"}, {"w": "介", "m": "耿直有操守"}, {"w": "鄙", "m": "看不起"}, {"w": "東籬", "m": "種菊之處（化用陶淵明「采菊東籬下」）"}, {"w": "苟", "m": "隨便、苟且"}, {"w": "務", "m": "刻意追求"}], "questions": [{"n": 12, "qtype": "單選", "stem": "關於下文陶、馬二人的對話，敘述最適當的是：", "options": {"A": "陶以馬未能安貧為恥", "B": "馬希望陶能自食其力", "C": "陶與馬商議賣菊維生", "D": "馬怕家貧而有辱於陶"}, "answer": "C", "explain": "整段就是陶生提議「賣菊亦足謀生」，馬子才反對，陶生再解釋——兩人在商量賣菊花維生這件事，選C。A相反：是馬認為陶「當能安貧」卻想賣花，陶並沒有嫌馬不能安貧。B「自食其力」是陶說的，馬是反對賣花的人。D馬怕的是賣花「有辱黃花」，不是怕家貧有辱於陶。", "skill": "對話題先標清楚「誰說了哪句」，選項常把甲的話安到乙身上。"}], "difficulty": "易", "label": "109學測", "year": 109, "kind": "學測", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "勞山道士"}, {"id": "xc109-13", "exam": "xc109", "nums": [13], "form": "單題", "img": "img/xc109-13.png", "source": "蘇軾〈石蒼舒醉墨堂〉（節錄）", "author": "蘇軾", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感", "文意推論"], "passage": "人生識字憂患始，姓名粗記可以休。何用草書誇神速，開卷惝怳令人愁。我嘗好之每自笑，君有此病何能瘳。自言其中有至樂，適意無異逍遙遊。近者作堂名醉墨，如飲美酒消百憂。乃知柳子語不妄，病嗜土炭如珍羞。", "translation": "人一識字，憂患就開始了，能大概寫出自己的姓名就可以停了。何必用草書來誇耀寫得神速，讓人打開卷子看得惆悵發愁呢？我也曾愛好書法，常常自己笑自己；你得了這種「病」，怎麼可能痊癒？你說這裡面有最大的快樂，稱心快意和莊子的逍遙遊沒有兩樣。最近你蓋了一座堂，取名「醉墨」，寫字就像喝美酒能消除百般憂愁。我這才知道柳宗元的話不假：有怪病的人嗜吃泥土木炭，就像吃山珍海味一樣。", "keywords": [{"w": "惝怳", "m": "惆悵、失意的樣子"}, {"w": "瘳", "m": "病癒"}, {"w": "適意", "m": "稱心快意"}, {"w": "珍羞", "m": "珍貴美食（羞同饈）"}, {"w": "柳子", "m": "柳宗元"}], "questions": [{"n": 13, "qtype": "單選", "stem": "關於詩中石蒼舒之「病」，敘述最適當的是：", "options": {"A": "石蒼舒醉心翰墨成疾仍不改其樂，蘇軾擔心他過度沉迷而招禍", "B": "石蒼舒嗜書與柳子嗜土炭如珍饈之病，蘇軾認為皆蘊不遇之憾", "C": "蘇軾好書藝而與石蒼舒同病，但自慚不及石神速，故開卷惝怳", "D": "蘇軾消遣石蒼舒病重難癒，意在稱美其癡迷書藝而能逍遙自樂"}, "answer": "D", "explain": "「病」是玩笑話：說石蒼舒迷書法迷到「何能瘳」（治不好），但接著說他「其中有至樂」「適意無異逍遙遊」「如飲美酒消百憂」，可見蘇軾是用調侃的口吻稱讚他能在書法裡逍遙自得，選D。A詩中沒有「擔心招禍」。B「病嗜土炭如珍羞」是比喻他把旁人看來奇怪的嗜好當成美味，跟懷才不遇無關。C「每自笑」是自嘲，沒有「自慚不及」；「開卷惝怳」是說看草書的人看不懂而發愁，不是蘇軾自慚。", "skill": "詩裡的「病、癡、狂」常是反話：先看後文怎麼描寫那份樂趣，就能判斷作者是貶還是褒。"}], "difficulty": "中", "label": "109學測", "year": 109, "kind": "學測", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "赤壁賦"}, {"id": "xc109-16", "exam": "xc109", "nums": [16, 17, 18], "form": "題組", "img": "img/xc109-16.png", "source": "甲：陸游粥品筆記（題目整理自古籍）；乙：改寫自譚健鍬《史料未及的奪命內幕》；丙：低GI飲食資料", "author": "陸游（甲）", "genre": "其他", "types": ["句意理解", "比較閱讀", "文意推論"], "passage": "烏豆粥：用新好大烏豆一斤，炭火鬻一日，當糜爛。（此時）可作三升米粥，至極熟，下豆，入糖一斤和勻，又入細生薑棊子四兩。\n地黃粥：用地黃二合，候湯沸，與米同下。別用酥二合、蜜一合，炒令香熟，貯器中，候粥欲熟乃下。\n枸杞粥：用紅熟枸杞子，生細研，淨布捩汁，每粥一椀用汁一盞，加少煉熟蜜乃鬻。", "translation": "烏豆粥：用新鮮上好的大烏豆一斤，用炭火煮一整天，豆子應該就爛透了。這時另外煮三升米的粥，煮到非常熟，再放進豆子，加一斤糖攪勻，再放四兩切成小塊的細生薑。\n地黃粥：用地黃二合，等水滾了，和米一起下鍋。另外用酥油二合、蜂蜜一合，炒到香熟，放在容器裡，等粥快熟時再加進去。\n枸杞粥：用紅熟的枸杞，生的時候細細磨碎，用乾淨的布擰出汁，每碗粥用一小杯汁，加一點煉熟的蜂蜜再煮。", "keywords": [{"w": "鬻", "m": "同「煮」"}, {"w": "糜爛", "m": "爛透"}, {"w": "候", "m": "等待"}, {"w": "別", "m": "另外"}, {"w": "捩", "m": "扭、擰"}, {"w": "盞", "m": "小杯"}], "questions": [{"n": 16, "qtype": "單選", "stem": "依據資料甲，關於陸游的煮粥祕訣，下列敘述最適當的是：", "options": {"A": "煮粥時間長短，依序為地黃粥＞烏豆粥＞枸杞粥", "B": "以烏豆、枸杞煮粥，烏豆和枸杞均須預先處理備用", "C": "以地黃、枸杞煮粥，均須在起鍋後另加以蜜炒製的配料", "D": "烏豆當於冷水時與米同煮，地黃則須待水沸後方與米入鍋"}, "answer": "B", "explain": "烏豆要先「炭火鬻一日」煮爛，枸杞要先「生細研，淨布捩汁」，兩者都要事先處理，選B。A烏豆光是煮豆就要一整天，時間最長，排序錯。C地黃粥的酥蜜是「候粥欲熟乃下」（快熟時加），不是起鍋後；枸杞粥只是加煉熟的蜜，沒有「炒製配料」。D烏豆是另外煮爛，等米粥「至極熟」才「下豆」，並不是冷水時與米同煮；地黃「候湯沸，與米同下」這半句才對。", "skill": "食譜類文言抓「時間詞」：候、乃、至……熟、別用，就能排出步驟先後。"}, {"n": 17, "qtype": "單選", "stem": "依據資料甲、乙、丙，關於陸游食粥與健康的敘述，最適當的是：", "options": {"A": "陸游曾向張耒求得煮粥筆記，鑽研粥品養生之道", "B": "陸游吃粥雖可使牙齒免於咀嚼，卻不利於血糖控制", "C": "吃粥兩小時內血糖波動小，能讓陸游的回籠覺睡得安穩", "D": "加糖會讓陸游的粥品GI值上升，但長時間熬煮可減低粥品GI值"}, "answer": "B", "explain": "乙說陸游牙周病，喜歡吃粥（不必咀嚼）；丙說「稀爛」的食物、「長時間烹煮」的澱粉 GI 值都較高，血糖上升快。所以吃粥對牙齒友善，但對陸游的消渴（糖尿病）不利，選B。A陸游只說「我得宛丘平易法」，是從張耒的〈粥記〉得到的觀念，沒說向張耒求得筆記。C粥是高GI，血糖波動大，不是小。D長時間熬煮會「糊化」，GI 值反而升高。", "skill": "多文本題：把每個選項拆成兩半，分別回到對應的資料核對，兩半都對才選。"}, {"n": 18, "qtype": "單選", "stem": "若陸游想控制血糖，則依據資料丙，對①、②兩項調整方式，最適當的判斷是：①每餐多吃一碗白飯，少吃一碗塊狀肉類。②每餐少吃一碗清粥，多吃一碗高纖蔬菜。", "options": {"A": "①、②皆正確", "B": "①無法判斷，②正確", "C": "①錯誤，②正確", "D": "①錯誤，②無法判斷"}, "answer": "C", "explain": "①白飯是精緻澱粉，GI 高；肉類是蛋白質、脂肪，GI 低。多白飯少肉會讓血糖升得更快，錯誤。②清粥稀爛、久煮，GI 高；高纖蔬菜纖維多，GI 低，減粥增菜可以控制血糖，正確。選C。", "skill": "「正確／錯誤／無法判斷」題：資料有明確依據才能判對錯，資料沒提到才是無法判斷。"}], "difficulty": "中", "label": "109學測", "year": 109, "kind": "學測", "textcat": "科普文本", "textcat2": "生活情境文本", "linked_core": ""}, {"id": "xc109-22", "exam": "xc109", "nums": [22, 23], "form": "題組", "img": "img/xc109-22.png", "source": "改寫自朱光潛〈文學的趣味〉（白話）；選項引《論語》、〈日喻〉、《文心雕龍》等", "author": "朱光潛", "genre": "說理議論", "types": ["文意推論", "主旨寓意", "典故出處"], "passage": "（本文為白話；文言部分見選項）\n知之者不如好之者，好之者不如樂之者。（《論語》）\n登東山而小魯，登泰山而小天下。（《孟子》）\n23選項：聞道有先後，術業有專攻／操千曲而後曉聲，觀千劍而後識器／恆患意不稱物，文不逮意；蓋非知之難，能之難也／常人貴遠賤近，向聲背實，又患闇於自見，謂己為賢", "translation": "操千曲而後曉聲，觀千劍而後識器：彈奏過上千首曲子以後才懂得音樂，看過上千把劍以後才會鑑別兵器。\n恆患意不稱物，文不逮意：常擔心心中的想法不能符合事物，文字又趕不上想法；其實不是懂道理難，而是做到難。\n常人貴遠賤近，向聲背實：一般人看重遠的、輕視近的，追逐名聲而背離實際，又苦於看不清自己，以為自己賢能。", "keywords": [{"w": "扣槃捫燭", "m": "盲人敲銅盤、摸蠟燭來認識太陽，比喻認識片面、不正確"}, {"w": "曉聲", "m": "懂得音樂"}, {"w": "識器", "m": "鑑別兵器"}, {"w": "逮", "m": "及、趕上"}, {"w": "闇", "m": "不明白"}], "questions": [{"n": 22, "qtype": "單選", "stem": "下列詞語，最能呼應上文所剖析「在知上有欠缺」的是：", "options": {"A": "扣槃捫燭", "B": "巧拙有素", "C": "含糊其辭", "D": "匪夷所思"}, "answer": "A", "explain": "文章說在「知」上有欠缺，有「不知、知得不正確、知得不周全」三種。「扣槃捫燭」出自蘇軾〈日喻〉：盲人聽說太陽像銅盤、光像蠟燭，就把敲鐘的聲音、摸到的笛子當成太陽——正是認識不正確又片面，選A。B「巧拙有素」指天分本來有高低。C「含糊其辭」是說話不清楚。D「匪夷所思」指不是常理能想到的。都和「知的欠缺」無關。", "skill": "成語題先還原典故故事，再比對文章的關鍵詞（這題是「知得不正確、不周全」）。"}, {"n": 23, "qtype": "單選", "stem": "下列文句，最適合說明上文主旨的是：", "options": {"A": "聞道有先後，術業有專攻", "B": "操千曲而後曉聲，觀千劍而後識器", "C": "恆患意不稱物，文不逮意；蓋非知之難，能之難也", "D": "常人貴遠賤近，向聲背實，又患闇於自見，謂己為賢"}, "answer": "B", "explain": "全文主旨：要治趣味的毛病，就要「擴大眼界，加深知解」，作品「玩索愈多……鑒別力愈可靠」。《文心雕龍‧知音》「操千曲而後曉聲，觀千劍而後識器」說的正是見多才能識廣，選B。A出自韓愈〈師說〉，講學問有先後、各有專長。C出自陸機〈文賦〉，講寫作時懂得容易、做到困難。D出自曹丕〈典論論文〉，講一般人重古輕今、看不清自己。", "skill": "主旨題：先用一句話說出文章結論（多看多比較→鑑別力），再找意思最貼近的那句。"}], "difficulty": "中", "label": "109學測", "year": 109, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc109-24", "exam": "xc109", "nums": [24, 25], "form": "題組", "img": "img/xc109-24.png", "source": "《莊子‧山木》", "author": "莊子", "genre": "寓言故事", "types": ["主旨寓意", "字詞解釋", "文意推論"], "passage": "莊子行於山中，見大木，枝葉盛茂，伐木者止其旁而不取也。問其故，曰：「無所可用。」莊子曰：「此木以不材得終其天年。」夫子出於山，舍於故人之家。故人喜，命豎子殺雁而烹之。豎子請曰：「其一能鳴，其一不能鳴，請奚殺？」主人曰：「殺不能鳴者。」明日，弟子問於莊子曰：「昨日山中之木，以不材得終其天年；今主人之雁，以不材死；先生將何處？」莊子笑曰：「周將處乎材與不材之間。材與不材之間，似之而非也，故未免乎累。若夫乘道德而浮遊則不然。無譽無訾，一龍一蛇，與時俱化，而無肯專為；一上一下，以和為量，浮遊乎萬物之祖；物物而不物於物，則胡可得而累邪！」", "translation": "莊子在山中行走，看到一棵大樹，枝葉茂盛，伐木的人停在樹旁卻不砍它。問他原因，說：「沒有什麼用處。」莊子說：「這棵樹因為不成材，才能活到自然的壽命。」莊子從山裡出來，住在老朋友家。朋友很高興，叫童僕殺鵝來煮。童僕請示：「一隻會叫，一隻不會叫，請問殺哪隻？」主人說：「殺不會叫的。」第二天，弟子問莊子：「昨天山中的樹因為不成材得以終其天年；今天主人的鵝卻因為不成材被殺；先生要站在哪一邊？」莊子笑說：「我將處在成材與不成材之間。不過材與不材之間，看似可以，其實不對，所以還是免不了牽累。如果順著自然之道而自在遨遊，就不是這樣了。沒有讚美也沒有毀謗，時而像龍騰飛、時而像蛇蟄伏，隨著時勢變化，不肯執著於某一種做法；時而上、時而下，以和順為準則，遨遊在萬物的本源；主宰外物而不被外物所役使，那怎麼會受到牽累呢！」", "keywords": [{"w": "不材", "m": "不成材、沒用"}, {"w": "天年", "m": "自然壽命"}, {"w": "豎子", "m": "童僕"}, {"w": "雁", "m": "此指家鵝"}, {"w": "奚", "m": "哪一個"}, {"w": "累", "m": "牽累、禍患"}, {"w": "訾", "m": "毀謗"}, {"w": "物物而不物於物", "m": "役使外物而不被外物役使"}], "questions": [{"n": 24, "qtype": "單選", "stem": "下列敘述，最符合上文所欲表達觀點的是：", "options": {"A": "與時俱化，不拘執於為龍或為蛇的價值思考", "B": "死生有命，富貴亦身外之物，毋須為此傷神", "C": "天生我材必有用，自當逍遙浮遊於大化之間", "D": "世人囿於俗見，渾然不知無用之用方為大用"}, "answer": "A", "explain": "樹因不材而活，鵝因不材而死，可見固守「有用」或「無用」都不保險，連「材與不材之間」也還有牽累。莊子的答案是「一龍一蛇，與時俱化，而無肯專為」——隨時變化，不執著任何一種價值，選A。B文章不談富貴。C「天生我材必有用」是執著於「材」，正好被莊子否定。D「無用之用」是莊子別篇的觀點，本文用鵝的例子說明「無用」也會死，所以不是重點。", "skill": "寓言題看「轉折」：前兩個例子互相矛盾，作者最後提出的第三條路才是主旨。"}, {"n": 25, "qtype": "單選", "stem": "下列文句，最符合上文中「道德」意涵的是：", "options": {"A": "順任自然，虛靜無為", "B": "居仁由義，存理去欲", "C": "道之以德，齊之以禮", "D": "海納百川，有容乃大"}, "answer": "A", "explain": "「乘道德而浮遊」的「道德」是道家的「道」與「德」，指順應自然的大道，表現為無譽無訾、與時俱化、無肯專為，也就是順任自然、虛靜無為，選A。B「居仁由義」是孟子、「存理去欲」是理學，屬儒家。C出自《論語》，講用德行、禮制治理百姓，也是儒家。D講包容的胸襟，不是道家的「道德」。", "skill": "看到「道德」先分學派：道家的道德＝自然無為；儒家的道德＝仁義禮。"}], "difficulty": "中", "label": "109學測", "year": 109, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc109-26", "exam": "xc109", "nums": [26, 27, 28], "form": "題組", "img": "img/xc109-26.png", "source": "甲：蔡瑜《中國抒情詩的世界》；乙：王安石〈浪淘沙令〉；丙：張養浩〈山坡羊〉（潼關懷古）", "author": "蔡瑜；王安石；張養浩", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀", "主旨寓意"], "passage": "乙\n伊呂兩衰翁，歷徧窮通。一為釣叟一耕傭。若使當時身不遇，老了英雄。湯武偶相逢，風虎雲龍。興王祇在笑談中。直至如今千載後，誰與爭功！（王安石〈浪淘沙令〉）\n丙\n峰巒如聚，波濤如怒，山河表裡潼關路。望西都，意躊躕。傷心秦漢經行處，宮闕萬間都做了土。興，百姓苦；亡，百姓苦！（張養浩〈山坡羊〉）", "translation": "乙：伊尹、呂尚兩位老人，經歷過窮困和顯達。一個是釣魚的老翁（呂尚），一個是耕田的傭工（伊尹）。假如當時沒遇到明主，英雄也只能就這樣老去。他們偶然遇到商湯、周武王，就像風從虎、雲從龍一樣君臣相得。在談笑之間就輔佐君王成就王業。直到千年後的今天，誰能和他們爭功呢！\n丙：群山像聚集在一起，黃河的波濤像在發怒，潼關的路依山傍水。遙望西邊的長安，心中猶豫難平。令人傷心的是秦漢兩朝經過的地方，千萬間宮殿都化成了塵土。王朝興盛，百姓受苦；王朝滅亡，百姓也受苦！", "keywords": [{"w": "伊呂", "m": "伊尹、呂尚（姜太公）"}, {"w": "窮通", "m": "困頓與顯達"}, {"w": "不遇", "m": "沒遇到賞識的君主"}, {"w": "風虎雲龍", "m": "比喻明君賢臣相遇相得"}, {"w": "西都", "m": "長安"}, {"w": "躊躕", "m": "猶豫、心緒起伏"}], "questions": [{"n": 26, "qtype": "單選", "stem": "下列敘述，最符合甲文觀點的是：", "options": {"A": "歷史題材現身於古典詩歌中，主要目的在展現文人的博覽積學", "B": "詩人常藉由歷史題材的書寫，以省視當代的情境或自身的定位", "C": "詠史、懷古詩皆以歷史為媒介抒情言志，所抒發的皆是家國之情", "D": "古人解讀歷史往往有所傳承，故詩人對特定人與事的詮釋，常呈現穩定性"}, "answer": "B", "explain": "甲文說中國人「透過對於歷史的不斷詮釋與建構，進行著當代的反省」，詩人「反思著人類的經驗與命運，也思忖著自身的定位」，正是B。A甲文說重點是「以史抒情」，不是炫耀學問。C抒發的是個人「情志」，不限於家國之情，「皆是」太絕對。D甲文說「歷史的意義從來都是流動的」，不是穩定。", "skill": "「最符合文章觀點」題，選項出現「皆、都、只」等絕對字眼時，特別回原文檢查。"}, {"n": 27, "qtype": "單選", "stem": "關於乙、丙二詩的詩意或作法，下列敘述最適當的是：", "options": {"A": "乙詩引述伊尹、呂望二人事蹟，旨在說明自古英雄出少年", "B": "丙詩感慨當世兵連禍結，不復秦漢之盛，故百姓生活困苦", "C": "二詩均在敘寫史事或史蹟之後，描摹當世的情境，並藉古今對照以興發議論", "D": "乙詩設想古人際遇，並對照事實而有所托寓；丙詩藉行經古跡所見，引發感慨"}, "answer": "D", "explain": "乙詩「若使當時身不遇，老了英雄」是假設伊、呂沒遇到明主的情形，再對照他們實際「風虎雲龍」的成就，寄託期待君臣相得的心意；丙詩走在潼關路上，看到秦漢宮闕化為塵土而發出「興亡皆苦」的感慨，選D。A伊、呂是「兩衰翁」，老年才遇明主，不是少年英雄。B丙詩說的是不論興亡百姓都苦，不是感慨當世不如秦漢。C兩首詩都沒有描寫「當世的情境」。", "skill": "注意詩中的「若使、假如」：那是設想，不是事實；作者常用假設來反襯真實。"}, {"n": 28, "qtype": "單選", "stem": "依據甲文觀點，下列對乙、丙二詩的解讀，最適當的是：", "options": {"A": "乙詩藉伊尹、呂望興王之功，投射個人期望君臣相得，以建功立業的心志", "B": "丙詩藉遙望西都，懷想宮闕隨王朝盛衰而興廢，揭示朝代興衰無常的規律", "C": "乙詩詠史，丙詩懷古，均透過對歷史的詮釋，闡述遭逢明君盛世的重要性", "D": "二詩均以史抒情，乙詩寄寓民胞物與的襟懷，丙詩寄寓以天下自任的抱負"}, "answer": "A", "explain": "甲文說詠史詩是「詩人主觀意念的投影」。王安石本身是希望得到君王信任、推行變法的政治家，寫伊、呂遇湯、武而成就王業，正是投射自己期待君臣相得、建功立業的心志，選A。B丙詩重點在「興，百姓苦；亡，百姓苦」，是對百姓的悲憫，不是在揭示興衰無常的規律。C丙詩與明君盛世無關。D乙詩是功業之志，不是民胞物與；丙詩是同情百姓，不是以天下自任的抱負。", "skill": "詠史懷古詩問「寄託」：想想作者的身分與處境，古人往往就是作者的影子。"}], "difficulty": "難", "label": "109學測", "year": 109, "kind": "學測", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "xc109-29", "exam": "xc109", "nums": [29, 30], "form": "題組", "img": "img/xc109-29.png", "source": "改寫自許進雄《中國古代社會──文字與人類學的透視》（白話）；30題選項引歸有光〈項脊軒志〉、黃宗羲〈原君〉、杜光庭〈虬髯客傳〉、魏徵〈諫太宗十思疏〉一類文句", "author": "許進雄", "genre": "其他", "types": ["字詞解釋", "文化常識"], "passage": "（本文為白話；文言部分見30題選項）\n(A)（項脊軒）又北向，不能得日，日過午已「昏」\n(B)天下有公利而「莫」或興之，有公害而莫或除之\n(C)俄而文皇來，精「采」驚人，長揖就坐，神清氣朗\n(D)臣歷觀前王嗣位之初，莫不躬勤庶政，坐以待「旦」", "translation": "(A)項脊軒又朝北，照不到陽光，過了中午就昏暗了。\n(B)天下有公眾的利益卻沒有人去興辦，有公眾的禍害卻沒有人去除掉。\n(C)不久李世民來了，神采驚人，拱手行禮後入座，神情清朗。\n(D)我看遍前代君王剛即位時，無不親自勤理政事，坐著等天亮（急著上朝）。", "keywords": [{"w": "旦", "m": "太陽剛升起，天亮"}, {"w": "昃", "m": "太陽偏西"}, {"w": "莫", "m": "本義日落（暮），借為「沒有人」"}, {"w": "采", "m": "本義採摘，假借為光彩"}, {"w": "昏", "m": "本義黃昏，引申為昏暗"}], "questions": [{"n": 29, "qtype": "單選", "stem": "依據上文，下列敘述最不適當的是：", "options": {"A": "由時間的分段推測，商代的人至少一日吃兩餐飯", "B": "「日中則昃」的現象可引申出「盛極而衰」之意", "C": "「大食」是依據太陽在天空變動的位置命名，通常為吃中餐時間", "D": "甲骨文「昃」、「昏」的造字，都以人為參照點表示太陽的位置"}, "answer": "C", "explain": "文中說「大食」是「吃一頓豐盛的早飯」的時候，是依「吃飯」這件事命名，不是依太陽位置，而且是早餐不是中餐，所以C最不適當。A有「大食」（早飯）和「小食」（下午飯），至少兩餐，正確。B太陽到正中後就開始西斜，可引申為盛極而衰，合理。D「昃」是太陽把人照出斜長的影子，「昏」是太陽降到人身高以下，都以人為參照，正確。", "skill": "「最不適當」題逐項回原文核對細節，命名依據、時間點這類小地方最容易被換掉。"}, {"n": 30, "qtype": "單選", "stem": "下列「」中的字，與該字的甲骨文字形本義最接近的是：", "options": {"A": "（項脊軒）又北向，不能得日，日過午已「昏」", "B": "天下有公利而「莫」或興之，有公害而莫或除之", "C": "俄而文皇來，精「采」驚人，長揖就坐，神清氣朗", "D": "臣歷觀前王嗣位之初，莫不躬勤庶政，坐以待「旦」"}, "answer": "D", "explain": "「旦」的本義是太陽剛升起，D「坐以待旦」就是等天亮，完全符合本義，選D。A的「昏」是因為房子朝北、照不到太陽而「昏暗」，不是太陽落下的黃昏時分。B的「莫」是否定詞「沒有人」，是後來的假借用法。C的「采」是「神采」，是假借的光彩義，本義是摘取果葉。", "skill": "本義題分三層：本義（造字原意）→引申義（意思相關的延伸）→假借義（借音不借義），只選第一層。"}], "difficulty": "中", "label": "109學測", "year": 109, "kind": "學測", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "虬髯客傳、諫太宗十思疏、項脊軒志、原君"}, {"id": "xc109-33", "exam": "xc109", "nums": [33, 34], "form": "題組", "img": "img/xc109-33.png", "source": "改寫自王德威《歷史與怪獸：歷史，暴力，敘事》（白話，引《爾雅》、《禮記》、《左傳》）", "author": "王德威", "genre": "其他", "types": ["文意推論", "比較閱讀"], "passage": "（本文為白話；所引文言如下）\n《爾雅》：「鬼之為言歸也。」\n《禮記》：「眾生必死，死必歸土：此之謂鬼。」\n《左傳‧昭公七年》：「鬼有所歸，乃不為厲，吾為之歸也。」", "translation": "《爾雅》：「鬼」的意思就是「歸」。\n《禮記》：所有生命都必定會死，死後一定回歸塵土，這就叫做鬼。\n《左傳》：鬼有了歸宿，才不會作祟害人，我是替它找個歸宿。", "keywords": [{"w": "之為言", "m": "意思就是（訓詁用語）"}, {"w": "厲", "m": "惡鬼、作祟"}, {"w": "大化", "m": "自然的大變化，指死亡回歸自然"}], "questions": [{"n": 33, "qtype": "單選", "stem": "下列敘述，符合文中經籍與通俗對「鬼」與「歸」詮釋的是：(A)經籍：人棄世歸返大化即為鬼／通俗：鬼不能忘情而歸返人間 (B)經籍：鬼不能忘情而歸返人間／通俗：人棄世歸返大化即為鬼 (C)經籍：鬼有所歸仍然可能為厲／通俗：鬼不能忘情而歸返人間 (D)經籍：人棄世歸返大化即為鬼／通俗：鬼有所歸仍然可能為厲", "options": {"A": "經籍：人棄世歸返大化即為鬼；通俗：鬼不能忘情而歸返人間", "B": "經籍：鬼不能忘情而歸返人間；通俗：人棄世歸返大化即為鬼", "C": "經籍：鬼有所歸仍然可能為厲；通俗：鬼不能忘情而歸返人間", "D": "經籍：人棄世歸返大化即為鬼；通俗：鬼有所歸仍然可能為厲"}, "answer": "A", "explain": "經籍（《爾雅》《禮記》）的「歸」是歸「去」：死了回歸塵土、回歸大化，就是鬼。通俗的說法把它顛倒成歸「來」：鬼放不下人間的喜怒哀樂，又回到人間。所以選A。B把兩邊對調了。C、D「鬼有所歸仍然可能為厲」和《左傳》「鬼有所歸，乃不為厲」（有歸宿就不作祟）意思相反。", "skill": "讀懂引文的關鍵否定字：「乃『不』為厲」一個字就能刪掉兩個選項。"}, {"n": 34, "qtype": "單選", "stem": "關於上文對「鬼」的看法，下列敘述最不適當的是：", "options": {"A": "人生而不免於死，鬼的存在，揭示生與死之間的時空分界", "B": "鬼的重返人世，反而說明陰陽永隔的生命裂變，不可回復", "C": "鬼顯現了人在此生與他生、大去與回歸間懸宕矛盾的欲念", "D": "為等待來世為人，新魂舊鬼穿梭徘徊於陰陽的時空縫隙中"}, "answer": "D", "explain": "文末說新魂舊鬼徘徊，是因為「不忍歸去，不能歸來」——放不下人間、又回不去，不是為了「等待來世為人」，文中完全沒提到投胎轉世，所以D最不適當。A對應「生與死被一層神祕的時空縫隙隔開」。B對應意娘的「回來」卻凸顯「陰陽永隔」。C對應鬼代表「對大去與回歸間，一股徘徊懸宕的欲念」。", "skill": "選項若加了文章沒說的「目的、原因」，通常就是錯的那一個。"}], "difficulty": "中", "label": "109學測", "year": 109, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc109-35", "exam": "xc109", "nums": [35], "form": "單題", "img": "img/xc109-35.png", "source": "諸葛亮〈出師表〉、徐宏祖〈遊黃山記〉、《戰國策》、王羲之〈蘭亭集序〉、《禮記‧禮運》、黃宗羲〈原君〉、陶淵明〈桃花源記〉、《史記‧項羽本紀》等", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)「陟」罰臧否，不宜異同／又「陟」一小巔，覺履底漸熱\n(B)呼曰：入之！王「面」牆，不敢入／呈卷，即「面」署第一\n(C)齊「放」其大臣孟嘗君於諸侯／或因寄所託，「放」浪形骸之外\n(D)男有「分」，女有歸／明乎為君之職「分」，則唐、虞之世，人人能讓\n(E)此人一一為「具」言所聞／項伯乃夜馳之沛公軍，私見張良，「具」告以事", "translation": "(A)升賞懲罰、褒善貶惡，不應該有不同標準／又登上一座小山頭，覺得鞋底漸漸發熱。\n(B)喊道：進去！王生面對牆壁，不敢進去／呈上考卷，當面就批為第一名。\n(C)齊國把大臣孟嘗君放逐到諸侯國去／有人把情懷寄託在所愛的事物上，放縱自己不受形體拘束。\n(D)男子有自己的職分，女子有好的歸宿／明白了做君主的職分，那麼唐堯、虞舜的時代，人人都能禮讓。\n(E)這個人一一詳細地說出他所聽到的事／項伯連夜騎馬到沛公軍營，私下見張良，把事情全部告訴他。", "keywords": [{"w": "陟", "m": "升官、獎賞；登上"}, {"w": "面", "m": "面對；當面"}, {"w": "放", "m": "放逐；放縱"}, {"w": "分", "m": "職分、本分"}, {"w": "具", "m": "詳盡、全部"}], "questions": [{"n": 35, "qtype": "多選", "stem": "下列各組文句「」內的詞義，前後相同的是：", "options": {"A": "「陟」罰臧否，不宜異同／又「陟」一小巔，覺履底漸熱", "B": "呼曰：入之！王「面」牆，不敢入／呈卷，即「面」署第一", "C": "齊「放」其大臣孟嘗君於諸侯／或因寄所託，「放」浪形骸之外", "D": "男有「分」，女有歸／明乎為君之職「分」，則唐、虞之世，人人能讓", "E": "此人一一為「具」言所聞／項伯乃夜馳之沛公軍，私見張良，「具」告以事"}, "answer": "DE", "explain": "A：前「陟」是升官獎賞（與「罰」相對），後是登上，不同。B：前「面」是面對（動詞），後是當面（副詞），不同。C：前「放」是放逐，後是放縱，不同。D：兩個「分」都是職分、本分，相同。E：兩個「具」都是詳盡、全部（通「俱」），相同。答案DE。", "skill": "判斷詞義先看詞性：同一個字在動詞位置和副詞位置，意思通常不一樣。"}], "difficulty": "中", "label": "109學測", "year": 109, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "大同與小康、鴻門宴、出師表、桃花源記、蘭亭集序、原君"}, {"id": "xc109-37", "exam": "xc109", "nums": [37], "form": "單題", "img": "img/xc109-37.png", "source": "蔣渭水〈入獄賦〉", "author": "蔣渭水", "genre": "其他", "types": ["寫作手法", "主旨寓意", "句意理解"], "passage": "蔣子曰：「蚊亦知夫秦與清乎？暴者如斯，而未嘗安也；受虧者如彼，而卒莫不興也。蓋將自其暴者而觀之，則其位曾不能以悠久也；自其受虧者而觀之，則仁與義皆無盡也，而又何悲乎！且夫天地之間，人各有權。茍非法文所許，雖一毫而莫侵。惟無額之給俸，與出張之旅費，爾得之而為產，民出之而甘心，取之無抗，徵之不拒，是島民者之無盡藏也，而任與你之所剝削。」蚊喜而笑，停足壁上。更夜已深，各自安眠，相與枕藉乎牢中，不知東方之既白。", "translation": "蔣先生說：「蚊子你也知道秦朝和清朝嗎？殘暴的人像那樣，卻從來沒有安穩過；受欺壓的人像那樣，最後沒有不興起的。如果從施暴者來看，他們的地位竟然不能長久；從受欺壓者來看，仁和義都是無窮無盡的，又有什麼好悲傷的呢！況且天地之間，人人各有權利。如果不是法律條文允許的，就算一根毫毛也不能侵犯。只有那沒有限額的薪俸，和出差的旅費，你們拿去當作財產，百姓拿出來還心甘情願，拿取也不反抗、徵收也不拒絕，這是島上人民的無盡寶藏，任憑你們去剝削。」蚊子高興地笑了，停在牆上。夜已經很深，各自安睡，在牢房裡互相枕著靠著睡著了，不知道東方已經發白。", "keywords": [{"w": "受虧者", "m": "受欺壓、吃虧的人"}, {"w": "曾不能", "m": "竟然不能"}, {"w": "法文", "m": "法律條文"}, {"w": "出張", "m": "出差（日語詞）"}, {"w": "無盡藏", "m": "取之不盡的寶藏"}, {"w": "枕藉", "m": "互相枕著躺臥"}], "questions": [{"n": 37, "qtype": "多選", "stem": "關於下文，適當的解說是：", "options": {"A": "套用蘇軾〈赤壁賦〉句型，並襲用文中盛衰無常的旨意", "B": "以秦、清兩朝終至覆滅的史實，推知剝削人民的執政者不能久存", "C": "藉受虧者的遭遇為誡，指出人民若一味姑息暴政，不足憐恤", "D": "「且夫天地之間，人各有權」意謂人民應有受法律保障的權利", "E": "「任與你之所剝削」是諷刺統治階層聚斂不已，人民莫可奈何"}, "answer": "BDE", "explain": "這篇是日治時期蔣渭水坐牢時，仿〈赤壁賦〉寫給牢中蚊子的遊戲文章，藉此諷刺殖民政府。A錯：句型確實套用〈赤壁賦〉（「客亦知夫水與月乎」「自其變者而觀之」），但〈赤壁賦〉講的是「變與不變」的人生觀照，本文講的是暴政不能長久、正義終將興起，並沒有沿用原旨。B對：秦、清殘暴卻「未嘗安」，可推知剝削者不能長存。C錯：文中說受虧者「卒莫不興」「仁與義皆無盡」，是安慰與肯定，不是責怪人民姑息。D對：「人各有權。茍非法文所許，雖一毫而莫侵」，就是人民權利受法律保障。E對：「無額之給俸、出張之旅費」任由官員拿取，是反諷統治者無止境搜括，人民只能任其剝削。答案BDE。", "skill": "仿作題要分開看「形式」和「內容」：句型像原作，不代表主旨也一樣。"}], "difficulty": "難", "label": "109學測", "year": 109, "kind": "學測", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "赤壁賦"}, {"id": "xc109-38", "exam": "xc109", "nums": [38], "form": "單題", "img": "img/xc109-38.png", "source": "唐宋筆記、元稹〈白氏長慶集序〉、白居易〈與元九書〉等所載白居易軼事", "author": "", "genre": "筆記小品", "types": ["文意推論", "句意理解"], "passage": "(A)開成中，物價至賤，村路賣魚肉者，俗人買以胡綃半尺，士大夫買以樂天詩\n(B)〈長恨歌〉一篇，……文人學士既嘆為不可及，婦人女子亦喜聞而樂誦之，是以不脛而走\n(C)有軍使高霞寓者欲聘倡伎，伎大誇曰：「我誦得白學士〈長恨歌〉，豈同他伎哉？」由是增價\n(D)樂天〈秦中吟〉、〈賀雨〉、〈諷諭〉等篇，……繕寫模勒衒賣於市井，或持之以交酒茗者，處處皆是\n(E)唐中葉，長安惡少年多以詩句鑱涅肌膚（即「刺青」），……至有周身用白樂天詩意刺涅，人呼為白舍人行詩圖", "translation": "(A)開成年間，物價極低，鄉村路上賣魚肉的，一般人用半尺胡綃來買，讀書人用白居易的詩來買。\n(B)〈長恨歌〉這一篇，文人學士讚嘆趕不上，婦女也喜歡聽、樂意背，所以不用推廣就流傳開來。\n(C)有個軍使高霞寓想聘請歌伎，歌伎大大誇口：「我會背白學士的〈長恨歌〉，怎麼能跟其他歌伎一樣呢？」因此身價提高。\n(D)白居易的〈秦中吟〉等詩，被人抄寫刻印，在市場上叫賣，或拿來換酒換茶的，到處都是。\n(E)唐朝中葉，長安的不良少年常把詩句刺在皮膚上，甚至有人全身刺上白居易的詩意，人們叫他「白舍人行詩圖」。", "keywords": [{"w": "胡綃", "m": "西域傳來的薄絲織品"}, {"w": "不脛而走", "m": "沒有腳卻跑得很快，比喻流傳迅速"}, {"w": "增價", "m": "提高身價"}, {"w": "模勒", "m": "刻印"}, {"w": "衒賣", "m": "叫賣"}, {"w": "鑱涅", "m": "刺字並塗上墨，即刺青"}], "questions": [{"n": 38, "qtype": "多選", "stem": "某篇討論唐代商業與文學的文章提到：「白居易的文壇聲譽，是商業市場的有用資本」。下列文句，可佐證此一觀點的是：", "options": {"A": "開成中，物價至賤，村路賣魚肉者，俗人買以胡綃半尺，士大夫買以樂天詩", "B": "〈長恨歌〉一篇，……文人學士既嘆為不可及，婦人女子亦喜聞而樂誦之，是以不脛而走", "C": "有軍使高霞寓者欲聘倡伎，伎大誇曰：「我誦得白學士〈長恨歌〉，豈同他伎哉？」由是增價", "D": "樂天〈秦中吟〉、〈賀雨〉、〈諷諭〉等篇，……繕寫模勒衒賣於市井，或持之以交酒茗者，處處皆是", "E": "唐中葉，長安惡少年多以詩句鑱涅肌膚（即「刺青」），……至有周身用白樂天詩意刺涅，人呼為白舍人行詩圖"}, "answer": "ACD", "explain": "關鍵是「商業市場的資本」，也就是白詩能換錢、能抬價、能買賣。A對：白詩可以當貨幣買魚肉。B錯：只說明〈長恨歌〉很受歡迎、流傳很快，沒有買賣交易。C對：歌伎會背〈長恨歌〉就「增價」，白詩成了提高身價的資本。D對：白詩被抄寫刻印在市場叫賣、拿來換酒茶。E錯：把白詩刺在身上只是流行與崇拜，沒有商業交易。答案ACD。", "skill": "佐證題抓題目的核心概念（這題是「商業」），選項光說「很紅」不夠，要有交易或價格才算數。"}], "difficulty": "中", "label": "109學測", "year": 109, "kind": "學測", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "xc109-39", "exam": "xc109", "nums": [39], "form": "單題", "img": "img/xc109-39.png", "source": "歐陽脩〈醉翁亭記〉、《楚辭‧漁父》、歐陽脩《新五代史‧馮道傳論》、《左傳‧燭之武退秦師》、蘇轍〈黃州快哉亭記〉", "author": "", "genre": "其他", "types": ["虛詞句式", "寫作手法"], "passage": "(A)醉能同其樂，醒能述以文者，太守也。太守謂誰？廬陵歐陽脩也\n(B)寧赴湘流，葬於江魚之腹中；安能以皓皓之白，而蒙世俗之塵埃乎\n(C)況為大臣而無所不取，無所不為，則天下其有不亂，國家其有不亡者乎\n(D)且君嘗為晉君賜矣，許君焦、瑕，朝濟而夕設版焉，君之所知也。夫晉，何厭之有\n(E)昔楚襄王從宋玉、景差於蘭臺之宮，有風颯然至者，王披襟當之，曰：快哉此風！寡人所與庶人共者耶", "translation": "(A)醉了能和大家同樂，醒了能用文章記述的，是太守。太守是誰？是廬陵的歐陽脩。\n(B)我寧可投入湘江，葬身魚腹；怎麼能讓潔白的自己，蒙上世俗的塵埃呢？\n(C)何況身為大臣卻什麼都拿、什麼都做，那天下哪有不亂、國家哪有不亡的呢？\n(D)而且您曾經對晉君施恩，他答應把焦、瑕兩地給您，結果早上渡河回國，晚上就築牆防禦，這是您知道的。晉國，哪有滿足的時候？\n(E)從前楚襄王帶著宋玉、景差在蘭臺宮遊玩，一陣風颯颯吹來，襄王敞開衣襟迎風說：「這風真暢快啊！這是我和百姓共同享有的吧？」", "keywords": [{"w": "安能……乎", "m": "怎麼能……呢（反問）"}, {"w": "其有……者乎", "m": "哪裡會有……的呢（反問）"}, {"w": "何厭之有", "m": "有什麼滿足的（賓語前置的反問句）"}, {"w": "設版", "m": "築牆防禦"}, {"w": "謂誰", "m": "是誰（設問）"}], "questions": [{"n": 39, "qtype": "多選", "stem": "文學作品中，常以反問的形式來加強論述或自抒懷抱，例如「人生自古誰無死？留取丹心照汗青」。下列文句，運用此文學手法的是：", "options": {"A": "醉能同其樂，醒能述以文者，太守也。太守謂誰？廬陵歐陽脩也", "B": "寧赴湘流，葬於江魚之腹中；安能以皓皓之白，而蒙世俗之塵埃乎", "C": "況為大臣而無所不取，無所不為，則天下其有不亂，國家其有不亡者乎", "D": "且君嘗為晉君賜矣，許君焦、瑕，朝濟而夕設版焉，君之所知也。夫晉，何厭之有", "E": "昔楚襄王從宋玉、景差於蘭臺之宮，有風颯然至者，王披襟當之，曰：快哉此風！寡人所與庶人共者耶"}, "answer": "BCD", "explain": "反問＝答案就在問題的反面，問了不必回答。A是「提問」（自問自答）：問「太守謂誰」，馬上答「廬陵歐陽脩也」，不是反問。B「安能……乎」＝絕不能讓潔白蒙塵，是屈原自抒懷抱的反問。C「其有不亂……者乎」＝天下一定亂、國家一定亡，用反問加強論述。D「何厭之有」＝晉國根本不會滿足，反問。E「寡人所與庶人共者耶」是楚王帶著得意、推測的語氣說「這是我和百姓共享的吧」，屬於一般疑問、感嘆，並非反問加強論述。答案BCD。", "skill": "判斷反問：把問句改成反面的肯定或否定句，意思通順而且更有力，才是反問；自問自答是提問。"}], "difficulty": "中", "label": "109學測", "year": 109, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "燭之武退秦師、漁父、醉翁亭記"}, {"id": "xc109-40", "exam": "xc109", "nums": [40], "form": "單題", "img": "img/xc109-40.png", "source": "孟浩然〈望洞庭湖贈張丞相〉、李白〈宣州謝朓樓餞別校書叔雲〉、杜甫〈旅夜書懷〉等詩詞（題目未標出處）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "典故出處"], "passage": "(A)欲濟無「舟楫」，端居恥聖明。坐觀垂釣者，徒有羨魚情\n(B)抽刀斷水水更流，舉杯銷愁愁更愁。人生在世不稱意，明朝散髮弄「扁舟」\n(C)跡不趨時分不侯，功名身外最悠悠。聽君總畫麒麟閣，還我閒眠「舴艋舟」\n(D)細草微風岸，危檣獨夜「舟」。星垂平野闊，月湧大江流。名豈文章著，官應老病休。飄飄何所似，天地一沙鷗\n(E)「綵舟」載得離愁動，無端更借樵風送。波渺夕陽遲，銷魂不自持。良宵誰與共，賴有窗間夢。可奈夢回時，一番新別離", "translation": "(A)想渡湖卻沒有船，閒居在家又愧對聖明的時代；坐看別人釣魚，只能空有羨慕魚的心情（比喻想出仕卻無人引薦）。\n(B)拔刀砍水水流得更急，舉杯消愁愁更深。人活在世上不如意，明天就披散頭髮，駕著小船漂遊江湖去。\n(C)行事不追逐時勢，命中也不該封侯，功名是身外之物最渺遠。任憑你們都被畫進麒麟閣，還給我在小船上悠閒睡覺的日子吧。\n(D)微風吹拂岸邊細草，高高桅杆的小船獨自停在夜裡……我四處飄泊像什麼呢？就像天地間一隻沙鷗。\n(E)彩船載著離愁啟程，偏偏又借著順風送走。……", "keywords": [{"w": "舟楫", "m": "船，比喻引薦的人"}, {"w": "散髮", "m": "不束髮戴冠，指不做官"}, {"w": "扁舟", "m": "小船，常喻歸隱江湖"}, {"w": "麒麟閣", "m": "漢代畫功臣像之處，代表功名"}, {"w": "舴艋舟", "m": "小船"}, {"w": "危檣", "m": "高聳的桅杆"}], "questions": [{"n": 40, "qtype": "多選", "stem": "孔子曾慨嘆「道不行，乘桴浮於海」，莊子則以為隱逸之士心無所求，「飽食而敖遊，汎若不繫之舟」，二者均以舟船暗指隱逸遁世。下列詩詞，用舟船意象暗指隱逸遁世的是：", "options": {"A": "欲濟無「舟楫」，端居恥聖明。坐觀垂釣者，徒有羨魚情", "B": "抽刀斷水水更流，舉杯銷愁愁更愁。人生在世不稱意，明朝散髮弄「扁舟」", "C": "跡不趨時分不侯，功名身外最悠悠。聽君總畫麒麟閣，還我閒眠「舴艋舟」", "D": "細草微風岸，危檣獨夜「舟」。星垂平野闊，月湧大江流。名豈文章著，官應老病休。飄飄何所似，天地一沙鷗", "E": "「綵舟」載得離愁動，無端更借樵風送。波渺夕陽遲，銷魂不自持。良宵誰與共，賴有窗間夢。可奈夢回時，一番新別離"}, "answer": "BC", "explain": "A錯：孟浩然說「想渡河卻沒有船」，船比喻引薦的人，他其實想當官，和隱逸相反。B對：李白說不如意就「散髮弄扁舟」，丟掉官帽去江湖漂遊，是隱逸。C對：不求功名，「還我閒眠舴艋舟」，表示寧可回到小船上過閒適隱居的生活。D錯：杜甫〈旅夜書懷〉的夜舟是他飄泊的實景，寫的是老病漂泊的孤寂，不是隱逸。E錯：「綵舟」載著離愁，寫的是離別相思。答案BC。", "skill": "同一個意象可以有不同寓意：舟楫＝引薦，扁舟＝歸隱，孤舟＝漂泊，要回到整首詩的情緒判斷。"}], "difficulty": "中", "label": "109學測", "year": 109, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc109-41", "exam": "xc109", "nums": [41], "form": "單題", "img": "img/xc109-41.png", "source": "《韓非子》（難一、備內、主道）、《墨子‧兼愛》、《孟子‧離婁下》", "author": "", "genre": "說理議論", "types": ["文意推論", "比較閱讀"], "passage": "(A)臣盡死力以與君市，君垂爵祿以與臣市，君臣之際，非父子之親也\n(B)若使天下兼相愛，國與國不相攻，……君臣父子皆能孝慈，若此則天下治\n(C)人主之患在於信人，信人則制於人。人臣之於其君，非有骨肉之親也，縛於勢而不得不事也\n(D)君之視臣如手足，則臣視君如腹心；君之視臣如犬馬，則臣視君如國人；君之視臣如土芥，則臣視君如寇讎\n(E)臣閉其主，則主失位；臣制財利，則主失德；臣擅行令，則主失制；臣得行義，則主失名；臣得樹人，則主失黨", "translation": "(A)臣子拚命出力來跟君主交易，君主拿出爵位俸祿來跟臣子交易，君臣之間，不是父子那樣的親情。\n(B)假如天下人都彼此相愛，國與國不互相攻打……君臣父子都能孝順慈愛，這樣天下就太平了。\n(C)君主的禍患在於相信別人，相信別人就會被別人控制。臣子對於君主，並沒有骨肉親情，只是被權勢綁住，不得不侍奉罷了。\n(D)君主把臣子看成手足，臣子就把君主看成心腹；君主把臣子看成犬馬，臣子就把君主看成路人；君主把臣子看成泥土草芥，臣子就把君主看成仇敵。\n(E)臣子蒙蔽君主，君主就失去地位；臣子掌控財利，君主就失去施恩的能力；臣子擅自發號施令，君主就失去控制；臣子能自行施義，君主就失去名聲；臣子能培植黨羽，君主就失去支持者。", "keywords": [{"w": "市", "m": "交易、買賣"}, {"w": "垂", "m": "賜予"}, {"w": "縛於勢", "m": "被權勢約束"}, {"w": "國人", "m": "一般路人"}, {"w": "寇讎", "m": "仇敵"}, {"w": "閉", "m": "蒙蔽"}], "questions": [{"n": 41, "qtype": "多選", "stem": "韓非認為君臣之間充滿利害算計，主張君王須大權獨攬，以威勢和刑賞駕馭臣下。下列文句，符合韓非思想的是：", "options": {"A": "臣盡死力以與君市，君垂爵祿以與臣市，君臣之際，非父子之親也", "B": "若使天下兼相愛，國與國不相攻，……君臣父子皆能孝慈，若此則天下治", "C": "人主之患在於信人，信人則制於人。人臣之於其君，非有骨肉之親也，縛於勢而不得不事也", "D": "君之視臣如手足，則臣視君如腹心；君之視臣如犬馬，則臣視君如國人；君之視臣如土芥，則臣視君如寇讎", "E": "臣閉其主，則主失位；臣制財利，則主失德；臣擅行令，則主失制；臣得行義，則主失名；臣得樹人，則主失黨"}, "answer": "ACE", "explain": "A對：君臣關係是「交易」（市），沒有親情，正是利害算計。B錯：「兼相愛」是墨子思想。C對：君主不能相信臣子，臣子只是被「勢」綁住才服從，強調君主要握有威勢。D錯：這是孟子對齊宣王說的話，強調君臣相待要以禮、互相對等，屬儒家。E對：列出臣子奪權的五種情形，提醒君主大權不可旁落，符合「大權獨攬」。答案ACE。", "skill": "諸子判別看關鍵詞：市、勢、刑賞→法家；兼愛→墨家；手足腹心、仁義→儒家。"}], "difficulty": "易", "label": "109學測", "year": 109, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc109-42", "exam": "xc109", "nums": [42], "form": "單題", "img": "img/xc109-42.png", "source": "古典散文文學常識", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "書論宜理", "m": "曹丕〈典論論文〉語，指書信、論說類文章應重說理"}, {"w": "唐宋八大家", "m": "韓愈、柳宗元、歐陽脩、蘇洵、蘇軾、蘇轍、王安石、曾鞏"}, {"w": "小品文", "m": "晚明篇幅短小、抒寫性靈的散文"}], "questions": [{"n": 42, "qtype": "多選", "stem": "關於古典散文，下列敘述適當的是：", "options": {"A": "《左傳》擅於敘事及刻劃人物，尤其長於以應對辭令描繪人物性格、鋪陳故事發展，標誌著先秦時期敘事散文的高度成就", "B": "先秦諸子散文富涵哲理，長於論辯。《孟子》善於運用譬喻和寓言來加強論述；《荀子》據題抒論，長於說理，皆是議論散文的出色之作", "C": "《史記》的文筆雄奇雅健，後世奉為散文的典範，為魏晉時期文人的師法對象，曹丕〈典論論文〉中的「書論宜理」，即是以《史記》為代表", "D": "韓愈、柳宗元提倡古文運動，革新六朝文風，宋代歐陽脩、王安石、曾鞏、三蘇等人繼起，主張文道並重，成就斐然，後人譽為「唐宋八大家」", "E": "晚明時期，篇幅短小、風格自由活潑、強調抒寫情性的小品文蔚為風潮，袁宏道即代表作家之一"}, "answer": "ABDE", "explain": "A對：《左傳》以辭令寫人敘事，是先秦敘事散文高峰（如〈燭之武退秦師〉）。B對：《孟子》多用譬喻寓言（如揠苗助長），《荀子》是有題目的專題論文，都是議論文佳作。C錯：魏晉六朝流行駢文，《史記》要到唐宋古文運動才被大力推崇；〈典論論文〉的「書論宜理」是在講文體特性，並沒有舉《史記》為代表。D對：唐代韓、柳加上宋代六家，合稱唐宋八大家。E對：袁宏道是晚明公安派代表，主張「獨抒性靈」，擅寫小品文。答案ABDE。", "skill": "文學史題抓「時代＋代表」：魏晉重駢文、唐宋重古文、晚明重小品，時代對不上就是錯。"}], "difficulty": "中", "label": "109學測", "year": 109, "kind": "學測", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "典論論文"}, {"id": "zk109-05", "exam": "zk109", "nums": [5], "form": "單題", "img": "img/zk109-05.png", "source": "詠物詩四首（(D)為李綱〈病牛〉，其餘出處待查）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "", "translation": "(A)凍寒中的花蕊凝著香氣，像雪一樣鮮豔清新，在小山深谷中陪伴隱居的人。知道你有意展現凌寒的姿態，羞於和千百種花一起在春天開放。\n(B)草木好像也有情感，葉子討厭被人觸碰、躲避人的嘲笑。也知道指出奸佞從來沒有用處，請問你含羞是為了誰呢？\n(C)百尺高的扶桑樹讓萬木都顯得低矮，朝陽下與五色鳳凰同棲。每天報曉喚醒千家萬戶，警戒天亮總比百鳥先啼。\n(D)耕犁了千畝田，收穫裝滿千箱，力氣用盡、筋骨疲憊，又有誰來憐惜？只要眾生都能吃飽，就算瘦弱生病倒臥在夕陽下也不推辭。", "keywords": [{"w": "塢", "m": "山間低地"}, {"w": "凌寒", "m": "冒著嚴寒"}, {"w": "指佞", "m": "指出奸佞小人（傳說中的指佞草）"}, {"w": "司晨", "m": "掌管報曉"}, {"w": "羸", "m": "瘦弱"}], "questions": [{"n": 5, "qtype": "單選", "stem": "關於下列詠物詩畫底線處之物的形貌特質與詩人的情志，敘述最適當的是：", "options": {"A": "「凍蕊凝香雪豔新，小山深塢伴幽人。知君有意凌寒色，羞共千花一樣春。」描寫梅花無懼嚴寒而綻放，宣示不隨俗浮沉的堅持", "B": "「草木多情似有之，葉憎人觸避人嗤。也知指佞曾無補，試問含羞卻為誰。」描寫含羞草以閉合葉片回應人的觸碰，蘊藏笑罵由人的生命態度", "C": "「百尺扶桑萬木低，朝陽五色鳳同棲。司晨每喚千家醒，戒旦常先百鳥啼。」描寫雞隻每於破曉之時先鳴，叫醒眾人，流露眾人皆醉我獨醒的寂寞", "D": "「耕犁千畝實千箱，力盡筋疲誰復傷。但得眾生皆得飽，不辭羸病臥殘陽。」描寫牛耗竭心力耕作，換來糧倉的豐實，展現厚植實力，無人可傷的自信"}, "answer": "A", "explain": "(A)正確：梅花「凌寒」開放，「羞共千花一樣春」，表示不願和眾花一樣在春天爭豔，正是不隨俗浮沉的堅持。\n(B)錯：「也知指佞曾無補，試問含羞卻為誰」是說指出奸佞也沒用，只好含羞退縮，帶有無奈自嘲，不是「笑罵由人」的豁達。\n(C)錯：雞「每喚千家醒」「常先百鳥啼」，展現的是盡責、先知先覺，沒有「眾人皆醉我獨醒」的寂寞。\n(D)錯：牛「力盡筋疲」「不辭羸病臥殘陽」，是犧牲奉獻、只求眾生溫飽，不是展現無人可傷的自信。", "skill": "詠物詩抓「物的特性→詩人借它說的志向」，再看選項的情志有沒有被改成相反或過度的說法。"}], "difficulty": "中", "label": "109指考", "year": 109, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk109-06", "exam": "zk109", "nums": [6], "form": "單題", "img": "img/zk109-06.png", "source": "王思任〈屠田叔笑詞序〉", "author": "王思任", "genre": "書信序跋", "types": ["文意推論", "主旨寓意"], "passage": "笑亦多術矣，然真於孩，樂於壯，而苦於老。海上憨先生者，老矣。歷盡寒暑，勘破玄黃，舉人間世一切蝦蟆傀儡，馬牛魑魅，搶攘忙迫之態，用醉眼一縫，盡行囊括。日居月諸，堆堆積積，不覺胸中五嶽墳起。欲嘆則氣短，欲罵則惡聲有限，欲哭則為其近於婦人。於是破涕為笑，極笑之變，各賦一詞，而以之囊括天下之苦事。", "translation": "笑也有很多種，但小孩的笑是真心的，壯年的笑是快樂的，老年的笑是苦澀的。海邊有一位憨先生，已經老了。他經歷了人生冷暖，看透了天地萬物，把人世間一切像蝦蟆、傀儡、馬牛、鬼怪般忙亂爭搶的醜態，都用醉眼瞇成一條縫，全部收進眼裡。日積月累，堆積起來，不知不覺胸中像有五嶽隆起般鬱積不平。想嘆氣卻氣短，想罵人可惡毒的話有限，想哭又覺得太像婦人。於是破涕為笑，把笑的各種變化發揮到極致，每種笑寫一首詞，用它來概括天下所有的苦事。", "keywords": [{"w": "勘破玄黃", "m": "看透天地（玄黃指天地）"}, {"w": "魑魅", "m": "山林鬼怪"}, {"w": "搶攘", "m": "紛亂"}, {"w": "日居月諸", "m": "日月流逝"}, {"w": "墳起", "m": "隆起"}], "questions": [{"n": 6, "qtype": "單選", "stem": "依據下文對「笑」的看法，敘述最適當的是：", "options": {"A": "即便老去，也努力追求純真的笑", "B": "遍嘗冷暖，唯在醉中能以笑紓憤", "C": "歷經興衰，終於能掌握笑的樣態", "D": "閱盡人生，方知萬事可一笑概括"}, "answer": "D", "explain": "憨先生「歷盡寒暑，勘破玄黃」，看盡世間醜態，嘆、罵、哭都不行，最後「破涕為笑」，用笑「囊括天下之苦事」，所以是(D)閱盡人生，萬事可以一笑概括。\n(A)文中說老年的笑是「苦」的，他不是努力追求孩子般純真的笑。\n(B)「醉眼一縫」是他看世界的方式，並沒有說「只有」在醉中才能笑。\n(C)「極笑之變」是把各種笑寫成詞，用來包括苦事，重點不是終於掌握笑的樣態。", "skill": "序文主旨常在結尾「於是……而以之……」，直接翻譯最後一句就能找到答案。"}], "difficulty": "中", "label": "109指考", "year": 109, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk109-07", "exam": "zk109", "nums": [7], "form": "單題", "img": "img/zk109-07.png", "source": "崔顥〈黃鶴樓〉、李煜〈浪淘沙〉、黃庭堅〈寄黃幾復〉、關漢卿〈大德歌‧秋〉", "author": "", "genre": "古典詩詞曲", "types": ["文化常識", "詩詞賞析"], "passage": "", "translation": "(A)從前的仙人已經乘黃鶴離去，這裡只留下空空的黃鶴樓。\n(B)在夢裡忘了自己是寄人籬下的俘虜，享受了片刻的歡樂。\n(C)我住在北海、你住在南海，想託鴻雁傳信，雁卻推辭說做不到。\n(D)秋蟬叫完了換蟋蟀叫，淅淅瀝瀝的細雨灑在芭蕉上。", "keywords": [{"w": "一晌", "m": "片刻"}, {"w": "寒蛩", "m": "秋天的蟋蟀"}, {"w": "襯字", "m": "曲中在格律規定字數外另加的字"}, {"w": "點鐵成金", "m": "化用前人詞句而使其更好，江西詩派主張"}], "questions": [{"n": 7, "qtype": "單選", "stem": "作品可反映體裁、流派特色。關於下列詩詞曲作品，敘述正確的是：", "options": {"A": "崔顥〈黃鶴樓〉首聯「昔人已乘黃鶴去，此地空餘黃鶴樓」，因其對仗工整，後人譽此詩為唐人七律傑作", "B": "李煜〈浪淘沙〉「夢裡不知身是客，一晌貪歡」，流露故國之思，不但拓展詞的境界，也開後世豪放詞風之先", "C": "黃庭堅〈寄黃幾復〉「我居北海君南海，寄雁傳書謝不能」化用典故，展現了江西詩派點鐵成金的風格", "D": "關漢卿〈大德歌秋〉「秋蟬兒噪罷寒蛩兒叫，淅零零細雨灑芭蕉」中「兒、淅零零」為襯字，元曲使用襯字與文句長短有關，文句長襯字多，文句短襯字少"}, "answer": "C", "explain": "(C)正確：黃庭堅是江西詩派之祖，主張「點鐵成金」；「寄雁傳書謝不能」化用鴻雁傳書（及雁至衡陽而止）的典故，翻出新意。\n(A)錯：「昔人已乘黃鶴去，此地空餘黃鶴樓」並不對仗（律詩首聯本來就不必對仗），此詩受推崇是因氣勢與情韻，不是首聯對仗工整。\n(B)錯：李煜亡國後的詞拓展了詞的境界，但「開豪放詞風之先」的是蘇軾，李煜詞風是深婉沉痛。\n(D)錯：襯字的多少由作者自由增加，和文句長短沒有「句長襯字多、句短襯字少」的規律。", "skill": "文學常識題，把每個選項拆成「作品事實」和「評價」兩半，兩半都要對才選。"}], "difficulty": "中", "label": "109指考", "year": 109, "kind": "指考", "textcat": "文學文本", "textcat2": "學術文本", "linked_core": ""}, {"id": "zk109-12", "exam": "zk109", "nums": [12, 13, 14], "form": "題組", "img": "img/zk109-12.png", "source": "選項引文：《管子‧牧民》、《論語‧顏淵》、《論語‧衛靈公》、《孟子‧梁惠王上》", "author": "", "genre": "經典語錄", "types": ["文意推論", "比較閱讀"], "passage": "(A)衣食足則知榮辱\n(B)足食，足兵，民信之矣\n(C)君子憂道不憂貧\n(D)數罟不入洿池，魚鱉不可勝食也", "translation": "(A)人民衣食充足了，才懂得榮譽和恥辱。\n(B)使糧食充足、軍備充足，人民就會信任政府。\n(C)君子擔憂的是道能否實行，不擔憂自己貧窮。\n(D)細密的漁網不放進池塘捕魚，魚鱉就吃不完。", "keywords": [{"w": "數罟", "m": "細密的漁網"}, {"w": "洿池", "m": "深水池"}, {"w": "憂道", "m": "憂慮道之不行"}], "questions": [{"n": 12, "qtype": "單選", "stem": "根據上文文意脈絡，甲、乙最適合填入的概念依序是：", "options": {"A": "生存需求／價值實現需求", "B": "價值實現需求／價值實現需求", "C": "生存需求／生存需求與價值實現需求", "D": "價值實現需求／生存需求與價值實現需求"}, "answer": "B", "explain": "甲處問的是孟子所說「人之所以異於禽獸者」——也就是價值實現的需求，而且「我欲仁，斯仁至矣」是實踐的問題；乙處說每個人在生命中「感受到」的，也是這種價值實現的需求。所以兩處都是「價值實現需求」，選(B)。\n(A)(C)甲填生存需求不對，生存需求是人與動物共有的部分。\n(D)乙填「生存需求與價值實現需求」太寬，文章強調的是人格自覺的價值實現。", "skill": "填空前後若有引文（我欲仁），先判斷引文在談哪一種概念，空格就填那個概念。"}, {"n": 13, "qtype": "單選", "stem": "依據上文，關於中西文化的差異，敘述最適當的是：", "options": {"A": "中華文化的發展與自然的人文發展進程不同", "B": "西方追求人存在的尊嚴，便是免於匱乏與恐懼", "C": "儒學和西方都將價值實現需求視為生存首要目標", "D": "中西文化的差異，在於是否透過教育來認知價值"}, "answer": "A", "explain": "(A)正確：文章說西方依「自然的人文發展進程」先謀生再求價值，但「中華文化的發展卻非循這自然進程以行」。\n(B)錯：免於匱乏與恐懼是生存的初級需求，不是存在的尊嚴。\n(C)錯：西方的科學與民主是針對初級需求，並非把價值實現當首要目標。\n(D)錯：文中說這不是認知問題，差異不在是否透過教育來認知價值。", "skill": "對比型文章，先畫出「中／西」兩欄各寫一句特點，再對選項。"}, {"n": 14, "qtype": "單選", "stem": "下列文句最符合上文「特殊的中華文化形態」的是：", "options": {"A": "衣食足則知榮辱", "B": "足食，足兵，民信之矣", "C": "君子憂道不憂貧", "D": "數罟不入洿池，魚鱉不可勝食也"}, "answer": "C", "explain": "「特殊的中華文化形態」是：多數人還困於衣食時，文化菁英已直視人性的終極需求並以此教化。(C)「君子憂道不憂貧」——不擔心貧窮而擔心道，正是先重價值而不待衣食充足，最符合。\n(A)「衣食足則知榮辱」是先滿足生存再談價值，屬於文中所說「自然進程」。\n(B)「足食，足兵」是治國的基本條件，偏重生存安全。\n(D)「數罟不入洿池」是讓百姓吃得飽的養民措施，屬生存需求。", "skill": "先把文中概念換成一個判斷標準（價值先於溫飽），再檢查每句文言是「先溫飽」還是「先價值」。"}], "difficulty": "中", "label": "109指考", "year": 109, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk109-15", "exam": "zk109", "nums": [15, 16, 17], "form": "題組", "img": "img/zk109-15.png", "source": "《孔子家語‧致思》", "author": "", "genre": "經典語錄", "types": ["人物情感", "文意推論", "虛詞句式"], "passage": "子路為蒲宰，為水備，與其民修溝瀆。以民之勞煩苦也，人與之一簞食、一壺漿。孔子聞之，使子貢止之。子路忿不說，往見孔子曰：「由也以暴雨將至，恐有水災，故與民修溝洫以備之。而民多匱餓者，是以簞食壺漿而與之。夫子使賜止之，是夫子止由之行仁也。夫子以仁教，而禁其行，由不受也。」孔子曰：「汝以民為餓也，何不白于君，發倉廩以賑之？而私以爾食饋之，是汝明君之無惠而見己之德美矣。汝速已則可，不則汝之見罪必矣。」", "translation": "子路擔任蒲邑的長官，為了防備水災，和百姓一起修築水溝。因為百姓勞動辛苦，就給每人一竹筐飯、一壺湯。孔子聽說了，派子貢去阻止他。子路生氣不高興，去見孔子說：「我因為暴雨將到，擔心有水災，所以和百姓修溝渠來防備。而百姓很多人缺糧挨餓，所以送飯和湯給他們。老師派子貢阻止我，這是老師阻止我行仁啊。老師用仁來教導我們，卻禁止我去實行，我不能接受。」孔子說：「你認為百姓在挨餓，為什麼不稟告國君，打開糧倉來救濟他們？卻私下用你自己的糧食送給他們，這是在彰顯國君沒有恩惠，而顯露自己德行美好啊。你趕快停止還來得及，不然你一定會被治罪。」", "keywords": [{"w": "宰", "m": "地方長官"}, {"w": "溝洫", "m": "田間水溝"}, {"w": "簞", "m": "盛飯的竹器"}, {"w": "說", "m": "通「悅」"}, {"w": "白", "m": "稟告"}, {"w": "賑", "m": "救濟"}, {"w": "見", "m": "顯露、彰顯"}], "questions": [{"n": 15, "qtype": "單選", "stem": "子路「忿不說」，是因為他認為孔子：", "options": {"A": "另派子貢，取而代之", "B": "體恤災民，毫無限度", "C": "拒絕饋贈，不通人情", "D": "言行不一，自相矛盾"}, "answer": "D", "explain": "子路說「夫子以仁教，而禁其行，由不受也」：老師教我們行仁，卻禁止我行仁，在他看來孔子言行不一，所以(D)正確。\n(A)子貢只是傳話阻止，不是取而代之。\n(B)子路沒有批評孔子無限度體恤災民。\n(C)子路沒有說孔子不通人情、拒絕饋贈。", "skill": "問人物為何生氣，直接找他生氣後說的話，最後一句通常就是理由。"}, {"n": 16, "qtype": "單選", "stem": "依據上文，最符合孔子之意的是：", "options": {"A": "要把國家資源給最需要者", "B": "要實行仁政應先以身作則", "C": "不可將服務人民當成施恩", "D": "不宜冒進而凸顯長官失德"}, "answer": "D", "explain": "孔子認為子路應「白于君，發倉廩以賑之」，私下送飯會「明君之無惠而見己之德美」，也就是自作主張、反而凸顯國君沒有恩德，所以(D)「不宜冒進而凸顯長官失德」最符合。\n(A)孔子雖說應發倉廩，但重點不是資源分配給誰。\n(B)文中沒有談以身作則。\n(C)孔子沒有說服務人民不能是施恩，他反對的是「私下」施恩而顯得國君無惠。", "skill": "找人物真正擔心的「後果」（汝之見罪必矣、明君之無惠），主旨通常就藏在後果裡。"}, {"n": 17, "qtype": "單選", "stem": "下列各組文句中的「以」，用法相同的是：", "options": {"A": "由也「以」暴雨將至／吾本寒家，世「以」清白相承", "B": "修溝洫「以」備之／君人者，誠能見可欲，則思知足「以」自戒", "C": "夫子「以」仁教／蓋將自其變者而觀之，則天地曾不能「以」一瞬", "D": "汝「以」民為餓也／道士笑而允之，乃傳「以」訣，令自咒"}, "answer": "B", "explain": "(B)相同：「修溝洫以備之」「知足以自戒」的以都是連詞，表目的，相當於「來」。\n(A)不同：「由也以暴雨將至」的以是「因為」；「世以清白相承」的以是「憑藉、用」。\n(C)不同：「夫子以仁教」的以是「用」；「曾不能以一瞬」的以是「在」（連一眨眼的時間都不能維持）。\n(D)不同：「汝以民為餓也」是「以……為」，認為；「傳以訣」的以是「把」。", "skill": "「以」的判斷：以＋名詞＋動詞多為「用、憑」；動詞＋以＋動詞多為「來」；以A為B是「認為／把」。"}], "difficulty": "中", "label": "109指考", "year": 109, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk109-18", "exam": "zk109", "nums": [18, 19], "form": "題組", "img": "img/zk109-18.png", "source": "陳亮恭《微霞與桑榆》（文中引《禮記‧禮運》及史籍文句）", "author": "陳亮恭", "genre": "其他", "types": ["文意推論", "文化常識"], "passage": "老有所終，壯有所用，幼有所長，矜寡孤獨廢疾者皆有所養。\n於錄事耆壽中，揀一人有名行謹信，為鄉里所稱者，專令勾當。\n鰥寡孤獨貧乏不得自存者，知州、通判、縣令、佐驗實，官為居養之。\n多合居養、安濟而為一，名之曰養濟院。\n民之孤獨殘病不能生者，許入院。", "translation": "讓老人得以安享天年，壯年人有所發揮，幼兒得以成長，鰥夫、寡婦、孤兒、無子的老人與殘疾病患都能得到供養。\n（唐武宗）從地方年高有德的人中，挑選一位名聲品行謹慎誠信、被鄉里稱道的人，專門負責管理。\n（宋哲宗）鰥寡孤獨、貧困無法自己生活的人，由知州、通判、縣令及佐官查證屬實後，由官府收容供養。\n（南宋）多把居養院、安濟坊合而為一，稱為養濟院。\n（明太祖）百姓中孤獨、殘疾、病重而無法生活的人，准許入院。", "keywords": [{"w": "矜", "m": "通「鰥」，無妻的老人"}, {"w": "耆壽", "m": "年高的人"}, {"w": "勾當", "m": "管理、負責辦理"}, {"w": "驗實", "m": "查驗屬實"}], "questions": [{"n": 18, "qtype": "單選", "stem": "依據上文，最符合古代照護機構發展概況的敘述是：", "options": {"A": "唐代照護機構為有效運用人力，皆由地方有名望的僧尼操辦", "B": "宋哲宗時的收治條件寬鬆，只要孤獨殘疾者都可由國家養護", "C": "機構經費歷代除國家挹注外，尚有出自寺廟悲田或民間捐助", "D": "歷代均明定政府應擔負養護的責任，照護機構皆載入律法中"}, "answer": "C", "explain": "(C)正確：唐玄宗時用國家官本利息，唐武宗撥給寺田「以充粥料」，明清開始接受民間捐助，可見經費來自國家、寺田與民間。\n(A)錯：唐初、玄宗時由寺僧負責，但武宗廢佛後改由地方有名望的耆老負責，不是「皆由僧尼」。\n(B)錯：哲宗的詔令要「貧乏不得自存」且經官員「驗實」才收養，不是只要孤獨殘疾就收。\n(D)錯：只有明代把養濟院載入《大明律》，不是歷代都入律。", "skill": "史料整理題，遇到「皆、均、只要」等全稱詞，回原文找一個反例就能刪掉。"}, {"n": 19, "qtype": "單選", "stem": "下列為今日長照的重點，與上文所述古代曾實施的老殘照護，作法相近的是：\n甲、社會互助　乙、減輕失能家庭租稅　丙、公私部門合作　丁、提供家庭照顧者支持，減輕負荷　戊、整合安養與醫療　己、串聯社區關懷據點，提供預防照顧", "options": {"A": "甲乙丁", "B": "甲丙戊", "C": "乙丙己", "D": "丙丁戊"}, "answer": "B", "explain": "甲社會互助：明清接受民間捐助、民間設立照護機構，相近。丙公私部門合作：官府的養濟院加上民間力量，相近。戊整合安養與醫療：南宋把居養院、安濟坊合一並派醫官治療，相近。乙減稅、丁家庭照顧者支持、己社區據點，文中都沒有提到。所以選(B)甲丙戊。", "skill": "配對題先在原文中逐一圈出古代的做法，再一項項對今日措施，沒有圈到的就刪。"}], "difficulty": "中", "label": "109指考", "year": 109, "kind": "指考", "textcat": "生活情境文本", "textcat2": "學術文本", "linked_core": ""}, {"id": "zk109-20", "exam": "zk109", "nums": [20, 21, 22, 23], "form": "題組", "img": "img/zk109-20.png", "source": "《紅樓夢》第3回", "author": "曹雪芹", "genre": "其他", "types": ["文意推論", "文化常識", "人物情感"], "passage": "", "translation": "", "keywords": [{"w": "一射之地", "m": "一箭射程的距離"}, {"w": "垂花門", "m": "舊式宅院內院的門，門上有垂花裝飾"}, {"w": "抄手遊廊", "m": "環繞庭院的走廊"}, {"w": "儀門", "m": "正門內的第二道門"}, {"w": "廂廡", "m": "正房兩側的廂房與廊屋"}], "questions": [{"n": 20, "qtype": "單選", "stem": "榮國府宅院若依上文大致圖示為甲、乙、丙三處，其主人依序應是：", "options": {"A": "賈母／賈政／賈赦", "B": "賈母／賈赦／賈政", "C": "賈赦／賈母／賈政", "D": "賈赦／賈政／賈母"}, "answer": "A", "explain": "黛玉從西邊角門進去，到垂花門內見賈母，所以西邊的宅院甲是賈母的。去見賈赦時，車「出了西角門，往東過榮府正門，便入一黑油大門」，所以在正門東邊的宅院丙是賈赦的。見賈政時，正房「一條大甬路，直接出大門」，就在正門內，是宅院乙。依序是賈母／賈政／賈赦，選(A)。", "skill": "空間題把文中的方向詞（西角門、往東過正門、直接出大門）一個個標在圖上。"}, {"n": 21, "qtype": "單選", "stem": "若依上文對賈母宅院的敘寫來推斷，垂花門的區隔作用應是：", "options": {"A": "門內為女眷主要活動區域", "B": "門內為下人禁止進入區域", "C": "乘車限門外，門內須搭轎", "D": "園林在門外，門內為房舍"}, "answer": "A", "explain": "轎子抬到垂花門前，男性小廝就「退出」，換眾婆子打起轎簾扶黛玉下轎，可見垂花門內是女眷活動的區域，男僕不進入，選(A)。\n(B)婆子也是下人，卻可以進入，所以不是禁止下人。\n(C)黛玉在垂花門內是步行，不是門內須搭轎。\n(D)文中沒有門外是園林的說法。", "skill": "注意「誰在門前退出、誰接手」，人員交替的地方就是區隔的界線。"}, {"n": 22, "qtype": "單選", "stem": "上文提到：「黛玉便知這方是正經正內室」，影響黛玉如此判斷的因素是：", "options": {"A": "正門前坐著華冠麗服之人", "B": "若乘坐騾車可直入南大廳", "C": "進堂屋前須通過三層儀門", "D": "屋宇宏闊且直通榮府正門"}, "answer": "D", "explain": "黛玉看到賈政這裡「五間大正房……軒昂壯麗，比賈母處不同」，又有「一條大甬路，直接出大門」，所以判斷這才是正經正內室，選(D)。\n(A)文中沒有提到正門前坐著華服之人。\n(B)黛玉此時是下車後步行，沒有騾車直入大廳之說。\n(C)三層儀門是賈赦宅院的描寫。", "skill": "問判斷依據，就找判斷句的前一兩句描寫。"}, {"n": 23, "qtype": "單選", "stem": "古代豪門的居所安排，通常與位階、身分密切相關。下列敘述，最不適當的是：", "options": {"A": "賈政住在榮國府正門內的宅院，顯示賈政在榮國府居於當家地位", "B": "賈母和賈政住的正房皆是「五間」，顯示二人在榮國府地位崇高", "C": "賈母住在垂花門內的宅院，暗示賈母完全隱退，不過問榮府事務", "D": "賈赦住在小巧別致的宅院，暗示賈赦雖是兄長，但權力不及賈政"}, "answer": "C", "explain": "本題選「最不適當」。(C)賈母住在垂花門內，只說明是女眷居處；賈母是府中最高長輩，文中看不出她「完全隱退，不過問榮府事務」，推論過度，所以選(C)。\n(A)賈政住在正門內、直通大門的正室，可見居當家地位，適當。\n(B)兩處都是「五間」正房，顯示地位崇高，適當。\n(D)賈赦是哥哥，卻住在從花園隔出來、小巧別致的院子，不如賈政軒峻壯麗，可推知權力不及賈政，適當。", "skill": "「最不適當」題特別注意選項中的「完全、一定」等極端詞，常是推論過度。"}], "difficulty": "中", "label": "109指考", "year": 109, "kind": "指考", "textcat": "文學文本", "textcat2": "生活情境文本", "linked_core": ""}, {"id": "zk109-24", "exam": "zk109", "nums": [24, 25], "form": "題組", "img": "img/zk109-24.png", "source": "王安石〈上曾參政書〉", "author": "王安石", "genre": "書信序跋", "types": ["主旨寓意", "文意推論"], "passage": "某聞古之君子立而相天下，必因其材力之所宜、形勢之所安而役使之，故人得盡其材，而樂出乎其時。今也某材不足以任劇，而又多病，不敢自蔽，而數以聞執事矣。而閣下必欲使之察一道之吏，而寄之以刑獄之事，非所謂因其材力之所宜也。某親老矣，有上氣之疾日久，比年加之風眩，勢不可以去左右。閣下必欲使之奔走跋涉，不常乎親之側，非所謂因其形勢之所安也。伏惟閣下由君子之道以相天下，故某得布其私焉。論者或以為事君使之左則左，使之右則右，害有至於死而不敢避，勞有至於病而不敢辭者，人臣之義也，某竊以為不然。上之使人也，既因其材力之所宜、形勢之所安，則使之左而左，使之右而右，可也。上之使人也，不因其材力之所宜、形勢之所安，上將無以報吾君，下將無以慰吾親，然且左右惟所使，則是無義無命，而苟悅之為可也。", "translation": "我聽說古代的君子擔任宰相治理天下，一定依照人才能力適合做什麼、處境能安於什麼來任用他，所以人人能發揮才能，也樂於在這個時代出來做事。現在我的才能不足以擔任繁重的職務，又多病，不敢隱瞞，已經多次向您報告了。而您一定要派我去督察一路的官吏，把刑獄的事交給我，這不是依照才能所適合的來任用。我的父母年老了，患氣喘的病很久，近年又加上頭暈，情勢上不能離開身邊。您一定要我四處奔走跋涉，不能常在父母身旁，這不是依照處境所能安的來任用。我想您是以君子之道治理天下，所以我才敢說出自己的私情。有人認為事奉君主，叫你往左就往左、叫你往右就往右，即使危險到會死也不敢逃避，辛勞到會病也不敢推辭，這是做臣子的道義，我私下認為不是這樣。上位者用人，如果依照才能所宜、處境所安，那麼叫往左就往左、叫往右就往右，是可以的。上位者用人，如果不依照才能所宜、處境所安，對上將無法報答君主，對下將無法安慰父母，卻還要一味聽從使喚，那就是沒有道義、沒有原則，只是苟且討好罷了。", "keywords": [{"w": "相天下", "m": "擔任宰相治理天下"}, {"w": "任劇", "m": "擔任繁重的職務"}, {"w": "執事", "m": "對對方的敬稱"}, {"w": "上氣之疾", "m": "氣喘病"}, {"w": "比年", "m": "近年"}, {"w": "布其私", "m": "陳述自己的私情"}, {"w": "苟悅", "m": "苟且討好"}], "questions": [{"n": 24, "qtype": "單選", "stem": "依據上文，王安石上書曾參政的主要目的是：", "options": {"A": "自薦其才，望獲破格拔擢", "B": "乞求辭官，准許還鄉終老", "C": "敘述理由，婉拒長官任命", "D": "增設官職，廣納天下賢才"}, "answer": "C", "explain": "王安石說自己才能不足、多病，父母年老多病不能離開，而曾參政「必欲使之察一道之吏」，這「非所謂因其材力之所宜」「非所謂因其形勢之所安」，目的是說明理由、婉拒這項任命，選(C)。\n(A)他說自己「材不足以任劇」，不是自薦求拔擢。\n(B)他沒有要辭官還鄉，只是不願接這個差事。\n(D)文中沒有建議增設官職。", "skill": "書信目的題，找「而閣下必欲……非所謂……」這類對收信人的要求或反對，那就是寫信的目的。"}, {"n": 25, "qtype": "單選", "stem": "依據上文，王安石認同的人臣之義是：", "options": {"A": "臣多病而不敢欺君，薦以有才之人", "B": "臣為君奔走跋涉，不敢常事親之側", "C": "君之使人，害有至於死而臣不敢避", "D": "君盱衡情勢以擢才，臣遵行以為報"}, "answer": "D", "explain": "王安石主張：上位者用人若「因其材力之所宜、形勢之所安」，臣子就「使之左而左，使之右而右」，也就是君主衡量情勢任用人才，臣子再遵行以回報，選(D)。\n(A)文中沒有推薦他人的內容。\n(B)他正是反對為了奔走而不能侍奉父母。\n(C)「害有至於死而不敢避」是「論者」的看法，王安石說「某竊以為不然」。", "skill": "議論文中出現「論者或以為……某竊以為不然」，論者的話是被反駁的，作者觀點在後面。"}], "difficulty": "中", "label": "109指考", "year": 109, "kind": "指考", "textcat": "生活情境文本", "textcat2": "學術文本", "linked_core": ""}, {"id": "zk109-26", "exam": "zk109", "nums": [26, 27, 28, 29, 30], "form": "題組", "img": "img/zk109-26.png", "source": "《史記‧孟嘗君列傳》", "author": "司馬遷", "genre": "史傳人物", "types": ["人物情感", "虛詞句式", "文意推論", "比較閱讀"], "passage": "齊王惑於秦、楚之毀，以為孟嘗君名高其主而擅齊國之權，遂廢孟嘗君。諸客見孟嘗君廢，皆去。馮驩曰：「借臣車一乘，可以入秦者，必令君重於國而奉邑益廣，可乎？」孟嘗君乃約車幣而遣之。\n馮驩乃西說秦王曰：「天下之遊士馮軾結靷西入秦者，無不欲強秦而弱齊；馮軾結靷東入齊者，無不欲強齊而弱秦。此雄雌之國也，勢不兩立為雄，雄者得天下矣。」秦王跽而問之曰：「何以使秦無為雌而可？」馮驩曰：「王亦知齊之廢孟嘗君乎？」秦王曰：「聞之。」馮驩曰：「使齊重於天下者，孟嘗君也。今齊王以毀廢之，其心怨，必背齊；背齊入秦，則齊國之情，人事之誠，盡委之秦，齊地可得也，豈直為雄也！君急使使載幣陰迎孟嘗君，不可失時也。如有齊覺悟，復用孟嘗君，則雌雄之所在未可知也。」秦王大悅，乃遣車十乘黃金百鎰以迎孟嘗君。\n馮驩辭以先行，至齊，說齊王曰：「天下之遊士馮軾結靷東入齊者，無不欲強齊而弱秦者；馮軾結靷西入秦者，無不欲強秦而弱齊者。夫秦齊雄雌之國，秦強則齊弱矣，此勢不兩雄。今臣竊聞秦遣使車十乘載黃金百鎰以迎孟嘗君。孟嘗君不西則已，西入相秦則天下歸之，秦為雄而齊為雌，雌則臨淄、即墨危矣。王何不先秦使之未到，復孟嘗君，而益與之邑以謝之？孟嘗君必喜而受之。秦雖強國，豈可以請人相而迎之哉！折秦之謀，而絕其霸強之略。」齊王曰：「善。」乃使人至境候秦使。秦使車適入齊境，使還馳告之，王召孟嘗君而復其相位，而與其故邑之地，又益以千戶。秦之使者聞孟嘗君復相齊，還車而去矣。", "translation": "齊王被秦、楚兩國的毀謗迷惑，認為孟嘗君名聲高過君主、獨攬齊國大權，就罷免了孟嘗君。門客們見孟嘗君被罷官，都離開了。馮驩說：「借我一輛可以到秦國的車，我一定讓您在齊國更受重視、封地更廣，可以嗎？」孟嘗君就準備車馬財禮送他去。\n馮驩向西遊說秦王：「天下的遊士駕車向西進入秦國的，沒有不想讓秦國強大、齊國衰弱的；駕車向東進入齊國的，沒有不想讓齊國強大、秦國衰弱的。秦齊是一雄一雌的國家，情勢上不能並立為雄，成為雄的就能得天下。」秦王挺直上身跪著問他：「怎樣才能讓秦國不成為雌呢？」馮驩說：「大王知道齊國罷免了孟嘗君嗎？」秦王說：「聽說了。」馮驩說：「讓齊國被天下看重的，就是孟嘗君。如今齊王因毀謗罷免他，他心裡怨恨，一定會背叛齊國；他背齊入秦，那麼齊國的國情、人事的實況，就都交給秦國了，齊國的土地都可以得到，豈只是成為雄國而已！您趕快派使者帶著財禮暗中迎接孟嘗君，不可錯失時機。如果齊王醒悟，再任用孟嘗君，那麼誰雄誰雌就難說了。」秦王非常高興，就派十輛車、帶黃金百鎰去迎接孟嘗君。\n馮驩告辭先行，到了齊國，遊說齊王說：「天下的遊士……（同前，說秦齊勢不兩雄）。現在我私下聽說秦國派十輛車載黃金百鎰來迎接孟嘗君。孟嘗君不往西去就算了，如果西去做秦國宰相，天下就歸向秦國，秦為雄而齊為雌，成了雌國，臨淄、即墨就危險了。大王何不趁秦國使者還沒到，恢復孟嘗君的職位，再多給他封地來道歉？孟嘗君一定高興地接受。秦國雖強，難道能請別國的宰相去迎接嗎！這樣就能挫敗秦國的計謀，斷絕它稱霸的策略。」齊王說：「好。」就派人到邊境等候秦使。秦使的車剛進齊境，偵察的人飛奔回報，齊王召回孟嘗君恢復相位，還給他原來的封地，又加了一千戶。秦國使者聽說孟嘗君又做了齊相，就掉頭回去了。", "keywords": [{"w": "毀", "m": "毀謗"}, {"w": "擅", "m": "獨攬"}, {"w": "約車幣", "m": "準備車輛和財禮"}, {"w": "馮軾結靷", "m": "駕車（馮通憑）"}, {"w": "跽", "m": "長跪，挺直上身跪著，表恭敬"}, {"w": "豈直", "m": "豈只"}, {"w": "謝", "m": "道歉"}], "questions": [{"n": 26, "qtype": "單選", "stem": "秦王以「跽」姿問馮驩「何以使秦無為雌而可」，透露出秦王的態度是：", "options": {"A": "驚慌焦慮", "B": "敬慎關切", "C": "倨傲輕蔑", "D": "猶豫戒懼"}, "answer": "B", "explain": "「跽」是挺直上身長跪，古人在聽到重要的話、表示恭敬重視時會這樣做；秦王聽到「雄者得天下」，急著問怎樣才不會成為雌國，可見態度是(B)敬慎關切。\n(A)秦王是重視，不是驚慌焦慮。\n(C)長跪請教是恭敬，與倨傲輕蔑相反。\n(D)他主動追問，並非猶豫戒懼。", "skill": "古代坐姿與禮節（跽、避席、再拜）常是人物態度的線索，要記住它們代表恭敬。"}, {"n": 27, "qtype": "單選", "stem": "「無不欲強秦而弱齊」句中的「強」與「弱」屬於使動用法，「強秦」、「弱齊」意謂「使秦強」、「使齊弱」。下列文句「」內，屬於相同用法的是：", "options": {"A": "天下有公利而莫或「興」之", "B": "秦時與臣游，項伯殺人，臣「活」之", "C": "芳草鮮美，落英繽紛，漁人甚「異」之", "D": "傅毅之於班固，伯仲之間耳，而固「小」之"}, "answer": "B", "explain": "(B)「臣活之」是「我使他活下來」，形容詞（不及物動詞）「活」用作使動，和「強秦」「弱齊」相同。\n(A)「莫或興之」的興是興辦、推動，是一般動詞用法。\n(C)「漁人甚異之」是「認為它很奇特」，屬於意動用法。\n(D)「固小之」是「班固看輕他、認為他小」，也是意動用法。", "skill": "分辨使動與意動：翻成「使它○」是使動，翻成「認為它○」是意動。"}, {"n": 28, "qtype": "單選", "stem": "上文第三段畫底線處為馮驩所言，下列文句最接近馮驩之意的是：", "options": {"A": "因人之力而敝之，不仁", "B": "此所謂藉寇兵而齎盜糧者也", "C": "狡兔有三窟，僅得免其死耳", "D": "相秦而顯其君於天下，可傳於後世，不賢而能之乎"}, "answer": "B", "explain": "畫線處說秦國迎孟嘗君去做宰相，天下就歸秦，秦雄齊雌，齊國都城危險——齊國放走人才等於幫助敵國，正是(B)「藉寇兵而齎盜糧」（把兵器借給敵人、把糧食送給盜賊）。\n(A)是〈燭之武退秦師〉晉文公說的，靠人家的力量又損害人家是不仁，和本段無關。\n(C)是〈馮諼客孟嘗君〉的「狡兔三窟」，談替主人預留退路。\n(D)談的是做秦相使君主顯揚於天下，不是警告齊王資敵。", "skill": "把畫線段濃縮成一句白話（放走人才＝資助敵人），再找意思一樣的成語、名句。"}, {"n": 29, "qtype": "單選", "stem": "依據上文，關於孟嘗君廢而復相一事，敘述最適當的是：", "options": {"A": "孟嘗君因政敵謗其廣納客卿，意欲奪權而被廢", "B": "孟嘗君被廢後，門下諸客共議由馮驩西向說秦", "C": "馮驩以策士的動向，分析當前國際角力的局勢", "D": "馮驩以害說秦、以利說齊，終使孟嘗君復相位"}, "answer": "C", "explain": "(C)正確：馮驩對秦、齊都用「遊士入秦者欲強秦、入齊者欲強齊」分析雄雌之勢，就是用策士動向分析國際局勢。\n(A)錯：孟嘗君被廢是因齊王聽信秦楚毀謗，以為他「名高其主而擅齊國之權」，不是因廣納客卿。\n(B)錯：門客「皆去」，是馮驩自己主動請求，不是諸客共議。\n(D)錯：說秦是用「齊地可得」的利益打動，說齊是用「臨淄、即墨危」的禍害警告，順序剛好相反。", "skill": "遊說題要分清楚「以利誘」還是「以害懼」：給好處是利，講危險是害。"}, {"n": 30, "qtype": "單選", "stem": "《戰國策》載孟嘗君被廢，馮諼西向事如下：「西遊於梁，謂（魏）惠王曰：齊", "options": {"A": "秦、齊二國勢均力敵，可凸顯「延攬孟嘗君的重要性」", "B": "秦、齊二國東西對峙，可凸顯「孟嘗君和齊王的衝突」", "C": "秦國有併吞天下之志，可襯托「馮驩建功立業的企圖」", "D": "秦國廣納各國人才，可襯托「孟嘗君食客眾多的豪氣」"}, "answer": "A", "explain": "文中馮驩反覆強調秦、齊是「雄雌之國」「勢不兩雄」，誰得孟嘗君誰就為雄。若司馬遷有意把梁改成秦，最可能是要用勢均力敵的秦齊，凸顯「延攬孟嘗君的重要性」，選(A)。\n(B)文中重點是秦齊爭霸，不是孟嘗君和齊王的衝突。\n(C)文中沒有凸顯馮驩建功立業的企圖。\n(D)文中沒有提到秦國廣納人才或孟嘗君食客多的豪氣。", "skill": "推論改寫動機，看文中被反覆強調的關鍵詞（雄雌、勢不兩立），改寫通常是為了強化它。"}], "difficulty": "難", "label": "109指考", "year": 109, "kind": "指考", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "馮諼客孟嘗君"}, {"id": "zk109-31", "exam": "zk109", "nums": [31, 32], "form": "題組", "img": "img/zk109-31.png", "source": "選項引文：丘遲〈與陳伯之書〉、郁永河《裨海紀遊》、歐陽脩〈醉翁亭記〉、柳宗元〈始得西山宴遊記〉", "author": "", "genre": "其他", "types": ["文意推論", "寫作手法"], "passage": "(A)推赤心於天下，安反側於萬物\n(B)入茅棘中，勁茅高丈餘，兩手排之，側體而入\n(C)至於負者歌於途，行者休於樹，前者呼，後者應\n(D)日與其徒上高山，入深林，窮迴谿，幽泉怪石，無遠不到", "translation": "(A)（朝廷）把赤誠的心推廣到天下，讓那些心懷不安的人都安定下來。\n(B)走進茅草荊棘中，堅韌的茅草有一丈多高，用兩手撥開，側著身子才能進去。\n(C)至於背東西的人在路上唱歌，走路的人在樹下休息，前面的人呼喊，後面的人應答。\n(D)每天和同伴登上高山，走進深林，走遍曲折的溪谷，凡是有幽深泉水、奇怪石頭的地方，再遠也都去了。", "keywords": [{"w": "赤心", "m": "真誠的心"}, {"w": "反側", "m": "輾轉不安，引申為心懷二心、不安的人"}, {"w": "排", "m": "推開"}, {"w": "負者", "m": "背東西的人"}], "questions": [{"n": 31, "qtype": "單選", "stem": "關於上文對心智與身體的敘述，最適當的是：", "options": {"A": "達爾文與尼采均重視走路，進而認為身體坐於書桌前思考的成果沒有價值", "B": "笛卡兒說自己「賣力」完成《沉思錄》，可知他主張心智與身體實質相同", "C": "約翰‧馬克安諾的肢體語言證明情緒難以由心控制，而是靠身體表達出來", "D": "梅洛龐蒂與尼采對於人的心智與身體二者之間的關係，有較為一致的看法"}, "answer": "D", "explain": "(D)正確：梅洛龐蒂說憤怒和身體「緊密相繫」，尼采說「身體即是全部的我」，兩人都認為心智情感和身體分不開，看法一致。\n(A)錯：達爾文、尼采重視走路時的思考，但沒有說坐在書桌前思考的成果「沒有價值」（尼采的話被形容為浮誇）。\n(B)錯：笛卡兒主張心智和身體是兩種不同實體，「賣力」一詞只是作者用來說明語言帶有身體色彩。\n(C)錯：文中說情緒透過身體呈現，並沒有說情緒「難以由心控制」。", "skill": "引述多位人物的文章，先把每人的主張寫成一句，再判斷選項說的是誰、有沒有誇大。"}, {"n": 32, "qtype": "單選", "stem": "下列文句畫底線處，最符合上文「我們使用的語言也帶有身體的色彩。語言中許多常用的隱喻都和基本的人類生理學有關」的是：", "options": {"A": "推赤心於天下，安反側於萬物", "B": "入茅棘中，勁茅高丈餘，兩手排之，側體而入", "C": "至於負者歌於途，行者休於樹，前者呼，後者應", "D": "日與其徒上高山，入深林，窮迴谿，幽泉怪石，無遠不到"}, "answer": "A", "explain": "題目要找用身體動作來比喻抽象事物的語言。(A)「反側」本是睡不著翻來覆去的身體動作，在這裡比喻心懷不安、可能反叛的人，是用生理感覺構成的隱喻，最符合。\n(B)「兩手排之，側體而入」是真的用手撥草、側身進去，是寫實。\n(C)「前者呼，後者應」是真的在呼喊應答，是寫實。\n(D)「上高山，入深林」是實際的遊歷行動，是寫實。", "skill": "分辨隱喻和寫實：把句子照字面想像，如果真的發生了就是寫實，必須轉個彎理解的才是隱喻。"}], "difficulty": "中", "label": "109指考", "year": 109, "kind": "指考", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "與陳伯之書、始得西山宴遊記、醉翁亭記、裨海紀遊"}, {"id": "zk109-33", "exam": "zk109", "nums": [33, 34], "form": "題組", "img": "img/zk109-33.png", "source": "蘇軾〈遊沙湖〉（《東坡志林》）", "author": "蘇軾", "genre": "山水遊記", "types": ["文意推論", "詩詞賞析", "典故出處"], "passage": "黃州東南三十里為沙湖，亦曰螺師店，予買田其間。因往相田得疾，聞麻橋人龐安常善醫而聾，遂往求療。安常雖聾，而穎悟絕人，以紙畫字，書不數字，輒深了人意。余戲之曰：「余以手為口，君以眼為耳，皆一時異人也。」疾癒，與之同遊清泉寺。寺在蘄水郭門外二里許，有王逸少洗筆泉，水極甘，下臨蘭溪，溪水西流。余作歌云：「山下蘭芽短浸溪，松間沙路淨無泥，蕭蕭暮雨子規啼。誰道人生無再少？君看流水尚能西，休將白髮唱黃雞。」是日劇飲而歸。", "translation": "黃州東南三十里的地方叫沙湖，也叫螺師店，我在那裡買了田。因為去察看田地而生病，聽說麻橋人龐安常擅長醫術但耳聾，就去找他治療。安常雖然耳聾，卻聰明過人，我在紙上寫字，寫不到幾個字，他就深深了解我的意思。我和他開玩笑說：「我用手當嘴巴，你用眼睛當耳朵，我們都是當代的奇人啊。」病好了，和他一起遊清泉寺。寺在蘄水城門外二里左右，有王羲之的洗筆泉，泉水非常甘甜，下面臨著蘭溪，溪水向西流。我作了一首歌說：「山下蘭草的嫩芽短短的浸在溪水裡，松林間的沙路乾淨沒有泥土，傍晚細雨瀟瀟，杜鵑鳥在啼叫。誰說人生不能再回到少年？你看門前的流水還能向西流，不要因為白髮就唱起『黃雞催曉』那種感嘆時光的歌。」這天痛快地喝酒才回去。", "keywords": [{"w": "相田", "m": "察看田地"}, {"w": "穎悟絕人", "m": "聰明過人"}, {"w": "了", "m": "明白"}, {"w": "子規", "m": "杜鵑鳥"}, {"w": "黃雞", "m": "白居易詩句「黃雞催曉」，感嘆時光催人老"}, {"w": "劇飲", "m": "暢飲"}], "questions": [{"n": 33, "qtype": "單選", "stem": "依據上文，關於蘇軾沙湖之遊，敘述最適當的是：", "options": {"A": "貶謫黃州時，因欲置田沙湖而有此行", "B": "病中邀龐安常同遊清泉寺，品泉賞溪", "C": "因療疾而識同遊者，其人聾，觀人畫字以解意", "D": "感物興悲，既傷謫居又嘆年老多病，痛飲而歸"}, "answer": "C", "explain": "(C)正確：蘇軾因看田生病去求醫，認識了龐安常；龐安常耳聾，「以紙畫字」，看人寫字就能了解意思。\n(A)錯：遊清泉寺是病好以後和龐安常同遊，不是為了買田而有這趟遊歷。\n(B)錯：原文是「疾癒，與之同遊」，不是病中同遊。\n(D)錯：蘇軾在歌中說「誰道人生無再少」，態度樂觀，暢飲而歸是高興，不是感物興悲。", "skill": "敘事題注意時間順序詞（因、疾癒、是日），選項常把先後或因果顛倒。"}, {"n": 34, "qtype": "單選", "stem": "關於上文蘇軾所作之歌的寫作特色，敘述最適當的是：", "options": {"A": "上闋寫景，藉由「蘭芽短」、「沙路淨」、「子規啼」描寫秋日清幽", "B": "下闋抒懷，化用白居易詩句，抒發了「世殊事異，其致一也」的悲懷", "C": "藉問言志，以「無再少」的質疑，傳達「烈士暮年，壯心不已」襟抱", "D": "觸景生情，觀蘭溪之水西流而興發「逝者如斯夫，不舍晝夜」的感嘆"}, "answer": "C", "explain": "(C)正確：「誰道人生無再少？」用反問質疑「人生不能再年輕」的說法，再以溪水西流為證，表達年老仍有壯志，和曹操「烈士暮年，壯心不已」相近。\n(A)錯：蘭芽初生、子規啼叫，寫的是春天景色，不是秋日。\n(B)錯：「休將白髮唱黃雞」是勸人不要像白居易那樣感嘆時光催老，是反用而非抒發悲懷。\n(D)錯：溪水西流（一般河流東流）讓他想到人也能「再少」，不是感嘆逝者如斯。", "skill": "遇到詩中的「誰道……」「休……」，要讀出作者是在否定、翻轉一般看法。"}], "difficulty": "中", "label": "109指考", "year": 109, "kind": "指考", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "赤壁賦"}, {"id": "zk109-35", "exam": "zk109", "nums": [35], "form": "單題", "img": "img/zk109-35.png", "source": "范仲淹〈岳陽樓記〉、歸有光〈項脊軒志〉、顧炎武〈廉恥〉、《左傳》、方苞〈左忠毅公軼事〉、韓愈〈師說〉、杜光庭〈虬髯客傳〉、賈誼〈過秦論〉、王羲之〈蘭亭集序〉、袁宏道〈晚遊六橋待月記〉", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "", "translation": "", "keywords": [{"w": "制", "m": "規模、形制"}, {"w": "是", "m": "此、這"}, {"w": "下", "m": "被關入／低於"}, {"w": "策", "m": "計策／馬鞭"}, {"w": "次", "m": "旁邊／依次"}], "questions": [{"n": 35, "qtype": "多選", "stem": "下列各組「」內的字，前後意義相同的是：", "options": {"A": "乃重修岳陽樓，增其舊「制」／乃使人復葺南閣子，其「制」稍異於前", "B": "故士大夫之無恥，「是」謂國恥／篳路藍縷，以啟山林，至於今「是」賴", "C": "及左公「下」廠獄，史朝夕窺獄門外／今之眾人，其「下」聖人也亦遠矣", "D": "衛公李靖以布衣來謁，獻奇「策」／奮六世之餘烈，振長「策」而御宇內", "E": "引以為流觴曲水，列坐其「次」／梅花為寒所勒，與杏、桃相「次」開發"}, "answer": "AB", "explain": "(A)相同：「增其舊制」「其制稍異於前」的制都是建築的規模、形制。\n(B)相同：「是謂國恥」是「這叫做國恥」；「至於今是賴」是「到今天都依賴這（篳路藍縷的開拓）」，兩個「是」都是指示代詞「這」。\n(C)不同：「左公下廠獄」的下是被關進；「其下聖人也亦遠矣」的下是低於、不如。\n(D)不同：「獻奇策」的策是計策；「振長策而御宇內」的策是馬鞭。\n(E)不同：「列坐其次」的次是旁邊；「與杏、桃相次開發」的次是依次、接著。", "skill": "一字多義題，把字的意思代回句子讀讀看，再回想課文注釋，兩邊都能代同一義才算相同。"}], "difficulty": "中", "label": "109指考", "year": 109, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "蘭亭集序、師說、虬髯客傳、岳陽樓記、項脊軒志、晚遊六橋待月記、廉恥、左忠毅公軼事"}, {"id": "zk109-37", "exam": "zk109", "nums": [37], "form": "單題", "img": "img/zk109-37.png", "source": "朱熹〈偶讀謾記〉", "author": "朱熹", "genre": "說理議論", "types": ["文意推論", "主旨寓意"], "passage": "俚俗相傳，疫疾能傳染人，有病此者，鄰里斷絕，不通訊問，甚者雖骨肉至親，亦或委之而去，傷俗害理，莫此為甚。或者惡其如此，遂著書以曉之，謂疫無傳染，不須畏避，其意善矣，然其實不然，是以聞者莫之信也。予嘗以為誣之以無染而不必避，不若告之以雖有染而不當避也。蓋曰無染而不須避者，以利害言也；曰雖染而不當避者，以恩義言也。告之以利害，則彼之不避者，信吾不染之無害而已，不知恩義之為重也，一有染焉，則吾說將不見信，而彼之避也，唯恐其不速矣。告之以恩義，則彼之不避者，知恩義之為重而不忍避也。知恩義之為重而不忍避，則雖有染者，亦知吾言之無所欺，而信此理之不可違矣。抑染與不染似亦繫乎人心之邪正、氣體之虛實，不可一概論也。", "translation": "民間相傳，瘟疫會傳染給人，有人得了這種病，鄰居就斷絕往來、不聞不問，更嚴重的連骨肉至親也可能丟下他離開，傷害風俗、違背倫理，沒有比這更嚴重的了。有人厭惡這種情形，就著書來告訴大家，說瘟疫不會傳染，不必害怕躲避，用意很好，但事實並非如此，所以聽的人都不相信。我曾認為，騙大家說不會傳染所以不必躲避，不如告訴大家雖然會傳染但不應該躲避。說不會傳染所以不必躲避，是從利害來說；說雖然會傳染但不應躲避，是從恩義來說。用利害告訴人，那些不躲避的人，只是相信我說不會傳染、沒有害處罷了，不知道恩義才是重要的，一旦有人被傳染，我的說法就不被相信，他們躲避起來，只怕躲得不夠快。用恩義告訴人，那些不躲避的人，是知道恩義重要而不忍心躲避。知道恩義重要而不忍心躲避，那麼即使有人被傳染，也知道我的話沒有欺騙，而相信這個道理不可違背。再說，染不染病，似乎也和人心的正邪、身體的虛實有關，不能一概而論。", "keywords": [{"w": "俚俗", "m": "民間"}, {"w": "委", "m": "拋棄"}, {"w": "曉", "m": "使人明白"}, {"w": "誣", "m": "欺騙"}, {"w": "抑", "m": "再說、而且（轉折語氣）"}, {"w": "繫乎", "m": "關係到"}], "questions": [{"n": 37, "qtype": "多選", "stem": "依據下文，關於朱熹對疫疾的看法，敘述適當的是：", "options": {"A": "疫疾隔離處所距鄰里太遠，不但使病人缺乏照護資源，也有違倫理", "B": "透過著書宣導疫疾不會傳染，既難取信於人，也無法解決照護問題", "C": "從利害角度加以剖析，可使群眾對疫疾有正確認識，有利於照顧家人", "D": "當群眾對疫疾照護態度分歧，明理者可曉以恩義，無知者宜勸以利害", "E": "每個人的身心素質狀況不同，即使在疫疾流行之時，也未必都會染病"}, "answer": "BE", "explain": "(B)正確：有人著書說瘟疫不會傳染，但「其實不然，是以聞者莫之信」，而且一旦有人染病，說法就不被相信，大家更急著躲避，無法解決照顧病人的問題。\n(E)正確：文末說染不染病和「人心之邪正、氣體之虛實」有關，不能一概而論，所以不一定人人都會染病。\n(A)錯：文中沒有提到隔離處所距離鄰里太遠。\n(C)錯：朱熹認為從利害角度說，反而一有人染病就不被相信，不利於照顧家人。\n(D)錯：朱熹主張要「告之以恩義」，沒有分明理者、無知者用不同方法。", "skill": "論說文先找作者「贊成什麼、反對什麼」（不若告之以……），再判斷選項是否把被反對的說法當成作者主張。"}], "difficulty": "中", "label": "109指考", "year": 109, "kind": "指考", "textcat": "科普文本", "textcat2": "學術文本", "linked_core": ""}, {"id": "zk109-38", "exam": "zk109", "nums": [38], "form": "單題", "img": "img/zk109-38.png", "source": "(A)蘇轍〈黃州快哉亭記〉、(B)郁永河《裨海紀遊》、(C)(D)(E)現代散文", "author": "", "genre": "其他", "types": ["寫作手法", "比較閱讀"], "passage": "(A)至於長洲之濱，故城之墟，曹孟德、孫仲謀之所睥睨，周瑜、陸遜之所騁騖，其流風遺跡，亦足以稱快世俗\n(B)林木蓊翳，大小不可辨名，老藤纏結其上，若虬龍環繞。風過葉落，有大如掌者。又有巨木裂土而出，兩葉始櫱，已大十圍，導人謂楠也", "translation": "(A)至於長江沙洲的岸邊、舊城的廢墟，是曹操、孫權傲視天下，周瑜、陸遜縱橫馳騁的地方，他們留下的風範與遺跡，也足以讓一般人感到暢快。\n(B)樹林茂密遮蔽，大大小小叫不出名字，老藤纏繞在上面，像虬龍盤繞。風吹過葉子落下，有像手掌那麼大的。又有巨大的樹木破土而出，才剛長出兩片葉子，已經有十人合抱那麼粗，嚮導說這是楠木。", "keywords": [{"w": "睥睨", "m": "斜眼看，傲視"}, {"w": "騁騖", "m": "奔馳"}, {"w": "蓊翳", "m": "草木茂盛而遮蔽"}, {"w": "櫱", "m": "發芽"}], "questions": [{"n": 38, "qtype": "多選", "stem": "文學作品中，作者常因當前的景物憶起自身的過往。下列文句，具有此一表述方式的是：", "options": {"A": "至於長洲之濱，故城之墟，曹孟德、孫仲謀之所睥睨，周瑜、陸遜之所騁騖，其流風遺跡，亦足以稱快世俗", "B": "林木蓊翳，大小不可辨名，老藤纏結其上，若虬龍環繞。風過葉落，有大如掌者。又有巨木裂土而出，兩葉始櫱，已大十圍，導人謂楠也", "C": "舉目四望，盡是繁密排列的古老房屋。當然，其中許多建築物幾度經歷天災兵禍的毀壞而又修復，不可能是十六世紀的原來面貌了", "D": "一整個夜晚都是月光，航向克里特島的夜航，原來是為了注解張九齡的一句詩。小時候讀過的一句詩，竟然一直儲存著，是美的庫存，可以在一生提領出來，享用不盡", "E": "向左邊看，就在防風林外，一片潔白的沙灘上，白芒花也開著，朝碧藍的大洋，永不休息的浪，它開著，在風裡。我知道它更明更亮更燦爛，曾經就是如此，猶似新雪，在我曾經的旅程"}, "answer": "DE", "explain": "題目要找「因眼前景物而想起自己過去」的句子。\n(D)正確：月光下夜航，想起「小時候讀過的一句詩」（張九齡「海上生明月」），由當前景物憶起自身過往。\n(E)正確：看見沙灘上的白芒花，想到它「曾經就是如此……在我曾經的旅程」，憶起自己過去的經歷。\n(A)錯：由長江故城想到曹操、孫權等歷史人物，是懷古，不是作者自己的過往。\n(B)錯：只描寫林木、老藤、巨楠的景象，沒有回憶。\n(C)錯：由古老房屋想到建築歷經天災兵禍，是歷史，不是自身經歷。", "skill": "「憶起自身過往」的關鍵是主詞要是「我」的經驗；想到古人、歷史的屬於懷古。"}], "difficulty": "中", "label": "109指考", "year": 109, "kind": "指考", "textcat": "文學文本", "textcat2": "部定古文", "linked_core": "裨海紀遊"}, {"id": "zk109-39", "exam": "zk109", "nums": [39], "form": "單題", "img": "img/zk109-39.png", "source": "金聖歎〈讀第五才子書法〉", "author": "金聖歎", "genre": "書信序跋", "types": ["文意推論", "寫作手法", "文化常識"], "passage": "(A)只是寫人粗鹵處，便有許多寫法。如魯達粗鹵是性急，史進粗鹵是少年任氣，李逵粗鹵是蠻，武松粗鹵是豪傑不受羈靮。\n(B)作者只是痛恨宋江奸詐，故處處緊接出一段李逵樸誠來，做個形擊。其意思自在顯宋江之惡，卻不料反成李逵之妙也。\n(C)一百八人中，獨於宋江用此大書者，蓋一百七人皆依列傳例，於宋江特依世家例，亦所以成一書之綱紀也。\n(D)《史記》是以文運事，《水滸》是因文生事。以文運事，是先有事生成如此如此，卻要算計出一篇文字來，雖是史公高才，也畢竟是吃苦事。因文生事即不然，只是順著筆性去，削高補低都由我。\n(E)《水滸傳》不說鬼神怪異之事，是他氣力過人處。《西遊記》每到弄不來時，便是南海觀音救了。", "translation": "(A)光是寫人物粗魯的地方，就有很多種寫法。像魯智深的粗魯是性急，史進的粗魯是少年意氣，李逵的粗魯是蠻橫，武松的粗魯是豪傑不受拘束。\n(B)作者只是痛恨宋江奸詐，所以處處緊接著寫一段李逵的樸實真誠，作為對照。本意是要顯出宋江的惡，沒想到反而成就了李逵的妙處。\n(C)一百零八人中，只對宋江用這種大筆特書的寫法，是因為其他一百零七人都依照「列傳」的體例，對宋江特別依照「世家」的體例，也藉此成為全書的綱領。\n(D)《史記》是用文字來記述已發生的事，《水滸》是因為行文需要而創造事件。用文字記述事件，是先有事情已經如此這般發生，卻要設計出一篇文章來，即使司馬遷才高，也終究是辛苦的事。因文生事就不同，只要順著筆意寫下去，要削高補低都由我決定。\n(E)《水滸傳》不寫鬼神怪異的事，這是它功力過人的地方。《西遊記》每到寫不下去時，就是南海觀音來救場。", "keywords": [{"w": "粗鹵", "m": "粗魯"}, {"w": "羈靮", "m": "馬籠頭與韁繩，比喻拘束"}, {"w": "形擊", "m": "對照、映襯"}, {"w": "綱紀", "m": "綱領"}, {"w": "以文運事", "m": "用文字記述已發生之事"}, {"w": "因文生事", "m": "依行文需要虛構情節"}], "questions": [{"n": 39, "qtype": "多選", "stem": "下列有關金聖歎對《水滸傳》的評點，詮釋適當的是：", "options": {"A": "評點：只是寫人粗鹵處，便有許多寫法。如魯達粗鹵是性急，史進粗鹵是少年任氣，李逵粗鹵是蠻，武松粗鹵是豪傑不受羈靮／詮釋：人物敘寫傳神，既寫出某類人物的共性，也表現個別人物的殊性", "B": "評點：作者只是痛恨宋江奸詐，故處處緊接出一段李逵樸誠來，做個形擊。其意思自在顯宋江之惡，卻不料反成李逵之妙也／詮釋：通過對比手法塑造人物，人物形象鮮明生動", "C": "評點：一百八人中，獨於宋江用此大書者，蓋一百七人皆依列傳例，於宋江特依世家例，亦所以成一書之綱紀也／詮釋：以史傳體例類比人物書寫方式，彰顯梁山泊好漢身分地位的差異", "D": "評點：《史記》是以文運事，《水滸》是因文生事。以文運事，是先有事生成如此如此，卻要算計出一篇文字來，雖是史公高才，也畢竟是吃苦事。因文生事即不然，只是順著筆性去，削高補低都由我／詮釋：在以文運事的基礎上加入虛構成分，用筆更為自在靈活", "E": "評點：《水滸傳》不說鬼神怪異之事，是他氣力過人處。《西遊記》每到弄不來時，便是南海觀音救了／詮釋：情節鋪敘詭譎幻怪，筆勢縱橫，能凸顯傳奇的色彩"}, "answer": "ABC", "explain": "(A)正確：同樣寫「粗魯」（共性），四人又各有不同（殊性）。\n(B)正確：用李逵的樸誠對照宋江的奸詐，「形擊」就是對比，兩人形象都更鮮明。\n(C)正確：其他人依「列傳」、宋江依「世家」，借史書體例凸顯宋江身為首領的地位不同。\n(D)錯：金聖歎是把「以文運事」和「因文生事」對立起來比較，《水滸》是因文生事、自由創造，不是「在以文運事的基礎上」加入虛構。\n(E)錯：金聖歎稱讚《水滸》「不說鬼神怪異」，詮釋卻說它情節詭譎幻怪，正好相反。", "skill": "評點詮釋題逐格對照：先翻譯左欄評點的重點詞（形擊、世家例），再看右欄有沒有說反或加料。"}], "difficulty": "難", "label": "109指考", "year": 109, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk109-40", "exam": "zk109", "nums": [40], "form": "單題", "img": "img/zk109-40.png", "source": "《論語‧子罕》、《詩經‧小雅‧蓼莪》、《論語‧陽貨》、《孟子‧梁惠王上》、《莊子‧養生主》、朱熹〈觀書有感〉", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "", "translation": "(A)沒有父親，我依靠誰？沒有母親，我仰賴誰？\n(B)時光流逝了，歲月不等待我。\n(C)大王不要怪罪年成不好，那麼天下的百姓就會來歸附了。\n(D)經絡相連、筋骨結合的地方都不曾碰過，何況是大骨頭呢？\n(E)問這池水怎麼能這樣清澈？因為有源頭活水不斷流來。", "keywords": [{"w": "怙、恃", "m": "依靠"}, {"w": "與", "m": "等待"}, {"w": "肯綮", "m": "筋骨結合處"}, {"w": "軱", "m": "大骨"}, {"w": "渠", "m": "它（指池塘）"}], "questions": [{"n": 40, "qtype": "多選", "stem": "《論語‧子罕》：「吾誰欺？欺天乎？」文中「吾誰欺」為「吾欺誰」之意，賓語（受詞）「誰」放在動詞「欺」之前。下列文句，也有將賓語前置情形的是：", "options": {"A": "無父何怙？無母何恃", "B": "日月逝矣，歲不我與", "C": "王無罪歲，斯天下之民至焉", "D": "技經肯綮之未嘗，而況大軱乎", "E": "問渠哪得清如許？為有源頭活水來"}, "answer": "ABD", "explain": "(A)有：「何怙」「何恃」就是「怙何」「恃何」（依靠誰），疑問代詞作賓語放在動詞前。\n(B)有：「歲不我與」是「歲不與我」，否定句中代詞「我」作賓語前置。\n(D)有：「技經肯綮之未嘗」是「未嘗技經肯綮」，用「之」把賓語提到動詞前。\n(C)沒有：「王無罪歲」是「王不要怪罪年歲」，動詞「罪」在前、賓語「歲」在後，語序正常。\n(E)沒有：「哪得清如許」是一般疑問句，沒有賓語前置。", "skill": "賓語前置三種常見型：疑問代詞（何、誰、安）＋動詞；否定詞＋代詞＋動詞（不我與）；賓語＋之／是＋動詞。"}], "difficulty": "中", "label": "109指考", "year": 109, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk109-41", "exam": "zk109", "nums": [41, 42], "form": "題組", "img": "img/zk109-41.png", "source": "選項引文：(C)《老子》第八十一章、(E)《荀子‧不苟》，其餘出處待查", "author": "", "genre": "其他", "types": ["文意推論", "比較閱讀"], "passage": "(A)君子苟不求利祿，則不害其身\n(B)君子未嘗不欲利，但專以利為心則有害\n(C)天之道，利而不害。聖人之道，為而不爭\n(D)君子羞言利名，言利名尚羞之，況居而求利者也\n(E)見其可利也，則必前後慮其可害也者，而兼權之", "translation": "(A)君子如果不追求利祿，就不會傷害自身。\n(B)君子並非不想要利益，只是一心只想著利益就有害了。\n(C)天的道理是利益萬物而不加害；聖人的道理是有所作為而不與人爭。\n(D)君子以談論利益名聲為羞恥，談論都覺得羞恥了，何況是佔著位子去謀求利益呢？\n(E)看到可以得利的事，一定要前前後後考慮它可能帶來的害處，兩相權衡。", "keywords": [{"w": "專以利為心", "m": "一心只想著利"}, {"w": "羞言", "m": "以說……為羞恥"}, {"w": "兼權", "m": "同時衡量"}], "questions": [{"n": 41, "qtype": "多選", "stem": "下列關於企業倫理與企業決策的敘述，符合上文觀點的是：", "options": {"A": "企業決策若考量企業倫理，常面臨利潤與道德的拉鋸", "B": "企業若將企業倫理納入考量，決策通常變得較為複雜", "C": "企業倫理重視利害關係人的利益，促使企業在決策時同步考量其責任", "D": "社會結構的互動關係緊密，促使企業倫理成為企業決策時的首要考量", "E": "法規不足時，企業倫理促使經理人自我要求而採取對社會有益的決策"}, "answer": "ABCE", "explain": "(A)正確：文中說重視企業倫理的經理人會面臨裁員、關廠等利潤與道德的兩難。\n(B)正確：不把企業倫理納入考量「要解決這些問題反而簡單多了」，可見納入後決策較複雜。\n(C)正確：企業倫理讓經理人「除了重視利潤，也關心並維持其他利害關係人的利益」。\n(E)正確：法律跟不上環境變化時，重視企業倫理的經理人會「以更高的標準」處理決策。\n(D)錯：文中沒有說企業倫理是決策時的「首要」考量，而是利潤之外「也」要關心。", "skill": "白話閱讀遇到「首要、唯一」等極端詞，回原文確認是否真有這種程度的說法。"}, {"n": 42, "qtype": "多選", "stem": "下列文句，與重視企業倫理的經理人在商業決策時所持觀點相近的是：", "options": {"A": "君子苟不求利祿，則不害其身", "B": "君子未嘗不欲利，但專以利為心則有害", "C": "天之道，利而不害。聖人之道，為而不爭", "D": "君子羞言利名，言利名尚羞之，況居而求利者也", "E": "見其可利也，則必前後慮其可害也者，而兼權之"}, "answer": "BE", "explain": "重視企業倫理的經理人：不排斥利潤，但也顧及其他人的利益，並事先評估決策的負面影響。\n(B)正確：君子不是不要利，而是不能只把利放在心上，和「重視利潤也關心他人」相符。\n(E)正確：看到利益要前後考慮可能的害處、兩相權衡，正是「事先瞭解決策結果所可能產生的負面影響」。\n(A)錯：主張不求利祿，排斥利潤，與企業經理人需重視利潤不合。\n(C)錯：講利物而不害、為而不爭，是道家無爭的境界，不是權衡利害的決策。\n(D)錯：以談利為恥，完全排斥求利，不合。", "skill": "比對觀點時抓「態度光譜」：完全排斥利、只求利、兼顧利與義，找跟文章站在同一格的。"}], "difficulty": "中", "label": "109指考", "year": 109, "kind": "指考", "textcat": "生活情境文本", "textcat2": "學術文本", "linked_core": ""}, {"id": "xc110-8", "exam": "xc110", "nums": [8], "form": "單題", "img": "img/xc110-8.png", "source": "顏之推《顏氏家訓》；吳訥《文章辨體序說》", "author": "顏之推；吳訥", "genre": "說理議論", "types": ["文化常識", "句意理解"], "passage": "甲、上書陳事，起自戰國，逮於兩漢，風流彌廣。原其體度：攻人主之長短，____之徒也；訐群臣之得失，訟訴之類也；陳國家之利害，____之伍也；帶私情之與奪，____之儔也。總此四塗，賈誠以求位，鬻言以干祿，或無絲毫之益，而有不省之困。（顏之推《顏氏家訓》）\n乙、大凡為文，須要有溫和敦厚之氣，____告君文字，蓋尤不可無也。（吳訥《文章辨體序》）", "translation": "甲、向君王上書陳述事情，從戰國開始，到了兩漢，這種風氣更加盛行。推究它的類型：批評君主優缺點的，屬於諫諍一類；揭發群臣得失的，屬於訴訟一類；陳述國家利害的，屬於對策一類；夾帶私人情感來左右賞罰取捨的，屬於遊說一類。總括這四種途徑，都是拿忠誠去換取官位，賣弄言辭來求取俸祿，有時沒有絲毫好處，反而招來不被理解的困境。\n乙、大凡寫文章，都要有溫和敦厚的氣度，章疏這種寫給君王的文字，尤其不能沒有。", "keywords": [{"w": "逮", "m": "到、及"}, {"w": "彌", "m": "更加"}, {"w": "訐", "m": "揭發別人的過失"}, {"w": "與奪", "m": "給予與奪取，指賞罰取捨"}, {"w": "賈、鬻", "m": "賣，指拿來交換"}, {"w": "干祿", "m": "求取俸祿"}], "questions": [{"n": 8, "qtype": "單選", "stem": "下文____內最適合填入的詞語依序是：（甲文三空、乙文一空）", "options": {"A": "諫諍／對策／遊說／章疏", "B": "諫諍／章疏／遊說／對策", "C": "遊說／對策／諫諍／章疏", "D": "遊說／諫諍／章疏／對策"}, "answer": "A", "explain": "一格一格對內容：「攻人主之長短」是直接批評君主，叫「諫諍」；「陳國家之利害」是針對國家大事提出對策，叫「對策」（漢代策問、對策）；「帶私情之與奪」是用私人情感去說動君主，這是戰國策士的「遊說」；乙「告君文字」是臣子寫給君主的奏章，叫「章疏」。答案 諫諍／對策／遊說／章疏，選A。B、D把章疏、對策放錯位置；C把遊說放在第一格，但攻擊君主長短不是遊說。", "skill": "文體填空：抓每格前面的「動作」（攻、陳、帶私情、告君），對應文體的功能。"}], "difficulty": "難", "label": "110學測", "year": 110, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc110-9", "exam": "xc110", "nums": [9], "form": "單題", "img": "img/xc110-9.png", "source": "歐陽脩〈醉翁亭記〉、柳宗元〈始得西山宴遊記〉、連橫〈臺灣通史序〉；D項出處待查", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "(A)望之蔚然而深秀者，琅邪也\n(B)以為凡是州之山水有異態者，皆我有也\n(C)夫史者，民族之精神，而人群之龜鑑也\n(D)鄭、衛、桑間、韶虞、武象者，異國之樂也", "translation": "(A)遠望草木茂盛又幽深秀麗的，就是琅邪山。\n(B)以為凡是這個州裡山水有奇特姿態的，都被我擁有了（都遊遍了）。\n(C)歷史，是民族的精神，也是人類的借鏡。\n(D)鄭、衛、桑間、韶虞、武象這些，是各國不同的音樂。", "keywords": [{"w": "者……也", "m": "判斷句：……就是……"}, {"w": "蔚然", "m": "草木茂盛的樣子"}, {"w": "異態", "m": "奇特的形態"}, {"w": "龜鑑", "m": "借鏡、榜樣"}], "questions": [{"n": 9, "qtype": "單選", "stem": "「……者，……也」是古文判斷句的典型結構，例如「南冥者，天池也」，即「所謂南冥就是天池」。下列文句，不是表達判斷語意的是：", "options": {"A": "望之蔚然而深秀者，琅邪也", "B": "以為凡是州之山水有異態者，皆我有也", "C": "夫史者，民族之精神，而人群之龜鑑也", "D": "鄭、衛、桑間、韶虞、武象者，異國之樂也"}, "answer": "B", "explain": "判斷句可以套「A就是B」。A：蔚然深秀的那座山＝琅邪山，判斷。C：史＝民族的精神、人群的龜鑑，判斷。D：鄭衛等音樂＝異國之樂，判斷。B「皆我有也」的「有」是動詞「擁有」，意思是「這些山水都被我擁有（遊遍）了」，是在敘述一件事，不能說「山水就是我有」，所以不是判斷句，選B。", "skill": "判斷句檢驗法：把「者……也」換成「……就是……」，若後半是動作（有、得、為）就不是判斷。"}], "difficulty": "中", "label": "110學測", "year": 110, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "始得西山宴遊記、醉翁亭記、臺灣通史序"}, {"id": "xc110-10", "exam": "xc110", "nums": [10], "form": "單題", "img": "img/xc110-10.png", "source": "《九國志》所載何氏〈烏鵲歌〉", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "韓憑，戰國時為宋康王舍人。妻何氏美，王欲之，捕舍人，築青陵台。何氏作〈烏鵲歌〉以見志，遂自縊死：「南山有烏，北山張羅。烏自高飛，羅當奈何。烏鵲雙飛，不樂鳳凰。妾是庶民，不樂宋王。」", "translation": "韓憑在戰國時是宋康王的家臣。他的妻子何氏很美，康王想占有她，就把韓憑抓起來，罰他去築青陵台。何氏作了〈烏鵲歌〉表明心志，然後上吊而死：「南山有隻烏鴉，北山張開了羅網。烏鴉自己往高處飛，羅網又能怎樣？烏鴉喜鵲成雙飛翔，不羨慕鳳凰。我是平民百姓，不愛慕宋王。」", "keywords": [{"w": "舍人", "m": "家臣、門客"}, {"w": "欲", "m": "想占有"}, {"w": "見志", "m": "表明心志（見同現）"}, {"w": "羅", "m": "捕鳥的網"}, {"w": "樂", "m": "喜愛、羨慕"}], "questions": [{"n": 10, "qtype": "單選", "stem": "關於下文〈烏鵲歌〉的解釋，最適當的是：", "options": {"A": "以「烏」暗指宋康王的邪惡", "B": "以「羅」比喻利誘韓憑的圈套", "C": "以「高飛」凸顯何氏的自主意志", "D": "以「鳳凰」形容韓憑夫婦情意堅貞"}, "answer": "C", "explain": "這首歌是何氏自比：「烏」是何氏自己，「羅」是宋王張開的網，「烏自高飛，羅當奈何」＝我要飛走，你的網奈何不了我，表現她不屈從、自己作主的意志，選C。A烏是何氏，不是宋王。B羅網是宋王用來捕捉何氏的威逼手段，不是利誘韓憑。D「鳳凰」比喻高貴的宋王，「不樂鳳凰」＝不羨慕宋王；成雙的「烏鵲」才是比喻韓憑夫婦。", "skill": "比興詩先配對：每個物象對應故事裡的誰，配好了就不會選錯。"}], "difficulty": "易", "label": "110學測", "year": 110, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc110-11", "exam": "xc110", "nums": [11], "form": "單題", "img": "img/xc110-11.png", "source": "章學誠《文史通義》", "author": "章學誠", "genre": "說理議論", "types": ["主旨寓意", "文意推論"], "passage": "天下有可為其半而不可為其全者，偏枯之藥可以治偏枯，倍其偏枯之藥不可以起死人也。天下有可為其全而不可為其半者，樵夫擔薪兩鈞，捷步以趨，去其半而不能行，非力不足，勢不便也。", "translation": "天下有些事可以做一半，卻不能做全部：治半身不遂的藥可以治半身不遂，但把藥量加倍，並不能讓死人復活。天下也有些事可以做全部，卻不能只做一半：樵夫挑兩捆各三十斤的柴，可以快步走；拿掉一半反而走不動，不是力氣不夠，而是重心不平衡、形勢不便。", "keywords": [{"w": "偏枯", "m": "半身不遂"}, {"w": "起", "m": "使……復活"}, {"w": "鈞", "m": "古代重量單位，三十斤"}, {"w": "趨", "m": "快走"}, {"w": "勢", "m": "形勢、情勢"}], "questions": [{"n": 11, "qtype": "單選", "stem": "依據下文，最符合主旨的敘述是：", "options": {"A": "再珍貴的藥材亦無法起死回生，面對死生窮達，當樂天知命", "B": "行百里者半九十，不能成事者多因半途而廢，並非力不能及", "C": "應世處事不能拘執一方，必須衡量狀況，審時度勢以制其宜", "D": "完滿或缺殘非由表象判斷，而是取決於主體如何處理和定義"}, "answer": "C", "explain": "兩個例子正好相反：藥是「半可、全不可」，挑柴是「全可、半不可」。可見做多做少沒有固定公式，要看情況、看「勢」來決定，選C。A只抓住藥的例子，而且文章不談樂天知命。B只扣挑柴，但文章說挑不動是「勢不便」，不是半途而廢。D文章講的是做事要配合情勢，不是在談怎麼定義完滿與殘缺。", "skill": "兩個相反的例子並列時，主旨通常是「要看情況」——不要被其中一個例子帶走。"}], "difficulty": "中", "label": "110學測", "year": 110, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc110-12", "exam": "xc110", "nums": [12], "form": "單題", "img": "img/xc110-12.png", "source": "王若虛《滹南詩話》", "author": "王若虛", "genre": "說理議論", "types": ["寫作手法", "文意推論"], "passage": "「郊寒白俗」，詩人類鄙薄之。然鄭厚評詩，荊公、蘇、黃輩曾不比數，而云：「樂天如柳陰春鶯，東野（郊）如草根秋蟲，皆造化中一妙」，何哉？哀樂之真，發乎情性，此詩之正理也。", "translation": "「孟郊的詩寒苦、白居易的詩淺俗」，詩人大多看不起他們。可是鄭厚評論詩人時，王安石、蘇軾、黃庭堅這些人他根本不放在眼裡，卻說：「白居易像柳蔭下的春鶯，孟郊像草根間的秋蟲，都是大自然中的一種美妙」，這是為什麼呢？因為真實的哀樂從性情中自然流露，這才是作詩的正道。", "keywords": [{"w": "郊寒白俗", "m": "蘇軾評孟郊詩寒苦、白居易詩淺俗"}, {"w": "類", "m": "大多"}, {"w": "鄙薄", "m": "輕視"}, {"w": "曾不比數", "m": "根本不放在同列計算，看不上"}, {"w": "造化", "m": "大自然"}], "questions": [{"n": 12, "qtype": "單選", "stem": "關於下文王若虛的論述方式，說明最適當的是：", "options": {"A": "運用對比映襯以凸顯詩人品格上的差異", "B": "藉物象之喻強調詩人長於自然草蟲之詠", "C": "先述習見論評，再引前人說法表達觀點", "D": "先分述各家短長，再總論詩歌創作之道"}, "answer": "C", "explain": "結構分三步：先說一般人的看法（郊寒白俗，詩人大多看不起）→再引鄭厚的不同說法（白、孟都是造化一妙）→最後提出自己的觀點（哀樂之真、發乎情性才是正理），選C。A文章談的是詩風，不是品格。B「春鶯」「秋蟲」是比喻兩人詩風各有自然之妙，不是說他們擅長寫草蟲。D並沒有逐一分述各家優缺點。", "skill": "論述方式題先把段落切成「誰的看法」：一般人→前人→作者，順序就是答案。"}], "difficulty": "中", "label": "110學測", "year": 110, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc110-13", "exam": "xc110", "nums": [13], "form": "單題", "img": "img/xc110-13.png", "source": "出處待查（題目僅稱施先生贈詩）", "author": "", "genre": "古典詩詞曲", "types": ["文化常識", "詩詞賞析"], "passage": "桂已飄香菊作花，門前遙駐七香車。競傳丰度誠端好，定卜咸宜到室家。", "translation": "桂花已經飄香，菊花正在開放，門前遠遠停著迎親的七香車。大家爭相傳說新人風度儀態真是端莊美好，一定可以預料兩人會和睦美滿、宜室宜家。", "keywords": [{"w": "七香車", "m": "用多種香木裝飾的華美車子，常指迎娶新娘的車"}, {"w": "丰度", "m": "風度儀態"}, {"w": "卜", "m": "預料"}, {"w": "咸宜室家", "m": "化用《詩經》「宜其室家」，指婚後家庭和順"}], "questions": [{"n": 13, "qtype": "單選", "stem": "施先生參加朋友舉辦的宴會，贈詩一首：「桂已飄香菊作花，門前遙駐七香車。競傳丰度誠端好，定卜咸宜到室家。」依據詩意，最適合這場宴會的題辭是：", "options": {"A": "珠聯璧合", "B": "椿萱並茂", "C": "君子攸居", "D": "望重桑梓"}, "answer": "A", "explain": "「七香車」是迎親的車，「咸宜到室家」化用《詩經》「之子于歸，宜其室家」，都是婚禮的線索，所以是結婚宴，題辭用「珠聯璧合」（比喻佳偶天成），選A。B「椿萱並茂」用於父母雙壽。C「君子攸居」用於新居落成。D「望重桑梓」用於稱頌在家鄉德高望重，如當選、榮退等。", "skill": "題辭題先從詩中挑出「場合關鍵字」（車、室家→婚禮；椿萱→父母；居→新屋），再對題辭。"}], "difficulty": "易", "label": "110學測", "year": 110, "kind": "學測", "textcat": "生活情境文本", "textcat2": "", "linked_core": ""}, {"id": "xc110-14", "exam": "xc110", "nums": [14], "form": "單題", "img": "img/xc110-14.png", "source": "《史記》、《楚辭》、《紅樓夢》、《儒林外史》人物", "author": "", "genre": "其他", "types": ["文化常識", "文意推論"], "passage": "", "translation": "", "keywords": [{"w": "樊噲", "m": "劉邦部將，鴻門宴中護主"}, {"w": "漁父", "m": "《楚辭‧漁父》中勸屈原隨波逐流的隱者"}, {"w": "胡屠戶", "m": "《儒林外史》范進的岳父"}], "questions": [{"n": 14, "qtype": "單選", "stem": "依據下表的故事角色設定，推斷古代經典中的人物關係，最適當的敘述是：導師（①是必備條件）：①傳授知識或技能，主角因此獲得啟發 ②有時會贈予主角重要或救命之物 ③不拘年紀，也可能是平庸、無德之人。伙伴（①是必備條件）：①忠於主角，值得信賴 ②目標與主角相同，但地位或能力不如主角 ③有時會質疑主角，在衝突中提供建議", "options": {"A": "《史記》中，樊噲是劉邦的伙伴", "B": "《楚辭》中，漁父是屈原的導師", "C": "《紅樓夢》中，薛寶釵是林黛玉的伙伴", "D": "《儒林外史》中，胡屠戶是范進的導師"}, "answer": "A", "explain": "先檢查必備條件①。A樊噲在鴻門宴闖帳護主，對劉邦忠心可靠，符合伙伴①；他和劉邦目標一致而地位較低（②），還在劉邦想留下時勸他「大行不顧細謹」（③），選A。B漁父勸屈原「與世推移」，屈原不接受，沒有因此得到啟發，不合導師①。C薛寶釵和林黛玉是情感上的對手，談不上忠於黛玉。D胡屠戶只會勢利地罵范進、打范進，並沒有傳授知識讓他獲得啟發。", "skill": "條件表格題：先用「必備條件」刪選項，再用其他條件確認。"}], "difficulty": "中", "label": "110學測", "year": 110, "kind": "學測", "textcat": "生活情境文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "xc110-15", "exam": "xc110", "nums": [15, 16, 17], "form": "題組", "img": "img/xc110-15.png", "source": "南宋、明代詞選統計表；李清照〈武陵春〉", "author": "李清照", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文意推論"], "passage": "風住塵香花已盡，日晚倦梳頭。物是人非事事休，欲語淚先流。聞說雙溪春尚好，也擬泛輕舟。只恐雙溪舴艋舟，載不動、許多愁。（李清照〈武陵春〉）", "translation": "風停了，塵土裡還帶著落花的香氣，花已經落盡；天色已晚，我還懶得梳頭。景物依舊，人卻不同了，一切事情都完了，想要說話，眼淚先流了下來。聽說雙溪的春色還很好，我也打算去划小船遊玩。只怕雙溪那小小的舴艋舟，載不動我這麼多的憂愁。", "keywords": [{"w": "塵香", "m": "落花化為塵土仍帶香氣"}, {"w": "事事休", "m": "一切都完了"}, {"w": "擬", "m": "打算"}, {"w": "舴艋舟", "m": "小船"}], "questions": [{"n": 15, "qtype": "單選", "stem": "關於上表內容的探究，最適當的是：", "options": {"A": "從四本明代詞選的備註「#」可知，部分繫名為李清照的詞作，真正作者是朱淑真", "B": "南宋詞選偏好孫夫人、魏夫人詞作的情況，到明代有所轉變，二位詞人的地位改由朱淑真取代", "C": "《唐宋諸賢絕妙詞選》肯定女詞人，「閨秀」卷共收錄十位女詞人詞作，每位至少選錄二首作品", "D": "參考備註「*」推算《梅苑》、《樂府雅詞》中每位詞人的獲選作品平均量，可對照出李清照詞頗受二書青睞"}, "answer": "D", "explain": "D：《梅苑》421首÷82人≈每人5首，李清照卻有18首；《樂府雅詞》923÷95≈每人近10首，李清照有23首，都遠高於平均，可見很受青睞，正確。A「#」只表示作者歸屬「存疑」，不能說真正作者就是朱淑真。B南宋詞選裡孫、魏兩人入選並不多，明代孫夫人仍持續入選，談不上被朱淑真取代。C 10位女詞人共29首，李8、孫5、魏7已占20首，剩下7人只有9首，不可能每人都至少2首。", "skill": "表格題遇到「平均」「每位至少」就動手算，數字會直接告訴你對錯。"}, {"n": 16, "qtype": "單選", "stem": "若以上表為研判依據，關於甲、乙兩項推論，最適當的是：甲、《花草粹編》選錄的詞人總數、詞作總數，均比《樂府雅詞》超出許多。乙、《類編草堂詩餘》僅調整《草堂詩餘》的分類方式，未更動收錄的詞作。", "options": {"A": "甲正確，乙錯誤", "B": "甲錯誤，乙正確", "C": "甲無法判斷，乙錯誤", "D": "甲正確，乙無法判斷"}, "answer": "C", "explain": "甲：表中《花草粹編》只列了「女」詞人數和女詞人作品數，沒有全書的詞人總數、詞作總數（備註「*」只有《梅苑》《樂府雅詞》），所以無法判斷。乙：《草堂詩餘》女詞作13首（李10、孫2），《類編草堂詩餘》15首（李9、孫5），收錄內容明顯不同，所以「未更動收錄的詞作」是錯的。選C。", "skill": "判斷「無法判斷」：題目問的數字表格裡根本沒有，就是無法判斷。"}, {"n": 17, "qtype": "單選", "stem": "上表中的詞選多有收錄李清照〈武陵春〉。關於此詞的解讀，最不適當的是：", "options": {"A": "藉由「花已盡」、「日晚」象徵美好事物的凋逝和歲月的滄桑", "B": "以「倦梳頭」、「淚先流」表現物是人非、世事無常的無力感", "C": "以「聞說」、「也擬」、「只恐」層遞表現出愈益濃烈的遊興", "D": "藉由「舴艋舟」之「載不動」，述說自我承受不住憂愁之深重"}, "answer": "C", "explain": "「聞說」（聽說春色好）→「也擬」（也想去划船）→「只恐」（只怕船載不動愁），心情是先稍微動念、最後又打消，遊興是越來越「淡」，被憂愁壓倒，不是越來越濃，所以C最不適當。A花落盡、日已晚，象徵美好消逝、年華老去，正確。B懶得梳頭、話未說淚先流，表現物是人非的無力，正確。D以船載不動寫愁之重，把抽象的愁寫成有重量，正確。", "skill": "詞中的轉折虛字（只恐、卻、怎）常是情緒的轉彎處，讀到這裡要注意情緒是升還是降。"}], "difficulty": "中", "label": "110學測", "year": 110, "kind": "學測", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "xc110-18", "exam": "xc110", "nums": [18, 19], "form": "題組", "img": "img/xc110-18.png", "source": "甲：《孟子‧離婁下》；乙：王夫之《四書箋解》", "author": "孟子；王夫之", "genre": "經典語錄", "types": ["文意推論", "比較閱讀", "主旨寓意"], "passage": "甲\n人之所以異於禽獸者，幾希。庶民去之，君子存之。舜明於庶物，察於人倫，由仁義行，非行仁義也。\n乙\n「幾希」，言幾於無也，乃一線之象，非一點之象，凡事俱異。凡事之異無多，稍一差錯，則墮入彼中。如禽獸亦未嘗不知「庶物」，只是不「明」；亦未嘗不有「倫類」，只是不「察」；未嘗不有所愛，而不能「行仁」；未嘗不求所宜，而不能「行義」。舉凡日用飲食，俱有異處，而俱差不遠，此其所以必戰兢惕厲，無念無事不思求其所以「異」也。「存之」，謂存其所以異者，以要言之，謂之人道。", "translation": "甲：人和禽獸不同的地方，只有那麼一點點。一般人把它丟掉了，君子把它保存下來。舜明白萬物的道理，洞察人與人之間的倫理，是順著內心的仁義去做，而不是刻意去實行仁義。\n乙：「幾希」是說差不多沒有了，但這差別像一條線（處處都有），不是只有一個點，每件事都有不同。每件事的差別都不多，稍有差錯，就掉到禽獸那邊去了。例如禽獸也不是不知道萬物，只是不「明白」；也不是沒有群類關係，只是不「洞察」；不是沒有愛，只是不能「行仁」；不是不求適宜，只是不能「行義」。凡是日常飲食，都有不同之處，但都相差不遠，所以必須戒慎恐懼、時時警惕，每個念頭、每件事都要想著人和禽獸不同的地方在哪裡。「存之」，就是保存人之所以異於禽獸的部分，簡單說，叫做人道。", "keywords": [{"w": "幾希", "m": "極少、一點點"}, {"w": "去", "m": "捨棄"}, {"w": "庶物", "m": "萬物"}, {"w": "察", "m": "明察"}, {"w": "倫類", "m": "同類間的關係"}, {"w": "戰兢惕厲", "m": "戒慎恐懼、時時警惕"}], "questions": [{"n": 18, "qtype": "單選", "stem": "下列敘述，最符合乙文對甲文「人禽之辨」詮釋的是：", "options": {"A": "人禽在道德意識和日用飲食等各方面，都有很大差異", "B": "禽獸亦具對外在事物的認知能力，且擁有情感和好惡", "C": "人只要稍有過錯，在價值層次上，即墮入禽獸的範疇", "D": "禽獸未嘗無仁義之心，但缺乏追求仁義的意志和智力"}, "answer": "B", "explain": "乙說禽獸「亦未嘗不知庶物」（也認識外物）、「未嘗不有所愛」「未嘗不求所宜」（有喜愛、有追求），所以禽獸也有認知、情感和好惡，選B。A乙一再說「異無多」「俱差不遠」，差異很小，不是很大。C乙說「稍一差錯則墮入彼中」是強調差距極細、必須時時警惕，選項把它說成「只要有過錯就等於禽獸」的價值判決，說得太過。D乙說禽獸「不能行仁、不能行義」，並沒有說禽獸有仁義之心。", "skill": "「未嘗不……只是不……」句型＝先承認有、再指出差在哪；讀懂前半就是本題答案。"}, {"n": 19, "qtype": "單選", "stem": "依據甲、乙二文，君子面對「幾希之異」的態度是：", "options": {"A": "嚴別差異，彰示人道的尊嚴和價值", "B": "存同去異，建立物我共同遵循的仁義準則", "C": "異中求同，探索萬物在紛殊表象下的共同本質", "D": "尊重差異，體認萬物平等，脫離以人為本位的思考"}, "answer": "A", "explain": "甲說「君子存之」，乙解釋「存之，謂存其所以異者……謂之人道」，而且要「戰兢惕厲，無念無事不思求其所以異」。可見君子是要牢牢守住、分清楚人與禽獸的差異，彰顯人道，選A。B「去異」正好相反，君子要存的就是「異」。C「求同」也相反。D儒家正是以人道為本位，不是萬物平等的思想。", "skill": "抓關鍵動詞：「存之」存的是什麼？回到乙文找定義，答案就出來了。"}], "difficulty": "中", "label": "110學測", "year": 110, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc110-20", "exam": "xc110", "nums": [20, 21], "form": "題組", "img": "img/xc110-20.png", "source": "改寫自盧希鵬《為什麼員工都是哈士奇，狼呢？》（白話）；21題引李斯〈諫逐客書〉、杜光庭〈虬髯客傳〉", "author": "盧希鵬；李斯；杜光庭", "genre": "其他", "types": ["文意推論", "比較閱讀"], "passage": "（本文為白話；文言部分見21題）\n甲、〈諫逐客書〉中李斯對秦王說：「今逐客以資敵國，損民以益讎，內自虛而外樹怨於諸侯，求國無危，不可得也。」\n乙、〈虬髯客傳〉中虬髯對李靖說：「某本欲於此世界求事，或當龍戰三二十載，建少功業。今既有主，住亦何為？太原李氏，真英主也。三五年內，即當太平。李郎以英特之才，輔清平之主，竭心盡善，必極人臣。」", "translation": "甲、現在驅逐客卿去資助敵國，減少人民去增加仇敵的力量，對內使自己空虛，對外與諸侯結怨，想要國家沒有危險，是不可能的。\n乙、我本來想在這世上幹一番事業，或許要爭戰二三十年，建立一點功業。現在既然已經有了真主，我留下來還做什麼？太原李氏（李世民）是真正的英明君主，三五年內天下就會太平。李郎以出眾的才能，輔佐太平時代的君主，盡心盡力，一定能做到人臣的最高地位。", "keywords": [{"w": "資", "m": "資助"}, {"w": "讎", "m": "仇敵"}, {"w": "求事", "m": "謀求事業（指爭天下）"}, {"w": "龍戰", "m": "群雄爭戰"}, {"w": "極人臣", "m": "做到人臣最高的地位"}], "questions": [{"n": 20, "qtype": "單選", "stem": "下列敘述，最符合上文觀點的是：", "options": {"A": "創業家全憑視野，不需有專業經理人的學養", "B": "人才若形成品牌，便難以用一般標準衡量其價值", "C": "狼具有侵略性，迫使哈士奇以販售時間交換生計", "D": "土狗靠出走成為狼，哈士奇靠時間熬得久而成為狼"}, "answer": "B", "explain": "文中說「to be（你是誰）」的價值比「to do」高很多，請林志玲演講付高價是「因為演講者是林志玲」——人一旦成為品牌，價值就不是一般計價方式能衡量，選B。A文章沒說創業家不需要學養。C哈士奇賣時間是自己的獲利模式，不是被狼逼的。D文章說的是土狗出走變成狼，沒說哈士奇熬久了會變成狼。", "skill": "例子後面的「理由」才是觀點：林志玲的例子，重點在「因為是她」。"}, {"n": 21, "qtype": "單選", "stem": "依據上文，關於甲、乙兩項推論，最適當的研判是：甲、〈諫逐客書〉中李斯對秦王說：「今逐客以資敵國，損民以益讎，內自虛而外樹怨於諸侯，求國無危，不可得也。」──李斯是價值被低估而想出走的土狗。乙、〈虬髯客傳〉中虬髯對李靖說：「某本欲於此世界求事……李郎以英特之才，輔清平之主，竭心盡善，必極人臣。」──虬髯是希望保有自己時間的狼，期許李靖成為優秀的哈士奇。", "options": {"A": "甲、乙皆正確", "B": "甲、乙皆錯誤", "C": "甲正確，乙錯誤", "D": "甲錯誤，乙正確"}, "answer": "D", "explain": "甲：李斯是被秦王下令驅逐，他上書是為了勸秦王「不要逐客」，希望留下來繼續為秦效力，不是自己覺得被低估而想出走，所以錯。乙：虬髯本來想自己打天下（像狼，時間屬於自己），見到真主李世民後就離開，不願當別人的部屬；又勸李靖去輔佐李世民、「必極人臣」，也就是當受主人重用的優秀哈士奇，所以對。選D。", "skill": "文白對讀先讀懂引文「說話的目的」：李斯是在勸留，不是在告別。"}], "difficulty": "中", "label": "110學測", "year": 110, "kind": "學測", "textcat": "部定古文", "textcat2": "生活情境文本", "linked_core": "諫逐客書、虬髯客傳"}, {"id": "xc110-24", "exam": "xc110", "nums": [24, 25], "form": "題組", "img": "img/xc110-24.png", "source": "甲：《商君書‧墾令》；乙：沈括《夢溪筆談》", "author": "商鞅（託名）；沈括", "genre": "說理議論", "types": ["比較閱讀", "文意推論"], "passage": "甲\n壹山澤，則惡農、慢惰、倍欲之民無所於食；無所於食則必農，農則草必墾矣。貴酒肉之價，重其租，令十倍其樸；然則商賈少，農不能喜酣奭，大臣不為荒飽。商賈少，則上不費粟；民不能善酣奭，則農不慢；大臣不荒，則國事不稽，主無過舉。\n乙\n慶曆中，議弛茶鹽之禁及減商稅，范文正以為不可：茶鹽、商稅之入，但分減商賈之利耳，行於商賈未甚有害也。今國用未減，歲入不可闕，既不取之於山澤及商賈，須取之於農；與其害農，孰若取之於商賈？今為計莫若先省國用，國用有餘，當先寬賦役，然後及商賈，弛禁非所當先也。其議遂寢。", "translation": "甲：由國家統一管理山林湖澤，那些討厭務農、懶惰、貪求過多的人就沒地方找食物；沒地方找食物就一定得去種田，種田的人多了，荒地就一定會被開墾。提高酒肉的價格，加重酒肉的稅，讓它是原價的十倍；這樣商人就會減少，農民不能盡情暢飲，大臣也不會荒廢政事、吃喝無度。商人少了，國家就不必浪費糧食；百姓不能盡情飲酒，農民就不會怠惰；大臣不荒廢，國家政事就不會延誤，君主就不會有錯誤的舉措。\n乙：慶曆年間，朝廷討論放寬茶鹽專賣的禁令並減少商稅，范仲淹認為不可以：茶鹽專賣和商稅的收入，只是分走商人的一部分利潤，對商人沒有太大傷害。現在國家開支沒有減少，每年的收入不能短缺，既然不從山澤和商人那裡取，就必須從農民那裡取；與其傷害農民，哪比得上向商人收取？現在的辦法不如先節省國家開支，等國用有餘，應該先減輕百姓的賦稅勞役，然後才輪到商人，放寬禁令不是應該優先做的事。這個提議於是被擱置。", "keywords": [{"w": "壹山澤", "m": "由國家統管山澤之利"}, {"w": "倍欲", "m": "貪欲過多"}, {"w": "樸", "m": "原價"}, {"w": "酣奭", "m": "暢飲縱情"}, {"w": "稽", "m": "延宕"}, {"w": "弛", "m": "放寬、解除"}, {"w": "孰若", "m": "哪比得上"}, {"w": "寢", "m": "停止、擱置"}], "questions": [{"n": 24, "qtype": "單選", "stem": "關於甲、乙二文對商賈和山澤之利的態度，敘述最適當的是：", "options": {"A": "甲文主張調漲酒肉價格，提高商賈獲利，以活絡經濟", "B": "乙文中，范文正認為維持茶鹽之禁，並不會危及商賈", "C": "甲文主張由國家統管山澤之利，將獲利分配給飢乏的百姓", "D": "乙文中，范文正認為歲入短缺時，不應取之於山澤及商賈"}, "answer": "B", "explain": "范仲淹說茶鹽、商稅「但分減商賈之利耳，行於商賈未甚有害也」——只是分掉商人一點利潤，對商人沒什麼傷害，所以B對。A甲文抬高酒肉價格、加重稅，目的是讓「商賈少」，是打壓商人。C甲文統管山澤，是讓懶人「無所於食」只好去種田，不是把利益分給百姓。D范仲淹說「與其害農，孰若取之於商賈」，主張要向商人取，說反了。", "skill": "政策類文言先找「目的句」：甲的目的是「必農」「商賈少」，掌握目的就能判斷選項方向。"}, {"n": 25, "qtype": "單選", "stem": "關於甲、乙二文對農業和農民的態度，敘述最適當的是：", "options": {"A": "甲文主張減少農民酒肉之樂的機會，使其專注於農作", "B": "乙文中，范文正主張給予農民賦稅優惠，以獎勵務農", "C": "二文皆認為執政者的驕荒怠惰是造成農業不振的主因", "D": "二文皆認為農民是經濟上的弱勢族群，應該予以保護"}, "answer": "A", "explain": "甲文「貴酒肉之價……農不能喜酣奭……則農不慢」：讓酒肉變貴，農民就不能盡情吃喝，也就不會怠惰，專心種田，A對。B范仲淹說等國用有餘「先寬賦役」，是為了不傷害農民、減輕負擔，並不是用優惠來「獎勵」務農。C甲文提到大臣荒飽會延誤國事，但沒說它是農業不振的主因；乙文更沒提。D甲文是用管制手段逼民務農，談不上保護弱勢。", "skill": "注意選項偷換「目的」：寬賦役是為了「不害農」，不是「獎勵農」。"}], "difficulty": "中", "label": "110學測", "year": 110, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc110-26", "exam": "xc110", "nums": [26, 27, 28], "form": "題組", "img": "img/xc110-26.png", "source": "甲：改寫自朱光潛《談文學》（白話）；乙：改寫自蕭馳《聖道與詩心》，引王夫之《薑齋詩話》", "author": "朱光潛；王夫之", "genre": "說理議論", "types": ["比較閱讀", "文意推論", "詩詞賞析"], "passage": "（甲文為白話；乙文所引文言如下）\n鳥宿池邊樹，僧推月下門。（賈島）\n王夫之《薑齋詩話》云：「『僧敲月下門』，只是妄想揣摩，如說他人夢。縱令形容酷似，何嘗毫髮關心？知然者，以其沉吟『推』、『敲』二字，就他作想也。若即景會心，則或推或敲，必居其一。因景因情，自然靈妙，何勞擬議哉？」", "translation": "王夫之說：「『僧敲月下門』這句，只是憑空揣想，就像在說別人做的夢。就算形容得很像，又哪裡有一絲一毫和自己內心相關？怎麼知道是這樣呢？因為他反覆琢磨『推』『敲』兩個字，是站在別人的角度去想。如果是親身面對景物、心有所感，那麼是推還是敲，一定只會是其中一個。依著景、依著情，自然就會靈動美妙，哪裡需要費心比較商量呢？」", "keywords": [{"w": "揣摩", "m": "揣測、猜想"}, {"w": "何嘗", "m": "哪裡曾經"}, {"w": "沉吟", "m": "反覆思量"}, {"w": "即景會心", "m": "面對眼前景物而心有所感"}, {"w": "擬議", "m": "揣度、比較商量"}, {"w": "措大", "m": "窮書生（帶輕視意味）"}], "questions": [{"n": 26, "qtype": "單選", "stem": "甲文朱光潛「懷疑韓愈的修改是否真如古今所稱賞的那麼妥當」的理由是：", "options": {"A": "用「敲」字不能展現詩人的胸襟氣度", "B": "用「推」字與全詩冷寂的氛圍更相應", "C": "「敲」字有聲響感，攪擾寺內的莊嚴氣氛", "D": "「推」字雖魯莽，但能表達僧人訪友心情"}, "answer": "B", "explain": "朱光潛說「就上句『鳥宿池邊樹』看來，『推』似乎比『敲』要調和些」，又說關鍵在「與全詩調和」：推可以無聲，配合鳥已入睡的冷寂夜景，B對。A朱光潛說推字表現「一副胸襟氣度」，但他懷疑韓愈的理由是全詩調和，不是胸襟。C敲門聲驚起的是「宿鳥」、打破的是「岑寂」，不是寺內的莊嚴。D「訪友」是「敲」字的意境，不是推。", "skill": "「理由是」題回到作者下結論的那句（關鍵在於……），不要被前面的描述細節帶走。"}, {"n": 27, "qtype": "單選", "stem": "乙文中，王夫之認為「或推或敲，必居其一」的原因是：", "options": {"A": "若韓愈有近似的經驗，就無須揣摩賈島的實際狀況，可直接選出推或敲", "B": "若韓愈能從全詩調和的情境來考慮，就能知道用推或敲，何者意境較佳", "C": "若賈島能從傳統佳作中鍛鍊用字技巧，就能輕易選定推或敲，不必詢問他人", "D": "若賈島能依據真實經驗，寫出當時景物及內在情感，就能清楚應選擇推或敲"}, "answer": "D", "explain": "王夫之說「若即景會心，則或推或敲，必居其一」：如果詩人親身在那個場景、有真實感受，當時是推門還是敲門就只有一個答案，根本不用猶豫，D對。A、B主詞錯成韓愈，而且王夫之反對的就是「揣摩」與「擬議」。C從傳統佳作學技巧，正是王夫之批評的「措大燈窗下鑽故紙」。", "skill": "「若……則……」是條件句：條件（即景會心）就是原因，直接翻譯它。"}, {"n": 28, "qtype": "單選", "stem": "依據甲、乙二文，下列敘述最不適當的是：", "options": {"A": "朱光潛強調文字上的斟酌與推敲，其實更動後表現的是不同的思想情感", "B": "王夫之認為在文字上沉吟推敲，即使最終文辭巧妙，仍非出自真實情感", "C": "朱光潛懷疑僧敲月下門未必比僧推月下門更好，王夫之則未做高下評判", "D": "王夫之、朱光潛均認為推敲文字首重全詩情調一致，才能臻至自然靈妙"}, "answer": "D", "explain": "「全詩調和」是朱光潛的標準；王夫之重視的是「即景會心」、真實的經驗與情感，「自然靈妙」也是王夫之的話，兩人的重點不同，所以D最不適當。A朱光潛說「更動了文字，就同時更動了思想情感」，正確。B王夫之說「縱令形容酷似，何嘗毫髮關心」，正確。C王夫之只說推敲都是揣摩，沒有判定哪個字比較好，正確。", "skill": "比較題遇到「均認為」，要確認兩人真的都說過；把甲的話安到乙身上是常見陷阱。"}], "difficulty": "難", "label": "110學測", "year": 110, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc110-31", "exam": "xc110", "nums": [31, 32], "form": "題組", "img": "img/xc110-31.png", "source": "曾鞏〈答李沿書〉", "author": "曾鞏", "genre": "書信序跋", "types": ["典故出處", "主旨寓意", "文意推論"], "passage": "夫足下之書，始所云者欲至乎道也，而所質者則辭也，無乃務其淺，忘其深，當急者反徐之歟！夫道之大歸非他，欲其得諸心，充諸身，擴而被之國家天下而已，非汲汲乎辭也。其所以不已乎辭者，非得已也。孟子曰：「□□」此其所以為孟子也。今足下其自謂已得諸心、充諸身歟？擴而被之國家天下而有不得已歟？不然，何遽急於辭也？", "translation": "您的來信，一開始說想要達到「道」，可是您請教的卻是文辭，這不就是致力於淺的、忘了深的，該急的反而放慢了嗎！道的大旨沒有別的，就是要在心裡體會它，在自身充實它，再擴大推行到國家天下罷了，不是急著追求文辭。那些人之所以不停地寫文辭，是因為不得已。孟子說：「我難道喜歡辯論嗎？我是不得已啊。」這正是孟子之所以為孟子的原因。現在您自認為已經心有所得、自身充實了嗎？已經推行到國家天下而有不得已要說的話了嗎？如果不是，為什麼急著追求文辭呢？", "keywords": [{"w": "足下", "m": "對平輩的敬稱，您"}, {"w": "質", "m": "詢問、請教"}, {"w": "無乃……歟", "m": "恐怕是……吧"}, {"w": "徐", "m": "緩、放慢"}, {"w": "大歸", "m": "大旨、歸趨"}, {"w": "被", "m": "覆蓋、推及"}, {"w": "汲汲", "m": "急切追求"}, {"w": "遽", "m": "急、匆忙"}], "questions": [{"n": 31, "qtype": "單選", "stem": "上文□□內最適合填入的文句是：", "options": {"A": "予豈好辯哉？予不得已也", "B": "無辭讓之心，非人也", "C": "不以文害辭，不以辭害志", "D": "盡信書，則不如無書"}, "answer": "A", "explain": "前一句說「其所以不已乎辭者，非得已也」（之所以不停發言寫作，是不得已），引孟子正要呼應「不得已」，所以是「予豈好辯哉？予不得已也」，選A。B講四端的辭讓之心。C講讀詩不要拘泥字面而誤解作者本意。D講讀書不可盡信。三者都和「不得已才發言」無關。", "skill": "引文填空看前後句的關鍵詞，前面說「非得已」，引文裡就該有「不得已」。"}, {"n": 32, "qtype": "單選", "stem": "依據上文，曾鞏主要是想提醒李沿：", "options": {"A": "治天下應恤民重諾", "B": "寫文章應深入淺出", "C": "讀書不宜欲速躁進", "D": "為學不宜捨本逐末"}, "answer": "D", "explain": "李沿說想求「道」，卻只問「辭」；曾鞏批評他「務其淺，忘其深，當急者反徐之」——道是根本，文辭是末節，先修養心身、推及天下，有不得已才發為文辭。所以是提醒他為學不要捨本逐末，選D。A沒談恤民重諾。B不是在談寫作技巧。C重點不是速度，而是先後輕重。", "skill": "書信題找「對方的問題」和「作者的批評」：對方問辭、作者說該重道，答案就是本末。"}], "difficulty": "中", "label": "110學測", "year": 110, "kind": "學測", "textcat": "學術文本", "textcat2": "生活情境文本", "linked_core": ""}, {"id": "xc110-33", "exam": "xc110", "nums": [33, 34], "form": "題組", "img": "img/xc110-33.png", "source": "《戰國策‧魏策》", "author": "", "genre": "寓言故事", "types": ["人物情感", "主旨寓意", "寫作手法"], "passage": "魏王欲攻邯鄲，季梁聞之，中道而反。衣焦不申，頭塵不去，往見王曰：「今者臣來，見人於大行，方北面而持其駕，告臣曰：『我欲之楚。』臣曰：『君之楚，將奚為北面？』曰：『吾馬良。』臣曰：『馬雖良，此非楚之路也。』曰：『吾用多。』臣曰：『用雖多，此非楚之路也。』曰：『吾御者善。』此數者愈善，而離楚愈遠耳。今王動欲成霸王，舉欲信於天下；恃王國之大、兵之精銳，而攻邯鄲，以廣地尊名。王之動愈數，而離王愈遠耳，猶至楚而北行也。」", "translation": "魏王想攻打趙國的邯鄲，季梁聽說了，半路上就折返回來。衣服皺了沒拉平，頭上的灰塵也沒撣掉，就去見魏王說：「我剛才回來時，在大路上看見一個人，正面朝北駕著車，告訴我說：『我要去楚國。』我說：『你要去楚國，為什麼往北走？』他說：『我的馬好。』我說：『馬雖然好，這不是去楚國的路。』他說：『我的旅費多。』我說：『旅費雖多，這不是去楚國的路。』他說：『我的車夫駕車技術好。』這幾樣條件越好，離楚國就越遠罷了。現在大王的行動想要成就霸業，舉措想要取信於天下；卻仗著國家大、軍隊精銳，去攻打邯鄲，想擴張土地、提高名聲。大王這樣的行動越多，離稱王的目標就越遠，就像要到楚國卻往北走一樣。」", "keywords": [{"w": "反", "m": "同「返」"}, {"w": "衣焦不申", "m": "衣服皺縮沒有拉平"}, {"w": "大行", "m": "大路"}, {"w": "之", "m": "往、到"}, {"w": "奚為", "m": "為什麼"}, {"w": "用", "m": "資用、旅費"}, {"w": "數", "m": "屢次、頻繁（音ㄕㄨㄛˋ）"}, {"w": "信", "m": "同「伸」，伸張威信"}], "questions": [{"n": 33, "qtype": "單選", "stem": "上文特意描繪季梁往見魏王時「衣焦不申，頭塵不去」的形象，主要在凸顯：", "options": {"A": "個性率真，不重外貌衣著", "B": "君臣親密，不拘繁文縟節", "C": "事態緊急，不暇梳洗更衣", "D": "旅途艱辛，不辭跋山涉水"}, "answer": "C", "explain": "季梁「聞之，中道而反」——一聽說魏王要出兵，半路就趕回來，連衣服、頭髮都來不及整理就去見王，可見他認為事情緊急、必須立刻勸阻，選C。A、B都不是重點，文中沒有寫他的個性或君臣關係。D雖然旅途勞頓，但作者強調的是他急著趕來，不是旅途多苦。", "skill": "外貌描寫要連前文的行動一起看：「中道而反」＋「衣焦頭塵」＝急。"}, {"n": 34, "qtype": "單選", "stem": "下列敘述，最符合上文所欲表達觀點的是：", "options": {"A": "前車之鑑，可以為師", "B": "欲速不達，弄巧成拙", "C": "緣木求魚，徒勞無功", "D": "駑馬十駕，功在不舍"}, "answer": "C", "explain": "「南轅北轍」的故事：方向錯了，馬再好、錢再多、車夫再好，只會離目標越遠。魏王想成霸業卻靠攻伐，方法和目標背道而馳，就像爬到樹上找魚，選C。A講記取前人教訓。B講太急反而做不到，故事重點不是快慢。D講只要堅持不懈就能成功，和本文相反。", "skill": "寓言主旨題，把故事濃縮成一句「用錯方法→離目標更遠」，再找同義成語。"}], "difficulty": "易", "label": "110學測", "year": 110, "kind": "學測", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "馮諼客孟嘗君"}, {"id": "xc110-35", "exam": "xc110", "nums": [35], "form": "單題", "img": "img/xc110-35.png", "source": "蘇軾〈赤壁賦〉、白居易〈賣炭翁〉、《荀子‧勸學》、《戰國策‧馮諼客孟嘗君》、柳宗元〈始得西山宴遊記〉、方苞〈左忠毅公軼事〉等", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)山川相繆，鬱乎「蒼蒼」／兩鬢「蒼蒼」十指黑\n(B)無「惛惛」之事者，無赫赫之功／心神恍惚，「惛惛」如醉\n(C)今君有「區區」之薛，不拊愛子其民／奚必於「區區」耳目之所及，度量世外事乎\n(D)自余為僇人，居是州，恆惴慄。其隟也，則「施施」而行／達官坐享俸祿，「施施」自得\n(E)吾諸兒「碌碌」，他日繼吾志事，惟此生耳／軾也，遠方之鄙人，家居「碌碌」，無所稱道", "translation": "(A)山水互相纏繞，草木茂密青蒼／兩邊鬢髮灰白，十根手指烏黑。\n(B)沒有專心默默做事的人，就沒有顯赫的功績／心神恍惚，迷迷糊糊像喝醉一樣。\n(C)現在您只有小小的薛地，卻不愛護那裡的百姓／何必用那有限的耳目所及，去揣度世外的事呢？\n(D)自從我成為罪人，住在這個州，常常憂懼不安。空閒時，就慢慢地走／達官貴人白白享受俸祿，洋洋得意。\n(E)我的幾個兒子都平庸無能，將來繼承我志向事業的，只有這個書生了／我蘇軾是遠方的鄙陋之人，在家平平庸庸，沒有什麼值得稱道的。", "keywords": [{"w": "蒼蒼", "m": "深青茂盛；灰白"}, {"w": "惛惛", "m": "專心默默；迷糊不清"}, {"w": "區區", "m": "小、少"}, {"w": "施施", "m": "徐行貌；得意貌"}, {"w": "碌碌", "m": "平庸無能"}], "questions": [{"n": 35, "qtype": "多選", "stem": "下列各組「」內的詞語，意義前後相同的是：", "options": {"A": "山川相繆，鬱乎「蒼蒼」／兩鬢「蒼蒼」十指黑", "B": "無「惛惛」之事者，無赫赫之功／心神恍惚，「惛惛」如醉", "C": "今君有「區區」之薛，不拊愛子其民／奚必於「區區」耳目之所及，度量世外事乎", "D": "自余為僇人，居是州，恆惴慄。其隟也，則「施施」而行／達官坐享俸祿，「施施」自得", "E": "吾諸兒「碌碌」，他日繼吾志事，惟此生耳／軾也，遠方之鄙人，家居「碌碌」，無所稱道"}, "answer": "CE", "explain": "A：前「蒼蒼」形容草木深青茂盛，後形容頭髮灰白，不同。B：前「惛惛」是專心默默（與後文「赫赫」相對），後是神智迷糊，不同。C：兩個「區區」都是小、有限，相同。D：前「施施」是緩慢行走的樣子，後是得意的樣子，不同。E：兩個「碌碌」都是平庸無能，相同。答案CE。", "skill": "疊字詞常一詞多義，看它修飾的對象：修飾山川、鬢髮、走路還是心情，意思就跟著變。"}], "difficulty": "中", "label": "110學測", "year": 110, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "勸學、馮諼客孟嘗君、始得西山宴遊記、赤壁賦、左忠毅公軼事"}, {"id": "xc110-36", "exam": "xc110", "nums": [36], "form": "單題", "img": "img/xc110-36.png", "source": "范仲淹〈岳陽樓記〉、曹丕〈典論論文〉、諸葛亮〈出師表〉、黃庭堅〈寄黃幾復〉、韓愈〈師說〉、王羲之〈蘭亭集序〉、魏徵〈諫太宗十思疏〉等", "author": "", "genre": "其他", "types": ["寫作手法"], "passage": "(A)正對：日星隱耀，山岳潛形／反對：西伯幽而演易，周旦顯而制禮\n(B)正對：物窮必變，慘極知悔／反對：受任於敗軍之際，奉命於危難之間\n(C)正對：塞客衣單，孀閨淚盡／反對：桃李春風一杯酒，江湖夜雨十年燈\n(D)正對：位卑則足羞，官盛則近諛／反對：麝蘭芳靄斜陽院，杜若香飄明月洲\n(E)正對：一死生為虛誕，齊彭殤為妄作／反對：竭誠則胡越為一體，傲物則骨肉為行路", "translation": "(A)日月星辰隱去光輝，山岳隱沒形體／周文王被囚禁而推演《易經》，周公顯貴而制定禮樂。\n(C)邊塞的旅人衣衫單薄，守寡的婦人淚水流乾／桃李盛開的春風中共飲一杯酒，江湖飄泊的夜雨裡獨對孤燈十年。\n(D)向地位低的人學習就覺得羞恥，向官位高的人學習就近於諂媚。\n(E)把生死看成一樣是荒誕的，把長壽短命看成相同是虛妄的／竭盡誠心，連胡、越這樣遠隔的人也能團結如一體；傲慢待人，連骨肉至親也會變成陌路人。", "keywords": [{"w": "正對", "m": "上下句意思相近、事異義同"}, {"w": "反對", "m": "上下句意義相反、對照凸顯"}, {"w": "幽", "m": "被囚禁"}, {"w": "彭殤", "m": "長壽的彭祖與早夭者"}, {"w": "胡越", "m": "北胡南越，比喻相隔極遠"}], "questions": [{"n": 36, "qtype": "多選", "stem": "對偶有「正對」、「反對」之別。「正對」的特徵是事異義同，上下句意思雷同，例如「木受繩則直，金就礪則利」；「反對」的特徵是藉由異質或相反事物的並列對照，凸顯意旨，例如「棄燕雀之小志，慕鴻鵠以高翔」。下列對偶的歸類，完全符合上述定義的是：", "options": {"A": "正對：日星隱耀，山岳潛形／反對：西伯幽而演易，周旦顯而制禮", "B": "正對：物窮必變，慘極知悔／反對：受任於敗軍之際，奉命於危難之間", "C": "正對：塞客衣單，孀閨淚盡／反對：桃李春風一杯酒，江湖夜雨十年燈", "D": "正對：位卑則足羞，官盛則近諛／反對：麝蘭芳靄斜陽院，杜若香飄明月洲", "E": "正對：一死生為虛誕，齊彭殤為妄作／反對：竭誠則胡越為一體，傲物則骨肉為行路"}, "answer": "ACE", "explain": "A：日星、山岳都「隱沒」，意思相同是正對；「幽」與「顯」相反，是反對，完全正確。B：「受任於敗軍之際，奉命於危難之間」上下句都說在危急時接受任命，意思相同，是正對，不是反對，錯。C：邊塞旅人與閨中寡婦都在受苦，是正對；春風飲酒的歡聚與夜雨孤燈的離別相對照，是反對，正確。D：「麝蘭芳靄」「杜若香飄」都寫香氣瀰漫的美景，是正對，卻被放在反對，錯；「位卑」與「官盛」高低相反，也不適合歸為正對。E：一死生、齊彭殤都是莊子的齊物觀，都被批評為虛妄，是正對；「竭誠」與「傲物」、「一體」與「行路」相反，是反對，正確。答案ACE。", "skill": "判斷正對反對：把上下句各濃縮成一個詞（隱/隱、幽/顯），一樣是正對，相反是反對。"}], "difficulty": "中", "label": "110學測", "year": 110, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "典論論文、出師表、蘭亭集序、師說、諫太宗十思疏、岳陽樓記"}, {"id": "xc110-37", "exam": "xc110", "nums": [37], "form": "單題", "img": "img/xc110-37.png", "source": "《論語‧子罕》、蘇軾〈赤壁賦〉、《史記‧項羽本紀》、韓愈〈師說〉、《左傳‧燭之武退秦師》", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "(A)松柏後凋於歲寒\n(B)此非孟德之困於周郎者乎\n(C)沛公曰：孰與君少長？良曰：長於臣\n(D)是故弟子不必不如師，師不必賢於弟子\n(E)秦、晉圍鄭，鄭既知亡矣。若亡鄭而有益於君，敢以煩執事", "translation": "(A)松柏在嚴寒的時節最後凋零。\n(B)這不就是曹操被周瑜圍困的地方嗎？\n(C)沛公說：他和你誰年紀大？張良說：比我年長。\n(D)所以學生不一定不如老師，老師不一定比學生賢能。\n(E)秦、晉包圍鄭國，鄭國已經知道要滅亡了。如果滅掉鄭國對您有好處，那就冒昧地麻煩您的手下吧。", "keywords": [{"w": "形容詞＋於＋名詞", "m": "比……（形容詞），表比較"}, {"w": "於（A）", "m": "在"}, {"w": "於（B）", "m": "被"}, {"w": "於（E）", "m": "對"}], "questions": [{"n": 37, "qtype": "多選", "stem": "古文表達兩事物相比較時，常運用「形容詞＋於＋名詞」的句型，例如：「羅紈之盛，多於堤畔之草」，「多於堤畔之草」即「比堤畔之草多」的意思。下列含有「於」的句子，屬於此種表意方式的是：", "options": {"A": "松柏後凋於歲寒", "B": "此非孟德之困於周郎者乎", "C": "沛公曰：孰與君少長？良曰：長於臣", "D": "是故弟子不必不如師，師不必賢於弟子", "E": "秦、晉圍鄭，鄭既知亡矣。若亡鄭而有益於君，敢以煩執事"}, "answer": "CD", "explain": "A「後凋於歲寒」＝在嚴寒時最後凋零，「於」是「在」，表時間。B「困於周郎」＝被周瑜圍困，「於」表被動。C「長於臣」＝比我年長，形容詞「長」＋於＋臣，表比較，正確。D「賢於弟子」＝比學生賢能，表比較，正確。E「有益於君」＝對您有好處，「於」是「對」。答案CD。", "skill": "把「X於Y」翻成「比Y還X」試試看，通順就是比較；翻成「在、被、對」才通的就不是。"}], "difficulty": "易", "label": "110學測", "year": 110, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "燭之武退秦師、鴻門宴、師說、赤壁賦"}, {"id": "xc110-40", "exam": "xc110", "nums": [40], "form": "單題", "img": "img/xc110-40.png", "source": "《列子‧說符》", "author": "列子", "genre": "寓言故事", "types": ["文意推論", "主旨寓意"], "passage": "晉國苦盜。有郄雍者，能視盜之貌，察其眉睫之間，而得其情。晉侯使視盜，千百無遺一焉。晉侯大喜，告趙文子曰：「吾得一人，而一國盜為盡矣，奚用多為？」文子曰：「吾君恃伺察而得盜，盜不盡矣。且郄雍必不得其死焉。」俄而群盜謀曰：「吾所窮者，郄雍也。」遂共盜而殘之。晉侯聞而大駭，立召文子而告之曰：「果如子言，郄雍死矣！然取盜何方？」文子曰：「周諺有言：『察見淵魚者不祥，智料隱匿者有殃。』且君欲無盜，莫若舉賢而任之，使教明於上，化行於下，民有恥心，則何盜之為？」於是用隨會知政，而群盜奔秦焉。", "translation": "晉國苦於盜賊太多。有個叫郄雍的人，能看人的相貌，觀察眉眼之間的神色，就知道他是不是盜賊。晉侯派他去辨認盜賊，成千上百個沒有漏掉一個。晉侯非常高興，告訴趙文子說：「我得到一個人，全國的盜賊就被抓光了，哪裡需要那麼多人呢？」文子說：「君主靠暗中偵察來抓盜賊，盜賊是抓不完的。而且郄雍一定不得好死。」不久，盜賊們商量說：「讓我們走投無路的，就是郄雍。」於是一起偷襲殺害了他。晉侯聽說後大為驚恐，立刻召見文子說：「果然像你說的，郄雍死了！那麼要用什麼方法抓盜賊呢？」文子說：「周朝有句諺語：『能看清深水裡魚的人不吉祥，能用智慧推測別人隱私的人有災禍。』而且君主想要沒有盜賊，不如舉用賢人、任用他，讓教化在上面彰明，在下面推行，百姓有了羞恥心，還有誰會去當盜賊呢？」晉侯於是任用隨會主持政事，盜賊們都逃到秦國去了。", "keywords": [{"w": "苦", "m": "苦於、為……所苦"}, {"w": "情", "m": "實情"}, {"w": "奚用多為", "m": "哪裡用得著那麼多（人、方法）呢"}, {"w": "伺察", "m": "暗中偵察"}, {"w": "不得其死", "m": "不得善終"}, {"w": "窮", "m": "使……困窘"}, {"w": "殘", "m": "殺害"}, {"w": "知政", "m": "主持政事"}], "questions": [{"n": 40, "qtype": "多選", "stem": "依據下文，符合故事內容的敘述是：", "options": {"A": "郄雍善於鑒人，能由人物的面目氣質判斷其是否為盜賊", "B": "郄雍善於察盜，晉侯大喜而授以專權，晉國亦因而大治", "C": "郄雍的表現引起同儕的嫉妒而遭殺害，符合文子的預言", "D": "文子認為過於善察和用智並非好事，將會為己招來災禍", "E": "文子將善於教化百姓的隨會推薦給晉侯，盜賊因而遷善"}, "answer": "AD", "explain": "A對：「視盜之貌，察其眉睫之間，而得其情」。B錯：文中沒說晉侯授予郄雍專權，而且盜賊抓不完、郄雍還被殺，國家並未大治。C錯：郄雍是被「群盜」聯手殺害，不是同儕嫉妒。D對：文子引周諺「察見淵魚者不祥，智料隱匿者有殃」，說太會看穿別人反而招禍。E錯：文子只建議「舉賢而任之」，沒說是他推薦隨會；而且盜賊是「奔秦」（逃走），不是改過向善。答案AD。", "skill": "故事題逐項找「人物＋動作」的原文依據：誰殺的、誰推薦的、結果是逃走還是改過，細節最常被換掉。"}], "difficulty": "易", "label": "110學測", "year": 110, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk110-03", "exam": "zk110", "nums": [3], "form": "單題", "img": "img/zk110-03.png", "source": "康培致王晉輝書信（出處待查）", "author": "康培", "genre": "書信序跋", "types": ["文化常識", "句意理解"], "passage": "晉輝先生左右：前天不明原因發熱，後漸增。今日延醫診視，知是瘄子。此一星期內不能外出受風，希賜休暇為幸。專此，敬請\n道安\n康培謹上", "translation": "晉輝先生：前天不知什麼原因發燒，後來越燒越高。今天請醫生來診察，知道是出麻疹。這一星期內不能出門吹風，希望您准我休假，就很感謝了。特此寫信，敬祝教安。康培敬上。", "keywords": [{"w": "左右", "m": "提稱語，用於平輩，表示不敢直呼對方，只敢告知其左右的人"}, {"w": "延醫", "m": "請醫生"}, {"w": "瘄子", "m": "麻疹"}, {"w": "希賜休暇為幸", "m": "希望准假，就很榮幸"}, {"w": "道安", "m": "用於教育界人士的問候語"}], "questions": [{"n": 3, "qtype": "單選", "stem": "依據右框康培寫給王晉輝的書信，敘述最適當的是：", "options": {"A": "由全文可推知，二人為年齡相近的長官與下屬", "B": "康培表示因延誤就醫，使病況加重且瘄疹增多", "C": "康培寫這封信的目的，是拜託王晉輝代為請假", "D": "對王晉輝的信末結尾問候語，也可用「福安」"}, "answer": "A", "explain": "(A)正確：稱對方「先生左右」是對平輩的用法，可推知年齡相近；信中「希賜休暇」是請對方批准休假，可見王晉輝是長官、康培是下屬。\n(B)錯：信中只說發熱漸增、今天請醫生看，沒有說延誤就醫使病況加重。\n(C)錯：「希賜休暇」是直接向王晉輝請假，不是拜託他代為請假。\n(D)錯：結尾問候語要依收信人身分選用，「道安」適用教育界；「福安」多用於長輩，不能隨意替換。", "skill": "書信題先看稱謂與提稱語判斷「輩分」，再看信中請求的動詞（賜、准）判斷「上下關係」。"}], "difficulty": "中", "label": "110指考", "year": 110, "kind": "指考", "textcat": "生活情境文本", "textcat2": "", "linked_core": ""}, {"id": "zk110-04", "exam": "zk110", "nums": [4], "form": "單題", "img": "img/zk110-04.png", "source": "項穆《書法雅言》", "author": "項穆", "genre": "說理議論", "types": ["文意推論", "主旨寓意"], "passage": "書法要旨，有正與奇。所謂正者，偃仰頓挫，揭按照應，筋骨威儀，確有節制是也。所謂奇者，參差起復，騰凌射空，風情恣態，巧妙多端是也。奇即運於正之內，正即列於奇之中。正而無奇，雖莊嚴沉實，恆樸厚而少文。奇而弗正，雖雄爽飛妍，多譎厲而乏雅。……世之厭常以喜新者，每捨正而慕奇，豈知奇不必求，久之自至者哉。", "translation": "書法的要領，有「正」和「奇」。所謂正，是筆畫的俯仰、頓挫，提筆按筆前後呼應，字有筋骨、有威儀，確實有節制。所謂奇，是筆勢參差起伏，騰躍凌空，風情姿態，巧妙變化多端。奇就運行在正之中，正也排列在奇之內。只有正而沒有奇，雖然莊重沉穩，卻常常樸厚而缺少文采；只有奇而沒有正，雖然雄健爽朗、飛動妍麗，卻多半怪異凌厲而缺乏雅正。……世上厭倦平常而喜歡新奇的人，往往捨棄正而追求奇，哪裡知道奇不必刻意追求，練久了自然就會達到呢。", "keywords": [{"w": "偃仰頓挫", "m": "筆畫的俯仰與停頓轉折"}, {"w": "揭按", "m": "提筆與按筆"}, {"w": "騰凌射空", "m": "筆勢騰躍凌空"}, {"w": "譎厲", "m": "怪異凌厲"}, {"w": "厭常", "m": "厭倦平常"}], "questions": [{"n": 4, "qtype": "單選", "stem": "下列敘述，最符合本文有關書法觀點的是：", "options": {"A": "嫻習「偃仰頓挫」，久之自可「參差起復」", "B": "重視「筋骨威儀」，但更強調「風情恣態」", "C": "須「捨正慕奇」，方可至「騰凌射空」之境", "D": "時人多喜「莊嚴沉實」，不好「雄爽飛妍」"}, "answer": "A", "explain": "(A)正確：「偃仰頓挫」屬於「正」，「參差起復」屬於「奇」；文末說「奇不必求，久之自至」，所以把正練熟了，久而久之自然能奇。\n(B)錯：作者主張奇正相融，沒有說更強調「風情恣態」（奇）。\n(C)錯：「捨正慕奇」是作者批評的世俗做法。\n(D)錯：時人是「厭常以喜新」、捨正慕奇，應是喜歡雄爽飛妍而不喜莊嚴沉實，說反了。", "skill": "先把文中術語分成兩組（哪些屬正、哪些屬奇），再用作者結論「奇不必求，久之自至」檢查選項。"}], "difficulty": "中", "label": "110指考", "year": 110, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk110-05", "exam": "zk110", "nums": [5], "form": "單題", "img": "img/zk110-05.png", "source": "洪繻〈王安石論後書《周禮》說〉", "author": "洪繻", "genre": "說理議論", "types": ["文意推論", "典故出處"], "passage": "五穀為養人之物，而飲食醉飽可以致死；藥石為治病之資，而庸醫可以殺人。自王莽、王安石行《周禮》之後，而世遂視《周禮》若烏喙，然管子固嘗以致霸，後周宇文泰亦嘗藉之立國，此物此志也。", "translation": "五穀是養活人的東西，但吃喝過度醉飽也會致死；藥物是治病的材料，但庸醫用了也會殺人。自從王莽、王安石推行《周禮》之後，世人就把《周禮》看成毒藥烏頭一樣，然而管仲曾經用它使齊國稱霸，北周宇文泰也曾憑藉它建立國家，用的是同一部書、同樣的志向啊。", "keywords": [{"w": "藥石", "m": "藥物"}, {"w": "烏喙", "m": "烏頭，一種毒藥"}, {"w": "致霸", "m": "成就霸業"}, {"w": "此物此志", "m": "同樣的東西、同樣的用意"}], "questions": [{"n": 5, "qtype": "單選", "stem": "關於文中人物施行《周禮》的動機、結果，敘述最適當的是：", "options": {"A": "王莽因行《周禮》而遭後世詆毀", "B": "王安石推行《周禮》卻未得好評", "C": "管仲主張以霸治國故倡《周禮》", "D": "宇文泰巧藉《周禮》以欺世盜名"}, "answer": "B", "explain": "作者用「五穀醉飽可致死、藥石庸醫可殺人」比喻：問題不在《周禮》，而在使用的人。(B)王安石依《周禮》推行新法，之後世人把《周禮》視為毒藥，可見他的推行沒有得到好評，正確。\n(A)文中被世人看壞的是《周禮》本身，並沒有說王莽是因為行《周禮》才遭詆毀。\n(C)文中只說管仲用《周禮》成就霸業，沒有說他是因主張以霸治國才提倡《周禮》，動機說錯。\n(D)宇文泰「藉之立國」，作者是正面舉例，不是說他欺世盜名。", "skill": "遇到「比喻＋舉例」的論證，先找比喻說的道理（工具本身無罪），再判斷各例子是正例還是反例。"}], "difficulty": "難", "label": "110指考", "year": 110, "kind": "指考", "textcat": "延伸", "textcat2": "學術文本", "linked_core": "鹿港乘桴記"}, {"id": "zk110-07", "exam": "zk110", "nums": [7], "form": "單題", "img": "img/zk110-07.png", "source": "楊萬里《誠齋詩話》", "author": "楊萬里", "genre": "說理議論", "types": ["寫作手法", "典故出處"], "passage": "四六有截斷古人語五字，而補以一字，如天成者；有用古人語，不易其字之形，而易其意者。《漢書》云：「在漢廷無出其右」，《論語》云：「與文子同升諸公」。而翟公巽〈賀蔡攸除少師啟〉云：「朝廷無出其右，父子同升諸公」，既截斷其語，而補以一字，讀者不覺其補，而又易文子為父子……此巧之至也。", "translation": "四六駢文中，有截取古人的五個字，再補上一個字，就像天生的一樣；也有引用古人的話，不改變字形，卻改變了意思的。《漢書》說：「在漢朝朝廷沒有人能超過他」，《論語》說：「（公叔文子推薦家臣）和文子一同升為公朝之臣」。而翟公巽〈賀蔡攸除少師啟〉說：「朝廷無出其右，父子同升諸公」，既截取了原句，又補上一個字，讀者察覺不出是補的，又把「文子」改成「父子」……這真是巧妙到了極點。", "keywords": [{"w": "四六", "m": "駢文，多用四字、六字句"}, {"w": "無出其右", "m": "沒有人超過他"}, {"w": "同升諸公", "m": "一同升任公朝之官"}, {"w": "除", "m": "任命官職"}], "questions": [{"n": 7, "qtype": "單選", "stem": "依據文意，最能說明劃底線處文句表現特色的是：", "options": {"A": "善刪削冗贅，言簡意賅", "B": "不仿擬古人，獨出機杼", "C": "取材古經史，藉古諷今", "D": "化用典籍語，無斧鑿痕"}, "answer": "D", "explain": "翟公巽截取《漢書》《論語》的句子，補一個字、改一個字，「讀者不覺其補」，讀起來自然天成，正是(D)化用典籍語句，看不出刻意雕琢的痕跡。\n(A)重點是借用改造古語，不是刪減冗贅。\n(B)明明是借用古人語，不是不仿擬古人。\n(C)取材經史沒錯，但這是賀啟，目的在讚美，沒有藉古諷今。", "skill": "讀詩話、文論，先找作者的評語（如天成、讀者不覺、巧之至），選項要對應這個評語。"}], "difficulty": "中", "label": "110指考", "year": 110, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk110-08", "exam": "zk110", "nums": [8], "form": "單題", "img": "img/zk110-08.png", "source": "國學常識：元明清文學", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "郁離子", "m": "劉基所著寓言體散文集"}, {"w": "獨抒性靈，不拘格套", "m": "公安派袁宏道的文學主張"}, {"w": "情至觀", "m": "湯顯祖主張至情可超越生死"}, {"w": "原君", "m": "黃宗羲探討君主本義的論文"}], "questions": [{"n": 8, "qtype": "單選", "stem": "下列是一段文學發展的介紹，劃底線處敘述最適當的是：", "options": {"A": "《郁離子》運用故事呈現其政治主張，形式承襲《世說新語》，屬志人筆記小說", "B": "〈晚遊六橋待月記〉上繼〈黃州快哉亭記〉的小品形式，詳述當日遊蹤", "C": "《牡丹亭》透過女性嚮往愛情的故事，呈現反禮教的思想，為其理論的實踐", "D": "〈原君〉推究設立君主制度的本義，可視為對心學的批判"}, "answer": "C", "explain": "(C)正確：湯顯祖主張「情至」，《牡丹亭》寫杜麗娘為愛而死、又為愛復生，追求自主愛情、反抗禮教，是他理論的實踐。\n(A)錯：《郁離子》是寓言體散文，承襲先秦諸子寓言，不是《世說新語》那種記錄人物言行的志人小說。\n(B)錯：〈晚遊六橋待月記〉是晚明小品，重在抒發性靈情趣，並沒有詳述遊蹤；〈黃州快哉亭記〉是唐宋古文家的亭臺記，也不是它的上承來源。\n(D)錯：〈原君〉批判的是君主專制「以天下為私」，不是批判心學。", "skill": "文學史題記「作家—主張—代表作—文類」四格，選項只要有一格配錯就刪。"}], "difficulty": "中", "label": "110指考", "year": 110, "kind": "指考", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "世說新語選、郁離子選、晚遊六橋待月記、原君"}, {"id": "zk110-09", "exam": "zk110", "nums": [9, 10], "form": "題組", "img": "img/zk110-09.png", "source": "《晏子春秋‧內篇問上》", "author": "", "genre": "經典語錄", "types": ["文意推論", "主旨寓意"], "passage": "景公問於晏子曰：「忠臣之事君也何若？」晏子對曰：「有難不死，出亡不送。」公不說，曰：「君裂地而封之，疏爵而貴之，君有難不死，出亡不送，可謂忠乎？」對曰：「言而見用，終身無難，臣奚死焉；謀而見從，終身不出，臣奚送焉。若言不用，有難而死之，是妄死也；謀而不從，出亡而送之，是詐偽也。故忠臣也者，＿＿＿＿。」", "translation": "齊景公問晏子：「忠臣事奉君主應該怎樣？」晏子回答：「君主有危難不為他死，君主出逃不去送他。」景公不高興，說：「君主分割土地封給他，分封爵位使他尊貴，君主有難卻不為他死，出逃也不送，可以說是忠嗎？」晏子回答：「臣子的話如果被採用，君主一輩子都不會有危難，臣子何必去死；臣子的謀略如果被聽從，君主一輩子不會出逃，臣子何必去送。如果臣子的話不被採用，君主有難時為他而死，這是白白送死；謀略不被聽從，君主出逃時去送他，這是虛偽。所以忠臣，是＿＿＿＿。」", "keywords": [{"w": "出亡", "m": "逃亡國外"}, {"w": "說", "m": "通「悅」"}, {"w": "裂地", "m": "分割土地"}, {"w": "疏爵", "m": "分封爵位"}, {"w": "奚", "m": "何、為什麼"}, {"w": "妄死", "m": "白白送死"}], "questions": [{"n": 9, "qtype": "單選", "stem": "下列敘述，最適合做為本文結語的是：", "options": {"A": "言說不見用，終身不仕以持節", "B": "策謀不見從，不惜死生以直諫", "C": "能獻策諫言，不忍見君獨赴難", "D": "能納善於君，不能與君陷於難"}, "answer": "D", "explain": "晏子的邏輯是：忠臣的價值在於讓君主採納好的言論和謀略，使君主不陷入危難；如果君主不聽，臣子陪著死、陪著逃都沒有意義。所以結語是(D)「能納善於君，不能與君陷於難」。\n(A)晏子沒有說不被採用就終身不仕。\n(B)晏子認為「有難而死之，是妄死」，不主張不惜生死。\n(C)晏子說君主出亡「不送」，與「不忍見君獨赴難」相反。", "skill": "結語填空，找出前文反覆出現的對照（言用→無難；言不用→死是妄死），結語就是把它濃縮。"}, {"n": 10, "qtype": "單選", "stem": "若將現代職場的上下關係，想像、對應於文中的君臣關係，下列上司與下屬的態度或作為，最符合晏子看法的是：", "options": {"A": "上司：照顧員工，提供良善工作環境／下屬：能為主管涉風險，一旦出事不頂罪", "B": "上司：身先士卒，提振團隊工作效率／下屬：上下一體無分別，誓與長官同進退", "C": "上司：充分授權，讓下屬展現創造力／下屬：理念相合才盡心，道不同不相為謀", "D": "上司：接受建言，追求公司穩定發展／下屬：盡心力出謀獻策，但求問心能無愧"}, "answer": "D", "explain": "晏子的君臣關係是：君主要「言而見用、謀而見從」，國家就能穩定無難；臣子的責任是盡力進言獻策，而不是盲目陪君主赴難。(D)上司接受建言、追求穩定，下屬盡心出謀獻策、問心無愧，最符合。\n(A)晏子談的不是上司照顧員工，下屬「為主管涉風險」也不是重點。\n(B)「誓與長官同進退」就是有難同死、出亡同送，晏子認為是妄死、詐偽。\n(C)上司「充分授權」不是「納言」；下屬「道不同不相為謀」是不獻策，和晏子主張盡心進言不同。", "skill": "古今對應題，先把古文關係寫成「上位者該做什麼／下位者該做什麼」兩欄，再逐欄比對選項。"}], "difficulty": "中", "label": "110指考", "year": 110, "kind": "指考", "textcat": "學術文本", "textcat2": "生活情境文本", "linked_core": ""}, {"id": "zk110-12", "exam": "zk110", "nums": [12, 13, 14, 15], "form": "題組", "img": "img/zk110-12.png", "source": "選項詩句：(C)盧仝〈有所思〉、(D)元稹〈離思〉，(A)(B)出處待查", "author": "", "genre": "古典詩詞曲", "types": ["人物情感", "詩詞賞析"], "passage": "(A)人間莫謾惜花落，花落明年依舊開\n(B)花樹不隨人寂寞，數枝猶自出牆來\n(C)相思一夜梅花發，忽到窗前疑是君\n(D)取次花叢懶回顧，半緣修道半緣君", "translation": "(A)人間不要白白可惜花落，花落了明年還會照樣開。\n(B)花樹不會跟著人一起寂寞，仍有幾枝自顧自地伸出牆外開放。\n(C)相思了一整夜，梅花開了，梅影忽然到了窗前，還以為是你來了。\n(D)經過花叢也懶得回頭看，一半是因為修道，一半是因為你。", "keywords": [{"w": "謾", "m": "徒然、白白"}, {"w": "猶自", "m": "仍然獨自"}, {"w": "取次", "m": "隨便、經過"}], "questions": [{"n": 12, "qtype": "單選", "stem": "下列關於文中人物的敘述，最不適當的是：", "options": {"A": "王玉英始終未曾察覺李小龍對她的關注", "B": "李小龍對於王玉英的婚嫁結果深感不平", "C": "王玉英雖知錢老五聲名不佳，仍願託付終身", "D": "錢老五婚前經常在家中招待朋友，出手闊綽"}, "answer": "D", "explain": "本題選「最不適當」。(D)文中說錢老五「手頭並不寬裕」「成天不在家，門老是鎖著」，沒有在家中招待朋友、出手闊綽的描寫，所以不適當。\n(A)全文都是李小龍在看王玉英，看不出王玉英察覺他的關注，適當。\n(B)結尾「他很氣憤」，適當。\n(C)王玉英聽到傳聞「不怎麼難過」，相信嫁過去他會改好，仍願託付終身，適當。", "skill": "人物敘述題逐一回原文找證據；找不到證據、或與原文細節矛盾的就是錯的。"}, {"n": 13, "qtype": "單選", "stem": "文中第二段劃底線處描寫晚飯花的文字，同時兼寫王玉英、李小龍二人的心緒。其中「非常熱鬧，但又很淒清」所暗示的意思，最適當的詮釋是：", "options": {"A": "王玉英正值花樣年華但心境已老／李小龍對王玉英情感強烈卻壓抑", "B": "王玉英心懷渴望但只能守分靜候／李小龍憤於王玉英的際遇卻無奈", "C": "王玉英心懷渴望但只能守分靜候／李小龍對王玉英情感強烈卻壓抑", "D": "王玉英正值花樣年華但心境已老／李小龍憤於王玉英的際遇卻無奈"}, "answer": "C", "explain": "晚飯花「使勁地往外開，發瘋一樣，喊叫著」是熱鬧，暗示王玉英青春的渴望與李小龍強烈的情感；「沒有一點聲音」是淒清，暗示王玉英只能坐在照不進太陽的天井做針線、守分等待，李小龍也只能默默看著。所以是(C)。\n(A)(D)王玉英正值青春、心懷期待，沒有「心境已老」。\n(B)(D)李小龍「憤於際遇」是在王玉英出嫁之後，第二段時還沒發生。", "skill": "寫景兼寫人時，把景物的兩面（熱鬧／淒清）分別對應到人物的「內心」與「處境」。"}, {"n": 14, "qtype": "單選", "stem": "依據文意，下列文句的詮釋，最適當的是：", "options": {"A": "王玉英就坐在這個狹長的天井裡──王玉英深居簡出，對外界漠不關心", "B": "要是沒有王玉英，黃昏就不成其為黃昏了──只有李小龍才能窺見王玉英在暮色中的美麗身影", "C": "（王玉英）看看兩邊沒有人，也曾經扒在門縫上往裡看──王玉英不想被人知道自己在意錢老五", "D": "只看見一個背影。她頭上戴著紅花──王玉英最終選擇離開錢老五，活出了自己的價值"}, "answer": "C", "explain": "(C)正確：王玉英先「看看兩邊沒有人」才扒門縫往裡看，表示她在意錢老五，又不想被人知道。\n(A)錯：她坐在天井做針線是家居生活，文中沒有對外界漠不關心的意思。\n(B)錯：這句是說王玉英對李小龍的黃昏很重要，不是說只有李小龍才看得到她。\n(D)錯：她已嫁給錢老五，在他家門前淘米、頭戴紅花，並沒有離開錢老五。", "skill": "細節詮釋題，留意動作前的小動作（看看兩邊沒有人），往往就是人物心理的線索。"}, {"n": 15, "qtype": "單選", "stem": "文末以「晚飯花還在開著」寓託李小龍的心境。下列詩句與其心境最相近的是：", "options": {"A": "人間莫謾惜花落，花落明年依舊開", "B": "花樹不隨人寂寞，數枝猶自出牆來", "C": "相思一夜梅花發，忽到窗前疑是君", "D": "取次花叢懶回顧，半緣修道半緣君"}, "answer": "B", "explain": "王玉英嫁走了，巷子裡看不見她，可是「晚飯花還在開著」——花照舊開，人卻不在了，李小龍心中寂寞失落。(B)「花樹不隨人寂寞，數枝猶自出牆來」，花不懂人的寂寞，仍自顧自地開，最相近。\n(A)勸人不必惜花落、明年還會開，是豁達安慰，不是失落。\n(C)寫一夜相思、誤以為梅影是情人來到，是熱切的思念。\n(D)寫對亡妻的專情，看到花也懶得回顧，和李小龍的心境不同。", "skill": "以景寓情題，先說出「景」和「人」的對比（花在、人不在），再找詩句中同樣的對比。"}], "difficulty": "中", "label": "110指考", "year": 110, "kind": "指考", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "zk110-16", "exam": "zk110", "nums": [16, 17], "form": "題組", "img": "img/zk110-16.png", "source": "《金粟詞話》、《介存齋論詞雜著》、《樂府餘論》、《藝概》；軼聞見宋人筆記", "author": "", "genre": "說理議論", "types": ["文意推論", "比較閱讀", "文化常識"], "passage": "甲、柳七亦自有唐人妙境，今人但從淺俚處求之，遂使金荃蘭畹之音，流入挂枝黃鶯之調，此學柳之過也。（《金粟詞話》）\n乙、耆卿樂府多，故惡濫可笑者多，使能珍重下筆，則北宋高手也。（《介存齋論詞雜著》）\n丙、柳詞曲折委婉，而中具渾淪之氣，雖多俚語，而高處足冠群流。（《樂府餘論》）\n丁、耆卿詞細密而妥溜，明白而家常，善於敘事，有過前人，惟綺羅香澤之態，所在多有，故覺風期未上耳。（《藝概》）", "translation": "甲、柳永的詞自有唐人的美妙境界，現在的人只從淺俗的地方去學他，於是使高雅的詞作，流為通俗小曲的腔調，這是學柳永的人的錯。\n乙、柳永的詞作很多，所以粗濫可笑的也多；如果他能慎重下筆，就是北宋的高手了。\n丙、柳永的詞曲折委婉，內在卻有渾厚完整的氣勢，雖然多用俚俗語，但好的作品足以冠絕群倫。\n丁、柳永的詞細密而流暢妥貼，明白又貼近日常，擅長敘事，超過前人；只是描寫綺羅脂粉的豔情處處都有，所以讓人覺得格調不夠高。", "keywords": [{"w": "金荃蘭畹", "m": "指高雅的詞集（《金荃集》《蘭畹集》）"}, {"w": "挂枝黃鶯", "m": "民間通俗小曲"}, {"w": "樂府", "m": "此指詞"}, {"w": "渾淪", "m": "渾厚完整"}, {"w": "妥溜", "m": "妥貼流暢"}, {"w": "風期未上", "m": "格調不高"}], "questions": [{"n": 16, "qtype": "單選", "stem": "下表為上引評論資料的歸納、分類，最符合原評論對柳詞的敘述是：", "options": {"A": "甲／正面評價：佳者有唐人妙境／負面評價：劣者不免淺俚如掛枝黃鶯", "B": "乙／正面評價：詩作為北宋高手／負面評價：樂府多惡濫可笑", "C": "丙／正面評價：曲折委婉、佳篇技壓群賢／負面評價：多用俚語、有失渾淪之氣", "D": "丁／正面評價：敘事佳且文詞細密明白／負面評價：詞風柔靡而格調不足"}, "answer": "D", "explain": "(D)正確：丁說柳詞「細密而妥溜，明白而家常，善於敘事」是正面；「綺羅香澤之態，所在多有，故覺風期未上」是說豔情多、格調不高，負面歸納正確。\n(A)錯：甲批評的是「今人」只學柳詞淺俚處，是「學柳之過」，不是說柳詞本身劣者淺俚。\n(B)錯：「樂府」指詞而不是詩；而且「使能珍重下筆，則北宋高手也」是假設語氣，表示他還不算高手。\n(C)錯：丙說柳詞「中具渾淪之氣」，是稱讚，不是「有失渾淪之氣」。", "skill": "評論題特別注意「主詞」（是柳永還是學柳的人）和「語氣」（使能……則……是假設，不是事實）。"}, {"n": 17, "qtype": "單選", "stem": "《藝概》評論柳永詞「綺羅香澤之態，所在多有」，下列關於柳永的軼聞，最適合用來說明其原因的是：", "options": {"A": "仁宗頗好其詞，每對酒，必使侍從歌之再三", "B": "居京華，暇日遍遊妓館。所至，妓者愛其有詞名，能移宮換羽", "C": "善為歌辭，教坊樂工每得新腔，必求永為辭，始行於世，於是聲傳一時", "D": "詣政府，晏公（殊）曰：「賢俊作曲子麼？」三變曰：「只如相公亦作曲子。」"}, "answer": "B", "explain": "「綺羅香澤之態」指柳詞多寫歌妓、男女情愛的脂粉題材。(B)柳永在京城常遊妓館，歌妓喜愛他的詞名，最能說明他為何多寫這類內容。\n(A)仁宗喜歡他的詞，說明的是詞作流行、受賞識。\n(C)樂工求他填詞，說明的是他精通音律、作品流傳廣。\n(D)晏殊問他作不作曲子，是兩人對詞的態度對話，與綺羅香澤的成因無關。", "skill": "找「原因」時，先把評語換成具體內容（綺羅香澤＝豔情題材），再找能產生這種內容的生活經歷。"}], "difficulty": "中", "label": "110指考", "year": 110, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk110-21", "exam": "zk110", "nums": [21, 22, 23], "form": "題組", "img": "img/zk110-21.png", "source": "王若虛《滹南遺老集》、鄭用錫〈勸和論〉、陳肇興〈械鬥竹枝詞〉", "author": "", "genre": "說理議論", "types": ["寫作手法", "比較閱讀"], "passage": "丙　作史與他文不同。寧失之質，不可至於蕪靡而無實；寧失之繁，不可至於疏略而不盡。宋子京不識文章正理，而惟異之求，肆意雕鐫，無所顧忌，以至字語詭僻，殆不可讀，其事實則往往不明，或乖本意。（王若虛《滹南遺老集》）\n丁　自分類興，而元氣剝削殆盡，未有如去年之甚也！干戈之禍愈烈，村市半成邱墟。問為漳、泉而至此乎？無有也。問為閩、粵而至此乎？無有也。蓋孽由自作，釁起鬩牆，大抵在非漳泉、非閩粵間耳。（鄭用錫〈勸和論〉）\n戊　淡水環垣病最多，漳泉棍棒粵閩戈。因牛為水芝麻釁，一鬥經年血漲河。（陳肇興〈械鬥竹枝詞〉）", "translation": "丙　寫史書和寫其他文章不同。寧可失於質樸，也不可以浮華而不實在；寧可失於繁瑣，也不可以疏略而不完整。宋祁不懂文章的正理，只追求新奇，任意雕琢，毫無顧忌，以致字句怪異偏僻，幾乎讀不下去，所記的事實往往不清楚，有時還違背原意。\n丁　自從（族群）分類興起，臺灣的元氣幾乎被削弱殆盡，沒有像去年那麼嚴重的！戰禍越來越激烈，村莊市鎮一半成了廢墟。問是為了漳州、泉州的分別才到這地步嗎？不是。問是為了福建、廣東的分別才到這地步嗎？也不是。其實是罪孽由自己造成，爭端起於兄弟內鬨，大概就發生在不分漳泉、不分閩粵的人之間罷了。\n戊　淡水城一帶的弊病最多，漳州、泉州人拿棍棒，廣東、福建人動刀戈。為了牛、為了水這種芝麻小事起爭端，一打就是一整年，血流成河。", "keywords": [{"w": "蕪靡", "m": "雜亂浮華"}, {"w": "疏略", "m": "粗疏簡略"}, {"w": "雕鐫", "m": "雕琢"}, {"w": "詭僻", "m": "怪異偏僻"}, {"w": "分類", "m": "清代臺灣依祖籍分類的族群械鬥"}, {"w": "鬩牆", "m": "兄弟在家中爭吵，比喻內鬨"}, {"w": "釁", "m": "爭端"}], "questions": [{"n": 21, "qtype": "單選", "stem": "依據甲、乙二表，下列關於華巧的敘述，最適當的是：", "options": {"A": "華巧來自於形式雕繪，與內容無關", "B": "修辭手法始於華巧，終於寧拙毋巧", "C": "欲強化讀者感受，不能不追求華巧", "D": "有華巧未必精確，有精確自有華巧"}, "answer": "C", "explain": "(C)正確：甲表中，藝術修辭的目的是「使人感受」，表現是「華巧」，所以要強化讀者感受，就要追求華巧。\n(A)錯：甲表說辭格是「內容與形式的綜合運用」，華巧不只來自形式。\n(B)錯：表中沒有「始於華巧，終於寧拙毋巧」的說法。\n(D)錯：乙表說抒情要「華巧而不失精確」，可見華巧和精確要兼顧，但不能推出「有精確自有華巧」。", "skill": "圖表題先橫著讀（同一列：手法→內涵→目的→表現），選項的因果要能在同一列找到。"}, {"n": 22, "qtype": "單選", "stem": "參照甲表，關於丙文對宋祁（子京）修史的批評，說明最適當的是：", "options": {"A": "一旦追求藝術修辭，必將損及規範修辭", "B": "規範修辭易失之質，藝術修辭易失之繁", "C": "藝術修辭常致詭僻，唯才高者方能駕馭", "D": "寫作應先認清目的，不宜忽略規範修辭"}, "answer": "D", "explain": "丙文說「作史與他文不同」，寧可質樸、繁瑣，也不能不實、不完整；批評宋祁只求新奇、雕琢，導致事實不明。對照甲表：史書應以「意義明白，條理清晰」的規範修辭為主，宋祁卻忽略了它，所以(D)「寫作應先認清目的，不宜忽略規範修辭」最適當。\n(A)「一旦……必將」說得太絕對，丙文只批評宋祁的過度雕琢。\n(B)丙文的「寧失之質」「寧失之繁」都是作史可接受的缺點，不是分屬兩種修辭的毛病。\n(C)丙文沒有說才高者才能駕馭藝術修辭。", "skill": "把文言批評翻成「他錯在哪、應該怎樣」兩句，再拿去對照表格的分類名稱。"}, {"n": 23, "qtype": "單選", "stem": "依據甲、乙二表，關於丁、戊二文的分析，最不適當的是：", "options": {"A": "丁的自問自答屬於辭格", "B": "丁以表達作者的認知為主", "C": "戊單用抒情的表述方式", "D": "戊的押韻屬形式修辭手法"}, "answer": "C", "explain": "本題選「最不適當」。(C)戊詩除了抒發痛心，也陳述了「漳泉棍棒粵閩戈」「因牛為水芝麻釁，一鬥經年」等械鬥的事實，兼有說明，不是「單用抒情」，所以不適當。\n(A)丁「問為漳、泉而至此乎？無有也」是自問自答（設問），屬於辭格，適當。\n(B)丁主要在說明分類械鬥的禍害與真正原因，以表達認知為主，適當。\n(D)戊是竹枝詞，押韻屬於音調格律，是辭趣、形式的修辭手法，適當。", "skill": "判斷「表述方式」：有交代人事物或因果的就是說明，有表達感受的就是抒情，一篇常兼用。"}], "difficulty": "難", "label": "110指考", "year": 110, "kind": "指考", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "勸和論"}, {"id": "zk110-24", "exam": "zk110", "nums": [24, 25], "form": "題組", "img": "img/zk110-24.png", "source": "《韓非子‧說難》", "author": "韓非", "genre": "說理議論", "types": ["文意推論", "典故出處", "比較閱讀"], "passage": "凡說之難，非吾知之有以說之之難也，又非吾辯之能明吾意之難也，又非吾敢橫佚而能盡之難也。凡說之難，在知所說之心，可以吾說當之。", "translation": "遊說的困難，不在於我的知識足以用來遊說的困難，也不在於我的口才能否清楚表達我的意思的困難，也不在於我敢不敢毫無顧忌地把話說盡的困難。遊說真正的困難，在於了解被遊說者的心理，使我的說辭能切合它。", "keywords": [{"w": "說", "m": "遊說"}, {"w": "辯", "m": "口才"}, {"w": "橫佚", "m": "縱橫奔放，毫無顧忌"}, {"w": "所說", "m": "被遊說的人"}, {"w": "當", "m": "切合"}], "questions": [{"n": 24, "qtype": "單選", "stem": "依據上文，說服過程中最困難的是：", "options": {"A": "善用言辭以明確表達觀點", "B": "堅持無所顧忌的直言態度", "C": "掌握對方的心理進行遊說", "D": "運用所知達到遊說的目的"}, "answer": "C", "explain": "韓非連用三個「非……之難也」排除知識、口才、膽量，最後說「凡說之難，在知所說之心，可以吾說當之」，所以最難的是(C)掌握對方心理進行遊說。\n(A)是「吾辯之能明吾意」，(B)是「吾敢橫佚而能盡」，(D)是「吾知之有以說之」，都被韓非說成不是真正的難處。", "skill": "「非A也，非B也，在C」的句型，答案永遠是C。"}, {"n": 25, "qtype": "單選", "stem": "依據上文，關於○1、○2的研判，最適當的是：\n○1燭之武對秦伯說：「若亡鄭而有益於君，敢以煩執事」，運用了「吾知之有以說之」與「知所說之心，可以吾說當之」。\n○2馮諼對梁惠王說：「齊放其大臣孟嘗君於諸侯，諸侯先迎之者，富而兵強」，運用了「吾辯之能明吾意」與「吾敢橫佚而能盡」。", "options": {"A": "○1、○2皆正確", "B": "○1、○2皆錯誤", "C": "○1正確，○2錯誤", "D": "○1錯誤，○2正確"}, "answer": "C", "explain": "○1正確：燭之武了解局勢（知之），又抓住秦伯在乎秦國利益的心理，說「滅鄭如果對您有利，就勞煩您吧」，以退為進，正是知所說之心。\n○2錯誤：馮諼說「先迎孟嘗君的諸侯就能富強」，是抓住梁惠王想要富國強兵的心理，屬於「知所說之心」，重點不在口才或敢說。所以選(C)。", "skill": "判斷遊說技巧，先問「這句話是衝著對方的什麼需求說的」，能對上需求就是知所說之心。"}], "difficulty": "中", "label": "110指考", "year": 110, "kind": "指考", "textcat": "延伸", "textcat2": "學術文本", "linked_core": "燭之武退秦師"}, {"id": "zk110-28", "exam": "zk110", "nums": [28, 29, 30, 31, 32], "form": "題組", "img": "img/zk110-28.png", "source": "《禮記‧禮運》、衛湜《禮記集說》引陳祥道說", "author": "", "genre": "經典語錄", "types": ["虛詞句式", "文意推論", "比較閱讀"], "passage": "甲　今大道既隱，天下為家，各親其親，各子其子，貨力為己。大人世及以為禮，城郭溝池以為固，禮義以為紀；以正君臣，以篤父子，以睦兄弟，以和夫婦，以設制度，以立田里，以賢勇知，以功為己。故謀用是作，而兵由此起。（ㄅ）禹、湯、文、武、成王、周公，由此其選也。（ㄆ）此六君子者，未有不謹於禮者也。（ㄇ）以著其義，以考其信，著有過，刑仁講讓，示民有常。（ㄈ）如有不由此者，在埶者去，眾以為殃。是謂小康。（《禮記‧禮運》）〔清代孫希旦認為「故謀用是作，而兵由此起」應前移至「貨力為己」之後〕\n乙　夫大道之行，天下為公而與人；大道既隱，天下為家而與子。與人、與子固出於天，聖人所以順天而趨時也。然其為公者非不家之，以為公者為主；為家者非不公之，以為家者為主。至於不獨親其親，不獨子其子，貨力不必藏於己，非無所別也；各親其親，各子其子，貨力為己，非無以待人也，亦其所為主者異矣。選賢與能，講信脩睦，六君子非不由之；禮義以為紀，堯舜非不用之；特其有所輕重淺深，煩簡之不一耳。蓋上世之選賢，則一於德而已；後世之選賢，則有及於勇知。上世之信，則出於精誠之中；而後世之信，則見於作誓作會之際。上世之睦，則和光同塵而有餘；後世之睦，則魚沫呴濡而不足。上世則有道德以為綱，而不止於禮義之紀；後世則禮義以為紀，而有失於道德之綱也。（衛湜《禮記集說》引陳祥道說）", "translation": "甲　如今大道已經隱沒，天下成為一家所有，人們各自親愛自己的親人、慈愛自己的子女，財物和勞力都為自己。諸侯世代相傳成為禮制，用城牆護城河作為鞏固，用禮義作為綱紀；用來端正君臣、使父子親厚、使兄弟和睦、使夫婦和諧，用來設立制度、劃定田地住所，用來尊重有勇有智的人，把功勞歸於自己。所以陰謀因此產生，戰爭也由此而起。禹、湯、文王、武王、成王、周公，因此成為傑出的人物。這六位君子，沒有不謹守禮的。用禮來彰明百姓的道義，考察百姓的誠信，揭露過錯，以仁為法則、講求謙讓，向百姓昭示常法。如果有不遵行禮的，即使是在位掌權者也要被罷免，百姓把他當作禍害。這就叫做小康。\n乙　大道實行的時候，天下為公，所以傳位給賢人；大道隱沒後，天下成為一家所有，所以傳位給兒子。傳賢、傳子本來都出於天意，是聖人順應天意、配合時勢的做法。然而天下為公的時代並不是不顧家，只是以公為主；天下為家的時代也不是不顧公，只是以家為主。至於不只親愛自己的親人、不只慈愛自己的子女，財物不必藏在自己家，並不是沒有親疏之別；各自親愛自己的親人、子女，財物勞力為自己，也不是沒有對待別人的心，只是兩個時代所重視的主次不同罷了。選拔賢能、講求誠信和睦，六君子並不是不遵行；以禮義為綱紀，堯舜也不是不用；只是有輕重深淺、繁簡的不同而已。上古選拔賢人只看德行；後世選賢則還考慮勇敢和智慧。上古的誠信出自內心的真誠；後世的誠信則表現在立誓、盟會的時候。上古的和睦是與世相融、無爭而綽綽有餘；後世的和睦則像魚用口沫互相濕潤，仍感不足。上古以道德為總綱，而不只限於禮義的規範；後世以禮義為規範，卻失去了道德的總綱。", "keywords": [{"w": "世及", "m": "世襲（父傳子為世，兄傳弟為及）"}, {"w": "紀", "m": "綱紀、規範"}, {"w": "由此其選", "m": "因此而成為傑出人物"}, {"w": "埶", "m": "通「勢」，權位"}, {"w": "殃", "m": "禍害"}, {"w": "與人、與子", "m": "傳位給賢人、傳位給兒子"}, {"w": "和光同塵", "m": "收斂光芒、混同於世"}, {"w": "魚沫呴濡", "m": "魚在乾涸處吐沫互相濕潤（相濡以沫）"}], "questions": [{"n": 28, "qtype": "單選", "stem": "關於甲文的解說，最不適當的是：", "options": {"A": "ㄅ句與ㄈ句的「此」，均指「禮義」或「禮」", "B": "ㄆ句補充說明ㄅ句，強調「六君子」共通處", "C": "ㄇ句的「其」，均指ㄆ句的「六君子」", "D": "ㄈ句藉假設情境，凸顯「禮」是評判依據"}, "answer": "C", "explain": "本題選「最不適當」。(C)ㄇ句「以著其義，以考其信」是說用禮來彰明百姓的道義、考察百姓的誠信，後面接「示民有常」，「其」指的是百姓（民），不是六君子，所以不適當。\n(A)ㄅ「由此其選」、ㄈ「如有不由此者」的「此」都指禮義、禮，適當。\n(B)ㄆ「此六君子者，未有不謹於禮者也」補充說明六君子的共同點是謹守禮，適當。\n(D)ㄈ「如有不由此者……眾以為殃」用假設說明不守禮的後果，凸顯禮是評判標準，適當。", "skill": "代詞「其、此」的指涉，往後讀到句子結束找呼應的名詞（示「民」有常），常比往前找更準。"}, {"n": 29, "qtype": "單選", "stem": "關於孫希旦移動文句的原因，下列○1、○2兩項推論，最適當的是：\n○1使「謀作」、「兵起」肇因於世人以私利為先。\n○2讓「謀作」、「兵起」做為實行禮制的原因，而非實行禮制的結果。", "options": {"A": "○1、○2皆正確", "B": "○1、○2皆錯誤", "C": "○1正確，○2錯誤", "D": "○1錯誤，○2正確"}, "answer": "A", "explain": "把「故謀用是作，而兵由此起」移到「貨力為己」之後，意思就變成：因為人人為己（私利），所以產生陰謀戰爭，○1正確。接著才說「大人世及以為禮……禮義以為紀」，禮制成了為了應付謀作兵起而設立的，也就是禮制的原因而不是禮制造成的結果，○2正確。所以選(A)。", "skill": "文句移位題，把句子放到新位置後重新讀一遍，看「故」字前後的因果關係變成什麼。"}, {"n": 30, "qtype": "單選", "stem": "乙文「上世之睦，則和光同塵而有餘；後世之睦，則魚沫呴濡而不足」意謂：", "options": {"A": "上世自足而相融無爭，後世互持仍時感困窘", "B": "上世君子超塵而拔俗，後世小人貪求而無饜", "C": "上世之養民無微不至，後世之勞民竭澤而漁", "D": "上世以道家精神為尚，後世距儒家理想益遠"}, "answer": "A", "explain": "「和光同塵」是收斂光芒、與人融合無爭；「有餘」是綽綽有餘。「魚沫呴濡」是魚在乾涸處吐沫互相濕潤，互相扶持仍然困窘；「不足」是不夠。所以(A)「上世自足而相融無爭，後世互持仍時感困窘」正確。\n(B)文中沒有君子、小人的對比。\n(C)談的是人與人的和睦，不是養民或勞民。\n(D)陳祥道是說主次輕重不同，不是儒道之分。", "skill": "遇到成語典故（相濡以沫），先想它的畫面，再把畫面翻成抽象意思。"}, {"n": 31, "qtype": "單選", "stem": "下列示意圖，最接近乙文觀點的是：", "options": {"A": "上世對天下繼承的態度（長條圖：與人高，與子無）", "B": "後世的社會安定之道（長條圖：禮義高，道德低）", "C": "後世的人們相處原則（長條圖：各親其親低，不獨親其親高）", "D": "上世的選賢所重條件（長條圖：德高，勇知低）"}, "answer": "B", "explain": "(B)正確：乙文說「後世則禮義以為紀，而有失於道德之綱」，後世重禮義、輕道德，圖示禮義高、道德低相符。\n(A)錯：陳祥道說「為公者非不家之，以為公者為主」，上世仍有與子的成分，不是完全沒有。\n(C)錯：後世是「各親其親」為主，圖示卻是各親其親低、不獨親其親高，說反了。\n(D)錯：上世選賢「一於德而已」，只看德行，不應有勇知的成分。", "skill": "示意圖題先確認圖的主角（上世還是後世），再用原文的「為主／而已／不止」判斷高低比例。"}, {"n": 32, "qtype": "單選", "stem": "孫希旦與陳祥道皆透過深度閱讀，對《禮記》原文提出新見。下列敘述，最符", "options": {"A": "孫希旦：後世治亂有合理演變／陳祥道：上世與後世皆因時制宜", "B": "孫希旦：後世治亂有合理演變／陳祥道：上世與後世皆積久弊生", "C": "孫希旦：後世明主應天下為公／陳祥道：上世與後世皆因時制宜", "D": "孫希旦：後世明主應天下為公／陳祥道：上世與後世皆積久弊生"}, "answer": "A", "explain": "孫希旦移動文句後，變成「人人為己→謀作兵起→聖人制禮來因應」，後世的亂與治是一步步合理演變而來。陳祥道說傳賢、傳子「固出於天，聖人所以順天而趨時」，上世、後世只是主次輕重不同，都是順應時勢的做法，也就是因時制宜。所以選(A)。\n(C)(D)孫希旦沒有主張後世明主應恢復天下為公。\n(B)(D)陳祥道並沒有說兩個時代都積久生弊。", "skill": "比較兩家說法，先各找一個關鍵句（順天而趨時），把它翻成四字概念再對選項。"}], "difficulty": "難", "label": "110指考", "year": 110, "kind": "指考", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "大同與小康"}, {"id": "zk110-33", "exam": "zk110", "nums": [33, 34], "form": "題組", "img": "img/zk110-33.png", "source": "〈眾惡之，必察焉。眾好之，必察焉〉（作者待查）", "author": "", "genre": "說理議論", "types": ["寫作手法", "主旨寓意"], "passage": "今之好惡者，多不免於因人，而尤易於附眾，不知眾人有眾人之好惡焉，而我亦自有我之好惡焉。使茍而同於眾，是我遂無好惡也，惟舉而試為察，則我故自有好惡也。\n察者不因眾而起信，豈因眾而起疑？獨彼所為瑕瑜失得之端，亦必嘗親見之，而後愛憎之意得緣而有所出，不然，則未知夫所曹好曹惡之為何事也。\n既無意於徇眾，豈有意於矯眾？獨彼所為積毀積譽之實，亦必嘗微得之，而後妍媸之意始因而有所生，不然，則未知夫所受好受惡之為何本也。\n故即眾人之惡自真，吾惡眾人之惡自妄，察則彼此皆真矣。即眾人之好自確，吾好眾人之好自浮，察則人我皆確矣。", "translation": "現在人們的喜好和厭惡，大多免不了跟著別人，尤其容易附和眾人，不知道眾人有眾人的好惡，而我也有我自己的好惡。如果隨便跟眾人一樣，那我就沒有自己的好惡了；只要拿來試著親自察看，那我本來就有自己的好惡。\n察看的人不因為眾人都說好就相信，又怎會因為眾人都這麼說就懷疑呢？只是對方的優缺點、得失的根源，一定要親眼見過，然後愛憎的心意才有依據而產生；不然，就不知道大家共同喜愛、共同厭惡的究竟是什麼事。\n既然無意順從眾人，又怎會有意故意和眾人唱反調呢？只是對方累積的毀謗、累積的讚譽的實情，一定要細細探得，然後美醜的判斷才有根據而產生；不然，就不知道大家所接受的好惡是根據什麼。\n所以即使眾人的厭惡本來是真的，我只是跟著眾人厭惡，那就是虛妄的；經過察看，彼此就都是真的了。即使眾人的喜好本來是確實的，我只是跟著眾人喜好，那就是浮泛的；經過察看，別人和我就都確實了。", "keywords": [{"w": "因人", "m": "依從別人"}, {"w": "附眾", "m": "附和眾人"}, {"w": "瑕瑜", "m": "缺點和優點"}, {"w": "曹", "m": "共同"}, {"w": "徇眾", "m": "順從眾人"}, {"w": "矯眾", "m": "故意違逆眾人"}, {"w": "妍媸", "m": "美與醜"}], "questions": [{"n": 33, "qtype": "單選", "stem": "關於上文第二、三段的說理方式，敘述最適當的是：", "options": {"A": "第二、三段平行，皆論「對於眾人之所好、所惡，都應親自明察」", "B": "第二、三段對立，先論「明察眾人之所惡」，再論「明察眾人之所好」", "C": "第二、三段是因果關係，先談「眾人有所好、有所惡」的原因，再談結果", "D": "第二、三段是總分關係，先述「眾人有所好、有所惡」的現象，再加以分論"}, "answer": "A", "explain": "第二段說「察者不因眾而起信，豈因眾而起疑」，必須親見才有愛憎；第三段說「既無意於徇眾，豈有意於矯眾」，必須細察才有美醜判斷。兩段句式對稱，都在說對眾人的好惡要親自明察，是平行關係，選(A)。\n(B)兩段不是對立，也沒有分別只談「惡」或只談「好」。\n(C)兩段沒有因果關係。\n(D)兩段沒有先總後分的結構。", "skill": "判斷段落關係，把兩段的第一句並排看：句式、意思相同就是平行，相反才是對立。"}, {"n": 34, "qtype": "單選", "stem": "下列敘述，最符合第四段看法的是：", "options": {"A": "人人皆有盲點，勿過度堅持己見", "B": "人能戒惡向善，皆可以回歸真我", "C": "縱有真知灼見，也難敵世俗觀點", "D": "若經反思驗證，固不忌好惡隨俗"}, "answer": "D", "explain": "第四段說：即使眾人的好惡是對的，我只是跟著好惡就是虛妄、浮泛；但經過「察」之後，彼此都真、人我都確。也就是說，只要經過自己察看驗證，和眾人好惡相同也無妨，選(D)。\n(A)本段不是叫人放棄己見，而是要親自察看。\n(B)本段沒有談戒惡向善、回歸真我。\n(C)本段認為經過察看就能「人我皆確」，不是真知難敵世俗。", "skill": "「即……自……，察則……」是讓步加轉折的句型，重點永遠在「察則」之後。"}], "difficulty": "難", "label": "110指考", "year": 110, "kind": "指考", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "zk110-36", "exam": "zk110", "nums": [36], "form": "單題", "img": "img/zk110-36.png", "source": "連橫〈臺灣通史序〉、范仲淹〈岳陽樓記〉、曹丕〈典論論文〉、方苞〈左忠毅公軼事〉、諸葛亮〈出師表〉、杜光庭〈虬髯客傳〉", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "", "translation": "(A)陰風怒吼，混濁的浪濤衝向天空。\n(B)文章不只一種體裁，很少有人能每種都擅長。\n(C)左公看完，就脫下貂皮外衣蓋在書生身上。\n(D)考慮事情的得失，進獻全部的忠言。\n(E)有善於相面的人想見郎君，請把他請來。", "keywords": [{"w": "稔", "m": "年"}, {"w": "排空", "m": "衝向天空"}, {"w": "備善", "m": "兼備而都擅長"}, {"w": "閱畢", "m": "看完"}, {"w": "進盡", "m": "完全進獻"}], "questions": [{"n": 36, "qtype": "多選", "stem": "「遂以十稔之間，撰成《臺灣通史》」，句中的「撰成」，「成」在動詞「撰」之後，用來補充動作的結果。下列文句「」內，屬於此種用法的是：", "options": {"A": "陰風怒號，濁浪排「空」", "B": "文非一體，鮮能備「善」", "C": "公閱「畢」，即解貂覆生", "D": "斟酌損益，進「盡」忠言", "E": "有善相者思「見」郎君，請迎之"}, "answer": "CD", "explain": "題目要找「動詞＋表結果的字」。\n(C)「閱畢」：看了而結果是「完畢」，補充動作的結果，正確。\n(D)「進盡忠言」：進獻而達到「盡」（全部），補充動作的結果，正確。\n(A)「排空」：浪濤衝向天空，「空」是動作的方向、處所，不是結果。\n(B)「備善」：各種文體都兼備而擅長，「善」不是「備」的結果。\n(E)「思見」：想要見，「見」是主要動作，「思」是表意願，不是補充結果。", "skill": "測試法：把句子說成「○○到變成△△」，說得通的才是動作結果。"}], "difficulty": "難", "label": "110指考", "year": 110, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "典論論文、出師表、虬髯客傳、岳陽樓記、左忠毅公軼事、臺灣通史序"}, {"id": "zk110-37", "exam": "zk110", "nums": [37], "form": "單題", "img": "img/zk110-37.png", "source": "荀子〈勸學〉、韓愈〈師說〉、蘇軾〈赤壁賦〉、歸有光〈項脊軒志〉、連橫〈臺灣通史序〉", "author": "", "genre": "其他", "types": ["寫作手法"], "passage": "", "translation": "", "keywords": [{"w": "銜接照應", "m": "文章前後段落的呼應、連結"}, {"w": "蓬生麻中", "m": "蓬草長在麻中間，不用扶持也會長直"}, {"w": "客踰庖而宴", "m": "客人要穿過廚房去赴宴"}], "questions": [{"n": 37, "qtype": "多選", "stem": "文章佳構多留意於銜接照應。關於下列各文的銜接照應，分析適當的是：", "options": {"A": "荀子〈勸學〉舉「蓬生麻中，不扶而直」為例，藉以闡發其後「（君子）遊必就士，所以防邪僻而近中正」的觀點", "B": "韓愈〈師說〉敘述士大夫「位卑則足羞，官盛則近諛」的態度，可與「師道之不傳也久矣」的深刻感慨相呼應", "C": "蘇軾〈赤壁賦〉描寫「水光接天」、「月出於東山之上」的景色，為其後「客亦知夫水與月乎」的議論預設開端", "D": "歸有光〈項脊軒志〉敘述家中「東犬西吠，客踰庖而宴」不分彼此的和樂情景，回應前文「居於此，多可喜」的感懷", "E": "連橫〈臺灣通史序〉指出「臺、鳳、彰、淡諸志，雖有續修，侷促一隅，無關全局」的事實，用以證明「老成凋謝，莫可諮詢；巷議街譚，事多不實」"}, "answer": "ABC", "explain": "(A)正確：「蓬生麻中，不扶而直」說明環境影響人，正好為後文「君子居必擇鄉，遊必就士」的觀點鋪路。\n(B)正確：士大夫「位卑則足羞，官盛則近諛」，恥於從師，正是師道不傳的原因，與「師道之不傳也久矣」呼應。\n(C)正確：前面寫水光、明月的景色，後文蘇軾以「客亦知夫水與月乎」展開變與不變的議論，前景為後議預設開端。\n(D)錯：「東犬西吠，客踰庖而宴」是叔伯分家後院落雜亂、各自為政的景象，呼應的是「亦多可悲」，不是和樂可喜。\n(E)錯：舊志「侷促一隅，無關全局」說明舊史範圍狹小，和「老成凋謝……事多不實」（史料難以徵求）是並列的修史困難，不是用來證明它。", "skill": "照應題先回想課文段落位置：這句在文章哪一段、那段的情感是喜還是悲，就能判斷它呼應什麼。"}], "difficulty": "中", "label": "110指考", "year": 110, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "勸學、師說、赤壁賦、項脊軒志、臺灣通史序"}, {"id": "zk110-38", "exam": "zk110", "nums": [38], "form": "單題", "img": "img/zk110-38.png", "source": "王羲之〈蘭亭集序〉、丘遲〈與陳伯之書〉、《荀子‧勸學》、《莊子‧養生主》、賈誼〈過秦論〉、司馬遷〈鴻門宴〉、劉基〈工之僑獻琴〉、郁永河〈北投硫穴記〉、黃宗羲〈原君〉、蒲松齡〈勞山道士〉", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "", "translation": "", "keywords": [{"w": "與", "m": "交往／讚許"}, {"w": "中", "m": "合乎"}, {"w": "亡", "m": "損失／逃走"}, {"w": "鼓", "m": "彈奏／鼓動托起"}, {"w": "果", "m": "果真"}], "questions": [{"n": 38, "qtype": "多選", "stem": "下列各組「」內的字，前後意義相同的是：", "options": {"A": "夫人之相「與」，俯仰一世／夫迷途知反，往哲是「與」", "B": "木直「中」繩，輮以為輪／砉然響然，奏刀騞然，莫不「中」音", "C": "秦無「亡」矢遺鏃之費，而天下諸侯已困矣／沛公今事有急，「亡」去不義", "D": "斲而為琴，弦而「鼓」之／余身乃行鑊蓋上，所賴以不陷者，熱氣「鼓」之耳", "E": "雖然，使後之為君者，「果」能保此產業，傳之無窮，亦無怪乎其私之也／道士笑曰：我固謂不能作苦，今「果」然"}, "answer": "BE", "explain": "(B)相同：「木直中繩」「莫不中音」的中都是「合乎」（合乎墨線、合乎音律）。\n(E)相同：「果能保此產業」「今果然」的果都是「果真、真的」。\n(A)不同：「人之相與」是交往；「往哲是與」是讚許。\n(C)不同：「無亡矢遺鏃之費」的亡是損失；「亡去不義」的亡是逃走。\n(D)不同：「弦而鼓之」的鼓是彈奏；「熱氣鼓之」的鼓是鼓動、托起。", "skill": "一字多義題先各自翻成白話，再看兩個白話詞能不能互換。"}], "difficulty": "中", "label": "110指考", "year": 110, "kind": "指考", "textcat": "部定古文", "textcat2": "", "linked_core": "勸學、鴻門宴、與陳伯之書、蘭亭集序、郁離子選、原君、勞山道士、裨海紀遊"}, {"id": "zk110-39", "exam": "zk110", "nums": [39], "form": "單題", "img": "img/zk110-39.png", "source": "《戰國策‧趙策》", "author": "", "genre": "史傳人物", "types": ["寫作手法", "文意推論", "人物情感"], "passage": "馮忌請見趙王，行人見之。馮忌接手免首，欲言而不敢。王問其故，對曰：「客有見人於服子者，已而請其罪。服子曰：『公之客獨有三罪：望我而笑，是狎也；談語而不稱師，是倍也；交淺而言深，是亂也。』客曰：『不然。夫望人而笑，是和也；言而不稱師，是庸說也；交淺而言深，是忠也。昔者堯見舜於草茅之中，席隴畝而蔭庇桑，陰移而授天下傳。伊尹負鼎俎而干湯，姓名未著而受三公。使夫交淺者不可以深談，則天下不傳，而三公不得也。』」趙王曰：「甚善。」馮忌曰：「今外臣交淺而欲深談，可乎？」王曰：「請奉教。」於是馮忌乃談。", "translation": "馮忌請求拜見趙王，接待賓客的官員引他晉見。馮忌拱手低頭，想說話又不敢。趙王問他原因，他回答：「有個門客把一個人引見給服子，之後服子問這人有什麼罪過。服子說：『你的這位客人有三條罪：看著我就笑，是輕慢；談話不稱引老師，是背叛師門；交情淺卻說得深，是亂來。』門客說：『不對。看著人笑，是和氣；說話不稱引老師，是平常的說法；交情淺而說得深，是忠誠。從前堯在草野之中見到舜，坐在田埂上、在桑樹蔭下談話，樹蔭還沒移動就把天下傳給了他。伊尹背著鼎和砧板去求見商湯，名字還不為人知就被任命為三公。假使交情淺的人不能深談，那麼天下就不會傳給舜，伊尹也得不到三公之位了。』」趙王說：「說得很好。」馮忌說：「現在我這外臣和您交情淺卻想深談，可以嗎？」趙王說：「請讓我聽你的指教。」於是馮忌才開始說。", "keywords": [{"w": "行人", "m": "掌管接待賓客的官員"}, {"w": "接手免首", "m": "拱手低頭"}, {"w": "見人於服子", "m": "把人引見給服子"}, {"w": "狎", "m": "輕慢"}, {"w": "倍", "m": "通「背」，背叛"}, {"w": "庸說", "m": "平常的說法"}, {"w": "干", "m": "求見"}], "questions": [{"n": 39, "qtype": "多選", "stem": "關於下列馮忌的言談方式與內容，學生評析適當的是：", "options": {"A": "馮忌先故作姿態，誘使趙王疑惑探問，以展開後續鋪陳", "B": "馮忌透過「服子與客對話」的故事，為之後與趙王暢言預埋伏筆", "C": "在服子與客的對話中，對於相同的態度和言語，客故意與服子做不同解讀，藉以諷刺服子寵信佞臣", "D": "舜見堯、伊尹見商湯的故事，強調明君樂見賢良毛遂自薦，既是客對服子的諫言，也是馮忌對趙王的期待", "E": "服子與客的對話最終暗示「囿於偏見或成俗，可能錯失賢良」，馮忌藉此對趙王形成「莫如服子一般」的壓力，也為自己創造機會"}, "answer": "ABE", "explain": "(A)正確：馮忌「欲言而不敢」，引得趙王主動「問其故」，才順勢講故事。\n(B)正確：故事的重點是「交淺而言深，是忠也」，正好為他接著說「今外臣交淺而欲深談」鋪路。\n(E)正確：故事暗示若像服子那樣拘泥成見，就會錯失賢才；趙王聽了說「甚善」，就不好意思拒絕馮忌深談。\n(C)錯：客是替被引見的人辯解，說明同樣的言行可有正面解讀，並不是諷刺服子寵信佞臣。\n(D)錯：原文是「堯見舜於草茅之中」，是堯主動見舜，不是舜去見堯；而且重點是「交淺言深也能被重用」，不是毛遂自薦。", "skill": "說話藝術題，看故事和真正要說的話之間的「接點」（交淺言深），整個鋪陳都是為了它。"}], "difficulty": "中", "label": "110指考", "year": 110, "kind": "指考", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "馮諼客孟嘗君"}, {"id": "zk110-40", "exam": "zk110", "nums": [40, 41, 42], "form": "題組", "img": "img/zk110-40.png", "source": "劉禹錫〈昏鏡詞并引〉（主文為李清筠〈酒中之米：對國文升學考試試題的一點想法〉）", "author": "劉禹錫", "genre": "古典詩詞曲", "types": ["寫作手法", "虛詞句式", "比較閱讀"], "passage": "鏡之工列十鏡於賈區，發奩而視，其一皎如，其九霧如。或曰：「良苦之不侔甚矣。」工解頤謝曰：「非不能盡良也。蓋賈之意，唯售是念。今來市者，必歷鑒周睞，求與己宜。彼皎者不能隱芒杪之瑕，非美容不合，是用什一其數也。」予感之，作〈昏鏡詞〉：\n昏鏡非美金，漠然喪其晶。陋容多自欺，謂若它鏡明。瑕疵既不見，姸態隨意生。一日四五照，自言美傾城。飾帶以紋繡，裝匣以瓊瑛。秦宮豈不重，非適乃為輕。", "translation": "磨鏡的工匠在市集陳列了十面鏡子，打開鏡匣來看，其中一面明亮清晰，九面模糊如霧。有人說：「好壞相差也太大了。」工匠笑著道謝說：「不是不能全部做好。商人的心思只想著賣出去。現在來買的人，一定會一一照遍、四處端詳，挑合自己心意的。那明亮的鏡子連細如芒尖的瑕疵都藏不住，不是容貌美的人就不合用，所以只做十分之一。」我有所感觸，作了〈昏鏡詞〉：\n昏暗的鏡子不是好銅做的，模模糊糊失去了光亮。相貌醜陋的人多會自欺，說它像別的鏡子一樣明亮。瑕疵既然看不見，美好的姿態就隨意浮現。一天照上四五次，自稱美得傾國傾城。用繡花絲帶裝飾它，用美玉裝飾鏡匣。秦宮的寶鏡難道不貴重嗎？只因為不合心意，反而被看輕了。", "keywords": [{"w": "賈區", "m": "市集"}, {"w": "奩", "m": "鏡匣"}, {"w": "皎如", "m": "明亮的樣子"}, {"w": "不侔", "m": "不相等"}, {"w": "解頤", "m": "開口而笑"}, {"w": "歷鑒周睞", "m": "一一照遍、四處端詳"}, {"w": "芒杪", "m": "芒尖，比喻極細微"}, {"w": "什一", "m": "十分之一"}, {"w": "瓊瑛", "m": "美玉"}], "questions": [{"n": 40, "qtype": "多選", "stem": "依據文意推論，符合本文看法的是：", "options": {"A": "學習國文要以能釀酒、釀蜜，轉化新生為目標，不必在意基本知識的多寡", "B": "「用教材教語文，而不是教語文教材」的主張，意近於「授人以魚，不如授人以漁」", "C": "教材是通向陌生文本的橋梁，課文可做為媒介，用以統整語文規律、建構背景知識系統", "D": "文中有（甲）、（乙）兩處標記，如欲引述「《雅堂文集》：『讀書不難，能熟為難；熟書不難，能用為難。』」做為論據，依據文意，應插入（甲）處", "E": "本題（第40題）屬於本文所謂的飯類試題"}, "answer": "BC", "explain": "(B)正確：「用教材教語文」是教會方法、規律，讓學生能遷移到陌生文本，和「授人以魚，不如授人以漁」意近。\n(C)正確：文中說教材提供示例，要教會規律與策略，「以有效遷移到陌生文本的閱讀」，教材正是通往陌生文本的橋梁。\n(A)錯：作者強調背景知識像篩網，越細密越好，並非不必在意基本知識。\n(D)錯：「讀書不難……能用為難」強調「用其所讀」，應放在（乙）處「檢驗學生是否能用其所讀」附近，而不是（甲）。\n(E)錯：本題是用課外文章考閱讀理解，依文中分類屬於「酒」類，不是「飯」類。", "skill": "引文插入題，找和引文關鍵詞（用）相同的句子，插在它旁邊。"}, {"n": 41, "qtype": "多選", "stem": "下列教育理念，可與文中孫本文的主張相應的是：", "options": {"A": "以校內課程為發端，奠定學生終身學習的基礎", "B": "以學生為學習的主體，能兼顧學生的個別需求", "C": "指導學生掌握學習方法策略，啟動自主學習力", "D": "引導學生妥善開展與自我、與他人的互動能力", "E": "協助學生應用及實踐所學，善盡國家公民責任"}, "answer": "AC", "explain": "孫本文主張「課內教授僅為指導課外自讀之預備」，國文主要功夫在課外自讀。\n(A)正確：以校內課程為起點，為課外、終身學習打基礎，相應。\n(C)正確：課內教方法策略，讓學生能自主課外自讀，相應。\n(B)錯：孫本文沒有談個別需求。\n(D)錯：沒有談人際互動能力。\n(E)錯：沒有談公民責任。", "skill": "把引文的主張改寫成一句「課內→課外」的關係，選項要能接上這個方向。"}, {"n": 42, "qtype": "多選", "stem": "關於運用教材所學理解右框文字的說明，適當的是：", "options": {"A": "與〈始得西山宴遊記〉中「不與培塿為類」相近，〈昏鏡詞〉亦運用藉物寫人手法，並隱有嘲諷之意", "B": "與〈桃花源記〉和〈桃花源詩〉的「序＋詩」形式相類，〈昏鏡詞‧引〉與〈昏鏡詞〉既能獨立閱讀，又能相互闡發", "C": "古詩文中常見「未若……」的句型，用以表示比較，如「未若柳絮因風起」。據此可推知詩中「謂若它鏡明」的「謂若」有誤，當作「未若」", "D": "〈諫太宗十思疏〉中提及「慮壅蔽」，點出障蔽會干擾我們對真實世界的認知，可與「求與己宜」、「瑕疵既不見，姸態隨意生」的內涵相連結", "E": "〈典論論文〉「審己以度人」的「以」，與〈昏鏡詞〉「飾帶以紋繡，裝匣以瓊瑛」的「以」，皆為連詞，表示順承，相當於「而」"}, "answer": "ABD", "explain": "(A)正確：柳宗元以西山「不與培塿為類」自比，是藉物寫人；〈昏鏡詞〉藉昏鏡寫自欺的醜人與迎合世俗的風氣，帶有嘲諷。\n(B)正確：引文說明寫作緣由，詩再加以發揮，和〈桃花源記〉配〈桃花源詩〉一樣，可以分開讀也能互相闡發。\n(D)正確：「慮壅蔽」是擔心被蒙蔽；人們挑「與己宜」的昏鏡，看不見瑕疵就自以為美，正是被蒙蔽而看不清真實。\n(C)錯：「謂若它鏡明」是「說它像別的鏡子一樣明亮」，文意通順，不必改成「未若」。\n(E)錯：「審己以度人」的以是連詞「而、來」；「飾帶以紋繡，裝匣以瓊瑛」的以是介詞「用」（用紋繡飾帶、用瓊瑛裝匣），不同。", "skill": "判斷原文有沒有錯字，先照原字翻譯一次，只要通順就不能說「有誤」。"}], "difficulty": "難", "label": "110指考", "year": 110, "kind": "指考", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "典論論文、桃花源記、始得西山宴遊記、諫太宗十思疏"}, {"id": "xc111-6", "exam": "xc111", "nums": [6], "form": "單題", "img": "img/xc111-6.png", "source": "杜甫〈灩澦〉、〈絕句漫興九首〉其八", "author": "杜甫", "genre": "古典詩詞曲", "types": ["詩詞賞析", "字詞解釋"], "passage": "甲、灩澦既沒孤根深，西來水多愁太陰。江天□□鳥雙去，風雨□□龍一吟。（杜甫〈灩澦〉）\n乙、舍西柔桑葉可拈，江畔細麥復□□。人生幾何春已夏，不放香醪如蜜甜。（杜甫〈絕句漫興九首〉其八）", "translation": "甲、灩澦堆已經被江水淹沒，只剩深深的根基，西邊流來的江水暴漲，讓人愁苦天色陰沉。江天一片迷濛，鳥兒成雙飛去；風雨中時時傳來像龍吟般的聲響。\n乙、屋舍西邊柔嫩的桑葉已經可以摘取，江邊的細麥也長得纖細柔美。人生能有多久？春天轉眼已到夏天，可不能放過像蜜一樣甜的美酒。", "keywords": [{"w": "灩澦", "m": "灩澦堆，長江瞿塘峽口的巨石"}, {"w": "太陰", "m": "陰沉的天色"}, {"w": "漠漠", "m": "迷濛、廣闊的樣子"}, {"w": "纖纖", "m": "細長柔美"}, {"w": "拈", "m": "用手指取"}, {"w": "香醪", "m": "美酒"}], "questions": [{"n": 6, "qtype": "單選", "stem": "閱讀下列杜詩，依據詩意與格律，□□內最適合填入的詞語依序是：", "options": {"A": "漠漠／瑟瑟／亭亭", "B": "漠漠／時時／纖纖", "C": "朗朗／時時／亭亭", "D": "朗朗／瑟瑟／纖纖"}, "answer": "B", "explain": "第一格：前句說「愁太陰」（天色陰沉），又有「風雨」，江天應是迷濛一片的「漠漠」，「朗朗」（晴朗明亮）和詩意衝突，刪C、D。第二格：「江天漠漠」對「風雨□□」，律詩對句平仄要相反，「漠漠」是仄聲，所以要填平聲的「時時」；「瑟瑟」也是仄聲，不合格律，刪A。第三格：乙詩押「拈、甜」的韻，「纖纖」同韻，又能形容細麥；「亭亭」不押韻，也不適合形容細麥。答案 漠漠／時時／纖纖，選B。", "skill": "詩句填空三步驟：先看詩意（晴或陰），再看對仗平仄，最後看韻腳。"}], "difficulty": "中", "label": "111學測", "year": 111, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc111-7", "exam": "xc111", "nums": [7], "form": "單題", "img": "img/xc111-7.png", "source": "《莊子‧逍遙遊》", "author": "莊子", "genre": "寓言故事", "types": ["文意推論", "主旨寓意"], "passage": "宋人有善為不龜手之藥者，世世以洴澼絖為事。客聞之，請買其方百金。聚族而謀曰：「我世世為洴澼絖，不過數金；今一朝而鬻技百金，請與之。」客得之，以說吳王。越有難，吳王使之將，冬與越人水戰，大敗越人，裂地而封之。", "translation": "宋國有個人很會調製防止手凍裂的藥，他家世世代代以漂洗絲絮為業。有個客人聽說了，願意出一百金買他的藥方。宋人召集全族商量說：「我們世世代代漂洗絲絮，賺的不過幾金；現在一下子就能把技術賣得百金，就賣給他吧。」客人得到藥方，拿去遊說吳王。越國來侵犯，吳王派他當將領，冬天和越人打水戰，大敗越人，吳王就割一塊地封賞他。", "keywords": [{"w": "龜", "m": "同「皸」，皮膚凍裂（音ㄐㄩㄣ）"}, {"w": "洴澼絖", "m": "漂洗絲絮"}, {"w": "鬻", "m": "賣"}, {"w": "說", "m": "遊說（音ㄕㄨㄟˋ）"}, {"w": "將", "m": "率領軍隊、當將領"}, {"w": "裂地", "m": "劃出土地"}], "questions": [{"n": 7, "qtype": "單選", "stem": "依據下文，關於不龜手之藥的敘述，最適當的是：", "options": {"A": "宋人認為它實際價格為百金", "B": "它功能單一卻帶來不同效益", "C": "越人用它來治療洴澼絖之害", "D": "吳王為爭奪它派遣軍隊攻越"}, "answer": "B", "explain": "這藥的功能只有一種——防止手凍裂；宋人用它只能漂洗絲絮、賺幾金，客人用它幫吳軍冬天水戰得勝，換來封地。同一個功能，用法不同，效益天差地遠，選B。A宋人覺得世代只賺「數金」，百金是賣價，並不認為它本來就值百金。C用藥的是吳軍，不是越人。D是「越有難」越國來犯，吳王才派客人領兵，不是為了搶藥去攻越。", "skill": "莊子寓言常有「同一件東西、不同用法」的對比，抓住對比就是主旨（善用其大）。"}], "difficulty": "易", "label": "111學測", "year": 111, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc111-8", "exam": "xc111", "nums": [8], "form": "單題", "img": "img/xc111-8.png", "source": "陳壽《三國志‧魏書‧武帝紀》", "author": "陳壽", "genre": "史傳人物", "types": ["句意理解", "文意推論"], "passage": "王（曹操）令曰：「去冬天降疫癘，民有凋傷，軍興於外，墾田損少，吾甚憂之。其令吏民男女：女年七十已上無夫子，若年十二已下無父母兄弟，及目無所見，手不能作，足不能行，而無妻子父兄產業者，廩食終身，幼者至十二止。貧窮不能自贍者，隨口給貸。老耄須待養者，年九十已上，復不事，家一人。」", "translation": "魏王曹操下令說：「去年冬天發生瘟疫，百姓有傷亡，軍隊又在外作戰，開墾的田地減少，我非常憂慮。現在命令官吏和百姓：女子七十歲以上沒有丈夫和兒子的，或十二歲以下沒有父母兄弟的，以及眼睛看不見、手不能工作、腳不能走路，又沒有妻兒父兄和產業的人，由官府供給糧食直到終老，年幼的供給到十二歲為止。貧窮到無法養活自己的，按人口借貸給他們。年老需要奉養的，九十歲以上，免除他家一個人的徭役。」", "keywords": [{"w": "疫癘", "m": "瘟疫"}, {"w": "凋傷", "m": "死傷"}, {"w": "軍興", "m": "發動戰爭"}, {"w": "已上、已下", "m": "以上、以下"}, {"w": "廩食", "m": "由官府供給糧食"}, {"w": "自贍", "m": "養活自己"}, {"w": "給貸", "m": "借貸給予"}, {"w": "復不事", "m": "免除徭役（復：免除）"}], "questions": [{"n": 8, "qtype": "單選", "stem": "依據下文，關於曹操所頒布的經濟紓困方案與背景，敘述最適當的是：", "options": {"A": "因疫癘橫行與軍隊大肆劫掠，帶來大量人民死亡，影響經濟生產甚鉅", "B": "家無財產，亦無親屬可照顧之身體殘疾者，國家將其列入需紓困對象", "C": "國家給予七十歲以上的老婦與幼兒終身照顧，後者滿十二歲即不適用", "D": "貧窮到無法自給之人與九十歲以上待養的長者，適用同樣的紓困方案"}, "answer": "B", "explain": "「目無所見，手不能作，足不能行，而無妻子父兄產業者，廩食終身」——身體殘疾、又沒有家人和產業的人，國家供糧到終老，選B。A「軍興於外」是軍隊在外打仗，不是劫掠百姓。C漏掉條件：要七十歲以上「無夫子」的婦女、十二歲以下「無父母兄弟」的孩子才適用，不是所有老婦幼兒。D貧窮者是「隨口給貸」（借糧），九十歲以上是「復不事，家一人」（免一人徭役），方案不同。", "skill": "法令類文言要把「條件」逐一圈出來，選項常故意省略條件或把兩種方案混在一起。"}], "difficulty": "中", "label": "111學測", "year": 111, "kind": "學測", "textcat": "文學文本", "textcat2": "生活情境文本", "linked_core": ""}, {"id": "xc111-12", "exam": "xc111", "nums": [12, 13], "form": "題組", "img": "img/xc111-12.png", "source": "張岱《陶庵夢憶‧自序》", "author": "張岱", "genre": "書信序跋", "types": ["文意推論", "人物情感", "主旨寓意"], "passage": "雞鳴枕上，夜氣方回，因想余生平，繁華靡麗，過眼皆空，五十年來，總成一夢。……遙思往事，憶即書之，持向佛前，一一懺悔。不次歲月，異年譜也；不分門類，別志林也。偶拈一則，如遊舊徑，如見故人、城郭、人民，翻用自喜，真所謂癡人前不得說夢矣。昔有西陵腳夫，為人擔酒，失足破其甕，念無以償，癡坐佇想曰：「得是夢便好。」一寒士鄉試中式，方赴鹿鳴宴，恍然猶意非真，自嚙其臂曰：「莫是夢否？」一夢耳，惟恐其非夢，又惟恐其是夢，其為癡人則一也。余今大夢將寤，猶事雕蟲，又是一番夢囈。", "translation": "雞叫時躺在枕上，夜晚的清氣剛剛恢復，於是回想我的一生，那些繁華奢靡，轉眼都成空，五十年來，總歸是一場夢。……遠遠回想往事，想起來就寫下，拿到佛前，一件件懺悔。不按年月排列，和年譜不同；不分類別，和志林筆記有別。偶然拿出一則來看，就像走在舊時的小路，又像見到老朋友、舊城郭、舊日的人們，反而因此暗自歡喜，真是所謂「在癡人面前不能說夢」啊。從前有個西陵的挑夫，替人挑酒，失足摔破了酒甕，想到沒錢賠，呆坐著想：「這要是一場夢就好了。」又有一個窮書生考中鄉試，正要去參加鹿鳴宴，恍恍惚惚以為不是真的，咬自己的手臂說：「莫非是夢嗎？」同樣是一場夢，一個怕它不是夢，一個怕它是夢，他們是癡人這一點是一樣的。我現在大夢就要醒了，還在做寫文章這種雕蟲小技，又是一番說夢話。", "keywords": [{"w": "靡麗", "m": "奢華"}, {"w": "不次歲月", "m": "不按年月排序"}, {"w": "翻", "m": "反而"}, {"w": "佇想", "m": "久久呆想"}, {"w": "中式", "m": "考中"}, {"w": "鹿鳴宴", "m": "鄉試放榜後宴請新科舉人的宴會"}, {"w": "嚙", "m": "咬"}, {"w": "寤", "m": "醒"}, {"w": "雕蟲", "m": "雕蟲小技，指寫作"}], "questions": [{"n": 12, "qtype": "單選", "stem": "依據上文，關於張岱撰《陶庵夢憶》，敘述最適當的是：", "options": {"A": "內容是對五十年人生的回憶", "B": "對信手拈來的寫法感到欣喜", "C": "常於深夜寫書，至雞鳴破曉時才肯擱筆", "D": "早年已悟繁華如夢，遂於書中深自懺悔"}, "answer": "A", "explain": "「五十年來，總成一夢……遙思往事，憶即書之」，書的內容就是回憶五十年人生的往事，選A。B「偶拈一則……翻用自喜」是翻看舊事、彷彿重遊故地而歡喜，不是對自己的寫法感到欣喜。C「雞鳴枕上」是醒來時回想人生，不是寫書寫到天亮。D是現在（大夢將寤）才覺悟繁華如夢，不是早年就已覺悟。", "skill": "序文題先找「寫什麼」（憶即書之）和「為何寫」，選項的時間點（早年、深夜）要特別核對。"}, {"n": 13, "qtype": "單選", "stem": "關於上文「腳夫」、「寒士」的敘述，最適當的是：", "options": {"A": "腳夫和寒士能以豁達心境待人接物", "B": "腳夫和寒士各有其專注執著的興趣", "C": "腳夫失足破甕，無法承受突發逆境，憾其非夢", "D": "寒士名落孫山，對於學識缺乏信心，疑其是夢"}, "answer": "C", "explain": "腳夫摔破酒甕賠不起，呆坐著說「得是夢便好」——承受不了突然的倒楣，遺憾它不是夢，選C。A兩人一個發呆、一個咬手臂，都談不上豁達。B文中說的是兩人對「夢」的癡想，不是興趣。D寒士是鄉試「中式」（考中了），要去參加慶功的鹿鳴宴，才會懷疑是夢，不是落榜。", "skill": "兩個例子對照時，一個「怕不是夢」、一個「怕是夢」，先把各自的處境（倒楣、高中）弄清楚。"}], "difficulty": "中", "label": "111學測", "year": 111, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc111-14", "exam": "xc111", "nums": [14, 15, 16, 17], "form": "題組", "img": "img/xc111-14.png", "source": "甲：張李德和〈畫菊自序〉；乙：呂碧城〈女界近況雜談〉", "author": "張李德和；呂碧城", "genre": "書信序跋", "types": ["比較閱讀", "文意推論", "詩詞賞析"], "passage": "甲\n人為萬物之靈，志有萬端之異。學琴學詩均從所好，工書工畫各有專長，是故咳唾珠玉，謫仙闢詩學之源；節奏鏗鏘，蔡女撰胡笳之拍，此皆不墮聰明，而有志竟成者也。若夫銀鈎鐵畫，固屬難窺；儷白妃青，亦非易事。余因停機教子之餘，調藥助夫之暇，竊慕管夫人之墨竹，紙上生風；敢藉陶彭澤之黃花，圖中寫影。庶幾秋姿不老，四座流芬，得比勁節長垂，千人共仰，竟率意而鴉塗，莫自知其鳩拙云爾！（張李德和〈畫菊自序〉）\n乙\n茲就詞章論，世多訾女子之作，大抵裁紅刻翠，寫怨言情，千篇一律，不脫閨人口吻者。予以為抒寫性情，本應各如其分，惟須推陳出新，不襲窠臼，尤貴格律雋雅，情性真切，即為佳作。詩中之溫、李，詞中之周、柳，皆以柔豔擅長，男子且然，況於女子寫其本色，亦復何妨？（呂碧城〈女界近況雜談〉）", "translation": "甲：人是萬物之靈，志向千差萬別。學琴學詩都依照自己的喜好，擅長書法擅長繪畫也各有專長。所以出口成章，李白開創了詩學的源流；音節鏗鏘，蔡文姬寫出〈胡笳十八拍〉，這些都是不埋沒聰明才智、有志者事竟成的例子。至於書法的剛勁筆畫，本來就難以窺見門徑；繪畫的著色配彩，也不是容易的事。我在織布教子之餘、調藥幫助丈夫的空閒，私下仰慕管夫人畫墨竹，紙上彷彿生風；斗膽借陶淵明喜愛的菊花，在畫中描繪它的影子。希望秋菊的姿態永不老去，香氣流遍滿座，能比擬它長久挺立的節操，受眾人景仰，於是隨意塗抹，自己也不知道畫得多麼笨拙罷了！\n乙：就詩詞文章來說，世人大多批評女子的作品，大都是剪紅裁翠、寫哀怨講情愛，千篇一律，脫不了閨中女子的口吻。我認為抒寫性情，本來就應該各依自己的本分，只要推陳出新、不落俗套，尤其重視格律雋永典雅、情感真切，就是好作品。詩裡的溫庭筠、李商隱，詞裡的周邦彥、柳永，都以柔美豔麗見長，男子尚且如此，何況女子寫出自己的本色，又有什麼妨礙呢？", "keywords": [{"w": "咳唾珠玉", "m": "出口成章，比喻文辭優美"}, {"w": "謫仙", "m": "李白"}, {"w": "蔡女", "m": "蔡文姬"}, {"w": "儷白妃青", "m": "配置顏色，指繪畫設色"}, {"w": "停機", "m": "停下織布機，用孟母斷機教子典故"}, {"w": "鴉塗", "m": "塗鴉，謙稱自己的作品"}, {"w": "鳩拙", "m": "笨拙（斑鳩不善築巢）"}, {"w": "訾", "m": "批評、詆毀"}, {"w": "裁紅刻翠", "m": "堆砌華麗辭藻"}, {"w": "窠臼", "m": "舊套"}], "questions": [{"n": 14, "qtype": "單選", "stem": "依據甲文，關於作者自述「莫自知其鳩拙云爾」的心態，最不可能的是：", "options": {"A": "無法預先了解後人對自己畫作的評價，也就不在意任何評論", "B": "既然有志於丹青之道，總要努力以赴，愚拙與否便毋須介懷", "C": "只能利用相夫教子以外的時間從事創作，故自婉言技巧尚拙", "D": "以率意塗抹謙稱自己的畫作，凸顯想要創作的欲望非常強烈"}, "answer": "A", "explain": "「莫自知其鳩拙」是謙虛地說「我也不知道自己畫得多笨拙」。B呼應前文「有志竟成」，有志就去做，拙不拙不放在心上，可能。C只能在「停機教子之餘，調藥助夫之暇」作畫，所以謙稱技巧不好，可能。D「竟率意而鴉塗」，明知不易還是忍不住要畫，可見創作欲望強，可能。A文中完全沒談到「後人的評價」，「不在意任何評論」也和謙虛的語氣不合，最不可能。", "skill": "謙詞（鳩拙、鴉塗、拙作）背後是「謙虛＋仍想做」，選項扯到別人評價就離題了。"}, {"n": 15, "qtype": "單選", "stem": "依據乙文，敘述最適當的是：", "options": {"A": "為推陳出新，不襲窠臼，男女皆應拋棄格律的束縛", "B": "詞章以閨人口吻成其本色，故男女表現宜各如其分", "C": "女子習寫詞章，可模仿以柔豔詩詞著稱的男性作家", "D": "女子創作可不忌裁紅刻翠，但直寫自己的真誠感受"}, "answer": "D", "explain": "呂碧城認為女子寫柔豔是「寫其本色，亦復何妨」，但要「情性真切」才是佳作——可以不避諱柔美題材，但要寫出真心感受，選D。A她說「尤貴格律雋雅」，重視格律，不是拋棄。B「不脫閨人口吻」是世人批評的毛病，她並沒有說詞章以閨人口吻為本色。C舉溫、李、周、柳是要說明「男子寫柔豔都可以，女子當然也可以」，不是要女子去模仿他們。", "skill": "論說文要分清「作者引述的別人說法」（世多訾……）和「作者自己的主張」（予以為……）。"}, {"n": 16, "qtype": "單選", "stem": "關於甲、乙二文所蘊含的創作觀念，下列推論最不適當的是：", "options": {"A": "甲文的「之餘、之暇」透露出張李德和的創作並未違背傳統性別角色規範", "B": "乙文認為「閨人」與「柔豔」皆為女性創作本色，女性其實不必引以為非", "C": "甲文「志有萬端之異」與乙文「情性真切」，都從性別角度論證創作合宜性", "D": "乙文所舉前輩作家，較甲文所舉前輩作家更具破除當時性別刻板印象的意味"}, "answer": "C", "explain": "甲文「志有萬端之異」說的是每個人志趣不同、各有所好；乙文「情性真切」說的是好作品的標準，兩者都不是從「性別」角度論證，所以C最不適當。A先完成教子、助夫的本分，再利用空檔作畫，沒有違背傳統角色，合理。B乙文說女子寫柔豔是「本色」，「亦復何妨」，合理。D乙文舉的是以柔豔見長的「男性」作家，打破「柔豔只屬女性」的印象；甲文舉李白、蔡文姬只說明有志竟成，所以乙文更有破除性別刻板印象的意味，合理。", "skill": "「最不適當」的推論常是把某句話的論述角度換掉，回原句看它到底在講什麼。"}, {"n": 17, "qtype": "單選", "stem": "下列詩詞與乙文所提及的柔豔風格，最相近的是：", "options": {"A": "世機消已盡，巾屨亦飄然。一室故山月，滿瓶秋澗泉", "B": "朔雁傳書絕，湘篁染淚多。無由見顏色，還自託微波", "C": "灞橋雪。茫茫萬徑人蹤滅。人蹤滅。此時方見，乾坤空闊", "D": "游宦成羈旅。短檣吟倚閑凝竚。萬水千山迷遠近，想鄉關何處"}, "answer": "B", "explain": "柔豔＝柔美婉約、寫男女情思。B書信斷絕、竹上淚痕（湘妃竹典故）、見不到心上人的容顏，只能託水波傳情，是纏綿的相思，最接近柔豔，選B。A寫世俗心機消盡、山月秋泉，是清淡的隱逸。C寫大雪中天地空闊，境界開闊豪放。D寫宦遊在外、思念家鄉的羈旅之愁，不是柔情。", "skill": "判斷風格看意象：淚、顏色、微波→柔情；山月、秋泉→清淡；萬徑、乾坤→開闊。"}], "difficulty": "難", "label": "111學測", "year": 111, "kind": "學測", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "畫菊自序"}, {"id": "xc111-18", "exam": "xc111", "nums": [18, 19], "form": "題組", "img": "img/xc111-18.png", "source": "劉基《郁離子‧獻馬》", "author": "劉基", "genre": "寓言故事", "types": ["字詞解釋", "人物情感", "文意推論"], "passage": "周厲王使芮伯帥師伐戎，得良馬焉，將以獻於王。芮季曰：「不如捐之。王欲無厭，而多信人之言。今以師歸而獻馬焉，王之左右必以子獲為不止一馬，而皆求於子。子無以應之，則將嘵於王，王必信之。是賈禍也。」弗聽，卒獻之。榮夷公果使有求焉，弗得，遂譖諸王曰：「伯也隱。」王怒逐芮伯。君子謂芮伯亦有罪焉。爾知王之瀆貨而啟之，芮伯之罪也。", "translation": "周厲王派芮伯率軍討伐戎人，得到一匹良馬，打算獻給厲王。芮季說：「不如把馬丟掉。大王的欲望沒有滿足的時候，又常聽信別人的話。現在你帶軍隊回來獻馬，大王身邊的人一定會以為你得到的不只一匹馬，都會來向你要。你拿不出來給他們，他們就會在大王面前說你壞話，大王一定會相信。這是自己招來災禍啊。」芮伯不聽，最後還是把馬獻上了。榮夷公果然派人來要馬，要不到，就向厲王誣陷說：「芮伯隱藏了馬。」厲王大怒，把芮伯放逐了。君子說芮伯自己也有罪。明知道君王貪求財物，還去開啟他的貪心，這就是芮伯的罪過。", "keywords": [{"w": "捐", "m": "捨棄"}, {"w": "厭", "m": "同「饜」，滿足"}, {"w": "嘵", "m": "爭吵、在背後說壞話"}, {"w": "賈禍", "m": "招來災禍"}, {"w": "譖", "m": "誣陷、說壞話"}, {"w": "瀆貨", "m": "貪求財物"}, {"w": "啟", "m": "開啟、引發"}], "questions": [{"n": 18, "qtype": "單選", "stem": "下列文句的「厭」，與「王欲無厭，而多信人之言」的「厭」意義相同的是：", "options": {"A": "學而不「厭」，誨人不倦，何有於我哉", "B": "館人「厭」之，忍弗言。將行，贈之以狗", "C": "君子之道：淡而不「厭」，簡而文，溫而理", "D": "近世「厭」常而反古，專尚奇麗。吾為衣食所迫，不能免俗"}, "answer": "A", "explain": "「王欲無厭」＝大王的欲望永遠不滿足，「厭」是滿足（同饜）。A「學而不厭」＝學習永不滿足，相同，選A。B「館人厭之，忍弗言」＝館舍的人討厭他，卻忍著不說，是厭惡。C「淡而不厭」（《中庸》）＝平淡卻不令人厭倦，是厭倦。D「厭常而反古」＝厭棄平常的東西，是厭惡、厭棄。", "skill": "「厭」三義：滿足（饜）、厭倦、厭惡。看它前後是在說「要不夠」還是「不喜歡」。"}, {"n": 19, "qtype": "單選", "stem": "依據上文，關於文中人物對獻馬的看法，敘述最適當的是：", "options": {"A": "芮季和榮夷公相同，都想從芮伯那裡獲得一匹良馬", "B": "榮夷公和周厲王相同，都認為芮伯不應只獻一匹馬", "C": "榮夷公和君子相同，都認為芮伯隱藏了其他的良馬", "D": "芮季和君子相同，都認為芮伯之舉使王想得更多馬"}, "answer": "D", "explain": "芮季說王「欲無厭」，獻馬會讓人以為還有更多；君子說芮伯「知王之瀆貨而啟之」——明知王貪還去引發他的貪欲。兩人都認為獻馬會讓王想要更多，選D。A芮季勸芮伯丟掉馬，自己並不想要。B周厲王是聽了讒言才發怒，文中沒說他認為不該只獻一匹。C「伯也隱」是榮夷公的誣陷，君子並沒有這樣認為，他批評的是芮伯不該引發王的貪心。", "skill": "人物立場題：把每個人說的話各濃縮成一句，再兩兩比較，「相同」的地方要真的一樣。"}], "difficulty": "中", "label": "111學測", "year": 111, "kind": "學測", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "郁離子選"}, {"id": "xc111-20", "exam": "xc111", "nums": [20, 21, 22], "form": "題組", "img": "img/xc111-20.png", "source": "甲：國定古蹟鄭崇和墓介紹；乙：鄭崇和臨終交代；丙：《古蹟指定及廢止審查辦法》第二條", "author": "鄭崇和（乙）", "genre": "其他", "types": ["文意推論", "比較閱讀", "文化常識"], "passage": "乙　鄭崇和臨終前交代\n作善降祥，作惡降殃，天之理也。吾見今人受祖父生前蔭庇，歿後又妄信風水，乞靈枯骨，不亦慎乎？吾歿後，爾輩勿惑堪輿家言，貪尋吉地，為福利計。吾後龍山中田有老屋地焉，營而葬之，吾願足矣。將來為吉為凶，爾輩自取之，何與墳塋？\n墓碑部分文字：皇清誥贈二品夫人通奉大夫顯祖妣考鄭門陳太夫人鄭公祀鄉賢祠合葬佳城／四大房孫男如蘭如雲如梁如椿等重修", "translation": "做好事會得到吉祥，做壞事會招來災禍，這是天理。我看現在的人，祖父在世時受到庇蔭，祖父死後又胡亂相信風水，向枯骨祈求保佑，不也太過分了嗎？我死後，你們不要被風水師的話迷惑，貪心地尋找吉地來替自己謀福利。我在後龍山中的田裡有一塊老屋地，在那裡營造墳墓安葬我，我就心滿意足了。將來是吉是凶，是你們自己造成的，和墳墓有什麼關係？", "keywords": [{"w": "蔭庇", "m": "庇護"}, {"w": "乞靈枯骨", "m": "向祖先遺骨祈求福佑"}, {"w": "不亦慎乎", "m": "此處「慎」意近「甚」，不也太過分了嗎"}, {"w": "堪輿家", "m": "看風水的人"}, {"w": "墳塋", "m": "墳墓"}, {"w": "誥贈", "m": "朝廷對已故者追贈官銜"}, {"w": "佳城", "m": "墓地"}], "questions": [{"n": 20, "qtype": "單選", "stem": "依據資料甲，下列關於鄭崇和的敘述，最適當的是：", "options": {"A": "十九歲時，隨祖父、父親、叔叔遷居後龍", "B": "生前即因兒子們功名有成，晉升為通奉大夫", "C": "長子由大房過繼，是鄭家家業發達關鍵人物之一", "D": "妻子姓陳，仙逝較早，故於鄭崇和過世後才同葬"}, "answer": "C", "explain": "鄭崇和收養大哥鄭崇聰之子用鍾為長子，用鍾「以經營實業著稱」，是家業發達的重要人物，選C。A乾隆21年生、40年來臺，確實19歲，但同行的是伯父國周、父親國唐、叔叔國慶，沒有祖父。B「父以子貴，去世後也獲誥贈」，是死後追贈，不是生前晉升。D妻子卒於道光25年，比鄭崇和（道光7年）晚死，是後來才移葬同穴。", "skill": "家譜題畫一張關係圖（誰是誰的兒子、哥哥），年份逐一相減，就不會被親屬稱謂繞昏。"}, {"n": 21, "qtype": "單選", "stem": "依據資料甲、乙，下列關於鄭崇和墓的敘述，最適當的是：", "options": {"A": "鄭崇和雖自認深受祖先陰宅風水庇蔭而富裕，但不願子孫迷信擇地求福之說", "B": "鄭用錫等雖按鄭崇和遺願將其葬於老家山中，但鄭如椿等仍另外擇吉地遷葬", "C": "最初形制簡約，後因鄭用錫中進士並授官，始據《大清會典事例》擴大規模", "D": "「祀鄉賢祠」記於墓碑，可見既是當時官方認可功績，家族也視為無上光榮"}, "answer": "D", "explain": "甲說鄭崇和「去世後即獲朝廷同意入祀鄉賢祠」，是官方認可；家族把「祀鄉賢祠」刻在墓碑上，可見引以為榮，選D。A乙文是批評別人「受祖父生前蔭庇，歿後又妄信風水」，他並沒有說自己是靠祖先風水才富裕。B墓碑寫鄭如椿等「重修」，不是另擇吉地遷葬。C甲說「墓始建於道光7年，規制悉依《大清會典事例》」，一開始就照規制建造，同治6年只是重修。", "skill": "讀懂乙文的批評對象：「吾見今人……」說的是別人，不是他自己。"}, {"n": 22, "qtype": "單選", "stem": "資料丙《古蹟指定及廢止審查辦法》為民國108年修訂版，若以資料丙審視資料甲，關於①、②兩項推論的研判，最適當的是：①鄭用錫墓展現清代「營造技術流派特色」，而列為國定古蹟。②王得祿墓的歷史價值，可能是被列入古蹟的條件之一。", "options": {"A": "①、②皆正確", "B": "①正確，②錯誤", "C": "①無法判斷，②錯誤", "D": "①無法判斷，②正確"}, "answer": "D", "explain": "①甲只說鄭崇和墓「與新竹鄭用錫墓相似」，沒說鄭用錫墓是不是國定古蹟，更沒說是因為營造技術特色而列入，無法判斷。②王得祿是一品官，墓在臺灣現存古墓中規模最大，具「高度歷史價值」是合理的「可能」條件，正確。選D。", "skill": "注意選項的語氣：「可能是」比「就是」寬鬆，有合理依據就能判為正確。"}], "difficulty": "中", "label": "111學測", "year": 111, "kind": "學測", "textcat": "生活情境文本", "textcat2": "", "linked_core": ""}, {"id": "xc111-23", "exam": "xc111", "nums": [23, 24, 25], "form": "題組", "img": "img/xc111-23.png", "source": "甲：《論語‧季氏》與朱熹解說；乙：《孟子‧盡心下》與朱熹解說（《朱子語類》）", "author": "孔子；孟子；朱熹", "genre": "經典語錄", "types": ["比較閱讀", "句意理解", "文意推論"], "passage": "甲\n《論語》：子曰：「君子有三畏：畏天命，畏大人，畏聖人之言。小人不知天命，而不畏也，狎大人，侮聖人之言。」\n朱熹：①「大人」不止有位者，是指有位、有齒、有德者。②「畏天命」三字好。是理會得道理，便謹去做，不敢違，便是畏之也。如非禮勿視聽言動，與夫戒慎恐懼，皆所以畏天命也。③要緊全在知上。纔知得（天命），便自不容不畏。\n乙\n《孟子》：說大人，則藐之，勿視其巍巍然。堂高數仞，榱題數尺，我得志，弗為也；食前方丈，侍妾數百人，我得志，弗為也；……在彼者，皆我所不為也；在我者，皆古之制也。吾何畏彼哉！\n朱熹：①這為世上有人把大人許多崇高富貴當事，有言不敢出口，故孟子云爾。②《論語》說「畏大人」，此卻說「藐大人」。大人固當畏，而所謂「藐」者，乃不是藐他，只是藐他許多「堂高數仞，榱題數尺」之類。", "translation": "甲：孔子說：「君子有三種敬畏：敬畏天命，敬畏大人，敬畏聖人的話。小人不懂天命，所以不敬畏，輕慢大人，侮辱聖人的話。」朱熹說：①「大人」不只是有地位的人，是指有地位、有年紀、有德行的人。②「畏天命」三個字說得好。懂得了道理，就謹慎去做，不敢違背，這就是敬畏。像不合禮的不看、不聽、不說、不做，以及戒慎恐懼，都是敬畏天命的表現。③關鍵全在「知」。一旦知道了天命，自然不能不敬畏。\n乙：孟子說：「向權貴進言，就要輕視他，不要把他高高在上的樣子放在眼裡。廳堂高好幾丈，屋椽頭好幾尺寬，我如果得志，不會這樣做；吃飯時滿桌菜餚，侍妾幾百人，我如果得志，也不會這樣做……他們擁有的，都是我不屑做的；我所堅持的，都是古代的禮制。我為什麼要怕他們呢！」朱熹說：①這是因為世上有人把大人的崇高富貴看得太重，有話也不敢說出口，所以孟子才這樣說。②《論語》說「畏大人」，這裡卻說「藐大人」。大人本來就應當敬畏，所謂「藐」，並不是輕視他這個人，只是輕視他那些高堂華屋之類的排場。", "keywords": [{"w": "齒", "m": "年齡"}, {"w": "狎", "m": "輕慢、不莊重"}, {"w": "纔", "m": "才、一旦"}, {"w": "說", "m": "遊說、進言（音ㄕㄨㄟˋ）"}, {"w": "藐", "m": "輕視"}, {"w": "巍巍然", "m": "高大尊貴的樣子"}, {"w": "仞", "m": "古代長度單位，約七、八尺"}, {"w": "榱題", "m": "屋椽的兩端"}, {"w": "食前方丈", "m": "面前擺滿一丈見方的食物"}], "questions": [{"n": 23, "qtype": "單選", "stem": "下列敘述，不符合資料甲意旨的是：", "options": {"A": "君子得識天命所歸，遂謹於視聽言動", "B": "小人處懵然狀態，故不知且不畏天命", "C": "君子須知得天命，天命可知遂不可畏", "D": "小人不畏天命，遂輕慢位高權重之人"}, "answer": "C", "explain": "朱熹說「纔知得，便自不容不畏」——一旦知道天命，就不能不敬畏。C說「天命可知遂不可畏」，意思完全相反，不符合，選C。A對應「理會得道理，便謹去做」「非禮勿視聽言動」。B小人「不知天命，而不畏也」，懵懂無知所以不畏。D小人不畏天命，所以「狎大人」，輕慢地位崇高的人。", "skill": "「不符合」題先找出關鍵句（纔知得，便不容不畏），選項中把因果翻轉的就是答案。"}, {"n": 24, "qtype": "單選", "stem": "下列人物及其言行表現，與孟子所藐的「大人」最接近的是：(A)鄭文公：無禮於晉，且貳於楚也 (B)項羽：（樊噲）瞋目視項王，……項王按劍而跽曰：「客何為者？」 (C)劉備：（劉備）每與臣（諸葛亮）論此事，未嘗不嘆息痛恨於桓、靈也 (D)楊素：奢貴自奉，禮異人臣。每公卿入言，賓客上謁，未嘗不踞床而見", "options": {"A": "鄭文公：無禮於晉，且貳於楚也", "B": "項羽：（樊噲）瞋目視項王，……項王按劍而跽曰：「客何為者？」", "C": "劉備：（劉備）每與臣（諸葛亮）論此事，未嘗不嘆息痛恨於桓、靈也", "D": "楊素：奢貴自奉，禮異人臣。每公卿入言，賓客上謁，未嘗不踞床而見"}, "answer": "D", "explain": "孟子所藐的大人：住高堂華屋、食前方丈、侍妾數百，以富貴排場自傲，讓人「有言不敢出口」。D楊素「奢貴自奉」，生活奢華；接見公卿賓客總是「踞床而見」（傲慢地坐在床上），擺出高高在上的架子，最接近，選D。A鄭文公是對晉無禮、對楚有二心，是外交問題。B項羽按劍而跪起，是因樊噲闖入而戒備。C劉備感嘆漢桓帝、靈帝的昏庸，與奢華傲慢無關。", "skill": "先把文本中的人物特徵列成清單（奢華、威勢），再拿選項逐一比對，符合最多項的就是答案。"}, {"n": 25, "qtype": "單選", "stem": "下列關於資料甲、乙的敘述，最適當的是：", "options": {"A": "小人所狎，是那些徒有高位，但非齒、德兼備的大人", "B": "彼等小人專為狎大人、侮聖人之事，因此無法知天命", "C": "合於古制的大人，當不為孟子所藐，且同於孔子所畏", "D": "孟子提出藐大人的說法，是因自己本無意於大人之位"}, "answer": "C", "explain": "朱熹說「大人固當畏」，孟子藐的只是「堂高數仞」那些不合古制的奢華；孟子自己堅持「古之制」。所以合乎古制、有位有齒有德的大人，孟子不會藐視，也正是孔子說的應敬畏的大人，選C。A朱熹說的「大人」是有位、有齒、有德者，小人連這樣的大人都輕慢，不是只狎「徒有高位」者。B因果顛倒：小人是因為「不知天命」，才狎大人、侮聖言。D孟子說「我得志，弗為也」，是得志也不會那樣奢侈，並不是無意於大人之位。", "skill": "兩段看似矛盾（畏 vs. 藐）時，找出解說者如何調和：藐的是「排場」，畏的是「人」。"}], "difficulty": "難", "label": "111學測", "year": 111, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc111-26", "exam": "xc111", "nums": [26], "form": "單題", "img": "img/xc111-26.png", "source": "《論語‧為政》、《禮記‧禮運》、《戰國策‧馮諼客孟嘗君》、林覺民〈與妻訣別書〉、韓愈〈師說〉、蒲松齡〈勞山道士〉、李斯〈諫逐客書〉、《史記‧項羽本紀》、歸有光〈項脊軒志〉等", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)吾十「有」五而志於學，三十而立／男「有」分，女有歸\n(B)使吏召諸民當償者，「悉」來合券／吾之所有，「悉」以充贈\n(C)小學而大遺，吾未「見」其明也／眾視三人，坐月中飲，鬚眉畢「見」\n(D)向使四君卻客而不「內」，疏士而不用／距關，毋「內」諸侯，秦地可盡王也\n(E)庭中始為籬，「已」為牆，凡再變矣／昔之所謂鹿港飛帆者，「已」不概見矣", "translation": "(A)我十五歲立志求學，三十歲能自立／男子有職分，女子有歸宿。\n(B)派官吏召集應該還債的百姓，全都來核對債券／我所有的東西，全部拿來充當贈禮。\n(C)小的學了大的卻丟了，我看不出他的明智／大家看那三個人坐在月光中喝酒，鬍鬚眉毛都清清楚楚顯現出來。\n(D)假如四位君主拒絕客卿而不接納，疏遠賢士而不任用／守住函谷關，不要讓諸侯進來，秦地就可以全部歸你稱王了。\n(E)庭院中起初圍上籬笆，後來砌成牆，總共變了兩次／從前所說的「鹿港飛帆」，已經看不到了。", "keywords": [{"w": "有", "m": "同「又」；擁有"}, {"w": "悉", "m": "全部"}, {"w": "見", "m": "看見；同「現」，顯現"}, {"w": "內", "m": "同「納」，接納、讓……進入"}, {"w": "已", "m": "不久、後來；已經"}], "questions": [{"n": 26, "qtype": "多選", "stem": "下列各組「」內的詞，意義前後相同的是：", "options": {"A": "吾十「有」五而志於學，三十而立／男「有」分，女有歸", "B": "使吏召諸民當償者，「悉」來合券／吾之所有，「悉」以充贈", "C": "小學而大遺，吾未「見」其明也／眾視三人，坐月中飲，鬚眉畢「見」", "D": "向使四君卻客而不「內」，疏士而不用／距關，毋「內」諸侯，秦地可盡王也", "E": "庭中始為籬，「已」為牆，凡再變矣／昔之所謂鹿港飛帆者，「已」不概見矣"}, "answer": "BD", "explain": "A：「十有五」的「有」同「又」，用在整數和零數之間；「男有分」的「有」是擁有，不同。B：兩個「悉」都是全部，相同。C：前「見」是看見、看出；後「見」同「現」，顯現，不同。D：兩個「內」都同「納」，接納、讓……進來，相同。E：前「已」是「不久、後來」（始為籬，已為牆）；後「已」是「已經」，不同。答案BD。", "skill": "「已」看前面有沒有「始」：始……已……＝起初……後來……；單用才是「已經」。"}], "difficulty": "中", "label": "111學測", "year": 111, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "大同與小康、諫逐客書、馮諼客孟嘗君、鴻門宴、師說、項脊軒志、勞山道士"}, {"id": "xc111-29", "exam": "xc111", "nums": [29], "form": "單題", "img": "img/xc111-29.png", "source": "古典文學常識", "author": "", "genre": "其他", "types": ["文化常識", "典故出處"], "passage": "", "translation": "", "keywords": [{"w": "流水對", "m": "上下句意思連貫，有因果、承接、轉折等關係的對偶"}, {"w": "新樂府", "m": "白居易、元稹倡導，以新題寫時事、不一定入樂的詩"}, {"w": "《三國演義》", "m": "元末明初羅貫中所作"}], "questions": [{"n": 29, "qtype": "多選", "stem": "某導演想籌拍一部年代設定在南宋且符合歷史真實的才子佳人古裝劇，男、女主角皆來自書香門第。下列編劇初擬的幾個構想中，時代與敘述都正確的是：", "options": {"A": "依序在書架上排列《詩經》、《楚辭》、《世說新語》和《杜工部集》，顯示女主角能掌握文學發展的歷史順序", "B": "安排男主角自述認同的對象為：寫〈五柳先生傳〉的陶潛、〈愛蓮說〉的周敦頤，以表現不慕榮利、高潔雅致的性格", "C": "女主角以流水對（上、下句具因果、連貫、轉折等關係）考較男主角，男主角能以「欲窮千里目，更上一層樓」正確回應", "D": "女主角引用元稹、白居易所寫入樂的「新樂府」詩，強調詩歌反映民瘼的寫實諷諭精神，規勸男主角別盡是吟風弄月", "E": "安排男主角臨江翻閱《三國演義》，誦讀卷首的〈臨江仙〉：「滾滾長江東逝水，浪花淘盡英雄」，以烘托劇中的歷史蒼茫之感"}, "answer": "ABC", "explain": "要同時檢查「南宋時已存在」和「敘述正確」。A《詩經》（周）→《楚辭》（戰國）→《世說新語》（南朝宋）→《杜工部集》（唐），順序對，也都在南宋以前，正確。B陶淵明（東晉）〈五柳先生傳〉表現不慕榮利，周敦頤（北宋）〈愛蓮說〉以蓮喻君子高潔，都在南宋前，正確。C王之渙（唐）「欲窮千里目，更上一層樓」上下句是條件、承接關係，是流水對，正確。D新樂府的特色正是「不入樂」，說「入樂」錯誤。E《三國演義》是元末明初羅貫中寫的，卷首〈臨江仙〉是明代楊慎的詞，南宋人不可能讀到。答案ABC。", "skill": "穿越劇題先替每個作品標上朝代，晚於設定年代的一律刪掉，再檢查敘述細節。"}], "difficulty": "中", "label": "111學測", "year": 111, "kind": "學測", "textcat": "生活情境文本", "textcat2": "學術文本", "linked_core": ""}, {"id": "xc111-30", "exam": "xc111", "nums": [30], "form": "單題", "img": "img/xc111-30.png", "source": "龔鼎孳〈吃野菜說〉", "author": "龔鼎孳", "genre": "說理議論", "types": ["寫作手法", "文意推論", "句意理解"], "passage": "新雨後，綠蕪如髮，園蔬葉葉，青滿畦徑。啟扉視之，知一年春事又將爛漫矣。家人間擷作羹，劣得一飽。野香拂拂，從匕箸間出，誠有如子瞻所謂飽霜雪之精、味含土膏者。獨憐此物沒蓬蒿中，與貧士為伍，寒窗一嚼，勝十日太牢，甚不可進於達官貴人、鐘鳴鼎食、芍藥饌、朱砂羹之口。今中原嗷嗷，道殣相屬，雁糞榆皮，所在仰以為命。甚且折骨解肢，與烏鳶爭攫啄之利。吁，可悲也！彼達官貴人日啖醲鮮，當翠袖奉卮，華茵度夢時，亦曾念及野人藜藿不繼無耶？昔人曰：民不可有此色，士大夫不可無此味。知言哉！", "translation": "剛下過雨，綠草像頭髮一樣茂密，園裡的菜一葉葉青翠，長滿田間小路。打開門一看，知道一年的春天又要燦爛盛開了。家人偶爾摘來煮湯，勉強吃個飽。野菜的香氣陣陣從湯匙筷子間飄出，真像蘇軾說的「飽含霜雪的精華、味道帶著泥土的養分」。只可惜這東西埋沒在野草中，和窮書生作伴，寒窗下吃一口，勝過十天的大魚大肉，卻根本不能送進達官貴人那些鳴鐘列鼎、吃芍藥菜、朱砂羹的嘴裡。現在中原百姓哀號挨餓，路上餓死的人一個接一個，雁糞、榆樹皮，到處都靠它們活命。甚至有人分解屍骨，和烏鴉老鷹爭奪啄食。唉，真可悲啊！那些達官貴人天天吃美酒佳餚，在美女捧杯、華麗被褥中入夢時，可曾想到鄉野百姓連野菜都接不上嗎？古人說：「百姓不可以有菜色，士大夫不可以不知道這種滋味。」真是有見識的話啊！", "keywords": [{"w": "綠蕪", "m": "綠草"}, {"w": "擷", "m": "摘取"}, {"w": "劣得", "m": "勉強得到"}, {"w": "太牢", "m": "牛羊豬三牲具備的盛饌"}, {"w": "嗷嗷", "m": "飢餓哀號聲"}, {"w": "道殣相屬", "m": "路上餓死的人一個接一個"}, {"w": "醲鮮", "m": "美酒佳餚"}, {"w": "藜藿", "m": "野菜，指粗劣的食物"}, {"w": "菜色", "m": "因飢餓而面黃肌瘦的臉色"}], "questions": [{"n": 30, "qtype": "多選", "stem": "關於下文的寫法與文意，敘述適當的是：", "options": {"A": "本文先敘眼中所見春景，繼而談及野菜之味，接著再論心中所感，最後歸結到對士大夫的期許", "B": "作者援引蘇軾之文，表達野菜飽含天地精華，並認為對未得功名的寒士而言，野菜的滋味勝過太牢之饌", "C": "文中提到「中原」的現況是：發生饑荒，路有餓莩，而烏鳶甚至還與饑民搶食其賴以維生的雁糞、榆皮", "D": "本文出現兩次「達官貴人」，前次意指野菜不可能入其華宴，第二次批判他們對於下層人民生活的漠然", "E": "「不可有」，意指不可讓人民有如菜的面色；「不可無」，指士大夫須食野菜，方能回歸素樸自然之味"}, "answer": "ABD", "explain": "A對：雨後春景→家人煮野菜的滋味→感嘆中原饑荒、批評權貴→引古語期許士大夫，順序正確。B對：引蘇軾「飽霜雪之精、味含土膏」，又說「寒窗一嚼，勝十日太牢」。C錯：饑民靠雁糞、榆皮活命，甚至「折骨解肢，與烏鳶爭攫啄之利」，是人和烏鴉老鷹搶食屍體，不是烏鳶搶雁糞榆皮。D對：第一次說野菜「甚不可進於達官貴人」之口；第二次質問他們「亦曾念及野人藜藿不繼無耶」，批評其冷漠。E錯：「士大夫不可無此味」是要士大夫體會百姓吃野菜的苦，知道民間疾苦，不是為了回歸素樸自然。答案ABD。", "skill": "文末引古語收束時，要放回全文脈絡（批評權貴不知民苦）解讀，不能只照字面理解。"}], "difficulty": "中", "label": "111學測", "year": 111, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc111-31", "exam": "xc111", "nums": [31, 32], "form": "題組", "img": "img/xc111-31.png", "source": "鄭燮〈濰縣署中寄舍弟墨第一書〉", "author": "鄭燮", "genre": "書信序跋", "types": ["寫作手法", "文化常識", "主旨寓意"], "passage": "讀書以過目成誦為能，最是不濟事。眼中了了，心下匆匆，方寸無多，往來應接不暇，如看場中美色，一眼即過，與我何與也。千古過目成誦，孰有如孔子者乎？讀《易》至韋編三絕，不知翻閱過幾千百遍來，微言精義，愈探愈出，愈研愈入，愈往而不知其所窮。雖生知安行之聖，不廢困勉下學之功也。東坡讀書不用兩遍，然其在翰林讀〈阿房宮賦〉至四鼓，老吏苦之，坡洒然不倦，豈以一過即記，遂了其事乎！惟虞世南、張睢陽、張方平，平生書不再讀，迄無佳文。且過輒成誦，又有無所不誦之陋。即如《史記》百三十篇中，以〈項羽本紀〉為最，而〈項羽本紀〉中，又以鉅鹿之戰、鴻門之宴、垓下之會為最。反覆誦觀，可欣可泣，在此數段耳。若一部《史記》，篇篇都讀，字字都記，豈非沒分曉的鈍漢！", "translation": "讀書把過目不忘當成本事，最沒用了。眼睛看得清清楚楚，心裡卻匆匆忙忙，心中容量有限，來來往往應接不暇，就像看戲場上的美女，一眼就過去了，跟我有什麼關係呢？自古以來說到過目成誦，誰比得上孔子？他讀《易經》讀到串竹簡的皮繩斷了好幾次，不知道翻了幾千百遍，精微的道理越探索越多，越研究越深入，越往前越不知道盡頭在哪。即使是生來就懂、自然能行的聖人，也不放棄刻苦學習的功夫。蘇東坡讀書不用讀兩遍，但他在翰林院讀〈阿房宮賦〉讀到四更天，陪他的老吏都受不了，東坡卻瀟灑不倦，難道他會因為讀一遍就記住，就此了事嗎！只有虞世南、張巡、張方平，一輩子書不讀第二遍，結果始終寫不出好文章。而且看過就能背，又有什麼都背的毛病。就像《史記》一百三十篇中，以〈項羽本紀〉最好；〈項羽本紀〉中，又以鉅鹿之戰、鴻門宴、垓下之圍最好。反覆誦讀觀覽，讓人欣喜讓人落淚的，就在這幾段罷了。如果一整部《史記》篇篇都讀、字字都記，豈不是不分輕重的笨蛋！", "keywords": [{"w": "了了", "m": "清清楚楚"}, {"w": "方寸", "m": "心"}, {"w": "與我何與", "m": "和我有什麼關係"}, {"w": "韋編三絕", "m": "串竹簡的皮繩斷了多次，形容勤讀"}, {"w": "生知安行", "m": "生來就懂、自然就能做到"}, {"w": "困勉", "m": "刻苦努力"}, {"w": "四鼓", "m": "四更天"}, {"w": "迄", "m": "始終、直到"}, {"w": "分曉", "m": "分辨輕重"}], "questions": [{"n": 31, "qtype": "多選", "stem": "上文對「讀書」一事的舉證與說明，敘述適當的是：", "options": {"A": "以孔子讀《易》韋編三絕為例，說明孔子讀書有過目成誦的本領", "B": "以蘇軾讀〈阿房宮賦〉為例，說明夜闌人靜時更能領略讀書況味", "C": "以孔子和蘇軾為例，說明讀書貴在鑽研不懈，而非只是迅速瀏覽", "D": "以虞世南書不再讀而迄無佳文為例，說明盡信書不如無書的道理", "E": "以〈項羽本紀〉的內容情節為例，說明讀書必須懂得慎擇和精讀"}, "answer": "CE", "explain": "A錯：舉孔子韋編三絕，是說他反覆研讀幾千百遍，不是說他過目成誦。B錯：舉蘇軾讀到四更，重點是不倦地反覆讀，不是夜深更能體會。C對：孔子、蘇軾都是聖賢天才，仍反覆鑽研，可見讀書貴在下功夫，不在快速看過。D錯：虞世南等書不再讀，結果沒有好文章，說明不反覆讀的壞處，和「盡信書」無關。E對：《史記》中選〈項羽本紀〉、再選其中三段反覆誦觀，說明要選擇重點、精讀。答案CE。", "skill": "舉例題問「為了說明什麼」，回到例子後面作者的評語（不廢困勉之功、豈以一過即記）。"}, {"n": 32, "qtype": "多選", "stem": "書信語言必須考慮寫信人與收信人的身分、關係。若依據上文鄭燮寫信給堂弟鄭墨的情境，適當的「信封啟封詞／提稱語／結尾頌詞」是：", "options": {"A": "大啟／左右／大安", "B": "台啟／足下／近安", "C": "敬啟／惠鑒／文安", "D": "鈞啟／如晤／勛安", "E": "收啟／壇席／福安"}, "answer": "AB", "explain": "堂兄寫給堂弟，屬於平輩（兄對弟）。A「大啟」、「左右」、「大安」都可用於平輩，正確。B「台啟」、「足下」、「近安」也都是平輩用語，正確。C「敬啟」不是給平輩的啟封詞；「文安」一般用於文教界。D「鈞啟」用於長官、「勛安」用於政界，「如晤」雖可用於晚輩，但整組不合。E「收啟」用於晚輩，「壇席」用於教育界、師長，「福安」用於長輩，都不適合。答案AB。", "skill": "書信用語先定位關係（長輩、平輩、晚輩），三個欄位都要合才能選；一格不合整組就錯。"}], "difficulty": "中", "label": "111學測", "year": 111, "kind": "學測", "textcat": "生活情境文本", "textcat2": "學術文本", "linked_core": ""}, {"id": "xc111-33", "exam": "xc111", "nums": [33, 34], "form": "題組", "img": "img/xc111-33.png", "source": "甲：蒲松齡《聊齋志異‧勞山道士》；乙：紀昀《閱微草堂筆記‧如是我聞二》", "author": "蒲松齡；紀昀", "genre": "筆記小品", "types": ["比較閱讀", "寫作手法", "文意推論"], "passage": "甲\n道士笑曰：「我固謂不能作苦，今果然。明早當遣汝行。」王曰：「弟子操作多日，師略授小技，此來為不負也。」道士問：「何術之求？」王曰：「每見師行處，牆壁所不能隔，但得此法足矣。」道士笑而允之。乃傳以訣，令自咒畢，呼曰：「入之！」王面牆不敢入。又曰：「試入之。」王果從容入，及牆而阻。道士曰：「俯首輒入，勿逡巡！」王果去牆數步，奔而入，及牆，虛若無物，回視，果在牆外矣。大喜，入謝。道士曰：「歸宜潔持，否則不驗。」遂助資斧遣之歸。抵家，自詡遇仙，堅壁所不能阻。妻不信。王效其作為，去牆數尺，奔而入；頭觸硬壁，驀然而踣。妻扶視之，額上墳起如巨卵焉。妻揶揄之。王慚忿，罵老道士之無良而已。\n乙\n奇門遁甲之書，所在多有，然皆非真傳。真傳不過口訣數語，不著諸紙墨也。德州宋先生清遠言：曾訪一友，友留之宿，曰：「良夜月明，觀一戲劇可乎？」因取凳十餘，縱橫布院中，與清遠明燭飲堂上。二鼓後，見一人踰垣入，環轉階前，每遇一凳，輒蹣跚，努力良久，乃跨過。始而順行，曲踊一二百度；轉而逆行，又曲踊一二百度。疲極踣臥，天已向曙矣。友引至堂上，詰問何來。叩首曰：「吾實偷兒，入宅以後，惟見層層皆短垣，愈越愈不能盡，窘而退出，又愈越愈不能盡，故困頓見擒，死生惟命。」友笑遣之。謂清遠，曰：「昨卜有此偷兒來，故戲以小術。」問：「此何術？」曰：「奇門法也。他人得之，恐召禍；君真端謹，如願學，當授君。」清遠謝不願。友太息曰：「願學者不可傳，可傳者不願學，此術其終絕矣。」意若有失，悵悵送之返。", "translation": "甲：道士笑著說：「我本來就說你吃不了苦，現在果然如此。明天早上就送你走。」王生說：「弟子做了這麼多天的工，師父稍微教我一點小法術，這趟就算沒白來。」道士問：「你想學什麼法術？」王生說：「常看師父走到哪裡，牆壁都擋不住，只要學到這個就夠了。」道士笑著答應了。於是傳他口訣，叫他自己唸完咒語，喊道：「進去！」王生面對牆壁不敢進去。道士又說：「試著進去看看。」王生果然慢慢走進去，到了牆邊就被擋住。道士說：「低頭直接衝進去，不要猶豫！」王生果然退後幾步，跑著衝進去，到了牆邊，空空的好像沒有東西，回頭一看，人果然已經在牆外了。王生非常高興，進去道謝。道士說：「回家後要潔身自持，否則就不靈驗。」於是送他路費讓他回去。王生到家後，自誇遇到神仙，再堅固的牆也擋不住他。妻子不相信。王生照著之前的做法，離牆幾尺，跑著衝進去；頭撞上硬牆，猛然跌倒在地。妻子扶起他一看，額頭上腫起一個像大雞蛋的包。妻子嘲笑他。王生又羞又氣，只能罵老道士沒良心罷了。\n乙：講奇門遁甲的書到處都有，但都不是真傳。真傳不過是幾句口訣，不寫在紙上。德州的宋清遠先生說：他曾去拜訪一位朋友，朋友留他過夜，說：「這麼好的月夜，看一齣戲好嗎？」於是拿了十幾張凳子，縱橫擺在院子裡，和清遠在堂上點著蠟燭喝酒。二更以後，看見一個人翻牆進來，在台階前繞來繞去，每碰到一張凳子，就步履蹣跚，費力好久才跨過去。起先順著走，彎著身子跳了一兩百次；接著倒著走，又彎身跳了一兩百次。累到極點倒在地上，天已經快亮了。朋友把他帶到堂上，問他從哪裡來。那人磕頭說：「我其實是小偷，進到宅子以後，只看到一層又一層的矮牆，越翻越翻不完，困窘想退出去，又越翻越翻不完，所以累倒被抓，是生是死聽憑處置。」朋友笑著放他走了。朋友對清遠說：「昨天占卜知道有這個小偷要來，所以用小法術戲弄他。」清遠問：「這是什麼法術？」朋友說：「是奇門遁甲之法。別人學到它，恐怕會招來災禍；您真是端正謹慎的人，如果願意學，我就教您。」清遠推辭不願學。朋友嘆息說：「想學的人不可以傳，可以傳的人不想學，這門法術大概要從此失傳了。」好像若有所失，悵然地送他回去。", "keywords": [{"w": "作苦", "m": "吃苦耐勞"}, {"w": "逡巡", "m": "猶豫不前"}, {"w": "潔持", "m": "潔身自持、保持心地純潔"}, {"w": "資斧", "m": "路費"}, {"w": "踣", "m": "跌倒"}, {"w": "揶揄", "m": "嘲笑"}, {"w": "踰垣", "m": "翻牆"}, {"w": "曲踊", "m": "彎身跳躍"}, {"w": "曙", "m": "天亮"}, {"w": "端謹", "m": "端正謹慎"}, {"w": "謝", "m": "推辭"}], "questions": [{"n": 33, "qtype": "單選", "stem": "上引甲、乙二文皆以記敘為主。關於文中運用的寫作手法，敘述最適當的是：（占2分，單選題）", "options": {"A": "甲文從頭至尾順時敘寫；乙文「二鼓後，……友笑遣之」則是在順時敘寫之外插補的追憶", "B": "甲文未見作者現身說法；乙文則隱然有作者身影，且於述說宋清遠及其友人的故事前表達看法", "C": "甲文的「牆」是王生的學習場所，也象徵王生的心理障礙；乙文的「短垣」是偷兒的關卡，也象徵宋清遠畏苦怕難", "D": "甲文藉妻「揶揄」與王生「慚忿」的對比，凸顯王生的愧疚；乙文藉宋清遠「謝」與友人「悵然」的對比，凸顯宋清遠的清高"}, "answer": "B", "explain": "乙文開頭「奇門遁甲之書，所在多有，然皆非真傳……」是作者紀昀先發表看法，再轉述宋清遠說的故事；甲文節選部分只有故事本身，作者沒有出來評論，選B。A乙文「二鼓後……友笑遣之」是照時間順序發生的事，不是插敘的追憶。C「短垣」是法術造成的幻象、困住小偷，和宋清遠是否怕苦無關（他不學是因為不願）。D王生「慚忿」後是「罵老道士之無良」，是又羞又怒、怪罪別人，不是愧疚；宋清遠推辭也看不出是在凸顯清高。", "skill": "判斷「作者現身」：找故事外的評論句（開頭或結尾的議論），有就是作者在說話。"}, {"n": 34, "qtype": "非選", "stem": "請依據提示，完成表格內容。師父問：「學法術的條件是什麼？」師父答：「條件一當然是要通過些考驗。條件二是無畏，只學口訣而不敢嘗試，怎學得會？條件三□□最重要，它是避免禍害或法術靈驗的保證。」表格：條件一「耐勞苦」——（1）；條件二「有勇氣」——俯首輒入，勿逡巡；條件三——（2）。（（1）請抄錄甲文文句，占2分，作答字數：10字以內。（2）請先寫出「條件」再「抄錄甲文或乙文文句」，建議兩者間以分號區隔（如條件；文句），占4分，作答字數：15字以內。）", "options": {}, "answer": "", "ref_answer": "（1）能作苦。（或：我固謂不能作苦。／我固謂不能作苦，今果然。）\n（2）德行好；（君真）端謹。或：心思純淨；（歸宜）潔持。", "ref_official": true, "explain": "（1）條件一是「耐勞苦」，要在甲文找跟「吃苦」有關的句子：道士一開頭就說「我固謂不能作苦，今果然」，關鍵字「作苦」就是耐勞苦。（2）條件三是「避免禍害或法術靈驗的保證」，兩篇各有一句：甲文道士叮嚀「歸宜潔持，否則不驗」——不潔持就不靈驗；乙文友人說「他人得之，恐召禍；君真端謹……當授君」——品行不端的人學了會招禍，端謹的人才能傳。所以條件可寫「德行好」配「端謹」，或「心思純淨」配「潔持」。", "skill": "抄錄文句題：先把題目的條件換成關鍵詞（苦、驗、禍），回原文找出現這些字的句子，抄最短而完整的那段。"}], "difficulty": "中", "label": "111學測", "year": 111, "kind": "學測", "textcat": "部定古文", "textcat2": "文學文本", "linked_core": "勞山道士"}, {"id": "xc112-05", "exam": "xc112", "nums": [5], "form": "單題", "img": "img/xc112-05.png", "source": "《左傳‧燭之武退秦師》、《史記‧項羽本紀》（鴻門宴）", "author": "左丘明、司馬遷", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "甲、燭之武謂秦穆公：「且君嘗為晉君賜矣，許君焦、瑕，朝濟而夕設版焉，君之所知也。夫晉，何厭之有？既東封鄭，又欲肆其西封。若不闕秦，將焉取之？」\n乙、樊噲謂項羽：「今沛公先破秦，入咸陽，毫毛不敢有所近，封閉宮室，還軍霸上，以待大王來。故遣將守關者，備他盜出入與非常也。勞苦而功高如此，未有封侯之賞，而聽細說，欲誅有功之人，此亡秦之續耳。」", "translation": "甲：燭之武對秦穆公說：「況且您曾經對晉君施過恩惠，他答應把焦、瑕兩地割給您，結果早上渡河回國，晚上就在那裡築起防禦工事，這是您知道的。晉國哪有滿足的時候？它向東把鄭國當作邊界之後，又會想向西擴張邊界。如果不削減秦國的土地，它要從哪裡取得呢？」\n乙：樊噲對項羽說：「沛公最先攻破秦國、進入咸陽，一絲一毫的東西都不敢碰，封閉宮室，退軍駐紮在霸上，等待大王到來。之所以派將領把守函谷關，是為了防備其他盜賊進出和意外變故。沛公這樣勞苦功高，沒有得到封侯的獎賞，您反而聽信小人的讒言，想殺有功的人，這是在延續已滅亡的秦朝的做法啊。」", "keywords": [{"w": "為晉君賜", "m": "對晉君施予恩惠"}, {"w": "設版", "m": "築城牆防禦，指背約"}, {"w": "厭", "m": "通「饜」，滿足"}, {"w": "闕", "m": "侵損、削減"}, {"w": "細說", "m": "小人的讒言"}, {"w": "續", "m": "延續、後繼者"}], "questions": [{"n": 5, "qtype": "單選", "stem": "溝通交涉時，說話者會自居某個角色，或讓受話者處於某個角色，以利達成目的。下列關於甲、乙的解說，最適當的是：", "options": {"A": "甲：說話者自居旁觀者的角色／乙：說話者自居當事者的角色", "B": "甲：說話者自居討人情的角色／乙：說話者自居討公道的角色", "C": "甲：受話者處於被嫉妒的角色／乙：受話者處於嫉妒人的角色", "D": "甲：受話者處於被辜負的角色／乙：受話者處於辜負人的角色"}, "answer": "D", "explain": "先抓兩段話各在「控訴誰」。甲：燭之武提醒秦穆公，秦曾經幫過晉君，晉君卻「朝濟而夕設版」翻臉不認帳，讓秦穆公覺得自己是被晉國辜負的一方。乙：樊噲說沛公「勞苦而功高」卻沒封賞，項羽還「欲誅有功之人」，等於把項羽放在辜負功臣的位置上。所以(D)正確。\n(A)燭之武是鄭國使者，本身就是當事人，只是把話說得像替秦國打算，並非旁觀者。\n(B)燭之武沒有向秦討人情，而是分析利害、離間秦晉。\n(C)兩段都沒有談到嫉妒。", "skill": "分析說服語言時，先問「說話者想讓對方覺得自己是什麼處境」，找出被點名的受害者或加害者。"}], "difficulty": "中", "label": "112學測", "year": 112, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "燭之武退秦師、鴻門宴"}, {"id": "xc112-06", "exam": "xc112", "nums": [6], "form": "單題", "img": "img/xc112-06.png", "source": "〈補江總白猿傳〉", "author": "佚名（唐傳奇）", "genre": "筆記小品", "types": ["字詞解釋", "文意推論"], "passage": "紇妻纖白，甚美。其部人曰：「將軍何為挈麗人經此？地有神，善竊少女，而美者尤所難免，宜謹護之。」紇甚疑懼，夜勒兵環其廬，匿婦密室中，謹閉甚固，而以女奴十餘伺守之。爾夕，陰風晦黑，至五更，寂然無聞。守者怠而假寐，忽若有物驚寤者，即已失妻矣。", "translation": "歐陽紇的妻子皮膚白皙、身材纖細，非常美麗。他的部下說：「將軍為什麼帶著美人經過這裡？這地方有神怪，專偷年輕女子，長得美的更是難逃一劫，應該小心保護她。」歐陽紇非常疑慮害怕，晚上派兵包圍住處，把妻子藏在密室裡，門關得嚴嚴實實，又派十幾個女僕守候在旁。那天晚上，陰風吹起，天色昏黑，到了五更，一片寂靜沒有聲響。守衛的人鬆懈打起瞌睡，忽然好像有什麼東西把他們驚醒，妻子就已經不見了。", "keywords": [{"w": "挈", "m": "攜帶"}, {"w": "尤所難免", "m": "更加難以倖免"}, {"w": "勒兵", "m": "部署、統率軍隊"}, {"w": "伺守", "m": "守候看護"}, {"w": "假寐", "m": "打瞌睡"}, {"w": "寤", "m": "睡醒"}], "questions": [{"n": 6, "qtype": "單選", "stem": "依據下文，□□內最適合填入的詞語依序是：", "options": {"A": "其來有自／疑懼／迎候", "B": "其來有自／倨傲／伺守", "C": "尤所難免／倨傲／迎候", "D": "尤所難免／疑懼／伺守"}, "answer": "D", "explain": "順著劇情走：部下警告「神怪專偷少女」，接著說美女更「尤所難免」（更逃不掉），才會推到「宜謹護之」；「其來有自」是「事情有來由」，接不上。歐陽紇聽了之後立刻派兵包圍、把妻子藏進密室，可見他是「疑懼」，不是「倨傲」（高傲不在乎）。最後讓十幾個女奴「伺守」（守在旁邊看護），而不是「迎候」（迎接等候）。所以選(D)。", "skill": "填空題先看前後句的因果：後面的行動（嚴密防守）會反過來告訴你前面的心情（害怕）。"}], "difficulty": "易", "label": "112學測", "year": 112, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc112-07", "exam": "xc112", "nums": [7], "form": "單題", "img": "img/xc112-07.png", "source": "《隨園食單‧須知單》", "author": "袁枚", "genre": "說理議論", "types": ["寫作手法", "主旨寓意"], "passage": "滿洲菜多燒煮，漢人菜多羹湯，童而習之，故擅長也。漢請滿人，滿請漢人，各用所長之菜，轉覺入口新鮮，不失邯鄲故步。今人忘其本分，而要格外討好。漢請滿人用滿菜，滿請漢人用漢菜，反致依樣葫蘆，有名無實，畫虎不成反類犬矣。秀才下場，專作自己文字，務極其工，自有遇合。若逢一宗師而摹仿之，逢一主考而摹仿之，則掇皮無真，終身不中矣。", "translation": "滿洲菜多用燒、煮，漢人菜多做羹湯，從小就學，所以拿手。漢人請滿人、滿人請漢人，各自端出自己擅長的菜，對方反而吃得新鮮，也不會像邯鄲學步那樣丟了本來的步法。現在的人忘了自己的本分，偏要特別討好客人：漢人請滿人就做滿菜，滿人請漢人就做漢菜，結果只是照樣畫葫蘆，有名無實，畫虎不成反而像狗。秀才進考場，專心寫自己的文章，力求做到最好，自然會遇到賞識的人。如果遇到一位學官就模仿他，遇到一位主考官又模仿他，那就只學到皮毛、沒有真東西，一輩子也考不上。", "keywords": [{"w": "童而習之", "m": "從小就學習它"}, {"w": "邯鄲故步", "m": "原本的步法；典出邯鄲學步"}, {"w": "遇合", "m": "遇到賞識自己的人"}, {"w": "宗師", "m": "主持考試的學官"}, {"w": "掇皮無真", "m": "只拾取表皮，沒有真實內涵"}], "questions": [{"n": 7, "qtype": "單選", "stem": "關於下文「做菜」與「作文」之間的譬喻，說明最適當的是：", "options": {"A": "學做料理須知各地菜餚特色，習文當須辨宗門流派", "B": "做菜須向前輩方家學習以精進，為文當須追摹宗師", "C": "漢人未自幼學習而做不好滿菜，學寫文章亦宜趁早", "D": "料理講究發揮個別的特長，作文亦以呈顯本色為尚"}, "answer": "D", "explain": "全文一句話：做菜和寫文章都要「做自己擅長的」。做菜是「各用所長之菜」，寫文章是「專作自己文字」，所以(D)正確。\n(A)文章沒有要人去認識各地菜色或辨別流派。\n(B)正好相反，作者批評「逢一宗師而摹仿之」會「掇皮無真」。\n(C)漢人做不好滿菜，是因為「忘其本分」去討好別人，重點不在學得早不早。", "skill": "譬喻題先找兩邊「對應的關鍵句」（各用所長／專作自己文字），再看選項有沒有說到同一件事。"}], "difficulty": "易", "label": "112學測", "year": 112, "kind": "學測", "textcat": "生活情境文本", "textcat2": "學術文本", "linked_core": ""}, {"id": "xc112-10", "exam": "xc112", "nums": [10, 11, 12], "form": "題組", "img": "img/xc112-10.png", "source": "歐陽亮〈都是星星惹的禍？木星合土星——歲星犯填星〉（第12題引《晉書》史事）", "author": "歐陽亮", "genre": "其他", "types": ["文意推論", "文化常識"], "passage": "（東晉）咸安二年正月己酉，歲星犯填星。……七月，帝疾甚，詔桓溫曰：「少子可輔者，輔之；如不可，君自取之。」賴侍中王坦之毀手詔，改使如王導輔政故事。溫聞之大怒，將誅坦之等。", "translation": "東晉咸安二年正月己酉日，木星逼近土星。……七月，皇帝病重，下詔給桓溫說：「小兒子如果值得輔佐，就輔佐他；如果不行，你就自己取代他吧。」幸好侍中王坦之撕毀了這道手詔，改成依照當年王導輔政的先例辦理。桓溫聽說後大怒，打算殺掉王坦之等人。", "keywords": [{"w": "歲星", "m": "木星"}, {"w": "填星", "m": "土星（又作鎮星）"}, {"w": "太白", "m": "金星"}, {"w": "犯", "m": "運動中的天體逼近另一天體"}, {"w": "故事", "m": "舊例、先例"}], "questions": [{"n": 10, "qtype": "單選", "stem": "談論專業知識的文章，通常預設讀者具備相關背景知識，而不加以說明。下列四個已確知的天文學知識，未被上文預設為背景知識的是：", "options": {"A": "金星的公轉速度比土星快", "B": "角分與度是測量角度的單位，1度＝60角分", "C": "清代的觀測誤差，小於宋元之際的觀測誤差", "D": "木星、土星與太陽的距離，較地球與太陽的距離遠"}, "answer": "C", "explain": "「未被預設」＝文章自己有交代。文中說木星每天頂多移動0.2度，「小於宋元之際觀測誤差，約等於清代觀測誤差」，讀者直接就能推出清代誤差比宋元小，所以(C)是文章已說明的。\n(A)文章用「太白犯填星」當例子，卻沒說金星比土星快，是預設讀者知道。\n(B)文章同時用「角分」和「度」，沒有換算，也是預設。\n(D)文章只說「外側行星」，沒說明木星、土星就是外側行星，同樣是預設。", "skill": "看到「未被預設」，就去文中找「有明說或能直接推出」的那一項。"}, {"n": 11, "qtype": "單選", "stem": "上文舉出西元828年的事例，主要是用來說明：", "options": {"A": "古代的天文記載常有國運占星色彩，故未必合乎事實", "B": "古代觀測技術不如現代精密，但保存的史料有利考證", "C": "古人無法完全依據木星、土星的移動速度判斷誰犯誰", "D": "古人只知木星、土星同向移動，不知二者會逆向靠近"}, "answer": "C", "explain": "828年的例子是：前段看起來木星追土星，後幾天卻是土星反向靠近木星；而且每天的移動量比古代觀測誤差還小，作者結論是「如果真要依據這五天的變化寫誰犯誰，古人恐怕辦不到」，所以是(C)。\n(A)這段沒談占星。\n(B)沒談史料有利考證。\n(D)文章沒說古人不知道會逆行，而是說細微變化古人測不出來。", "skill": "問「舉例用來說明什麼」，就找例子後面作者下的那句結論。"}, {"n": 12, "qtype": "單選", "stem": "上文若要介紹「古人如何從木星合土星占驗未來」，並援引下列史事，印證《開元占經》收錄的某項預言，則此預言最可能是：（引文見上）", "options": {"A": "填星與歲星合，相犯為內亂", "B": "填星所在，歲星從之，伐者利", "C": "填星與歲星合，有軍在外，戰不勝，失地", "D": "歲星與填星鬥，此謂離德，不出三月，必有亡國"}, "answer": "A", "explain": "先讀懂史事：皇帝病重，竟寫詔書說「兒子不行，你（桓溫）就自己當皇帝」，王坦之毀掉詔書，桓溫大怒想殺人——這是朝廷內部的權力鬥爭，也就是「內亂」，所以選(A)。\n(B)「伐者利」講出兵攻打的一方占便宜，史事沒有征伐。\n(C)講軍隊在外打敗仗、失去土地，史事沒有對外戰爭。\n(D)「必有亡國」，但東晉並沒有因此滅亡。", "skill": "用史事印證預言時，先把史事濃縮成一個關鍵詞（內鬥／打仗／亡國），再去對選項。"}], "difficulty": "中", "label": "112學測", "year": 112, "kind": "學測", "textcat": "科普文本", "textcat2": "", "linked_core": ""}, {"id": "xc112-15", "exam": "xc112", "nums": [15, 16, 17], "form": "題組", "img": "img/xc112-15.png", "source": "洪繻〈籌海議〉", "author": "洪繻（洪棄生）", "genre": "說理議論", "types": ["文意推論", "主旨寓意"], "passage": "我果戰士有勇，大將有謀，成算在胸，地利足恃，猶不如誘之登岸而設伏殲之。不然，汪洋海上以數百人操一舟，東馳西突，以角逐於勝負不可知之地，我即無恙，而彼之所挾者小，我之所勞者大，設防設守，形勢不亦懣乎！然誘之上岸，非有成算，則斷不可。蓋敵一登陸，民心易動，軍心易震，非宿將強兵不能得手也。生，臺人也，為臺灣計，臺北可誘之近岸，臺南則不可。蓋臺北港道深通而有屏蔽，彼之駐輪甚便；若登岸，則反失所恃。臺南則港門雖深，風浪甚苦，四圍無山，港中非可駐輪；彼不登岸，不能久居也。若臺中諸港，沙線淺灘，難駛鐵船。然澎湖不守，則敵人得之，安穩收泊。有時展輪四掠，有時載小艇窺闖，臺中難防，臺南、北亦可慮。", "translation": "我軍如果真的士兵勇敢、將領有謀略，胸中有勝算，又有地利可以依靠，那還不如引誘敵人登岸，再埋伏把他們消滅。否則在茫茫大海上，用幾百人操作一艘船，東奔西闖，在勝負難料的地方爭鬥，就算我方沒有損失，敵人付出的小，我方付出的大，到處設防，情勢不是很令人煩悶嗎！但是引誘敵人上岸，如果沒有必勝的把握，就絕對不行。因為敵人一登陸，民心容易動搖，軍心容易震恐，不是老練的將領和精強的軍隊無法得手。我是臺灣人，替臺灣打算：臺北可以引誘敵人靠近岸邊，臺南就不行。因為臺北港道深而通暢，又有屏障，敵艦停泊很方便；如果他們登岸，反而失去了依靠。臺南港口雖深，風浪卻很大，四周沒有山，港中無法停泊船艦；敵人不登岸，就不能久留。至於臺中各港，沙洲淺灘多，鐵甲船難以行駛。然而如果澎湖守不住，敵人佔領了它，就能安穩停泊，有時開船四處劫掠，有時用小船來窺探闖入，臺中難以防守，臺南、臺北也令人擔憂。", "keywords": [{"w": "成算", "m": "預定的計畫、必勝的把握"}, {"w": "所挾者", "m": "所憑藉、付出的"}, {"w": "懣", "m": "煩悶"}, {"w": "宿將", "m": "經驗豐富的老將"}, {"w": "駐輪", "m": "停泊輪船"}, {"w": "沙線", "m": "沙洲"}], "questions": [{"n": 15, "qtype": "單選", "stem": "關於上文對清末臺灣攻守情勢的分析，敘述最適當的是：", "options": {"A": "基於後勤準備已充足而可誘敵深入", "B": "由海戰與陸戰兩方面揭示敵我利弊", "C": "因船艦操作耗人力而主張放棄海戰", "D": "從軍民齊心的優勢判斷可無懼陸戰"}, "answer": "B", "explain": "作者先講海戰：在海上纏鬥「彼之所挾者小，我之所勞者大」，對我不利；再講陸戰：誘敵登岸可以設伏，但「民心易動，軍心易震」，沒有把握不可輕試。兩邊的利害都說了，所以(B)正確。\n(A)「戰士有勇……成算在胸」是假設語氣（果＝如果），沒說準備已充足。\n(C)作者沒主張放棄海戰，還提醒要守住澎湖。\n(D)文中正好說登陸後民心、軍心容易動搖，不是軍民齊心。", "skill": "看到「果……猶……」「非……則斷不可」這類條件句，要分清楚是假設還是事實。"}, {"n": 16, "qtype": "單選", "stem": "關於①、②是否符合上文看法，最適當的研判是：①應加強澎湖海防，避免敵軍入侵臺北、臺中、臺南三地。②依臺北、臺南地形評估，引誘敵軍自臺北登岸，是可行的戰略。", "options": {"A": "①、②皆符合", "B": "①符合，②不符合", "C": "①符合，②無法判斷", "D": "①無法判斷，②符合"}, "answer": "A", "explain": "①符合：文末說「澎湖不守」，敵人就能安穩停泊，四處侵擾，臺中難防，臺南、臺北也令人擔憂，所以應加強澎湖防守。②符合：作者比較兩地地形——臺北「港道深通而有屏蔽」，敵艦停泊方便，在海上占優勢，但敵人「若登岸，則反失所恃」，所以「臺北可誘之近岸」；臺南風浪大、無處停泊，敵人本來就非登岸不可，所以「臺南則不可」。可見引誘敵軍從臺北登岸，讓他失去船艦的依靠，是可行的戰略。答案(A)。", "skill": "評估戰略類文意，抓住「彼之所恃」：讓敵人離開他的優勢所在，就是作者推薦的做法。"}, {"n": 17, "qtype": "單選", "stem": "若依據上文設計一款戰爭攻略遊戲「海戰1894」，遊戲腳本中，根據不同的項目，會讓敵我雙方戰力值互有增減。設計者為此遊戲設定的戰力值項目最不可能出現：", "options": {"A": "將士經驗", "B": "地理環境", "C": "攻守路線", "D": "外援力量"}, "answer": "D", "explain": "把文中提到的影響因素列出來：「宿將強兵」是將士經驗(A)；港道深淺、有無屏蔽、沙線淺灘是地理環境(B)；誘敵登岸、守澎湖是攻守路線(C)。全文完全沒提到別國援助，所以最不可能出現的是(D)外援力量。", "skill": "「最不可能」題，先把文中出現的因素一條條勾掉，剩下的就是答案。"}], "difficulty": "中", "label": "112學測", "year": 112, "kind": "學測", "textcat": "延伸", "textcat2": "學術文本", "linked_core": "鹿港乘桴記"}, {"id": "xc112-18", "exam": "xc112", "nums": [18, 19, 20], "form": "題組", "img": "img/xc112-18.png", "source": "陸游〈跋李莊簡公家書〉", "author": "陸游", "genre": "書信序跋", "types": ["人物情感", "寫作手法", "文意推論"], "passage": "李丈參政罷政歸鄉里時，某年二十矣。時時來訪先君，劇談終日。每言秦氏，必曰「咸陽」，憤切慨慷，形於色辭。一日平旦來共飯，謂先君曰：「聞趙相過嶺，悲憂出涕。僕不然，謫命下，青鞋布襪行矣，豈能作兒女態耶！」方言此時，目如炬，聲如鐘，其英偉剛毅之氣，使人興起。後四十年，偶讀公家書，雖徙海表，氣不少衰，叮嚀訓誡之語，皆足垂範百世，猶想見其道青鞋布襪時也。淳熙戊申五月己未，笠澤陸某題。", "translation": "李參政（李光）罷官回到家鄉時，我二十歲。他常常來拜訪先父，暢談一整天。每次談到秦檜，一定稱他為「咸陽」，悲憤激昂，表現在臉色和言辭上。有一天清早來我家一起吃飯，對先父說：「聽說趙丞相（趙鼎）被貶過五嶺時，悲傷憂愁到流淚。我可不會這樣，貶謫的命令一下，我穿上青鞋布襪就上路了，怎麼能像小孩子婦人一樣哭哭啼啼呢！」他說這話的時候，目光像火炬，聲音像洪鐘，那種英武剛毅的氣概，讓人精神振奮。四十年後，我偶然讀到李公的家書，他雖然被貶到海外，氣概一點也沒衰減，信中叮嚀教誨的話，都足以作為百世的典範，讓我彷彿又看到他說「青鞋布襪」時的樣子。淳熙戊申年五月己未日，笠澤陸游題。", "keywords": [{"w": "丈", "m": "對長輩的尊稱"}, {"w": "某", "m": "作者自稱"}, {"w": "先君", "m": "已過世的父親"}, {"w": "劇談", "m": "暢談"}, {"w": "咸陽", "m": "秦朝都城，借指秦檜"}, {"w": "過嶺", "m": "越過五嶺，指貶謫嶺南"}, {"w": "興起", "m": "感奮振作"}, {"w": "海表", "m": "海外，指偏遠之地"}], "questions": [{"n": 18, "qtype": "單選", "stem": "關於文中李參政的敘述，最適當的是：", "options": {"A": "少年得志，但因個性耿介，二十歲便罷政而歸鄉里", "B": "常至陸游家，議論秦朝暴政虐民、聚斂咸陽的史事", "C": "雖貶謫海表而坦然赴任，未嘗悲憂，英氣絲毫不減", "D": "訓誨陸游之言響若鐘鳴，示現剛毅氣節，令人激昂"}, "answer": "C", "explain": "李光自己說「謫命下，青鞋布襪行矣，豈能作兒女態耶」，四十年後陸游讀他的家書，也說「雖徙海表，氣不少衰」，所以(C)正確。\n(A)「某年二十」的「某」是陸游自稱，二十歲的是陸游，不是李光。\n(B)「秦氏」指秦檜，「咸陽」是李光拿秦都來暗諷秦檜，不是談秦朝歷史。\n(D)「聲如鐘」的那番話是對陸游的父親說的，而且是在說自己面對貶謫的態度，不是訓誨陸游。", "skill": "古文中的「某」「僕」「先君」等稱謂要先搞清楚指誰，人物就不會張冠李戴。"}, {"n": 19, "qtype": "單選", "stem": "關於文中陸游的行為或感懷的敘述，最適當的是：", "options": {"A": "相隔四十年後，因重讀李莊簡公來信而為文回覆", "B": "採用書序體書寫方式，闡述自己撰作本文的動機", "C": "憶及青鞋布襪之言而連結今昔，流露對李公的欽仰", "D": "追述昔日共聚議事的情景，感嘆故人遠謫而難再見"}, "answer": "C", "explain": "文末「猶想見其道青鞋布襪時也」，把四十年後讀家書的感受和年輕時聽到的豪語連在一起，又稱讚家書「皆足垂範百世」，充滿敬佩，所以(C)正確。\n(A)本文是題在家書後面的「跋」，不是回信；而且家書是李光寫給家人的。\n(B)跋是題寫在別人作品後面的文字，本文寫的是對李光的追憶，沒有說明自己寫作動機。\n(D)當年是「劇談」，不是議事；文中也沒有感嘆難再相見。", "skill": "題跋類文章：常是「讀某件東西→想起某人某事→表達評價或感受」，抓住今昔連結的那一句。"}, {"n": 20, "qtype": "單選", "stem": "上文藉細節描述，展現李參政的人格特質。下列文句，亦透過書寫細節以呈現人物性格特質的是：", "options": {"A": "將軍向寵，性行淑均，曉暢軍事，試用於昔日，先帝稱之曰「能」", "B": "樊噲側其盾以撞，衛士仆地，噲遂入。披帷，西嚮立，瞋目視項王", "C": "行次靈石旅舍，既設床，爐中烹肉且熟，張氏以髮長委地，立梳床前", "D": "三人移席，漸入月中。眾視三人坐月中飲，鬚眉畢見，如影之在鏡中"}, "answer": "B", "explain": "題目要的是「用具體細節」帶出「性格」。(B)寫樊噲側盾撞倒衛士、闖帳、站定、瞪著項羽，一連串動作細節，把他的勇猛無畏寫活了。\n(A)「性行淑均，曉暢軍事」是直接評價，沒有細節描寫。\n(C)寫紅拂女長髮垂地、站著梳頭，是外貌與場景，沒有表現性格。\n(D)寫月光下飲酒、鬍鬚眉毛清楚可見，是畫面描寫，不在表現個性。", "skill": "分辨「直接評價」（說他很好）和「細節描寫」（寫他做了什麼動作），再看細節是否指向性格。"}], "difficulty": "中", "label": "112學測", "year": 112, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc112-21", "exam": "xc112", "nums": [21, 22], "form": "題組", "img": "img/xc112-21.png", "source": "葉嘉瑩《論語百則‧前言》（選項引《論語》）", "author": "葉嘉瑩", "genre": "經典語錄", "types": ["典故出處", "文意推論"], "passage": "（選項為《論語》原句）\n食夫稻，衣夫錦，於女安乎？（〈陽貨〉）\n士志於道，而恥惡衣惡食者，未足與議也。（〈里仁〉）\n色惡不食，臭惡不食，失飪不食，不時不食。（〈鄉黨〉）\n菲飲食，而致孝乎鬼神；惡衣服，而致美乎黻冕。（〈泰伯〉）\n貧而樂，富而好禮。如切如磋，如琢如磨。（〈學而〉）", "translation": "吃白米飯、穿錦緞衣服（守喪期間），你心安嗎？\n讀書人立志追求真理，卻以穿得差、吃得差為恥，這種人不值得和他談論道理。\n顏色難看的不吃，氣味難聞的不吃，烹調不當的不吃，不合時令的不吃。\n（禹）自己吃得很簡單，卻用豐盛的祭品孝敬鬼神；自己穿得很差，卻把祭祀時的禮服禮帽做得很華美。\n貧窮卻快樂，富有卻愛好禮節。像切磋骨角、琢磨玉石一樣精益求精。", "keywords": [{"w": "恥惡衣惡食", "m": "以粗劣的衣食為羞恥"}, {"w": "未足與議", "m": "不值得和他討論"}, {"w": "菲", "m": "微薄"}, {"w": "黻冕", "m": "祭祀時的禮服禮帽"}, {"w": "興", "m": "由詩引發感動、聯想"}], "questions": [{"n": 21, "qtype": "單選", "stem": "依據文意，最適合填入上文________處的文句是：", "options": {"A": "食夫稻，衣夫錦，於女安乎", "B": "士志於道而恥惡衣惡食者，未足與議也", "C": "色惡不食，臭惡不食，失飪不食，不時不食", "D": "菲飲食，而致孝乎鬼神；惡衣服，而致美乎黻冕"}, "answer": "B", "explain": "作者穿補丁衣、吃難嚥的混合麵卻「不以為苦」，靠的是一句給她精神力量、讓她不在意物質貧乏的話。(B)說「有志於道的人不該以粗衣惡食為恥」，最能支撐她。\n(A)是孔子責問宰我守喪不滿三年卻吃好穿好，談的是孝與心安。\n(C)是孔子講究飲食的生活習慣，跟安於貧苦相反。\n(D)是稱讚大禹自奉儉約卻重視祭祀，重點在敬鬼神，不是在貧困中自我安頓。", "skill": "文白對讀填空：先用白話找出「情境＋需要的態度」（貧苦→不以為苦），再挑出講同一種態度的古文。"}, {"n": 22, "qtype": "單選", "stem": "下列敘述，最符合上文體會或想法的是：", "options": {"A": "熟誦經典可將文章的深意烙印腦中，是對當代學子有益的教育方式", "B": "《論語》與《詩經》、「四書」中的語句，可透過聯想體悟相印證", "C": "孔門教學注重興發，子貢因以修養之道闡明詩句涵義而受孔子讚賞", "D": "讀書之樂來自探求作品真實體驗，進而連結經典以形成興感的力量"}, "answer": "B", "explain": "作者由《論語》句子「聯想到『四書』中的其他語句」，又舉子貢由修養之語聯想到《詩經》，說這種「融會貫通的聯想和體悟」最可貴，所以(B)正確。\n(A)作者只說自己早年受背誦教育，沒有主張這對當代學子有益，而且說「無論懂與不懂」，並非把深意烙印腦中。\n(C)方向顛倒：子貢是由修養之道聯想到詩句，不是用修養去解釋詩句。\n(D)作者說讀書之樂是體會「可以提昇人精神的力量」，不是探求作品的真實體驗。", "skill": "留意「A聯想到B」與「用A解釋B」的方向差異，選項常在這裡偷換。"}], "difficulty": "中", "label": "112學測", "year": 112, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc112-23", "exam": "xc112", "nums": [23, 24, 25], "form": "題組", "img": "img/xc112-23.png", "source": "黃楷元〈陪蘇東坡一起吃檳榔〉、焦桐〈禁忌的親密關係〉（引《鶴林玉露》、《嶺外代答》、《本草綱目》）", "author": "黃楷元、焦桐", "genre": "其他", "types": ["比較閱讀", "文意推論", "寫作手法"], "passage": "甲（引文）：能消瘴癘暖如薰（蘇軾詩）。不可一日無此君矣（羅大經《鶴林玉露》）。有嘲廣人曰：「路上行人口似羊。」言以蔞葉雜咀，終日噍飼也，曲盡噉檳榔之狀矣。每逢人，則黑齒朱唇；數人聚會，則朱殷遍地，實可厭惡。（周去非《嶺外代答》）\n乙（引文）：嶺南人以檳榔代茶禦瘴，其功有四：一曰醒能使之醉，蓋食之久，則醺然頰赤，若飲酒然，蘇東坡所謂「經潮登頰醉檳榔」也。二曰醉能使之醒，蓋酒後嚼之，則寬氣下痰，餘酲頓解，朱晦庵所謂「檳榔收得為祛痰」也。三曰飢能使之飽。四曰飽能使之飢。蓋空腹食之，則充然氣盛如飽；飽後食之，則飲食快然易消。又且賦性疏通而不泄氣，稟味嚴正而更有餘甘。（李時珍《本草綱目》）", "translation": "甲：（檳榔）能消除瘴氣，讓人暖得像被薰過。一天也少不了它。有人嘲笑廣東人說：「路上的行人嘴巴像羊。」意思是把蔞葉和檳榔一起嚼，整天嚼個不停，把吃檳榔的樣子形容得淋漓盡致。每次遇到人，都是黑牙紅唇；幾個人聚在一起，地上就一片暗紅，實在令人厭惡。\n乙：嶺南人用檳榔代替茶來抵禦瘴氣，它的功效有四種：一是清醒時能讓人醉，因為吃久了臉頰會發紅，像喝了酒，就是蘇東坡說的「紅潮上臉，醉於檳榔」；二是醉時能讓人醒，因為酒後嚼它可以順氣化痰，殘留的醉意立刻消解，就是朱熹說的「檳榔收來可以祛痰」；三是飢餓時能讓人飽；四是吃飽時能讓人餓。因為空腹吃，會覺得氣足像吃飽；飽後吃，食物就容易消化。而且它的性質疏通卻不會使氣外洩，味道嚴正卻帶有回甘。", "keywords": [{"w": "瘴癘", "m": "南方濕熱地區的疫病之氣"}, {"w": "噍", "m": "嚼"}, {"w": "朱殷", "m": "暗紅色"}, {"w": "酲", "m": "酒醉未醒"}, {"w": "祛痰", "m": "去除痰液"}], "questions": [{"n": 23, "qtype": "單選", "stem": "綜合甲、乙二文，關於檳榔的功效或危害，說明最適當的是：", "options": {"A": "賦性疏通而不泄氣，有益調節呼吸系統，嶺南用以對抗瘴氣", "B": "李時珍認同朱晦庵檳榔可祛痰的看法，咀嚼檳榔有助於醒酒", "C": "所含多酚類化合物具雙向調節的作用，既可充飢又可助消化", "D": "世界衛生組織證實檳榔鹼會刺激腎上腺素分泌，致食用成癮"}, "answer": "B", "explain": "李時珍說「醉能使之醒」，並引朱熹「檳榔收得為祛痰」來佐證，代表他認同；酒後嚼之「餘酲頓解」，就是醒酒，所以(B)正確。\n(A)「賦性疏通而不泄氣」是講檳榔的性質，文中沒說它能調節呼吸系統。\n(C)飢飽雙向作用是李時珍的說法，文中並沒有把它歸功於多酚類化合物。\n(D)世界衛生組織證實的是「潛在致癌性」；刺激腎上腺素是另一句的內容，也沒說它導致成癮。", "skill": "綜合題最常見的陷阱是「把A說的接到B的身上」，每個說法都要回頭確認是誰說的、說了什麼。"}, {"n": 24, "qtype": "單選", "stem": "關於甲、乙二文的寫作方式，說明最適當的是：", "options": {"A": "甲文就歷史發展評論，認為嚼檳榔有礙觀瞻而不鼓勵食用", "B": "乙文兼論檳榔功效與危害，呼籲人們抗拒檳榔的危險誘惑", "C": "二文皆引述相關的文學創作與醫療知識，呈現檳榔多面性", "D": "二文皆提及食用者親身經驗，點出嚼食檳榔後的成癮現象"}, "answer": "D", "explain": "甲文引羅大經住了一年多後「不可一日無此君矣」；乙文作者自述「嚼食經驗令我覺得檳榔很容易成癮」，兩文都有食用者的親身經驗，也都指出上癮，所以(D)正確。\n(A)甲文是羅列古人的不同態度，「實可厭惡」是周去非的看法，不是甲文作者的評論主張。\n(B)乙文最後只說自己的矛盾感受，並沒有呼籲大家抗拒。\n(C)甲文引的是詩文與筆記，沒有醫療知識。", "skill": "「二文皆……」的選項，要兩篇都各找到證據才算對。"}, {"n": 25, "qtype": "單選", "stem": "下列詩句畫線處所敘述的檳榔作用，甲文或乙文中未提及的是：（畫線處：(A)益精神 (B)解紛惟有送檳榔 (C)淨口舐 (D)淡可療飢）", "options": {"A": "登頰紅潮增嫵媚，潤脾津液益精神", "B": "一抹腮紅還舊好，解紛惟有送檳榔", "C": "有時食鮆苦羶腥，也須細嚼淨口舐", "D": "淡可療飢醫苦口，津能分潤滴枯腸"}, "answer": "B", "explain": "逐一比對：(A)「益精神」對應乙文「提高警覺度」；(C)「淨口」去腥，對應乙文飽後食之「飲食快然易消」、「更有餘甘」的清口作用；(D)「療飢」對應「飢能使之飽」。只有(B)「送檳榔來化解糾紛」是社交上的用途，兩文都沒提到（乙文只說用來待客），所以選(B)。", "skill": "「未提及」題：把每個畫線作用翻成白話功能，再回文中一一配對，配不到的就是答案。"}], "difficulty": "中", "label": "112學測", "year": 112, "kind": "學測", "textcat": "科普文本", "textcat2": "生活情境文本", "linked_core": ""}, {"id": "xc112-26", "exam": "xc112", "nums": [26], "form": "單題", "img": "img/xc112-26.png", "source": "《論語》、韓愈〈師說〉、《左傳》、蒲松齡〈勞山道士〉、《莊子‧養生主》、《史記‧項羽本紀》、袁宏道〈晚遊六橋待月記〉、歸有光〈項脊軒志〉等", "author": "多家", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)克己復禮為仁／師道之不復可知矣\n(B)微夫人之力不及此／奔而入，及牆，虛若無物\n(C)蓋藏既富，絃誦興焉／既親其所親，亦親其所疏\n(D)為之躊躇滿志，善刀而藏之／（項伯）素善留侯張良\n(E)余時為桃花所戀，竟不忍去湖上／久不見若影，何竟日默默在此", "translation": "(A)克制自己、回復到禮就是仁／從師的風氣不能恢復，由此可知了\n(B)如果沒有那個人的力量，我不會到這個地步／跑著衝進去，到了牆邊，牆好像空無一物\n(C)積蓄已經富足，讀書的風氣就興起了／既然親愛自己所親近的人，也要親愛自己所疏遠的人\n(D)因此心滿意足，把刀擦乾淨收起來／項伯向來和張良交好\n(E)我當時被桃花吸引，竟然捨不得離開西湖／很久沒看到你的身影，為什麼整天默默待在這裡", "keywords": [{"w": "復", "m": "回復、恢復"}, {"w": "及", "m": "到達"}, {"w": "善刀", "m": "擦拭刀子"}, {"w": "素善", "m": "向來交好"}, {"w": "竟日", "m": "整天"}], "questions": [{"n": 26, "qtype": "多選", "stem": "下列各組「」內的詞，意義前後相同的是：", "options": {"A": "克己「復」禮為仁／師道之不「復」可知矣", "B": "微夫人之力不「及」此／奔而入，「及」牆，虛若無物", "C": "蓋藏「既」富，絃誦興焉／「既」親其所親，亦親其所疏", "D": "為之躊躇滿志，「善」刀而藏之／（項伯）素「善」留侯張良", "E": "余時為桃花所戀，「竟」不忍去湖上／久不見若影，何「竟」日默默在此"}, "answer": "AB", "explain": "(A)對：兩個「復」都是「回復、恢復」。克己復禮＝回到禮；師道不復＝從師之道不能恢復。\n(B)對：兩個「及」都是「到達」。不及此＝不會到這地步；及牆＝到了牆邊。\n(C)錯：前者「既」是「已經」（積蓄已經富足）；後者「既……亦……」是「既然／不但……也……」的連接用法。\n(D)錯：前者「善」通「繕」，擦拭；後者是「交好、友好」。\n(E)錯：前者「竟」是「竟然、終究」；後者「竟日」是「整天、全天」。", "skill": "一詞多義題，把字放回原句換成白話試讀，讀得通的意思才是答案；熟課文例句要背。"}], "difficulty": "中", "label": "112學測", "year": 112, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "鴻門宴、師說、項脊軒志、晚遊六橋待月記、勞山道士"}, {"id": "xc112-27", "exam": "xc112", "nums": [27], "form": "單題", "img": "img/xc112-27.png", "source": "〈虬髯客傳〉、陶淵明〈桃花源記〉、范仲淹〈岳陽樓記〉、諸葛亮〈出師表〉、《史記‧項羽本紀》", "author": "多家", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "(A)侍婢羅列，頗僭於上\n(B)漁人甚異之，復前行\n(C)滿目蕭然，感極而悲者矣\n(D)蓋追先帝之殊遇，欲報之於陛下也\n(E)行略定秦地，函谷關有兵守關，不得入", "translation": "(A)侍女成排站著，排場很是超越了皇帝\n(B)漁人覺得非常奇怪，又往前走\n(C)放眼一片蕭條，感慨到了極點而悲傷起來\n(D)是因為追念先帝特別的禮遇，想要報答在陛下身上\n(E)一路攻取平定秦地，函谷關有士兵把守，進不去", "keywords": [{"w": "頗", "m": "很、相當"}, {"w": "僭", "m": "超越本分"}, {"w": "甚", "m": "非常"}, {"w": "殊", "m": "特殊的（形容詞）"}, {"w": "略", "m": "奪取、攻占（動詞）"}], "questions": [{"n": 27, "qtype": "多選", "stem": "「稍微哭一下，就不得了啦，戲也不演啦」，句中「稍微」用來修飾動詞「哭」，表示哭的程度。下列文句「」內的詞，用來修飾動詞，表示動作程度的是：", "options": {"A": "侍婢羅列，「頗」僭於上", "B": "漁人「甚」異之，復前行", "C": "滿目蕭然，感「極」而悲者矣", "D": "蓋追先帝之「殊」遇，欲報之於陛下也", "E": "行「略」定秦地，函谷關有兵守關，不得入"}, "answer": "ABC", "explain": "(A)對：「頗」＝很，修飾動詞「僭」（超越本分），表示僭越的程度。\n(B)對：「甚」＝非常，修飾「異」（覺得奇怪），表示程度。\n(C)對：「感極」＝感慨到了極點，「極」說明「感」的程度。\n(D)錯：「殊遇」是「特殊的待遇」，「殊」修飾名詞「遇」，是形容詞。\n(E)錯：「略」在這裡是「攻取」的意思，和「定」並列成動詞「略定」，不是「稍微」。", "skill": "判斷是不是程度副詞：把它換成「很／非常／稍微／極」試試，再確認它後面接的是動詞還是名詞。"}], "difficulty": "中", "label": "112學測", "year": 112, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "鴻門宴、出師表、桃花源記、虬髯客傳、岳陽樓記"}, {"id": "xc112-29", "exam": "xc112", "nums": [29], "form": "單題", "img": "img/xc112-29.png", "source": "《論衡‧吉驗》", "author": "王充", "genre": "其他", "types": ["句意理解", "文意推論"], "passage": "北夷橐離國王侍婢有娠，王欲殺之。婢對曰：「有氣大如雞子，從天而下，我故有娠。」後產子，捐於豬溷中，豬以口氣噓之不死；復徙置馬欄中，欲使馬藉殺之，馬復以口氣噓之不死。王疑以為天子，令其母收取奴畜之。名東明，令牧牛馬。東明善射，王恐奪其國也，欲殺之。東明走，南至掩淲水，以弓擊水，魚鱉浮為橋，東明得渡。魚鱉解散，追兵不得渡。因都王夫餘，故北夷有夫餘國焉。", "translation": "北方橐離國國王的侍女懷孕了，國王想殺她。侍女回答：「有一團像雞蛋那麼大的氣從天而降，我因此懷孕。」後來生下兒子，國王把他丟到豬圈裡，豬用嘴呼氣暖他，他沒有死；又把他移到馬廄裡，想讓馬踩死他，馬也用嘴呼氣暖他，他還是沒死。國王懷疑他是上天的兒子，就叫他母親收養，把他當奴僕養著。取名東明，叫他放牧牛馬。東明擅長射箭，國王怕他奪取自己的國家，想殺他。東明逃走，往南到了掩淲水，用弓拍打水面，魚和鱉浮上來搭成橋，東明得以渡河。魚鱉散開，追兵過不了河。東明於是在夫餘建都稱王，所以北方有夫餘國。", "keywords": [{"w": "娠", "m": "懷孕"}, {"w": "捐", "m": "拋棄"}, {"w": "溷", "m": "豬圈"}, {"w": "噓", "m": "吐氣、呵氣"}, {"w": "藉", "m": "踐踏"}, {"w": "奴畜之", "m": "像奴僕一樣養他"}], "questions": [{"n": 29, "qtype": "多選", "stem": "關於「夫餘國王」的事蹟，符合下文敘述的是：", "options": {"A": "為橐離國王和侍婢所生，因其出生時間而被命名為東明", "B": "曾被棄於豬圈馬槽，不僅未受傷害且受到豬馬呼氣照護", "C": "其母為侍婢而被視為奴僕，後因善騎射被派去放牧牛馬", "D": "為救母而謀反，事敗後南向逃至夫餘，於是成立夫餘國", "E": "逃避追殺至河邊時，魚鱉浮出讓他踩踏而渡，得以免難"}, "answer": "BE", "explain": "(A)錯：侍婢說是天上的氣讓她懷孕，並非國王所生；文中也沒說名字由來。\n(B)對：「捐於豬溷中，豬以口氣噓之不死」，馬欄中「馬復以口氣噓之不死」。\n(C)錯：「奴畜之」是把東明當奴僕養；他被派去牧牛馬在先，「善射」是後來寫的，且導致國王想殺他，不是派他放牧的原因。\n(D)錯：沒有救母、謀反的情節，是國王怕他奪國而要殺他。\n(E)對：「以弓擊水，魚鱉浮為橋，東明得渡」。", "skill": "敘事題照時間順序畫出事件鏈（懷孕→棄養→收養→善射→被追殺→渡河→建國），選項的因果一對就知道對錯。"}], "difficulty": "易", "label": "112學測", "year": 112, "kind": "學測", "textcat": "文學文本", "textcat2": "", "linked_core": ""}, {"id": "xc112-31", "exam": "xc112", "nums": [31, 32], "form": "題組", "img": "img/xc112-31.png", "source": "馬致遠〈撥不斷〉、白樸〈寄生草‧飲〉；徐平〈一個屈原，各自表述〉", "author": "馬致遠、白樸", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀", "典故出處"], "passage": "甲：菊花開，正歸來。伴虎溪僧鶴林友龍山客，似杜工部陶淵明李太白，有洞庭柑東陽酒西湖蟹。哎！楚三閭休怪。（馬致遠〈撥不斷〉）\n乙：長醉後妨何礙？不醒時有甚思？糟醃兩個功名字，醅渰千古興亡事，麴埋萬丈虹霓志。不達時皆笑屈原非，但知音盡說陶潛是。（白樸〈寄生草〉）", "translation": "甲：菊花盛開，我正好辭官歸來。陪伴我的是虎溪的高僧、鶴林的朋友、龍山的賓客，像杜甫、陶淵明、李白那樣的人；有洞庭的柑橘、東陽的美酒、西湖的螃蟹。唉！楚國的三閭大夫屈原啊，請不要怪我（不學你）。\n乙：長醉之後有什麼妨礙？不清醒時還有什麼好想的？用酒糟醃掉「功名」兩個字，用濁酒淹沒千古的興亡事，用酒麴埋葬萬丈高的遠大志向。不懂時勢的人都笑屈原錯了，但真正懂的人都說陶潛對。", "keywords": [{"w": "楚三閭", "m": "屈原，曾任三閭大夫"}, {"w": "糟、醅、麴", "m": "酒糟、未過濾的酒、酒麴，皆指酒"}, {"w": "渰", "m": "同「淹」"}, {"w": "虹霓志", "m": "遠大的志向"}, {"w": "不達時", "m": "不通達時務的人"}], "questions": [{"n": 31, "qtype": "多選", "stem": "關於甲、乙二曲的寫作手法，敘述適當的是：", "options": {"A": "甲曲以「菊花開，正歸來」，點出當時非如屈原身處的亂世", "B": "乙曲以糟醃、醅渰、麴埋，把萬事可隨一醉泯滅加以形象化", "C": "甲曲在飲酒食蟹中流露閒居之趣，乙曲在醉醒間隱含矛盾之情", "D": "二曲皆藉嘲諷屈原的結局，表現出滑稽幽默的輕鬆與玩世態度", "E": "二曲皆以陶潛對比屈原，說明自身生命選擇或價值判斷的傾向"}, "answer": "BCE", "explain": "(A)錯：「菊花開，正歸來」是點出歸隱的時節，像陶淵明採菊東籬，不是在說時代太平。\n(B)對：用醃、淹、埋三個動作，把功名、興亡、壯志通通「泡進酒裡」，抽象的「一醉忘懷」變得具體。\n(C)對：甲曲柑、酒、蟹、好友，是悠閒的隱居生活；乙曲「長醉」「不醒」看似灑脫，其實是放不下才要用酒埋掉，藏著矛盾苦悶。\n(D)錯：甲曲「楚三閭休怪」是向屈原致意說抱歉；乙曲表面曠達、底下有憤懣，都不是輕鬆玩世地嘲笑屈原。\n(E)對：甲曲把自己比作陶淵明並向屈原說「休怪」，乙曲直接說「笑屈原非」「陶潛是」，都用陶、屈對照表明自己選擇歸隱。", "skill": "元曲常用「屈原（執著）vs. 陶潛（歸隱）」對照，看到這兩人並列，就想到作者在表態人生選擇。"}, {"n": 32, "qtype": "多選", "stem": "依據甲、乙二曲和丙文，關於歷代對屈原的看法，敘述適當的是：", "options": {"A": "漢代對屈原的爭辯，在其作品情感的表達方式是否優於《詩經》", "B": "宋代時關注屈原愛國之心，從民族情操的角度使怨君問題合理化", "C": "元代文人喜借用屈原典故，說明自己雖然歸隱卻待時而動的心境", "D": "明代時有與屈原相似際遇的人，將自身認同投射到屈原的遭遇上", "E": "現代的各種文化語境中，詮釋屈原既保有過去面向也有時代新意"}, "answer": "BDE", "explain": "(A)錯：漢代爭議在「怨君」是否合乎儒家「樂而不淫，哀而不傷」的中庸，不是比較是否優於《詩經》。\n(B)對：丙文說宋人轉而強調屈原愛國，「確立屈原情感的正當性」。\n(C)錯：甲、乙二曲是借屈原表明自己選擇歸隱、醉中忘世，沒有「待時而動」。\n(D)對：黃文煥蒙冤下獄，對屈原感同身受，著書為屈原辯護。\n(E)對：抗戰時再強調愛國（延續宋代面向），又新添「詩人何為」、理想與世界衝突的思考。", "skill": "跨文本整合題，把選項按朝代對回文中段落，一段一段核對關鍵詞。"}], "difficulty": "難", "label": "112學測", "year": 112, "kind": "學測", "textcat": "文學文本", "textcat2": "延伸", "linked_core": "漁父"}, {"id": "xc112-35", "exam": "xc112", "nums": [35], "form": "單題", "img": "img/xc112-35.png", "source": "許潮《赤壁遊》雜劇", "author": "許潮", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感", "文意推論"], "passage": "〔生〕今山水星月，相照若昔，而英雄何寥寥也！吾四人遊賞於此，幸各能詩。可將曹孟德、孫仲謀、劉玄德、周公瑾，寫作四鬮，各拈取一鬮，吟詩一首，以見弔古斷案。〔眾〕最好！最好！……〔生〕我等吟詠已完，可斟酒來。各照題目，嘆他一番。……（黃鶯兒）〔生〕躍馬意何長，視東吳已入囊，舳艫千里旌旗望。橫槊時氣揚，釃酒時態狂，誰知一火把神魂喪！〔合〕嘆興亡，江山如故，何處覓曹郎？……（祝英台）〔生〕把古今愁，廊廟悶，聊付與滄浪。", "translation": "〔蘇軾〕如今山水星月，和從前一樣相互輝映，可是英雄怎麼這樣稀少啊！我們四人在這裡遊賞，幸好都會作詩。可以把曹操、孫權、劉備、周瑜寫成四張籤，每人抽一張，各作一首詩，來表達憑弔古人、評斷是非的看法。〔眾人〕太好了！太好了！……〔蘇軾〕我們都吟詠完了，拿酒來。各自依照題目，感嘆他一番。……〔蘇軾唱〕（曹操）躍馬揚鞭志向多麼遠大，把東吳看成囊中之物，千里戰船首尾相接，旌旗遙望。橫握長矛時意氣飛揚，灑酒祭江時神態狂放，誰知一把火就讓他魂飛魄散！〔合唱〕感嘆興亡，江山依舊，哪裡還找得到曹操呢？……〔蘇軾唱〕把古往今來的愁、朝廷政事的煩悶，姑且都交付給滄浪之水吧。", "keywords": [{"w": "鬮", "m": "抽籤用的紙團"}, {"w": "拈", "m": "用手指取"}, {"w": "弔古斷案", "m": "憑弔古人並下評斷"}, {"w": "舳艫", "m": "首尾相接的船隻"}, {"w": "槊", "m": "長矛"}, {"w": "釃酒", "m": "斟酒、灑酒"}, {"w": "廊廟", "m": "朝廷"}, {"w": "滄浪", "m": "青蒼的江水，暗用〈漁父〉滄浪之水"}], "questions": [{"n": 35, "qtype": "非選", "stem": "甲、乙二文均認為古典具有永恆性。明代許潮《赤壁遊》雜劇，對蘇軾〈赤壁賦〉既有承繼又有創新，請依引文回答：(1)舟中四人抽籤後，賦詩的規則為何？（占2分，20字以內，不可抄錄原文）(2)①眾人〔合〕唱，除表達物是人非的喟嘆，更反映出世人對個體生命有什麼「共同的焦慮」？②許潮藉東坡之口道出：「聊付與滄浪」，對此一焦慮所持的態度是什麼？（①②各占2分，各10字以內）", "options": {}, "answer": "", "ref_answer": "(1)各就所抽中的人物，賦詩一首歌詠（或：吟詠所抽中的人物；各就所抽中的人物，賦詩一首來懷古）。\n(2)①生命有限（或：死亡不可抗拒；人終有一死）。②隨任自然（或：曠達；釋懷）。", "ref_official": true, "explain": "(1)規則藏在「各拈取一鬮，吟詩一首，以見弔古斷案」：每人抽一個人物，就那個人物作一首詩來憑弔、評論。因為不能抄原文，要改寫成自己的話，例如「各依抽到的人物作詩懷古」。\n(2)①〔合〕唱「江山如故，何處覓曹郎」：江山還在，曹操這樣的英雄卻已不見，對照出人的生命短暫、終將消逝——這正是〈赤壁賦〉「哀吾生之須臾」的焦慮。②「把古今愁，廊廟悶，聊付與滄浪」是把愁悶交給江水，不再執著，態度是曠達、隨順自然，呼應〈赤壁賦〉「客喜而笑」的轉念。", "skill": "非選限字題：先從原文圈出關鍵句，再把它濃縮成「主詞＋動作＋目的」的自己的話，避免直接抄錄。"}], "difficulty": "中", "label": "112學測", "year": 112, "kind": "學測", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "赤壁賦"}, {"id": "xc113-04", "exam": "xc113", "nums": [4], "form": "單題", "img": "img/xc113-04.png", "source": "《抱朴子》", "author": "葛洪", "genre": "說理議論", "types": ["主旨寓意", "文意推論"], "passage": "偏才不足以經周用，隻長不足以濟眾短。是以雞知將旦，不能究陰陽之曆數；鵠識夜半，不能極晷景之道度；山鳩知晴雨於將來，不能明天文；蛇螘知潛泉之所居，不能達地理。", "translation": "只有某方面的才能，不足以應付全面的需要；只有一項長處，不足以補救許多短處。所以雞知道天快亮了，卻不能探究陰陽曆法的運算；鶴知道已經半夜，卻不能透徹日影計時的度數；山鳩能預知晴雨，卻不能通曉天文；蛇和螞蟻知道地下泉水在哪裡，卻不能通達地理。", "keywords": [{"w": "究", "m": "探究到底"}, {"w": "鵠", "m": "天鵝、鶴類的鳥"}, {"w": "晷景", "m": "日影，古代用來計時"}, {"w": "螘", "m": "同「蟻」，小蟲"}, {"w": "經周用", "m": "應付全面的用途"}, {"w": "濟", "m": "補救"}], "questions": [{"n": 4, "qtype": "單選", "stem": "下文________處應填入可總括文中所舉四項事例的文句，最適合填入的是：", "options": {"A": "英逸之才，非淺短所識", "B": "官達者，才未必當其位", "C": "小疵不足以損大器，短疢不足以累長才", "D": "偏才不足以經周用，隻長不足以濟眾短"}, "answer": "D", "explain": "四個例子的句型都一樣：「某動物懂某一點，卻不能懂整套學問」（雞知將旦→不能究曆數……）。要總括它們，就是「只有一點長處，不能應付全部」，所以選(D)。\n(A)講傑出人才不被淺薄者了解，例子中沒有「不被了解」。\n(B)講做大官的人才能不一定配得上職位，和動物例子無關。\n(C)講小缺點不會掩蓋大才能，方向正好相反。", "skill": "「總括句」題：先把例子的共同句型抽出來（有A能力→沒有B能力），再找意思相同的選項。"}], "difficulty": "易", "label": "113學測", "year": 113, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc113-05", "exam": "xc113", "nums": [5], "form": "單題", "img": "img/xc113-05.png", "source": "《鹽鐵論》", "author": "桓寬", "genre": "說理議論", "types": ["虛詞句式", "文意推論"], "passage": "昔周公之相也，謙卑而不鄰，以勞天下之士，是以俊義滿朝，賢智充門。孔子無爵位，以布衣從才士七十有餘人，皆諸侯卿相之人也，況處三公之尊以養天下之士哉？", "translation": "從前周公擔任宰相時，謙虛卑下而不吝惜（屈己待人），用來慰勞招納天下的士人，因此才俊之士布滿朝廷，賢能聰明的人擠滿門庭。孔子沒有爵位，以平民身分就有七十多位有才之士追隨他，都是可以當諸侯卿相的人才，更何況身居三公的尊位來供養天下士人呢？", "keywords": [{"w": "相", "m": "擔任宰相、輔佐"}, {"w": "鄰", "m": "通「吝」，吝惜"}, {"w": "勞", "m": "慰勞、招徠"}, {"w": "俊義", "m": "即「俊乂」，才德出眾的人"}, {"w": "布衣", "m": "平民"}], "questions": [{"n": 5, "qtype": "單選", "stem": "下列是一段古文，依據文意，甲、乙、丙、丁排列順序最適當的是：昔周公之相也，（甲、皆諸侯卿相之人也／乙、是以俊義滿朝，賢智充門／丙、謙卑而不鄰，以勞天下之士／丁、孔子無爵位，以布衣從才士七十有餘人）況處三公之尊以養天下之士哉？", "options": {"A": "甲乙丁丙", "B": "甲丙乙丁", "C": "丙甲丁乙", "D": "丙乙丁甲"}, "answer": "D", "explain": "先排周公：「周公之相也」後面要接他怎麼做——「謙卑而不鄰，以勞天下之士」（丙），結果「是以俊義滿朝」（乙），「是以」表示結果，一定在原因之後。再排孔子：「孔子……從才士七十有餘人」（丁），接著補充這些人「皆諸侯卿相之人也」（甲），「皆」承接前面的七十多人。最後「況處三公之尊」把兩人對比收尾。順序丙乙丁甲，選(D)。", "skill": "排序題抓連接詞：「是以」接結果、「皆」承前面的人群，先把成對的句子綁在一起。"}], "difficulty": "易", "label": "113學測", "year": 113, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc113-13", "exam": "xc113", "nums": [13, 14, 15], "form": "題組", "img": "img/xc113-13.png", "source": "羅景文〈周處傳說探究〉（引孔約《志怪》、祖台之《志怪》、《世說新語‧自新》）", "author": "羅景文", "genre": "史傳人物", "types": ["比較閱讀", "文意推論"], "passage": "孔約《志怪》：義興有邪足虎，溪渚長橋有蒼蛟，並大啖人，並郭西周，時謂郡中三害。周即處也。\n祖台之《志怪》：義興郡溪渚長橋下有蒼蛟吞啖人，周處執劍橋側伺。久之，遇出，於是懸自橋上投下蛟背而刺蛟，數創，流血滿溪，自郡渚至太湖句浦乃死。\n《世說新語》：周處年少時，兇彊俠氣，為鄉里所患。又義興水中有蛟，山中有白額虎，並皆暴犯百姓。義興人謂為「三橫」，而處尤劇。或說處殺虎斬蛟，實冀三橫唯餘其一。處即刺殺虎，又入水擊蛟。蛟或浮或沒，行數十里，處與之俱。經三日三夜，鄉里皆謂已死，更相慶。竟殺蛟而出，聞里人相慶，始知為人情所患，有自改意……處遂改勵，終為忠臣孝子。", "translation": "孔約《志怪》：義興有跛腳的老虎，溪渚長橋下有青色的蛟龍，都大量吃人，加上城西的周家（周處），當時稱為郡中三害。周就是周處。\n祖台之《志怪》：義興郡溪渚長橋下有青蛟吞吃人，周處拿著劍在橋邊等候。過了很久，蛟出來了，他就從橋上縱身跳到蛟背上刺牠，刺了好幾刀，血流滿溪，蛟一路逃到太湖句浦才死。\n《世說新語》：周處年輕時兇暴強悍、好逞意氣，被鄉里視為禍患。義興水裡又有蛟龍，山中有白額虎，都侵害百姓。義興人稱為「三橫」，而周處最嚴重。有人慫恿周處去殺虎斬蛟，其實是希望三橫只剩一個。周處就去刺死老虎，又下水去擊殺蛟龍。蛟時浮時沉，游了幾十里，周處一路跟著搏鬥。過了三天三夜，鄉里都以為他死了，互相慶賀。他竟然殺了蛟龍出來，聽到鄉人互相慶賀，才知道自己被大家當成禍害，於是有了改過的念頭……周處從此改過自勉，最後成為忠臣孝子。", "keywords": [{"w": "啖", "m": "吃"}, {"w": "伺", "m": "等候、窺伺"}, {"w": "兇彊", "m": "兇暴強橫"}, {"w": "三橫", "m": "三種橫行的禍害"}, {"w": "冀", "m": "希望"}, {"w": "更相慶", "m": "互相慶賀"}, {"w": "改勵", "m": "改過自勉"}], "questions": [{"n": 13, "qtype": "單選", "stem": "上文有甲、乙、丙、丁四處標記。依據文意，「蓋由民間口傳，各記見聞，彼此歧異，故是尋常事。」句應填在：", "options": {"A": "甲", "B": "乙", "C": "丙", "D": "丁"}, "answer": "C", "explain": "這句話是在「解釋為什麼記載會不同」。文中在乙之後提出問題：「同一件事，何以在記述上各有其偏重之處？」緊接著的丙處，正好用「蓋由民間口傳……故是尋常事」來回答，再轉入《世說新語》。所以填在丙，選(C)。", "skill": "句子插入題：先判斷該句的功能（解釋、舉例、總結），再找文中「缺回答」或「缺例子」的位置。"}, {"n": 14, "qtype": "單選", "stem": "關於文中引述的三則周處傳說，說明不適當的是：", "options": {"A": "孔約提及義興時有三害，周處為其一，而未述及周處的改過自新", "B": "祖台之未提到義興三害，聚焦於周處斬蛟，敘述較孔約《志怪》生動", "C": "《世說新語》渲染周處殺虎以見其兇彊，呈現與志怪相異的志人特質", "D": "《世說新語》增加里人相慶、周處聞知情節，以突出周處悔悟自新的轉折"}, "answer": "C", "explain": "(C)不適當：《世說新語》的殺虎只用一句「處即刺殺虎」帶過，並沒有渲染；周處的兇彊是用「為鄉里所患」「處尤劇」來寫，不是靠殺虎情節表現。\n(A)適當：孔約只寫三害，沒寫改過。\n(B)適當：祖台之只寫斬蛟，有「執劍橋側伺」「投下蛟背」「流血滿溪」等細節，比孔約生動。\n(D)適當：「聞里人相慶，始知為人情所患」是他悔悟的關鍵轉折。", "skill": "比較同一故事的不同版本：列表比較「有寫什麼、沒寫什麼、寫得詳或略」，就能判斷選項。"}, {"n": 15, "qtype": "單選", "stem": "迷因（meme）是文化傳遞的微型單位……「周處除三害」即屬迷因，依據右列電影《周處除三害》簡介，關於其模仿、改作傳說，說明最適當的是：", "options": {"A": "行為動機模仿傳說，陳桂林因欲「為民除害」，而向兩大通緝要犯下手", "B": "故事結局模仿傳說，陳桂林悔悟後奮發向上，改造自己，最終盡除三害", "C": "人物設計模仿傳說，均安排一關鍵角色，勸說主角在離世前為人間除惡", "D": "三害概念模仿傳說，將猛虎惡蛟轉為兩大通緝要犯，並創發貪嗔痴的新義"}, "answer": "D", "explain": "電影把傳說裡的虎、蛟換成排名在他前面的兩大通緝犯，又說真正困住他的是內心的「貪、嗔、痴」，把「三害」翻出新意，所以(D)正確。\n(A)陳桂林是「不希望死後被遺忘」才追殺，不是為民除害。\n(B)他最後投案被槍決，並沒有奮發向上改造自己。\n(C)醫師勸的是「自首」，不是勸他去除惡；而傳說中慫恿周處的人也不是要他在離世前除惡。", "skill": "改編比較題：逐項比對「動機、人物、情節、結局、主題」哪些相同、哪些被改。"}], "difficulty": "中", "label": "113學測", "year": 113, "kind": "學測", "textcat": "學術文本", "textcat2": "延伸", "linked_core": "世說新語選"}, {"id": "xc113-18", "exam": "xc113", "nums": [18, 19, 20], "form": "題組", "img": "img/xc113-18.png", "source": "保羅‧艾克曼《心理學家的面相術》（第19、20題選項引古文）", "author": "保羅‧艾克曼", "genre": "其他", "types": ["文意推論", "人物情感", "典故出處"], "passage": "第19題選項：\n(A)其（嫦娥）聲清越，烈如簫管。歌畢，盤旋而起，躍登几上，驚顧之間，已復為箸。（蒲松齡〈勞山道士〉）\n(B)客喜而笑，洗盞更酌。肴核既盡，杯盤狼藉。相與枕藉乎舟中，不知東方之既白。（蘇軾〈赤壁賦〉）\n(C)言訖，乘驢而去，其行若飛，回顧已失。靖與張氏且驚且喜，久之，曰：「烈士不欺人，固無畏！」促鞭而行。（杜光庭〈虬髯客傳〉）\n(D)親賢臣，遠小人，此先漢所以興隆也；親小人，遠賢臣，此後漢所以傾頹也。先帝在時，每與臣論此事，未嘗不嘆息痛恨於桓、靈也。（諸葛亮〈出師表〉）\n第20題選項：\n(A)人稟七情，應物斯感，感物吟志，莫非自然。（《文心雕龍‧明詩》）\n(B)真者，所以受於天也，自然不可易也。故聖人法天貴真，不拘於俗。（《莊子‧漁父》）\n(C)登山則情滿於山，觀海則意溢於海，我才之多少，將與風雲而並驅矣。（《文心雕龍‧神思》）\n(D)聖人所以治人七情，修十義，講信修睦，尚辭讓，去爭奪，舍禮何以治之？（《禮記‧禮運》）", "translation": "第19題：(A)嫦娥的歌聲清亮高亢，像簫管一樣響亮。唱完，盤旋飛起，跳上桌子，大家驚訝一看，她已經變回筷子。(B)客人高興地笑了，洗淨酒杯再斟酒。菜餚果品吃完了，杯盤散亂。大家互相枕靠著睡在船裡，不知道東方已經發白。(C)說完，騎驢離去，走得像飛一樣，回頭一看已經不見了。李靖和張氏又驚又喜，過了一會兒說：「俠義之士不會騙人，本來就沒什麼好怕的！」就催馬上路。(D)親近賢臣、疏遠小人，是西漢興盛的原因；親近小人、疏遠賢臣，是東漢衰敗的原因。先帝在世時，每次和我談到這件事，沒有不對桓帝、靈帝嘆息痛恨的。\n第20題：(A)人天生有七情，受到外物觸動就有感受，有感受就吟詠心志，這都是自然的。(B)真性是從天那裡得來的，自然而不能改變。所以聖人效法天、重視真性，不受世俗拘束。(C)登山時情感充滿山間，觀海時情意溢滿海上，我的才思有多少，都能和風雲一起奔馳。(D)聖人用來治理人的七情、修養十種道義、講求誠信和睦、崇尚辭讓、去除爭奪的，捨棄禮還能用什麼呢？", "keywords": [{"w": "驚顧", "m": "驚訝地看"}, {"w": "枕藉", "m": "縱橫交錯地躺著"}, {"w": "促鞭", "m": "催馬快行"}, {"w": "稟", "m": "天生具有"}, {"w": "治人七情", "m": "調理人的各種情感"}], "questions": [{"n": 18, "qtype": "單選", "stem": "依據上文，關於情緒訊號的敘述，最適當的是：", "options": {"A": "正向情緒會使人露出笑容，總能帶給他人愉快", "B": "臉部表情比身體動作情緒訊號，更易憑意志控制", "C": "人們常以電話溝通，可能是因為聲音比表情容易隱藏情緒", "D": "情緒訊號系統總是開啟的，通常從身體動作最先出現訊號"}, "answer": "C", "explain": "文中說聲音「可以憑意志完全關閉」，並推測「想隱藏表情，可能是人常以電話取代面對面溝通的原因」，所以(C)正確。\n(A)文中說快樂也可能很殘忍（嘲笑別人），不一定帶給他人愉快。\n(B)相反，文中說控制身體動作比控制臉部、聲音更容易。\n(D)文中說「最立即的情緒訊號是臉部表情」，不是身體動作。", "skill": "「比較級」選項（比……更易）最容易被顛倒，一定回原文確認比較方向。"}, {"n": 19, "qtype": "單選", "stem": "依據上文，下列文句畫線處所暗示的情緒訊號，解讀最適當的是：", "options": {"A": "其（嫦娥）聲清越……躍登几上，驚顧之間，已復為箸——眾人臉上露出驚訝的表情而把目光集中在嫦娥身上", "B": "客喜而笑……相與枕藉乎舟中，不知東方之既白——蘇軾與客藉著疏狂的身體姿態表達對人生苦短的感傷", "C": "言訖，乘驢而去……促鞭而行——李靖二人快馬加鞭的身體動作，表現二人驚懼之下急於離開", "D": "親賢臣，遠小人……未嘗不嘆息痛恨於桓、靈也——劉備低聲嘆息，凸顯其極力壓抑面部表情與聲調"}, "answer": "A", "explain": "(A)正確：「驚顧」是驚訝地看，對應文中「驚訝則是把注意力固定在產生情緒的對象」，眾人目光都盯著嫦娥。\n(B)「客喜而笑」之後大家醉倒舟中，是放鬆、釋懷的身體姿勢，已經走出感傷了。\n(C)二人「且驚且喜」，又說「固無畏」，催馬是安心上路，不是驚懼逃離。\n(D)「嘆息痛恨」是把情緒表露出來，不是壓抑。", "skill": "解讀古文中的情緒，先看畫線前後的情緒字（喜、驚、無畏、痛恨），再判斷選項的解釋方向對不對。"}, {"n": 20, "qtype": "單選", "stem": "某些心理學家認為：情緒調整模式可藉學習而來。下列最接近此一觀點的是：", "options": {"A": "人稟七情，應物斯感，感物吟志，莫非自然", "B": "真者，所以受於天也，自然不可易也。故聖人法天貴真，不拘於俗", "C": "登山則情滿於山，觀海則意溢於海，我才之多少，將與風雲而並驅矣", "D": "聖人所以治人七情，修十義，講信修睦，尚辭讓，去爭奪，舍禮何以治之"}, "answer": "D", "explain": "「情緒可以學習調整」＝後天可以透過某種方法來管理情緒。(D)說聖人用「禮」來治理人的七情，就是後天學習、修養來調整情緒，最接近。\n(A)強調情感「莫非自然」，是天生自然發生。\n(B)強調真性「受於天」「不可易」，不能改變。\n(C)講創作時情感隨景物湧現，談的是文思，不是調整情緒。", "skill": "把觀點拆成關鍵詞（後天、學習、調整），再刪掉強調「天生、自然、不可改」的選項。"}], "difficulty": "中", "label": "113學測", "year": 113, "kind": "學測", "textcat": "部定古文", "textcat2": "科普文本", "linked_core": "大同與小康、出師表、虬髯客傳、赤壁賦、勞山道士"}, {"id": "xc113-21", "exam": "xc113", "nums": [21, 22], "form": "題組", "img": "img/xc113-21.png", "source": "《名公書判清明集》", "author": "宋代官員判詞（佚名）", "genre": "其他", "types": ["文意推論", "寫作手法"], "passage": "父子，人倫之大。父老而子不能事，則其罪在子；子幼而父不能養，則其責在父。劉珵為衡州知郡孫，有男元老，幼不撫養，而賣與鄉民鄭七。棄衣冠而服田畝，情亦可憐，此猶可諉也，曰劉珵一時為貧之故。已而，元老不安於鄭七家，逃歸本父，劉珵固宜復回天理，自子其子矣，乃復以元老賣與程十乙，則其意安在哉？可謂敗人倫、滅天理之已甚者！今鄭七入詞，欲取回元老於已去三年後，此決無復合之理。……劉珵兩將元老賣弄，為父不父，本合勘杖，且與從蔭，決小杖二十。元老牒押往族長劉萬二宣教宅，聽從收養。觀此子情貌奸狡，兼所習已乖，請萬二宣教嚴與鈐束，庶免墮落下流，為衣冠之玷，亦一美事。", "translation": "父子關係是人倫中最重大的。父親老了而兒子不能奉養，罪過在兒子；兒子年幼而父親不能撫養，責任在父親。劉珵是衡州知郡的孫子，有個兒子叫元老，年幼時不撫養，卻把他賣給鄉民鄭七。讓士族子弟丟下讀書人身分去種田，情況也很可憐，但這還可以推託，說是劉珵一時貧窮的緣故。後來元老在鄭七家待不下去，逃回親生父親身邊，劉珵本來應該回歸天理，把自己的兒子當兒子養，竟然又把元老賣給程十乙，他到底安什麼心呢？可說是敗壞人倫、滅絕天理到了極點！現在鄭七提出告訴，想在元老離開三年之後把他要回去，這絕對沒有再團聚的道理。……劉珵兩次把元老拿來買賣，做父親不像父親，本該審訊杖打，姑且看在他祖上蔭庇的份上，判打小杖二十下。元老行文押送到族長劉萬二宣教郎家，由他收養。看這孩子神情相貌奸猾，加上沾染的習氣已經不好，請萬二宣教郎嚴加管束，希望他不至於墮落下流，成為士族的汙點，這也是一件好事。", "keywords": [{"w": "事", "m": "侍奉、奉養"}, {"w": "衣冠", "m": "士大夫、士族身分"}, {"w": "諉", "m": "推託"}, {"w": "子其子", "m": "把自己的兒子當兒子看待"}, {"w": "入詞", "m": "具文陳述、提出告訴"}, {"w": "從蔭", "m": "依祖先功蔭從寬"}, {"w": "鈐束", "m": "管束"}, {"w": "玷", "m": "汙點"}], "questions": [{"n": 21, "qtype": "單選", "stem": "若依右框當代判決書要項，觀察上列古代判決書，最符合文中所述的是：", "options": {"A": "當事人：程十乙為原告，劉珵、鄭七為被告", "B": "事實：鄭七有償獲得元老，自認有理由繼續保有養子", "C": "主文：劉珵須賠償鄭七，並不得與元老恢復父子關係", "D": "理由：鄭七已撫養元老三年；元老已對生父心懷不滿"}, "answer": "B", "explain": "(B)正確：鄭七是用錢「買」到元老的（賣與鄉民鄭七），現在「入詞」要把人要回去，就是他主張自己有理由保有元老——這是訴訟一方主張的事實。\n(A)提出告訴（入詞）的是鄭七，所以原告是鄭七，不是程十乙。\n(C)判決是劉珵打小杖二十、元老交族長收養，沒有判賠償。\n(D)「已去三年」是元老離開鄭七已經三年，不是鄭七撫養了三年；文中也沒說元老對生父不滿（他是不安於鄭七家才逃回生父那裡）。", "skill": "讀判決、契約類古文，先標出「誰告誰、要什麼、怎麼判、為什麼」四件事。"}, {"n": 22, "qtype": "單選", "stem": "下列敘述，最符合上文寫作方式的是：", "options": {"A": "全文大致先提出法律規定，再說明案件違背該法條，最後敘述判決結果", "B": "說明案件時，先列被告自陳的事實，再敘原告的反駁，再舉證人的佐證", "C": "以「其罪在子、其責在父」為綱領，依序指陳「子不子、父不父」之過", "D": "時見教化口吻，除對悖倫者嚴辭訓斥，並期勉受託者負起維護禮教之責"}, "answer": "D", "explain": "(D)正確：判詞罵劉珵「敗人倫、滅天理之已甚者」，最後又請族長「嚴與鈐束」，免得元老成為「衣冠之玷」，處處是教化的口吻。\n(A)開頭講的是人倫道理（父子之道），不是法律條文。\n(B)文中沒有被告自陳、原告反駁、證人佐證的結構。\n(C)開頭雖然並舉子與父，但全文只追究「父不父」，沒有指責元老「子不子」。", "skill": "寫作方式題，先概括每段在做什麼（說理→敘事→判決→叮囑），再對照選項描述的結構。"}], "difficulty": "中", "label": "113學測", "year": 113, "kind": "學測", "textcat": "生活情境文本", "textcat2": "學術文本", "linked_core": ""}, {"id": "xc113-23", "exam": "xc113", "nums": [23, 24], "form": "題組", "img": "img/xc113-23.png", "source": "傅璇琮《唐代科舉與文學》（引《獨異志》）", "author": "傅璇琮（引李亢《獨異志》）", "genre": "筆記小品", "types": ["文意推論", "文化常識"], "passage": "崔群為相，清名甚重。元和中，自中書舍人知貢舉，既罷，夫人李氏嘗勸其樹莊田以為子孫之計。笑答曰：「余有三十所美莊良田遍天下，夫人復何憂？」夫人曰：「不聞君有此業。」群曰：「吾前歲放春榜三十人，豈非良田耶？」夫人曰：「若然者，君非陸相門生乎？然往年君掌文柄，使人約其子（簡禮），不令就春闈之試。如君以為良田，則陸氏一莊荒矣。」群慚而退，累日不食。", "translation": "崔群當宰相，清廉的名聲很大。元和年間，他以中書舍人的身分主持科舉考試，考完後，夫人李氏曾勸他置辦田產，作為子孫的打算。崔群笑著回答：「我有三十處好莊園、好田地遍布天下，夫人還擔心什麼？」夫人說：「沒聽說您有這些產業啊。」崔群說：「我前年放榜錄取了三十人，難道不是良田嗎？」夫人說：「如果是這樣，您不是陸贄宰相的門生嗎？可是往年您主持考試時，卻派人約束他的兒子陸簡禮，不讓他參加考試。如果您把門生當成良田，那陸家就有一處莊園荒廢了。」崔群慚愧地退下，好幾天吃不下飯。", "keywords": [{"w": "知貢舉", "m": "主持科舉考試"}, {"w": "樹莊田", "m": "置辦田產"}, {"w": "放春榜", "m": "春試放榜錄取"}, {"w": "門生", "m": "考中者對主考官自稱"}, {"w": "掌文柄", "m": "主持考試、掌握取士大權"}, {"w": "春闈", "m": "春季舉行的進士考試"}], "questions": [{"n": 23, "qtype": "單選", "stem": "下列敘述，可藉由上文判斷確知的是：", "options": {"A": "韓愈、陸贄皆曾於唐代知貢舉", "B": "柳宗元於顧十郎知貢舉時登榜及第", "C": "韓愈肯定崔群言行，但不認同其拘守座主門生關係", "D": "柳宗元、崔群對座主門生關係的認知，不脫時人之見"}, "answer": "D", "explain": "柳宗元說門生不知感恩「非人也」，崔群把門生當「良田」，文章說兩人都反映了「當時這種社會意識」，所以(D)可以確知。\n(A)崔群是陸贄的門生，可知陸贄知過貢舉；但文中沒說韓愈知貢舉。\n(B)文中只引了〈與顧十郎書〉的一句話，看不出柳宗元是不是顧十郎錄取的。\n(C)韓愈只是盛讚崔群言行「無瑕尤」，沒有提到不認同他的門生觀念。", "skill": "「可確知」題只接受文中有明說或必然推出的內容，凡是「可能」「看起來」的都要刪。"}, {"n": 24, "qtype": "單選", "stem": "上文《獨異志》中的崔群之妻說「陸氏一莊荒矣」，最可能的原因是：", "options": {"A": "譏嘲陸贄未曾知貢舉，缺乏門生", "B": "暗諷崔群受陸贄提拔，卻不報恩", "C": "感嘆陸贄子孫不上進，門庭漸衰", "D": "提醒崔群以陸贄為戒，買田躬耕"}, "answer": "B", "explain": "順著崔群的比喻走：門生＝座主的良田，會回報座主。崔群自己就是陸贄的「田」，可是他主考時卻不讓陸贄的兒子應試——這塊田不但沒回報，反而害了主人家，所以說「陸氏一莊荒矣」，暗諷他忘恩不報，選(B)。崔群聽了「慚而退」也證明是被戳到痛處。\n(A)崔群是陸贄門生，陸贄當然知過貢舉。\n(C)陸贄的兒子是被崔群擋住不能考，不是自己不上進。\n(D)夫人是在諷刺，不是勸他買田種地。", "skill": "遇到比喻式的反諷，把對方的比喻原樣套回他自己身上，就能看出諷刺點。"}], "difficulty": "中", "label": "113學測", "year": 113, "kind": "學測", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "xc113-26", "exam": "xc113", "nums": [26], "form": "單題", "img": "img/xc113-26.png", "source": "歸有光〈項脊軒志〉、諸葛亮〈出師表〉、《論語‧衛靈公》、蘇軾〈赤壁賦〉、韓愈〈師說〉", "author": "多家", "genre": "其他", "types": ["虛詞句式"], "passage": "(A)垣牆周庭，以當南日\n(B)願陛下託臣以討賊興復之效\n(C)無求生以害仁，有殺身以成仁\n(D)挾飛仙以遨遊，抱明月而長終\n(E)余嘉其能行古道，作師說以貽之", "translation": "(A)在庭院四周砌上牆，用來擋住南面的陽光\n(B)希望陛下把討伐國賊、復興漢室的成效交託給我\n(C)不會為了求活而損害仁德，只會犧牲生命來成全仁德\n(D)希望挽著飛仙遨遊，抱著明月永遠存在\n(E)我讚許他能實踐古人從師之道，寫了〈師說〉來送給他", "keywords": [{"w": "以（目的）", "m": "來、用來，連接作為與目的"}, {"w": "以（介詞）", "m": "把、拿"}, {"w": "當", "m": "抵擋"}, {"w": "貽", "m": "贈送"}], "questions": [{"n": 26, "qtype": "多選", "stem": "中文文句中的「以」，可用於某項作為之後，表示該作為的目的，例如「保持距離（作為），以策安全（目的）」。下列畫底線文句中的「以」，屬於此種用法的是：", "options": {"A": "垣牆周庭，以當南日", "B": "願陛下託臣以討賊興復之效", "C": "無求生以害仁，有殺身以成仁", "D": "挾飛仙以遨遊，抱明月而長終", "E": "余嘉其能行古道，作師說以貽之"}, "answer": "ACE", "explain": "(A)對：砌牆（作為）→來擋南面陽光（目的）。\n(B)錯：「託臣以討賊興復之效」＝把討賊興復的任務託付給我，「以」是介詞「把」。\n(C)對：犧牲生命（作為）→來成全仁德（目的）。\n(D)錯：「挾飛仙以遨遊」和下句「抱明月而長終」對仗，「以」等於「而」，表示伴隨的方式，挽著飛仙一起遨遊，不是目的。\n(E)對：寫〈師說〉（作為）→來送給他（目的）。", "skill": "把「以」換成「為了／用來」讀讀看，通順且前面是動作、後面是想達成的事，就是目的用法；若有對仗句，看另一句用什麼字替換。"}], "difficulty": "中", "label": "113學測", "year": 113, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "出師表、師說、赤壁賦、項脊軒志"}, {"id": "xc113-27", "exam": "xc113", "nums": [27], "form": "單題", "img": "img/xc113-27.png", "source": "陶淵明〈桃花源記〉、《左傳‧燭之武退秦師》、《史記‧項羽本紀》、歸有光〈項脊軒志〉、蒲松齡〈勞山道士〉等", "author": "多家", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)三五年內，即當太平／快意當前，適觀而已矣\n(B)便扶向路，處處誌之／向時估帆所出入者，時已淤為沙灘\n(C)爾其自戕爾手／蒙賜月明之照，乃爾寂飲，何不呼嫦娥來\n(D)若亡鄭而有益於君，敢以煩執事／入咸陽，毫毛不敢有所近\n(E)軒凡四遭火，得不焚，殆有神護者／得比勁節長垂，千人共仰", "translation": "(A)三五年內，就將太平／令人暢快的景象在眼前，只是看看罷了\n(B)就沿著原先的路，處處做記號／從前商船出入的地方，現在已淤積成沙灘\n(C)你要親手殺死你自己／承蒙賜予明月照耀，卻這樣冷清地喝酒，為什麼不叫嫦娥來\n(D)如果滅掉鄭國對您有好處，那就冒昧地麻煩您的手下／進入咸陽，一絲一毫都不敢碰\n(E)項脊軒總共遭過四次火災，能夠沒被燒毀，大概有神明保護吧／能夠和堅勁的節操一樣長久流傳，受眾人敬仰", "keywords": [{"w": "當", "m": "將、應當／面對、在"}, {"w": "向", "m": "先前、原先"}, {"w": "爾", "m": "你／如此"}, {"w": "敢", "m": "冒昧（謙詞）／有膽量"}, {"w": "得", "m": "能夠"}], "questions": [{"n": 27, "qtype": "多選", "stem": "下列各組「」內的詞，意義前後相同的是：", "options": {"A": "三五年內，即「當」太平／快意「當」前，適觀而已矣", "B": "便扶「向」路，處處誌之／「向」時估帆所出入者，時已淤為沙灘", "C": "爾其自戕「爾」手／蒙賜月明之照，乃「爾」寂飲，何不呼嫦娥來", "D": "若亡鄭而有益於君，「敢」以煩執事／入咸陽，毫毛不「敢」有所近", "E": "軒凡四遭火，「得」不焚，殆有神護者／「得」比勁節長垂，千人共仰"}, "answer": "BE", "explain": "(A)錯：前者「當」是「將會」；後者「當前」是「在眼前」，「當」是「面對、在」。\n(B)對：「向路」是先前走過的路，「向時」是從前，「向」都是「先前、從前」。\n(C)錯：前者「爾手」的「爾」是「你」；後者「乃爾寂飲」的「爾」是「如此、這樣」。\n(D)錯：前者「敢」是謙詞「冒昧」；後者「不敢」的「敢」是「有膽量」。\n(E)對：兩個「得」都是「能夠」。", "skill": "一詞多義題，先把字替換成候選意思（你／如此；冒昧／有膽量），哪個通順就用哪個。"}], "difficulty": "中", "label": "113學測", "year": 113, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "燭之武退秦師、鴻門宴、桃花源記、項脊軒志、勞山道士"}, {"id": "xc113-29", "exam": "xc113", "nums": [29], "form": "單題", "img": "img/xc113-29.png", "source": "資料整合題（古文引自宋應星《天工開物》、李時珍《本草綱目》）", "author": "宋應星、李時珍", "genre": "其他", "types": ["文意推論", "比較閱讀"], "passage": "水飛：惟取好砂，軋碎如微塵，入缸注清水澄浸。過三日夜，其上浮者不堪入藥，傾入別缸。其下沉結者，曬乾即頭朱也。\n升煉：次砂不入藥，作爐置砂於中，下承以水，上覆以盆，器外加火，則煙飛於上，水銀溜於下。丹砂性寒而無毒，入火則熱而有毒，能殺人。水銀乃至陰毒物，因火煅丹砂而出，或加鹽、礬煉而為輕粉，或加硫黃升而為銀朱。", "translation": "水飛法：只挑好的硃砂，碾碎成像灰塵一樣細，放進缸裡注入清水讓它沉澱浸泡。過了三天三夜，浮在上面的不能入藥，倒到別的缸裡；沉在下面凝結的，曬乾就是上等的「頭朱」。\n升煉法：次等的硃砂不入藥，做一個爐子把砂放在裡面，下面用水承接，上面用盆蓋住，在器具外面加火燒，煙就往上飛，水銀就流到下面。丹砂本性寒涼、沒有毒，一經火燒就變熱而有毒，能毒死人。水銀是極陰的毒物，是用火燒煉丹砂得來的；或加鹽、明礬煉成輕粉，或加硫黃升煉成銀朱。", "keywords": [{"w": "軋", "m": "碾、壓碎"}, {"w": "澄浸", "m": "浸泡使沉澱"}, {"w": "頭朱", "m": "上等硃砂"}, {"w": "煅", "m": "用火燒煉"}, {"w": "升", "m": "加熱使昇華"}], "questions": [{"n": 29, "qtype": "多選", "stem": "關於硃砂（主成分為硫化汞），符合下列資料所述的是：", "options": {"A": "水飛法是將硃砂先以清水反覆淘洗，再曬乾研成粉末", "B": "今日若以機器研磨取代水飛法，將因高溫使硃砂含有劇毒", "C": "升煉法主要用於煉製水銀，水銀加入硫黃之後可再產生銀朱", "D": "銀朱藉升煉獲得，不僅速度快，毒性也比水飛法獲得的頭朱低", "E": "藥用硃砂若以安全方式炮製，非全不可用，但臺灣目前完全禁用"}, "answer": "BCE", "explain": "(A)錯：順序顛倒，是先「軋碎如微塵」，再入缸注水浸泡，沉澱的曬乾就是頭朱，不是先洗後研。\n(B)對：中醫師說機器研磨會因高溫「使硃砂產生劇毒」。\n(C)對：升煉時「水銀溜於下」，水銀「加硫黃升而為銀朱」。\n(D)錯：資料沒說升煉比較快；而且「入火則熱而有毒」，升煉品的毒性反而可能更高。\n(E)對：中醫師說重複水飛多次就可以炮製藥用硃砂，但衛生署公告禁止中藥用硃砂的製造、販賣等。", "skill": "圖文資料題：每個選項先找出它在哪一格資料，再逐字比對步驟順序與因果。"}], "difficulty": "中", "label": "113學測", "year": 113, "kind": "學測", "textcat": "科普文本", "textcat2": "", "linked_core": ""}, {"id": "xc113-30", "exam": "xc113", "nums": [30, 31], "form": "題組", "img": "img/xc113-30.png", "source": "甲：《重修福建臺灣府志‧叢談》；乙：《臺灣紀事‧鄭事紀略》", "author": "劉良璧等纂；吳子光", "genre": "史傳人物", "types": ["比較閱讀", "文意推論", "寫作手法"], "passage": "甲：鄭成功起兵荼毒濱海，民間患之。有問善知識云：「此何孽肆毒若是？」答曰：「乃東海大鯨也。」問何時而滅？曰：「歸東即逝。」凡成功所犯之處，如南京、溫、台並及臺灣，舟至海水為之暴漲。順治辛丑攻臺灣，紅毛先望見一人冠帶騎鯨，從鹿耳而入，隨後成功將舟由是港進。癸卯成功未疾時，轄下夢見前導稱成功至，視之，乃鯨首冠帶乘馬，由鯤身東入於外海。未幾，成功病卒，正符「歸東即逝」之語。\n乙：鄭成功，倭產也。誕降之前一日，天晴霽無片雲。薄暮，忽有雷破土窟而出，煙霾漲天，人對面不可辨。少頃，狂風疾雨，拔古木且盡，屋瓦皆飛，平地水深數尺。正錯愕間，空中有聲，如天崩地裂，繞郭顛簸不止。眾相驚以地震，曰：「弗去懼壓。」則皆走，亟覓山村避之。天明，諜者言島中有鯨鯢長數十丈，夭矯起波間。金光閃爍，噓氣如雷鳴，風濤暴漲，隱隱有金戈鐵馬之聲不絕。舟航糜碎，溺入海盡死，竟夜哭聲震天。雞鳴，風始定，魚亦不見。相譁以為妖怪云。是夕，成功生，人奇之。\n自成功生後，倭視翁氏禮加謹。及長，據金廈，兵敗勢蹙，將以海外為逋逃藪，乃決計東行。時臺地屬荷蘭左賢王，忽夜夢一偉人盛服騎鯨魚入鹿耳門，侍衛甲兵甚眾，道無阻者。及寤，異之。未幾，報鄭兵至矣。", "translation": "甲：鄭成功起兵，荼毒沿海地區，百姓深受其害。有人問高僧：「這是什麼妖孽，如此肆虐？」高僧回答：「是東海的大鯨魚。」問什麼時候會消滅？答：「回到東方就死。」凡是鄭成功進犯的地方，像南京、溫州、台州以及臺灣，船一到海水就暴漲。順治辛丑年攻臺灣，荷蘭人先看到一個戴冠束帶的人騎著鯨魚從鹿耳門進來，隨後鄭成功的船就從這個港口進入。癸卯年鄭成功還沒生病時，部下夢見前導的人喊「成功到了」，一看，是鯨魚頭戴冠帶騎著馬，從鯤身往東進入外海。不久鄭成功病死，正好應驗了「歸東即逝」的話。\n乙：鄭成功是在日本出生的。他出生前一天，天氣晴朗，沒有一片雲。傍晚忽然有雷從土洞裡衝出，煙霧瀰漫天空，人面對面都看不清。不久狂風暴雨，古樹幾乎被拔光，屋瓦全飛走，平地積水好幾尺深。大家正驚愕時，空中傳來如天崩地裂的聲音，整個城郭搖晃不停。眾人驚以為地震，說：「不離開就怕被壓死。」於是都逃走，急忙找山村躲避。天亮後，探子說島邊有一條長數十丈的鯨魚，在波浪中翻騰，金光閃爍，噴氣聲像雷鳴，風浪暴漲，隱約有兵馬廝殺之聲不斷。船隻全被打碎，落海的人都淹死了，整夜哭聲震天。到雞叫時風才停，鯨魚也不見了。大家紛紛說是妖怪。當天晚上，鄭成功出生，人們都覺得驚奇。\n鄭成功出生後，日本人對他母親翁氏更加禮敬。長大後，他占據金門、廈門，兵敗勢窮，打算把海外當作逃亡的據點，於是決定東行。當時臺灣屬於荷蘭的長官，他忽然夜裡夢見一個穿著盛裝的偉人騎著鯨魚進入鹿耳門，侍衛兵士很多，一路沒有阻擋。醒來後覺得奇怪。不久，就有人來報鄭軍到了。", "keywords": [{"w": "荼毒", "m": "殘害"}, {"w": "善知識", "m": "高僧大德"}, {"w": "孽", "m": "妖孽、禍害"}, {"w": "紅毛", "m": "指荷蘭人"}, {"w": "倭", "m": "日本"}, {"w": "鯨鯢", "m": "大鯨魚"}, {"w": "夭矯", "m": "屈伸翻騰的樣子"}, {"w": "逋逃藪", "m": "逃亡者聚集的地方"}], "questions": [{"n": 30, "qtype": "多選", "stem": "關於甲、乙二文中鄭成功的事蹟，敘述適當的是：", "options": {"A": "出生之日傳說大鯨現身，引發巨浪破壞船隻", "B": "出生後因降伏害人的大鯨，其母受倭人禮敬", "C": "擁有騎鯨的天賦，因而率軍船征戰無往不利", "D": "率兵剿滅海賊，解救了久被荼毒的濱海人民", "E": "病死於臺灣，符應高僧大鯨歸東即逝的預言"}, "answer": "AE", "explain": "(A)對：乙文說出生前後有鯨鯢翻騰、「風濤暴漲」「舟航糜碎」，當晚鄭成功出生。\n(B)錯：倭人禮敬翁氏是因為鄭成功出生時異象，文中沒有他降伏大鯨的情節。\n(C)錯：騎鯨只出現在別人的夢境或望見的異象，沒說他有騎鯨天賦，也沒說無往不利（乙文還寫他「兵敗勢蹙」）。\n(D)錯：甲文說是鄭成功「荼毒濱海」，他本身被當成禍害。\n(E)對：甲文說他攻下臺灣後病卒，「正符『歸東即逝』之語」。", "skill": "神異故事題要分清楚「真的發生」與「夢見、望見、傳說」，選項常把夢境當成事實。"}, {"n": 31, "qtype": "多選", "stem": "關於甲、乙二文的寫作方式，敘述適當的是：", "options": {"A": "分從神異事蹟、中日混血角度，解釋鄭氏軍事才能卓越之因", "B": "均藉描述海水暴漲，以凸顯鄭氏船隊之軍威浩大、軍容壯盛", "C": "均記載鄭成功與鯨魚密切關聯的夢境，以凸顯鄭氏乃非常人", "D": "皆敘寫鄭成功攻臺時獲神靈天助，登陸鹿耳門後，勢如破竹", "E": "皆以清廷統治的觀點，看待鄭氏攻打荷人、占領臺灣的事蹟"}, "answer": "CE", "explain": "(A)錯：乙文雖說「倭產也」，但沒有用混血來解釋他的軍事才能；兩文也沒有稱讚他軍事卓越。\n(B)錯：甲文的海水暴漲是說他所到之處帶來災異；乙文的風濤暴漲是出生時鯨魚作怪，都不是誇軍威。\n(C)對：甲文部下夢見鯨首冠帶乘馬，乙文荷蘭長官夢見偉人騎鯨入鹿耳門，都把他和鯨魚連在一起，顯示他不是凡人。\n(D)錯：兩文都沒寫登陸後勢如破竹。\n(E)對：甲文說他「荼毒濱海，民間患之」，乙文說他「以海外為逋逃藪」，都是把鄭氏當成亂黨、逃寇的清朝官方立場。", "skill": "判斷作者立場，看用詞褒貶：「荼毒」「孽」「逋逃藪」都是貶義，代表敵對一方的觀點。"}], "difficulty": "中", "label": "113學測", "year": 113, "kind": "學測", "textcat": "文學文本", "textcat2": "學術文本", "linked_core": ""}, {"id": "xc113-34", "exam": "xc113", "nums": [34, 35, 36], "form": "題組", "img": "img/xc113-34.png", "source": "李煜〈浪淘沙〉、辛棄疾〈破陣子〉（搭配甲文論回憶、乙文戴安‧艾克曼《氣味、記憶與愛欲》）", "author": "李煜、辛棄疾", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感", "比較閱讀"], "passage": "丙：簾外雨潺潺，春意闌珊。羅衾不耐五更寒。夢裡不知身是客，一晌貪歡。獨自莫憑欄，無限江山，別時容易見時難。流水落花春去也，天上人間。（李煜〈浪淘沙〉）\n丁：醉裡挑燈看劍，夢回吹角連營。八百里分麾下炙，五十絃翻塞外聲。沙場秋點兵。馬作的盧飛快，弓如霹靂弦驚。了卻君王天下事，贏得生前身後名。可憐白髮生。（辛棄疾〈破陣子〉）", "translation": "丙：簾外雨聲潺潺，春天的氣息將盡。絲綢被子擋不住五更天的寒冷。夢裡忘了自己是寄居他鄉的俘虜，貪享片刻的歡樂。一個人不要倚欄遠望，那無邊的江山，離別時容易，再見就難了。流水帶走落花，春天走了，過去和現在就像天上和人間一樣遙遠。\n丁：醉中挑亮燈火察看寶劍，夢中回到號角聲連綿的軍營。把八百里牛的烤肉分給部下，各種樂器奏出雄壯的塞外軍歌。秋天在沙場上檢閱軍隊。戰馬像的盧馬一樣飛快，弓弦像霹靂般震響。一心要完成君王收復天下的大業，贏得生前死後的美名。可惜白髮已經長出來了。", "keywords": [{"w": "闌珊", "m": "將盡、衰殘"}, {"w": "羅衾", "m": "絲綢被子"}, {"w": "一晌", "m": "片刻"}, {"w": "夢回", "m": "夢中回到；一說夢醒"}, {"w": "八百里", "m": "牛名，指烤牛肉"}, {"w": "麾下", "m": "部下"}, {"w": "的盧", "m": "駿馬名"}], "questions": [{"n": 34, "qtype": "單選", "stem": "關於丙、丁二詞中的夢與現實，解讀最適當的是：（占2分，單選題）", "options": {"A": "夢中皆突破局限，穿梭過去、現在與未來，虛實相生", "B": "皆自歡快的夢境中醒來，從而生發想望落空的幻滅感", "C": "李煜夢醒覺知「身是客」，辛棄疾夢中自憐「白髮生」", "D": "夢醒後，對照夢境與當前的境遇，皆萌生壯志未酬之嘆"}, "answer": "B", "explain": "丙詞：夢裡「一晌貪歡」，醒來卻是五更寒、江山已失，故國夢碎。丁詞：夢中是軍營點兵、馳騁沙場的豪情，最後「可憐白髮生」回到現實，壯志落空。兩者都是由歡快的夢醒來，產生失落幻滅，所以(B)正確。\n(A)兩詞的夢都是回到過去，沒有寫未來。\n(C)「白髮生」是醒後面對的現實，不是夢中。\n(D)李煜感嘆的是亡國之痛、今昔之別，不是壯志未酬。", "skill": "讀「夢」的詩詞，先把夢中與醒後的畫面分開列出，再看兩者落差帶出什麼情感。"}, {"n": 35, "qtype": "單選", "stem": "若綜合甲、乙、丙、丁文提出下列理解，對①、②是否適當的研判應是：①丙詞以「一晌」形容「貪歡」，此歡樂既是片刻的，應屬於短期記憶。②丁詞寫吹角、塞外聲、點兵，融入年少抗金記憶的斷片，並潛藏夢想。（占2分，單選題）", "options": {"A": "①、②皆適當", "B": "①、②皆不適當", "C": "①適當，②不適當", "D": "①不適當，②適當"}, "answer": "D", "explain": "①不適當：「一晌貪歡」是說夢中享受的歡樂很短暫，夢到的其實是過去當國君的長期回憶；乙文的「短期記憶」是指只保存5～20秒的資訊，兩者是不同的概念。\n②適當：辛棄疾年輕時曾聚眾抗金，詞中軍營號角、塞外樂聲、沙場點兵，正是記憶的片段；「了卻君王天下事」又寫出他收復失土的夢想。答案(D)。", "skill": "跨文本題要小心「字面相似、概念不同」：時間短的「歡樂」不等於科學定義的「短期記憶」。"}, {"n": 36, "qtype": "非選", "stem": "若參照甲文理解丙、丁二詞，請回答：(1)丙詞以「天上人間」的對比表達感受，亦暗示作者意識到怎樣的「自我」的變化？（占2分，20字以內）(2)假設丁詞「夢回」後所寫的夢境，屬於「不由自主的回憶」，詞中何者是「提醒物」？它與作者回憶起的往事有何關聯？（占4分，30字以內）", "options": {}, "answer": "", "ref_answer": "(1)由帝王淪為囚徒（或：由生命的主人變成受人宰制的人）。\n(2)劍；劍是他征戰沙場的工具（或：劍；讓他想起曾馳騁於戰場）。", "ref_official": true, "explain": "(1)甲文說回憶會讓人「意識到時光的失落和自我的變化」。李煜在夢裡忘了「身是客」，醒來才驚覺：過去是天上般的帝王生活，現在是人間的亡國俘虜，所以答「從帝王變成囚徒」。\n(2)甲文說不由自主的回憶靠「提醒物」觸發（像瑪德蓮蛋糕）。丁詞開頭「醉裡挑燈看劍」，接著就「夢回吹角連營」，看的「劍」就是提醒物；劍是他當年上戰場殺敵的武器，看見它就喚起從軍抗金的往事。答題時要寫出「提醒物是什麼」和「它和往事的關係」兩部分。", "skill": "套用理論解讀作品時，先把理論的關鍵詞（自我變化、提醒物）找出來，再到作品中找對應的句子。"}], "difficulty": "難", "label": "113學測", "year": 113, "kind": "學測", "textcat": "文學文本", "textcat2": "科普文本", "linked_core": ""}, {"id": "xc114-05", "exam": "xc114", "nums": [5], "form": "單題", "img": "img/xc114-05.png", "source": "王安石〈材論〉", "author": "王安石", "genre": "說理議論", "types": ["文意推論", "主旨寓意"], "passage": "吾聞之，六國合從，而辯說之材出；劉、項並世，而籌畫戰鬥之徒起；唐太宗欲治，而謨謀諫諍之佐來。此數輩者，方此數君未出之時，蓋未嘗有也。人君苟欲之，斯至矣。天下之廣，人物之眾，而曰果無材可用者，吾不信也。", "translation": "我聽說，戰國時六國合縱抗秦，善於遊說辯論的人才就出現了；劉邦、項羽同時爭天下，擅長謀劃作戰的人就興起了；唐太宗想要治理好國家，善於出謀劃策、直言進諫的輔佐之臣就來了。這幾類人，在這幾位君主還沒出現時，大概是沒有的。君主如果真心想要人才，人才就會到來。天下這麼廣大，人口這麼眾多，卻說真的沒有可用的人才，我不相信。", "keywords": [{"w": "合從", "m": "合縱，六國聯合抗秦"}, {"w": "謨謀", "m": "謀劃"}, {"w": "諫諍", "m": "直言規勸"}, {"w": "苟", "m": "如果"}, {"w": "斯", "m": "就"}], "questions": [{"n": 5, "qtype": "單選", "stem": "下文________處，若要填入使文意前後連貫的文句，最適當的是：", "options": {"A": "人君苟欲之，斯至矣", "B": "古之人，於材有以教育成就之", "C": "人之有異能於其身，猶錐之在囊", "D": "後之在位者，蓋未嘗求其說而試之以實也"}, "answer": "A", "explain": "前面三個例子都是「君主想要什麼→那種人才就出現」（六國合從→辯士出；唐太宗欲治→諫臣來），而且說這些人在君主出現之前「未嘗有」。所以中間要總結成「君主只要真心想要，人才自然會來」，後面才能接「說天下沒人才，我不信」。選(A)。\n(B)講教育培養人才，例子沒談教育。\n(C)講有才能的人自然會顯露（毛遂自薦），重點在人才本身，不在君主。\n(D)批評後世君主沒有試用人才，和前面舉的正面例子接不上。", "skill": "填空句要同時接得上前文（歸納例子）與後文（推出結論），兩頭都試讀一遍。"}], "difficulty": "易", "label": "114學測", "year": 114, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc114-11", "exam": "xc114", "nums": [11, 12], "form": "題組", "img": "img/xc114-11.png", "source": "魏禧《魏叔子日錄》", "author": "魏禧", "genre": "說理議論", "types": ["句意理解", "主旨寓意"], "passage": "論小人者，必論其心。小人庸多善事，其心未有無所為而為者。若徒論外事人品真偽，學術邪正，幾不可辨矣。論君子者，又不當徒論其心，心雖純正，而行事偶失，亦即是過。故論小人以心者，所以防閑小人之法；論君子以事者，所以造就君子之方。", "translation": "評論小人，一定要評論他的用心。小人也常常做好事，但他的用心沒有不是另有目的的。如果只看外在的行為，那麼人品的真假、學問的正邪，幾乎無法分辨。評論君子，又不應該只看他的用心；用心雖然純正，但做事偶有失誤，也就是過錯。所以用「用心」來評論小人，是防範小人的方法；用「做事」來評論君子，是成就君子的方法。", "keywords": [{"w": "庸", "m": "常、也"}, {"w": "無所為而為", "m": "沒有私心目的而去做"}, {"w": "徒", "m": "只、僅僅"}, {"w": "防閑", "m": "防範"}, {"w": "造就", "m": "培養成就"}], "questions": [{"n": 11, "qtype": "單選", "stem": "關於「君子行事」，下列最符合上文觀點的是：", "options": {"A": "縱有疏失也不易察覺", "B": "必然具有良善的動機", "C": "經常招致小人的詆毀", "D": "能引領世風正向發展"}, "answer": "B", "explain": "文中說論君子「不當徒論其心」，因為君子「心雖純正」——也就是君子的動機本來就是好的，問題只在做事會不會出錯，所以(B)符合。\n(A)文中說「行事偶失，亦即是過」，是要檢討，不是不易察覺。\n(C)(D)文中都沒提到。", "skill": "從「讓步句」（心雖純正，而……）找作者默認的前提：雖然後面是重點，但「雖」字後面的內容也是作者承認的事實。"}, {"n": 12, "qtype": "單選", "stem": "依據上文，「論小人者，必論其心」旨在告訴讀者：", "options": {"A": "小人也有心存善念的可能", "B": "不可被小人的作為所蒙蔽", "C": "小人無目標的行事易壞事", "D": "必須致力讓小人改邪歸正"}, "answer": "B", "explain": "小人「庸多善事」，表面常做好事，但「其心未有無所為而為者」，背後都有目的；只看外在行為就「幾不可辨」。所以要看他的用心，才不會被他的好表現騙了，選(B)。\n(A)正好相反，文中說小人做好事都別有居心。\n(C)小人是「有所為而為」，是有目的的，不是無目標。\n(D)文中說這是「防閑小人之法」，是防範而不是感化。", "skill": "「旨在」題回到作者的結論句（所以防閑小人之法），找出這句話的真正目的。"}], "difficulty": "易", "label": "114學測", "year": 114, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc114-13", "exam": "xc114", "nums": [13, 14], "form": "題組", "img": "img/xc114-13.png", "source": "司馬談〈論六家要旨〉；《孟子》、《論語》（白話對話式材料）", "author": "司馬談等", "genre": "經典語錄", "types": ["文意推論", "比較閱讀", "典故出處"], "passage": "（儒家）博而寡要，勞而少功，是以其事難盡從。然其序君臣父子之禮，列夫婦長幼之別，不可易也。\n（道家）與時遷移，應物變化，立俗施事，無所不宜，指約而易操，事少而功多。\n第14題選項：①五畝之宅，樹之以桑，五十者可以衣帛矣；雞豚狗彘之畜，無失其時，七十者可以食肉矣。（《孟子‧梁惠王上》）②政者，正也。子帥以正，孰敢不正？（《論語‧顏淵》）③鄉愿，德之賊也。（《論語‧陽貨》）④理義之悅我心，猶芻豢之悅我口。（《孟子‧告子上》）", "translation": "儒家學問廣博卻缺少要領，費力多而成效少，所以他們的主張很難全部照做。但是它排定君臣父子的禮節，區分夫婦長幼的差別，是不能改變的。\n道家隨著時勢變遷，順應事物變化，建立風俗、處理事務，沒有不適宜的；主旨簡約而容易掌握，做的事少而功效多。\n①五畝大的住宅旁種上桑樹，五十歲的人就可以穿絲綢了；雞豬狗等家畜，不錯過繁殖的時機，七十歲的人就可以吃肉了。②政就是正。您帶頭走正道，誰敢不正？③沒有是非、討好眾人的好好先生，是敗壞道德的人。④義理讓我的心喜悅，就像牛羊豬狗的肉讓我的口喜悅一樣。", "keywords": [{"w": "博而寡要", "m": "廣博卻缺少要領"}, {"w": "序", "m": "排定次序"}, {"w": "指約而易操", "m": "主旨簡要、容易施行"}, {"w": "鄉愿", "m": "外表忠厚、實則同流合汙的好好先生"}, {"w": "芻豢", "m": "牛羊豬狗等牲畜的肉"}], "questions": [{"n": 13, "qtype": "單選", "stem": "乙若依上文MBTI研判，兩處________內依序應是：", "options": {"A": "ST／NP", "B": "SF／NT", "C": "TJ／FP", "D": "FJ／TP"}, "answer": "A", "explain": "儒家「博而寡要，勞而少功」——重細節、繁瑣，偏S（重具體細節）；「序君臣父子之禮，列夫婦長幼之別，不可易」——講倫常原則，偏T。道家「與時遷移，應物變化」——隨現況調整，是P；「指約而易操」——簡要掌握大方向，是N。所以儒家ST、道家NP，選(A)。", "skill": "把古文的形容詞逐一翻成表格中的描述（寡要→細節多、與時遷移→隨現況調整），再對照代號。"}, {"n": 14, "qtype": "單選", "stem": "依上文MBTI，丙的舉證，不適當的是：", "options": {"A": "①五畝之宅，樹之以桑，五十者可以衣帛矣；雞豚狗彘之畜，無失其時，七十者可以食肉矣", "B": "②政者，正也。子帥以正，孰敢不正", "C": "③鄉愿，德之賊也", "D": "④理義之悅我心，猶芻豢之悅我口"}, "answer": "D", "explain": "F是「重視和諧、體諒，把人們的情緒納入考量」。(D)「理義之悅我心」是說人心天生喜愛義理，強調的是義理原則，不是體諒他人情緒，當F的例子不適當。\n(A)種桑、養畜、幾歲穿帛吃肉，是具體實踐細節，符合S。\n(B)「政者，正也」用一句簡要的話抓住政治的核心概念，符合N。\n(C)批評鄉愿是破壞道德的人，講原則、是非，符合T。", "skill": "「不適當」題，逐項把例句「歸類」到定義上，對不上的那一個就是答案。"}], "difficulty": "中", "label": "114學測", "year": 114, "kind": "學測", "textcat": "學術文本", "textcat2": "生活情境文本", "linked_core": ""}, {"id": "xc114-15", "exam": "xc114", "nums": [15, 16, 17, 18, 19], "form": "題組", "img": "img/xc114-15.png", "source": "田曉菲《赤壁之戟》（論杜牧〈赤壁〉、蘇軾〈赤壁賦〉）", "author": "田曉菲", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀", "文意推論"], "passage": "杜牧〈赤壁〉：折戟沉沙鐵未銷，自將磨洗認前朝。東風不與周郎便，銅雀春深鎖二喬。\n第18題所引〈赤壁賦〉：①挾飛仙以遨遊，抱明月而長終。知不可乎驟得。②且夫天地之間，物各有主，苟非吾之所有，雖一毫而莫取。", "translation": "杜牧〈赤壁〉：折斷的戟沉在沙裡，鐵還沒有銷蝕，我把它拿起來磨洗乾淨，認出是前朝的遺物。如果東風不給周瑜方便，那麼春色深深的銅雀臺，就要鎖住大喬、小喬了。\n〈赤壁賦〉：①（客說）想挽著飛仙遨遊，抱著明月永遠存在，知道這是不可能輕易得到的。②（蘇子說）況且天地之間，萬物各有主人，如果不是我所擁有的，即使一根毫毛也不拿。", "keywords": [{"w": "折戟", "m": "折斷的戟（古兵器）"}, {"w": "銷", "m": "銷熔、銷蝕"}, {"w": "周郎", "m": "周瑜"}, {"w": "銅雀", "m": "曹操所建銅雀臺"}, {"w": "二喬", "m": "大喬、小喬，孫策與周瑜之妻"}, {"w": "驟得", "m": "輕易、很快得到"}], "questions": [{"n": 15, "qtype": "單選", "stem": "下列敘述，最符合本文對杜牧〈赤壁〉一詩意象解讀的是：", "options": {"A": "「戟」被賦予殺敵之外的作用，呈現了文武交疊的影像", "B": "「鐵未銷」暗示戰事慘烈，並隱喻赤壁之戰的影響深鉅", "C": "「東風」喻生命的復甦，意謂二喬在銅雀臺享受新生活", "D": "「銅雀」指銅雀臺，藉空間的閉鎖以暗示政治權力轉移"}, "answer": "A", "explain": "文中說杜牧磨洗戟「並非如兵士般用以傷敵，而是為辨認前朝」，於是戟由「武」的工具變成「文」的載體，正是(A)。\n(B)文中說「鐵」在末句化為囚禁二喬的鐵鎖，沒說它暗示戰事慘烈或影響深遠。\n(C)東風是周瑜「偶然的助力」；若無東風，二喬就要被俘、禁錮，不是享受新生活。\n(D)銅雀臺的閉鎖是指二喬被囚，文中沒談政治權力轉移。", "skill": "「本文對……的解讀」題，一定要回文中找作者怎麼說，不能用自己對詩的印象作答。"}, {"n": 16, "qtype": "單選", "stem": "下列敘述，最符合本文對杜牧〈赤壁〉寫作特色說明的是：", "options": {"A": "結合銅雀臺的典故，首開以赤壁之戰入詩的風氣", "B": "透過特寫古兵器戟，寄託以文治取代武事的理想", "C": "藉東風興發想像，隱含人未必是歷史成敗的關鍵", "D": "經由磨洗動作暗示真相難明，並批判梟雄的野心"}, "answer": "C", "explain": "詩的後半「藉『東風』引入虛設的情境：若周瑜未得到偶然的助力」，二喬就會被俘——勝負竟取決於一陣風這種偶然因素，暗示人未必是成敗關鍵，所以(C)正確。\n(A)文中說杜牧「最早將赤壁之戰與銅雀臺連結」，不是最早以赤壁之戰入詩。\n(B)由武變文是戟的意象轉變，文中沒說寄託文治理想。\n(D)磨洗是為了「認前朝」，強調與歷史個人性的相遇，不是暗示真相難明或批判曹操。", "skill": "留意「最早將A與B連結」和「首開A」的差別，選項常把限定條件拿掉。"}, {"n": 17, "qtype": "單選", "stem": "依據上文，客在〈赤壁賦〉中扮演的角色，說明最適當的是：", "options": {"A": "帶出曹操詩句，建構一世梟雄形象", "B": "照見蘇子欲求，提出質疑引發反思", "C": "對照古今，揭示鐘鼎山林的人生領悟", "D": "開展想像，呈顯空明飄逸的主體心境"}, "answer": "B", "explain": "文中說蘇子的歌傳達「求而不得的情思」，自己卻沒意識到，反而怪客的簫聲太悲；客「提供了與蘇子截然不同的視角」，把先前羽化登仙的浪漫描寫「一一否認」，蘇子才提出變與不變的回應——客照出蘇子內心的渴望，又用質疑引發他思考，選(B)。\n(A)客引〈短歌行〉是建立赤壁與曹詩的關聯，不是為了塑造梟雄形象。\n(C)文中沒談鐘鼎山林（仕與隱）。\n(D)空明飄逸是蘇子的心境延伸，客恰恰否定了它。", "skill": "分析對話體中配角的作用：看他說的話讓主角「發現了什麼」或「轉變了什麼」。"}, {"n": 18, "qtype": "單選", "stem": "上文畫線處（①「凌萬頃之茫然、羽化登仙」的浪漫描寫，被他成功地一一否認；②以莊子式的相對論回應「羨長江之無窮」）如欲引述〈赤壁賦〉原文為論據，是否適當的研判是：①挾飛仙以遨遊，抱明月而長終。知不可乎驟得。②且夫天地之間，物各有主，苟非吾之所有，雖一毫而莫取。", "options": {"A": "①、②皆適當", "B": "①適當，②不適當", "C": "①不適當，②無法判斷", "D": "①無法判斷，②不適當"}, "answer": "B", "explain": "①適當：「挾飛仙以遨遊……知不可乎驟得」是客說的話，直接否定了遨遊成仙的浪漫想像，正好證明「被他一一否認」。\n②不適當：「莊子式的相對論」是指「自其變者而觀之，則天地曾不能以一瞬；自其不變者而觀之，則物與我皆無盡也」這段；「物各有主，雖一毫而莫取」是接下來講取與不取，不是相對論。答案(B)。", "skill": "熟記課文的段落結構（誰說的、哪一段講什麼），引文佐證題就能快速對號入座。"}, {"n": 19, "qtype": "單選", "stem": "關於杜牧與蘇軾的赤壁書寫，最符合上文觀點的是：", "options": {"A": "皆在歌詠前代詩人的同時，重疊自身影像以寄託心志", "B": "皆對歷史事件賦予個人想像，而將赤壁轉變為文學意象", "C": "均拼貼片斷訊息以進行歷史想像，重現赤壁之戰發生場景", "D": "均透過人與自然的對比，凸顯文學書寫對生命有限的突破"}, "answer": "B", "explain": "文章開頭說赤壁原本只是地名，杜牧「賦予『赤壁』具體的形象與情感」，蘇軾則是「赤壁建構過程的第二個關鍵時刻」，兩人都用個人的想像（東風的假設、客與〈短歌行〉的連結）把赤壁變成文學意象，選(B)。\n(A)杜牧詠的是戰事與二喬，不是前代詩人。\n(C)兩人都不是要重現戰爭場景。\n(D)人與自然對比、文字使生命永恆，是文中對〈赤壁賦〉的詮釋，杜牧詩沒有。", "skill": "「皆／均」選項要拿兩個對象分別檢查，一個不符就刪。"}], "difficulty": "難", "label": "114學測", "year": 114, "kind": "學測", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "赤壁賦"}, {"id": "xc114-20", "exam": "xc114", "nums": [20, 21], "form": "題組", "img": "img/xc114-20.png", "source": "李漁《閒情偶寄‧居室部‧廳壁》", "author": "李漁", "genre": "筆記小品", "types": ["文意推論", "句意理解"], "passage": "廳壁不宜太素，亦忌太華。名人尺幅，自不可少，但須濃淡得宜，錯綜有致。予謂裱軸不如實貼；軸慮風起動搖，損傷名跡，實貼則無是患，且覺大小咸宜也。實貼又不如實畫，「何年顧虎頭，滿壁畫滄洲」自是高人韻事。予齋頭偶仿此制，而又變幻其形，良朋至止，無不耳目一新，低回留之不能去者。\n因予性嗜禽鳥，而又最惡樊籠，二事難全，終年搜索枯腸，一悟遂成良法。乃於廳旁四壁，倩四名手，盡寫著色花樹，而繞以雲煙，即以所愛禽鳥，蓄於虯枝老幹之上。畫止空跡，鳥有實形，如何可蓄？曰：不難，蓄之須自鸚鵡始。從來蓄鸚鵡者必用銅架，即以銅架去其三面，止存立腳之一條，並飲水啄粟之二管。先於所畫松枝之上，穴一小小壁孔，後以架鸚鵡者插入其中，務使極固，庶往來跳躍，不致動搖。松為著色之松，鳥亦有色之鳥，互相映發，有如一筆寫成。\n良朋至止，仰觀壁畫，忽見枝頭鳥動，葉底翎張，無不色變神飛，詫為仙筆；乃驚疑未定，又復載飛載鳴，似欲翱翔而下矣。諦觀熟視，方知個裡情形，有不抵掌叫絕，而稱巧奪天工者乎？", "translation": "廳堂的牆壁不宜太樸素，也忌諱太華麗。名人的書畫自然少不了，但要濃淡合宜、錯落有致。我認為裱成卷軸掛著，不如直接貼在牆上；卷軸怕風吹搖晃，損傷名家真跡，直接貼上就沒有這個問題，而且大小都合適。直接貼又不如直接畫在牆上，杜甫說「何年顧虎頭，滿壁畫滄洲」，本來就是高雅之士的風雅事。我在書齋偶然仿照這種做法，又變化了形式，好友來訪，沒有不耳目一新、流連忘返的。\n因為我天性喜愛禽鳥，卻又最討厭籠子，兩件事難以兩全，整年絞盡腦汁，忽然想通就有了好辦法。我在廳旁四面牆上，請四位名畫家畫滿彩色的花木，四周繞上雲煙，再把我喜愛的禽鳥養在彎曲的老枝幹上。畫只是虛的筆跡，鳥卻是真實的形體，怎麼養呢？答：不難，要從養鸚鵡開始。向來養鸚鵡一定用銅架，我就把銅架去掉三面，只留站腳的一根橫桿，以及喝水、啄食的兩根小管。先在畫的松枝上鑿一個小小壁孔，再把架鸚鵡的桿子插進去，務必非常牢固，讓牠來回跳躍也不會搖動。松是彩色的松，鳥也是彩色的鳥，互相輝映，好像一筆畫成。\n好友來訪，抬頭看壁畫，忽然看見枝頭的鳥在動、葉下的羽毛張開，沒有不臉色大變、精神飛揚，驚以為是仙人的手筆；正驚疑不定時，鳥又邊飛邊叫，好像要飛下來了。仔細觀察，才知道其中的奧妙，哪有不拍手叫絕、稱讚巧奪天工的呢？", "keywords": [{"w": "尺幅", "m": "書畫作品"}, {"w": "裱軸", "m": "裱成卷軸"}, {"w": "咸", "m": "都"}, {"w": "樊籠", "m": "鳥籠"}, {"w": "倩", "m": "請"}, {"w": "庶", "m": "希望、或許可以"}, {"w": "諦觀", "m": "仔細觀看"}, {"w": "抵掌", "m": "拍手"}], "questions": [{"n": 20, "qtype": "單選", "stem": "關於上文對廳堂壁面的設計，敘述最適當的是：", "options": {"A": "風格極簡或華麗皆可接受，但不能缺少名人書畫作品", "B": "書畫貼於壁面以免風吹損傷，且可依喜好來裁切尺寸", "C": "將滄洲直接繪於廳堂壁面，藉此懷念當年相識的舊友", "D": "邀請名家實畫景物於壁面，並融入個人喜好選擇題材"}, "answer": "D", "explain": "作者主張「實貼又不如實畫」，於是「倩四名手，盡寫著色花樹」，又因為自己「性嗜禽鳥」而把鸚鵡養在畫中枝上——名家實畫加上個人喜好，所以(D)正確。\n(A)「不宜太素，亦忌太華」，極簡和華麗都不行。\n(B)「大小咸宜」是說貼在牆上大小都合適，不是可以裁切。\n(C)「滿壁畫滄洲」是引杜甫詩讚美實畫的雅事，滄洲是隱士居處，和懷念舊友無關。", "skill": "留意「不宜……亦忌……」這種雙重否定，選項常把它改成「皆可」。"}, {"n": 21, "qtype": "單選", "stem": "根據上文朋友抵掌稱「巧奪天工」的原因，最可能是：", "options": {"A": "觀賞繞以雲煙的花樹與鸚鵡，對畫壁的開創之舉驚為仙筆", "B": "肯定主人的創意，既將花樹繪於壁面，又打造鸚鵡的樂園", "C": "驚嘆虛實相映的樹林與鸚鵡，理解裝置方法後方恍然大悟", "D": "發現裝置能操控鸚鵡，使其動靜自如，顯現主人深知鳥性"}, "answer": "C", "explain": "朋友的反應有兩階段：先看到畫中鳥會動，「詫為仙筆」；接著「諦觀熟視，方知個裡情形」，弄懂是真鳥架在畫上，才「抵掌叫絕」稱巧奪天工。畫是虛、鳥是實，虛實互映，所以(C)正確。\n(A)「驚為仙筆」是還沒看懂時的反應，不是稱讚巧奪天工的原因。\n(B)重點不在給鸚鵡一個樂園，而在畫與真鳥融成一體。\n(D)裝置只是固定鳥架，不能操控鸚鵡。", "skill": "人物反應有先後階段時，要對準題目問的那一個反應（抵掌叫絕），找它緊鄰的原因。"}], "difficulty": "中", "label": "114學測", "year": 114, "kind": "學測", "textcat": "生活情境文本", "textcat2": "科普文本", "linked_core": ""}, {"id": "xc114-22", "exam": "xc114", "nums": [22, 23, 24], "form": "題組", "img": "img/xc114-22.png", "source": "甲：白話介紹文；乙：錢乙《小兒藥證直訣》", "author": "錢乙（閻孝忠編）", "genre": "其他", "types": ["文意推論", "文化常識"], "passage": "東都張氏孫，九歲，病肺熱。……其證：嗽喘，悶亂，飲水不止，全不能食。錢氏用使君子丸、益黃散。張曰：「本有熱，何以又行溫藥？他醫用涼藥攻之，一月尚無效。」錢曰：「涼藥久則寒不能食。小兒虛不能食，當補脾，候飲食如故，即瀉肺經，病必愈矣。」服補脾藥二日，其子欲飲食。錢以瀉白散瀉其肺，遂愈。張曰：「何以不虛？」錢曰：「先實其脾，然後瀉其肺，故不虛也。」", "translation": "東京張家的孫子九歲，得了肺熱病。……症狀是：咳嗽氣喘、胸悶煩亂、不停喝水，完全吃不下東西。錢乙用使君子丸和益黃散。張家人說：「本來就有熱，為什麼還用溫性的藥？別的醫生用涼藥治了一個月都沒效。」錢乙說：「涼藥用久了，身體寒冷就吃不下。小孩虛弱吃不下，應該先補脾，等飲食恢復正常，再瀉肺經的熱，病一定會好。」吃了兩天補脾藥，孩子想吃東西了。錢乙用瀉白散瀉肺熱，病就好了。張家人問：「為什麼孩子沒有虛弱？」錢乙說：「先讓脾強健，然後才瀉肺熱，所以不會虛弱。」", "keywords": [{"w": "證", "m": "症狀"}, {"w": "嗽", "m": "咳嗽"}, {"w": "行溫藥", "m": "使用溫性的藥"}, {"w": "如故", "m": "像原來一樣"}, {"w": "實其脾", "m": "使脾充實強健"}], "questions": [{"n": 22, "qtype": "單選", "stem": "甲文敘及「豆蔻香連丸」，主要是為了強調錢乙：", "options": {"A": "不拘限於傳統，合宜調整用藥", "B": "善於改變藥性，易溫澀為寒涼", "C": "致力考察古今方劑藥材的差異", "D": "積極保存古代醫典所載的名藥"}, "answer": "A", "explain": "文中把豆蔻香連丸放在「化裁古方」的例子：古方香連丸用黃連、木香，錢乙「加入豆蔻溫澀止瀉」，改成新方——在傳統基礎上靈活調整，選(A)。\n(B)方向相反，他是加入溫澀的豆蔻。\n(C)(D)文中沒有談考察差異或保存名藥。", "skill": "看例子被放在哪個「標題句」下面（化裁古方），就知道它要證明什麼。"}, {"n": 23, "qtype": "單選", "stem": "依據甲文附圖，乙文________內應填入的藥名，依序應是：", "options": {"A": "導赤散／瀉白散", "B": "導赤散／瀉青丸", "C": "益黃散／瀉白散", "D": "益黃散／瀉青丸"}, "answer": "C", "explain": "第一個空：錢乙說要「當補脾」，張家還質疑他用「溫藥」，所以是補脾的藥；脾對應黃色，是「益黃散」。第二個空：「瀉其肺」，肺對應白色，是「瀉白散」。答案(C)。導赤散對應心（赤），瀉青丸對應肝（青），都不合。", "skill": "圖表題先建立對應表（脾＝土＝黃、肺＝金＝白），再到文中找「補哪裡、瀉哪裡」。"}, {"n": 24, "qtype": "單選", "stem": "綜合甲乙二文，下列①、②是否符合錢乙醫療觀點，最適當的研判是：①五臟母子相生，治療時宜先補母，母實之後再瀉子。②不強攻病證，待小兒飲食恢復正常後，方對症用藥。", "options": {"A": "①、②皆符合", "B": "①、②皆不符合", "C": "①符合，②不符合", "D": "①不符合，②符合"}, "answer": "A", "explain": "①符合：依附圖，脾（土）生肺（金），脾是母、肺是子。錢乙「先實其脾，然後瀉其肺」，正是先補母再瀉子。\n②符合：甲文說他主張小兒「用藥應避免強攻」；乙文他也說「候飲食如故，即瀉肺經」，等孩子能吃了才針對肺熱下藥。答案(A)。", "skill": "綜合題要把「理論（甲文、附圖）」和「案例（乙文）」互相對照，兩邊都找到證據才判定符合。"}], "difficulty": "中", "label": "114學測", "year": 114, "kind": "學測", "textcat": "科普文本", "textcat2": "", "linked_core": ""}, {"id": "xc114-25", "exam": "xc114", "nums": [25], "form": "單題", "img": "img/xc114-25.png", "source": "《禮記‧禮運》、歸有光〈項脊軒志〉、李斯〈諫逐客書〉、蒲松齡〈勞山道士〉、諸葛亮〈出師表〉、屈原〈漁父〉、杜光庭〈虬髯客傳〉等", "author": "多家", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)刑仁講讓，示民有常／自後余多在外，不常居\n(B)人煙猶是，而蕭條矣／同居一府，猶同室之兄弟至親也\n(C)由此觀之，客何負於秦哉／師略授小技，此來為不負也\n(D)當獎率三軍，北定中原／竟率意而鴉塗，莫自知其鳩拙云爾\n(E)新沐者必彈冠，新浴者必振衣／巾箱妝奩冠鏡首飾之盛，非人間之物", "translation": "(A)以仁為典範、提倡謙讓，向百姓昭示常法／從此以後我多在外地，不常住在家\n(B)人家仍然還在，卻已經冷落了／同住一府，就像同一個家的兄弟至親\n(C)從這裡看來，客卿有什麼對不起秦國的呢／師父稍微教我一點小法術，這趟就不算白來了\n(D)應當激勵率領三軍，向北平定中原／竟然隨意亂寫一通，不知道自己的笨拙\n(E)剛洗過頭的人一定要彈去帽子上的灰塵，剛洗過澡的人一定要抖掉衣服上的灰塵／頭巾箱、梳妝盒、帽子、鏡子、首飾的華美，不是人間的東西", "keywords": [{"w": "常", "m": "常法／經常"}, {"w": "猶", "m": "仍然／如同"}, {"w": "負", "m": "辜負、對不起"}, {"w": "率", "m": "率領／隨意、輕率"}, {"w": "冠", "m": "帽子"}], "questions": [{"n": 25, "qtype": "多選", "stem": "下列各組「」內的詞，意義前後相同的是：", "options": {"A": "刑仁講讓，示民有「常」／自後余多在外，不「常」居", "B": "人煙「猶」是，而蕭條矣／同居一府，「猶」同室之兄弟至親也", "C": "由此觀之，客何「負」於秦哉／師略授小技，此來為不「負」也", "D": "當獎「率」三軍，北定中原／竟「率」意而鴉塗，莫自知其鳩拙云爾", "E": "新沐者必彈「冠」，新浴者必振衣／巾箱妝奩「冠」鏡首飾之盛，非人間之物"}, "answer": "CE", "explain": "(A)錯：前者「常」是名詞「常法、常規」；後者是副詞「經常」。\n(B)錯：前者「猶」是「仍然」；後者是「如同」。\n(C)對：兩個「負」都是「辜負、對不起」。客何負於秦＝客卿哪裡對不起秦國；此來為不負＝這趟沒有白來（沒辜負）。\n(D)錯：前者「率」是「率領」；後者「率意」是「隨意、輕率」。\n(E)對：兩個「冠」都是名詞「帽子」。", "skill": "一詞多義先判斷詞性（名詞／副詞／動詞），詞性不同意思通常就不同。"}], "difficulty": "中", "label": "114學測", "year": 114, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "大同與小康、諫逐客書、漁父、出師表、虬髯客傳、項脊軒志、勞山道士"}, {"id": "xc114-29", "exam": "xc114", "nums": [29], "form": "單題", "img": "img/xc114-29.png", "source": "諸葛亮〈出師表〉、《論語‧述而》、歸有光〈項脊軒志〉、蒲松齡〈勞山道士〉、李斯〈諫逐客書〉等", "author": "多家", "genre": "其他", "types": ["虛詞句式"], "passage": "(A)舉一隅，不以三隅反，則不復也\n(B)吾家讀書久不效，兒之成，則可待乎\n(C)門人然燭來，則道士獨坐，而客杳矣\n(D)然同自內府播遷而來，則同為臺人而已\n(E)必秦國之所生然後可，則是夜光之璧，不飾朝廷", "translation": "(A)舉出一個角落，學生如果不能類推出另外三個角落，就不再教他了\n(B)我家讀書很久沒有成就，這孩子的成功，或許可以期待吧\n(C)門人點著蠟燭進來，只見道士獨自坐著，客人已經不見了\n(D)然而同樣是從內地遷移來的，那就同樣只是臺灣人罷了\n(E)如果一定要秦國出產的才可以用，那麼夜光璧就不會裝飾朝廷了", "keywords": [{"w": "則（假設結果）", "m": "那麼、就"}, {"w": "隅", "m": "角落"}, {"w": "復", "m": "再（教）"}, {"w": "杳", "m": "不見蹤影"}, {"w": "播遷", "m": "遷徙流離"}], "questions": [{"n": 29, "qtype": "多選", "stem": "「願陛下託臣以討賊興復之效；不效，則治臣之罪」，「則」之前提出一種假設情況（不效），「則」之後敘述結果。下列文句，屬於相同表意方式的是：", "options": {"A": "舉一隅，不以三隅反，則不復也", "B": "吾家讀書久不效，兒之成，則可待乎", "C": "門人然燭來，則道士獨坐，而客杳矣", "D": "然同自內府播遷而來，則同為臺人而已", "E": "必秦國之所生然後可，則是夜光之璧，不飾朝廷"}, "answer": "AE", "explain": "(A)對：「如果」舉一隅不能類推三隅（假設），「就」不再教（結果）。\n(B)錯：「兒之成，則可待乎」的「則」帶有推測語氣「大概、或許」，前面不是假設條件。\n(C)錯：「則」表示「才發現、只見」，是敘述看到的情景。\n(D)錯：前面是已知事實（同樣自內地遷來），「則」是「那就是」的判斷，不是假設。\n(E)對：「如果」一定要秦國出產的才用（假設），「那麼」夜光璧就不能裝飾朝廷（結果）。", "skill": "在「則」前面加「如果」試讀：讀得通且是尚未發生的條件，才是假設句。"}], "difficulty": "中", "label": "114學測", "year": 114, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "諫逐客書、出師表、項脊軒志、勞山道士"}, {"id": "xc114-30", "exam": "xc114", "nums": [30, 31], "form": "題組", "img": "img/xc114-30.png", "source": "袁宏道〈晚遊六橋待月記〉、王思任〈遊杭州諸勝記〉（甲為白話）", "author": "袁宏道、王思任", "genre": "山水遊記", "types": ["比較閱讀", "文意推論"], "passage": "乙：西湖最盛，為春為月。一日之盛，為朝煙，為夕嵐。……然杭人遊湖，止午、未、申三時。其實湖光染翠之工，山嵐設色之妙，皆在朝日始出，夕舂未下，始極其濃媚。月景尤不可言，花態柳情，山容水意，別是一種趣味。此樂留與山僧遊客受用，安可為俗士道哉！（袁宏道〈晚遊六橋待月記〉）\n丙：西湖之妙，山光水影，明媚相涵。圖畫天開，鏡花自照，四時皆宜也。然湧金門苦於官皂，錢塘門苦僧、苦客，清波門苦鬼。勝在岳墳，最勝在孤山與斷橋。吾極不樂豪家徽賈，重樓架舫，優喧粉笑，勢利傳杯，留門趨入。所喜者野航兩棹，坐恰兩三，隨處夷猶，侶同鷗鷺。或柳堤魚酒，或僧屋飯蔬，可信可宿。不過一二金而輕移曲探，可盡兩湖之致。（王思任〈遊杭州諸勝記〉）", "translation": "乙：西湖最美的時候是春天、是月夜；一天中最美的時候是早晨的煙霧和傍晚的山嵐。……但杭州人遊湖，只在午、未、申三個時辰（中午到下午）。其實湖水染成翠綠的工巧、山嵐著色的美妙，都在太陽剛出來、夕陽還沒落下時，才最濃豔嫵媚。月夜的景色更是說不出的好，花的姿態、柳的風情、山的容貌、水的意趣，別有一番趣味。這種樂趣只留給山僧和懂得遊賞的人享受，怎麼能對俗人說呢！\n丙：西湖的美妙在於山光水影，明媚交融。像天然展開的圖畫、像鏡中映照的花，四季都適宜遊覽。但是湧金門苦於衙役多，錢塘門苦於僧人、遊客多，清波門苦於多墳墓（鬼）。景色好的是岳飛墓，最好的是孤山和斷橋。我最不喜歡富豪和徽州商人，樓船層層、歌伎喧鬧、勢利地互相敬酒，關起門來趨炎附勢。我喜歡的是兩支槳的小野船，恰好坐兩三人，隨處從容自在，與鷗鷺為伴。或在柳堤邊吃魚喝酒，或在僧舍吃素飯，可以隨意，可以住宿。不過花一二兩銀子，輕快地划船、曲折探訪，就能享盡兩湖的情趣。", "keywords": [{"w": "朝煙、夕嵐", "m": "早晨的煙霧、傍晚的山氣"}, {"w": "夕舂", "m": "夕陽"}, {"w": "濃媚", "m": "濃豔嫵媚"}, {"w": "官皂", "m": "州縣衙役"}, {"w": "徽賈", "m": "徽州商人"}, {"w": "夷猶", "m": "從容自在"}, {"w": "致", "m": "情趣"}], "questions": [{"n": 30, "qtype": "多選", "stem": "綜合上述三文，關於晚明文人的記遊，說明適當的是：", "options": {"A": "偏重經驗的總結，而不著力於食宿行程的翔實記錄", "B": "既用以記錄遊蹤，亦塑造了旅遊目的地的景物內涵", "C": "遊記刊刻發行後，往往引發閱讀者跟風模仿其書寫風格", "D": "個人的審美情趣、生活的雅化，在乙、丙二文中分別以待月、野航展現", "E": "文人與大眾遊觀方式的不同，在乙、丙二文中都以空間選擇的差異呈現"}, "answer": "ABD", "explain": "(A)對：乙、丙都在總結「什麼時候、什麼地方、怎樣遊最好」，丙提到食宿也只是「或柳堤魚酒，或僧屋飯蔬」一筆帶過，沒有詳細行程。\n(B)對：甲文說文人記錄所見所聞，作品發行後「不斷塑造並加強西湖景物的內涵」。\n(C)錯：甲文說的是對讀者產生「行為與審美的指引」，不是模仿書寫風格。\n(D)對：乙文推崇月景（待月），丙文喜愛「野航兩棹」，都展現個人雅趣。\n(E)錯：乙文的差異是「時間」（杭人只在午未申遊湖，作者重朝夕與月夜）；只有丙文談到地點選擇。", "skill": "比較兩篇遊記時，分成「時間、地點、方式、同伴」幾個面向整理，選項的偷換就藏在面向錯置。"}, {"n": 31, "qtype": "多選", "stem": "乙、丙文發行後，杭州旅店若提供「跟著袁進士、王進士遊西湖」自助行程建議，符合乙、丙文的介紹文字是：", "options": {"A": "首選賞遊方案：畫舫周遊，盡覽湖光山色", "B": "彈性食宿規劃：依航線或個人喜好，安排餐飲住宿", "C": "專屬加碼行程：山僧相伴同遊，觀鷗鷺高飛，陶然忘機", "D": "誠心推薦：六橋待月、岳墳尋幽訪古", "E": "貼心提醒：喜好清靜者，切忌午後遊錢塘門"}, "answer": "BDE", "explain": "(A)錯：丙文作者「極不樂」豪家的「重樓架舫」，喜歡的是小野船。\n(B)對：丙文「或柳堤魚酒，或僧屋飯蔬，可信可宿」，隨意安排吃住。\n(C)錯：乙文說月景之樂「留與山僧遊客受用」，不是與山僧同遊；丙文是「侶同鷗鷺」，與鷗鷺為伴，不是觀賞牠們高飛。\n(D)對：乙文即〈晚遊六橋待月記〉，丙文說「勝在岳墳」。\n(E)對：杭人遊湖集中在「午、未、申三時」，而「錢塘門苦僧、苦客」，人擠人，喜歡清靜的人要避開。", "skill": "情境應用題，每個選項都要回原文找到「出處句」，找不到或意思被改就刪。"}], "difficulty": "中", "label": "114學測", "year": 114, "kind": "學測", "textcat": "部定古文", "textcat2": "生活情境文本", "linked_core": "晚遊六橋待月記"}, {"id": "xc114-32", "exam": "xc114", "nums": [32, 33, 34, 35, 36], "form": "題組", "img": "img/xc114-32.png", "source": "杜光庭〈虯髯客傳〉（搭配白話對話討論「概念框架」）", "author": "杜光庭", "genre": "筆記小品", "types": ["人物情感", "文意推論", "比較閱讀"], "passage": "張氏以髮長委地，立梳床前。靖方刷馬，忽有一人，中形，赤髯而虯，乘蹇驢而來，投革囊於爐前，取枕攲臥，看張氏梳頭。靖怒甚，未決，猶刷馬。張氏熟視其面，一手握髮，一手映身搖示靖，令勿怒。急急梳頭畢，斂衽前問其姓。臥客答曰：「姓張。」對曰：「妾亦姓張，合是妹。」遽拜之。……張氏遙呼曰：「李郎且來拜三兄！」靖驟拜之，遂環坐。曰：「煮者何肉？」曰：「羊肉，計已熟矣。」客曰：「飢甚！」靖出市胡餅。客抽腰間匕首，切肉共食。……客曰：「觀李郎之行，貧士也，何以致斯異人？」曰：「靖雖貧，亦有心者焉。他人見問，固不言，兄之問，則無隱耳。」具言其由。曰：「然則將何之？」曰：「將避地太原。」客曰：「然，吾故謂非君所能致也。」曰：「有酒乎？」靖曰：「主人西則酒肆也。」靖取酒一斗，酒既巡，客曰：「吾有少下酒物，李郎能同之乎？」靖曰：「不敢。」於是開革囊，取一人頭並心肝，卻頭囊中，以匕首切心肝共食之。曰：「此人天下負心者，銜之十年，今始獲，吾憾釋矣。」又曰：「觀李郎儀形器宇，真丈夫也。」\n第33題選項：(A)河內凶，則移其民於河東，移其粟於河內。河東凶，亦然（《孟子‧梁惠王上》）(B)竊慕管夫人之墨竹，紙上生風；敢藉陶彭澤之黃花，圖中寫影（張李德和〈畫菊自序〉）(C)彼節者有間，而刀刃者無厚，以無厚入有間，恢恢乎其於遊刃必有餘地矣（《莊子‧養生主》）(D)若亡鄭而有益於君，敢以煩執事。越國以鄙遠，君知其難也，焉用亡鄭以陪鄰（《左傳‧燭之武退秦師》）", "translation": "紅拂女（張氏）頭髮長到垂地，站在床前梳頭。李靖正在刷馬，忽然來了一個人，中等身材，滿臉捲曲的紅鬍子，騎著一頭跛驢，把皮囊丟在爐子前，拿了枕頭斜躺著，看張氏梳頭。李靖非常生氣，還沒決定怎麼做，仍在刷馬。張氏仔細看了那人的臉，一手握著頭髮，一手藏在身側向李靖搖手示意，叫他不要發怒。她趕緊梳完頭，整理衣襟上前問他姓什麼。躺著的客人回答：「姓張。」張氏說：「我也姓張，應該是妹妹。」立刻向他下拜。……張氏遠遠喊道：「李郎快來拜見三哥！」李靖趕緊拜見，於是三人圍坐。客人問：「煮的是什麼肉？」答：「羊肉，估計已經熟了。」客人說：「我餓極了！」李靖出去買胡餅，客人抽出腰間匕首，切肉一起吃。……客人說：「看李郎的樣子是個窮書生，怎麼能得到這樣的奇女子？」李靖說：「我雖然窮，也是有抱負的人。別人問我，我本來不說，兄長問，我就不隱瞞了。」便詳細說了經過。客人問：「那你們要去哪裡？」答：「要到太原避難。」客人說：「對，我本來就說她不是你能得到的。」又問：「有酒嗎？」李靖說：「旅店西邊就是酒館。」李靖買來一斗酒，酒過一巡，客人說：「我有一點下酒的東西，李郎敢一起吃嗎？」李靖說：「不敢當。」客人就打開皮囊，取出一顆人頭和心肝，把人頭放回囊中，用匕首切心肝一起吃。說：「這人是天下最負心的人，我恨了他十年，今天才抓到，我的遺憾消除了。」又說：「看李郎的儀表氣度，真是大丈夫啊。」", "keywords": [{"w": "虯", "m": "捲曲"}, {"w": "蹇驢", "m": "跛腳的驢"}, {"w": "攲臥", "m": "斜靠著躺"}, {"w": "熟視", "m": "仔細看"}, {"w": "斂衽", "m": "整理衣襟，表示恭敬"}, {"w": "遽", "m": "立刻"}, {"w": "致", "m": "得到、招來"}, {"w": "銜", "m": "懷恨"}], "questions": [{"n": 32, "qtype": "單選", "stem": "下列①、②「→」後，是就前人名言所提出的看法。關於這兩項看法是否符合上文觀點，最適當的研判是：①「你可以從外表的美評論一朵花或一隻蝴蝶，但不能以此評論一個人。」→人其實不適合以任何框架「評論」，有框架反而會壓抑才能的發揮。②「這世界不是缺少美，而是缺少發現美的眼睛。」→發現與否，其實無關眼睛構造，而是得先具備「看見」某個事物的概念框架，才能發現它的美。（占2分，單選題）", "options": {"A": "①、②皆符合", "B": "①、②皆不符合", "C": "①符合，②不符合", "D": "①不符合，②符合"}, "answer": "D", "explain": "①不符合：對話最後說「人們即使能擺脫一個框架，也無法擺脫所有框架」，孫悟空正是走進取經框架才成佛，框架不一定壓抑才能。\n②符合：文中說「凡是理解、思考，都需要概念框架」，要先有框架才看得見、理解得了，和②一致。答案(D)。", "skill": "判斷看法是否符合，先找文中的結論句，再看選項是順著說還是唱反調。"}, {"n": 33, "qtype": "單選", "stem": "下列文句，意在表達「有其他概念框架可以選擇」的是：（占2分，單選題）", "options": {"A": "河內凶，則移其民於河東，移其粟於河內。河東凶，亦然", "B": "竊慕管夫人之墨竹，紙上生風；敢藉陶彭澤之黃花，圖中寫影", "C": "彼節者有間，而刀刃者無厚，以無厚入有間，恢恢乎其於遊刃必有餘地矣", "D": "若亡鄭而有益於君，敢以煩執事。越國以鄙遠，君知其難也，焉用亡鄭以陪鄰"}, "answer": "D", "explain": "燭之武先順著秦穆公「滅鄭有利」的想法說，接著指出隔著晉國管理遠方土地很難，滅鄭只是增強鄰國——提醒秦穆公換一個角度（秦國自身利益）來看這件事，等於提供另一個思考框架，選(D)。\n(A)是梁惠王說自己救災的具體做法，不是換框架。\n(B)是表達仰慕前人、借前人畫風作畫。\n(C)是庖丁說明解牛技術的原理。", "skill": "「換框架」＝同一件事用不同角度重新評估，找有「如果……但其實……」轉折論證的選項。"}, {"n": 34, "qtype": "非選", "stem": "上文中，虯髯客、孫悟空的某些行為，曾讓李靖、唐僧動怒，請回答：(1)李靖基於什麼身分框架，對虯髯客「取枕攲臥，看張氏梳頭」動怒？虯髯客這項舉動為何讓李靖如此介意？（占4分，30字以內）(2)唐僧對孫悟空打死強盜如此介意，是因為此舉損害了他所認定的什麼身分框架與特質？（占2分，15字以內）", "options": {}, "answer": "", "ref_answer": "(1)他是紅拂的伴侶，不容許虯髯客有非分之想。\n(2)出家人的框架，慈悲為懷。", "ref_official": true, "explain": "(1)文中說紅拂來找李靖是「引導對方走進終身伴侶的框架」，所以李靖是以紅拂伴侶的身分看事情；陌生男子大剌剌躺著盯著自己的女伴梳頭，在他看來是輕薄、有非分之想，自然生氣。\n(2)文中唐僧罵孫悟空「沒有慈悲好善之心，去不得西天，做不得和尚」，可見他在意的是「出家人（和尚）」這個身分應有的慈悲。", "skill": "非選題先在文中找到題目關鍵詞出現的地方（身分框架、慈悲），答案通常就在附近，再用自己的話濃縮。"}, {"n": 35, "qtype": "非選", "stem": "上文中，紅拂、東海龍王均曾以身分框架來引導虯髯客、孫悟空，請回答：(1)紅拂對於虯髯客攲臥相視，採取什麼身分框架來界定彼此？她「遽拜之」的舉動，是什麼用意？（占4分，30字以內）(2)東海龍王的提醒，讓孫悟空在「仙」的身分框架下，有何取與捨的領悟？（占4分，30字以內）", "options": {}, "answer": "", "ref_answer": "(1)以兄妹界定她與虯髯客的關係，並立刻下拜，不容虯髯客拒絕。\n(2)捨去做妖仙，要修成正果。", "ref_official": true, "explain": "(1)紅拂說「妾亦姓張，合是妹」，用「兄妹」重新定義兩人關係；「遽」是立刻，她馬上下拜，把關係定下來，讓虯髯客沒有機會拒絕，也就化解了曖昧和李靖的怒氣。\n(2)龍王說若不保護唐僧，「到底是個妖仙，休想得成正果」。孫悟空因此明白：同樣是「仙」，要捨棄只當妖仙的身分，選擇保唐僧取經、修成正果。答題要寫出「捨」和「取」兩面。", "skill": "注意題目中的副詞（遽＝立刻）常是答題關鍵：它說明了行為的用意。"}, {"n": 36, "qtype": "非選", "stem": "上文中，虯髯客一度看不起李靖，後來才改變看法，請回答：(1)虯髯客問李靖「何以致斯異人」，透露了他推測李靖也許不是等閒之輩，他如此推測的前提是什麼？（占2分，15字以內）(2)虯髯客進一步觀察李靖的「儀形器宇」，認為他的哪些表現符合「真丈夫」框架？請舉出一項，參考示例（自言貧而有心→雖然尚未顯達，卻胸懷大志），填寫①李靖的表現（10字以內）、②符合真丈夫的什麼特質（20字以內）。（占4分）", "options": {}, "answer": "", "ref_answer": "(1)紅拂聰慧，故李靖應非等閒之輩。\n(2)①避地太原；②能投明主。或：①吃負心人的心肝；②有膽識。", "ref_official": true, "explain": "(1)「斯異人」指紅拂這位奇女子。虯髯客的邏輯是：這麼不凡的女子會跟著他，那他應該也有過人之處——前提就是「紅拂聰慧有眼光」。\n(2)從文中找李靖的具體表現：他說要「避地太原」，太原是李世民所在，代表他能選擇投靠明主；又如虯髯客請他吃仇人心肝，他敢一起吃，表現出膽識。選一項，左欄寫行為、右欄寫它代表的特質。", "skill": "「表現→特質」的表格題，左欄寫具體動作（引文中的事），右欄寫抽象品格，不要兩欄都寫成同一層次。"}], "difficulty": "難", "label": "114學測", "year": 114, "kind": "學測", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "燭之武退秦師、虬髯客傳、畫菊自序"}, {"id": "xc115-03", "exam": "xc115", "nums": [3], "form": "單題", "img": "img/xc115-03.png", "source": "鄭用錫賀林占梅詩", "author": "鄭用錫", "genre": "古典詩詞曲", "types": ["文化常識", "典故出處"], "passage": "四方男子志，今更挂桑弧。天上誕麟種，人間浴鳳雛。共誇田得玉，早叶夢投珠。清福知誰享，孤山一幅圖。", "translation": "男兒志在四方，如今府上又掛起桑木弓（生了男孩）。天上降下麒麟之子，人間沐浴著鳳凰的雛鳥。大家都誇您像藍田種出美玉，早就應驗了夢中投珠的吉兆。這份清福誰能享有？就像孤山林和靖那樣一幅閒逸的圖畫。", "keywords": [{"w": "挂桑弧", "m": "古代生男孩，在門左懸掛桑木弓"}, {"w": "麟種", "m": "麒麟之子，稱美人家的兒子"}, {"w": "田得玉", "m": "藍田種玉，喻生得佳兒"}, {"w": "夢投珠", "m": "夢中得珠，生子的吉兆"}, {"w": "孤山", "m": "林逋隱居孤山，梅妻鶴子，切合林占梅之「林」「梅」"}, {"w": "姻兄", "m": "對有姻親關係之平輩的尊稱"}], "questions": [{"n": 3, "qtype": "單選", "stem": "依據資料甲、乙，下列敘述最適當的是：（甲、鄭用錫、林占梅為清代新竹文學名家，鄭用錫次子鄭如梁娶林占梅之妹為妻。林占梅年幼喪父，由叔父林祥雲撫養成人。）", "options": {"A": "遞送賀詩的信封上，可題「鳳侶鸞儔」呼應詩意", "B": "詩中藉「得玉」、「投珠」，讚美林占梅玉樹臨風", "C": "若鄭用錫一併附上箋札，末尾署名前可自稱「家岳父」", "D": "若鄭用錫同時寫信向林祥雲致賀，可稱林祥雲「姻兄」"}, "answer": "D", "explain": "先畫關係圖：鄭用錫的兒子娶了林占梅的妹妹，所以鄭用錫是林占梅妹妹的公公，和撫養林占梅兄妹的叔父林祥雲是同一輩的親家。對同輩的姻親可以尊稱「姻兄」，所以(D)正確。\n(A)詩中「挂桑弧」「麟種」「鳳雛」都是賀生男孩，「鳳侶鸞儔」是賀新婚，不合。\n(B)「田得玉」「夢投珠」都是比喻生了好兒子，不是稱讚林占梅外貌。\n(C)鄭用錫不是林占梅的岳父，林占梅的妹妹嫁到鄭家，鄭用錫是林占梅的姻長輩，自稱「家岳父」錯誤。", "skill": "稱謂題先畫家族關係圖，確定輩分（同輩稱兄、長一輩稱伯）與親屬類別（血親／姻親）。"}], "difficulty": "中", "label": "115學測", "year": 115, "kind": "學測", "textcat": "延伸", "textcat2": "生活情境文本", "linked_core": "勸和論"}, {"id": "xc115-04", "exam": "xc115", "nums": [4], "form": "單題", "img": "img/xc115-04.png", "source": "《韓非子‧亡徵》；選項涉〈鴻門宴〉、〈燭之武退秦師〉、〈諫逐客書〉、《孟子‧梁惠王上》", "author": "韓非等", "genre": "說理議論", "types": ["文意推論", "典故出處"], "passage": "①大臣甚貴，偏黨眾強。②聽以爵，不以眾言參驗。③無禮而侮大鄰，貪愎而拙交。④境內之傑不事，而求封外之士。⑤財物寡，無守戰之備而輕攻伐。⑥大臣隆盛，外藉敵國，內困百姓，以攻怨讎。", "translation": "①大臣地位太尊貴，結黨的勢力眾多強大。②依爵位高低聽取意見，不用眾人的說法來參照檢驗。③沒有禮貌而侮辱強大的鄰國，貪婪固執又拙於外交。④不任用國內的傑出人才，反而去求國外的人士。⑤財物少，沒有守備作戰的準備卻輕易發動攻伐。⑥大臣權勢極盛，對外倚仗敵國，對內困苦百姓，用來攻擊自己的仇人。（有這些情況，國家可能走向敗亡。）", "keywords": [{"w": "偏黨", "m": "結黨營私的人"}, {"w": "參驗", "m": "參照檢驗"}, {"w": "愎", "m": "固執任性"}, {"w": "拙交", "m": "不善外交"}, {"w": "不事", "m": "不任用"}], "questions": [{"n": 4, "qtype": "單選", "stem": "依據右框（韓非：有這些情況，國家可能走向敗亡啊！），下列篇章的解讀，最適當的是：", "options": {"A": "〈鴻門宴〉中，范增指沛公「其志不在小」，意在避免楚軍陷入①②", "B": "〈燭之武退秦師〉中，晉文公謂「失其所與，不知」，意在避免晉國陷入③", "C": "〈諫逐客書〉中，李斯以「藉寇兵而齎盜糧」為喻，意在警示執政者勿陷入④⑥", "D": "《孟子》中，孟子舉出「塗有餓莩而不知發，人死，則曰：『非我也，歲也。』」的荒謬，意在警示執政者勿陷入⑤"}, "answer": "B", "explain": "(B)正確：晉文公不肯趁機攻打秦軍，理由之一是「失其所與，不知」——秦國是盟友又是大國，攻打它等於侮辱強鄰、斷送盟友，正是③「無禮而侮大鄰，貪愎而拙交」。\n(A)范增說沛公志向不小，是提醒項羽除掉對手，和大臣太貴、只聽爵位高者的話無關。\n(C)李斯說趕走客卿等於把兵器借給敵人、送糧給盜賊，是反對排斥外來人才；④是「不用國內人才只求外人」，方向相反，⑥講大臣勾結敵國也不合。\n(D)孟子批評的是見百姓餓死不開倉、還推給年歲，屬於不恤民，與⑤「財物少卻輕易攻伐」無關。", "skill": "把每個典故濃縮成一句「誰在擔心什麼」，再對照框中條目的關鍵詞（侮大鄰、求外士、輕攻伐）。"}], "difficulty": "難", "label": "115學測", "year": 115, "kind": "學測", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "燭之武退秦師、諫逐客書、鴻門宴"}, {"id": "xc115-05", "exam": "xc115", "nums": [5], "form": "單題", "img": "img/xc115-05.png", "source": "蘇軾〈書論〉", "author": "蘇軾", "genre": "說理議論", "types": ["虛詞句式", "文意推論"], "passage": "夫三代之君，惟不忍鄙其民而欺之，故天下有故，而其議及於百姓，以觀其意之所嚮；及其不可聽也，則又反覆而諭之，以窮極其說，而服其不然之心，是以其民親而愛之。", "translation": "夏商周三代的君主，正因為不忍心輕視百姓、欺騙他們，所以國家有大事時，議論就會讓百姓參與，來觀察他們的意向；等到百姓的意見不可採行時，又反覆向他們說明，把道理講透徹，讓他們原本不以為然的心服氣，因此百姓都親近愛戴君主。", "keywords": [{"w": "三代", "m": "夏、商、周"}, {"w": "鄙", "m": "輕視"}, {"w": "有故", "m": "有變故、大事"}, {"w": "嚮", "m": "同「向」，趨向"}, {"w": "諭", "m": "曉諭、說明"}, {"w": "窮極其說", "m": "把道理說盡說透"}], "questions": [{"n": 5, "qtype": "單選", "stem": "下列是一段古文，依據文意，甲、乙、丙、丁、戊排列順序最適當的是：夫三代之君，惟不忍鄙其民而欺之，（甲、及其不可聽也／乙、以觀其意之所嚮／丙、而服其不然之心／丁、故天下有故，而其議及於百姓／戊、則又反覆而諭之，以窮極其說）是以其民親而愛之。", "options": {"A": "乙丙丁戊甲", "B": "丙丁戊甲乙", "C": "丁乙甲戊丙", "D": "戊丙甲乙丁"}, "answer": "C", "explain": "開頭說君主「不忍欺民」，接「故」字的丁最順：因此有事就讓百姓參與討論；接乙「以觀其意之所嚮」說明目的。再來是轉折：甲「及其不可聽也」（等到百姓意見不可行時），接戊「則又反覆而諭之」，「及……則……」是固定搭配；最後丙「而服其不然之心」接在說理之後，表示讓百姓心服。順序丁乙甲戊丙，選(C)。", "skill": "排序題抓關聯詞：「故」接原因後、「及……則……」成對、「以」表目的接在動作後。"}], "difficulty": "易", "label": "115學測", "year": 115, "kind": "學測", "textcat": "延伸", "textcat2": "學術文本", "linked_core": "赤壁賦"}, {"id": "xc115-11", "exam": "xc115", "nums": [11, 12, 13], "form": "題組", "img": "img/xc115-11.png", "source": "余英時〈俠與中國文化〉（第13題選項引《孟子》、《荀子》、《論語》）", "author": "余英時", "genre": "經典語錄", "types": ["文意推論", "典故出處"], "passage": "第13題選項：\n(A)桀紂之失天下也，失其民也，失其民者，失其心也。（《孟子‧離婁上》）\n(B)殘賊之人，謂之一夫，聞誅一夫紂矣，未聞弒君也。（《孟子‧梁惠王下》）\n(C)天行有常，不為堯存，不為桀亡，應之以治則吉，應之以亂則凶。（《荀子‧天論》）\n(D)紂之不善，不如是之甚也，是以君子惡居下流，天下之惡皆歸焉。（《論語‧子張》）", "translation": "(A)桀和紂失去天下，是因為失去了人民；失去人民，是因為失去了民心。\n(B)殘害仁義的人，叫作「獨夫」。我只聽說誅殺了獨夫紂，沒聽說殺了君主。\n(C)大自然的運行有一定的規律，不因堯而存在，不因桀而消亡；用治理的方式順應它就吉祥，用混亂的方式對待它就凶險。\n(D)紂的壞，並不像傳說的那麼嚴重。所以君子厭惡處在下流的地位，一旦如此，天下的壞事都會歸到他身上。", "keywords": [{"w": "殘賊", "m": "殘害仁義的人"}, {"w": "一夫", "m": "獨夫，眾叛親離的暴君"}, {"w": "弒", "m": "臣殺君、下殺上"}, {"w": "天行有常", "m": "自然運行有規律"}, {"w": "下流", "m": "地勢低窪處，比喻惡名匯聚的地位"}], "questions": [{"n": 11, "qtype": "單選", "stem": "依據上文，關於中國古代的「俠」，敘述最適當的是：", "options": {"A": "由於社會重文輕武，導致俠與菁英士人處於對立狀態", "B": "俠有激昂慷慨的氣概，可追溯到古代儒家的議政傳統", "C": "東漢俠的勢力遠逾以往，乃促成名士的集體反抗行動", "D": "俠風狂放進取的一面，與儒者不屈服的批判精神相契"}, "answer": "D", "explain": "文末說「儒家傳統中本有一股『狂』的精神，能與『俠風』一拍即合」，後世有批判精神的儒者也帶「俠氣」，所以(D)正確。\n(A)文中說俠「進入儒生文士的道德意識中」，是融合不是對立。\n(B)方向反了：是俠的作風影響了儒士的批判行動，不是俠源自儒家。\n(C)東漢時俠已經不是武力集團，是「俠節」提供名士情感動力，不是俠的勢力變大。", "skill": "注意影響的方向：A影響B和B源自A是兩回事。"}, {"n": 12, "qtype": "單選", "stem": "關於①、②是否符合上文寫作策略，最適當的研判是：①以西方騎士為對照，闡述中國之「士」與武力的關係。②通過儒家思想與俠的比較，說明中國古代俠文化的興衰。", "options": {"A": "①、②皆符合", "B": "①、②皆不符合", "C": "①符合，②不符合", "D": "①不符合，②無法判斷"}, "answer": "B", "explain": "①不符合：文中拿西方騎士和中國的「俠」比較武力地位；拿騎士和「士」比較的是維持秩序與批判傳統，並沒有談士與武力的關係。\n②不符合：文章說明的是俠如何融入士的精神、影響儒者的批判傳統，並沒有拿儒家和俠做比較來講俠文化的興衰。答案(B)。", "skill": "寫作策略題，先畫出「誰跟誰比、比什麼」，選項常把比較對象或比較內容換掉。"}, {"n": 13, "qtype": "單選", "stem": "依據上文，如果想為畫線處（不肯屈服於權威、持「道」以議政）提供文獻佐證，最適合引用的是：", "options": {"A": "桀紂之失天下也，失其民也，失其民者，失其心也", "B": "殘賊之人，謂之一夫，聞誅一夫紂矣，未聞弒君也", "C": "天行有常，不為堯存，不為桀亡，應之以治則吉，應之以亂則凶", "D": "紂之不善，不如是之甚也，是以君子惡居下流，天下之惡皆歸焉"}, "answer": "B", "explain": "畫線處是「不肯屈服於權威、拿『道』來評論政治」。(B)孟子不承認暴君紂的君主身分，說殺他是「誅一夫」而非「弒君」——用仁義之道來評判君主，不屈服於君權，最能佐證。\n(A)講得民心才能得天下，是政治道理，沒有對抗權威的意味。\n(C)講自然規律與人為治亂，不是議政。\n(D)子貢提醒君子不要讓自己身處惡名之地，是修身的警惕。", "skill": "佐證題先把畫線處的關鍵詞（不屈權威、以道議政）列出，選項要「同時」符合才選。"}], "difficulty": "中", "label": "115學測", "year": 115, "kind": "學測", "textcat": "學術文本", "textcat2": "", "linked_core": ""}, {"id": "xc115-14", "exam": "xc115", "nums": [14, 15], "form": "題組", "img": "img/xc115-14.png", "source": "量詞分類表（例句引《戰國策》、〈虬髯客傳〉、《紅樓夢》等）", "author": "", "genre": "其他", "types": ["字詞解釋", "文化常識"], "passage": "①夫人與禽各為一「類」。②孟嘗君予車五十「乘」。③劉姥姥留神打量了黛玉一「番」。④見靖驚喜，召坐，環飲十數「巡」。⑤或當龍戰三二十「載」，建少功業。", "translation": "①人和禽獸各自是一類。②孟嘗君給（馮諼）五十輛車。③劉姥姥仔細把黛玉打量了一遍。④（虬髯客）看見李靖又驚又喜，請他坐下，大家圍坐喝了十幾輪酒。⑤或許應該在群雄爭戰中奮鬥二三十年，建立一點功業。", "keywords": [{"w": "乘", "m": "量詞，四匹馬拉的一輛車"}, {"w": "番", "m": "量詞，次、回"}, {"w": "巡", "m": "量詞，斟酒一遍為一巡"}, {"w": "載", "m": "年"}, {"w": "龍戰", "m": "群雄爭戰"}], "questions": [{"n": 14, "qtype": "單選", "stem": "依據上表，對右框5個量詞進行分類，最適當的是：", "options": {"A": "名量詞①②／動量詞③④⑤", "B": "名量詞①②⑤／動量詞③④", "C": "名量詞①③⑤／動量詞②④", "D": "名量詞②④⑤／動量詞①③"}, "answer": "B", "explain": "名量詞計算人、事、物的數量；動量詞計算動作的次數。①「一類」是計算人、禽的類別，名量詞；②「五十乘」是計算車的數量，名量詞；⑤「三二十載」是時間單位（年），像表中的「星期、小時」屬名量詞中的準量詞。③「打量了一番」是打量這個動作的次數，動量詞；④「環飲十數巡」是喝酒的輪數，動量詞。答案(B)。", "skill": "判斷量詞類別：看它計算的是「東西」還是「動作」，把量詞前後的名詞或動詞找出來。"}, {"n": 15, "qtype": "單選", "stem": "依據上表，關於「名量詞中的借用量詞」與「動量詞中的借用量詞」，敘述不適當的是：", "options": {"A": "前者與數詞「一」結合時，「一」即表示「滿」、「全」的意思", "B": "後者可作為某種行為的次數單位，也表示該行為所憑藉的事物", "C": "二者都可將名詞借用為量詞，且須與數詞結合，才會產生量詞意義", "D": "二者都可凸顯事物或動作的形象性，藉以營造出鮮明具體的畫面感"}, "answer": "A", "explain": "(A)不適當：「一腔熱血」「一身傲骨」的「一」有「滿、全」的意思，但「一床棉被」「一葉扁舟」的「一」只是單純的數量，不能說都表示滿、全。\n(B)適當：「看一眼」「踢兩腳」既是次數，也說明用眼、用腳。\n(C)適當：腔、床、眼、刀本來都是名詞，要和數詞結合才成為量詞。\n(D)適當：「一葉扁舟」「切五刀」都讓畫面更具體。", "skill": "看到「即」「都」「必」等絕對性字眼，拿表中每個例子逐一檢驗，有一個例外就不成立。"}], "difficulty": "中", "label": "115學測", "year": 115, "kind": "學測", "textcat": "學術文本", "textcat2": "部定古文", "linked_core": "虬髯客傳"}, {"id": "xc115-16", "exam": "xc115", "nums": [16, 17, 18], "form": "題組", "img": "img/xc115-16.png", "source": "白話說明文（引莊綽《雞肋編》、李時珍《本草綱目》、李漁《閒情偶寄》等）", "author": "", "genre": "其他", "types": ["文意推論", "比較閱讀"], "passage": "《雞肋編》：浙中少皂莢，澡面、浣衣皆用肥珠子。……子圓黑肥大，肉亦厚，膏潤於皂莢，故一名肥皂。\n《本草綱目》：（皂莢）莢之樹皂，故名。……（肥皂團）十月採莢，煮熟，搗爛和白麵及諸香作丸。澡身面，去垢而膩潤，勝於皂莢也。\n《閒情偶寄》：（香皂）以江南六合縣出者為第一，但價值稍昂，又恐遠不能致，多則浴體，少則止以浴面。", "translation": "《雞肋編》：浙江一帶皂莢少，洗臉、洗衣都用肥珠子。……它的種子圓、黑、肥大，果肉也厚，比皂莢更油潤，所以又叫「肥皂」。\n《本草綱目》：皂莢樹的莢是黑色的，所以叫「皂莢」。……（肥皂團）十月採收莢果，煮熟後搗爛，和白麵粉及各種香料做成丸子。用來洗澡洗臉，去汙又滋潤，比皂莢好。\n《閒情偶寄》：香皂以江南六合縣出產的最好，但價格稍貴，又怕路遠買不到；多的話就用來洗澡，少的話就只用來洗臉。", "keywords": [{"w": "澡面", "m": "洗臉"}, {"w": "浣衣", "m": "洗衣"}, {"w": "膏潤", "m": "油潤"}, {"w": "皂", "m": "黑色"}, {"w": "膩潤", "m": "滋潤細滑"}, {"w": "昂", "m": "價格高"}], "questions": [{"n": 16, "qtype": "單選", "stem": "依據上文，關於皂莢與肥皂莢，敘述最適當的是：", "options": {"A": "無論皂莢或肥皂莢，其洗淨力強弱均取決於莢果短長", "B": "皂莢與肥皂莢皆須將莢果煮熟後搗碎，方能用於洗滌", "C": "不同品種的皂莢，去垢力有別，但滋潤程度皆優於肥皂莢", "D": "皂莢名「皂」，與顏色有關；肥皂莢名「肥」，與莢果有關"}, "answer": "D", "explain": "「莢之樹皂，故名」：「皂」是黑色，所以皂莢得名和顏色有關；肥皂莢的莢果「肥厚多肉」，《雞肋編》也說「膏潤於皂莢，故一名肥皂」，「肥」和莢果肥厚有關。選(D)。\n(A)文中說皂莢「以多脂者為佳」，看的是油脂多寡，不是長短。\n(B)一般洗滌只要「搗碎加水揉搓」；煮熟是製作肥皂團的步驟。\n(C)正好相反，肥皂團「膩潤，勝於皂莢」。", "skill": "「故名」「故一名」是解釋命名由來的訊號，看到就圈起來。"}, {"n": 17, "qtype": "單選", "stem": "關於「香皂」在上文所引明清文學作品中的文化意涵，闡釋最適當的是：", "options": {"A": "具洗滌功能，藉以傳達對人心淨化的期許", "B": "因價格不菲，可區別身分階層與生活品味", "C": "融入地域元素，呈現製造地植物分布的特色", "D": "展現工藝水準，配合不同功能需求而客製化"}, "answer": "B", "explain": "李漁說好香皂「價值稍昂」，文章結論說「香皂在富貴家庭中已普遍使用，不過，尋常百姓家並不多見」，香皂成了富貴人家的生活象徵，選(B)。\n(A)文中沒有談淨化人心。\n(C)只提到六合縣產的最好，沒談植物分布。\n(D)沒提到工藝與客製化。", "skill": "「文化意涵」題，回頭找作者整理例子後下的那句結論。"}, {"n": 18, "qtype": "單選", "stem": "依據上文，關於現代手工皂與工業皂，敘述最適當的是：", "options": {"A": "二者製作原理與肥皂團並無不同，差別在於潔淨成分的來源", "B": "二者在「皂化反應」製程中，因分別合成皂素或香料而有差別", "C": "前者添加植物油，環境成本低；後者添加防腐劑，洗後抗菌力高", "D": "前者成分較天然，洗後肌膚不乾澀；後者保存期限長，銷售價格低"}, "answer": "D", "explain": "手工皂用植物油與草本低溫皂化，「保留了天然甘油，保溼力高」；工業皂「製程快、成本低」，又添加防腐劑，可推知保存較久、價格較低。選(D)。\n(A)肥皂團是靠果實中天然的皂素，現代肥皂是油脂與鹼的皂化反應，原理不同。\n(B)皂素是植物果實本身含有的，不是皂化反應合成的。\n(C)文中沒說防腐劑讓抗菌力高，只說它可能刺激皮膚。", "skill": "比較題要確認每一個比較點都在文中有根據，不能自己補上文中沒說的效果。"}], "difficulty": "中", "label": "115學測", "year": 115, "kind": "學測", "textcat": "科普文本", "textcat2": "生活情境文本", "linked_core": ""}, {"id": "xc115-19", "exam": "xc115", "nums": [19, 20, 21], "form": "題組", "img": "img/xc115-19.png", "source": "盧慧紋〈興風作浪的浪漫〉（引懷素〈自敘帖〉所錄唐人詩句）", "author": "盧慧紋", "genre": "其他", "types": ["詩詞賞析", "文意推論"], "passage": "奔蛇走虺勢入座，驟雨旋風聲滿堂。\n筆下唯看激電流，字成只畏盤龍走。\n醉來信手兩三行，醒後卻書書不得。\n心手相師勢轉奇，詭形怪狀翻合宜。\n忽然絕叫三五聲，滿壁縱橫千萬字。\n遠鶴無前侶，孤雲寄太虛。狂來輕世界，醉裡得真如。", "translation": "筆勢像奔跑的蛇、遊走的毒蛇撲向座位，聲勢像驟雨旋風充滿廳堂。\n筆下只看見閃電奔流，字寫成了，只怕它像盤曲的龍飛走。\n醉時隨手寫下兩三行，醒來後卻怎麼也寫不出來。\n心和手互相引導，筆勢越來越奇，怪異的字形反而恰到好處。\n忽然大叫三五聲，滿牆縱橫寫滿千萬字。\n像遠方的孤鶴沒有同伴，像孤雲寄身太空。狂放時輕視世間一切，醉中領悟了佛法真理。", "keywords": [{"w": "虺", "m": "毒蛇"}, {"w": "心手相師", "m": "心與手互相引導"}, {"w": "翻", "m": "反而"}, {"w": "太虛", "m": "天空"}, {"w": "真如", "m": "佛教語，事物的真實本性"}], "questions": [{"n": 19, "qtype": "單選", "stem": "依據上文，關於〈自敘帖〉中詩作對懷素其人其書的描述，說明最適當的是：", "options": {"A": "以奔蛇、走虺、遠鶴等物象，說明運筆時身形的伸展變化", "B": "以盤龍走、滿壁縱橫，形容其運筆速度時而迅疾時而徐緩", "C": "下筆時近乎顛狂且不忌飲酒，觀者卻能從中印證佛道之理", "D": "心手相師，乍看怪異不合常軌，卻能引發觀者多重的聯想"}, "answer": "D", "explain": "「心手相師勢轉奇，詭形怪狀翻合宜」：字形看起來怪異，反而恰到好處；文中也說懷素筆下「充滿驚奇的物象變化」，讓觀者聯想到蛇、龍、雷電等，選(D)。\n(A)奔蛇走虺形容的是筆勢，「遠鶴」是比喻懷素孤高的人格，都不是身形。\n(B)盤龍走、滿壁縱橫都表現快速奔放，沒有「徐緩」。\n(C)文中說宗教氛圍影響了觀者對神異的期待，沒說觀者從中印證佛道之理（「醉裡得真如」是寫懷素）。", "skill": "詩句描述的對象要分清：是字（筆勢）、是人（性格）還是場面（聲勢）。"}, {"n": 20, "qtype": "單選", "stem": "關於上文對〈自敘帖〉的敘述，最適當的是：", "options": {"A": "觀者可以透過墨色由濃到淡的變化，推想其換行蘸墨的規律", "B": "藉助神異力量書寫的怪奇字形，具奔放不拘且震懾人心之美", "C": "以摹本、臨本、仿本或刻本的形式流傳，故宮所藏為唯一存世真跡", "D": "後人可從中了解懷素的交遊、師承，以及書寫時的構思和創作理念"}, "answer": "A", "explain": "文中說故宮藏本「每行第一字墨色飽滿，漸寫漸乾，直到寫完行末最後一字」，可推知他每換一行才蘸一次墨，選(A)。\n(B)神異力量只是當時觀者的認知；作者強調它「字形結構謹守草法」，有法度。\n(C)文中只說唐代狂草名品多以摹本等流傳，沒說故宮藏本是唯一真跡。\n(D)〈自敘帖〉記出身、經歷與交遊，但沒有提到師承與構思理念。", "skill": "「最適當」題中，凡是「唯一」「全部」等強烈字眼，都要在文中找到同樣強度的說法才成立。"}, {"n": 21, "qtype": "單選", "stem": "依據上文，關於懷素〈自敘帖〉中所錄眾人詩作的價值，敘述最適當的是：", "options": {"A": "留存盛唐時藝文活動的珍貴剪影", "B": "記錄當時不被人知的狂草書法家", "C": "提供後人臨摹狂草的造型與布局", "D": "揭示法度為浪漫得以穩定的憑藉"}, "answer": "A", "explain": "文中說這些詩「為八世紀的書法表演現場留下難得的紀錄」，就是保存了盛唐書法表演這種藝文活動的畫面，選(A)。\n(B)懷素「二十餘歲即以草書聞名」，不是不被人知。\n(C)詩是文字描述，不能提供臨摹的造型布局。\n(D)「法度」是作者從帖的書法本身觀察出的，不是詩作揭示的。", "skill": "問「某材料的價值」，就找文中對該材料的直接評價句（留下難得的紀錄）。"}], "difficulty": "中", "label": "115學測", "year": 115, "kind": "學測", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "xc115-22", "exam": "xc115", "nums": [22, 23, 24], "form": "題組", "img": "img/xc115-22.png", "source": "杜甫〈觀打魚歌〉；仇兆鰲《杜詩詳注》；浦起龍《讀杜心解》", "author": "杜甫；仇兆鰲；浦起龍", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀", "文意推論"], "passage": "甲詩：綿州江水之東津，魴魚鱍鱍色勝銀。漁人漾舟沉大網，截江一擁數百鱗。眾魚常才盡卻棄，赤鯉騰出如有神。潛龍無聲老蛟怒，迴風颯颯吹沙塵。饔子左右揮霜刀，鱠飛金盤白雪高。徐州禿尾不足憶，漢陰槎頭遠遁逃。魴魚肥美知第一，既飽歡娛亦蕭瑟。君不見朝來割素鬐，咫尺波濤永相失。（杜甫〈觀打魚歌〉）\n乙注：（前八句）敘打魚事。魴魚味美，故漁人取之。眾魚、赤鯉、潛龍、老蛟，俱屬伴說。（後八句）復記魚鱠。鱠飛，言其薄；金盤，言其華；白雪高，言其潔且多；一句中含數義。禿尾、槎頭，亦屬伴說。盧注：此魚一經剖割，永與波濤相失，漁人能不見之而傷心乎？鍾云：數語可當一篇戒殺文。\n丙解：此詩從來誤會以魴為鱠，……今詳玩詩意，乃知作鱠者謂赤鯉，魴其陪襯也。前八句，敘打魚事，鱍鱍、數百，皆眾魚常才爾。赤鯉騰出，特筆以表之，乃是主句。後八句，志啖鱠事。鱠鯉堆盤，使人神旺，則凡禿尾、槎頭之類魴者，俱退舍矣。末再繳醒之，言魴魚固其美者，然當厭飫之餘，無復朵頤焉，況忍多戕物命乎？不見赤鯉就烹朝來之苦若是乎？", "translation": "甲詩：綿州江水的東邊渡口，魴魚活蹦亂跳，顏色比銀子還亮。漁人搖船撒下大網，攔江一兜就是幾百條魚。普通的雜魚都被丟棄，一條紅鯉魚神氣地騰躍而出。深潭裡的龍沉默無聲，老蛟發怒，旋風颯颯捲起沙塵。廚師左右揮動雪亮的刀，切下的魚片飛落金盤，白得像雪堆得高高的。徐州的禿尾魚不值得回味，漢水南邊的槎頭鯿也只好遠遠逃走。都知道魴魚最肥美，但吃飽歡樂之後也感到一陣蕭瑟。你沒看見早上剛被割下白鰭的魚嗎？近在咫尺的江水，從此永遠和牠分離了。\n乙注：前八句寫打魚。魴魚味道好，所以漁人捕牠；雜魚、紅鯉、潛龍、老蛟都是陪襯。後八句寫生魚片。「鱠飛」說切得薄，「金盤」說器皿華美，「白雪高」說魚肉潔白又多，一句包含好幾層意思。禿尾、槎頭也是陪襯。盧氏注：魚一經剖殺，就永遠和江水分離，漁人看見能不傷心嗎？鍾氏說：這幾句可以當作一篇戒殺生的文章。\n丙解：這首詩一向被誤解為用魴魚做生魚片，……現在仔細玩味詩意，才知道做生魚片的是紅鯉，魴魚只是陪襯。前八句寫打魚，「鱍鱍」「數百」都是普通雜魚；紅鯉騰躍而出，特別用筆突顯牠，才是主句。後八句寫吃生魚片。鯉魚片堆滿盤子，讓人精神一振，那麼禿尾、槎頭這類魴魚都只能退讓了。最後再點醒：魴魚固然美味，但吃飽厭膩之後，也不會再想大嚼，何況忍心多殺生命呢？沒看見紅鯉被烹殺時，早上那樣的痛苦嗎？", "keywords": [{"w": "鱍鱍", "m": "魚跳躍的樣子"}, {"w": "鱠", "m": "細切的魚肉，同「膾」"}, {"w": "饔子", "m": "廚師"}, {"w": "鬐", "m": "魚鰭"}, {"w": "伴說", "m": "陪襯的說法"}, {"w": "厭飫", "m": "吃飽、吃膩"}, {"w": "朵頤", "m": "大口咀嚼"}, {"w": "戕", "m": "殺害"}], "questions": [{"n": 22, "qtype": "單選", "stem": "下列關於甲詩的解讀，最適當的是：", "options": {"A": "「色勝銀」、「數百鱗」凸顯魴魚帶來可觀的收入", "B": "「徐州」、「漢陰」襯托出「綿州」廚師的刀工佳", "C": "「既飽歡娛亦蕭瑟」指出口腹之慾滿足後終難免悵然", "D": "「咫尺波濤永相失」感嘆竭澤而漁將造成長遠的損失"}, "answer": "C", "explain": "「既飽歡娛亦蕭瑟」：吃飽了很開心，卻也湧起一股蕭瑟，接著想到魚被割殺、永別江水，所以是口腹滿足後的悵然，選(C)。\n(A)寫魚的鮮亮與數量，是描寫捕魚場面，沒談收入。\n(B)徐州禿尾、漢陰槎頭是別地的名魚，用來襯托眼前魚鱠的美味，不是廚師刀工。\n(D)「咫尺波濤永相失」是同情被殺的魚再也回不到近在眼前的江水，不是講漁業資源的長遠損失。", "skill": "詩末的轉折句常是情感重心，抓住「既……亦……」的前後對比。"}, {"n": 23, "qtype": "單選", "stem": "依據丙解，許多人解讀甲詩時所產生的誤解，主要是：", "options": {"A": "誤以為名貴魴魚最適合做魚鱠", "B": "不知鯉魚才是金盤魚鱠主角", "C": "不了解赤鯉經烹煮之後會變苦", "D": "錯認禿尾、槎頭與魴魚同類"}, "answer": "B", "explain": "丙解第一句就說「此詩從來誤會以魴為鱠」，又說「作鱠者謂赤鯉，魴其陪襯也」——大家以為盤中的生魚片是魴魚，其實是紅鯉，選(B)。\n(A)誤會的是「盤中是哪種魚」，不是「哪種魚最適合做鱠」。\n(C)「就烹朝來之苦」是說鯉魚被殺的痛苦，不是味道變苦。\n(D)丙解自己說「禿尾、槎頭之類魴者」，並不認為這是誤解。", "skill": "評注題先找注家「破題」的那句（從來誤會……今……乃知……），就是他要糾正的重點。"}, {"n": 24, "qtype": "單選", "stem": "對於甲詩的詮釋，乙注、丙解說明相同的是：", "options": {"A": "「禿尾」、「槎頭」皆意在陪襯魴魚", "B": "「白雪高」、「堆盤」凸顯魚鱠味美", "C": "魴魚之滋味鮮美，可供製作佳餚美饌", "D": "不忍戕物，諷諫主政者不可魚肉百姓"}, "answer": "C", "explain": "乙注說「魴魚味美，故漁人取之」，丙解說「魴魚固其美者」，兩家都肯定魴魚美味，選(C)。\n(A)乙注認為禿尾、槎頭陪襯魴魚；丙解認為牠們是「類魴者」，被鯉魚鱠比下去，陪襯的是赤鯉。\n(B)乙注說「白雪高」是潔白又多，不是味美；丙解說「堆盤」使人神旺。\n(D)兩家都提到戒殺、不忍傷生，但都沒說是諷諫主政者。", "skill": "比較兩家注解，把同一詞句在兩家的解釋並排對照，只有兩邊意思一致的才算「相同」。"}], "difficulty": "難", "label": "115學測", "year": 115, "kind": "學測", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "xc115-25", "exam": "xc115", "nums": [25], "form": "單題", "img": "img/xc115-25.png", "source": "《禮記‧禮運》、《論語‧先進》、袁宏道〈晚遊六橋待月記〉、《史記‧項羽本紀》、《左傳‧燭之武退秦師》、蘇軾〈赤壁賦〉、陶淵明〈桃花源記〉、杜光庭〈虬髯客傳〉、李斯〈諫逐客書〉、張李德和〈畫菊自序〉", "author": "多家", "genre": "其他", "types": ["字詞解釋", "虛詞句式"], "passage": "(A)昔者，仲尼與於蜡賓／夫子喟然嘆曰，吾與點也\n(B)今歲春雪甚盛，梅花為寒所勒／不者，若屬皆且為所虜\n(C)以其無禮於晉，且貳於楚也／此非孟德之困於周郎者乎\n(D)問今是何世，乃不知有漢／乃知真人之興也，非英雄所冀\n(E)臣聞吏議逐客，竊以為過矣／竊慕管夫人之墨竹，紙上生風", "translation": "(A)從前孔子參加蜡祭，擔任助祭的賓客／孔子感嘆地說：我贊同曾點啊\n(B)今年春雪很大，梅花被寒氣抑制／不然的話，你們這些人都將被他俘虜\n(C)因為鄭國對晉國無禮，而且對楚國有二心／這不是曹操被周瑜圍困的地方嗎\n(D)問現在是什麼朝代，竟然不知道有漢朝／這才知道真命天子的興起，不是一般英雄所能企求的\n(E)我聽說官員們在議論驅逐客卿，我私下認為這是錯的／我私下仰慕管夫人的墨竹，在紙上彷彿生出風來", "keywords": [{"w": "與", "m": "參與／贊同"}, {"w": "為……所", "m": "被"}, {"w": "於", "m": "對、向／被"}, {"w": "乃", "m": "竟然／才"}, {"w": "竊", "m": "私下，謙詞"}], "questions": [{"n": 25, "qtype": "多選", "stem": "下列各組「」內的詞，意義前後相同的是：", "options": {"A": "昔者，仲尼「與」於蜡賓／夫子喟然嘆曰，吾「與」點也", "B": "今歲春雪甚盛，梅花「為」寒所勒／不者，若屬皆且「為」所虜", "C": "以其無禮於晉，且貳「於」楚也／此非孟德之困「於」周郎者乎", "D": "問今是何世，「乃」不知有漢／「乃」知真人之興也，非英雄所冀", "E": "臣聞吏議逐客，「竊」以為過矣／「竊」慕管夫人之墨竹，紙上生風"}, "answer": "BE", "explain": "(A)錯：前者「與」是「參與」；後者是「贊同」。\n(B)對：兩個都是「為……所……」的被動句，「為」是「被」。\n(C)錯：前者「貳於楚」的「於」是「對、向」（對楚國有二心）；後者「困於周郎」的「於」是「被」。\n(D)錯：前者「乃」是「竟然」；後者「乃知」是「才知道」。\n(E)對：兩個「竊」都是「私下」，表示自謙。", "skill": "「於」「為」等虛詞判斷被動，可試著換成「被」讀讀看；「乃」則試換「竟然／才／就是」。"}], "difficulty": "中", "label": "115學測", "year": 115, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "燭之武退秦師、大同與小康、諫逐客書、鴻門宴、桃花源記、虬髯客傳、赤壁賦、晚遊六橋待月記、畫菊自序"}, {"id": "xc115-27", "exam": "xc115", "nums": [27], "form": "單題", "img": "img/xc115-27.png", "source": "袁宏道〈開先寺至黃巖寺觀瀑記〉", "author": "袁宏道", "genre": "山水遊記", "types": ["寫作手法", "人物情感"], "passage": "次日晨起，復至峽，觀香爐紫烟，心動。僧曰：「至黃巖之文殊塔，瀑勢乃極。」杖而往，磴狹且多折，芒草割人面。少進，石愈嶔。白日蒸厓，如行熱冶中，微聞諸客皆有嗟嘆聲。既至半，力皆憊，遊者昏昏愁墮，一客眩思返。余曰：「戀軀惜命，何用遊山？且而與其死於床笫，孰若死於一片冷石也？」客大笑，勇百倍。頃之，躋其巔，入黃巖寺。少定，折而至前嶺，席文殊塔觀瀑。瀑注青壁下，雷奔海立，孤搴萬仞，峽風逆之，簾捲而上，忽焉橫曳，東披西帶。", "translation": "第二天一早起來，又到峽谷，看見香爐峰的紫色雲煙，心動了。僧人說：「到黃巖的文殊塔，瀑布的氣勢才最壯觀。」我們拄著手杖前往，石階窄又多轉折，芒草割傷人臉。再往前走，山石越來越險峻。太陽烤著山崖，像走在熔爐裡，隱約聽到同行的客人都在嘆氣。走到一半，大家都筋疲力盡，昏昏沉沉怕跌下去，有一位客人頭暈想回頭。我說：「捨不得身體、愛惜性命，何必來遊山？況且你與其死在床上，哪比得上死在一片清涼的石頭上呢？」客人大笑，勇氣增加了百倍。不久，登上山頂，進入黃巖寺。稍作休息，轉到前面的山嶺，坐在文殊塔前看瀑布。瀑布灌注到青色石壁下，像雷霆奔騰、海水直立，獨自高掛萬仞；峽谷的風迎面吹來，瀑布像簾子被捲起往上飛，忽然又橫向拖曳，向東披散、向西飄帶。", "keywords": [{"w": "磴", "m": "石階"}, {"w": "嶔", "m": "山石高峻"}, {"w": "冶", "m": "熔爐"}, {"w": "憊", "m": "疲倦"}, {"w": "而", "m": "你"}, {"w": "床笫", "m": "床鋪"}, {"w": "躋", "m": "登上"}, {"w": "搴", "m": "高舉、懸掛"}, {"w": "曳", "m": "拖拉"}], "questions": [{"n": 27, "qtype": "多選", "stem": "關於下文的寫作特色，分析適當的是：", "options": {"A": "藉「割」、「蒸」二字所引發的身體痛感，呈現攀爬時的艱辛", "B": "在敘事寫景中插入對話，藉提問反映忘身以遂其志的生命態度", "C": "對比客的退縮與作者的豪情，諷刺人以好遊為名而實不能涉險", "D": "運用動詞的連續切換，捕捉瀑布在峽風作用之下瞬息多變的姿態", "E": "以宗教空間的轉換為寫景主線，景隨步移，營造山林幽寂的禪意"}, "answer": "ABD", "explain": "(A)對：「芒草割人面」「白日蒸厓」，一個刺痛、一個悶熱，讓讀者感受到爬山的辛苦。\n(B)對：作者用「戀軀惜命，何用遊山？」「孰若死於一片冷石也？」的反問，表現為了看到美景可以不顧自身的態度。\n(C)錯：客人聽了「大笑，勇百倍」，作者是在鼓舞同伴，不是諷刺。\n(D)對：「捲而上」「橫曳」「東披西帶」，一連串動作寫出瀑布被峽風吹得千變萬化。\n(E)錯：雖然經過黃巖寺、文殊塔，但主線是一路攀爬去看瀑布，寫的是壯闊與艱險，不是幽寂禪意。", "skill": "分析寫作特色，從「用字（動詞、感官）」「結構（敘事、對話）」「情感（態度）」三層檢查。"}], "difficulty": "中", "label": "115學測", "year": 115, "kind": "學測", "textcat": "延伸", "textcat2": "文學文本", "linked_core": "晚遊六橋待月記"}, {"id": "xc115-29", "exam": "xc115", "nums": [29], "form": "單題", "img": "img/xc115-29.png", "source": "《韓詩外傳》", "author": "韓嬰", "genre": "經典語錄", "types": ["文意推論", "比較閱讀"], "passage": "甲、孔子學鼓琴於師襄子而不進。師襄子曰：「夫子可以進矣！」孔子曰：「丘已得其曲矣，未得其數也。」有間，曰：「夫子可以進矣！」曰：「丘已得其數矣，未得其意也。」有間，復曰：「夫子可以進矣！」曰：「丘已得其人矣，未得其類也。」有間，曰：「……必作此樂也，默然思，戚然而悵，以王天下，以朝諸侯者，其惟文王乎？」師襄子避席再拜曰：「善！師以為文王之操也。」\n乙、孔子鼓瑟，曾子、子貢側門而聽。曲終，曾子曰：「嗟乎！夫子瑟聲殆有貪狼之志，邪僻之行，何其不仁，趨利之甚。」子貢以為然，……以曾子之言告。子曰：「……丘鼓瑟，有鼠出游，狸見於屋，循梁微行，造焉而避，厭目曲脊，求而不得，丘以瑟淫其音，參以丘為貪狼邪僻，不亦宜乎！」", "translation": "甲：孔子向師襄子學彈琴，一直沒有往下學新曲。師襄子說：「您可以學新的了！」孔子說：「我已經會這首曲子了，但還沒掌握它的技法。」過了一段時間，師襄子說：「可以學新的了！」孔子說：「我已經掌握技法，但還沒領會它的意境。」又過一段時間，師襄子又說：「可以學新的了！」孔子說：「我已經體會到作曲者的為人，但還沒弄清他是哪一類人。」又過了一段時間，孔子說：「……作這首曲子的人，一定是沉默深思、憂傷惆悵，能夠稱王天下、使諸侯來朝的，大概只有周文王吧？」師襄子離開座位拜了兩次說：「好！我的老師說過這是〈文王操〉。」\n乙：孔子彈瑟，曾子、子貢在門邊聽。曲子彈完，曾子說：「唉！老師的瑟聲好像有貪婪凶狠的心志、邪僻的行為，多麼不仁，多麼急於求利啊。」子貢也認為是這樣，……就把曾子的話告訴孔子。孔子說：「……我彈瑟時，看到一隻老鼠出來遊走，有隻貓出現在屋裡，沿著屋梁悄悄前進，靠近老鼠卻又閃避，瞇著眼、弓著背，想抓卻抓不到，我就用瑟聲誇大表現這個情景，曾參認為我貪狠邪僻，不也是應該的嗎！」", "keywords": [{"w": "進", "m": "進一步學習新曲"}, {"w": "數", "m": "技法、規律"}, {"w": "有間", "m": "過了一段時間"}, {"w": "避席", "m": "離開座位，表示敬意"}, {"w": "操", "m": "琴曲"}, {"w": "殆", "m": "大概"}, {"w": "狸", "m": "野貓"}, {"w": "淫", "m": "過度表現、渲染"}, {"w": "參", "m": "曾參，即曾子"}], "questions": [{"n": 29, "qtype": "多選", "stem": "關於樂曲的彈奏與聆聽，符合下文敘述的是：", "options": {"A": "聆聽者常將個人意念投射於樂曲，如子貢善經商，遂覺曲中有趨利之心", "B": "聆聽者的體悟往往超出創作者原意，如孔子認為師襄子因詠文王而作曲", "C": "聆聽者對樂曲的細究，可使體悟由技巧轉入意境，如孔子持續探索師襄子的樂曲", "D": "彈奏者通常樂意聆聽者成為知音，如師襄子讚許孔子之見，孔子接受曾子的評論", "E": "彈奏者心思可能自樂曲流露，如師襄子聽出孔子上進之心，曾子聽出孔子貪狼之志"}, "answer": "CD", "explain": "(A)錯：聽出「趨利」的是曾子，子貢只是附和；文中也沒提到子貢經商的背景。\n(B)錯：孔子推斷是文王的曲子，師襄子證實「師以為文王之操也」，正好符合原意，沒有超出。另外曲子也不是師襄子作的。\n(C)對：孔子從「得其曲」→「得其數」→「得其意」→「得其人」→「得其類」，由技巧一路深入到意境與作者。\n(D)對：師襄子「避席再拜曰：善！」讚許孔子；孔子也承認曾子聽得對（不亦宜乎）。\n(E)錯：師襄子說「可以進矣」是催孔子學新曲，不是從樂曲聽出孔子的心思。", "skill": "多選題每個選項有「原則＋例子」兩半，兩半都要對才選，例子錯放人物最常見。"}], "difficulty": "中", "label": "115學測", "year": 115, "kind": "學測", "textcat": "學術文本", "textcat2": "文學文本", "linked_core": ""}, {"id": "xc115-30", "exam": "xc115", "nums": [30, 31], "form": "題組", "img": "img/xc115-30.png", "source": "諸葛亮〈出師表〉、曹操〈陳損益表〉（甲為柯慶明白話評論）", "author": "諸葛亮、曹操", "genre": "書信序跋", "types": ["比較閱讀", "寫作手法", "文化常識"], "passage": "乙：今南方已定，兵甲已足，當獎率三軍，北定中原。庶竭駑鈍，攘除姦凶，興復漢室，還於舊都，此臣所以報先帝而忠陛下之職分也。至於斟酌損益，進盡忠言，則攸之、禕、允之任也。願陛下託臣以討賊興復之效，不效，則治臣之罪，以告先帝之靈。若無興德之言，則責攸之、禕、允等之慢，以彰其咎。陛下亦宜自課，以諮諏善道，察納雅言，深追先帝遺詔，臣不勝受恩感激。今當遠離，臨表涕泣，不知所云。（諸葛亮〈出師表〉）\n丙：陛下即祚，復蒙試用，遂受上將之任，統領二州，內參機事，實所不堪。……臣以區區之質，而當鐘鼎之任；以闇鈍之才，而奉明明之政。顧恩念責，亦臣竭節授命之秋也。謹條遵奉舊訓權時之宜十四事，奏如左，庶以蒸螢增明太陽，言不足採。（曹操〈陳損益表〉）", "translation": "乙：現在南方已經平定，兵器裝備已經充足，應當激勵率領三軍，北伐平定中原。希望竭盡我平庸的才能，剷除奸邪凶惡的敵人，復興漢室，回到舊都，這是我報答先帝、效忠陛下的職責。至於衡量得失、進獻忠言，就是郭攸之、費禕、董允的責任了。希望陛下把討伐國賊、復興漢室的任務交給我，若沒有成效，就治我的罪，來告慰先帝在天之靈。如果沒有發揚德政的進言，就責罰攸之、費禕、董允等人的怠慢，來彰顯他們的過失。陛下也應當自己謀劃，詢問治國的好方法，明察採納正直的言論，深切追念先帝的遺詔，我就感激不盡了。如今即將遠離，面對這篇表文淚流滿面，不知道說了些什麼。\n丙：陛下即位後，又承蒙任用，於是接受上將的職位，統領兩州，在朝內參與機要政事，實在不能勝任。……我以微小的資質，擔當國家重任；以愚鈍的才能，侍奉聖明的政治。想到皇恩、念及職責，這正是我盡忠效命的時候。謹分條列出遵奉舊有訓令、因時制宜的十四件事，奏報如下，希望像用蒸騰的螢火替太陽增添光明一樣，言論不值得採用。", "keywords": [{"w": "駑鈍", "m": "才能平庸，謙詞"}, {"w": "攘除", "m": "排除"}, {"w": "斟酌損益", "m": "衡量興革得失"}, {"w": "自課", "m": "自我督促、謀劃"}, {"w": "諮諏", "m": "詢問"}, {"w": "即祚", "m": "即位"}, {"w": "不堪", "m": "不能勝任，謙詞"}, {"w": "鐘鼎之任", "m": "國家重任"}, {"w": "蒸螢增明太陽", "m": "以螢火為太陽增光，謙稱己言微不足道"}], "questions": [{"n": 30, "qtype": "多選", "stem": "「表」是古代官員進言的媒介，自信與謙敬的聲音常並存表中。關於乙、丙文的敘述，適當的是：", "options": {"A": "乙文推薦後起新秀擔當內政，並表示若識人不明願受責罰", "B": "丙文勇於指出囿於舊訓之十四事應及時揚棄，以重振朝綱", "C": "二文均感恩國君禮遇舊臣，在國家需要用人之時賦予重任", "D": "二文均謙稱自己能力有限，但願意在當前時局中承擔使命", "E": "二文均期許自己為朝廷效力，並盼國君充分授權以為後盾"}, "answer": "CD", "explain": "(A)錯：諸葛亮說若攸之等人沒有進忠言，是「責攸之、禕、允等之慢」，受罰的是他們，不是諸葛亮自己；他願受罰的是「討賊興復」不成功。\n(B)錯：曹操是「謹條遵奉舊訓」，主張遵守舊訓，不是揚棄。\n(C)對：乙文「臣不勝受恩感激」，丙文「陛下即祚，復蒙試用，遂受上將之任」，都感念君恩、受託重任。\n(D)對：乙文「庶竭駑鈍」，丙文「區區之質」「闇鈍之才」，都自謙，但都表示願意承擔。\n(E)錯：乙文雖說「願陛下託臣」，丙文並沒有要求授權。", "skill": "比較兩篇表文，分別圈出「謙詞」「感恩句」「請求句」，再逐項對照選項。"}, {"n": 31, "qtype": "多選", "stem": "甲文運用文體知識，深入解讀乙文表層文字下的聲音，若循此方式觀察丙文，關於乙、丙文違異「表」的典型特質，敘述適當的是：", "options": {"A": "乙文屢言「先帝」，使「下言於上」的「上」並非唯一，以重申其輔政重任", "B": "乙文以「臨表涕泣」取代表的常用套語，使老臣的稟告增添了父執輩的溫度", "C": "丙文以「不堪」表達對數項要職難以抉擇的猶豫，也暗示朝廷全仰賴其支撐", "D": "丙文以「蒸螢」對比「太陽」，暗諷國君之智遠不如己，流露恃才傲物的性格", "E": "二文的進言口吻，雖減省部分常見的應酬詞語，但仍符合身為臣下應有的態度"}, "answer": "ABE", "explain": "(A)對：甲文說〈出師表〉十三次提「先帝」，使「陛下」成了虛位——諸葛亮對話的對象不只後主，還有先帝，藉此強調自己受先帝託付的輔政責任。\n(B)對：甲文說它不用「誠惶誠恐，稽首頓首」結尾，而以「臨表涕泣」真情流露；諸葛亮是先帝託孤的老臣，語氣像長輩。\n(C)錯：「實所不堪」是謙稱自己不能勝任，不是在幾個職位間猶豫。\n(D)錯：「蒸螢增明太陽」是把自己比作螢火、把君主比作太陽，是自謙，不是暗諷。\n(E)對：兩篇都沒有完整的套語，但仍有「臣不勝受恩感激」「言不足採」等謙敬之詞，合乎臣下身分。", "skill": "謙詞（不堪、駑鈍、蒸螢）是古代公文的慣例，看到時先理解為自謙，不要過度解讀成真實猶豫或諷刺。"}], "difficulty": "難", "label": "115學測", "year": 115, "kind": "學測", "textcat": "部定古文", "textcat2": "學術文本", "linked_core": "出師表"}, {"id": "xc115-32", "exam": "xc115", "nums": [32], "form": "單題", "img": "img/xc115-32.png", "source": "歸有光〈項脊軒志〉、〈先妣事略〉、〈祭外姑文〉", "author": "歸有光", "genre": "書信序跋", "types": ["人物情感", "文意推論"], "passage": "（歸有光語）三代王教修明，內外順治，「閨門之事皆可歌詠而傳道之」。所述雖「婦人女子之常，而事之至微者」，但「幽閑貞靜之德，隱然寓於其間，而足以章明王者之化」。……此後女子在史傳作者眼中，必有「非平常之行」，乃能「著美名」於後世，導致女性「罕可紀述」。\n〈項脊軒志〉：一日，大母過余曰：「吾兒，久不見若影，何竟日默默在此，大類女郎也？」比去，以手闔門，自語曰：「吾家讀書久不效，兒之成，則可待乎？」頃之，持一象笏至，曰：「此吾祖太常公宣德間執此以朝，他日汝當用之。」\n〈先妣事略〉：有光七歲，與從兄有嘉入學。每陰風細雨，從兄輒留，有光意戀戀，不得留也。孺人中夜覺寢，促有光暗誦《孝經》，即熟讀，無一字齟齬，乃喜。\n〈祭外姑文〉：昔吾亡妻，能孝於吾父母，友於吾女兄弟，知夫人之能教也；粗食之養，未嘗不甘，知夫人之儉也。", "translation": "（歸有光的看法）夏商周三代王道教化昌明，家內家外和順有序，「家中婦女的事都可以歌詠流傳」。記述的雖然是「婦女平常、極細微的事」，但「嫻雅貞靜的品德隱含其中，足以彰顯君王的教化」。……後來的史書作者認為女子一定要有「不平凡的行為」，才能「留下美名」，結果女性「很少能被記載」。\n〈項脊軒志〉：有一天，祖母經過我的書房說：「我的孫兒，好久沒看到你的身影，怎麼整天默默待在這裡，很像個女孩子呢？」離開時，用手關上門，自言自語：「我們家讀書很久沒有功名了，這孩子的成功，或許可以期待吧？」不久，拿了一個象牙笏板來，說：「這是我祖父太常公在宣德年間拿著上朝的，將來你應當用得上。」\n〈先妣事略〉：我七歲時和堂兄有嘉一起上學。每逢陰風細雨，堂兄常常留在家裡不去上學，我心裡也很想留下，卻不被允許。母親半夜醒來，督促我背誦《孝經》，背得爛熟、沒有一個字卡住，她才高興。\n〈祭外姑文〉：從前我去世的妻子，能孝順我的父母，友愛我的姊妹，由此知道岳母教導有方；吃粗茶淡飯，從不覺得不好，由此知道岳母的節儉。", "keywords": [{"w": "大母", "m": "祖母"}, {"w": "象笏", "m": "象牙做的笏板，官員上朝所執"}, {"w": "孺人", "m": "明清時對七品官之母或妻的封號，此指母親"}, {"w": "齟齬", "m": "不順暢、卡住"}, {"w": "外姑", "m": "岳母"}, {"w": "章明", "m": "彰顯"}], "questions": [{"n": 32, "qtype": "非選", "stem": "歸有光的抒情散文中，有意識地留存了家族女性的聲音，而成為其特色，請回答：(1)依據甲文所引三段文字，文中的「大母」、「孺人」、「夫人」對自己角色所擔負責任的認知，共通點是什麼？（占2分，10字以內）(2)當代學者指出歸有光書寫女性，取材固然與後世史傳不同，但也有其所本。請依據上述的「我認為……」，說明：①他的取材有別於後世史傳的內容是什麼？②他的特定標準是什麼？（占4分，①、②各15字以內）", "options": {}, "answer": "", "ref_answer": "(1)教育栽培子孫。\n(2)①取材女子日常生活的平凡小事。②幽閑貞靜之德，能章明王者教化。", "ref_official": true, "explain": "(1)三段的共同點：祖母勉勵孫子讀書、拿出象笏期待他做官；母親半夜督促背《孝經》；岳母把女兒教得孝順節儉。她們都把「教育、栽培下一代」當成自己的責任。\n(2)①後世史傳只記女子「非平常之行」，歸有光則記「婦人女子之常，而事之至微者」，也就是日常生活中的小事。②他選材的標準是這些小事中要「隱然寓」有「幽閑貞靜之德」，而且「足以章明王者之化」。答題時要把引號中的關鍵語改寫成簡短的話，注意字數限制。", "skill": "「共通點」題：先把每段濃縮成一個動作（勉讀、督誦、教女），再找上位概念（教育子孫）。"}], "difficulty": "中", "label": "115學測", "year": 115, "kind": "學測", "textcat": "部定古文", "textcat2": "", "linked_core": "項脊軒志"}];
window.METHOD="<nav class=\"toc\">\n  <a href=\"#m-map\">先看地圖</a><a href=\"#m-steps\">八個動作</a><a href=\"#m-text\">六種文本</a><a href=\"#m-qtype\">三種題型</a><a href=\"#m-core\">課本 15 篇</a><a href=\"#m-use\">怎麼練</a>\n</nav>\n\n<h2 id=\"m-map\" style=\"margin-top:0\">一、先看地圖：高中文言文考什麼？</h2>\n<p>學測、指考的國文，<b>文言文大約占一半</b>。把十幾年的考題攤開來看，有三個明顯的變化：</p>\n<table>\n<tr><th>變化</th><th>以前（101–106 年）</th><th>現在（111–115 年）</th></tr>\n<tr><td>一段文言配幾題</td><td>大多一題就結束</td><td>常常一段文章配 2–5 題（題組），還會加上要自己寫的混合題</td></tr>\n<tr><td>題目問什麼</td><td>這個字什麼意思、這句在說什麼</td><td>大多在問「從文章推出什麼」，要你比較、判斷、找證據</td></tr>\n<tr><td>出什麼文章</td><td>詩詞、散文、故事最多</td><td>學者評論、古代科學、法規判決、表格圖表變多了；課文常被拿來和課外文章對讀</td></tr>\n</table>\n<p>所以，<b>只會翻譯不夠</b>。你要能分辨「這是哪一種文章」，再用適合它的讀法。這一頁把考題分成六種文本，每種都有它的讀法、常見的坑和示範題。</p>\n\n<h2 id=\"m-steps\">二、每篇都要做的八個動作</h2>\n<div class=\"step\"><div class=\"num\">1</div><div><b>先看題：知道要找什麼</b><br>先讀「X–Y 為題組」那行和每一題的題目。有幾篇文章？問的是字義、推論、比較，還是要你寫？多選題旁邊先寫「逐項判斷」。<br><span class=\"meta\">口訣：題目是地圖，文章是地形。</span></div></div>\n<div class=\"step\"><div class=\"num\">2</div><div><b>先抓主題，再處理難字</b><br>第一遍不要卡在看不懂的字。先弄清楚「誰、在哪裡、做了什麼」，有了大方向，難字比較猜得出來。<br><span class=\"meta\">口訣：先看森林，再看樹。</span></div></div>\n<div class=\"step\"><div class=\"num\">3</div><div><b>判斷這是哪一種文本</b><br>是課文、學者評論、古代科學、生活應用，還是文學作品？不同文本，第一步要做的事不一樣（見下一節）。<br><span class=\"meta\">口訣：先認文本，再選讀法。</span></div></div>\n<div class=\"step\"><div class=\"num\">4</div><div><b>每句話都問：這是誰說的？</b><br>一段文字裡常同時有原文、古人的解釋、一般人的看法、作者自己的意見。在旁邊標上【原文】【注解】【作者】，最不容易被選項騙。看到「<span class=\"yue\">曰</span>」「云」「謂」，就標出說話的人。<br><span class=\"meta\">口訣：先問誰說的，再問說什麼。</span></div></div>\n<div class=\"step\"><div class=\"num\">5</div><div><b>補主角、看虛字</b><br>文言常把主角省略。每句補上「誰」做的；「之、其、而、以、乃、焉」標出它指誰、連接什麼。<br><span class=\"meta\">口訣：每句問誰，虛字看方向。</span></div></div>\n<div class=\"step\"><div class=\"num\">6</div><div><b>猜字義，至少用兩個線索</b><br>上下文、部首、它在句子裡的位置、你知道的成語、課文裡學過的用法，至少兩個線索都指向同一個意思，才算猜對。<br><span class=\"meta\">口訣：兩個線索對得上，才算數。</span></div></div>\n<div class=\"step\"><div class=\"num\">7</div><div><b>讀到卡住就回頭</b><br>後面讀起來不通，常常是前面讀錯了。問自己：「我前面是不是把主角或意思弄錯了？」<br><span class=\"meta\">口訣：不通就回頭，別硬讀下去。</span></div></div>\n<div class=\"step\"><div class=\"num\">8</div><div><b>答案要有證據句</b><br>選擇題的每一個選項、非選題的每一個要點，都要能在原文指出依據。說不出依據的，就是猜的。<br><span class=\"meta\">口訣：指得出原文，才是答案。</span></div></div>\n\n<h2 id=\"m-text\">三、六種文本，六種讀法</h2>\n<table>\n<tr><th>文本</th><th>怎麼認出來</th><th>第一個動作</th><th>口訣</th></tr>\n<tr><td>部定古文</td><td>題目引課文、課文作者或課文人物</td><td>想起這篇的背景、問題、觀點、寫法</td><td>課文是尺，題目給的是新東西</td></tr>\n<tr><td>延伸</td><td>課文作者的其他作品、同一本書的另一篇</td><td>先想課文，再找「跟課文哪裡不一樣」</td><td>同中求異</td></tr>\n<tr><td>學術文本</td><td>詩話、注解、「謂」「言」、學者名字、甲乙丙並列</td><td>標出每句話是誰說的</td><td>先問誰說的，再問說什麼</td></tr>\n<tr><td>科普文本</td><td>物名、工法、本草、天象、「故名」</td><td>分三層：看到的、古人的解釋、現在知道的</td><td>看到的、猜的、現在知道的分開</td></tr>\n<tr><td>生活情境文本</td><td>稱謂、題辭、對聯、判決、法規、表格、任務</td><td>畫關係圖或對照表</td><td>先畫圖，再作答</td></tr>\n<tr><td>文學文本</td><td>詩詞曲、人物對話、情節、作者評論</td><td>詩詞分景與情；故事做人物言行表</td><td>找轉折，問為什麼</td></tr>\n</table>\n\n<div class=\"cat\" id=\"tc-部定古文\"><h3>📜 部定古文：課文被拿來「用」，不是拿來背</h3>\n<p><b>怎麼考：</b>很少只考課文本身，而是把課文當成比較的尺：拿課文和課外文章對讀、用新的觀念重新看課文、或一題列出五、六篇課文的句子比字義和語法。</p>\n<p><b>讀法：</b></p>\n<ol>\n<li><b>認出處：</b>在選項旁寫上篇名，回想那句話的上下文和說話的人。</li>\n<li><b>想起這篇的四件事：</b>寫作背景、要解決的問題、作者的觀點、主要寫法。</li>\n<li><b>看題目給了什麼新東西：</b>新的觀念？學者的新解讀？同作者的其他作品？</li>\n<li><b>以題目為準：</b>題目問「依上文」「本文認為」時，答案來自題目給的文章，不是課本。</li>\n<li><b>字義、虛字題：</b>把字放回句子換成白話試試看（例如「以」逐一換成「來／把／因為／而」），再標出詞性。</li>\n</ol>\n<p><b>常見的坑：</b>把〈赤壁賦〉主客說的話弄反、把虯髯客做的事寫成李靖；用課本的老印象，蓋過題目給的新解讀；「最早」「唯一」這種限定詞被偷偷拿掉；把「表」裡的客套謙詞當成真心話。</p>\n<div class=\"demo\"><b>示範題：</b><a href=\"#\" data-open-item=\"xc107-12\">107學測〈師說〉</a>：「吾師道也」的「師」是動詞（以道為師），選項把它當名詞就錯了。　<a href=\"#\" data-open-item=\"xc112-05\">112學測 燭之武與樊噲的說辭</a>　<a href=\"#\" data-open-item=\"xc113-26\">113學測 虛字「以」</a></div>\n<button class=\"btn ghost practice-btn\" data-practice-tc=\"部定古文\">練部定古文的題目 →</button></div>\n\n<div class=\"cat\" id=\"tc-延伸\"><h3>🔗 延伸：認識的作者，沒讀過的文章</h3>\n<p><b>怎麼考：</b>出課文作者的其他作品（蘇軾最常出現）、同一本書的另一篇（《戰國策》《史記》《聊齋》）、同一件事的不同記載，或後代模仿、改寫課文的作品。</p>\n<p><b>讀法：</b></p>\n<ol>\n<li>先用課文想起作者的風格與想法，當作「預測」。</li>\n<li>再找<b>這篇跟課文哪裡不一樣</b>：換了文體？換了時期？想法轉變了？</li>\n<li>同一件事不同記載時，列一張表：「事件一樣，哪些細節不一樣、各自想強調什麼」。</li>\n<li>模仿、改寫的作品，分開判斷「學了哪些形式」和「意思改成什麼」。</li>\n</ol>\n<p><b>常見的坑：</b>以為同一個作者，想法一定和課文一樣。</p>\n<div class=\"demo\"><b>示範題：</b><a href=\"#\" data-open-item=\"xc109-37\">109學測〈入獄賦〉仿〈赤壁賦〉</a>　<a href=\"#\" data-open-item=\"zk110-24\">110指考 說難與燭之武</a>　<a href=\"#\" data-open-item=\"xc115-27\">115學測 袁宏道</a></div>\n<button class=\"btn ghost practice-btn\" data-practice-tc=\"延伸\">練延伸的題目 →</button></div>\n\n<div class=\"cat\" id=\"tc-學術文本\"><h3>🔍 學術文本：先分清楚「誰說的」</h3>\n<p><b>怎麼考：</b>古人寫的詩話、文學評論、史論，古書的注解，說明文字用法的文章，還有現代學者怎麼解讀古典作品。這是題庫裡數量最多、難題也最多的一類。</p>\n<p><b>讀法：</b></p>\n<ol>\n<li><b>貼標籤：</b>每段旁邊標【原文】【注解甲】【注解乙】【作者】【一般人的看法】。</li>\n<li><b>找判斷句：</b>圈出「乃知」「非……也」「斯為謬矣」這類作者下結論的句子。</li>\n<li><b>找定義句：</b>「A，謂 B」「A 即 B」，把定義寫在旁邊，後面的推論都靠它。</li>\n<li><b>畫「主張←理由←例子」：</b>一行一個，看作者用什麼支持自己的說法。</li>\n<li><b>比較兩家說法時做表：</b>針對同一句話，甲怎麼說、乙怎麼說，意思一樣才算相同。</li>\n</ol>\n<p><b>常見的坑：</b>把注解的說法當成原作者的本意；把作者要反駁的說法當成作者的主張；「X 相當於 Y」被偷換成「X 和 Y 相通」；問「哪一項文中沒有預設你知道」，卻反著選。</p>\n<div class=\"demo\"><b>示範題：</b><a href=\"#\" data-open-item=\"zk106-14\">106指考 談「其」字的語法文</a>：作者說測度的「其」相當於「殆」、勸勉的「其」相當於「可」，那是兩種意思，選項說三者「相通」就錯了。　<a href=\"#\" data-open-item=\"xc110-18\">110學測《孟子》與王夫之</a>　<a href=\"#\" data-open-item=\"xc110-12\">110學測 王若虛詩話</a></div>\n<button class=\"btn ghost practice-btn\" data-practice-tc=\"學術文本\">練學術文本的題目 →</button></div>\n\n<div class=\"cat\" id=\"tc-科普文本\"><h3>🔭 科普文本：看到的、猜的、現在知道的分開</h3>\n<p><b>怎麼考：</b>古代的本草醫書、工藝技術、天文記錄、動植物觀察，常和現代科普文章放在一起。重點不是考你的科學知識，<b>答案一定在材料裡</b>。</p>\n<p><b>讀法：</b></p>\n<ol>\n<li><b>列出對象和術語：</b>在講什麼東西？術語在哪裡被解釋？看到「故名」「一名」就是在說名稱由來。</li>\n<li><b>分三層：</b>每句旁標【看到的】【古人解釋原因】【現代的說法】。古人的觀察可能是對的，解釋卻常常是錯的。</li>\n<li><b>做法、步驟畫成流程：</b>用時間詞（候、乃、至……熟）排出順序。</li>\n<li><b>判斷證據力：</b>哪一則是親眼觀察？哪一則是轉述或猜測？要佐證時選親眼觀察的。</li>\n<li><b>只用材料判斷：</b>材料沒寫的效果不能選；資料沒提到就是「無法判斷」。</li>\n</ol>\n<p><b>常見的坑：</b>把已經被推翻的舊說當成正確知識；用自己學過的化學、生物知識作答；選項多加了材料沒寫的好處。</p>\n<div class=\"demo\"><b>示範題：</b><a href=\"#\" data-open-item=\"zk107-23\">107指考 螟蛉與蜾蠃</a>：《詩經》是原始記錄，揚雄的「念咒變成己子」是錯誤解釋，陶弘景用親眼觀察去補充、說明《詩經》。　<a href=\"#\" data-open-item=\"xc113-29\">113學測 硃砂</a>　<a href=\"#\" data-open-item=\"xc114-22\">114學測 錢乙醫案</a></div>\n<button class=\"btn ghost practice-btn\" data-practice-tc=\"科普文本\">練科普文本的題目 →</button></div>\n\n<div class=\"cat\" id=\"tc-生活情境文本\"><h3>✉️ 生活情境文本：先畫圖，再作答</h3>\n<p><b>怎麼考：</b>書信、賀詞題辭、對聯、古代判決書、現代法規、表格圖表，或是一個生活任務（玩卡牌遊戲、審查古蹟、規劃飲食）。</p>\n<p><b>讀法：</b></p>\n<ol>\n<li><b>確認任務：</b>題目要我扮演誰、做什麼決定？</li>\n<li><b>畫關係圖：</b>人物用方框，血親畫實線、姻親畫虛線，標出輩分。</li>\n<li><b>判決、契約抓四件事：</b>誰告誰、要什麼、怎麼判、為什麼。</li>\n<li><b>表格用「查」的：</b>先看題目問哪一欄哪一列，再去表裡找；需要計算就動筆算。</li>\n<li><b>兩份資料對照：</b>現代的標準（法規條文）列左邊，古代資料列右邊，一條一條配對。</li>\n</ol>\n<p><b>常見的坑：</b>輩分弄錯；賀生子的詞當成賀結婚；表格裡沒有的數字也拿來判斷；「都」「必」只要有一個例外就不成立。</p>\n<div class=\"demo\"><b>示範題：</b><a href=\"#\" data-open-item=\"xc107-17\">107學測 歷史人物卡牌遊戲</a>　<a href=\"#\" data-open-item=\"zk110-03\">110指考 文言請假信</a>　<a href=\"#\" data-open-item=\"xc111-20\">111學測 鄭崇和墓與古蹟審查</a></div>\n<button class=\"btn ghost practice-btn\" data-practice-tc=\"生活情境文本\">練生活情境的題目 →</button></div>\n\n<div class=\"cat\" id=\"tc-文學文本\"><h3>🌙 文學文本：找轉折，問為什麼</h3>\n<p><b>怎麼考：</b>詩詞曲的意象和情感、散文的人物形象、小說和史傳的人物動機與敘事手法，也常和現代作品對讀。</p>\n<p><b>讀法：</b></p>\n<ol>\n<li><b>先認文類：</b>詩、詞、曲、散文、小說、史傳，決定要找意象、情節還是說話的策略。</li>\n<li><b>詩詞景情分行：</b>每句標「景」或「情」；「只恐」「卻」「怎」是情緒轉彎的地方。</li>\n<li><b>故事做人物言行表：</b>誰、說了什麼、做了什麼、對誰、結果如何。</li>\n<li><b>找作者跳出來說話的句子：</b>故事開頭或結尾的評論，常常就是主旨。</li>\n<li><b>從表面問到動機：</b>寫完「他做了什麼」，再問「他為什麼這樣做」「對方因此不得不怎樣」。</li>\n</ol>\n<p><b>常見的坑：</b>只寫表面發生的事，沒寫出為什麼；人物張冠李戴；把比喻當成真的。</p>\n<div class=\"demo\"><b>示範題：</b><a href=\"#\" data-open-item=\"zk101-11\">101指考</a>　<a href=\"#\" data-open-item=\"xc111-7\">111學測 不龜手之藥</a>　<a href=\"#\" data-open-item=\"zk103-15\">103指考 羅隱〈鸚鵡〉</a></div>\n<button class=\"btn ghost practice-btn\" data-practice-tc=\"文學文本\">練文學文本的題目 →</button></div>\n\n<h2 id=\"m-qtype\">四、三種題型的作答方法</h2>\n<div class=\"cat\"><h3>多選題：每個選項都是一題是非題</h3>\n<p><b>先搞懂計分：</b>選錯一個錯的選項，和<b>漏選一個對的選項</b>，扣分一樣多（五個選項的題目，錯一個得 3/5，錯兩個得 1/5，錯三個以上 0 分）。所以「不確定就不選」並不會比較安全。</p>\n<ol>\n<li>不管答案有幾個，五個選項一個一個判斷。</li>\n<li>把選項拆開看：主角是誰、做了什麼、對誰、程度多大、因果關係、時間先後。</li>\n<li>每一塊都回原文找證據；看到「皆」「均」，兩邊都要查。</li>\n<li><b>覺得它對的可能超過一半，就選；沒超過，就不選。</b></li>\n</ol></div>\n<div class=\"cat\"><h3>文白對讀、好幾篇一起比：先分開，再並排</h3>\n<ol>\n<li>每篇先用一句話寫重點，主角寫清楚。</li>\n<li>想想它們是什麼關係：原文與解釋？古代記載與現代知識？同一題目不同作者？一套觀念與套用的例子？古代資料與現代標準？</li>\n<li>畫比較表：橫的是比較的項目，直的是各篇文章，每一格都要有原文依據。</li>\n<li>兩篇看起來矛盾時，找文中有沒有調和的說法。</li>\n<li>選項常寫成「甲文說……，乙文說……」，<b>兩半都對才選</b>。</li>\n</ol></div>\n<div class=\"cat\"><h3>混合題、非選題：先數要寫幾件事</h3>\n<ol>\n<li><b>看配分：</b>2 分的題目通常是「抄出原文的句子」，抄對就好；4 分的題目通常要寫<b>兩件事</b>，只寫一件只拿一半。</li>\n<li><b>圈題目裡的名詞：</b>題目問「考量與行動」「取與捨」「表現與特質」，就把答案分成兩格，兩格都要填。</li>\n<li><b>抄錄題抄最短、但意思完整的句子；</b>歸納題要用自己的話，不能只抄原文的關鍵字。</li>\n<li><b>寫完檢查三件事：</b>主角對嗎？意思有沒有寫反？人名、關鍵字有沒有錯字？</li>\n</ol></div>\n\n<h2 id=\"m-core\">五、課本 15 篇：考試最常拿來用的課文</h2>\n<p>這 15 篇是 108 課綱推薦的高中文言文。就算考題出的是課外文章，也很常拿這幾篇來比較。點篇名，就能練所有跟這一篇有關的題目（包含舊課綱年份的考題）。</p>\n<div class=\"corelist\"><a href=\"#\" class=\"corebtn\" data-open-set=\"xc112-05,xc114-32,xc115-04,zk101-n1,xc104-11,xc106-17,xc109-39,xc110-37,xc113-27,xc115-25,zk101-20,zk102-5,zk106-19,zk108-36,zk110-24,xc102-4,zk103-19\">〈燭之武退秦師〉<span>17 組</span></a><a href=\"#\" class=\"corebtn\" data-open-set=\"xc105-17,xc113-18,zk110-28,xc109-35,xc111-26,xc114-25,xc115-25,zk103-20,zk108-38,xc103-21,xc108-41,xc106-5\">〈大同與小康〉<span>12 組</span></a><a href=\"#\" class=\"corebtn\" data-open-set=\"xc105-17,xc110-20,xc115-04,zk106-nc1,xc107-36,xc108-37,xc111-26,xc114-25,xc114-29,xc115-25,zk102-19,zk107-3,zk108-41\">〈諫逐客書〉<span>13 組</span></a><a href=\"#\" class=\"corebtn\" data-open-set=\"xc112-05,xc115-04,xc108-35,xc109-35,xc110-37,xc111-26,xc112-26,xc112-27,xc113-27,xc115-25,zk101-19,zk101-20,zk102-21,zk103-18,zk105-19,zk106-19,zk107-36,zk108-36,zk110-38,xc105-15,xc108-3,zk107-28,zk104-20,zk107-40\">〈鴻門宴〉<span>24 組</span></a><a href=\"#\" class=\"corebtn\" data-open-set=\"xc103-ns2,xc113-18,xc115-30,xc101-20,xc104-11,xc105-5,xc106-16,xc109-35,xc110-36,xc112-27,xc113-26,xc114-25,xc114-29,zk101-9,zk101-19,zk102-7,zk104-2,zk105-19,zk107-36,zk108-36,zk110-36,xc102-18,xc107-35,zk103-1\">〈出師表〉<span>24 組</span></a><a href=\"#\" class=\"corebtn\" data-open-set=\"xc101-ns2,zk105-10,xc104-17,xc105-5,xc109-35,xc112-27,xc113-27,xc115-25,zk101-7,zk107-37,zk108-35,zk106-16,zk106-14,zk110-40\">〈桃花源記〉<span>14 組</span></a><a href=\"#\" class=\"corebtn\" data-open-set=\"xc107-12,xc101-20,xc103-22,xc104-18,xc105-4,xc105-22,xc106-17,xc110-36,xc110-37,xc111-26,xc112-26,xc113-26,zk102-21,zk104-2,zk105-19,zk107-3,zk107-36,zk109-35,zk110-37,xc108-41,zk101-16\">〈師說〉<span>21 組</span></a><a href=\"#\" class=\"corebtn\" data-open-set=\"xc106-ns2,xc109-29,xc110-20,xc113-18,xc114-32,xc112-27,xc114-25,xc115-25,zk101-20,zk104-19,zk105-19,zk107-36,zk107-37,zk108-36,zk109-35,zk110-36,xc103-23,xc104-23,xc115-14\">〈虬髯客傳〉<span>19 組</span></a><a href=\"#\" class=\"corebtn\" data-open-set=\"xc106-8,xc113-18,xc114-15,xc103-22,xc104-17,xc105-22,xc108-35,xc110-35,xc110-37,xc113-26,xc115-25,zk105-19,zk110-37,xc101-11,xc102-6,xc108-7,xc109-13,xc109-37,xc112-35,xc115-05,zk108-27,zk109-33,zk103-21,zk107-40,zk108-41\">〈赤壁賦〉<span>25 組</span></a><a href=\"#\" class=\"corebtn\" data-open-set=\"xc114-30,xc105-4,xc112-26,xc115-25,zk109-35,xc115-27,zk107-40,zk110-08\">〈晚遊六橋待月記〉<span>8 組</span></a><a href=\"#\" class=\"corebtn\" data-open-set=\"xc108-13,xc109-29,xc115-32,xc101-20,xc104-17,xc105-22,xc111-26,xc112-26,xc113-26,xc113-27,xc114-25,xc114-29,zk104-19,zk105-19,zk107-36,zk108-38,zk109-35,zk110-37\">〈項脊軒志〉<span>18 組</span></a><a href=\"#\" class=\"corebtn\" data-open-set=\"xc111-33,xc113-18,zk105-10,xc104-18,xc105-5,xc106-16,xc107-36,xc108-35,xc111-26,xc112-26,xc113-27,xc114-25,xc114-29,zk102-5,zk106-19,zk107-37,zk108-36,zk110-38,xc103-12,xc109-12\">〈勞山道士〉<span>20 組</span></a><a href=\"#\" class=\"corebtn\" data-open-set=\"xc108-37,zk107-3,xc115-03,zk110-21\">〈勸和論〉<span>4 組</span></a><a href=\"#\" class=\"corebtn\" data-open-set=\"xc112-15,zk106-10,zk110-05\">〈鹿港乘桴記〉<span>3 組</span></a><a href=\"#\" class=\"corebtn\" data-open-set=\"xc111-14,xc114-32,xc115-25\">〈畫菊自序〉<span>3 組</span></a></div>\n<p class=\"meta\">〈鹿港乘桴記〉〈畫菊自序〉〈勸和論〉直接出題的比較少，但它們的作者（洪繻、鄭用錫）其他作品考過好幾次。</p>\n\n<h2 id=\"m-use\">六、怎麼用這個練習場</h2>\n<ul>\n<li><b>剛開始：</b>首頁點「暖身」，先做學測的單題。</li>\n<li><b>找弱點：</b>首頁「依文本類別練習」挑一類，連續做 10 題，看哪一類最常錯。</li>\n<li><b>練多選：</b>每個選項都說出對或錯的理由，再按對答案。</li>\n<li><b>練寫作答：</b>點「寫寫看」，先自己寫非選題，再對照參考答案，數數看寫到幾個重點。</li>\n<li><b>複習課文：</b>在上面的「課本 15 篇」點篇名，一次練完跟那篇課文有關的題目。</li>\n<li><b>做錯了：</b>看「解題小撇步」，再到「錯題本」重做一次。</li>\n</ul>\n";
